-- ============================================================
-- Alman4a (1/2): Günə-özəl push bildirişlərinin DE tərcüməsi
-- pregnancy_day_notifications + mommy_day_notifications — Azure/gpt-5.6-sol
-- ƏVVƏL sxem faylı (sütunlar) işlədilməlidir.
-- ============================================================

UPDATE public.pregnancy_day_notifications AS x SET title_de = v.t, body_de = v.b
FROM (VALUES
  ('1466cb19-fd27-4f75-a79c-d709e1623239'::uuid, 'So groß wie ein Mohnsamen 🌱', 'Dein Baby macht es sich bereits in deiner Gebärmutter gemütlich. Obwohl es noch winzig ist, beginnt sich sein Herz zu bilden.'),
  ('ad5cb90c-5ee0-41f0-8e3f-90512dcf6636', 'Das DNA-Paket ist fertig! 🧬', 'Augenfarbe, Haare und Geschlecht deines Babys sind bereits festgelegt. Was meinst du, wem wird es ähnlich sehen?'),
  ('77a7a0c4-cbc4-4060-9824-f3657b9506c0', 'Beerenpower 🍓', 'Himbeeren oder Erdbeeren? Diese antioxidantienreichen Früchte stärken dein Immunsystem.'),
  ('c13826a2-03b2-4512-bcfb-084ebb8c2f13', 'Eine stille Revolution findet statt 🤫', 'Die befruchtete Eizelle nistet sich in deiner Gebärmutter ein. Auch wenn du nichts davon spürst, ist ein faszinierender Prozess im Gange.'),
  ('fb1313b6-50fc-44e5-80b6-0c243b450b62', 'Kalzium für die Knochen 🥛', 'Milch, Joghurt oder Käse? Gönn dir heute unbedingt ein Milchprodukt – für das zukünftige Skelett deines Babys.'),
  ('33a29a12-915d-4926-a3e0-77d719ad233b', 'Du fühlst dich schlapp? Das hat einen Grund 🥱', 'Der Progesteronspiegel steigt. Wenn dein Bett nach dir ruft, sag nicht Nein und ruh dich aus!'),
  ('e07ed45f-67ec-4ce6-a8d6-4499daea0b9d', 'Eine neue Reise beginnt! 🚀', 'Dein Körper bereitet sich darauf vor, ein großes Wunder zu beherbergen. Bist du bereit dafür?'),
  ('3ff0a063-2126-4cd6-a3ce-f5e944bb5487', 'Vitamine vergessen? 💊', 'Folsäure ist jetzt deine beste Freundin. Schau im Bereich Ernährung vorbei, um eine gesunde Grundlage für dein zukünftiges Baby zu schaffen!'),
  ('a2855683-73b8-4bf4-af85-cc599724b360', 'Wie fühlst du dich heute? 🌈', 'Zu Beginn dieses neuen Lebensabschnitts können deine Gefühle schwanken. Halte im Stimmungstagebuch fest, wie du dich heute fühlst, und beobachte dein Wohlbefinden.'),
  ('f1a0230f-d87a-49ad-b1c8-d849ef306a7f', 'Noch ist es mikroskopisch klein 🔬', 'Große Geschichten beginnen mit winzigen Teilchen. Im Moment ist dein zukünftiges Baby noch wie eine Idee, doch sein Potenzial ist grenzenlos!'),
  ('137ef65d-9ea9-410c-9d5d-bbb4811b21f8', 'Zeit für einen Neustart! 🚫', 'Zigaretten, Alkohol oder zu viel Koffein? Jetzt ist genau der richtige Zeitpunkt, dich davon zu verabschieden. Gesunde Mutter = gesunder Start.'),
  ('f4bccccc-158d-4658-9abe-6ea45b62e469', 'Hast du deine Wasserflasche dabei? 💧', 'Eine ausreichende Flüssigkeitszufuhr ist für deinen Körper jetzt doppelt wichtig. Vergiss nicht, täglich genug Wasser zu trinken.'),
  ('bd4effb9-20aa-4b2c-9886-28f1a8aa42f4', 'Zeit für Walnüsse und Mandeln 🥜', 'Greif als Snack lieber zu Nüssen statt zu Chips. Omega-3-Fettsäuren sind wichtig für dich und dein zukünftiges Baby.'),
  ('186bdc98-bb17-499f-bf7e-d9ff9eaa5492', 'Nimm dir Zeit für dich 💆‍♀️', 'Sag den Stresshormonen den Kampf an! Schau dir heute einen deiner Lieblingsfilme an oder gönn dir eine warme Dusche.'),
  ('caca7263-c7a5-4d9a-92e5-c7d0658633f3', 'Der winzigste Anfang 🫧', 'Noch ist es mit bloßem Auge nicht zu erkennen. Dein zukünftiges Baby ist erst eine einzige Zelle – aber es hat Großes vor!'),
  ('c71b2b52-957c-4d0d-918e-02a81d0c792c', 'Ist der magische Moment gekommen? ✨', 'Die Befruchtung findet meist in diesen Tagen statt. Auch wenn du nichts davon spürst, hat ein wundersamer Prozess begonnen.'),
  ('00106d30-5d19-414e-a507-c025fa6d17d2', 'Eine echte Proteinbombe 🍳', 'Gibt es heute Eier zum Frühstück? Protein ist wichtig für die Zellerneuerung. Guten Appetit!'),
  ('ff01c295-45c4-493a-ab43-5a6c543c478d', 'Gehen wir eine Runde spazieren? 👟', 'Frische Luft hebt deine Stimmung. Schau dir im Bereich „Übungen“ das sanfte Gehprogramm an.'),
  ('4268dd91-2b9a-483a-aa93-8f2b7d7809a9', 'Vitamin vergessen? 😬', 'Folsäure ist die Grundlage für meine zukünftige Wirbelsäule! Schau in die Medikamentenerinnerung: Hast du deine heutige Dosis eingenommen? ✅'),
  ('45bd19ab-fec8-4848-87b2-8afc6fee3b1d', 'Sind Schmierblutungen normal? 🩸', 'Keine Sorge, es könnte sich um eine Einnistungsblutung handeln. Wenn du unsicher bist, schau im Bereich „Ärzte“ nach.'),
  ('549f62ec-94b7-42af-8ae8-87ad5504509a', 'Bist du eine Eisen-Lady? 🥩', 'Dein Blutvolumen wird zunehmen. Iss rotes Fleisch oder Linsen und sag der Anämie den Kampf an.'),
  ('3829c3d1-13c3-4dcc-9b0a-b1c150f1dbf6', 'Warten voller Spannung ... 🧘‍♀️', 'Deine Periode rückt näher. Hör dir im Bereich „Weißes Rauschen“ beruhigende Klänge an, um Stress abzubauen.'),
  ('648746b5-1de4-41ff-8fb8-976e17ef9c18', 'Hast du in den Kalender geschaut? 🗓️', 'Wenn deine Periode ausbleibt, ist es vielleicht Zeit für einen Test? Teile die schöne Nachricht mit uns!'),
  ('df6c4f91-28b1-4f7a-8ab6-64fb294a5ab9', 'So groß wie ein Sesamkorn! 🌱', 'Jetzt heißt es offiziell Embryo. Es wächst schnell, und auch du veränderst dich.'),
  ('29fd118b-28ca-4783-a20d-0dfe1f9257be', 'Plane die Zukunft 💭', 'Möchtest du nicht das erste „Startfoto“ in dein Schwangerschaftsalbum hochladen?'),
  ('aa7e5901-964e-4a5b-a2e3-24bbf3210a04', 'Wir legen den Grundstein 🏗️', 'Dein Körper bereitet sich auf ein neues Wunder vor, deine Periode ist fast vorbei. Für eine gesunde Entwicklung deines zukünftigen Babys ist ein ausreichender Vorrat an Folsäure (B9) unverzichtbar. Hast du dir schon den abwechslungsreichen Speiseplan im Bereich Ernährung angesehen? 🥑'),
  ('9e6d0515-f2ff-48ac-93ec-f1d970c7ffc2', 'Schlaf ist etwas Wunderbares 😴', 'Du solltest neue Energie tanken. Versuche, mindestens 8 Stunden täglich zu schlafen, bevor die schlaflosen Nächte beginnen.'),
  ('e9c7a1d0-36f4-4892-aa41-43d1c6c5e948', 'Aktiviere die grüne Kraft! 🥦', 'Spinat und Brokkoli sind nicht einfach nur Gemüse, sondern natürliche Vitaminquellen. Bring heute unbedingt etwas Grünes auf deinen Speiseplan.'),
  ('95c500c4-d966-4eca-85e3-f43263957e13', 'Hast du deine Ärztin oder deinen Arzt schon ausgewählt? 👩‍⚕️', 'Informiere dich schon jetzt über eine Fachperson, der du vertrauen kannst. Im Bereich Ärzte und Kliniken kannst du dir Bewertungen ansehen und deine Wahl treffen.'),
  ('572d6539-f881-4ec9-a3f9-b12c236e3b0d', 'Sendet dein Körper Signale? 🌡️', 'Dein Eisprung rückt näher. Achte auf deine Körpertemperatur – jetzt beginnen die Tage, an denen deine Chancen am höchsten sind!'),
  ('6f8a4fbb-f3ef-409d-a1cc-75f70eff873b', 'Ist dir übel? 🤢', 'Sind die Morgen besonders schwierig? Ingwertee oder Zitronenwasser können helfen. Lass deinen Magen nicht leer.'),
  ('d2eb5bbc-3775-4f57-aa9a-087ca149ab57', 'Hier wird fleißig gebaut! 🚧', 'Gehirn und Wirbelsäule bilden sich. Nimm weiterhin Folsäure ein!'),
  ('90d7f6db-e46c-4431-84a4-08c7cb36dff8', 'Morgenübelkeit? 🤢', 'Iss noch vor dem Aufstehen ein paar Salzcracker. Nimm kleine Mahlzeiten zu dir, um deinen Blutzuckerspiegel stabil zu halten.'),
  ('ee028003-7c13-49d6-a074-6279f0809a0e', 'Poch, poch ... Hörst du es? 💓', 'Mein Herz hat angefangen zu schlagen! Kannst du es kaum erwarten, diesen kleinen Motor zu hören? Trag den Termin für deinen ersten Ultraschall in den Kalender ein! 🖊️'),
  ('b0910e0e-cc92-44f5-8046-b09a58173a6b', 'Zeit für die offizielle Bestätigung! ✅', 'Falls du noch nicht dort warst, vereinbare einen Arzttermin. Im Bereich „Ärzte“ findest du die passende Praxis.'),
  ('55b6e494-7a56-4309-af7f-8fd6e4c2696c', 'Die ersten Herzschläge 💓', 'Auch wenn du es noch nicht hören kannst, schlägt das kleine Herz bereits. Mehr als 100-mal pro Minute!'),
  ('f2d72cc5-1dfe-472f-b0dd-cab7471cb46d', 'Ist dir übel? Entschuldige! 🥺', 'Die Hormone feiern eine Party, und ich bin schuld daran. Mache ich dir zu schaffen? Wie wäre es mit ein paar Salzcrackern? 🍪'),
  ('d24fadf2-1d24-4001-b4cd-1006ba1390b4', 'Das Gesicht nimmt Form an 👀', 'Augen, Nase und Ohren entwickeln sich. Noch sehen sie wie schwarze Punkte aus, aber die Gesichtszüge zeichnen sich bereits ab.'),
  ('98979663-767c-4d48-9b7b-786f81533442', 'Wo steckt Vitamin B6 drin? 🍌', 'Bananen, Avocado oder Hähnchenfleisch ... Dieses Vitamin kann Übelkeit lindern.'),
  ('b82ae448-8da6-41fb-9588-70bee70788e8', 'Geheime Tanzparty! 💃', 'Auch wenn du es noch nicht spürst, bewegt sich dein Baby bereits. Die ersten Bewegungen ähneln nur einem leichten Zucken.'),
  ('32c29664-93a4-4e94-bb42-a62ada8dcf6a', 'Saure Gurken oder Schokolade? 🥒', 'Ungewöhnliche Gelüste sind ganz normal. Achte aber auf den Zucker! Es gibt gesunde Alternativen.'),
  ('6389a83c-6f25-4ebf-a0ca-cf0883f3ce2a', 'Ist deine Hose zu eng? 👖', 'Hast du dein Ausgangsgewicht im Gewichtstracker eingetragen? 📈'),
  ('1af4d57c-0075-4fda-8ae2-57d6f0df3dd7', 'Ingwertee hilft! 🍵', 'Die Übelkeit lässt nicht nach? Ingwer beruhigt den Magen. Im Bereich Ernährung findest du Rezepte.'),
  ('ee6d0fe8-1439-46ca-a99d-71bece3db7ff', 'Müdigkeit auf dem Höhepunkt? 😴', 'Dein Körper arbeitet wie ein Energiekraftwerk. Ein kurzes Mittagsschläfchen ist dein gutes Recht als werdende Mama!'),
  ('6a854983-edba-4550-9294-f82d79978af6', 'Eine süße kleine Erbse 🟢', 'Etwa 6 mm groß. Arme und Beine beginnen als kleine Knospen zu wachsen. Ein winziger Schwimmer!'),
  ('68d813b6-47ae-4b82-ac7f-506d3dacf437', 'Wie ein Rennwagen! 🏎️', 'Das Herz schlägt 100-160 Mal pro Minute. Doppelt so schnell wie deins! Dieser Klang wird für dich wie Musik sein.'),
  ('1eea9abf-8e8e-49f8-aca7-b449e73948c5', 'Halte deinen Blutzucker stabil! 📉', 'Bei leerem Magen wird die Übelkeit stärker. Hab immer Cracker oder Trockenfrüchte in deiner Tasche dabei.'),
  ('83b88cf3-52f6-408b-8331-beef50dfe19f', 'Toilettenmarathon? 🚻', 'Häufiger Harndrang ist normal. Deine Nieren arbeiten jetzt mehr. Aber trink deshalb nicht weniger, sondern mehr Wasser!'),
  ('e7c343f8-73b3-41d3-a74d-ee9ee11dc752', 'Das Zitronenwasser-Wunder 🍋', 'Es lindert Übelkeit und unterstützt den Körper bei der Entgiftung. Zu wenig Flüssigkeit kann Kopfschmerzen verursachen.'),
  ('06ad8151-63c5-48be-b794-51e51402550d', 'Ist dein Akku leer? 🔋', 'Deine Energie kann schnell aufgebraucht sein. Ein kurzes Mittagsschläfchen wird dir richtig guttun.'),
  ('ae668457-885f-4308-8392-39228dd44060', 'Ich brauche einen Pool! 🏊‍♀️', 'Du bildest das Wasser, in dem ich schwimme (das Fruchtwasser), Mami. Öffne den Wasser-Tracker. Hast du schon ein Glas Wasser getrunken? ✅'),
  ('d2d789ff-23ab-49d2-829b-2a59a12e57ec', 'Gefühlsachterbahn 🎢', 'Erst lachen, dann weinen ... Die Hormone machen dich nicht verrückt, sie sind einfach fleißig am Werk.'),
  ('b80da43f-4fa0-465f-a1f5-d415c59577d5', 'Bist du geruchsempfindlich? 👃', 'Zwing dich nicht, Lebensmittel zu essen, die du nicht magst. Alternativen findest du im Bereich Ernährung.'),
  ('e7025bb0-45af-4595-8380-1e2af3adb2b9', 'Das Gehirn entwickelt sich! 🧠', 'Das Neuralrohr schließt sich. Nimm weiterhin Folsäure ein – jetzt wird der Grundstein für dein kleines Genie gelegt!'),
  ('a94e0a87-fa0f-44bc-96ea-31a14e8e1954', 'Wieder wie ein Teenager? 😳', 'In deinem Gesicht können Pickel auftreten. Daran sind die Hormone schuld! Halte deine Haut sauber und nimm keine Medikamente dagegen.'),
  ('bb01f67b-68b6-46f0-9ecd-af5b6f80b28b', 'Hast du unser erstes Foto gemacht? 🤰', 'Lade dein erstes Babybauchfoto in die Galerie hoch! ✨'),
  ('a8178689-8b83-4c18-aed1-047d8befc921', 'Probleme mit Verstopfung? 🚽', 'Viel Wasser und ballaststoffreiche Lebensmittel sind jetzt deine besten Freunde. Kiwis und getrocknete Aprikosen können wahre Wunder wirken.'),
  ('6fc47392-9629-4d33-8e40-e40e2521230e', 'Drücke ich dich? Tut mir leid!', 'Auch wenn du nicht zunimmst, mache ich mein Zuhause größer. Zieh die enge Hose aus und lieber etwas Bequemes an. 🤰'),
  ('9fae4e34-d2bb-467a-bd40-2f0853238a4e', 'Essiggurken oder Schokolade? 🍫', 'Schau im Bereich Ernährung nach: Was Gesundes steht heute auf dem Speiseplan? 😋'),
  ('c1f145fd-3d01-40af-8a31-7f261ae6105a', 'Der Geschmackssinn entwickelt sich 👅', 'Auf der Zunge deines Babys bilden sich Geschmacksknospen. So kann es auch schmecken, was du isst.'),
  ('e6b9a24b-da46-4708-9e5b-b659c3de661e', 'Du kannst den Geruch von Fleisch nicht ertragen? 🥩', 'Du brauchst Eiweiß! Wenn du kein Fleisch essen kannst, ersetze es durch Linsen, Kichererbsen oder Nüsse.'),
  ('44977c78-f7ae-4f0e-9e98-b634c325ef0b', 'Dein BH ist zu eng? 👙', 'Deine Brüste werden größer und empfindlicher. Zeit, auf einen bequemen Sport-BH ohne Bügel umzusteigen.'),
  ('494e490f-741c-402a-90a1-087cb49feebd', 'Dein Körper braucht Wasser! 💧', 'Flüssigkeitsmangel kann Kopfschmerzen verursachen. Öffne den Wasser-Tracker und trink ein Glas! ✅'),
  ('91f2c1e3-6e09-405e-873b-1c7871ae42d1', 'Dein Baby sieht schon wie ein kleiner Mensch aus! 👶', 'Und was ist mit deinem berühmten Schwangerschafts-Glow? ✨ Halte diese Schönheit in der Galerie für immer fest!'),
  ('6632cd55-3fc2-4b5a-99ae-1934d4d07a48', 'Eine Vitamin-C-Bombe 🍊', 'Orange, Kiwi oder Paprika ... Halte dein Immunsystem stark wie Stahl – jetzt bloß nicht krank werden!'),
  ('0839dbbd-18f9-4a16-8c8c-024d9b6c0fb5', 'Die Nieren arbeiten jetzt! 🚽', 'Unglaublich, aber dein Baby scheidet bereits Urin aus. Es schluckt Fruchtwasser und scheidet es wieder aus. Der Kreislauf beginnt!'),
  ('6ff4b2b8-64a6-4583-a2a6-a17dcd93d858', 'Hast du deinen Koffeinkonsum reduziert? ☕', 'Mehr als 1 Tasse pro Tag sollte es nicht sein. Probiere koffeinfreien Tee oder Kräutertee.'),
  ('75ccffd0-f3f8-457f-9109-f503ba1c9c27', 'Ich tanze! 🕺', 'Meine Arme und Beine können sich schon beugen. Ich mache in deinem Bauch akrobatische Übungen, aber du spürst mich noch nicht.'),
  ('471326ec-b4e0-411d-b639-63ddc151da1f', 'Wie wäre es mit Gemüsesuppe? 🥣', 'Wenn dein Magen schwere Speisen nicht verträgt, iss eine leichte Suppe. Sie liefert dir sowohl Vitamine als auch Flüssigkeit!'),
  ('20943f1e-d4df-412e-9bff-ad93646d91c9', 'Zeit für Bewegung 🧘‍♀️', 'Möchtest du dich bewegen? Schau doch im Bereich „Übungen“ nach, was zu dir passt.'),
  ('3efe947d-4b4b-4c7f-9958-16d89faba8db', 'Bezieh auch den Papa mit ein 🗣️', 'Das ist nicht nur dein Abenteuer. Schaut euch gemeinsam das erste Ultraschallbild an und sprecht über eure Pläne für die Zukunft.'),
  ('410a1e31-b41d-4130-8526-c1b0f94d7fcb', 'Meine Zähnchen machen sich noch nicht bemerkbar … noch nicht! 😬', 'Milch, Joghurt, Käse … Stehen diese Lebensmittel heute auf deinem Speiseplan? 🥛'),
  ('6d2e668d-18e8-41a3-a260-749a9ad4112f', 'Achte auf genügend Kalzium 🥛', 'Die Zahnknospen bilden sich. Quark, Käse oder Joghurt ... Das braucht dein Baby für sein späteres Lächeln!'),
  ('36af91e4-7cdc-478f-b431-003ca4f4075f', 'Hast du Kopfschmerzen? 🤕', 'Greife nicht gleich zu Medikamenten. Ein dunkler Raum, eine kalte Kompresse oder eine Massage können besser helfen.'),
  ('17a77385-a0f0-43f1-b604-ef36e1b9f457', 'Dein Kreislauf läuft auf Hochtouren! 🌊', 'Dein Blutvolumen nimmt zu und dein Herz arbeitet schneller. Wasser ist jetzt besonders wichtig, damit dein Körper gut damit zurechtkommt. Vergiss nicht, genug zu trinken, damit dir nicht schwindelig wird! ✅'),
  ('75908864-8ad0-496c-8a26-f45ae3d7e742', 'Hier wird fleißig gebaut! 🏗️', 'Dein Baby braucht Kalzium! Schau im Ernährungsbereich nach Milchprodukten. 🧀'),
  ('4395d8a1-8cd6-4561-9d88-e944bb78801d', 'Heute gibt es Fisch! 🐟', 'Wähle quecksilberarmen Fisch. Omega-3 ist für die Entwicklung des Gehirns unverzichtbar.'),
  ('2ba98fa8-fbf2-4460-81c1-96e992eb2cff', 'Sag Nein zu Dehnungsstreifen! 🧴', 'Auch wenn dein Bauch noch nicht sichtbar ist, solltest du deine Haut mit Feuchtigkeit versorgen. Mandel- oder Kokosöl kann auch den Juckreiz lindern.'),
  ('cbca369c-5e1a-4ee2-86f1-c37e9a851106', 'Zeit, das Geheimnis zu lüften? 📢', 'Das 1. Trimester geht zu Ende. Das Risiko ist gesunken. Bist du bereit, die frohe Botschaft mit deinen Freunden zu teilen?'),
  ('c3c5cda3-e24a-4bf6-8134-243e683db4d1', 'Das Skelett wird fester! 🦴', 'Der weiche Knorpel verwandelt sich in Knochen. Achte auf ausreichend Kalzium, damit dein Kleines starke Knochen bekommt!'),
  ('0c81e884-eb3b-459e-9e4c-250ee35d9884', 'Du erschaffst einen Ozean! 🌊', 'Das Fruchtwasser erneuert sich. Vergiss nicht, reichlich Wasser zu trinken, damit dein Baby in einem sauberen Pool schwimmen kann.'),
  ('5b178828-ade2-47ab-8de7-afb567ca7a86', 'Juckt dein Bauch? 🌵', 'Wenn sich die Haut dehnt, ist Juckreiz normal. Trage Mandelöl oder eine spezielle Creme auf und entspann dich.'),
  ('113c2ffd-412e-42e7-9340-2d6ba48c6d05', 'Kommt deine Energie zurück? 🔋', 'Wie fühlst du dich heute? Trag es in dein Symptomtagebuch ein! ✅'),
  ('a2d117f1-96df-4258-ab55-9a8d07073a66', 'Ich werde dich Mama nennen ... 🥺', 'Meine Stimmbänder bilden sich. Noch bin ich still, aber stellst du dir schon den Tag vor, an dem ich dich zum ersten Mal rufe? Ich schon ...'),
  ('d77d400f-027c-4514-b287-ee1cd4aff422', 'So groß wie eine Grapefruit! 🍊', 'Deine Taille kann breiter werden. Haben sich die Zahlen verändert? Trag sie im Gewichts-Tracker ein! 📈'),
  ('5d87369c-e5c4-4b67-b09a-fc38d7a668d6', 'Zeit für das Ersttrimester-Screening? 🗓️', 'Es ist zwischen der 11-14 Woche wichtig. Sprich mit deinem Arzt über die Untersuchung des Risikos für das Down-Syndrom.'),
  ('9b258cde-4bf1-416d-abf2-57eb7d09c208', 'Hast du Hunger oder Durst? 🤔', 'Manchmal verwechselt das Gehirn beides. Trink zuerst ein Glas Wasser. Wenn du danach immer noch hungrig bist, ist es Zeit zu essen.'),
  ('827f46df-37d3-4f5e-80af-9e3b8db96d01', 'Zeit für Gymnastik! 🤸', 'Dein Baby ballt schon seine Hände und öffnet den Mund. Auch wenn du es noch nicht spürst, finden da drinnen gerade Olympische Spiele statt!'),
  ('b247c7cf-7ded-4d8a-b64f-d3854d3be583', 'Da kommt ein schlaues Baby! 🧠', 'Jod ist für die Entwicklung des Gehirns unverzichtbar. Stehen Jodsalz, Fisch oder Milchprodukte auf deinem Speiseplan?'),
  ('9dfe8f42-50e3-422f-b528-dfdbb8ba5b68', 'Ich strecke mich! 🤸', 'Bleib du auch nicht untätig, Mami. Wollen wir uns die sanften Yogaübungen im Bereich „Übungen“ ansehen?'),
  ('2743aaf7-db86-4143-a5f6-a342a96beb63', 'Ballaststoffe sind echte Helden 🌾', 'Greif zu Haferflocken, Gemüse und Obst, um deine Verdauung zu unterstützen. Im Bereich Ernährung findest du leckere Salate.'),
  ('0aec0374-a2a9-4f72-92ad-01577161b993', 'Hebst du Gewichte? 🏋️‍♀️', 'Das Baby legt bereits eine Fettschicht an und sein Skelett wird fester. Wir werden schnell schwerer!'),
  ('0e8f121b-aec8-4bf1-b771-2456d0bdda0c', 'Der Nährstoffstrom nimmt Fahrt auf!', 'Was hast du heute Gesundes gegessen? Schau dir die Ernährungsliste an! 🥦'),
  ('e5a543f3-7d41-4d55-8690-ab14ba108363', 'Es nuckelt am Daumen! 👍', 'Beim Ultraschall kannst du vielleicht sehen, wie es am Daumen nuckelt. So trainiert es den Saugreflex für die Zeit nach der Geburt.'),
  ('1b07a663-2dbb-41a5-b9a0-2b4b252d015a', 'Schwimmst du gern? 🏊‍♀️', 'Dein Baby lebt im Wasser. Damit ausreichend Fruchtwasser vorhanden bleibt, solltest auch du über den Tag verteilt viel Wasser trinken.'),
  ('4e185ebb-b0f4-4552-9a03-4a4c79c95d4f', 'Lass deine Stimme hören! 🗣️', 'Das Baby kann deine Stimme und deinen Herzschlag jetzt deutlich hören. Sing ihm Schlaflieder vor – das beruhigt es. 🎶'),
  ('bc8843f7-6bd5-46ee-b8a3-e7c54310c8ea', 'Nuss-Power 🐿️', 'Omega-3 ist wichtig für die Gehirnentwicklung. Hab immer ein paar Nüsse in deiner Tasche: Sie halten dich satt und unterstützen gleichzeitig die geistige Entwicklung deines Babys.'),
  ('6b4229bd-ff86-4124-a6db-5ad3cc3444fe', 'Die schönste Zeit beginnt! ✨', 'Herzlichen Glückwunsch! Du bist jetzt im 2. Trimester. Deine Energie nimmt zu und die Risiken gehen zurück. Jetzt ist es Zeit, deine Schwangerschaft zu genießen.'),
  ('0e5bf60f-0c98-4770-8559-a9df3a31089c', 'Du brauchst einen Energieschub 💥', 'Dein Baby wächst schnell. Rotes Fleisch, Eier oder Hülsenfrüchte ... Denk daran, deine Eisen- und Eiweißreserven aufzufüllen.'),
  ('f6a83ba0-02bc-4279-b4c0-86ed3ee5b0ed', 'So groß wie eine Zitrone! 🍋', 'Ungefähr 7-8 cm. Dein Baby kann bereits den Kopf drehen und die Stirn runzeln. Seine Mimik entwickelt sich weiter!'),
  ('1a084eb2-2d29-44b6-a691-ad102b5c44de', 'Zeit für einen Kleiderschrank-Check 👗', 'Die Knöpfe gehen nicht mehr zu? Leg enge Hosen erst einmal beiseite. Steig auf weite, bequeme Kleidung aus natürlichen Stoffen um.'),
  ('0b20c112-5b84-42c9-aa1a-637151b2cd33', 'Mädchen oder Junge? 🩷💙', 'Die Geschlechtsorgane sind nun vollständig ausgebildet. Auch wenn es im Ultraschall noch schwer zu erkennen ist, weiß dein Baby schon, wer es ist! Was glaubst du?'),
  ('77993f33-af63-4a22-9cb2-3af058c96f19', 'Zieht dein Bauch? 😣', 'Vermeide plötzliche Bewegungen. Eine warme Dusche oder eine sanfte Massage kann die Schmerzen lindern.'),
  ('0cc5cbcc-4e89-43b3-8303-b5765d583930', 'Die Fingerabdrücke sind fertig! 🖐️', 'Diese einzigartigen Muster, die sonst niemand auf der Welt hat, sind bereits ausgebildet. Dein Baby ist jetzt schon ein einzigartiger Mensch. Ist das nicht großartig?'),
  ('f36e06df-bab1-456a-b2ec-00d5e38377c7', 'Hast du schnell wieder Hunger? 😋', 'Mehr Appetit zu haben ist völlig normal, aber für zwei zu essen ist ein Mythos. Wähle nährstoffreiche Lebensmittel wie Nüsse, Obst und Gemüse.'),
  ('9c22925e-f028-48cf-85a0-9499c06415cb', 'Ist deine Nase verstopft? 🤧', 'Du bist nicht krank – das ist ein Schwangerschaftsschnupfen. Verwende ein Kochsalz-Nasenspray und befeuchte die Raumluft.'),
  ('1ea8357f-773e-45c8-a5ce-b632b68c81c2', 'Schnelle Lieferung! 🚚', 'Wenn ich Hunger habe, kann es sein, dass ich anfange, dich anzustupsen. Was gibt es heute im Ernährungsbereich Gesundes? 😋'),
  ('5efd10b2-de1a-4b0e-b6df-24a9fc762806', 'Eine Fettschicht entsteht 🧸', 'Das Baby beginnt, Fett einzulagern, damit es warm bleibt.'),
  ('1228f5ed-c94b-45f8-bf5f-7e475683d6ed', 'Du bist eine Iron Lady! 🦸‍♀️', 'Iss rotes Fleisch oder Linsen, um Schwindel vorzubeugen. Unter „Ernährung“ findest du passende Rezepte.'),
  ('e7c711cf-139e-409a-9191-4e2baba06f95', 'So groß wie ein Apfel 🍎', 'Du darfst ruhig den Hosenknopf öffnen – mach es dir bequem! 😄'),
  ('f99f033a-c9d9-464f-8a73-afdf2f8530ec', 'Blutet dein Zahnfleisch? 😬', 'Die Hormone machen dein Zahnfleisch empfindlicher. Benutze eine weiche Zahnbürste und spüle deinen Mund mit Salzwasser aus.'),
  ('5b358e1c-fd56-41ad-b947-12dea0b15c36', 'Ich höre dich, Mama! 👂', 'Die Gehörknöchelchen werden fester. Dein Baby erkennt jetzt schon den Klang deiner Stimme, dein Lachen und deinen Herzschlag.'),
  ('e95b0195-5d3f-434c-9f11-c74aa50f4ba5', 'Das Skelett deines Babys wird fester🦴', 'Trink Milch oder iss Joghurt oder Mandeln, damit deine Kalziumreserven nicht aufgebraucht werden.'),
  ('22f8517a-e978-4689-beff-108150f23b01', 'Schlaf auf der linken Seite 🛌', 'Auf dem Rücken zu schlafen kann die Durchblutung beeinträchtigen. In der linken Seitenlage werden sowohl du als auch dein Baby besser mit Sauerstoff versorgt.'),
  ('000cbfe1-b7f7-4d1c-8e2e-4509f7ace829', 'Wellness-Tag? ✨', 'Die Haut deines Babys ist mit einer speziellen Schutzschicht bedeckt, damit sie im Wasser nicht schrumpelig wird. Und du? Nimm dir heute Zeit für dich! 💆‍♀️'),
  ('bec50930-1201-4fc9-8c19-535459114067', 'Ich sehe Licht! 💡', 'Obwohl seine Augenlider geschlossen sind, nimmt dein Baby helles Licht wahr. Wenn du mit einer Taschenlampe auf deinen Bauch leuchtest, dreht es möglicherweise sein Gesicht weg.'),
  ('2781a73f-51c3-4a91-8e1e-4ee828c3f885', 'Keine Chance für Verstopfung 🏃‍♀️', 'Trink reichlich Wasser und iss Trockenpflaumen und Kiwis, statt gleich zu Medikamenten zu greifen.'),
  ('fcdb41b2-8b6a-4d75-be79-f72070d4756a', 'Wo ist der Schlüssel? 🔑', 'Vergesslichkeit ist ganz normal. Dein Gehirn ist gerade mit etwas viel Wichtigerem beschäftigt: Es erschafft einen Menschen! Fang am besten an, Listen zu schreiben.'),
  ('2ac8ff81-e925-4d31-8ac2-6b55896aedfb', 'Hast du Wadenkrämpfe? 🦵', 'Möglicherweise fehlt dir Magnesium oder Kalzium. Iss eine Banane, Mandeln oder Joghurt. Und vergiss nicht, ausreichend Wasser zu trinken!'),
  ('937d5186-cb49-4a6c-a7a2-0e5731c4ae78', 'So groß wie eine Birne! 🍐', 'Dein Baby wird länger und sein Körper richtet sich auf. Es kann seinen Kopf jetzt ganz aufrecht halten. Dein Baby wächst und du wirst immer schöner!'),
  ('d4b39ae6-9d34-4c4d-8a69-951fc75c6f59', 'Wer ist der beste Freund von Eisen? 🍊', 'Wenn du Eisen einnimmst, solltest du es unbedingt mit Vitamin C kombinieren. So kann dein Körper das Eisen besser aufnehmen.'),
  ('9ad99447-3f71-4bc4-9dff-13a64a93c8f4', 'Tut dein Rücken weh? 👠', 'Stell die High Heels in den Schrank – jetzt ist Komfort angesagt! Entscheide dich für orthopädische Schuhe.'),
  ('a4dafbff-3c24-457e-81b5-bb659a58fa4b', 'Zieht es an den Seiten? ⚡', 'Es kann plötzlich stechen, aber keine Angst – ich mache nur mein Zuhause größer! Probiere die entspannenden Übungen im Bereich „Übungen“ aus. 🤸‍♀️'),
  ('039c5d10-ebc0-436e-9936-a148242fd9a3', 'Der Reisepass ist fertig! 🛂', 'Die Fingerabdrücke sind vollständig ausgebildet. Diese Muster, die sonst niemand auf der Welt hat, sind jetzt da. Ein einzigartiger Mensch ist unterwegs!'),
  ('f1613176-745a-48b4-a20e-1dee77f819cf', 'Wasser schmeckt dir zu langweilig? 💧', 'Wenn dir das Trinken schwerfällt, probiere Wasser mit Gurke, Wassermelone oder Minze. Flüssigkeitsmangel kann Kopfschmerzen verursachen.'),
  ('f319fe10-d32c-42c4-938c-e7358782f1f1', 'Mami, ich kann dich hören! 👂', 'Deine Stimme klingt für mich wie ein Schlaflied. Und dein Herzschlag ist der schönste Rhythmus. Sprich öfter mit mir, ich möchte dich kennenlernen.'),
  ('08cbf45e-1a2d-4043-a7ff-cbce10cda3f8', 'Zink: Der heimliche Held 🛡️', 'Meine Zellen teilen sich rasant. Ich brauche Baumaterial! Stehen rotes Fleisch, Käse oder Nüsse auf dem Speiseplan?'),
  ('08979df0-c3a9-4a97-8501-c4fbc032480c', 'Ich bin so groß wie eine Mango! 🥭', 'Ungefähr 15 cm. Meine Haut ist noch dünn, aber langsam bildet sich eine Fettschicht. Jetzt sehe ich schon etwas rundlicher aus, Mami!'),
  ('9cb3f2ab-0aed-4e06-977f-d372f91e236f', 'Hast du es gespürt? Ein Tritt! ⚽', 'Mami, ich bin wach! Dieses leichte Flattern ist mein Gruß an dich. Leg deine Hand auf den Bauch – vielleicht mache ich es noch einmal?'),
  ('c42cae82-ff16-485c-8a26-23b4bfd30c8b', 'Junge oder Mädchen? 💙💗', 'Der Ultraschalltermin, bei dem du mein Geschlecht erfahren kannst, rückt näher. Bist du schon aufgeregt?'),
  ('6ada1169-9af2-4ce3-bb7e-de40ea64dfd1', 'Ich habe mein erstes Spielzeug!', 'Ich greife nach der Nabelschnur, spiele mit ihr und drücke sie manchmal. Meine Finger lernen bereits, Dinge festzuhalten.'),
  ('7529d4a8-1e26-4d8b-8bcf-18154f789283', 'Zeit für den großen Termin! 🗓️', 'Zwischen der 18. und 22. Woche findet der ausführlichste Ultraschall statt. Dabei werden meine Finger, mein Herz und alles andere ganz genau untersucht. Hast du schon einen Termin vereinbart?'),
  ('d03c23f6-2e1d-4083-b90a-157da0e6e6f4', 'Die Verstopfung lässt nicht nach? 🚽', 'Ballaststoffreiche Lebensmittel und viel Wasser sind die beste Medizin. Bleib in Bewegung – tägliche Spaziergänge bringen den Darm in Schwung.'),
  ('0deb48f1-6a30-484b-9569-decc49f2c37c', 'Die Knochen werden härter! 🦴', 'Die weichen, gummiartigen Knorpel verwandeln sich in Knochen. Fülle deine Kalziumspeicher auf, damit das Skelett deines Babys stark wie Stahl wird!'),
  ('b9294383-8fdd-4af3-9a0e-31820d8761cf', 'Schluss mit Schwindel! 🛑', 'Mit zunehmendem Blutvolumen steigt auch dein Eisenbedarf. Spinat, Buchweizen oder rotes Fleisch ... Nimm sie unbedingt in deinen Speiseplan auf!'),
  ('38d34d85-388f-49ed-9594-2287f8011443', 'Disko im Bauch? 💃', 'Ich lerne hier drinnen gerade Purzelbäume zu schlagen! Hast du es gespürt?'),
  ('2496cef6-77ee-4345-81fb-7ae6ee89a5c4', 'Hast du seltsame Träume? 😴', 'Die Hormone können deine Nächte in einen Kinofilm verwandeln. Keine Sorge, das ist normal. Halte deine Träume im Stimmungstagebuch fest!'),
  ('a0a2da1d-904a-4c50-8ef1-d362ba476da8', 'Natürliche Schutzcreme! 🧴', 'Damit seine Haut nicht schrumpelig wird, bedeckt sie sich mit einer weißen, käseähnlichen Substanz namens Vernix. Die natürliche Schutzcreme der Natur!'),
  ('6fb4f290-31ce-473d-a17d-ea607c5d055d', 'So groß wie eine Banane! 🍌', 'Ungefähr 18-20 sm. Jetzt werde ich vom Kopf bis zu den Füßen gemessen. Ich werde länger und mein Körper richtet sich auf.'),
  ('8731dd9d-3325-4b84-b0cd-b6cef3da8f89', 'Pssst, ich schlafe 😴', 'Ich habe auch schon meinen eigenen Schlafrhythmus, Mami. Wenn du unterwegs bist, werde ich sanft in den Schlaf gewiegt. Aber sobald du dich hinlegst, wache ich auf und veranstalte eine Disco! Entschuldige 😇'),
  ('61323e5e-ad2b-4a40-a3f3-72d99e6d77ef', 'Die Hälfte ist geschafft! 🏁', 'Herzlichen Glückwunsch! 20 Wochen liegen bereits hinter dir. Du hast die Halbzeit deiner Schwangerschaft erreicht. Du bist großartig – das solltest du feiern!'),
  ('5d030bf9-1346-4234-959d-a123523b7611', 'Wird geladen... 50% ⏳', 'Herzlichen Glückwunsch! Wir haben die Hälfte des Weges geschafft. Dieser besondere Tag verdient ein Foto in der Galerie! ✨'),
  ('5a1b20c0-b4ed-4031-8577-4c8ce7ee3faf', 'Kann Papa mich spüren?', 'Wenn er seine Hand auf deinen Bauch legt, sage ich vielleicht auch ihm Hallo.❤️'),
  ('dafe2e2c-e054-4c05-a7f0-7e5828a0bd40', 'Träumst du in bunten Farben?', 'Träume in der Schwangerschaft sind wie Filme, nicht wahr? Komme ich auch darin vor? 😴'),
  ('b707fa58-b376-47be-9e74-acc0d0bc553a', 'Selfcare-Tag 💅', 'Wenn du Schwangerschaftsflecken bekommen hast, schütze dich vor der Sonne. Wie wäre es heute mit einer Gesichtsmaske?'),
  ('b050527e-1e40-44a0-ab00-fb32d6abb570', 'Es entdeckt sein Gesicht! 👶', 'Mit den Händen berührt dein Baby sein Gesicht, seine Nase und sogar die Nabelschnur. Sein Tastsinn entwickelt sich. Es lernt sich selbst kennen!'),
  ('866256da-856c-40a8-a2d6-0e562a2b89fa', 'Essiggurken und Eis? 🥒🍦', 'Hast du Lust auf ungewöhnliche Kombinationen? Das sind Signale deines Körpers. Achte aber darauf, Zucker und Salz in Maßen zu genießen.'),
  ('b5881822-5bbb-4123-8e83-7e5e1502c2a2', 'So groß wie eine Kokosnuss! 🥥', 'Ungefähr 28 cm. Dein Baby wiegt jetzt schon über ein halbes Kilo! Und es tritt nun kräftiger.'),
  ('b4b9bd27-17f0-4aee-8b06-793656f6ef67', 'Wollen wir Musik hören? 🎶', 'Mami, ich kann die Geräusche von draußen hören! Deine Lieblingslieder gefallen mir auch. Wollen wir zusammen tanzen?'),
  ('473ac730-c42b-4a8b-8df8-3ff17fbbb8fc', 'Steht dein Bauchnabel hervor? 🔘', 'Wenn dein Bauch wächst, kann sich dein Bauchnabel nach außen wölben. Keine Sorge, nach der Geburt bildet er sich wieder zurück!'),
  ('5b28b973-6a08-480a-befc-a57bb7fa577b', 'Eisen wird gebraucht 🏗️', 'Ich bin damit beschäftigt, rote Blutkörperchen zu bilden. Hilf mir dabei: Iss Rindfleisch, Spinat oder Linsen.'),
  ('323b3eda-82d0-406d-9ef8-03c3ba37648c', 'Sind deine Beine geschwollen? 👠', 'Wassereinlagerungen können jetzt auftreten. Lege deine Beine bei der Arbeit oder zu Hause so oft wie möglich hoch. Wähle bequeme Schuhe!'),
  ('e5b18866-69e0-4ac8-9b93-de4b2812e136', 'Hicks... Hicks... 🤭', 'Zuckt dein Bauch rhythmisch? Keine Sorge, Mami, das ist nur Schluckauf! Ich trainiere gerade mein Zwerchfell.'),
  ('fae74e2f-98a8-45d5-8202-44383d0eb18a', 'Es erkennt Geschmäcker! 👅', 'Der Geschmack des Fruchtwassers verändert sich je nachdem, was du isst. Hast du scharfe Paprika gegessen? Dein Baby wird es schmecken!'),
  ('88a2f76b-bbca-49e6-a2ea-fe93e58a6be7', 'Meine Augen tanzen...', 'Obwohl meine Augenlider geschlossen sind, träume ich schon. Was meinst du, wovon ich träume?'),
  ('302938ba-54dd-42b1-8785-76afddeea091', 'Hast du Sodbrennen? 🔥', 'Die Gebärmutter drückt auf den Magen. Iss kleinere Portionen, dafür aber häufiger. Lege dich nicht direkt nach dem Essen hin, sondern bleib aufrecht sitzen.'),
  ('ba959c1d-a66b-4198-9703-7d204b6d9029', 'Was war das für ein Geräusch, Mama? 🔊', 'Bei plötzlichen Geräuschen erschrecke ich mich. Wenn du ruhig bist, bin ich auch ruhig. Kannst du mir ein Schlaflied vorsingen?'),
  ('52571825-8dff-470b-9a01-2096ca6a9ef9', 'Du bist meine Wiege ... 💤', 'Wenn du gehst, werde ich sanft in den Schlaf geschaukelt. Aber sobald du stehen bleibst, wache ich auf! Wollen wir weiter gemütlich spazieren gehen, damit ich schlafen kann? 🚶‍♀️'),
  ('1184b7b9-b4b5-43fa-a2bc-fd09d7701438', 'Hast du die Zuckerlösung getrunken? 🥤', 'Der Test auf Schwangerschaftsdiabetes ist wichtig. Lass ihn unbedingt durchführen – für deine und meine Gesundheit.'),
  ('27ba2d28-f6c7-4448-bd98-0c87bc789c84', 'Hast du eine dunkle Linie auf dem Bauch? ➖', 'Die Linea nigra entsteht durch die Hormone. Keine Sorge, nach der Geburt wird sie wieder verblassen. Du bist immer wunderschön!'),
  ('352b7abf-9862-4591-888e-8f478b7b349c', 'Meine Überlebenschancen sind gestiegen! 🌟', 'Ich bin jetzt 24 Wochen alt! Medizinisch gelte ich nun als lebensfähig. Das ist ein riesiger Meilenstein, Mama.'),
  ('48f71f64-0f7f-494d-bb7e-d0d4e9ee139b', 'Hast du Sodbrennen? 🔥', 'Das liegt nicht daran, dass meine Haare wachsen, sondern daran, dass die Gebärmutter auf deinen Magen drückt. Leg dich nicht direkt nach dem Essen hin, sondern bleib aufrecht sitzen.'),
  ('3993d773-d077-4047-afc5-47cd2550cb94', 'Wehen oder nur Übung? 🤔', 'Dein Bauch wird hart? Das könnten Übungswehen sein. Deine Gebärmutter bereitet sich auf die Geburt vor. Solange sie nicht schmerzhaft sind, ist das normal.'),
  ('60d55b22-fbf7-460c-942e-d9f7e0731669', 'Vermeide salzige Speisen 🧂', 'Wenn deine Füße anschwellen, solltest du weniger Salz essen. Viel Wasser und Petersilie können helfen. Sitzt dein Ring am Finger etwa zu eng?'),
  ('6de7574a-4dcf-48fd-a091-4641ee581b82', 'Die kleine Fabrik läuft! 🏭', 'Nicht mehr meine Leber, sondern mein Knochenmark produziert jetzt Blutzellen. Welche eisenreichen Lebensmittel kannst du essen, um mich dabei zu unterstützen?'),
  ('a2eb3d0f-d97b-4159-b6ca-2c03e31ea7ae', 'Pssst, ich schlafe ... 🤫', 'Mami, warum bewege ich mich nicht? Weil ich die meiste Zeit des Tages schlafe. Ruh dich auch aus, während ich schlafe.'),
  ('cb6d62d7-338e-4fb3-907d-9bfa587ddc19', 'Zeit für ein heimliches Training! 🧘‍♀️', 'Vergiss deine Kegelübungen nicht. Spanne im Sitzen deine Beckenbodenmuskulatur an und lass wieder locker. Das wird dir bei der Geburt helfen!'),
  ('26be4f7a-020a-4656-9916-24ee79dcc7a2', 'Meine ersten Atemübungen! 🫁', 'In meiner Lunge bildet sich Surfactant. Diese Substanz wird mir helfen, nach der Geburt meinen ersten Atemzug zu machen. Ich übe schon!'),
  ('20bf8c66-4b67-4eac-9759-383a08875de7', 'Mami, mir ist langweilig! 🤸', 'Wenn du zur Ruhe kommst, wache ich auf. Streichle deinen Bauch – vielleicht antworte ich dir mit einem kleinen Tritt?'),
  ('db0c5fae-71f1-477b-b321-634c423e0906', 'Ich bin so groß wie eine Melone! 🍈', 'Ich wiege ungefähr 600 Gramm. Langsam wird es hier etwas eng. Meine Tritte können jetzt kräftiger werden – entschuldige! 🦶'),
  ('526f7ea7-3f69-40d2-905e-c2bffa0601cc', 'Drücken deine Schuhe? 👟', 'Deine Schuhgröße kann zunehmen. Jetzt zählt nicht der Stil, sondern der Komfort. Steig auf weite Sneaker um!'),
  ('2383cc1a-d388-4623-bfbc-9b03b5278f79', 'Meine Haare bekommen Farbe! 🎨', 'Die genetische Lotterie hat begonnen. Blond, schwarz oder rötlich? Die Pigmente in meinen Haaren bilden sich. Was meinst du, wem werde ich ähnlich sehen?'),
  ('d07f0b6e-c86e-44de-8e9f-d89a09f2ec43', 'Genug von den Schwellungen? 🎈', 'So paradox es klingt: Wassertrinken kann Wassereinlagerungen reduzieren. Auch wasserreiche Lebensmittel wie Gurken und Wassermelonen können helfen. Vermeide zu viel Salz.'),
  ('fec31592-3149-479f-9be0-155a720e090b', 'Ich werde rosig ...', 'Meine Haut ist nicht mehr durchsichtig wie Glas! Meine Kapillaren füllen sich mit Blut und meine Haut wird rosiger. Vergiss nicht, mit dem Wasser-Tracker genug Wasser zu trinken – das unterstützt deinen Kreislauf! 🥤'),
  ('153927df-2197-4033-aa1c-31dfbfdf9083', 'Hoppla! Was war das für ein Geräusch? 😳', 'Als die Tür zuschlug, habe ich mich erschreckt. Ich kann schon sehr gut hören, Mami. Mach ruhige Musik an, dann entspannen wir uns gemeinsam.'),
  ('4de979ce-b173-440f-bc60-e4d333797f19', 'Meine Nase ist jetzt frei! 👃', 'Meine Nasenlöcher waren bisher verschlossen, jetzt sind sie offen. Ich übe schon mal das Atmen.'),
  ('2efc37a3-7408-4f42-8512-00545c8b1565', 'Ist deine Verdauung träge? 🐌', 'Progesteron verlangsamt die Darmtätigkeit. Getrocknete Aprikosen, Pflaumen und Vollkornbrot können dir helfen.'),
  ('32fe315d-64ad-42bb-8357-047270382c70', 'Baue dir eine Kissenburg! 🏰', 'Du kannst nicht bequem schlafen? Lege ein Kissen zwischen deine Beine und eines unter deinen Bauch. Unterstützung ist jetzt besonders wichtig!'),
  ('99d63bff-e50d-4a8d-89f1-525eee8af207', 'Ich bin ein Yoga-Profi! 🦶', 'Du wirst es kaum glauben, aber ich kann meinen Zeh greifen und in den Mund stecken! Ich bin richtig beweglich. Und dir fällt das Bücken inzwischen schwer?'),
  ('9c19e501-078c-4145-9bf4-28096c2e69da', 'Ich habe meine Augen geöffnet! 👀', 'Mami, du wirst es kaum glauben, aber ich habe meine Lider geöffnet. Obwohl es dunkel ist, entwickelt sich mein Sehvermögen immer weiter. Bald kann ich dich sehen!'),
  ('5b81d2cf-3568-4e53-b14d-b0aeaec2f43f', 'Höre ich Papa? 🗣️', 'Eine Männerstimme klingt tiefer, deshalb kann ich sie besser hören. Sprich mit Papa und lass ihn mir eine Geschichte vorlesen.'),
  ('cf9fd374-f357-4b58-bc32-9c2c7983b9f8', 'Du bist mein Schutzschild!', 'Mein Immunsystem entwickelt sich, und über dich bekomme ich Antikörper. Du schützt mich vor Krankheiten, Mami. ❤️'),
  ('6631a482-e880-499b-a108-1eb7cfe533ac', 'Hast du Krämpfe? 🦶', 'Hast du nachts Wadenkrämpfe? Vielleicht fehlt dir Magnesium. Banane, Mandeln oder Joghurt ... Deine Muskeln brauchen Entspannung.'),
  ('67d7589f-358a-44b0-9ee8-70aca8b6ffc6', 'Ich habe meine Augen geöffnet! 👀', 'Obwohl es dunkel ist, kann ich meine Augenlider schon öffnen. Ich blinzle. Bald kommt der Tag, an dem ich die Welt sehen werde!'),
  ('6a3d4aec-a08e-46ec-9845-95181acaa958', 'Ich sehe Licht, Mami! ☀️', 'Ich blinzle! Wenn Sonnenlicht auf deinen Bauch fällt, kann ich die Helligkeit sehen. Welche Farbe hat die Welt?'),
  ('79b3dcb1-a984-4729-ab92-c057730e6f8d', 'Zeit zum Eincremen 🧴', 'Dein Bauch wächst schnell und die Haut spannt. Trage täglich eine Feuchtigkeitscreme auf, um Juckreiz vorzubeugen.'),
  ('11db6f3d-a2eb-4392-b358-993a953c992e', 'Der erste Impfschutz kommt von dir 🛡️', 'Deine Antikörper werden auf dein Baby übertragen. Sie schützen es in den ersten Monaten nach der Geburt.'),
  ('ecec560e-f533-42fa-b81c-743ce51e2fa4', 'Salzgurken? Lieber nicht! 🚫', 'Wenn deine Beine anschwellen, solltest du Salz auf ein Minimum reduzieren. Eingelegtes schmeckt zwar lecker, kann aber Wassereinlagerungen begünstigen. Trink stattdessen Wasser mit Zitrone.'),
  ('eb78f9b1-0793-4172-8289-9ad69826fa75', 'Die Welt ist so laut ... 🔊', 'Meine Ohren sind inzwischen so empfindlich, dass ich sogar Geräusche von draußen hören kann. Wollen wir es uns etwas ruhiger machen? Spiel mir bei den Weißen Geräuschen Regengeräusche vor, dann schlummern wir gemeinsam ein. 🌧️'),
  ('23bdc5ce-4bf9-4c06-b27f-3cf7672d0391', 'Ich halte den Takt 🥁', 'Mein Herz schlägt gleichmäßig und ich übe schon das Atmen. Manchmal habe ich Schluckauf.'),
  ('486ac2e6-38fa-429a-b2e0-197066312def', 'Der Endspurt naht! 🏁', 'Die letzten Tage des 2. Trimesters sind da. Schlaf dich gut aus, bevor das 3. Trimester beginnt!'),
  ('2a7b5422-c620-43f8-9faf-09db6234cc0f', 'Willkommen im 3. Trimester! 🏁', 'Die letzte Etappe hat begonnen! Dein Körper wird sich jetzt schwerer anfühlen, aber die Ziellinie ist schon in Sicht. Hab noch etwas Geduld, Mama!'),
  ('283efed7-5c27-4325-a5d1-abc7b9874001', 'Wie wird mein Charakter sein? ✨', 'Stur oder gefühlvoll? Was sagt mein Sternzeichen anhand meines Geburtstermins über mich aus? Passt es zu deinem Sternzeichen? Lass uns ins Horoskop schauen! 🌠'),
  ('2d850fd8-33a5-4d99-8d38-9501167a4a14', 'Tun dir die Rippen weh? 🥊', 'Entschuldige, Mami, ich habe nur wenig Platz. Wenn ich meine Beine ausstrecke, stoße ich an deine Rippen. Aufrechtes Sitzen kann dir helfen.'),
  ('881c71cb-32af-4e22-9bf1-839ae870e7a5', 'Zählst du meine Tritte? 🦶', 'Allmählich entwickelt sich ein Bewegungsrhythmus. Öffne den Trittzähler und beobachte meine Aktivität. Ist alles in Ordnung?'),
  ('9d46b716-6bee-4533-9dcb-2ebd6327811f', 'Mein Gehirn bekommt Falten! 🧠', 'Früher war es glatt, jetzt bilden sich Falten und Furchen. Das bedeutet, dass Milliarden von Nervenzellen aktiv werden. Ein Genie ist unterwegs!'),
  ('b2fb0049-069a-46c3-bea3-307a0c34873c', 'Macht dir der Reflux zu schaffen? 🔥', 'Steigt dir Magensäure bis in den Hals? Nach dem Essen Kaugummi zu kauen oder warme Milch zu trinken, kann helfen.'),
  ('88619dd2-a8e1-47a0-8257-5ec0eff6998d', 'Ich bin so groß wie ein Kürbis! 🎃', 'Ungefähr 39-40 sm. Ich wiege jetzt 1.2 kq! Bin ich dir schon zu schwer? Entschuldige, Mami, aber ich muss zunehmen.'),
  ('c1685f6c-ebb8-432c-88df-49144f8b19c4', 'Brennt dein Magen? 🔥', 'Die Gebärmutter drückt deinen Magen nach oben. Ein Glas Milch oder eine Handvoll rohe Mandeln können das Sodbrennen lindern.'),
  ('b119316e-3eaf-473d-92b5-cf9d282e6e05', 'So groß wie ein Brokkoli 🥦', 'Meine Fettpolster werden dicker und meine Arme und Beine immer pummeliger.'),
  ('0a1c9fc7-d6fb-46ee-b640-782093d821ef', 'Bauen wir ein Nest? 🐣', 'Mein Bettchen, meine kleinen Kleidungsstücke ... Erstellt die Liste gemeinsam mit Papa im Gemeinsamen Einkauf! 📝'),
  ('f8beb64f-d6c0-4f9c-a2ac-a26ff5b8a6ea', 'Hast du einen negativen Rhesusfaktor? 🩸', 'Für Mamas mit negativem Rhesusfaktor ist dies eine entscheidende Woche. Möglicherweise brauchst du eine Immunglobulin-Spritze. Sprich mit deinem Arzt darüber!'),
  ('6e18672f-c08d-4df7-a33d-ffe41885dcb7', 'Meine Wimpern sind gewachsen! 👁️', 'Ich öffne und schließe meine Augen und kann zwischen Licht und Dunkelheit unterscheiden. Wenn du mit einer Taschenlampe auf deinen Bauch leuchtest, drehe ich mein Gesicht weg. Möchtest du es ausprobieren?'),
  ('382ecc0d-761f-4375-83d6-da7672e029c4', 'Fisch, Fisch, Fisch! 🐟', 'Mein Gehirn entwickelt sich gerade besonders schnell. Ich brauche Omega-3. Isst du zweimal pro Woche Fisch?'),
  ('8e4d973a-778f-424e-8c3a-935a1a80329f', 'Hast du schon an deine Tasche gedacht? 👜', 'Es ist noch nicht zu früh! Schau dir die Checkliste für die Kliniktasche an. Wenn du jetzt schon alles Fehlende besorgst, hast du später weniger Stress.'),
  ('5e65c444-b9a6-406f-9ff5-56e21f7ef978', 'Soll ich dir ein Geheimnis verraten? 🤫', 'Wenn du schläfst, schlafe ich mit der Erinnerung an deine Stimme ein. Was meinst du, von wem ich träume? Natürlich von dir! 🥰'),
  ('d7852d04-73e0-436f-88c1-c1f3779215e1', 'War das etwa Schokolade? 🍫', 'Mmm, der leckere Geschmack ist bis zu mir vorgedrungen! Jetzt sprühe ich nur so vor Energie. Lass uns tanzen, Mami! 💃'),
  ('cbb3164b-a073-4125-89bc-aa96300b8738', 'Ich bin so groß wie ein Kürbis! 🎃', 'Meine Bäckchen werden so rund, dass du am liebsten hineinbeißen möchtest! Es wird langsam eng, aber ich bin gern so nah bei dir.'),
  ('24a71b37-df5d-44b3-a005-e5736c2b3038', 'Ich stehe kopfüber! 🙃', 'Es ist spannend, die Welt verkehrt herum zu sehen! Ich bereite mich auf die Geburt vor, Mami. In dieser Position bin ich dir noch näher.'),
  ('2bb496d6-7982-41e7-af5d-07497cf28d32', 'Wird dein Bauch hart? 🤰', 'Keine Angst, mein Engel! Das sind nur Übungswehen. Gemeinsam bereiten wir uns als Team auf den großen Tag vor!'),
  ('6c259c3a-0864-4b21-9205-87b10a98dab6', 'Ich bin hier, Mami! 👋', 'Manchmal bin ich ganz ruhig, manchmal tanze ich. Zählst du meine Tritte? Alles ist in Ordnung, ich habe nur immer weniger Platz.'),
  ('90084ac3-06b5-4f06-ab1a-792e7c238804', 'Ein Spinnennetz an deinen Beinen? 🕸️', 'Es können Krampfadern entstehen. Steh nicht zu lange. Leg dich abends hin und stütze deine Beine an der Wand hoch.'),
  ('7a6fc4a8-e1e2-4415-a61f-8af42944c1a1', 'Die Blutzellfabrik läuft 🩸', 'Bisher hat die Leber Blutzellen gebildet, jetzt übernimmt das Knochenmark diese Aufgabe. Das ist die Vorbereitung auf ein eigenständiges Leben!'),
  ('c0cb44c3-4840-4ac8-9cb6-1e444e960d76', 'Das Duo aus Eisen und Vitamin C 🥩🍊', 'Um das Risiko einer Anämie zu senken: Trink zum Fleisch ein Glas Orangensaft. Vitamin C erhöht die Eisenaufnahme um das 2-Fache.'),
  ('5f837347-a4f8-48d6-bc79-6f4d3e4ab2ed', 'Ein großer Kohlkopf 🥬', 'Meine Haut wird glatter und meine Wangen werden runder. Ich kann es kaum erwarten, dich zu sehen!'),
  ('a1284943-8afb-4514-a518-910d7434b8db', 'Bekommst du schlecht Luft? 😮‍💨', 'Je höher ich rutsche, desto mehr drücke ich auf dein Zwerchfell. Versuch, tief durchzuatmen, Mami. Es dauert nicht mehr lange, dann rutsche ich nach unten.'),
  ('6c2d3dce-218d-4319-8647-5e91a8fe5c40', 'Da ist Papas Stimme! 🧔', 'Wenn ich seine Stimme höre, schlägt mein Herz noch schneller. Sag ihm, dass ich auch hier bin und Hallo sage! 👋'),
  ('8564b0d7-d9cc-487d-822b-1f8072415eb2', 'Mach meine Knochen stark! 💪', 'Ich brauche Kalzium, Mami. Wenn du ein Glas Milch trinkst oder einen Joghurt isst, werden wir beide superstark! 🥛'),
  ('15ce00b6-4caf-41e5-8ad8-51691c8f30be', 'Klopf, klopf! Wer ist da? ✊', 'Tun dir meine Tritte manchmal weh? Tut mir leid 🥺 Ich möchte dich einfach nur berühren.'),
  ('b989ed16-7146-4f41-9b58-332ae708a0f2', 'Bist du kurzatmig? 😮‍💨', 'Ich bin etwas weiter nach oben gerutscht und drücke auf deine Lunge. Tut mir leid, Mami, bald rutsche ich nach unten und du kannst wieder leichter atmen! 🤞'),
  ('030e064d-37b0-4189-9cde-718dbc4298a7', 'Ich werde deinen Duft riechen ...', 'Stellst du dir den Moment vor, in dem du mich in deine Arme nimmst? Ich wachse jeden Tag mit dem Traum von diesem Moment, Mami! 🌸'),
  ('e03f95b4-ad0c-4331-ae04-096968066425', 'Mein Zuhause wird eng ... 🏠', 'Meine Bewegungen fühlen sich jetzt wie kleine Faust- und Ellbogenstöße an. Ist alles in Ordnung? Lass uns gemeinsam den Trittzähler überprüfen!'),
  ('76a21abd-5509-4070-92f1-19d3342eec20', 'Du brauchst frische Luft 🌿', 'Wollen wir heute rausgehen und an einem ruhigen Ort mit frischer Luft einen Tee trinken? Schau dir die mama-freundlichen Orte an!'),
  ('24bc4a35-8099-475a-bea1-67cccf403b8e', 'Der große Tag ... ✨', 'Nur keine Eile, aber lass uns langsam die Kliniktasche packen. Wollen wir gemeinsam schauen, was auf der Checkliste für die Kliniktasche steht?'),
  ('e0c08939-6705-4af3-8c21-9e0d55be665b', 'Pssst ... Ich schlafe 😴', 'Mein Gehirn entwickelt sich so schnell, dass ich die meiste Zeit schlafe. Ruh du dich auch aus, Mami.'),
  ('c28b4b45-5df1-4c21-963d-2cd627f1bb02', 'Wie soll ich heißen? 👶', 'Falls ihr euch noch nicht entschieden habt, schaut euch gemeinsam die Liste mit Babynamen an. Welcher Name passt wohl am besten zu mir?'),
  ('c121195f-505c-434b-b2d9-c9f6d23b400a', 'Mein Zimmer, mein Bettchen, meine kleinen Sachen ... 🐣', 'Hast du alles besorgt, was wir brauchen? Schau dir die empfohlenen Produkte an – vielleicht fehlt noch etwas.'),
  ('c3f0f3b0-ee69-4cef-beda-1bb1348e7009', 'Die Gebärmuttermuskulatur bereitet sich auf die Geburt vor.', 'Keine Sorge, das sind nur Übungswehen. Wenn die Wehen häufig auftreten, überprüfe die Abstände mit dem Wehentimer!'),
  ('8dfa3145-c829-45b1-afeb-aa3c0845ee68', 'Meine Maniküre ist fertig!', 'Du wirst es nicht glauben: Meine Nägel reichen schon bis zu den Fingerspitzen.'),
  ('59ee96ac-8001-4e85-87e8-bcbd686717cb', 'Die Arzttermine werden häufiger! 🩺', 'Hast du dich schon für eine Geburtsklinik und einen Arzt entschieden? Schau dir die Liste der Ärzte und Kliniken an! ✅'),
  ('ca64b110-70d5-455b-a30e-4c256cab3188', 'Erst lachst du, dann weinst du?', 'Die Hormone spielen mal wieder verrückt. Die Angst vor der Geburt und die Freude auf unser Kennenlernen liegen ganz nah beieinander. Schütte deinem Stimmungstagebuch dein Herz aus und entspann dich. ❤️'),
  ('715eeefe-c617-4bf3-bb6a-6c3fba21c1f5', 'Deine Superkraft geht auf mich über! 🛡️', 'Werde nicht krank, Mama! Dein Immunsystem wird mein erster Schutzschild sein. Wir sind ein unschlagbares Team! 💪'),
  ('c1070439-01ff-45b2-8b26-5012c32a3638', 'Kannst du schon wieder nicht schlafen? 🥺', 'Ich dagegen schlafe tief und fest. Schließ die Augen und stell dir mich vor ... Vielleicht treffen wir uns im Traum? 🌙'),
  ('8be6aa28-e9ad-4b76-b7b7-9a3182c371dc', 'Meine Knochen werden hart wie Stein! 🦴', 'Aber dafür plündere ich deine Reserven ... Entschuldige! 🙈 Vertragen wir uns wieder, wenn du ein Glas Milch trinkst? 🥛'),
  ('80a0c6d7-ffbe-49de-90ea-da3074257deb', 'Sing das Lied noch einmal! 🎶', 'Deine Stimme beruhigt mich so sehr ... Wenn du singst, tanze ich hier drinnen. Spürst du es? 💃'),
  ('8a02111b-8b8b-4912-a2f8-2e33ed9f29ac', 'Die Wände kommen immer näher! 🏠', 'Hier wird es ganz schön eng, Mami. Wenn ich mein Bein ausstrecke, stoße ich gegen deine Rippen ... Falls ich dir wehgetan habe: Soll ich es mit einem Kuss wieder gut machen? 💋'),
  ('d8af3bb6-0839-43e8-86c1-22d12e84c887', 'Hast du meine Sachen gebügelt? 👗', 'Ich kann ihren Duft jetzt schon riechen. Ich weiß, du kannst es kaum erwarten, mich darin zu sehen! 🥰'),
  ('54999531-d81c-49ad-a8e5-0a766a343a4f', 'Das Wasser in meinem Pool wird weniger ... 💧', 'Ich schwimme so gern in sauberem, reichlich vorhandenem Wasser. Trinkst du mir zuliebe ein Glas Wasser? 🥺'),
  ('2c4aee4a-e8a9-4bb3-96b6-16fd76a9994b', 'Ich prüfe schon mal den Weg! 🔦', 'Mein Kopf zeigt nach unten und ich schaue zum Ausgang. Atme einfach tief durch, alles wird wunderbar!'),
  ('1f094983-199a-44c0-ba29-5474fcd1ba0b', 'Wessen warme Hand ist das? 🖐️', 'Ist das Papa? Wenn ich seine Berührung spüre, werde ich ganz ruhig. Sag ihm, dass ich meine Hand auch aufgelegt habe – gib mir fünf! ✋'),
  ('b4ebdd4a-9196-4b7e-a71f-fdfdc053ec32', 'Ich sammle Kraft! ⚡', 'Ich bewege mich nicht so viel? Keine Angst. Jetzt brauche ich Schlaf. Ich sammle Energie für den großen Tag. Ruh du dich auch aus! 🛌'),
  ('222ef9f4-b496-4bfc-b795-b205f25d7c39', 'Hast du meinen Ellbogen gespürt? 💪', 'Entschuldige, Mami! Ich möchte mich strecken, aber ich habe keinen Platz. Musst du lachen, wenn dein Bauch ganz schief und krumm aussieht? 😄'),
  ('4659f949-94b4-4bda-af43-5053a4d85dd9', 'Watschelst du wie ein Pinguin? 🤭', 'Weil ich tiefer gerutscht bin, hat sich dein Gang verändert. Aber egal, wie du aussiehst oder gehst: Du bist die schönste Mama der Welt! ❤️'),
  ('fa6077ec-5cef-4d3a-887a-ecb99696e48f', 'Hicks... Hicks... 😲', 'Schon wieder habe ich Schluckauf! Ich trainiere mein Zwerchfell. Wenn dein Bauch rhythmisch hüpft, dann weißt du: Das bin ich!'),
  ('ac593045-989b-4db2-a1c0-5cf1b85a8800', 'Waren wir beim Arzt? 👩‍⚕️', 'Wenn das kalte Gel deinen Bauch berührt, kitzelt es mich! 🙈 Aber ich weiß, dass es dich beruhigt, meinen Herzschlag zu hören.'),
  ('f1b0e4ba-30ba-4a1d-82af-0d740c3ae044', 'Wir sind ein Team! 🤝', 'Hab keine Angst, wenn die Wehen einsetzen. Atme tief durch. Gemeinsam schaffen wir das, versprochen!'),
  ('1eaf3d66-fce7-4349-aeaf-3af62fb5c512', 'Ist mein Zimmer fertig? 🧸', 'Schaust du mein Bettchen an und träumst vor dich hin? Ich kann es kaum erwarten, das Kuscheltier zu umarmen, das du hineingelegt hast! 🥰'),
  ('23ae0c73-2d4e-42be-98d5-a256a7fc152c', 'Ich rutsche tiefer – spürst du es? ⬇️', 'Ich senke mich zwischen deine Beckenknochen. Jetzt kannst du leichter atmen, musst aber häufiger zur Toilette! 🤭'),
  ('10bb8281-56bc-44a1-b78e-8cb23edb7f86', 'Mein Immunsystem wird stärker 🛡️', 'Die Antikörper, die ich von dir bekomme, bereiten mich auf die Welt voller Keime vor. Auch deine Muttermilch wird mich schützen, Mami!'),
  ('2e44c870-ae65-48e2-ad71-57a350b34616', 'Wo ist mein erstes Outfit? 👕', 'Hast du die Kliniktasche gepackt? Streichele schon mal den kleinen Strampler, den du mir anziehen wirst ...')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.pregnancy_day_notifications AS x SET title_de = v.t, body_de = v.b
FROM (VALUES
  ('deba1190-6096-4dec-88eb-70e669fb3ccb'::uuid, 'Ich möchte dich sehen! 👀', 'Meine Augen sind geöffnet, aber hier ist es dunkel. Ich zähle die Tage, bis ich dein Gesicht und dein Lächeln sehen kann. Bald ist es so weit! ⏳'),
  ('eff2a55b-f3e4-4d2a-b53a-483716c9d978', 'Meine Haut wird glatt! 🧖‍♀️', 'Mein feiner Flaum verschwindet und meine Fettpolster wachsen. Ich bereite mich auf deine sanften Berührungen vor, Mami. Ich werde ganz weich sein! ☁️'),
  ('586cf1f5-c7b6-4014-aa9e-8da51416de7e', 'Ich reiße meine Augen weit auf! 👀', 'Auch wenn es dunkel ist, beobachte ich alles. Ob ich wohl dir oder Papa ähnlich sehe? Habt ihr schon gewettet? 😄'),
  ('450a79a5-c3df-4f37-ba9e-30274759f7a8', 'Pssst ... Ich schlafe! 😴', 'Mein Gehirn entwickelt sich so rasant, dass ich ganz viel Schlaf brauche. Schlaf doch auch ein bisschen, Mama! 🛌'),
  ('be58ff2d-88eb-4c07-a49c-bb64ed9da351', 'Räumst du zu Hause alles um? 🌪️', 'Du möchtest alles putzen und die Schränke neu ordnen ... Das ist der Nestbautrieb! Aber überanstrenge dich nicht, ich brauche eine ausgeruhte Mama.'),
  ('d4a9673c-e78e-49b9-8680-f5a870142dec', 'Hier wird es ganz schön eng! 🏠', 'Ich möchte mich drehen, aber ich habe keinen Platz. Wenn ich meinen Ellbogen herausstrecke, sieht dein Bauch ganz schief aus. Da musst du bestimmt lachen! 😄'),
  ('ad62dd64-4e59-4e08-8d87-d88f11192fd8', 'Ich brauche Fett! 🥑', 'Avocado, Nüsse oder Olivenöl ... Du kannst mir dabei helfen, schön rundlich zu werden!'),
  ('7ab48424-114b-4f93-bf60-a6a791cf5a3b', 'Dein Herz ist mein Schlaflied ... 💓', 'Mein Kopf liegt unten und mein Ohr ist deinem Herzen jetzt noch näher. Dieser Rhythmus ist die einzige Musik, die mich beruhigt.'),
  ('8bb10475-6f0a-4fa8-839d-6d4d4f784276', 'Stehen die Taschen bereit? 🎒', 'Ich könnte jederzeit „Überraschung!“ rufen. Hast du meine erste Mütze, die du mir anziehen wirst, in die Tasche gepackt? Ich möchte nicht frieren. 🧢'),
  ('884382e7-c971-4251-a601-ff9e5d8d7bc2', 'Das Ziel ist zum Greifen nah! 🏆', 'Die 37. Woche geht zu Ende! Jetzt sind wir in der frühen Terminsphase. Das heißt: Selbst wenn ich heute zur Welt komme, ist meine Lunge bereit zum Atmen!'),
  ('9848ae06-dfd4-4fde-8a6f-3787325bfeb8', 'Ich habe von dir geträumt ... 💤', 'Deine Stimme, dein Duft, deine Wärme ... Ich kann es kaum erwarten, aufzuwachen und dich endlich wirklich zu umarmen, Mama!'),
  ('7461f26e-8ba4-4a54-a57e-84bed4745dfc', 'Ist dein Bauch hart geworden? 🤰', 'Sind das nur Übungswehen oder komme ich schon? Wenn du dir unsicher bist, öffne den Wehen-Timer. Er sagt dir genau, wohin es geht: ins Krankenhaus oder ins Bett?'),
  ('0e2e37ee-dd10-44ae-98a1-2379b737ce2b', 'Ich bin immer noch hier! 👋', 'Ich habe kaum noch Platz, deshalb bewege ich mich weniger. Wenn du dir aber Sorgen machst, öffne den Trittzähler. Lass uns gemeinsam zählen! 🦶'),
  ('0add760f-e392-4d33-9e33-dd2c593a0a0c', 'Hast du meine Söckchen eingepackt? 🧦', 'Ich möchte nicht frieren, Mama! Überprüfe die Checkliste für die Kliniktasche ein letztes Mal. Ist mein erster Strampler dabei? 🥰'),
  ('c98ad2e9-dab2-435c-b719-03a62f1368f2', 'Du kannst nicht schlafen? 🥺', 'Du findest keinen Schlaf? Komm, lass uns schon jetzt die Geräusche anhören, die du mir nach meiner Geburt vorspielen wirst. Die Rubrik „Weißes Rauschen“ kann uns beide beruhigen. 🌊'),
  ('73f5c761-83f4-4b9c-ab8c-ebbbc23c1ad2', 'Mein Koffer ist gepackt und ich warte an der Tür! 🚪', '38 Wochen! Jetzt bin ich offiziell bereit für die Geburt. Meine Lunge, mein Gehirn – alles ist vollständig entwickelt.'),
  ('b02641e8-c8b3-4941-8bbc-12e86e7720ae', 'Was wirst du tun, wenn deine Fruchtblase platzt? 💦', 'Keine Panik! Lies im Blog den Artikel „Die 3 wichtigsten Anzeichen für den Geburtsbeginn“.'),
  ('8013f167-1549-4b4a-8e28-e01b854ddc4c', 'Ich rutsche tiefer ... ⬇️', 'Ich weiß, dass ich Druck auf dein Becken ausübe. Aber nur so kann ich endlich zu dir kommen. Meine tapfere Mami! ❤️'),
  ('d154d2c7-ec75-47ac-ba69-4fbe92885614', 'Schlaflose Nächte? 🥱', 'Je näher die Geburt rückt, desto schwerer kann es dir fallen, einzuschlafen. So bereitet sich dein Körper auf den Rhythmus mit deinem Baby vor.'),
  ('b3effc18-3aca-4ae1-9929-0aa55b124180', 'Wie schlägt mein Herz? 💓', 'Wenn du mich vermisst, leg deine Hand auf deinen Bauch. Unsere Herzen schlagen im Einklang. Alles ist in Ordnung, wir warten nur noch auf den Tag, an dem wir uns endlich kennenlernen. 🗓️'),
  ('508da239-e1ff-41bc-b69e-7ac41310e57b', 'Trete ich weniger? 🦶', 'Ich habe kaum noch Platz, Mami! Trotzdem solltest du meine Bewegungen spüren. Wenn du unsicher bist, iss etwas Süßes und öffne den Trittzähler.'),
  ('94a030ca-34dd-44fe-9971-596b00948ae5', 'Sind alle Unterlagen eingepackt? 📄', 'Personalausweis, Untersuchungsergebnisse ... Schau ein letztes Mal in deine Tasche. Hast du auf der Kliniktaschen-Checkliste alles abgehakt? ✅'),
  ('8d62f4d6-0c1f-4d76-ad37-4f81f9b3a9c0', 'Schließ die Augen ... 😌', 'Hab keine Angst vor der Geburt. Stell dir einfach den Moment vor, in dem du mich zum ersten Mal in den Armen hältst. Mein Duft wird dich all die Schmerzen vergessen lassen.'),
  ('c87d28dc-caee-4571-989c-8e696b1ae968', 'Zervix (Gebärmutterhals) 🗝️', 'Im Verborgenen tut sich etwas! Der Gebärmutterhals wird weicher, verkürzt sich und öffnet sich. Auch wenn du es nicht spürst, öffnet dein Körper mir bereits die Tür.'),
  ('76e46ae6-114d-4692-9572-4e285ec80590', 'Ist heute der große Tag? 🗓️', '40 Wochen sind geschafft! Laut Kalender ist es heute so weit. Komme ich jetzt oder lasse ich dich noch ein bisschen warten? Ich kann dich jederzeit überraschen! Sei bereit! 🎁'),
  ('98686d18-af97-4647-942d-188f1dec2753', 'Ich bin nicht zu spät! 👑', 'Die Stars betreten die Bühne eben zuletzt, Mami! Ich lasse dich noch ein wenig warten, dann komme ich. Hab Geduld! 😌'),
  ('777b97b8-95e9-4f43-a5c2-c68495d48777', 'Klopf, klopf – ich bin’s! ✊', 'Kommen und gehen die Schmerzen im Bauch? Verliere keine Zeit und tippe auf den Wehen-Timer. Werden die Abstände kürzer, ist der große Tag gekommen! 🚑'),
  ('23425b07-63ff-4191-a065-718ed3a783d1', 'Ist die goldene Milch schon da? ✨', 'Aus deinen Brüsten kann gelbliche Flüssigkeit austreten – sie gilt als der erste natürliche Schutz für dein Baby. Lies in den Blogs mehr über das Stillen. 📖'),
  ('85c5a987-f8eb-414a-99b9-ec981bbc08cd', 'Übungswehen oder echte Wehen? 🤔', 'Wird dein Bauch hart und dann wieder weich? Wenn die Wehen nicht regelmäßig kommen, sind es wahrscheinlich Übungswehen. Öffne den Wehen-Timer und überprüfe es!'),
  ('55b51f8f-337f-485f-a7bb-0d388895d70b', 'Hat sich der Schleimpfropf gelöst? 🩸', 'Wenn zäher Schleim abgegangen ist, beginnt sich der Muttermund möglicherweise zu öffnen. Keine Angst, das ist nur ein Zeichen dafür, dass sich dein Körper auf die Geburt vorbereitet.'),
  ('e3c60e6b-f031-49de-9d1e-df5e6adaec56', 'Platsch! Was war das? 💦', 'Wenn deine Fruchtblase platzt, gerate nicht in Panik. Atme einfach tief durch und informiere deinen Arzt oder deine Hebamme. Ich komme! 🌊'),
  ('a7c9fb31-732f-48c9-869e-cb25de2cc6bf', 'Zeit, den Stress zu vertreiben! 😮‍💨', 'Bist du aufgeregt? Lerne schon jetzt im Bereich Übungen die Atemtechniken für die Geburt. Während der Wehen werden sie dir sehr helfen.'),
  ('e6c910e7-1cd4-4a57-af91-421a76624e12', 'Natürlich nachhelfen 🍍', 'Datteln und Ananas sollen den Gebärmutterhals weicher machen. Füge sie heute deinem Speiseplan im Bereich Ernährung hinzu. 🥗'),
  ('0b2b54c8-9ff4-43bd-80a3-8a3a373a1975', 'Herzschläge ... ❤️', 'Wenn du die 40 Wochen überschritten hast, ist eine KTG-Untersuchung (NST) wichtig, um den Zustand der Plazenta zu überprüfen. Vergewissere dich, dass alles in Ordnung ist.'),
  ('52d95173-f625-471a-8fd4-bc36c2714133', 'Wollen wir Treppen steigen? 🪜', 'Zeig mir den Weg! Treppensteigen oder Kniebeugen können mir helfen, tiefer ins Becken zu rutschen. Schau im Bereich Übungen nach.'),
  ('c54d6aec-cbfd-44de-8deb-f24fc551c345', 'Hier ist es so schön 🌡️', 'Warm, dunkel und gemütlich ... Du wirst mir doch nicht böse sein, wenn ich sage, dass ich nicht rauskommen möchte, oder? 🥺 Nur ein Scherz, ich komme!'),
  ('e0f642a2-57ae-48a0-88a3-c592939d5139', 'Wie schlägt mein Herz? 💓', 'Sind wir gerade beim KTG (NST) in der Arztpraxis? Wie beruhigend es für dich ist, dieses pochende Geräusch zu hören ...'),
  ('a43fd2c0-9279-47da-b7ee-4898765553ab', 'Isst du Datteln? 🌴', 'Für eine natürliche Geburt ist dieser leckere Versuch einen Versuch wert!'),
  ('0247f27e-7ddb-489d-b670-ca491d8ccd50', 'Ich werde immer pummeliger! ⚖️', 'Mit jedem weiteren Tag hier werde ich ein bisschen pummeliger. Meine Bäckchen werden immer süßer, aber für dich wird es anstrengender. Entschuldige! 🙈'),
  ('87267b60-6c8e-4a16-ba93-8c4128e465bd', 'Hast du einen Snack eingepackt? 🍫', 'Nach der Geburt wirst du großen Hunger haben! Pack deine Lieblingskekse oder Schokolade in die Kliniktasche.'),
  ('8ec6da93-6997-4754-83f8-6c1f12fd0335', 'Altert die Plazenta? 🍂', 'Kontrolliert der Arzt die Fruchtwassermenge? Solange ich noch mit Sauerstoff versorgt werde, ist alles in Ordnung. Es sind einfach unsere letzten Tage hier.'),
  ('5b55999e-5ad0-4f78-afa8-f94623d8adca', 'Hast du nachts Wehen bekommen? 🌙', 'Dieser Schmerz, der dich aus dem Schlaf weckt ... Sind das echte Wehen? Verliere keine Zeit und starte den Wehen-Timer. Vielleicht ist heute Nacht DIE NACHT! 🚑'),
  ('1f7612ce-6ffd-41c2-b5d1-de2a40214c65', 'Ist der Räumungsbefehl da? 📢', 'Der Arzt spricht von einer Geburtseinleitung? Hab keine Angst. Das Wichtigste ist, dass ich gesund und sicher in deine Arme komme. Auf welchem Weg, spielt keine Rolle!'),
  ('4f2c691b-071d-4e41-bb69-0e7f415e73df', 'Dein letztes Schwangerschaftsfoto ... 📸', 'Sieh dir diesen Bauch noch ein letztes Mal an. Morgen liege ich vielleicht schon in deinen Armen. Sei stolz auf deinen wundervollen Körper, Mami!')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_de = v.t, body_de = v.b
FROM (VALUES
  ('0ed5afeb-bfa9-4fba-a6c1-40d487f8789c'::uuid, 'Der Saugreflex deines Babys ist sehr stark! 🍼', 'Stoppe bei jeder Mahlzeit die Zeit, um sicherzustellen, dass dein Baby ausreichend satt wird.'),
  ('da08e82c-f1b1-4615-9a78-803ac91a2d92', 'Bist du ohne ersichtlichen Grund besonders emotional? 😢', 'Das ist völlig normal! Du kannst deine Gefühle mit Anacan AI oder in unserer Community teilen und Unterstützung erhalten.'),
  ('fee5ed13-dd9c-4182-b62b-254289a55cec', 'Hat dein Baby Schwierigkeiten beim Einschlafen? 🎶', 'Aktiviere die Funktion „Weißes Rauschen“ in unserer App, damit dein Baby so tief und geborgen schläft wie im Mutterleib.'),
  ('45b225f1-1304-44c7-93ed-fd6649d6138a', 'Der Nabelschnurrest muss trocken und sauber bleiben. ⏱️', 'Wenn der Nabelschnurrest nass wird, muss er sorgfältig getrocknet und täglich mit der ärztlich verordneten antiseptischen Lösung behandelt werden.'),
  ('a63353e6-5360-4f33-ba4b-ae8f83d9831a', 'Eine vitaminreiche Ernährung ist für Mütter besonders wichtig! 🥗', 'Schau dir unsere gesunden Rezepte an und tanke neue Kraft.'),
  ('e8719824-5aaa-4cf3-a9a0-c265fa3bf36c', 'Dein Baby erkennt dich an deinem Geruch und deiner Stimme! 👃', 'Deshalb wird dein Baby unruhig und fühlt sich unsicher, wenn du den Raum verlässt.'),
  ('3258a482-400c-485d-af7c-ccb221416732', 'Machen dir die nächtlichen Wachphasen zu schaffen? 😴', 'Halte im Stimmungstagebuch fest, wie du dich heute fühlst, und lass dir von Anacan AI hilfreiche Tipps geben.'),
  ('80a2cd79-a6d6-4c87-b540-c42931228485', 'Der Magen deines Babys wird größer. 🍒', 'Trage im Ernährungstracker ein, wie viel dein Baby getrunken hat, und überprüfe die empfohlene Tagesmenge.'),
  ('cdd7b6ae-f340-479e-9d33-221c6775ebb3', 'Wickle dein Baby nicht zu fest, damit es sich frei bewegen kann! 🚫', 'In unseren Blogbeiträgen erfährst du mehr über hilfreiche Informationen und moderne Ansätze.'),
  ('1b82205e-3e0a-48f0-abf7-dac783f4bce8', 'Deine Milch entwickelt sich jetzt zu kalorienreicher reifer Muttermilch. 🥛', 'Starte den Still-Timer und erfasse genau, wie lange dein Baby heute getrunken hat!'),
  ('9a18572b-e386-4df8-ba20-b5eb78b8f99f', 'Wie waren die ersten 10 Tage? 📸', 'Schlaflose Nächte, Ängste, manchmal Tränen und ein überwältigendes Gefühl der Liebe... Die ersten 10 Tage – und damit die schwierigste Anfangszeit – liegen nun hinter dir! Du bist großartig.'),
  ('ffd7ff0c-bf80-4552-8a28-8d30f0674b07', 'Nimm dir heute wenigstens 15 Minuten nur für dich. 🛁', 'Gönn dir eine warme Dusche und verwöhne dich mit den gesunden Rezepten in der App.'),
  ('1af46170-3a5b-41ea-bb18-ce899698f996', 'Alles Gute zum ersten Tag! 🥳', 'Nutze ab jetzt den Timer in der Anacan-App, um den Schlaf- und Ernährungsrhythmus deines Babys im Blick zu behalten.'),
  ('96187549-321c-4f4b-8ab6-e849804b2e3f', 'Ruhe dich aus, während dein Baby schläft! 😴', 'Vergiss nicht, im Stimmungstagebuch festzuhalten, wie du dich heute fühlst.'),
  ('c21d305d-a798-46f7-a57b-5ee7fc159b60', 'Kolostrum ist die erste Impfung! 🤱', 'Dokumentiere die Mahlzeiten ganz einfach mit dem Ernährungstracker in der App.'),
  ('1de2111f-1bc3-4ba2-9e4a-c85aa4453abb', 'Sei nicht traurig, weil du glaubst, zu wenig Milch zu haben! 🥛', 'Der Magen deines Babys ist noch so klein wie eine Kirsche. Deine tägliche Stillstatistik kannst du in der App verfolgen.'),
  ('75f8bf1f-a1b6-48ed-8282-db88f2b4b621', 'Nimm dir Zeit für dich. 💆‍♀', '️ Deine Gebärmuttermuskulatur bildet sich zurück. Halte deine heutigen Gefühle im Stimmungstagebuch fest und gönn dir etwas Entspannung.'),
  ('ee814c6a-2fd2-46fc-a3a3-6fece315052e', 'Die weiße Schicht auf der Haut deines Babys schützt es. 👶 Keine Sorge.', 'Vergiss nicht, jeden Windelwechsel in Anacan zu dokumentieren und die Normwerte zu überprüfen!'),
  ('28500aa6-3ac1-4fd2-a987-e74e0b2bccb8', 'Glaub nicht an den Mythos, dass sich dein Baby ans Tragen gewöhnt! 🤗', 'Kuschelt ganz viel. Das stärkt eure Bindung und regt gleichzeitig deine Milchbildung an.'),
  ('2df49d87-7d2b-44bb-bb5a-a25b24863389', 'Tag und Nacht sind vertauscht? 🛌', 'Behalte den Schlafrhythmus und die täglichen Routinen in der App im Blick – und schließe auch du die Augen, wenn dein Baby schläft.'),
  ('2e317973-be56-4e35-b4da-81c9dc7b1f3d', 'Die Vorsorgeuntersuchungen beginnen. 💉', 'Trage Größe und Gewicht deines Babys in den Entwicklungs-Tracker ein und erstelle eine persönliche Wachstumskurve!'),
  ('6401ca5a-6403-42c9-b967-6741dd863d7c', 'Damit du keine Abstände vergisst, ist der Timer für dich da. 🍼', 'Plane mit Anacan ganz einfach die Zeiten für Windelwechsel und Mahlzeiten.'),
  ('c61401b5-5ca0-4aea-9f3d-ce4b09083a8c', 'Du musst keine Supermama sein! 🦸‍♀', '️ Scheue dich nicht, um Hilfe zu bitten. Motivation findest du in den Artikeln unseres Blog-Bereichs.'),
  ('ded576fe-d3fa-4078-9b83-36eaf5b495d5', 'Verfolge die Entwicklung Schritt für Schritt. 📏', 'Hast du vergessen, Kopfumfang, Größe und Gewicht in den Gewichts-Tracker einzutragen? Hol es jetzt nach.'),
  ('0240c7db-30e2-4d5b-86a4-0b27f230557c', 'In Papas Armen 🫂', 'Die Erschöpfung der ersten Woche steckt dir in den Knochen. Lass das Baby heute Abend auf Papas Brust einschlafen und schalte das Weiße Rauschen ein. Gönn dir währenddessen eine warme Dusche und vergiss hinter geschlossener Tür für nur 15 Minuten unter dem Wasserstrahl alles um dich herum. Du schaffst das.'),
  ('7449500c-dd2f-4529-a9a7-67ddeee4fe31', 'Zeit für Tummy Time (Bauchlage)! 🐢', 'Lege dein Baby, wenn es wach ist, für 1-2 Minuten auf den Bauch, um seine Muskeln zu stärken.'),
  ('74dae015-c762-4d96-ad34-7d706065ef5f', 'Herzlichen Glückwunsch, du bist seit 1 Woche Mama! 🥳', 'Herzlichen Glückwunsch, du bist seit 1 Woche Mama! 🥳 Nutze den Bereich für Baby-Fotoshootings, um ein Erinnerungsfoto an diesen besonderen Tag zu erstellen.'),
  ('7c7a5fbe-09ea-4f4c-a054-883ad490f939', 'Werfen wir einen Blick auf die Auswertung der ersten Woche? 📊', 'Möchtest du in der Anacan App deine wöchentlichen Schlaf-, Windel- und Ernährungsstatistiken ansehen?'),
  ('d06a4b75-fad1-4ee5-9c5c-c70d98373c0c', 'Körperliche Erholung 🩹', 'Dein Körper erholt sich noch, und vielleicht schmerzen auch deine Nähte. Erwarte keine Perfektion von dir.'),
  ('d83a6f20-2dc5-45c9-9550-38fedec5c042', 'Die Darmflora entwickelt sich! 🦠', 'Wenn die Blähungen beginnen, können die Rhythmen im Bereich „Weißes Rauschen“ von Anacan helfen, dein Baby zu beruhigen.'),
  ('092f30cd-002d-4c4e-a83e-0b13c38cc743', 'Der Blick deines Babys wird klarer! 👀', 'Dein Baby kann dein Gesicht jetzt besser erkennen. Halte im Stimmungstagebuch fest, welche Gefühle diese schönen Momente in dir auslösen.'),
  ('20684bd3-d3fb-479e-89f1-9adf84e485af', 'Wie läuft eure Still- und Fütterungsroutine? 🤱', 'Starte den Timer in der App und behalte mit dem Ernährungstracker ganz einfach im Blick, ob dein Baby genug Nahrung bekommt.'),
  ('7797557a-9277-450c-98b3-b0fa58923513', 'Nach dem abendlichen Bad ist Schlafenszeit! 🛁', 'Ein Bad vor dem Nachtschlaf kann deinem Baby helfen, entspannt einzuschlafen.'),
  ('8c6679da-fafd-4f32-9db9-54953d4a08fe', 'Behältst du die tägliche Anzahl der Windeln im Blick? 🧷', 'Die Windeln geben am besten Aufschluss darüber, ob dein Baby genug Nahrung bekommt. Vergiss nicht, jeden Windelwechsel in Anacan einzutragen!'),
  ('bbcb238e-ee32-4e4b-a429-0c4d99613140', 'Analysieren wir den Schlafrhythmus. ⏱️', 'Starte den Schlaf-Timer, sobald dein Baby einschläft, und sieh in der Grafik, ob es täglich genug Schlaf bekommt.'),
  ('c8038ed4-40d8-4c96-b84d-dd22d681496c', 'Lecker und gesund – ideal für Mamas! 🍲', 'Entdecke in unserem Bereich „Gesunde Rezepte“ Gerichte, die dir neue Energie schenken, und achte gut auf dich.'),
  ('2ef0546f-a471-4ef1-833d-3a8427b3c92c', 'Dein Baby wächst schnell! ⚖', '️ Trage sein wöchentliches Gewicht in den Entwicklungstracker ein und verfolge seine gesunde Wachstumskurve in der App.'),
  ('84bd0c91-57d2-4afc-a090-33645f6c3336', 'Hast du eine Frage? 🤖', 'Anacan AI ist auch nachts für dich da! Stelle alle Fragen, die dich beschäftigen, und erhalte sofort Unterstützung.'),
  ('ba7edb24-6da8-4a69-9b59-da2faf81dfa6', 'Eure ersten gemeinsamen Spaziergänge! 🌳', 'Wenn das Wetter schön ist, geht nach draußen. Frische Luft ist jeden Tag sehr wichtig und wohltuend für dein Baby.'),
  ('0d572d8d-fc2a-4534-aab4-0054197f9297', 'Halte den Moment für immer fest! 📸', 'Lade die süßen Momente von heute in das Babyalbum hoch und schaffe Erinnerungen, die dich später zum Lächeln bringen werden.'),
  ('2c1d3bb2-7e3e-4938-89fb-c5a7a19e27a2', 'Die richtige Balance zwischen Schlaf und Ernährung. 📚', 'Hast du schon unseren neuesten Artikel über die Entwicklung von Neugeborenen im Blogbereich gelesen?'),
  ('7bc61271-cc44-4b34-a12b-faa852a23b6c', 'Herzlichen Glückwunsch, dein Baby ist jetzt schon 2 Wochen alt! 🎈', 'Nutze die liebevollen Motive im Bereich Baby-Fotoshooting, um diesen kleinen Meilenstein zu feiern.'),
  ('04916f68-94af-484d-968d-c1e05636c373', 'Zeit für die Hautpflege. 🛁', 'Suchst du nach Cremes, die für die empfindliche Haut deines Babys geeignet sind? Unsere Liste empfohlener Produkte hilft dir dabei.'),
  ('17096c26-bde5-4bba-9013-08a06133ab4f', 'Die Reflexe entwickeln sich! 🖐️', 'Wie fest hält dein Baby deinen Finger? Entdecke unsere Blogbeiträge, um mehr darüber zu erfahren.'),
  ('d935b5ec-1166-4c5b-a013-19977086a00b', 'Dein Tagesbericht ist fertig! 📊', 'Öffne die Anacan-App und sieh dir die heutige Auswertung zu Schlaf, Ernährung und Windelwechseln an.'),
  ('4ad69c28-25c9-4155-a875-498e8858786c', 'Wir verfolgen die Entwicklung! 📏', 'Der nächste Monat rückt näher. Öffne in der App den Bereich „Entwicklungstracker“ und vergewissere dich, dass deine Angaben aktuell sind.'),
  ('58f18841-d6c8-49e1-84e7-3ca2b96787a6', 'Ihr seid schon seit 20 Tagen zusammen! 🥰', 'Du bist eine großartige Mama! Halte diesen Tag mit dem Baby-Fotoshooting-Tool als wunderschöne Erinnerung fest.'),
  ('e9631c46-1105-44f2-b850-b1671ee6df45', 'Heute zählen nur positive Gefühle! ✨', 'Öffne dein Stimmungstagebuch und halte den Moment fest, in dem dein Baby dich am meisten zum Lachen gebracht hat. Anacan AI hört dir zu!'),
  ('78429eb3-1c37-4e59-ba1f-884cf298f9f6', 'Manchmal kann das Füttern etwas länger dauern. 🍼', 'Nutze den Timer, um den Ablauf zu analysieren. Hauptsache, du und dein Baby fühlt euch wohl.'),
  ('ade4c5f5-2712-4328-ae1d-961b6a95f615', 'Wie fühlst du dich? 🧘‍♀', '️ Muttersein ist wunderschön, kann aber auch anstrengend sein. Öffne das Stimmungstagebuch und halte fest, wie du dich heute fühlst.'),
  ('da011889-3632-43ce-aa11-c46cc9ffe260', 'Was fehlt noch für die Babypflege? 🧴', 'Im Bereich „Empfohlene Produkte“ findest du Artikel, die andere Mütter getestet und für gut befunden haben.'),
  ('515f484e-8ce4-4442-bca4-24b38a77b194', 'Windelwechseln gehört jetzt zur Routine! 👶', 'Trage die täglichen Urin- und Stuhlausscheidungen im Windel-Tracker ein, um die Gesundheit deines Babys im Blick zu behalten.'),
  ('76b75bd8-766d-4f01-b3d1-e6a56e5ad949', 'Auch Mama braucht eine Pause! 🛋', '️ Wenn du den Schlafrhythmus deines Babys mit dem Timer erfasst hast, bist jetzt du an der Reihe. Gieß dir eine Tasse Tee ein und entspann dich.'),
  ('7e8ac4ba-1fc8-4ac4-92f2-b519b8fbd60b', 'Hat dein Baby Blähungen? 🌪️', 'Keine Panik. Massiere sanft seinen Bauch und spiele im Hintergrund Weißes Rauschen ab, um es abzulenken.'),
  ('228ed9a7-6c09-4e18-b632-934b4149caf5', 'Zeit für die Bauchlage! 🐢', 'Schon ein paar Minuten täglich in Bauchlage stärken die Nackenmuskulatur deines Babys.'),
  ('b42303f7-3c77-46e1-97e5-9a1b1e60430c', 'Vorbereitung auf den Nachtschlaf. 🌙', 'Reguliere vor dem Schlafengehen die Raumtemperatur und starte den Schlaf-Timer von Anacan.'),
  ('f833f5dd-8e28-4c1e-a3cb-e9f3a3133ca5', 'Tipps für mehr Muttermilch! 🥛', 'Im Bereich für gesunde Rezepte erwarten dich natürliche Lebensmittel und Smoothie-Rezepte, die die Milchbildung unterstützen.'),
  ('403b119e-e637-45fc-b072-cf84725abb35', 'Vielleicht steckt ein Entwicklungsschub dahinter. 📈', 'Dein Baby schreit und weint scheinbar ohne Grund? Der Entwicklungsschub in der 3. Woche fällt oft mit dem Höhepunkt der Blähungen und Bauchkrämpfe zusammen. Keine Panik.'),
  ('844e0b7f-c62a-4e7b-b863-965ea3061be3', 'Mit Baby im Arm ans Sofa gefesselt 🛋️', 'Dein Baby wacht auf und weint, sobald du es ablegst? Heute fühlst du dich vielleicht mit deinem Baby im Arm zu Hause gefangen. Aber vergiss nicht: Für dein Baby ist dein Arm der sicherste Ort. Hab Geduld.'),
  ('f3dc49b8-e32b-422e-80b3-e76c0488dc0f', 'Beziehe auch deinen Partner mit ein. 👨‍👩‍👦', 'Überlasse ihm heute Abend das Windelwechseln oder das Einschlafen mit Weißem Rauschen und gönn dir eine Pause.'),
  ('77ad5a07-cc0a-4fb4-b323-d177412300b1', 'Deine Wochenstatistik ist fertig! 📊', 'Öffne die App, um zu sehen, wie gut du dich in den letzten Tagen an die Schlaf- und Ernährungsempfehlungen gehalten hast.'),
  ('8fac7e6d-3d63-4646-99a7-c927a088e849', 'Frische Luft macht Appetit! 🌳', 'Achte darauf, jeden Tag mit deinem Baby nach draußen zu gehen. Das tut sowohl dir als auch deinem Baby sehr gut.'),
  ('dd0fbf42-9f2a-4cb9-8c66-db4c46ee2124', 'Verbessere die Qualität deiner Muttermilch. 🍲', 'Entdecke im Bereich „Gesunde Rezepte“ der App, wie du dich gesund und lecker ernähren kannst.'),
  ('15d59560-fd44-4273-9de7-62fd70c1a0dd', 'Die Werte für den ersten Monat! 📏', 'Trage die aktuellen Größen- und Gewichtsdaten im Entwicklungstracker ein und freu dich über die gesunde Wachstumskurve.'),
  ('22b47ac3-665d-4f67-b497-67efe6238be4', 'Herzlichen Glückwunsch, wir sind schon 1 Monat alt! 🥳', 'Erstelle im Bereich „Baby-Fotoshooting“ schöne Bilder, um diesen großen Tag zu feiern.'),
  ('ed8acfc1-dd31-48da-a8f2-04bd91f60de7', 'Sei stolz auf dich! 💖', 'Du hast den ersten und schwierigsten Monat gemeistert. Öffne dein Stimmungstagebuch und halte fest, was du diesen Monat Großartiges geleistet hast.'),
  ('1961895f-8e5d-4529-9dd1-eba3d3c72045', 'Zeit für einen Entwicklungsschub! 📈', 'Dein Baby kann jetzt häufiger hungrig sein. Verfolge seine Mahlzeiten mit dem Still- und Fütterungstimer.'),
  ('2450c51d-55f8-4e27-b691-cd2f503d7dd4', 'Wird dein Baby abends unruhiger? 🎶', 'Dahinter können Blähungen oder Müdigkeit stecken. Beruhige es mit den Naturklängen im Bereich „Weißes Rauschen“.'),
  ('43caac7d-8fec-4815-a021-c436856ae779', 'Schon genau 3 Wochen alt! 🎉', 'Halte diesen süßen Meilenstein fest: Nutze den Bereich „Baby-Fotoshooting“ und verewige einen zauberhaften Moment.'),
  ('2421fc4d-6878-4078-87b3-b7d35e8743ea', 'Vergiss dich selbst nicht! 🥗', 'Deine Gesundheit ist auch für die Gesundheit deines Babys wichtig. Wähle aus den gesunden Rezepten für Frauen einen Snack aus, der dir neue Energie schenkt.'),
  ('4600773a-c43e-4163-a5da-2b2294833f5c', 'Ausreichend Schlaf pro Tag ist wichtig. 😴', 'Starte den Schlaftimer, wenn dein Baby einschläft, und prüfe, wie gut es sein tägliches Schlafbedürfnis erfüllt.'),
  ('bd3843ff-7d20-45e7-9e12-a76db028322e', 'Es versucht, sein Köpfchen zu heben! 🐢', 'Nimm die Bewegungen deines Babys in Bauchlage (Tummy Time) als Video auf und füge sie dem Babyalbum hinzu.'),
  ('592aca51-491e-44f3-b426-3734a638d0f9', 'Hast du eine Frage? 🤖', 'Bei Fragen, die dich beschäftigen, wie „Warum wacht mein Baby nachts so oft auf?“, ist Anacan AI jederzeit für dich da.'),
  ('70951e1d-e161-4f61-adb6-2b3b015c6f79', 'Wie sieht es heute mit den Windeln aus? 🧷', 'Anhand der Windelwechsel kannst du am einfachsten erkennen, ob dein Baby genug Nahrung bekommt. Trage sie jetzt in der App ein!'),
  ('9b230269-a517-40c2-a23b-f2bd57a211d4', 'Das erste Lächeln rückt näher! 😊', 'Verpasse nicht die Momente, in denen dein Baby dein Gesicht aufmerksam betrachtet. Halte im Stimmungstagebuch fest, welche Gefühle diese Augenblicke in dir auslösen.'),
  ('6b6f1411-38ea-47b2-b82b-7ec0af1fa9ed', 'Zeit für eine feste Routine! 🌙', 'Bade und stille dein Baby jeden Tag zur gleichen Zeit, spiele Weißes Rauschen ab und starte den Einschlaftimer.'),
  ('b2ff3f80-95a8-44a7-96b9-573095f4b7ba', 'Vergiss deine Bedürfnisse als Mutter nicht. 🛍', '️Brustwarzencreme und Stilleinlagen bieten Schutz und sorgen dafür, dass du dich wohler fühlst.'),
  ('ef4b3736-bd78-46e0-af19-3bceb15bf443', 'Zeit für einen Spaziergang an der frischen Luft! ☀️', 'Suchst du einen kinderfreundlichen Ort, an dem du dich entspannt erholen kannst? Dann wirf unbedingt einen Blick auf unseren Blog über still- und familienfreundliche Orte.'),
  ('2037f6e8-905d-4847-8172-fdba3ba09cf5', 'Die Abendroutine gerät durcheinander? 🌙', 'Keine Sorge. Wähle unter „Weiße Geräusche“ den Herzschlag aus, damit sich dein Baby so geborgen fühlt wie im Mutterleib.'),
  ('63fcc8ee-0343-4d14-8f0d-e6d98a5377e8', 'Manchmal brauchen wir einfach eine Pause. ☕', 'Aktiviere den Schlaf-Timer, während dein Baby schläft, und gönn dir etwas Ruhe.'),
  ('b61a8e62-d1c0-449f-9d5b-6bb72079c512', 'Die Wachphasen werden länger. ⏱️', 'Lies die Spielideen im Bereich „Blogs“, um mit deinem Baby zu spielen und seine Entwicklung zu fördern.'),
  ('111e6f27-8aef-4cfb-a5ab-60fea52474e0', 'Vorbereitung auf den nächsten Monat. 🛒', 'Wenn du nach passenden Windeln und Pflegeprodukten für den neuen Monat suchst, helfen dir unsere Produktempfehlungen garantiert weiter.'),
  ('713d2aac-0316-483d-9c46-781631bb7e21', 'Du bist eine großartige Mama! ✨', 'Ihr seid nun schon seit 30 Tagen zusammen. Füge dem Babyalbum eine Collage hinzu, die den Unterschied zwischen dem ersten Tag und heute zeigt.'),
  ('ef07a5ff-817b-4b0a-ad2a-706e799bad22', 'Ein neuer Monat, ein neues Kapitel. 📊', 'Sieh dir die monatlichen Statistiken zu Ernährung, Schlaf und Windeln an und entdecke, wie wunderbar du den Tagesrhythmus deines Babys gestaltet hast!'),
  ('498afb20-12cf-4e99-872a-93ae66ffadf8', 'Lies und lerne, wann immer du Zeit findest. 📚', 'Im Bereich „Blogs“ warten die hilfreichsten Artikel über die Entwicklung und Pflege von Neugeborenen auf dich.'),
  ('a1d43ae2-7007-4910-b05d-6c1d71529cf9', 'Die erste Monatsuntersuchung steht bald an. ⚖️', 'Vergewissere dich, dass du die bisherige Gewichts- und Größenentwicklung deines Babys im Bereich „Entwicklungstracker“ eingetragen hast.'),
  ('eabf6802-121e-4850-8036-ab2dbabaf84e', 'Hab keine Scheu, deine Gefühle festzuhalten. 📝', 'Müde oder glücklich? Ganz gleich – trage deine heutigen Gefühle in dein Stimmungstagebuch ein und erleichtere dir damit den Alltag.'),
  ('2b4adff1-6ebf-471c-9dc4-e4e39cc16323', 'Immer aufmerksamer! 👀', 'Dein Baby kann Schwarz-Weiß-Kontraste jetzt besser erkennen.  Denk daran, bei der Bauchlage Kontrastkarten zur visuellen Förderung zu verwenden.'),
  ('5e1b47e3-2994-433f-a7c8-b1e6a121de30', 'Hast du vergessen, mit welcher Brust du gestillt hast? 🤱', 'Halte mit dem Timer fest, ob du mit der rechten oder linken Brust gestillt hast – der Ernährungstracker merkt sich alles für dich!'),
  ('8152dc55-7f72-41b2-bb12-02cf7745f75a', 'Auch die Väter werden einbezogen! 👨‍🍼', 'Im Partnermodus können auch Väter die Entwicklung des Babys mitverfolgen.'),
  ('5bfad78e-cb6a-405d-8517-a356018909ca', 'Wie entwickeln sich Größe und Gewicht? 📏', 'Trage im Bereich „Entwicklungstracker“ neue Werte ein und analysiere die individuelle Entwicklungskurve.'),
  ('d87d1938-6445-47b1-b0eb-19c7a9941726', 'Auf der Suche nach frischer Luft! 🌳', 'Wähle für einen entspannten Spaziergang mit deinem Baby einen Ort in der Nähe aus, der mit dem Kinderwagen zugänglich ist.'),
  ('fa1d2aaa-c80f-46e8-82ed-6c8fa2ce54f1', 'Anacan AI ist immer für dich da! 🤖', 'Hast du Fragen zum Schlafrhythmus? Schreib unserer künstlichen Intelligenz – sie antwortet dir sofort.'),
  ('0ac0ad4d-776b-416d-a345-c0bddd639ff1', 'Die Konzentrationsfähigkeit verbessert sich! 👀', 'Beobachte, wie dein Baby Gegenstände im Raum mit den Augen verfolgt. In den Blogbeiträgen erfährst du mehr über seine Entwicklung.'),
  ('1a8980b4-ba5e-4179-adce-580423431a55', 'Es ist wichtig, den normalen Schlafbedarf zu kennen. ⏱️', 'Starte den Schlaf-Timer, wenn dein Baby einschläft, und prüfe, ob es seinen täglichen Schlafbedarf erreicht.'),
  ('c7ce3717-a6e8-4d86-ba21-d6964fb4fd5f', 'Mamas brauchen Energie! 🍳', 'Tanke neue Kraft mit einem leckeren, einfach zuzubereitenden Smoothie aus unseren gesunden Rezepten.'),
  ('041b2f2c-3594-4ff1-96a1-f589206d267b', 'Stillen und Pausen. 🤱', 'Optimiere eure Routine, indem du die Dauer jeder Stillmahlzeit mit dem Ernährungstracker misst.'),
  ('bae9c6f0-b7fe-4fe9-ba7a-7ba60aceb9ec', 'Wie geht es dir, liebe Mama? 💖', 'Manchmal kann einem alles über den Kopf wachsen. Öffne dein Stimmungstagebuch und schreib dir alles frei von der Seele.'),
  ('cb8cc6b6-0d64-4498-81ae-bc15f03ad73b', 'Besondere Pflege für die Haut deines Babys. 🧴', 'Entdecke in unserem Blog „Empfohlene Produkte“ die von Müttern ausgewählten besten Pflegeprodukte für seine samtweiche Haut.'),
  ('47a30b46-d385-4b3c-979c-5465d481ef29', 'Bewegung gegen Blähungen! 🚴', 'Lass im Hintergrund Weißes Rauschen laufen, während du mit den Beinchen deines Babys Fahrradbewegungen machst – so hat es Spaß und kann sich gleichzeitig entspannen.'),
  ('a7868664-8e30-4849-9648-70deec39cf3a', 'Der Entwicklungsschub in der 6. Woche steht bevor! 📈', 'Dein Baby könnte mehr weinen als sonst. Im Bereich „Blogs“ erfährst du mehr über diese Entwicklungsphase und ihre Ursachen.'),
  ('ba4d5548-5eb3-44e1-bb68-bbab9deb11ee', 'Zeit für gemeinsame Babypflege mit Papa. 👨‍🍼', 'Überlass Papa nach der abendlichen Mahlzeit das Bäuerchen, während du ein kurzes Nickerchen machst.'),
  ('282baeb2-eb26-44cb-9eff-2eb2d88677a2', 'Lass die Müdigkeit des Tages hinter dir. 🛁', 'Nimm dir Zeit für dich und entspanne dich, indem du deine heutigen Gefühle in dein Stimmungstagebuch einträgst.'),
  ('5366cee2-8491-4a45-8d5c-88d78aa6eee0', 'Jetzt sind wir schon im 2. Monat! 🎊', 'Sprich tagsüber mit deinem Baby, um seine Entwicklung zu fördern.'),
  ('c5b12eaa-4012-417b-bf89-d5bd9d26aee9', 'Der Trinkrhythmus kann sich verändern. 🍼', 'Starte den Anacan-Timer, um den Appetit deines Babys zu beobachten und seine tägliche Trinkmenge zu überprüfen.'),
  ('24927359-7877-4f99-9dea-0460583a0880', 'Behalte die täglich benötigten Windeln im Blick. 🧷', 'Erfasse weiterhin jeden Windelwechsel in Anacan, um sicherzugehen, dass dein Baby genug Nahrung bekommt.'),
  ('77d01c80-0ffb-4089-a192-db04bf909aa1', 'Hat dein Baby Schwierigkeiten einzuschlafen? 🌙', 'Wähle bei den Weißen Geräuschen das Rauschen der Meereswellen aus und ruhe dich ebenfalls aus, während dein Baby tief und fest schläft.'),
  ('afe3841b-76da-4cfe-9cf7-b2077153f607', 'Die ersten Gurrlaute sind zu hören! 🗣️', 'Ahme die Laute deines Babys nach und sprich mit ihm, um seine Sprachentwicklung zu fördern.'),
  ('22e06076-dd91-4e1b-834c-b78c42879a13', 'Auch unterwegs ganz entspannt. ☕', 'Du planst ein Treffen mit Freunden? Schau vor dem Losgehen auf unsere Karte mit mama­freundlichen Orten.'),
  ('367f3154-4760-43d6-b507-b914372b7538', 'Mach dich bereit für ein Lächeln! 😊', 'Das erste soziale Lächeln kann jeden Moment kommen. Halte dein Handy bereit.'),
  ('56603835-e00b-48c0-82ab-bbdf1844d6ac', 'Eine feste Routine verbessert die Schlafqualität. 🛁', 'Bade und stille dein Baby, starte den Schlaftimer und verfolge den täglichen Schlaf direkt in der App.'),
  ('173da4aa-4d6e-4106-ab0c-34773a383b02', 'Die Bauchlage klappt immer länger! 🐢', 'Dein Baby kann seinen Kopf jetzt schon aufrechter halten. Baue diese Übungen zur Stärkung der Nackenmuskulatur in euren Tagesablauf ein.'),
  ('3c5122e2-a92c-4444-baa3-d7b7fdd4786f', 'Schauen wir uns deine Windelstatistik an? 📊', 'Öffne die Anacan App und vergleiche die Windeldaten der letzten Tage. Ist alles in Ordnung?'),
  ('f653426f-c687-4b5c-806e-74f597e75cf2', 'Damit du sicher sein kannst, dass alles in Ordnung ist. 🤖', 'Du kannst Anacan AI jederzeit nach allem fragen, was dich beschäftigt – sogar nachts.'),
  ('2a04ee0c-770e-425b-8987-e6ab25472f0b', 'Natürliche Wege, die Milchbildung anzuregen. 🥛', 'Probiere für mehr Milch die nahrhaften Suppen- und Getränkerezepte im Bereich Gesunde Rezepte aus.'),
  ('6a605601-9da6-47e9-8d07-a1f552eb5fc0', 'Die tägliche Balance zwischen Ernährung und Schlaf. ⚖', '️ Analysiere deine heutigen Daten in den Übersichten zur Ernährung und zum Schlaf und plane den nächsten Tag.'),
  ('756d2914-ecb6-4838-adb6-d312a4bc59a2', 'Es entdeckt seine Hände! 👐', 'Dein Baby kann seine Hände jetzt zum Mund führen.'),
  ('2dcd9888-3b4b-4cb6-a25a-51c4642e3c54', 'Heute sind die ersten 40 Tage geschafft! 🧿', 'Mach diesen besonderen, traditionellen Tag unvergesslich: Wähle im Bereich Baby-Fotoshooting schöne Themen aus und gestalte einzigartige Bilder.'),
  ('92e4d1aa-c4f4-477c-ab81-176ef4f03a16', 'Sanft in den Schlaf finden. 🌙', 'Dunkle am Ende dieses besonderen Tages das Zimmer ab, schalte Weißes Rauschen ein und schlummere friedlich, während dein Baby in einen tiefen Schlaf findet.'),
  ('ba92608f-780e-4381-a0e7-3f6af86021be', 'Wie fühlst du dich? ✨', 'Du hast eine lange und besondere Zeit von 40 Tagen gemeistert! Du bist eine echte Heldin!'),
  ('6dd4f975-8504-4871-83c4-a6f7bc24a950', 'Wie war dein Tag heute? 📝', 'Gönn dir einen Kaffee und entspanne dich, indem du deine heutigen Gefühle im Stimmungstagebuch festhältst.'),
  ('c6c2469c-d36e-4ffe-a532-bee6050f4bac', 'Ein neuer Abschnitt nach den ersten 40 Tagen! 🌸', 'Dein Baby interessiert sich immer mehr für seine Umgebung. Lernkarten in seiner Nähe fördern seine Entwicklung.'),
  ('d647162e-98ae-41c0-81b4-cc5ca3e15dff', 'Wie läuft eure Ernährungsroutine? 🍼', 'Prüfe mit dem Ernährungstracker und dem Timer in der App, wie gut ihr euer Tagesziel erreicht.'),
  ('06dbea83-4e3d-4be5-8968-0961033df8d5', 'Es erkennt Farben immer besser! 🔴', 'Beobachte, wie dein Baby leuchtende Gegenstände im Zimmer mit den Augen verfolgt.'),
  ('295afbf2-1104-44c2-abf4-fb0e41a0ff0e', 'Frische Luft tut euch beiden gut. 🌳', 'Wähle auf der Karte „Mama-freundliche Orte“ einen Ort für euren Spaziergang aus, der mit dem Kinderwagen gut zugänglich ist.'),
  ('9f7dfdf1-83be-4fad-a93a-817e105844ce', 'Erleichtere deinem Baby das Einschlafen. 🌙', 'Wähle nach dem abendlichen Bad bei den Weißen Geräuschen das Geräusch eines Föhns oder Regens aus, um dein Baby auf einen tiefen Schlaf einzustimmen.'),
  ('431cbe5a-0f52-442d-a6e8-ab53cd482a5f', 'Deine Tagesstatistik ist da! 📊', 'Sieh dir die Diagramme in der App an, um zu erfahren, wie lange dein Baby heute geschlafen und wie viel es getrunken hat.'),
  ('c4adf9ce-d711-4011-af60-94f404f59ae5', 'Behalte Größe und Gewicht im Blick! 📏', 'Aktualisiere die neuesten Werte im Bereich „Entwicklungstracker“ und freue dich über die gesunde Entwicklungskurve.'),
  ('ffb18a7a-0d53-482c-b130-00223f89efd3', 'Energie für Mamas! 🥗', 'Wähle zur Stärkung aus den gesunden Rezepten für Frauen in der App eine vitaminreiche und leckere Mahlzeit aus.'),
  ('40712cc0-bb4b-4d42-9a36-7942cb47a970', 'Dein Baby reagiert immer stärker auf Geräusche! 🎶', 'Merkst du, wie es sich beruhigt, wenn es deine Stimme hört? Halte diese süßen Momente im Babyalbum für immer fest.'),
  ('aa025645-c5cd-4f2b-840e-6fb50bb6398b', 'Zeit zum Einkaufen? 🛍', '️Sieh dir unsere Liste empfohlener Produkte an – dort findest du Pflegeartikel und Spielzeug, die zum neuen Lebensmonat deines Babys passen.'),
  ('c6ae0bdf-11e6-43d9-a0ab-d021b7461194', 'Zähle weiterhin die Windeln! 🧷', 'Dokumentiere die täglichen Windeln in Anacan, um sicherzugehen, dass dein Baby ausreichend Nahrung bekommt.'),
  ('4c289cf6-60de-4ba6-9f14-eae4086d8d21', 'Die Abstände richtig planen. 🍼', 'Verfolge die Fütterungszeiten und Abstände mit dem Fütterungs-Tracker und finde so den idealen Rhythmus für dein Baby.'),
  ('7f93cf2f-abf0-4b16-9f93-396050a7ddb9', 'Hast du noch Fragen? 🤖', 'Mein Baby hat heute wenig geschlafen – ist das normal? Stelle deine Fragen anderen Müttern in der Community.'),
  ('c505d849-65c8-4ead-80b3-2648f5feaa49', 'Zeit für die Bauchlage! 🐢', 'Dein Baby kann seinen Kopf jetzt schon länger aufrecht halten. Wiederholt diese Übungen täglich, um seine Nackenmuskulatur zu stärken.'),
  ('65d67a55-0ffc-4c5f-8c78-443c16c7f697', 'Beziehen wir auch die Papas mit ein. 👨‍🍼', 'Überlasse dem Papa nach der abendlichen Fütterung das Bäuerchen und Zubettbringen und nimm dir etwas Zeit für dich.'),
  ('c7ab2e50-8e71-4df1-97cc-6432f40c4349', 'Immer mehr Lächeln! 😍', 'Verpasse nicht diesen magischen Moment, wenn dein Baby dich ansieht und fröhlich gluckst! Mach ein Foto und gib ihm einen besonderen Platz im Babyalbum.'),
  ('dba00752-8e14-4710-8793-6a828172c915', 'Kaffeepause mit Freundinnen? ☕', 'Entdecke unter den kinderfreundlichen Orten gemütliche Cafés in deiner Nähe, die du gemeinsam mit deinem Baby besuchen kannst.'),
  ('99125d76-b832-4f75-8c29-6320b71e5e67', 'Entwicklungsschub in der 6. Woche! 📈', 'Heute kann dein Baby etwas fordernder sein. Keine Sorge, wende dich für Unterstützung an Anacan AI.'),
  ('9f56ae7d-2431-4cb2-8d79-fa19be16c242', 'So werden nächtliche Wachphasen zur Routine. 😴', 'Schalte nicht jedes Mal das Licht ein, wenn dein Baby aufwacht. Nutze den Anacan-Timer zum Füttern und hilf ihm anschließend mit Weißem Rauschen, wieder einzuschlafen.'),
  ('bef1515a-3c39-4799-b9d9-717742d94d5f', 'Ruhe dich aus, während dein Baby schläft. ⏱️', 'Aktiviere den Schlaftimer und schließe ebenfalls die Augen oder lies ein Buch, solange dein Baby schläft.'),
  ('3deddca7-0eae-4a46-a2c9-5a8e2ac8b32c', 'Die ersten Gurrlaute werden immer häufiger! 🗣️', 'Halte fest, wie dein Baby versucht, mit dir zu sprechen. Wähle im Bereich für Baby-Fotoshootings einen passenden Rahmen für diesen Moment aus.'),
  ('48e4fdbb-6f6b-4c2d-90c9-ebe6d10f8179', 'Lebensmittel, die deine Milchbildung unterstützen. 🍲', 'Gönn dir im Bereich „Gesunde Rezepte für Frauen“ milchbildungsfördernde Suppen und Getränke.'),
  ('bcfe1987-8bea-4b53-a1dc-7ef7e234e755', 'Achte auf deine Gefühle. 💖', 'Muttersein kann anstrengend sein. Öffne das Stimmungstagebuch, schreibe auf, was dich heute beschäftigt, und erleichtere dir damit das Herz.'),
  ('503a0808-7061-4b7d-ae17-f65b9abb87de', 'Verfolge die Entwicklung Schritt für Schritt. 📚', 'Lies unseren neuesten Artikel im Bereich „Blogs“, um zu erfahren, welche Fähigkeiten Neugeborene in diesem Monat entwickeln.'),
  ('aeea52a4-dd88-4cf1-a812-0c13b4f98004', 'Täglicher Schlafbedarf. 🛌', 'Starte den Schlaf-Timer, wenn dein Baby einschläft, und prüfe, ob es seinen täglichen Schlafbedarf von 14-17 Stunden erreicht.'),
  ('c86bd995-9231-4eae-b8e0-8f84d6a46b62', 'Du bist so stark! ✨', 'Auch wenn es manchmal schwer ist: Du bist eine wundervolle Mama!'),
  ('8e6d5e26-758c-4169-81b6-bd9cbcc10cc5', 'Ein süßer Abschluss für einen schönen Tag. 🌙', 'Dimme das Licht im Zimmer, spiele unter „Weißes Rauschen“ die Geräusche aus dem Mutterleib ab und sieh zu, wie dein Baby friedlich einschläft.'),
  ('9d97fdbc-edef-4830-93ad-c388f586d909', 'Ihr seid seit genau 50 Tagen zusammen! 🎈', 'Feiere dieses wundervolle Jubiläum, indem du mit dem Tool „Baby-Fotoshooting“ ein besonderes Bild erstellst!'),
  ('cb1a5cad-e167-45a8-b0b1-4e8ebe455866', 'Auswertung der letzten 50 Tage. 📈', 'Sieh dir den Entwicklungs-Tracker und die Ernährungskontrolle an und entdecke, wie wunderbar dein Baby in diesen 50 Tagen gewachsen ist.'),
  ('10f8db02-014b-4a08-8d7a-e5cbbb260125', 'Übergang in den Tiefschlaf. 😴', 'Wähle unter den Weißen Geräuschen das Föhngeräusch aus. Während dein Baby friedlich schläft, kannst du deine Gefühle im Stimmungstagebuch festhalten und zur Ruhe kommen.'),
  ('2cd12a68-4486-435f-ad24-55a11a2f62a2', 'Tägliche Ernährungsanalyse. 🍼', 'Miss mit dem Timer in der App die Stilldauer und überprüfe im Bereich Ernährungskontrolle, ob sie im empfohlenen Bereich liegt.'),
  ('b67a89c9-d8cf-40c2-97a2-43b27081ed44', 'Das Blickfeld wird größer! 👀', 'Dein Baby kann Gegenstände jetzt besser mit den Augen verfolgen.'),
  ('917836b6-b023-4945-8e64-bc144ba97f42', 'Dein Baby entdeckt neue Laute! 🗣️', 'Halte seine süßen Brabbellaute fest. Lies die Blogbeiträge, um mehr über die Sprachentwicklung zu erfahren.'),
  ('d31b874f-e957-475e-a461-b294c96db59f', 'Wacht dein Baby nachts weiterhin auf? ⏱️', 'Erfasse jedes Aufwachen mit dem Schlaftimer, um den gesamten Schlafrhythmus und den täglichen Schlafbedarf zu analysieren.'),
  ('d491dc2d-f6b9-49dd-8461-5cbffee476e5', 'Vergiss dich selbst nicht! 🥗', 'Die Energie einer Mutter ist besonders wichtig. Wähle aus den gesunden Rezepten für Frauen eine vitaminreiche Mahlzeit aus und tanke neue Kraft.'),
  ('0c1e843a-b2dc-4995-89cf-7af4230d574e', 'Entdeckt seine Hände! 👐', 'Dein Baby betrachtet jetzt seine Finger und steckt sie in den Mund.'),
  ('3cf29d40-9703-4e58-8a17-b7e68f86c3fa', 'Auf der Suche nach Pflegeprodukten oder Spielzeug? 🧸', 'In unserer Liste empfohlener Produkte findest du ganz einfach sichere Produkte, die die Entwicklung deines Babys fördern.'),
  ('e6e49938-5987-45e7-8021-a8d016100be4', 'Wie fühlst du dich? 💖', 'Warst du den ganzen Tag müde oder voller Energie? Öffne das Stimmungstagebuch und halte fest, wie dein Tag war.'),
  ('814305c3-77b7-491e-ae0f-134875923d1a', 'An welcher Seite hast du gestillt? 🤱', 'Der Anacan-Timer merkt sich für dich, ob du an der rechten oder linken Brust gestillt hast. Starte jetzt die Stillzeit!'),
  ('910b6936-83b0-441d-abe5-33c85153dffe', 'Ein Lächeln am Morgen! 😊', 'Sein soziales Lächeln macht den Tag noch schöner. Halte diese Freude bei einem Baby-Fotoshooting für immer fest.'),
  ('fcecf920-146e-4152-abc5-066ce8392fd8', 'Beruhigende Klangtherapie. 🎶', 'Bei Blähungen oder Müdigkeit kann der Herzschlag aus den Weißen Geräuschen dein Baby sofort beruhigen – wie im Mutterleib.'),
  ('6ca1ad26-9f01-4a3a-9164-e9f0d68cc33c', 'Was beschäftigt dich? 🤖', 'Stelle unserem Anacan KI-Assistenten auch nachts alle deine Fragen und erhalte fachkundige Unterstützung.'),
  ('f710f746-b942-4fd7-a8ca-dd9b5a248195', 'Schauen wir uns den Windel-Tracker an. 🧷', 'Halte die tägliche Anzahl der Windeln in Anacan fest, um sicherzugehen, dass dein Baby ausreichend Nahrung bekommt.'),
  ('fa5fc8d8-4263-4a99-9f46-297b1d6ea219', 'Es hält sein Köpfchen immer besser! 🐢', 'Mach die Bauchlage zu einem spielerischen Erlebnis.'),
  ('42ca0f3b-8083-4338-bf16-9998a33b15c6', 'Zeit für frische Luft! 🌳', 'Öffne unsere Karte mit mama­freundlichen Orten und finde den angenehmsten Ort, den du gemeinsam mit deinem Baby besuchen kannst.'),
  ('7fc52d97-b36d-4c5e-a169-0eadba238b0e', 'Gewicht und Größe im Blick behalten. 📏', 'Wie wächst dein Baby? Trage die neuen Daten in den Gewichts-Tracker ein und verfolge seine persönliche Wachstumskurve.'),
  ('df56b34d-b5f8-476f-a65e-11a244242a2f', 'Die Abendroutine vor dem Schlafengehen. 🛁', 'Bade und stille dein Baby und starte den Schlaf-Timer. So läuft alles entspannt und nach Plan!'),
  ('2776b020-9972-4e23-acb7-6a529664582d', 'Dein Baby sucht nach deiner Stimme! 👂', 'Sprich ganz viel mit deinem Baby und halte Blickkontakt. Im Bereich „Blogs“ findest du verschiedene Aktivitäten, die seine Entwicklung fördern.'),
  ('72abc90e-b301-468a-9629-3f3bb7949709', 'Bist du bei der Babypflege unsicher? 🤖', 'Die Anacan Community hört dir zu, ohne dich zu verurteilen, und gibt dir die passendsten Empfehlungen.'),
  ('816ef2cf-32b6-4eba-b12b-4e8f7936a78f', 'Unterstütze deine Milchbildung. 🥛', 'Vergiss nicht, viel Wasser zu trinken! Bereite dir außerdem mit den gesunden Rezepten für Frauen ein Getränk zur Förderung der Milchbildung zu.'),
  ('1501b0ff-9742-40e2-9aae-ff2e8f8e5188', 'Zeit für einen Familienausflug! ☕', 'Wähle bei den mama-freundlichen Orten ein gemütliches Café oder Restaurant aus und genieße deine freie Zeit.'),
  ('427917df-21f2-46c9-a030-52d511e37ce5', 'Tagesübersicht. 📊', 'Wie lange hat dein Baby heute geschlafen und wie oft wurde es gefüttert? Sieh dir in den Diagrammen der App die heutige Gesamtstatistik an.'),
  ('c555165e-a5c9-4e8c-9a72-cf4d0a16a367', 'Auch die Papas vergessen wir nicht! 👨‍🍼', 'Genieße die süßen und lustigen Momente, in denen dein Baby mit seinem Papa spielt.'),
  ('052bbdef-be6b-4b3f-bf88-905af0d4abc5', 'Manchmal muss man sich einfach ausruhen. 🛋', '️ Stelle den Schlaf-Timer ein, während dein Baby schläft, und nimm dir einfach Zeit für dich, ohne etwas zu erledigen.'),
  ('1053981f-f622-407a-ade7-529fc27bb2ff', 'Wir verfolgen die Entwicklung! ⚖️', 'Der zweite Monat geht zu Ende. Öffne in der App den Gewichts-Tracker und vergewissere dich, dass du die neuesten Daten eingetragen hast.'),
  ('8f5fde4a-3542-4bb1-be02-6df262d75b50', 'Ist alles in Ordnung? 📝', 'Wie fühlst du dich? Bist du müde oder voller Energie? Das Anacan-Stimmungstagebuch ist deine beste digitale Vertraute.'),
  ('292a637a-a0ca-4e58-8523-7b2c8b754743', 'Ein schöner Monat geht zu Ende. ✨', 'Dimme das Licht im Zimmer, schalte die weißen Geräusche ein und sei stolz auf dein Baby, während es schläft. Du bist eine großartige Mama!'),
  ('39c9a98b-8f4e-4896-9385-5588121bd72d', 'Herzlichen Glückwunsch, wir sind genau 2 Monate alt! 🎈', 'Erstelle beim Baby-Fotoshooting ein Erinnerungsfoto, um diesen wundervollen Moment festzuhalten!'),
  ('3c5f5d9f-939f-4c7e-9bc8-1feef640d854', 'Entwicklungsbericht nach zwei Monaten. 📈', 'Sieh dir den Gewichts-Tracker sowie deine Windel- und Ernährungsstatistiken an und erfahre, wie gesund dein Baby in diesen 60 Tagen gewachsen ist.'),
  ('1ed5f326-68dd-494e-a31c-2d3466644cd0', 'Energiequelle für Mamas! 🥗', 'Wähle unter „Gesunde Rezepte“ ein vitaminreiches Rezept aus, um deine Erholung und Milchbildung zu unterstützen.'),
  ('59041ede-10ec-4754-8f5f-31f415db3701', 'Die A-gu-Laute werden häufiger! 🗣️', 'Dein Baby versucht immer häufiger, mit dir zu kommunizieren. Lies die Beiträge im Bereich „Blogs“, um seine Sprachentwicklung zu fördern.'),
  ('d7b0c908-0d97-40c6-a82a-c5283f30a1d8', 'Behalte den Schlafbedarf im Blick. ⏱️', 'Aktiviere den Schlaf-Timer, wenn dein Baby schläft, und prüfe, ob es seinen täglichen Schlafbedarf erreicht.'),
  ('5309698d-6050-4993-9a68-ab592375ed60', 'Die Speicheldrüsen werden aktiv! 💧', 'Dein Baby kann jetzt vermehrt Speichel produzieren.'),
  ('83d11db6-0443-4d69-8d55-9ea20f0cf905', 'Wir verfolgen das Wachstum! 📏', 'Trage die Gewichts- und Größenangaben der nächsten Woche in den Gewichts-Tracker ein, um die persönliche Wachstumskurve deines Babys zu aktualisieren.'),
  ('ca5bc974-1377-4065-9dfa-50549135eb55', 'Gibt es etwas, das dich beunruhigt? 🤖', 'Stelle unserem Anacan AI-Assistenten auch nachts Fragen wie: „Warum schläft mein Baby heute so kurz?“'),
  ('5a4dd587-0176-4bbf-bb1c-d0eab0227cdc', 'Zeit für gemeinsame Babybetreuung mit Papa. 👨‍🍼', 'Überlass Papa nach dem abendlichen Füttern das Bäuerchen und Zubettbringen, während du dich ausruhst.'),
  ('a6843443-e0f6-4ec7-a4ec-03cb5d81d392', 'Die Übungen in Bauchlage werden leichter. 🐢', 'Dein Baby kann seinen Kopf jetzt aufrechter und länger halten. Integriere diese Übung in euren Tagesablauf.'),
  ('c2daa58e-e7ee-4f2b-917b-6e5273ca2c1d', 'Behalten wir die täglichen Windeln im Blick. 🧷', 'Erfasse weiterhin jeden Windelwechsel in Anacan, um sicherzustellen, dass dein Baby ausreichend Nahrung bekommt.'),
  ('7764e41d-176a-41d8-8f87-2a21677a36ee', 'Wir schaffen eine Routine. 🛁', 'Bade und stille dein Baby jeden Abend zur gleichen Zeit und starte den Schlaf-Timer, um einen gesunden Schlafrhythmus zu fördern.'),
  ('9754280d-c633-46e8-94c9-6f16ff032551', 'Vergiss dich selbst nicht, liebe Mama! 🍲', 'Schau dir in der Anacan-App den Bereich „Gesunde Rezepte“ an und bereite dir heute etwas Leckeres zu.'),
  ('c1c4c9b0-cdd8-4321-a494-3bb43739df94', 'Dein Baby erkennt dich und deine Stimme! 😍', 'Achte darauf, wie sehr es sich freut, wenn du den Raum betrittst. 😊'),
  ('149e95b1-a682-4369-8b74-5827cc5d31dc', 'Trau dich, deine Gefühle zu teilen. 📝', 'Müde oder voller Energie? Ganz gleich – halte deine heutigen Gefühle im Stimmungstagebuch fest und fühl dich leichter.'),
  ('79b7fb29-fa37-4176-9ae5-409d73ee982e', 'Auch unterwegs entspannt. ☕', 'Du möchtest mit Freunden einen Kaffee trinken? Dann wirf vor dem Losgehen einen Blick auf unsere Karte mit kinderfreundlichen Orten.'),
  ('818c91c1-bd54-42c5-8ac8-1505ae1830ab', 'Das soziale Lächeln! 😊', 'Sein süßes Lächeln lässt dich all deine Müdigkeit vergessen.'),
  ('998faa86-f9bb-47df-aa71-acba217766a9', 'Deine Wochenstatistik ist fertig! 📊', 'Öffne die App, um zu sehen, wie gut du in den letzten Tagen die empfohlenen Schlaf- und Ernährungszeiten eingehalten hast.'),
  ('aba537d3-5a0f-4b17-b02b-4754b93f711f', 'Vergessen, mit welcher Brust du gestillt hast? 🤱', 'Halte mit dem Timer fest, ob du mit der rechten oder linken Brust gestillt hast – Anacan merkt sich alles für dich!'),
  ('b4eb6af7-758b-41ff-a277-ea0ef21a9fb8', 'Der Tagschlaf verändert sich. ⏱️', 'Miss die Wachzeiten und Schlafpausen mit der Ernährungsübersicht und den Schlaf-Timern und entwickle so einen neuen Tagesrhythmus.'),
  ('32ff20f3-f1f8-47fd-b3be-c14bea1452a2', 'Klangtherapie gegen Unruhe. 🎶', 'Wenn dein Baby heute Abend unruhig ist, spiele unter „Weißes Rauschen“ Herzschlaggeräusche ab, um es abzulenken.'),
  ('a061022a-6a47-4aae-8590-2f0f328fbf09', 'Zeit zum Spielen! 🎈', 'Lies im Bereich „Blogs“ unsere Empfehlungen für entwicklungsfördernde Spiele und erfahre, wie du wertvolle Zeit mit deinem Baby verbringen kannst.'),
  ('b95ca7be-8491-4bbc-afb0-321f795780ea', 'Zeit zum Einkaufen? 🛍', 'In unserer Liste mit Produktempfehlungen findest du ganz einfach sichere Spielzeuge und Hilfsmittel, die zum aktuellen Alter deines Babys passen.'),
  ('633e342d-82b1-442c-9da8-5c5326907322', 'Tagesauswertung. 📈', 'Sieh dir die Auswertung deiner Ernährungs- und Schlafaufzeichnungen an und entdecke, wie gut sich eure Routine entwickelt.'),
  ('8655d498-c5d9-40f8-bd47-346f815d3e75', 'Ein schöner Abschluss für einen wundervollen Tag. 🌙', 'Dimme das Licht im Zimmer, spiele unter „Weißes Rauschen“ Gebärmuttergeräusche ab und sieh zu, wie dein Baby friedlich einschläft.'),
  ('97e88a0b-26cf-486d-a17f-2c34cfc6b47d', 'Ihr seid seit genau 70 Tagen zusammen! ✨', 'Du bist eine großartige Mama! Füge dem Babyalbum eine Collage hinzu, die den Unterschied zwischen dem ersten Tag und heute zeigt.'),
  ('1ef4e046-ea34-4d3c-b7c9-53017c12e5ae', 'Lass die Müdigkeit des Tages hinter dir. 🛁', 'Nimm dir Zeit für dich und halte deine heutigen Gefühle im Stimmungstagebuch fest – das kann dir helfen, dich leichter zu fühlen.'),
  ('59aa01c0-7e8d-4375-9fcd-733a242d640c', 'Wir behalten den Fütterungsrhythmus bei. 🍼', 'Der Appetit deines Babys kann zunehmen. Starte den Anacan-Timer und überprüfe die empfohlene Nahrungsmenge mit dem Tool zur Ernährungskontrolle.'),
  ('a19b5a5e-db95-4571-b0b8-5f50fabb0b6a', 'Der erste Tag des dritten Monats! 🎉', 'Dein Baby nimmt seine Umgebung jetzt bewusster wahr.'),
  ('8d26cab1-ebfd-469f-9ae0-aa66e0f36761', 'Fällt das Einschlafen schwerer? 🌙', 'Dunkle das Zimmer ab und wähle bei den Weißen Geräuschen Meeresrauschen aus, um dein Baby auf einen tiefen Schlaf vorzubereiten.'),
  ('92c57c1c-b876-4895-9dd9-de2d4fc5b8a4', 'Zeit für einen Spaziergang an der frischen Luft. 🌳', 'Spaziergänge an der frischen Luft sind für die Entwicklung und das Wohlbefinden deines Babys sehr wichtig.'),
  ('b6825824-6eff-4740-b6c1-dc607b41b996', 'Es greift nach Spielzeug! 🧸', 'Wie schön es ist, diese kleinen Entdeckungen mitzuerleben! Lade die Videos, die du beim Spielen mit deinem Baby aufgenommen hast, in das Babyalbum hoch.'),
  ('0c5e05bb-e0ba-4c0b-a9c9-f1f210abb37a', 'Wir sind ein Team! 💪', 'Fühlst du dich manchmal allein und unverstanden? Komm in die Anacan Community. Dort findest du Tausende Mütter, denen es genauso geht wie dir. Teile heute eine deiner Erfahrungen mit ihnen.'),
  ('60059890-bf5b-4e0b-ba41-fedc82fa6a43', 'Papa ist dran 👨‍🍼', 'Lass die Anstrengungen des Tages hinter dir. Gib das Baby seinem Papa und lass ihn es heute Abend ins Bett bringen. Du kannst dir einfach eine heiße Tasse Tee einschenken und den beiden entspannt zusehen.'),
  ('b1778419-cb70-4711-96e0-a612732e8575', 'Sabberndes Lächeln 🤤', 'Sabbert dein Baby häufig und hat es ständig die Hände im Mund? Beginne mit den ersten Einträgen im Zahnungs-Tracker. Ja, die aufregenden Vorbereitungen beginnen schon früh!'),
  ('0eb4da19-cb98-497a-a36b-a4934f47e071', 'Ruhe bewahren 🤫', 'Dein Baby ist gerade eingeschlafen, aber du machst dir Sorgen wegen der Geräusche im Haus? Aktiviere den Schallpegelmesser, behalte die Dezibelzahl im Raum im Blick und schütze so seinen Schlaf.'),
  ('9cab0c58-8a4f-4869-b607-be3e284373f0', 'Hast du eine Frage? 🤖', 'Geht dir bei all den täglichen Aufgaben etwas nicht aus dem Kopf? Ernährung, Schlaf oder Blähungen ... Ganz gleich, worum es geht: Frag sofort Anacan AI und erhalte eine präzise, wissenschaftlich fundierte Antwort.'),
  ('e6d33eab-abbe-4eca-94e9-c05138d06c07', 'Schau, ich bin hier! 👀', 'Dein Baby beobachtet dich jetzt sogar vom anderen Ende des Zimmers aufmerksam. Halte diesen großartigen Fortschritt beim Blickkontakt im Entwicklungs-Tracker fest und sei stolz darauf, wie es wächst!'),
  ('6cefc0b3-6f91-4329-bd4c-bf6671e0e8aa', 'Sternenklare Träume 🌌', 'Kinder lieben Routinen. Erstelle im Bereich „Smarte Märchen“ eine ganz persönliche Geschichte für dein Baby.'),
  ('dacdc0bf-3562-4ab5-be87-7acb17a3f2f9', 'Du bist großartig! 🌸', 'Denkst du manchmal, dass du nichts schaffst? Dann schau, wie ruhig und gleichmäßig dein Baby atmet ... Du gibst dein Bestes!'),
  ('faace99e-5074-497e-b5c0-f25a9880f5b0', 'Energie für Mama 🍲', 'Hast du bei all dem Trubel auch daran gedacht, selbst etwas zu essen? Wähle im Bereich „Gesunde Rezepte“ ein schnelles Suppenrezept aus, das dir neue Energie schenkt und deine Milchbildung unterstützt.'),
  ('1cd41578-3422-4bf8-9401-e9a058dcad6f', 'Nur 15 Minuten 🛁', 'Dein Baby schläft? Leite jetzt im Partnermodus alle Benachrichtigungen an deinen Partner weiter. Geh ins Bad und genieße 15 Minuten lang warmes Wasser und wohltuende Ruhe.'),
  ('73a10da9-aef9-4c21-b8d7-bca1f62e8528', 'Erfahrungen teilen 💬', 'Welche Bewegung deines Babys bringt dich in letzter Zeit am meisten zum Lachen? Besuche die Anacan-Community und teile diesen Moment in einem Beitrag. Die Geschichten anderer Mütter zu lesen, wird auch dir guttun.'),
  ('acfd33be-87a0-41a3-858d-d5921f61d9a4', 'Die eigenen Hände entdecken 👋', 'Hat dein Baby seine Hände entdeckt und betrachtet sie stundenlang? Verpasse diesen lustigen und wundervollen Entwicklungsmoment nicht – halte ihn gleich mit dem Baby-Fotoshooting für immer fest!'),
  ('5543e602-8610-44ac-8995-56ec74a0576e', 'Clevere Ruhe 🤫', 'Um abendliche Unruhephasen auf ein Minimum zu reduzieren, ist es wichtig, auf die Ruhe im Zimmer zu achten. Schalte den Geräuschpegelmesser ein, vermeide eine zu laute Umgebung und bereite dein Baby auf eine entspannte Zeit vor.'),
  ('81600590-d6f0-495d-b852-9afcf35b137a', 'Outfit für kleine Entdecker ⛅', 'Du möchtest spazieren gehen, aber das Wetter ist unbeständig? Mit deinem Wetter- und Kleidungsassistenten findest du in Sekundenschnelle das passende Outfit für die heutige Temperatur.'),
  ('fbf2b91a-0a2a-4aa9-9404-589ba5628b25', 'Ein Lächeln am Morgen ☀️', 'Hat dein Baby gleich nach dem Aufwachen zu dir geschaut und dir ein strahlendes Lächeln geschenkt? Dann hast du das kostbarste Geschenk der Welt bekommen. Denk heute einfach an diesen Moment und bleib positiv.'),
  ('1f2c4967-df72-43b6-91d0-25ece4f2331b', 'Noch 10 Tage bis zur Feier! 🎂', 'Mach dich bereit: In nur 10 Tagen ist der 3. Monat geschafft! Einer der ersten großen Meilensteine steht bevor. Jetzt ist genau der richtige Zeitpunkt, dir ein schönes Motto zu überlegen und die Torte zu bestellen!'),
  ('488e046f-44fb-4fcc-80e0-064c20288a56', 'Ein Hoch auf euch als Team 🥂', 'Bedankt euch heute Abend gegenseitig für die 80 Tage, die ihr gemeinsam gemeistert habt. Ihr habt es geschafft!'),
  ('720785a0-3423-4036-a26d-bba9419b8cb2', 'Ein großartiger 80. Tag! 🎉', 'Ihr seid jetzt genau 80 Tage zusammen! Öffne den Bereich für Baby-Fotoshootings, halte diesen Meilenstein mit den besonderen Stickern zum 80. Tag fest und teile die Erinnerung mit der Community!'),
  ('36b1e2d3-b43a-467e-b08f-870a612d1bb5', 'Der Schrei-Code 🧩', 'Dein Baby hat keinen Hunger, die Windel ist sauber, aber es ist trotzdem unruhig? Wenn du die Ursache nicht herausfinden kannst, nutze die Schrei-Analyse und erfahre, welches Bedürfnis wirklich hinter diesem Weinen steckt.'),
  ('384efd2a-d9fb-48b6-8e4a-eca7c3a0d8ee', 'Ehrlich erschöpft 💖', 'Die Wohnung ist unordentlich und das Essen wurde online bestellt? Das ist völlig in Ordnung. Du bist auf diesem Weg nicht allein.'),
  ('8f6c6637-de06-4b9d-8e44-d9e85864f3c8', 'Morgengymnastik 🐢', 'Dein Baby hält den Kopf schon viel aufrechter! Mach die Bauchlage zu einem kleinen Abenteuer. Lege es vor einen Spiegel und beobachte, wie es auf sein Spiegelbild reagiert.'),
  ('049d3744-b2ac-49ea-bf86-ad5e8d0bcb74', 'Merkzettel 📝', 'Im Haushalt fehlt immer etwas. Zerbrich dir nicht den Kopf: Öffne die Einkaufsliste, trage dort alles ein, was ihr braucht, und teile die Liste mit nur einem Fingertipp mit deinem Partner.'),
  ('12a076b6-d8dc-4bec-a8af-ddc523182bad', 'Zeit für eine Geschichte 📖', 'Der Weg deines Babys zu einem großen Träumer beginnt schon jetzt. Erstelle mit Smarten Märchen eine zauberhafte Geschichte, lies sie vor und beobachte, wie seine Augen langsam zufallen.'),
  ('58ce6bd9-90fd-4e98-a133-ddfda6d59177', 'Der Kinderarzt für deine Hosentasche 🤖', 'Nimmt dein Baby gut zu? Hat sein Stuhl eine ungewöhnliche Farbe? Bevor du dir Sorgen machst, schreib Anacan AI, erfahre mehr über die mögliche Ursache und erhalte beruhigende Informationen.'),
  ('05925891-b678-4a87-8f54-39f692aa9143', 'Gehen die Vorräte zur Neige? 🛒', 'Gehen die Windeln oder Feuchttücher aus? Du musst nicht alles im Kopf behalten. Füge sie jetzt zur Einkaufsliste hinzu, damit dein Partner oder deine Partnerin sie abends mitbringt.'),
  ('41007feb-f415-4088-b094-428b2275abbf', 'Magische Welt der Klänge 📖', 'Bringe Abwechslung in eure Abendroutine. Erstelle mit den smarten Märchen eine beruhigende Geschichte für dein Baby und erleichtere euch beiden das Einschlafen.'),
  ('e23c6a5f-2a6d-45e5-af3a-8681c3bb9e03', 'Morgenkonzert 🎶', 'Macht dein Baby seine ersten Gurrlaute? Sprich seine Sprache und antworte auf seine Laute. Genieße heute einfach diesen süßen Moment und lass euch Zeit.'),
  ('62fbb893-6a1c-4847-a99e-981afea8fa87', 'Unterschiedliche Arten des Weinens 😭', 'Weint dein Baby vor Hunger oder weil es müde ist? Keine Sorge: Mit unserem Tool zur Weinanalyse finden wir gemeinsam in Sekundenschnelle heraus, was dir diese Laute sagen möchten.'),
  ('83a0ab90-d44d-4758-bd3f-c7126ae6e20f', 'Sei ehrlich zu dir selbst 📝', 'Bist du heute sehr erschöpft? Schreibe deine Gefühle ganz ehrlich in dein Stimmungstagebuch. Du musst nicht jeden Tag perfekt sein – du bist auch nur ein Mensch.'),
  ('d9e30a3e-ad9b-4b4b-85a6-bcaa444e488c', 'Was soll mein Baby anziehen? ⛅', 'Das Wetter ist wechselhaft und du hast Angst, dass dein Baby friert oder schwitzt? Sieh gleich im Tool „Wetter und Kleidung“ nach und finde das ideale Outfit für das heutige Wetter.'),
  ('357bed80-6ac0-481c-9f5b-22bc1c97e3fe', 'Die Hände entdecken 🤲', 'Versucht dein Baby schon ganz bewusst, nach hängenden Spielsachen zu greifen? Seine motorischen Fähigkeiten entwickeln sich. Schau im Bereich „Empfohlene Produkte“ nach sicheren Greifspielzeugen, die diese neue Neugier unterstützen.'),
  ('3c4bae00-6309-4214-a502-aa8dcb398a77', 'Überraschungswetter ⛅', 'Du möchtest nach draußen, kannst das Wetter beim Blick aus dem Fenster aber nicht einschätzen? Zieh dein Baby nicht in mehreren Schichten an, sodass es schwitzt. Das Wetter- und Kleidungstool zeigt dir in Sekundenschnelle das ideale Outfit für die heutige Temperatur.'),
  ('42bfdf13-2735-49dc-b527-89506330c670', 'Papas Schultern 👨‍👧', 'Deine Geduld ist am Ende und deine Arme sind müde? Aktiviere heute Abend den Partnermodus. Bäuerchen machen und im Zimmer umhertragen ist heute ganz Papas Aufgabe. Du darfst dich einfach auf dem Sofa ausruhen.'),
  ('3d2a21ef-6e5b-4f36-9011-f9c3474762a4', 'Nicht hungrig – warum weint es dann? 🧩', 'Dein Baby lässt sich durch nichts beruhigen und sein Weinen klingt anders als sonst? Hör auf zu rätseln: Lass die Weinanalyse den Laut anhören und finde sofort heraus, ob Blähungen oder Müdigkeit dahinterstecken.'),
  ('b092d275-f2d6-47ce-b8d0-3f8ced210589', 'Kopfhörer und Kaffee 🎧', 'Heute war wirklich ein harter Tag. Schreib dir im Stimmungstagebuch alles von der Seele. Setz dann die Kopfhörer auf, mach deine Lieblingsmusik an und genieße 10 Minuten lang in aller Ruhe einen heißen Kaffee.'),
  ('c6fb2576-7fa6-4e01-b8a4-ec89ac753089', 'Die morgendliche Windelkatastrophe 💩', 'Du öffnest die Augen und findest ein Baby vor, bei dem alles bis zum Hals ausgelaufen ist – samt Bettwäsche, die gewechselt werden muss? Trag dieses große Malheur mit einem Lächeln im Windeltracker ein. Ja, auch das gehört zum Mamasein!'),
  ('7d54b8de-cc42-4891-b97a-5856eefffe9d', 'Dein persönliches Märchen entsteht 🪄', 'Heute Abend spielt dein Baby die Hauptrolle! Öffne das Tool für intelligente Märchen und gib ein Thema ein: „Das Abenteuer des kleinen Ritters, der nachts nicht schlafen wollte“. Lass die künstliche Intelligenz nur für euch eine einzigartige und zauberhafte Geschichte erschaffen.'),
  ('d5c6a987-139f-4c65-bdd8-e9dc3eb4c43a', 'Bereit für einen Dialog? 🗣️', 'Dein Baby macht nicht mehr nur Geräusche, sondern versucht, mit unterschiedlichen Tönen auf deine Stimme zu reagieren! Öffne den Entwicklungstracker, halte diesen wunderbaren Kommunikationssprung fest und antworte ihm in seiner eigenen Sprache.'),
  ('f027a882-3827-4905-9807-216432d88e53', 'Der Mama-Gedächtnisnebel 🌫️', 'Du weißt nicht mehr, was du gestern gegessen hast? Mama-Demenz (Baby Brain) gibt es wirklich. Überfordere deinen Kopf nicht: Schreib alles, was ihr zu Hause braucht, auf die Einkaufsliste und lass deinen Partner den Rest erledigen.'),
  ('2e536117-6f18-4388-b1bd-29587c89d3cb', 'Die Wahrheit über Haare überall 💇‍♀️', 'Erschreckt dich dein Haarausfall beim Blick in den Spiegel? Das ist eine der lästigsten Begleiterscheinungen der Zeit nach der Geburt! Du bist nicht allein. Schau gleich in der Anacan-Community vorbei und erfahre, wie andere Mütter mit dieser schwierigen Phase umgehen.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_de = v.t, body_de = v.b
FROM (VALUES
  ('41393920-01a7-42fe-a049-e26e1148a375'::uuid, 'Auf der Suche nach Ruhe 🤫', 'Manchmal hindert der Lärm zu Hause dein Baby am Einschlafen, ohne dass du es bemerkst. Aktiviere den Geräuschpegelmesser, prüfe die Raumakustik und schaffe die ideale ruhige Umgebung für dein Baby.'),
  ('acb2ca22-b3e3-4ac0-b344-a63734056dfa', 'Juckt das Zahnfleisch? 🦷', 'Steckt dein Baby alles in den Mund, besonders seine eigenen Hände? Hat es angefangen, stark zu sabbern? Halte die ersten Anzeichen gleich im Zahnungs-Tracker fest und bereite dich auf diesen langen Prozess vor.'),
  ('13035ad4-af08-4b79-ba71-a42ceb60fe5b', 'Teambesprechung 🛋️', 'Wenn dein Kind eingeschlafen ist, schaut euch gemeinsam die Wochenstatistik in deinem Stimmungstagebuch an. An welchen Tagen warst du besonders gestresst? Was könnt ihr anders machen? Ihr seid ein Team!'),
  ('400a0bc6-f5e7-4dd0-9d49-d6e66ce5c9b6', 'Schau nach unten! 👣', 'Dein Baby entdeckt gerade seine Füße! Verpasse nicht diesen lustigen und süßen Moment, wenn es versucht, seine Zehen zu greifen. Öffne das Baby-Fotoshooting, verziere das Foto mit Stickern und halte diesen großen Entwicklungsschritt fest.'),
  ('daf9dd68-0ed6-4ada-9b16-84c4ff46a8e8', 'Zeit für einen Beißring 🦷', 'Dein Baby sabbert ununterbrochen und kaut auf allem herum? Der Zahnungs-Tracker macht dich darauf aufmerksam. Jetzt ist der perfekte Zeitpunkt, um im Bereich „Empfohlene Produkte“ nach Beißringen aus unbedenklichem Silikon oder Holz zu suchen.'),
  ('0d132ba6-d6e9-44f6-a85d-e139c66b9760', 'Schnelle Antwort 🤖', 'Warum verweigert dein Baby plötzlich seine Tagschläfchen? Du hast keine Zeit, lange Artikel zu lesen. Stelle deine Frage direkt an Anacan AI und erhalte eine konkrete, kurze Antwort zur 3-Monats-Schlafregression.'),
  ('3d40ac30-86f9-4dfc-9db8-efd1a5dd1198', 'Märchenhafte Einschlafhilfe 🪄', 'Die intelligenten Märchen sind wieder im Einsatz! Schreibe ins System: „Die Geschichte einer Fee, die tagsüber vom Spielen müde wird und nachts wunderschön träumt“. Vielleicht schläfst du beim Vorlesen sogar selbst ein.'),
  ('6c6289cf-6e7c-4e83-a178-d01d67cef488', 'Das Rätsel um die richtige Kleidung 👗', 'Ziehst du dein Baby manchmal zu dünn und manchmal zu warm an? Du musst nicht länger überlegen. Statt aus dem Fenster zu schauen, prüfe gleich „Wetter und Kleidung“ und atme dank der empfohlenen Kleidung im Zwiebellook entspannt auf.'),
  ('022a6d7a-76fe-47e7-aae6-a35dad3d3555', 'Miss die Zeit ⏱️', 'Unregelmäßige Mahlzeiten sind anstrengend? Miss mit dem Timer im Ernährungs-Tracker, wie lange dein Baby an der Brust oder mit der Flasche trinkt, und lerne so seine neue Routine besser kennen.'),
  ('62da6149-1edf-4e2a-abc6-d69d21a43fa4', 'Keine Lust auf Bauchlage 🐢', 'Dein Baby möchte nicht auf dem Bauch liegen (Tummy Time) und weint? Zwinge es nicht. Frag Anacan AI: „Wie kann ich die Bauchlage für ein 3 Monate altes Baby spielerisch gestalten?“ und erhalte schnelle Tipps.'),
  ('938dd21f-e30f-4b2b-b3e0-d79140f44b59', 'Lass uns noch eine Geschichte erfinden! 🪄', 'Gib den Smarten Geschichten diesmal eine besonders lustige Aufgabe: „Die Geschichte des Wichtels, der sich in Papas Bart versteckt“. Lass deinen Partner die von der künstlichen Intelligenz erfundene Geschichte vorlesen und den Raum mit fröhlichem Lachen erfüllen.'),
  ('1f0c7fc3-49b6-44d6-a78b-152d7ead7adc', 'Raus aus den eigenen vier Wänden 🏃‍♀️', 'Dir fällt zu Hause die Decke auf den Kopf, aber du weißt nicht, wohin du mit deinem Kind gehen kannst? Finde bei den mama-freundlichen Orten das nächste Café mit barrierefreiem Zugang für den Kinderwagen und einem Stillraum – und genieße ein wenig Gesellschaft.'),
  ('55bafaf5-82ef-4f88-880d-836cf89145d0', 'Die Kraft der Klänge 🌊', 'Die scheinbar grundlosen Schreiphasen am späten Nachmittag sind anstrengend. Geh mit deinem Baby ins Zimmer und wähle beim weißen Rauschen Meereswellen oder das Geräusch eines Haartrockners, um sofort eine beruhigende Atmosphäre zu schaffen.'),
  ('a6e787a8-1712-42a4-9b2a-4f48a9e5fc87', 'Wo ist Mamas Energie geblieben? 🔋', 'Mach dir keine Vorwürfe, wenn du deine müden Augen im Spiegel siehst. Achtest du auf deine Ernährung? Wähle aus den gesunden Rezepten einen eisenreichen Smoothie für Mamas, der in 10 Minuten fertig ist, und tanke neue Energie.'),
  ('132d4620-5085-4072-ac1e-81f46dc4e74c', 'Schütze den Schlaf mit dem Lautstärkemesser 🤫', 'Du bist aufgeregt und zu Hause laufen die Vorbereitungen, aber der Schlaf deines Babys sollte nicht gestört werden. Lass das Lautstärkemesser im Zimmer eingeschaltet und erkenne sofort, wenn der Geräuschpegel den Grenzwert überschreitet.'),
  ('32bd9b1c-365c-405d-addd-9a30d6295abc', 'Heute wird nicht geputzt! 🛑', 'Du musst nicht überall aufräumen. Aktiviere den Partnermodus: Heute ist dein Partner für den Hausputz und die Essensbestellung zuständig. Du planst einfach nur das morgige 3-Monats-Fotoshooting.'),
  ('a4183b3c-1979-434f-a71f-64b50e2e618c', 'Zeit für die Vorbereitungen! 🎂', 'Achtung! Morgen ist der große Tag – dein Baby wird genau 3 Monate alt! Hast du daran gedacht, eine Torte zu bestellen oder ein kleines Motto vorzubereiten, um den 90. Tag ganz besonders zu gestalten? Beeil dich!'),
  ('10a571b7-6bc2-4092-a70f-a265883d71ba', 'GENAU 3 MONATE! EXAKT 90 TAGE! 🎉', 'Du hast es geschafft! Trotz Schlafmangel, schwieriger Phasen und Ängsten habt ihr ganze 90 Tage lang großartige Teamarbeit geleistet. Öffne das Baby-Fotoshooting, wähle den 3-Monate-Sticker aus und teile diese Freude sofort mit den anderen Müttern in der Anacan-Community!'),
  ('9877e456-4a5e-45a3-aee9-e9703be5cf91', 'Herzlichen Glückwunsch! 🥂', 'Schau dir all deine Aufzeichnungen und Entwicklungskurven noch einmal an. Sieh, wie sehr dein Baby gewachsen ist und wie viel stärker du geworden bist. Jetzt ist genau der richtige Zeitpunkt, stolz auf dich zu sein!'),
  ('9b7b163b-1de2-4ecd-becc-21f1f3c0e10e', 'Der Siegesmoment für euer Team 💖', 'Du hast dein Baby mit diesem besonderen Schlaf-Timer zum Einschlafen gebracht. Jetzt setzt euch einander gegenüber. Bedankt euch gegenseitig für jeden einzelnen Moment dieser 90 Tage. Es sind nicht nur die ersten 3 Monate eures Babys, sondern auch eure ersten 3 Monate als Eltern!'),
  ('5c67089a-581e-455d-b113-f87f427babb2', 'Euer ganz persönliches Märchen 🪄', 'Gib dem Tool „Smarte Märchen“ heute Abend ein zauberhaftes Thema: „Die Geschichte vom süßesten Stern, der vom Himmel fiel“. Lass im Zimmer nur dieses Märchen erklingen – und genießt ansonsten vollkommene Stille.'),
  ('66bd508e-0413-4d01-9ea7-c369b0d8cafa', 'Papa ist dran 👨‍👧', 'Deine Geduld ist am Ende? Übergib deinem Partner heute für eine Weile die Elternschicht. So können die beiden etwas Zeit miteinander verbringen, während du einfach die Füße hochlegst und dich ausruhst.'),
  ('8474a75e-7aaf-420e-b5ab-acd7d55ac51c', 'Zeit zum Lachen! 😂', 'Dein Baby lächelt nicht mehr nur, sondern lacht jetzt richtig laut! Spiel mit ihm und kitzle seinen Bauch. Dieses Lachen ist die schönste Belohnung für all die schlaflosen Nächte.'),
  ('0027b4ad-2816-4a79-ae3a-7ddbdcf29e4b', 'Müdigkeitssignale 🥱', 'Reibt sich dein Baby die Augen, zieht es an seinem Ohr oder starrt es ins Leere? Warte nicht, bis es am Abend völlig übermüdet ist. Sobald du diese Signale bemerkst, verdunkle das Zimmer und beginne mit eurem Einschlafritual.'),
  ('1867104a-7fa8-428a-ad5d-dd10e6890f0f', 'Die Welt mit dem Mund entdecken 🤤', 'Steckt dein Baby seine Hände, Spielsachen und alles, was es findet, direkt in den Mund? So erkundet es die Welt. Nimm ihm nicht alles weg, sondern achte einfach darauf, dass die Dinge in seiner Umgebung sauber sind.'),
  ('4ad3cf84-0aac-46cb-bfdf-5a928764105a', 'Warum ist es zu Hause so unordentlich? 🌪️', 'Du siehst den Spielzeughaufen mitten im Zimmer und das ungewaschene Geschirr und machst dir Vorwürfe? Lass das Geschirr heute einfach stehen. Ein Kind großzuziehen ist schließlich schon eine riesige Aufgabe!'),
  ('2e4ec0c9-5de6-407d-9e5d-26c67a8ecc5b', 'Drehübungen 🤸‍♂️', 'Dein Baby versucht, sich vom Rücken auf den Bauch zu drehen! Für diesen kleinen Körper ist das eine große Herausforderung. Unterstütze seine lustigen Versuche, aber sei an Bettkanten unbedingt besonders vorsichtig.'),
  ('91aad506-9119-4c1d-9011-ca750f77b2da', 'Du bist genug! 💖', 'Hast du heute Morgen in den Spiegel geschaut und dich müde oder vielleicht sogar unzulänglich gefühlt? Atme tief durch. Für die unschuldigen Augen deines Babys, die dich ansehen, bist du das vollkommenste Wesen der Welt. Du bist genug!'),
  ('cc5d4a21-5a6c-4726-9656-04a48085588c', 'Wie müde sind wir? 🛋️', 'Das Baby schläft – und ihr? Öffnet das Stimmungstagebuch und haltet gemeinsam mit deinem Partner oder deiner Partnerin das heutige Chaos mit Humor fest. Schwierige Tage gehen vorbei, was bleibt, ist euer Teamgeist.'),
  ('8557b605-4ddd-4ff9-9e9a-646d4a26ea63', 'Steht die Schlafregression vor der Tür? 🤖', 'Wacht dein Baby nachts plötzlich häufig auf? Keine Sorge, möglicherweise steht die Schlafregression im 4. Monat bevor. Lass dir von Anacan AI sofort eine kurze, beruhigende Erklärung zu diesem biologischen Prozess geben.'),
  ('88a16b76-764f-4acc-b335-0aa3f126d25a', 'Zeit, nach draußen zu gehen ⛅', 'Sich fertig zu machen kann anstrengend sein, aber schon 20 Minuten an der frischen Luft tun sowohl deinem Baby als auch deinem seelischen Wohlbefinden richtig gut. Prüfe das Wetter, wähle passende Kleidung, zieh dich an und öffne nicht das Fenster, sondern die Tür!'),
  ('bb5697de-df9c-4558-a606-a7acef72c755', 'Papa, der Held der Nacht 🦸‍♂️', 'Die schönste Regel für die ersten Monate: Beim Bäuerchenmachen und Schlaflieder-Singen wird sich abgewechselt! Heute Abend liegt das Baby in Papas Armen, während du deine Kopfhörer aufsetzt und die Musik genießt.'),
  ('4696c250-45bb-4765-b4bf-ee4e94f6361c', 'Mamas Tasse ☕', 'Was hast du heute für dich selbst getan? Nichts? Sobald dein Baby seinen Mittagsschlaf macht, leg das Handy beiseite. Gieß dir einen heißen Kaffee (oder Tee) ein und denke 10 Minuten lang an gar nichts.'),
  ('7831318d-6b24-4373-9578-2c2a43ef02bf', 'Die Kunst des Haareziehens 💇‍♀️', 'Greift dein Baby direkt nach deinen Haaren, wickelt sie um seine Hände und zieht kräftig daran? Sein Greifreflex wird stärker! Halte diese lustige, aber schmerzhafte Entwicklungsphase unbedingt in einem Video als Erinnerung fest.'),
  ('d66ea07a-276e-489b-bd8f-3ff80abe7258', 'Das Wunder des Körperkontakts 🫂', 'Dein Baby will einfach nicht schlafen und schreit, sobald du es ins Bettchen legst? Manchmal braucht es keinerlei Hilfsmittel. Leg es auf deine Brust und spüre, wie der Hautkontakt euch beide beruhigt.'),
  ('a99309cf-e0e5-4d40-9004-a8b08226861a', 'Ist der Kragen alle 10 Minuten nass?', 'Die ersten Anzeichen im Zahnungs-Tracker werden nun Wirklichkeit. Schau regelmäßig am Unterkiefer nach – vielleicht ist das erste weiße Zähnchen schon unterwegs!'),
  ('b14018ad-b2b5-4374-a785-9d281ebdd7e0', 'Nur 15 Minuten Ruhe 🤫', 'Brummt dir vor Erschöpfung schon den ganzen Tag der Kopf? Sobald dein Baby eingeschlafen ist, aktiviere den Geräuschmesser, behalte die Lautstärke im Blick, bitte alle zu Hause um Ruhe und gönne deinem Kopf eine Pause.'),
  ('c69510ed-a6e2-4456-a462-211d3917dec3', 'Was machen andere Mamas? 💬', 'Fragst du dich: „Macht das nur mein Kind?“ Du bist nicht allein! Schau in der Anacan-Community vorbei, lies die echten Geschichten anderer Mamas und atme erleichtert auf.'),
  ('51cd27c2-62e8-409d-8a08-48c1ba2f8c3b', 'Der Freund im Spiegel 👀', 'Setz dein Baby vor einen Spiegel. Beobachte, wie es sein Spiegelbild staunend und lächelnd betrachtet. Es weiß noch nicht, dass es sich selbst im Spiegel sieht, aber dieses Spiel fördert seine geistige Entwicklung.'),
  ('6f416e63-4acf-4dd2-8216-6601a8c26df5', 'Lass die Schuldgefühle los 🛑', 'Warst du heute ungeduldig, vielleicht sogar etwas gereizt, und hast jetzt ein schlechtes Gewissen? Halt kurz inne. Bist du ein Roboter? Nein. Nimm deine Gefühle an, verzeih dir selbst und starte morgen neu in den Tag.'),
  ('d584b1c4-e42a-483d-b585-e83a9ab20c88', 'Energie für Mama 🍲', 'Hast du beim Füttern deines Babys vergessen, selbst etwas zu essen? Bereite dir im Bereich „Gesunde Rezepte“ einen leicht verdaulichen, energiereichen Snack zu. Du brauchst Kraft, um auch deinem Baby Kraft geben zu können.'),
  ('014e3f07-72e8-47f8-b62e-ff583a9df29e', 'Sprich mit mir! 🗣️', 'Schaut dein Baby dich an und bildet dabei lustige Silben? Reagiere auf seine Laute und Pausen. Es führt gerade einen echten Dialog mit dir! Das ist einer der wichtigsten ersten Schritte der Sprachentwicklung.'),
  ('c290d85d-0e02-4b4e-aaab-db6ae8bfcaef', 'Dinge, die leicht übersehen werden 🛒', 'Geht im hektischen Alltag gerade etwas zur Neige? Toilettenpapier, Windeln oder Shampoo? Füge es jetzt gleich deiner Einkaufsliste hinzu, bevor du es vergisst, damit dein Partner eine Benachrichtigung auf sein Handy erhält.'),
  ('e8ec2cd2-3417-4383-8892-bb623cb07365', 'Die Zeit anhalten 📸', 'Dein Baby wächst so schnell ... Schau dir heute Abend, während es schläft, seine Gesichtszüge ganz genau an. Halte seine kleinen Hände und sein Gesicht mit dem Baby-Fotoshooting in einer Aufnahme fest und bewahre diesen Moment für immer.'),
  ('2a23a61b-4ca6-48f6-8845-f47a357eed0f', 'Was bedeutet dieses Geräusch? 🧩', 'Dein Baby quengelt und weint zugleich, sobald es die Augen öffnet? Wenn du den Grund nicht herausfindest, nutze die Schreianalyse und entschlüssle in Sekundenschnelle, was hinter dieser Krise steckt.'),
  ('43fbc1cb-7e93-4983-b59f-f5bc67650d3e', 'Die Geschichte geht immer weiter 📖', 'Gib den Intelligenten Geschichten heute Abend eine besonders kreative Aufgabe: „Die Geschichte vom kleinen Bären, der den Duft seiner Mama sucht“. Lass den Abend liebevoll und ruhig ausklingen.'),
  ('b8cf3d8c-2c7c-497e-8657-18fd989a1928', 'Zeit, rauszugehen! 🌳', 'Du weißt nicht, wohin du mit deinem Kind gehen kannst? Ein Spaziergang im Park ist dir zu anstrengend? Entdecke bei den mama-freundlichen Orten einen Platz, an dem du bequem mit deinem Kind sitzen und eine Tasse Kaffee genießen kannst.'),
  ('1c648ce0-799c-41f0-964a-90e59cbddc3d', 'Ein großer Triumph, auf den ihr gemeinsam stolz sein könnt 🥂', '100 Nächte, 100 Tage ... Schau deinen Partner an, der diese große Last mit dir getragen hat. Halte den Stolz auf den 100. Tag im Stimmungstagebuch fest und schenkt euch gegenseitig Applaus im Stehen. Das ist der Triumph eures Teams!'),
  ('52155593-73d7-4bb9-861d-d87a0ca100e9', 'EIN 100-TAGE-WUNDER! 🎉', 'Ja, heute sind es genau 100 Tage, seit sich euer Leben von Grund auf verändert hat! Ihr leistet Unglaubliches.'),
  ('7c63492d-1515-406a-bd31-b41ece7e0412', 'Applaudiere dir selbst 👏', 'Wenn du zurückblickst, erkennst du, wie beängstigend die ersten Tage waren und wie viel du inzwischen gelernt hast. Sei stolz auf dich. Nicht nur dein Kind ist 100 Tage gewachsen – auch du bist in diesen 100 Tagen gewachsen.'),
  ('724659ec-f59f-4bfe-b20d-efdd3d977217', 'Zeit zum Entspannen 🛋️', 'Wenn dein Baby allein spielt, solltest du nicht sofort zur nächsten Aufgabe eilen. Setz dich hin, beobachte es einfach 5 Minuten lang aus der Entfernung und genieße deinen Kaffee.'),
  ('aaed3963-e8dd-47d4-93bd-9b307c2b65fd', 'Morgenenergie ⚡', 'Brabbelt dein Baby gleich nach dem Aufwachen? Es möchte mit dir sprechen. Lächle und antworte ihm – das legt den Grundstein für seine Sprachentwicklung.'),
  ('d1e64fb7-d149-4fd0-afca-834eed2264d1', 'Schlafregression? 🌙', 'Wacht dein Baby nachts plötzlich häufig auf? Das könnten Anzeichen der 4-Monats-Schlafregression sein. Hab Geduld, auch diese Phase geht vorüber.'),
  ('13cad6d0-aa0a-426b-9515-1e96e73e716a', 'Neue Entdeckungen 🤲', 'Steckt dein Baby alles in den Mund, was es in die Hände bekommt? Keine Panik, so entdeckt es die Welt. Achte einfach darauf, seine Umgebung sauber zu halten.'),
  ('bfab4a59-c162-47a2-9035-51b03b7fe911', 'Die Hausarbeit kann warten 🛑', 'Lass dich von einem unaufgeräumten Zimmer nicht stressen. Du ziehst gerade einen kleinen Menschen groß und musst keine perfekte Hausfrau sein.'),
  ('ca9affc4-d638-41a2-8dc7-75447d9ea222', 'Papa ist dran 👨‍🍼', 'Heute Abend übernimmt Papa das Bäuerchen und das Schlaflied. Du darfst dich währenddessen ausruhen.'),
  ('18211145-ceeb-48f3-8053-1e2ff686e384', 'Der Zauber der Klänge 🌊', 'Wenn abends die Schreiphasen beginnen, gerate nicht in Panik. Spiele deinem Baby weißes Rauschen vor und verändere so im Handumdrehen die Atmosphäre im Zimmer.'),
  ('49d00520-8368-4f13-9074-fbe894888b76', 'Frag die KI 🤖', 'Du hast tausend Fragen im Kopf? Verschwende keine Zeit mit der Suche – frag direkt Anacan AI und erhalte eine präzise, wissenschaftlich fundierte Antwort.'),
  ('e6ea83f7-b8a5-46f7-ba44-81c58175071e', 'Schau nach unten! 👣', 'Dein Baby entdeckt gerade seine Zehen! Beobachte diesen lustigen und faszinierenden Moment ganz genau und genieße diesen Entwicklungsschritt.'),
  ('53a91083-d8e0-4baf-9f90-46ce72a9291d', 'Der Freund im Spiegel 👀', 'Setze dein Baby vor einen Spiegel. Es ist eine wunderbare Beschäftigung, zu beobachten, wie es sein Spiegelbild staunend betrachtet und anlacht.'),
  ('96d4756e-270f-426b-9e78-f2a573accdac', 'Zeit, nach draußen zu gehen 🌳', 'Die eigenen vier Wände fallen dir auf den Kopf. Setze dein Baby in den Kinderwagen und geht an die frische Luft – und wenn es nur für 15 Minuten ist. Das wird euch beiden guttun.'),
  ('de11a3ea-d3e5-4374-adb5-b6c04fb6fc41', 'Der Held der Nacht 🦸‍♂️', 'Bist du von den nächtlichen Wachphasen erschöpft? Scheue dich nicht, den Papa zu wecken. Ein Team zu sein bedeutet, die Last gleichmäßig zu verteilen.'),
  ('0695fd99-0b0d-4896-bd12-4ec8e6b49a4e', 'Vergiss dich selbst nicht 🍲', 'Dein Baby ist satt, aber was ist mit dir? Um wieder zu Kräften zu kommen, musst du dich gut ernähren. Bestell dir heute eine leckere und sättigende Mahlzeit.'),
  ('957a90d0-61dc-45f5-a2da-ef7086521cd5', 'Hast du plötzlich lautes Lachen im Zimmer gehört? 😂', 'Ja, dein Baby lacht jetzt aus vollem Herzen! Dieses Lachen ist all die Müdigkeit wert.'),
  ('dd50206e-acee-43ac-8f19-c5dd29cf7e62', 'Hautkontakt 🫂', 'Dein Baby ist sehr unruhig? Wenn nichts hilft, leg es auf deine Brust. Dein Herzschlag ist das beste Beruhigungsmittel.'),
  ('2c73f922-1b22-4eb6-922b-215d8e623242', 'Das Haarezieh-Spiel 💇‍♀️', 'Wickelt dein Baby seine Finger um deine Haare und zieht kräftig daran? Sein Greifreflex entwickelt sich. Versuch, über diesen etwas schmerzhaften Entwicklungsmoment zu lachen.'),
  ('f32eaadc-b85c-4f36-b182-6f6665e1eaae', 'Absolute Stille 🤫', 'Dein Baby kann nur schwer einschlafen? Verdunkle das Zimmer vollständig und sorge für Ruhe. Dunkelheit und Stille sind seine besten Einschlafhelfer.'),
  ('f4e3cb01-431f-4e52-a62b-ab96cbc1de4b', 'Kommen die ersten Zähnchen? 🦷', 'Speichelt dein Baby mehr als sonst? Halte es im Zahnungs-Tracker fest und bewahre saubere Beißringe griffbereit auf.'),
  ('1e555e61-fac2-4756-83d5-5c2a2ceaa400', 'Euer ganz persönliches Märchen 🪄', 'Erleichtere deinem Baby mit intelligenten Märchen das Einschlafen am Abend. Erstelle eine ganz persönliche, liebevolle Geschichte und lies sie ihm vor.'),
  ('a4146327-bb44-44e0-9860-d8e3c1abe5c4', 'Wir sind ein Team! 💪', 'Fühlst du dich allein und erschöpft? Atme tief durch. Du bist die stärkste Heldin in diesen turbulenten Tagen.'),
  ('e3c0355b-40c6-476a-8c2d-f69c78debdb1', 'Eine tolle Drehung 🤸‍♂️', 'Versucht dein Baby, sich vom Rücken auf den Bauch zu drehen? Es gibt sich große Mühe! Beobachte diese Versuche, aber lass es niemals allein auf dem Bett liegen.'),
  ('532d58e2-50f3-422a-818a-36c88094bb87', 'Was soll mein Baby anziehen? ⛅', 'Du musst nicht lange überlegen, was dein Baby draußen anziehen soll. Schau im Wetter- und Kleidungshelfer nach und finde in Sekundenschnelle das ideale Outfit.'),
  ('f37039a0-f7af-487a-827e-622e2d9e4d05', 'Erschöpft zu sein ist normal 🔋', 'Fühl dich nicht wie eine schlechte Mutter, wenn deine Geduld nachlässt. Diese Erschöpfung ist ganz normal. Scheue dich nicht, deinen Partner oder deine Partnerin um Unterstützung zu bitten.'),
  ('f94cdd25-2b6b-47df-81dc-6e3cab221652', 'Du bist genug! 🌸', 'Geht heute alles schief? Das ist in Ordnung. Dein Baby braucht niemanden so sehr wie dich. Für dein Baby bist du genau richtig.'),
  ('07f48fa2-56fd-416e-adda-88c824f2bd6f', 'Vorbereitung auf tiefen Schlaf 🛀', 'Ein warmes Bad, eine sanfte Massage und ein abgedunkeltes Zimmer ... Eine feste Schlafroutine ist das Geheimnis ruhiger Nächte.'),
  ('828415f3-317f-4e76-8caf-753026dcf9f1', 'Hab kein schlechtes Gewissen 💖', 'Denkst du, dass du zu wenig Zeit mit deinem Kind verbringst? 10 wertvolle Minuten mit einem Lächeln sind mehr wert als 1 stressige Stunde.'),
  ('f4730701-e02f-4cf0-9730-df8b7e034297', 'Ich greife selbst danach! 🧸', 'Greift dein Baby schon ganz gezielt nach hängenden Spielsachen? Seine Hand-Auge-Koordination wird immer besser. Motiviere es mit Gegenständen in verschiedenen Farben.'),
  ('70597740-ab51-4b20-b743-042bccb768a6', 'Morgengymnastik 🐢', 'Die Bauchlage stärkt die Nackenmuskulatur. Übt sie jeden Tag für kurze Zeit, auch wenn dein Baby dabei weint.'),
  ('81a8fffa-561b-48b8-9be0-ff9b930a7bac', 'Gefühle rauslassen 📝', 'Wächst dir heute alles über den Kopf? Schreib all deine Sorgen und deine Erschöpfung ins Stimmungstagebuch. Unterdrücke deine Gefühle nicht.'),
  ('87db18be-f6b3-443d-9d07-0e305836d90b', 'Ein Hoch auf Tag 110! 🥂', 'Seit genau 110 Tagen kümmert ihr euch um ein neues Leben. Bedankt euch heute Abend beieinander und genießt gemeinsam die Ruhe.'),
  ('088b061c-e51f-4931-8636-b06152d7eaff', 'Bringt dich etwas durcheinander? 🤖', 'Statt stundenlang in Foren zu lesen, stell deine Frage Anacan AI und erhalte schnell eine Antwort.'),
  ('5e878638-6613-43f0-b734-dd308940758d', 'Noch 5 Tage bis zum 4. Monat! 🎂', 'Wenn ihr die Tradition habt, ein Foto mit einer Torte zu machen, ist jetzt genau der richtige Zeitpunkt, sie zu bestellen.'),
  ('616fd04c-b736-454a-9242-b3c011b0cdc5', 'Keine Geduld mehr und müde Arme? 👨‍👧', 'Überlass das Kind heute Abend dem Papa, schließ die Tür und nimm dir 15 Minuten nur für dich.'),
  ('232de7cd-2ff6-4b62-8cee-002063d545fd', 'Chaotisches Paradies 🌪️', 'Liegen überall im Haus Babysachen herum? Lass sie ruhig liegen. Ein unordentliches Zuhause bedeutet nicht, dass du eine schlechte Mutter bist, sondern dass dein Baby für dich an erster Stelle steht.'),
  ('2cbef83d-a5f1-4b69-858b-9d1310e2cac3', 'Genug davon, zu Hause zu sein? ☕', 'Genug davon, zu Hause zu sein? Wähle bei den kinderfreundlichen Orten ein Café in deiner Nähe aus, das du bequem mit dem Kinderwagen besuchen kannst.'),
  ('ff5950e2-aed4-41ca-bc9a-64a1b039968a', 'Zeit für ein magisches Märchen 🪄', 'Erstelle in den magischen Märchen eine besondere Geschichte für heute Abend: die Geschichte eines mutigen Kleinen, das über den Wolken schläft.'),
  ('1063f207-152c-4454-9267-2e05e30929d8', 'Clevere Stille 🤫', 'Wacht dein Baby beim Einschlafen durch plötzliche Geräusche auf? Mit einem Schallpegelmesser kannst du die Lautstärke im Zimmer im Blick behalten.'),
  ('17c1a37e-ab5c-4032-afa2-27e4d0964076', 'Hungrig oder müde? 😭', 'Weint dein Baby scheinbar grundlos und klingt sein Weinen anders als sonst? Vielleicht hat es keinen Hunger, sondern ist einfach übermüdet. Behalte seinen Schlafrhythmus aufmerksam im Blick.'),
  ('93512cbe-adab-49c7-8e82-4466bf0e00ad', '10 Minuten für Mama ☕', 'Stürz dich nicht gleich auf die Hausarbeit, sobald dein Baby schläft. Setz dich aufs Sofa, trink deinen Kaffee und gönn dir 10 Minuten Ruhe – auch wenn du dabei einfach nur die Wand anschaust.'),
  ('8bc219eb-803c-491e-9625-0efec17a7dad', 'Übergib die nächste Schicht 🛋️', 'Wenn du dich am liebsten ebenfalls ins Bett fallen lassen möchtest, sobald dein Baby schläft, überlass die anderen Aufgaben im Haushalt deinem Partner oder deiner Partnerin. Deine Gesundheit ist wichtiger als alles andere.'),
  ('924ff591-18ec-4c20-80af-4008cda2fc41', 'Verschiedene Töne 🗣️', 'Die Laute deines Babys werden immer lauter und abwechslungsreicher. Hör aufmerksam zu, ahme sie nach und bring dein Baby damit zum Lachen.'),
  ('be9ad5fd-195c-40e7-99c6-7f5f91e01526', 'Gedächtnisstütze 🛒', 'Hat der Schlafmangel dein Gedächtnis geschwächt? Versuch nicht, dir alles zu merken, was ihr zu Hause braucht – schreib es einfach auf die Einkaufsliste.'),
  ('37346c6c-3239-4e07-bcc0-24af9be99f3f', 'Sabberalarm 🤤', 'Ist der ganze Ausschnitt innerhalb von Sekunden nass? Das Zahnfleisch bereitet sich langsam aufs Zahnen vor. Silikonlätzchen sind jetzt die besten Retter.'),
  ('86a98c8a-884a-4567-83c1-4d206dccead9', 'Frische Luft wirkt Wunder 🌳', 'Wenn dein Baby sehr unruhig ist, geh direkt mit ihm an die frische Luft. Frische Luft ist oft das einfachste und wirksamste Mittel gegen solche Unruhephasen.'),
  ('ae291c04-b5c7-4ff1-937e-2b2b6d502624', 'Wir sind ein Team! 💖', 'Setzt euch nach einem schwierigen Tag zusammen und sprecht offen über das, was euch belastet. Gegenseitige Unterstützung halbiert die Last.'),
  ('5fcfd433-5086-40d6-89d5-0d756fb06e17', 'Die Kraft der Musik 🎶', 'Versuche, scheinbar grundloses Weinen am späten Nachmittag mit ruhiger klassischer Musik zu lindern. Das hilft erstaunlich oft.'),
  ('b4113857-b164-4ab8-b41d-4e516341edad', 'Dein Baby versucht es! 🤸‍♂️', 'In der Bauchlage stützt es sich auf seine Arme und versucht, nach oben zu schauen. Seine Muskeln werden von Tag zu Tag stärker – bravo!'),
  ('ec61705b-0071-49b5-a6b0-3849dfa461ac', 'Die Zeit anhalten 📸', 'Dein Baby wächst so schnell ... Zieh ihm etwas Schönes an und halte diesen Moment bei einem Baby-Fotoshooting für immer fest.'),
  ('2226c745-19bb-4270-8e5c-a438c71816d4', 'Was machen andere Mütter? 💬', 'Machst du dir Sorgen? Tritt der Anacan-Community bei und stelle deine Frage. Glaub uns: Alle Mütter machen ähnliche Erfahrungen.'),
  ('31bb23a0-6713-4c06-9f74-65b7a51a3dd9', 'Eine beruhigende Stimme 📖', 'Lies deinem Baby heute Abend einfach mit deiner eigenen Stimme eine kurze Geschichte vor. Du brauchst nichts weiter – Mamas Stimme ist der größte Zauber.'),
  ('34253cb9-0e01-47a7-9def-03c3b3e05aba', 'Spiel und Spaß 🎈', 'Macht dein Baby im Liegen mit den Beinen Fahrradbewegungen in der Luft? Das ist sein neuer Lieblingsspaß. Mach mit und kitzle dein Baby dabei.'),
  ('4eb27952-4f25-4c0d-8e25-cf21169fe3eb', 'Achte auf dich 🥑', 'In der Zeit nach der Geburt können Knochen und Zähne empfindlicher sein. Achte darauf, genügend Kalzium über deine Ernährung aufzunehmen. Pass gut auf dich auf.'),
  ('5e90ebc0-15bf-465f-ae64-eff8a7b0a00c', 'Heute Morgen mit nichts zufrieden? ☁️', 'Vielleicht steckt dein Baby gerade in einem Wachstumsschub. Nimm es einfach öfter in den Arm und gib ihm ein Gefühl von Geborgenheit.'),
  ('813f6345-1636-47fd-9a6b-aee16d069800', 'Müdigkeitssignale 🥱', 'Warte nicht, bis dein Baby sich die Augen reibt und gähnt. Sobald sein Blick ins Leere geht, solltest du mit der Schlafroutine beginnen.'),
  ('0fa7eced-c60c-4055-8da1-5df4e54ec1ce', 'Ich kann sprechen! 🗣️', 'Bildet dein Baby Silben wie „Ba-ba“ oder „Ma-ma“? Öffne den Entwicklungs-Tracker, halte diesen großen sprachlichen Fortschritt fest und sprich ganz viel mit deinem Baby.'),
  ('19b9faef-1d59-42d5-bcb0-12290f627a1f', 'Ein Moment der Ruhe ☕', 'Das Chaos im Zimmer läuft dir nicht davon. Während dein Kind selbstständig spielt, trink einfach deinen Kaffee und genieße die Ruhe im Raum.'),
  ('65cb82a7-67e0-48b5-80b8-74e806b2980e', 'Euer ganz persönliches Märchen 🪄', 'Öffne heute Abend die intelligenten Märchen, erstelle ein persönliches Märchen für dein Kind und lies es ihm vor.'),
  ('290cd0a7-b2db-4a34-8b28-f8d9bbc37b62', 'Bleibt dein Baby länger in Bauchlage?  🐢', 'Seine Muskeln werden von Tag zu Tag stärker. Lege ein buntes Spielzeug vor dein Baby, um das Training noch unterhaltsamer zu gestalten.'),
  ('431c0c7a-2968-4edd-9882-df9a926adf72', 'Ein Wasserfall aus Sabber 🤤', 'Ist der Kragen deines Babys neuerdings ständig nass? Halte unbedingt einen Beißring aus Silikon griffbereit.'),
  ('5817fca0-3cbb-4276-a47d-9383c042597d', 'Dezibelkontrolle 🤫', 'Erschreckst du bei jedem Geräusch im Haus, wenn dein Kind schläft? Aktiviere den Schallpegelmesser, überprüfe die Raumakustik und schütze so seinen Schlaf.'),
  ('72b166c9-a8f9-4dc5-be7f-5911ccda18ea', 'Immer mehr Lachen 😂', 'Dein Baby reagiert auf alles, was du Lustiges machst, mit herzhaftem Lachen. Vergiss nicht, diesen wundervollen Moment auf Video festzuhalten!'),
  ('968ec1c9-36e5-4127-8374-922149e153dc', 'Die Basis für guten Schlaf ⏱️', 'Im vierten Monat ist es besonders wichtig, eine gute Schlafroutine zu entwickeln. Halte konsequent daran fest, damit eure Nächte ruhig bleiben.'),
  ('e3d8f3ea-e67f-48ce-87e1-b51ae00dba4f', 'Alles ist in Ordnung ✔️', 'Manchmal denkst du vielleicht, dass du nichts schaffst. Aber sieh dir die saubere Kleidung und das satte Bäuchlein deines Babys an. Du machst das großartig!'),
  ('4f713889-2b51-4db7-8d5d-7ee8676555a4', 'UNGLAUBLICHE 4 MONATE! 🎉', 'Kannst du es glauben? Seit genau 120 Tagen geht ihr diesen magischen Weg gemeinsam! Halte diesen Moment mit einem Baby-Fotoshooting als Erinnerung fest!'),
  ('8d072236-96cb-4886-b83d-b2d8d6523abb', 'Blick zurück 📈', 'Erinnere dich an deine Ängste in den ersten Tagen. Und nun sieh, was für eine erfahrene Mama du geworden bist. Sei stolz auf dich!'),
  ('cfb7b283-3b96-44ef-84b8-0eca1ae74852', 'Sei stolz auf diese 4 Monate.  🥂', 'Vergiss nicht, heute Abend, wenn euer Baby schläft, gemeinsam mit deinem Partner euren Erfolg als Team zu feiern!'),
  ('0140116f-1e50-4656-93a0-277a1645b1ba', 'Gefühle rauslassen 📝', 'War es ein anstrengender Tag? Schreib dir im Stimmungstagebuch ganz offen alles von der Seele, was dich belastet.'),
  ('1f632261-0ec6-4f1f-be74-71aaaaf4c706', 'Gehen die Vorräte zur Neige? 🛒', 'Gehen die Windeln oder Feuchttücher aus? Füge sie gleich der Einkaufsliste hinzu, damit dein Partner eine Benachrichtigung auf sein Handy bekommt.'),
  ('f2dc5d57-91a4-45de-b81b-0b2998a8593b', 'Fröhliches Kinderlachen 😂', 'Antwortet dein Baby auf deine niedlichen Grimassen und Gesten mit lautem Lachen? Halte dieses Lachen unbedingt in einem Video fest.'),
  ('1c68be5f-505e-4c46-be58-571a7196e98d', 'Teile deine Erfahrungen 💬', 'Fragst du dich: „Geht es nur mir so?“ Tritt der Anacan-Community bei und tausche dich mit Müttern aus, denen es ähnlich geht.'),
  ('4b6ccde7-7cce-4142-8822-fa952592f465', 'Müdigkeitssignale 🥱', 'Reibt sich dein Baby die Augen oder zieht es am Ohr? Warte nicht, bis es vor Müdigkeit quengelig wird: Verdunkle gleich das Zimmer und beginne mit der Abendroutine.'),
  ('7b3662bc-d715-468b-a32f-326c023ef66e', 'Kleiner Dreh-Champion 🤸‍♂️', 'Versucht sich dein Baby vom Rücken auf den Bauch und wieder zurückzudrehen? Lass es niemals allein auf dem Bett und genieße diese bewegungsreiche Phase.'),
  ('df219eb3-fe33-48d7-81df-3e2d39df4620', 'Was du alles schaffst! 💖', 'Schau in deine müden Augen im Spiegel und lächle. Ganz ohne Bedienungsanleitung lässt du ein kleines Wunder heranwachsen!'),
  ('f8c399ff-a31e-4e77-a55d-5aab198bafaa', 'Zeit für frische Luft ⛅', 'Finde mit dem Wetter- und Kleidungs-Tool in Sekundenschnelle das passende Outfit für das aktuelle Wetter und genieße die frische Luft.'),
  ('fb3d810e-9135-4194-bb47-9ce9e588d70c', 'Papas starke Schultern 👨‍👧', 'Heute Abend ist Papa dafür zuständig, das Baby herumzutragen und ihm beim Bäuerchen zu helfen.'),
  ('09081d67-84a7-403e-b876-3cc97106eb52', 'Kleiner Greifprofi 🧸', 'Greift dein Baby schon ganz gezielt nach hängenden Spielsachen? Seine motorischen Fähigkeiten entwickeln sich großartig. Beobachte seine Versuche liebevoll und ermutige es dabei.'),
  ('15b0ec22-2156-4080-ad64-7a588de85fc5', 'Lass dich von der Unordnung zu Hause nicht stressen. 🌪️', 'Deine Priorität ist kein perfektes Zuhause, sondern ein gesundes und glückliches Baby. Entspann dich.'),
  ('e8181dea-ccff-4ba2-ae33-93fa07ea8c28', 'Hast du eine Frage? 🤖', 'Bist du bei den Themen Schlaf, Ernährung oder Blähungen unsicher? Verschwende keine Zeit in Foren – schreib einfach der Anacan AI und erhalte eine konkrete, wissenschaftlich fundierte Antwort.'),
  ('0aded6bb-b0fa-4cac-b297-4311bcd7f798', 'Du musst nicht alles schaffen. 🌸', 'In den liebevollen Augen deines Babys bist du das vollkommenste Wesen der Welt.'),
  ('658bd674-cc84-4d51-8a7e-822b9255b9d7', 'Entdeckt ein neues Märchen 📖', 'Macht diesen Abend zu etwas Besonderem. Erstellt in den smarten Märchen eine Geschichte über eine Meerjungfrau auf Entdeckungsreise in der Unterwasserwelt und erfüllt das Zimmer mit Magie.'),
  ('b8b57297-f4b4-4473-87af-9acfeee74dd3', 'Nicht hungrig – was ist dann los? 🧩', 'Dein Baby lässt sich einfach nicht beruhigen? Hör auf zu rätseln: Lass die Schreianalyse den Laut auswerten und finde sofort heraus, was dahintersteckt.'),
  ('9ce62e84-5124-421b-bdd6-3fa7c590aa1a', 'Eine neue Welt der Farben 👀', 'Dein Baby sieht Farben jetzt lebendiger und deutlicher. Zeig ihm Spielzeug in kontrastreichen Farben.'),
  ('b42e7a75-4fab-45bd-89fe-f334b8181757', 'Vergiss dich selbst nicht 🍲', 'Ist dein Baby satt, bist du an der Reihe. Wähle aus den gesunden Rezepten einen energiereichen Snack, der in 10 Minuten zubereitet ist, und tu dir etwas Gutes.'),
  ('cf65b961-f3be-4509-9af3-0b6c17f757e7', 'Papa-Baby-Zeit 🫂', 'Auch Papas sollten viel Körperkontakt mit dem Baby haben. Lass die beiden abends Zeit zu zweit verbringen – so können sie eine enge Bindung aufbauen und du kannst dich ausruhen.'),
  ('0ed5ca13-9d93-489b-99e3-a198862dd467', 'Schlafregression? 🤖', 'Wacht dein Baby nachts plötzlich häufiger auf? Vielleicht macht es gerade einen Entwicklungssprung. Erfahre von Anacan AI mehr über die Schlafregression im Alter von 4–5 Monaten.'),
  ('450e1ee4-0ee2-4568-acc9-22677b87903d', 'Es schaut mich an! 📸', 'Egal, wo du dich im Raum befindest, dein Baby folgt dir mit den Augen.'),
  ('696eaa28-30b3-4a02-87e3-0cd00d185f07', 'Nur 10 Minuten 🛀', 'Dein Baby schläft und endlich ist es still. Statt den Geschirrspüler auszuräumen, stell dich unter die warme Dusche und lausche 10 Minuten lang dem Rauschen des Wassers.'),
  ('27873a53-69de-4c27-a20c-c15256739b9a', 'Wir sind ein Team! 🌟', 'Bist du müde vom nächtlichen Aufwachen? Scheue dich nicht, den Papa zu wecken. Ein Team zu sein bedeutet, die Last liebevoll zu teilen.'),
  ('77e7ae70-0ff1-4b56-a2eb-2e4ed43e460c', 'Überraschungswetter ⛅', 'Lass dich beim Spazierengehen nicht vom Wetter täuschen, damit dein Baby sich nicht erkältet. Mit dem Wetter- und Kleidungsassistenten findest du ganz einfach die passende Kleidung für die Bedingungen draußen.'),
  ('82b46290-c3d6-4ad5-8d94-600e0311ba33', 'Ich will auf den Arm 🛋️', 'Dein Baby möchte gar nicht mehr von deinem Arm herunter? Das ist kein Verwöhnen – es braucht deinen vertrauten Geruch. Drück es fest an dich, denn diese Zeit vergeht schnell.'),
  ('132a3a1b-1001-4fec-a775-7883117a6988', 'Wie läuft eure Routine? 📈', 'Sieh dir die Statistiken der letzten Tage im Ernährungs- und Schlaf-Tracker an und werte sie aus.'),
  ('61f15500-8617-42e1-b833-c482f6ae935c', 'Wirft dein Baby sein Spielzeug oft auf den Boden? 🧸', 'So lernt es den Zusammenhang zwischen Ursache und Wirkung kennen. Unter „Empfohlene Produkte“ findest du neue Spielsachen.'),
  ('92d9f590-3160-4e15-966d-3ee82f9db1d0', 'Entdeckungsreise mit dem Mund 🦷', 'Kaut dein Baby intensiv auf allem herum, besonders auf seinen eigenen Fingern? Der Zahnungs-Tracker schlägt Alarm! Zeit, saubere Beißringe bereitzulegen.'),
  ('02654c5d-e5dc-4168-b20f-e995771e2a24', 'Gemeinsam sind wir stark 💬', 'Schau heute Abend in der Anacan Community vorbei und tausche dich mit Müttern aus, deren Babys im selben Monat geboren wurden. Teilt eure Entwicklungsschritte und Erfahrungen miteinander.'),
  ('158eaa65-78bb-40d6-8e0b-a66fa8dda6b3', 'Sei stolz auf dich 👏', 'Schau dich im Zimmer um und denk daran, wie weit du gekommen bist. Die Unsicherheit der ersten Wochen ist echtem Selbstvertrauen als Mutter gewichen. Du bist großartig!'),
  ('50a6a489-6955-49c4-9f2c-e768f813dd17', 'Zehen im Mund 👣', 'Dein Baby entdeckt seine Füße und versucht, sie in den Mund zu stecken! Halte diesen lustigen und wunderbaren Entwicklungsmoment unbedingt fest, um ihn mit deinen Liebsten zu teilen.'),
  ('4a91e0c3-a4cb-4e5c-b68a-474b7d153369', 'Zähl weiter die Windeln! 🧷', 'Dokumentiere die täglichen Windeln in Anacan, um sicherzugehen, dass dein Baby genug Nahrung bekommt.'),
  ('4d4822a8-2d08-4775-b1d8-71202fa22509', 'Energie für Mama 🔋', 'Beim Stillen verbrauchst auch du Kalorien. Probiere jetzt unter „Gesunde Rezepte“ eine leichte Suppe, die deine Milchbildung unterstützt.'),
  ('dac4f6ca-f7b7-40a3-a427-dece1b15eaf7', 'Wir verfolgen Größe und Gewicht! 📏', 'Aktualisiere die letzten Werte im Entwicklungs-Tracker und freue dich über die gesunde Entwicklungskurve deines Babys.'),
  ('648c9f9b-15f6-49e6-933c-3da395b58c88', 'Hartnäckige Versuche 🐢', 'Versucht dein Baby in Bauchlage vorwärtszukommen und wird dabei ungeduldig? Es möchte sich jetzt fortbewegen! Motiviere es mit Spielzeug, sich nach vorn zu ziehen.'),
  ('903de81c-9443-4b1e-8662-d8cbed1ca54e', 'Jetzt kommen die Beißringe zum Einsatz! 💧', 'Dein Baby möchte alles in den Mund nehmen. Schau in den Blogs vorbei, um mehr über Sicherheit und Entwicklung zu erfahren.'),
  ('9dd94bee-b76e-43ec-94c9-51937e10ad6e', 'Heute wird nicht geputzt 🛑', 'Bist du müde? Sag deinem Partner Bescheid. Heute gibt es kein selbst gekochtes Essen und es wird nicht geputzt. Heute ist einfach Mamas Ruhetag!'),
  ('25015c8c-0ca6-43bc-a465-c8490ee6d808', 'Es ist ganz vernarrt in dich! 🥰', 'Schaut dein Baby dir beim Stillen oder Essen tief in die Augen? Es entdeckt deine Gesichtszüge und liebt dich sehr!'),
  ('565cbb4c-39dd-4c69-980a-b02d63f6cdb4', 'Ein bisschen Entspannung 🛋️', 'Halte nach einem anstrengenden Tag deine Gefühle im Stimmungstagebuch fest. Schreiben und sich alles von der Seele reden kann manchmal die beste kostenlose Therapie sein.'),
  ('f0338702-1ba5-495b-840d-9ad790085c24', 'Der Kinderarzt in deiner Tasche 🤖', 'Hat der Stuhl deines Babys eine ungewöhnliche Farbe oder entdeckst du einen kleinen Ausschlag auf seiner Haut? Bevor du in Panik gerätst, schreib der Anacan AI und informiere dich über mögliche Ursachen.'),
  ('5996a5e8-c639-4f34-8f02-ccaebf8a96eb', 'Die Hände sind im Einsatz 👐', 'Versucht dein Baby, größere Gegenstände gleichzeitig mit beiden Händen zu greifen? Halte diesen Entwicklungsschritt im Entwicklungstracker fest und probiere es mit einem weichen Ball aus.'),
  ('6dd3138c-1bd5-4dac-80d8-a5b5ffa166ee', 'Ist deinem Baby kalt oder warm? ⛅', 'Ist die Kleiderwahl immer wieder eine Herausforderung? Das Wetter- und Kleidungstool sagt dir genau, wie viele Schichten dein Baby braucht. Mach dir keinen Kopf.'),
  ('a1ca42ca-05ed-42dc-af4a-99af31043623', 'Der Zauber von Mamas Stimme 🎶', 'Keine App kann Mamas Wiegenlied ersetzen. Drück dein Baby heute Abend einfach an deine Brust und sing ihm leise sein liebstes Schlaflied vor.'),
  ('b0613bc2-510c-4582-8829-fd09f1ed2898', 'Interesse am Essen? 🍽️', 'Schaut dein Baby beim Essen aufmerksam auf deinen Teller und deinen Mund? Langsam beginnt es, sich für feste Nahrung (Beikost) zu interessieren!'),
  ('cd2a678b-9234-4910-9725-95b0b9e3443e', 'Die Abendroutine ist die Fahrkarte in den Schlafzug.🚂', 'Ein warmes Bad, eine Massage und ein abgedunkeltes Zimmer ... Behalte diese Routine unbedingt bei.'),
  ('cfb5c864-525c-4db1-869c-94c18824f78e', 'Iss dein Mittagessen im hektischen Alltag nicht im Stehen. 🥑', 'Bereite nach einem unserer gesunden Rezepte einen einfachen Salat zu, setz dich hin und genieße ihn in Ruhe.'),
  ('3325dc87-cd45-494c-a42f-d923bde10bc2', 'Ein Lachen für die Kamera 📸', 'Dein Baby lacht jeden Tag mehr! Öffne das Baby-Fotoshooting und halte heute sein fröhliches Lachen fest, das jede schlechte Stimmung vertreibt.'),
  ('37ba096d-4d60-4d73-9c8d-1e0fc44ce8b8', 'Ein beruhigendes Märchen 🪄', 'Erstelle in den intelligenten Märchen eine Geschichte über den kleinen Helden, der sich auf den 5. Monat vorbereitet, und zaubere eine liebevolle Atmosphäre ins Zimmer.'),
  ('b25cbe8a-634a-4863-b56c-19ebbb878905', 'AUF IN DEN 5. MONAT! 🎂', 'Achtung! In nur 10 Tagen ist der große Tag da – dein Baby vollendet seinen 5. Monat! Hast du daran gedacht, eine besondere Torte zu bestellen oder ein Motto zu planen? Beginne schon jetzt mit den Vorbereitungen!'),
  ('0b47b1a5-bf87-49ea-bae7-b0bb8b0e46f2', 'Dein Baby lässt sich nicht beruhigen und du bist völlig erschöpft?  🛑', 'Lege dein Baby sicher ins Bettchen und geh für 5 Minuten in ein anderes Zimmer. Auch du hast das Recht, einmal durchzuatmen.'),
  ('1f6b52bc-5331-4372-8c65-f0f6ee109098', 'Geräuschanalyse 😭', 'Du kommst zurück ins Zimmer und dein Baby weint immer noch. Verzweifle nicht! Lass die Weinanalyse das Weinen sofort analysieren, finde heraus, was dein Baby braucht, und beruhige es.'),
  ('90149fde-54c0-4d98-ba95-374230a626e1', 'Die Hände sind ständig im Mund 🦷', 'Kaut dein Baby heftig auf allem herum? Ein warmer, sauberer Waschlappen kann seinem Zahnfleisch guttun.'),
  ('6065edb3-ae62-4429-96cf-e894b4e2c7d8', 'Helden der Nacht 🦸‍♀️', 'Wir wissen, dass euch das nächtliche Aufwachen an die Grenzen bringt. Schreib in dein Stimmungstagebuch, wie erschöpft du bist, und bitte deinen Partner um Unterstützung.'),
  ('ad21218a-5e7d-436c-9c74-264990c096bd', 'Siehst du mich? 🧸', 'Verstecke ein Spielzeug zur Hälfte unter einer Decke. Sucht und findet dein Baby es? Das ist ein großartiger Entwicklungsschritt auf dem Weg zum Verständnis der Objektpermanenz!'),
  ('faba44da-b2fb-4aa7-a374-4d5f04ad9d27', 'Ein Spaziergang muss sein ⛅', 'Prüfe das Wetter- und Kleidungstool, zieh dein Baby passend an und geht mindestens 20 Minuten im Park spazieren. Das tut euch beiden richtig gut.'),
  ('1a9e3246-5c48-4c5d-9be8-b35243065267', 'Was fehlt zu Hause? 🛒', 'Ist das Shampoo alle oder fehlt Babyöl? Du musst nicht lange überlegen. Fülle einfach die Einkaufsliste aus – um den Rest kümmert sich dein Partner.'),
  ('6e836ffa-475e-446a-bc5a-eddbd0eeeec4', 'Geräusche filtern 🤫', 'Straßenlärm kann den Tiefschlaf stören. Behalte den Geräuschpegelmesser im Blick und nutze bei Bedarf weißes Rauschen als Hintergrundgeräusch.'),
  ('e31b222d-5c34-45e3-b291-c3f8c8989d13', 'Wunderschön und ganz echt 💇‍♀️', 'Vielleicht hat dein Shirt einen Fleck und deine Haare sind zerzaust. Doch in den Augen deines Babys bist du das schönste Wesen der Welt. Sei nicht so streng mit dir.'),
  ('29aebaa9-a1ae-4a00-8854-a771800bf560', 'Den richtigen Rhythmus finden 🍼', 'Behalte mit dem Fütterungs-Tracker die Fütterungszeiten und Wachphasen im Blick und finde so den perfekten Tagesrhythmus.'),
  ('3942c763-be60-481b-bb4e-1a53687a8d34', 'Papas liebevoller Einsatz 💖', 'Auch er hat den ganzen Tag gearbeitet, doch jetzt ist seine Papa-Schicht dran. Schau zu, wie behutsam er euer Baby zum Schlafen bringt, und genieße diesen glücklichen Moment.'),
  ('3cd07d9d-076c-4523-8ba1-47b8737d6bbf', 'Ich bin hier! 👀', 'Ruf dein Baby von einer Ecke des Zimmers aus beim Namen. Du wirst sehen, wie es sich sofort zur Stimme dreht und dich ansieht. Gehör und Aufmerksamkeit sind hervorragend!'),
  ('46a6fe4d-c7d7-4c66-88f8-3a6a534cd295', 'So klug wie ein Arzt 🤖', 'Kommt dir etwas an den Bewegungen deines Kindes ungewöhnlich vor? Statt beunruhigende Meldungen im Internet zu lesen, erhältst du von Anacan AI eine präzise Antwort.'),
  ('ac9907ff-b075-4451-8252-dbc842968901', 'Ein Schlaflied von Papa 👨‍🍼', 'Im Partnermodus werden die Benachrichtigungen an deinen Partner gesendet. Heute Abend liest er die Gute-Nacht-Geschichte vor und singt das Schlaflied. Du darfst einfach nur zuschauen.'),
  ('aedfce5f-449d-49c9-8f9b-a5ac88f1e750', 'Morgenkonzert 🎶', 'Dein Baby schaut dich mit einem breiten Lächeln an und gibt dabei verschiedene Silben von sich. Gerade veranstaltet es das schönste Morgenkonzert im ganzen Zimmer – hör gut zu!'),
  ('46db3cbc-ae0b-4520-b12e-5586db9977cf', 'Unsicher beim Schlafrhythmus? 🤖', 'Stelle deine Fragen zu den Schlafveränderungen rund um den 5. Monat in der Anacan Community und hole dir Unterstützung von anderen Müttern.'),
  ('b203fb94-1780-44e0-8f8f-1e6840729e68', 'Lautstärke im Blick 🤫', 'Gegen Ende des vierten Monats kann das Einschlafen manchmal schwieriger werden. Öffne den Schallpegelmesser, überprüfe den Lautstärkegrenzwert und dunkle das Zimmer unbedingt ab.'),
  ('d7985574-7fae-4ef9-b025-2442a8b0b3a6', 'Du bist die Beste! 💖', 'Niemand ist perfekt, aber für dein Baby bist genau du die beste Mama.'),
  ('05aab0a6-c49b-4d4d-bd26-b20d5c9af4d5', 'Verpasse die Müdigkeitszeichen nicht 🥱', 'Wenn dein Baby ins Leere starrt, lass sofort alles stehen und liegen. Bring es ins Bett, bevor du sein Schlaffenster verpasst.'),
  ('0ecae509-0e89-4406-80e4-d01161b92754', 'Zahnungshilfe als Retter 🦷', 'Versucht dein Baby, auf allem herumzukauen? Gekühlte Beißringe aus Silikon beruhigen sein Zahnfleisch sofort.'),
  ('60bbb8df-cb46-4930-8422-5f0c6fa7daad', 'Ich kenne dich! 🥰', 'Schenkt dir dein Baby ein ganz besonderes, aufgeregteres Lächeln, wenn du ins Zimmer kommst? Ja, es erkennt dich unter allen anderen wieder und liebt deinen Duft!'),
  ('adbfecc6-7186-41fe-a870-83cf6809ec00', 'Nimm dir Zeit für dich 🛋️', 'Wenn dein Baby schläft, widme deine Zeit nicht dem Haushalt, sondern dir selbst. Das Zimmer darf unaufgeräumt bleiben – wichtig ist, dass du neue Energie tankst.'),
  ('ba61a641-e703-4b01-b161-601cf36add7a', 'Der Zauber der Natur ⛅', 'Ist dein Baby sehr unruhig? Hilft kein Spielzeug? Prüfe das Wetter und seine Kleidung und geh gleich mit ihm an die frische Luft. Die Natur ist das beste Beruhigungsmittel.'),
  ('e97550d4-794b-4a9e-94da-881338077d81', 'Warum weint mein Baby schon wieder? 😭', 'Weinanfälle, deren Ursache du nicht herausfinden kannst, sind kräftezehrend. Quäl dich nicht damit: Nutze die Weinanalyse und entdecke die verborgene Botschaft in der Stimme deines Babys.'),
  ('2e9ea238-ddc7-4932-b1bd-be8b8ed87bc9', 'Energie tanken 🍲', 'Wenn es dir gut geht, geht es auch deinem Baby gut. Such dir bei den gesunden Rezepten ein leckeres Kuchenrezept aus, das dir neue Kraft gibt, und genieße ein Stück zu deinem Kaffee.'),
  ('9ee15fcc-d37a-4d63-9556-1032868e91e8', 'HAST DU DIE TORTE BESTELLT? 🎂', 'In nur 5 Tagen wird dein Kleines 5 Monate alt! Bestell jetzt eine besondere Torte oder ein Outfit zum 5-Monats-Motto!'),
  ('d25e75e7-0029-43b9-b1e7-c401d6b9ca28', 'Smarte Geschichtenerzählerin 🪄', 'Erstelle heute Abend bei den smarten Märchen eine ganz persönliche, emotionale Geschichte darüber, wie schnell dein Kleines bis zum 5. Monat gewachsen ist.'),
  ('6a21d9c4-96ab-4453-9d5f-d8979016e2cc', 'Auf dem Weg zur Selbstständigkeit 🤸‍♂️', 'Kann sich dein Baby schon mühelos vom Rücken auf den Bauch drehen? Seine Muskeln entwickeln sich schnell. Leg es regelmäßig auf eine Spielmatte, damit es sich frei bewegen kann.'),
  ('c057830d-8790-40ec-a09d-53a252d3ee15', 'Lass die Schuldgefühle los 🛑', 'Heute ist dir der Geduldsfaden gerissen und du bist laut geworden? Mach dir keine Vorwürfe. Du bist kein unermüdlicher Roboter. Morgen kannst du es noch einmal versuchen.'),
  ('fd786e6d-a723-4c95-b0ff-52e01e6ccb8a', 'Du bist nicht allein 💬', 'Schau dir an, was andere Mütter von 5 Monate alten Babys in der Anacan Community schreiben. In jedem Zuhause herrschen dasselbe Chaos, derselbe Schlafmangel und dieselbe Liebe!'),
  ('5e32b8c3-c1c2-4dbd-a394-96bbfe39e0ed', 'Die Kraft der Mütter 🤖', 'Schau dich im Raum um und sei stolz darauf, wie du diese 5 Monate gemeistert hast. Wenn du Ängste oder Sorgen hast, schreib Anacan AI und hol dir Unterstützung.'),
  ('792511a4-1d02-4324-a33c-59bacedb4645', 'NUR NOCH 1 TAG BIS ZUM JUBILÄUM! 🎈', 'Morgen ist der große Tag! Ist die Torte zum 5-monatigen Jubiläum fertig und ist die Kleidung gebügelt? Öffne das Baby-Fotoshooting-Tool und mach schon jetzt ein paar Probeaufnahmen!'),
  ('af763c83-7a14-4218-b3c2-49cdc7255b18', 'Tausch dich mit deinem Partner aus 🥂', 'Erinnert euch heute Abend gemeinsam an die ersten Tage und lacht darüber. Ihr habt schon einen langen Weg zurückgelegt!'),
  ('3e771dfa-0468-483a-a4d1-a848e1eff82d', 'GENAU 5 MONATE! 🎉', 'Unglaublich! Seit genau 150 Tagen, also ganzen 5 Monaten, lasst ihr dieses kleine Wunder als Team wachsen. Halte diesen besonderen Tag jetzt mit dem Baby-Fotoshooting fest!'),
  ('8b9fb477-8954-40e0-aa32-b586b125f806', 'Applaus für dich selbst 👏', 'Schau dir noch einmal all deine Notizen und Entwicklungskurven an. Sieh, wie sehr dein Baby gewachsen ist und wie routiniert du inzwischen geworden bist!'),
  ('bd07ae62-d716-4470-a226-d2dc1c918f7c', 'Ein Abend zum Feiern 🪄', 'Spielt heute Abend bei den intelligenten Märchen einfach eine liebevolle Geschichte ab und feiert gemeinsam euren Erfolg als Team!'),
  ('dcb350dc-49ff-4c0f-b6e7-e4777138873a', 'Weinen entschlüsseln 😭', 'Kommt das morgendliche Quengeln von Hunger oder vom Zahnen? Statt zu raten, lass die Schreianalyse die Laute auswerten und finde sofort heraus, was dein Baby braucht.'),
  ('e9e20fa8-2ecc-4e20-8e3b-90ed8d74e1e4', 'Deine Geduld ist am Ende? 👨‍👧', 'Lass heute Abend den Papa das Baby komplett übernehmen, während du deine Kopfhörer aufsetzt und dich ausruhst.'),
  ('eb92cfef-308b-40f6-9214-f36986bb10ba', 'Wir sind ein Team! 🌟', 'Fühlst du dich allein und unverstanden? Atme tief durch. Du bist die stärkste Heldin in diesen turbulenten Tagen und machst das großartig.'),
  ('20b556a3-1b9a-4c51-bc18-a68bea6af134', 'Absolute Ruhe 🤫', 'Fällt das Einschlafen schwer? Prüfe mit dem Schallpegelmesser die Lautstärke im Zimmer. Schalte den Fernseher stumm und verdunkle den Raum vollständig.'),
  ('5cbbbe44-8dae-45f7-8369-18aae825551b', 'Juckendes Zahnfleisch? 🦷', 'Hat dein Baby ständig die Finger im Mund und speichelt viel? Dann ist es Zeit für gekühlte Beißringe.'),
  ('f00bd5bd-287a-46fb-8532-9655a797aab3', 'Vergiss dich selbst nicht 🥑', 'Hast du beim Füttern deines Babys vergessen, selbst zu essen? Wähle aus den gesunden Rezepten eine energiespendende Mahlzeit, die in 10 Minuten zubereitet ist.'),
  ('2668e59c-6b79-42c7-903c-24806c9559de', '10 Minuten für Mama ☕', 'Das Chaos zu Hause läuft dir nicht davon. Stürz dich nicht sofort in die Hausarbeit, sobald dein Baby schläft. Mach dir einen heißen Kaffee und schau einfach 10 Minuten lang nur an die Wand.'),
  ('99274040-6797-4a0d-b6f8-4369e3e3436d', 'Von Hand zu Hand 🧸', 'Kann dein Baby ein Spielzeug von einer Hand in die andere geben? Das zeigt, wie gut seine beiden Gehirnhälften zusammenarbeiten! Halte diesen großen Entwicklungsschritt im Entwicklungstracker fest.'),
  ('cbbe11e5-f7e4-422b-8d0e-cf2a181684c8', 'Halte deine Stimmung fest 📝', 'Bist du heute sehr müde oder voller Energie? Schreib deine Gefühle ganz ehrlich in dein Stimmungstagebuch. Dir alles von der Seele zu schreiben, wird dir guttun.'),
  ('503f1c6e-f32e-42d4-96c5-cf663fbb57cd', 'Geschichten zum Anhören 🪄', 'Lass uns heute Abend ein wenig neue Magie ins Zimmer bringen. Erstelle bei den smarten Märchen die Geschichte einer mutigen Katze, die zum Mond fliegt, und mach die Einschlafroutine zu einem schönen Erlebnis.'),
  ('b7efef49-9c1d-49fe-9e2d-4889969cd685', 'Natürliches Beruhigungsmittel ⛅', 'Ist dein Baby sehr unruhig und möchte nicht zu Hause bleiben? Prüfe das Wetter, zieh euch passend an und geht direkt in den Park. Frische Luft ist für euch beide die beste Medizin.'),
  ('fa1bb3e3-66d0-4cc7-8d63-61478e045e39', 'Steckt dein Baby wirklich alles in den Mund? 🤤', 'So entdeckt es die Welt. Achte einfach darauf, dass die Gegenstände in seiner Umgebung sauber und sicher sind.'),
  ('5cacab5c-c142-4162-9118-942fa6678db3', 'Hungrig oder müde? 🧩', 'Egal, was du tust, dein Baby hört nicht auf zu weinen? Vielleicht ist es einfach übermüdet. Nutze die Schreianalyse, um herauszufinden, was hinter dem Weinen steckt.'),
  ('92894378-2736-426b-99c1-d408f0e76945', 'Lautstärke im Blick 🤫', 'Wacht dein Baby beim Einschlafen durch plötzliche Geräusche auf? Mit dem Schallpegelmesser kannst du die Lautstärke im Zimmer im Blick behalten.'),
  ('aab86ddb-de4e-46b1-a168-2145a68d243b', 'Mamas Energie 🔋', 'Geht dir mitten am Tag die Energie aus? Entdecke unter den gesunden Rezepten einen Smoothie, der sowohl deine Milchbildung unterstützt als auch neue Energie schenkt.'),
  ('2f79ccaf-9886-4cc5-8de6-c8151fcbc753', 'Die Kraft der Musik 🎶', 'Versuche, scheinbar grundloses Weinen am späten Nachmittag mit langsamer klassischer Musik oder weißem Rauschen zu beruhigen.'),
  ('6ac04f2a-cb0e-47b2-91d7-757e201eec80', 'Überraschungswetter ⛅', 'Lass dich beim Spaziergang nicht vom Wetter täuschen, damit sich dein Baby nicht erkältet. Mit dem Wetter- und Kleidungsassistenten kannst du die passende Kleidung für die Bedingungen draußen auswählen.'),
  ('e458b23e-9cff-4743-b31b-4ce87556944c', 'Interesse an neuen Geschmäckern? 🍽️', 'Kann dein Baby beim Essen den Blick nicht von deinem Teller abwenden? Das können erste Anzeichen dafür sein, dass es bald bereit für feste Nahrung ist. Aber überstürze nichts und warte noch bis zum 6. Monat.'),
  ('4d2be2fb-f7bc-4bd9-a340-7f3c456ff87c', 'Ein Schlaflied für die Nacht 🎶', 'Keine Stimme beruhigt so sehr wie Mamas Stimme. Nimm dein Baby heute Abend einfach an deine Brust und sing ihm leise sein liebstes Schlaflied vor.'),
  ('57873aa1-acb0-439b-98e9-70fd8b575b47', 'Überall im Zimmer liegt Spielzeug? 🌪️', 'Überall im Zimmer liegt Spielzeug? Lass dich von der Unordnung zu Hause nicht stressen. Du bist eine großartige Mama – deine Priorität ist dein Baby, nicht der Haushalt.'),
  ('bb854fb5-befa-49e1-bf95-4f811865fe4f', 'Was machen andere Mütter? 💬', 'Du machst dir Sorgen? Dann schau in der Anacan-Community vorbei. Zu sehen, dass andere Mütter dort die gleichen schlaflosen Nächte und Herausforderungen erleben, kann dir Trost spenden.'),
  ('23720343-b8a6-4414-a95b-f2b2afa5cab1', 'Die Vorräte gehen zur Neige 🛒', 'Sind die Windeln oder das Babyöl aufgebraucht? Belaste deinen Kopf nicht mit Kleinigkeiten. Schreib es auf die Einkaufsliste, damit dein Partner es auf dem Heimweg besorgen kann.'),
  ('77df7526-5d53-4e7e-8d03-ef3224240fd5', 'Hast du eine Frage? 🤖', 'Schwirren dir tausend Fragen zur Entwicklung durch den Kopf? Statt stundenlang Foren zu durchstöbern, frag Anacan AI und erhalte eine kurze, wissenschaftlich fundierte Antwort.'),
  ('ffb2dcc3-196c-4439-b233-ee14c9337ae5', 'Wir behalten die täglichen Windeln im Blick. 🧷', 'Dokumentiere jeden Windelwechsel in Anacan, um sicherzustellen, dass dein Baby genug Nahrung bekommt, und um seine Verdauung im Blick zu behalten.'),
  ('42fb5186-3443-4ea8-b1d1-54ac0c1a9ccb', 'Nächtliches Aufwachen zur Routine machen 😴', 'Mach nicht jedes Mal das Licht an, wenn dein Baby aufwacht. Füttere es mithilfe des Anacan-Timers und begleite es mit weißem Rauschen wieder in den Schlaf.'),
  ('b460ef96-b60f-4ef0-893f-50bb64397d11', 'Heute wird nicht geputzt 🛑', 'Du bist müde? Sag deinem Partner oder deiner Partnerin Bescheid. Heute wird weder gekocht noch geputzt. Heute ist Mamas Ruhe- und Kaffeetag!'),
  ('f10c4519-156b-4eca-8117-28c233b11129', 'Sprich mit mir! 🗣️', 'Hört dein Baby dir aufmerksam zu und macht dabei verschiedene Laute? Dann führt es ein richtiges Gespräch mit dir. Reagiere auf seine Laute und unterstütze so eure Kommunikation.'),
  ('01ae2fd5-6c02-4d2d-8691-089f2f85a502', 'Erste Sitzversuche 🪑', 'Hält dein Baby Kopf und Rücken aufrechter, wenn du es beim Sitzen stützt? Das zeigt, dass seine Muskeln kräftiger werden. Beginne mit kurzen Sitzübungen, bei denen du es gut stützt.'),
  ('3ae0359c-235f-4ea4-9a97-929da4740dc7', 'Raus aus den vier Wänden ☕', 'Fällt dir zu Hause die Decke auf den Kopf? Suche das nächste Café, das du bequem mit dem Kinderwagen betreten kannst, und genieße deinen Kaffee in einer anderen Umgebung.'),
  ('a66c05d0-980d-472a-8187-902f12cc0e87', 'Müdigkeitssignale 🥱', 'Wenn dein Baby sich die Augen reibt und ins Leere blickt, warte nicht, bis es quengelig wird. Verdunkle sofort das Zimmer und beginne mit der Schlafroutine.'),
  ('297cb03f-f4bc-4fe0-aba8-dc539d62bcce', 'Gemeinsam sind wir stark 🛋️', 'Setzt euch nach einem schwierigen Tag zusammen und sprecht offen darüber, was euch beschäftigt. Wenn ihr euch gegenseitig unterstützt und euch als Team fühlt, wird die Last gleich viel leichter.'),
  ('3f28d490-5c17-44cf-b02a-a0a5ea44e564', 'Sei stolz auf dich 👏', 'Denk daran zurück, wie unsicher du in den ersten Wochen warst. Und jetzt meisterst du alles wie ein Profi! Du bist großartig!'),
  ('bdd2cc62-7f55-4558-bc57-531c376128b9', 'Bald beginnen köstliche Entdeckungen! 🥦', 'Bereite dich auf den nächsten Monat vor und entdecke im Bereich Rezepte die ersten Püree-Ideen für Babys, die mit der Beikost beginnen.'),
  ('1325aee8-211f-49a3-af39-fd0cef6023c0', 'Dein Kinderarzt für unterwegs 🤖', 'Hat sich der Schlafrhythmus plötzlich verändert? Bevor du dir Sorgen machst, kannst du Anacan AI nach Informationen und Tipps zur Schlafregression im 5. Monat fragen.'),
  ('6692c328-0a11-48ba-9a13-0443aeead27c', 'Selbstständiges Drehen 🤸‍♂️', 'Dreht sich dein Baby schon mühelos vom Rücken auf den Bauch? Lege es auf einen großen Teppich, damit es sich frei bewegen und seine Muskeln trainieren kann.'),
  ('e22900db-05e9-4ef6-8e2b-3f0d3690dce5', 'Die Zeit anhalten 📸', 'Dein Baby wächst so schnell ... Halte mit einem Baby-Fotoshooting sein süßes, friedliches Gesicht im Schlaf als liebevolle Erinnerung fest.'),
  ('25b7edd7-55ed-4b9f-b931-91fdbbe75fb4', 'Erfahrungen teilen 💬', 'Hat dich eine neue Bewegung deines Babys überrascht? Tritt der Anacan Community bei und tausche dich mit anderen Müttern über diese Entdeckung aus.'),
  ('6e3db4e0-169c-4b26-92b7-3281435ce439', 'Diese Geschichte ist noch lange nicht zu Ende 📖', 'Gib den schlauen Märchen heute Abend eine zauberhafte Aufgabe: die Geschichte einer Fee, die auf einem Regenbogen schläft.'),
  ('91c0efe1-1cc1-4adc-a7d5-398c2cd0f5c8', 'Du bist gut genug! 💖', 'Heute ist alles schiefgelaufen? Gib dir nicht die Schuld. Bist du etwa ein Roboter? Nein. Nimm deine Gefühle an, verzeih dir selbst und lächle.'),
  ('0a102f68-6cd0-452b-9fa2-0aa24ccb1814', 'Auf dem Weg zum ersten halben Jahr 📈', 'Kaum zu glauben, oder? Bis zum Ende des 6. Monats ist es nicht mehr lange! Öffne den Entwicklungstracker und schau voller Stolz auf den unglaublichen Weg zurück, den ihr bis zu diesem Monat zurückgelegt habt.'),
  ('f295eaa8-f2fa-42e3-9941-4e98a42703f5', 'Übergib die nächste Schicht 🛋️', 'Wenn du dich am liebsten auch sofort hinlegen möchtest, sobald dein Baby schläft, überlass die übrigen Aufgaben im Haushalt deinem Partner oder deiner Partnerin.'),
  ('ff9ff3bc-de2b-4add-9a4b-7f31e78329bd', 'Gedächtnisnebel 📝', 'Vergesslichkeit gehört zur Zeit nach der Geburt dazu. Nutze deine Einkaufsliste regelmäßig, damit dir nichts entgeht.'),
  ('05c1eaa2-4a23-478a-a816-f6e336bf8650', 'Der Freund im Spiegel 👀', 'Setz dein Baby vor einen Spiegel. Wenn es sein Spiegelbild betrachtet und dabei gluckst, ist das eine tolle und unterhaltsame Übung für seine geistige Entwicklung.'),
  ('5e7b7a68-8be5-48ad-9672-e4c1e4de4125', 'Zeit für ein Teamgespräch 🥂', 'Öffne dein Stimmungstagebuch, lass die negativen Gedanken des Tages hinter dir und genieße es, gemeinsam mit deinem Partner ein Team zu sein.'),
  ('d8a2fadb-f854-4f00-9556-bd2eb305be92', 'Zeit für einen Beißring 🦷', 'Der Speichelfluss und der Juckreiz am Zahnfleisch nehmen zu. Saubere Beißringe sind jetzt eure besten Freunde.'),
  ('06a86ce4-2e7a-4f35-a865-7e585114d78f', 'Kannst du mich sehen? 🧸', 'Verstecke ein Spielzeug unter der Decke. Sucht dein Baby danach und findet es? Das ist ein großartiger Entwicklungsschritt auf dem Weg zum Verständnis der Objektpermanenz!'),
  ('478917cd-56f0-483c-b59c-a9eb5ad87e67', 'Papa, der Held der Nacht 🦸‍♂️', 'Die schönste Regel für die ersten Monate: Wechselt euch mit dem Schlaflied ab! Heute Abend kuschelt sich das Baby in Papas Arme und du ruhst dich aus.'),
  ('b31044ce-8042-4a44-af14-b71856994efe', 'Zeit, nach draußen zu gehen 🌳', 'Setz dein Baby in den Kinderwagen und geht an die frische Luft – auch wenn es nur 15 Minuten sind. Ihr beide braucht frische Luft.'),
  ('43a61a10-16d2-4518-b6bc-479ff5985526', 'Morgenkonzert 🎶', 'Dein Baby schaut dich mit einem breiten Lächeln an und probiert neue Laute aus. Gerade gibt es das schönste Konzert im ganzen Raum – hör gut zu!'),
  ('d26efa64-1d4b-4147-ad2c-7a309dc2c5a4', 'Die Basis für guten Schlaf ⏱️', 'Ein warmes Bad, eine Massage und ein abgedunkeltes Zimmer ... Bleib konsequent bei der Schlafroutine, damit eure Nächte entspannt bleiben.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_de = v.t, body_de = v.b
FROM (VALUES
  ('ddef2887-0bec-40c8-91a4-05edb188b86b'::uuid, 'So schlau wie ein Arzt 🤖', 'Statt beunruhigende Beiträge im Internet zu lesen, stell Anacan AI deine Fragen zur Beikosteinführung und finde beruhigende Antworten.'),
  ('6b3cb5c5-1970-4fdc-b099-5f91eda48758', 'Clever leise 🤫', 'Wacht dein Baby beim Einschlafen durch plötzliche Geräusche auf? Überprüfe mit dem Schallpegelmesser die Lautstärke im Zimmer.'),
  ('7bed8f71-075d-414c-be3c-9bf2c4a82ea3', 'Das richtige Outfit bei jedem Wetter 👗', 'Ziehst du dein Baby manchmal zu dünn und manchmal zu warm an? Keine Sorge. Prüfe das Wetter und die Kleidungsempfehlung, damit du dein Baby sicher passend anziehen kannst.'),
  ('dcc95e44-9688-48db-a64f-a544e0720dec', 'Ein Fest für Mama 🥑', 'Iss dein Mittagessen im hektischen Alltag nicht im Stehen. Bereite dir nach einem unserer gesunden Rezepte einen einfachen Salat zu, setz dich hin und genieße ihn in Ruhe.'),
  ('0b493cb3-45ff-4a4a-8782-40ce3d792d2c', 'Achte auf dich 🛋️', 'Wenn dein Baby schläft, solltest du dir Zeit für dich nehmen, statt den Haushalt zu erledigen. Das Zimmer darf ruhig unaufgeräumt bleiben – wichtig ist, dass du neue Energie tankst.'),
  ('6c45dc56-f21e-446c-bca9-3243c5189d5e', 'Wirft dein Baby Spielzeug auf den Boden und beobachtet es? 🎯', 'So lernt es die Schwerkraft und den Zusammenhang von Ursache und Wirkung kennen! Gib ihm das Spielzeug geduldig zurück.'),
  ('fe300d0f-4fab-4b71-8cf4-cb6e9825b2b9', 'Du bist nicht allein 💬', 'Machst du dir Sorgen? Tritt der Anacan-Community bei und stelle deine Frage. Glaub uns: Alle Mütter machen ähnliche Erfahrungen.'),
  ('3cf67221-c8f7-4a51-b0e0-23076d4cd531', 'Vorbereitung auf die Beikost 🥣', 'Bis zum 6. Monat ist es nicht mehr lange. Interessierst du dich schon für die ersten Breie? Frag Anacan AI nach den wichtigsten Informationen zum Beikoststart.'),
  ('9d27d38e-2ae9-4b74-ae13-5eaab2d9f776', 'Gemeinsam stark 🥂', 'Sprecht heute Abend darüber, wie ihr gemeinsam diesen großen Meilenstein erreicht habt. Als Team habt ihr Großartiges geleistet.'),
  ('c09a3abb-6f75-4a5a-99d6-fbc4e4f2425f', 'NOCH 10 TAGE BIS ZUM HALBJÄHRIGEN! 🎂', 'Macht euch bereit! In genau 10 Tagen wird dein Baby 6 Monate alt – also ein halbes Jahr! Jetzt ist der perfekte Zeitpunkt, eine Torte zum Halbjährigen zu bestellen und ein besonderes Outfit auszusuchen!'),
  ('3259939c-e2bd-4126-abc3-d15439051dda', 'Die Kraft der frischen Luft 🌳', 'Wenn dein Baby sehr unruhig ist, geh gleich mit ihm nach draußen. Frische Luft ist das einfachste und wirksamste Mittel gegen solche Unruhephasen.'),
  ('382370f5-d970-4100-b0bc-f8460c0758ae', 'Meisterhaftes Greifen 👐', 'Versucht dein Baby, größere Gegenstände mit beiden Händen gleichzeitig zu greifen? Probiert es mit einem weichen Ball aus.'),
  ('ccbcf153-8cbf-48df-8422-b2c8e63c5f2d', 'Klangvolle Geschichten 🪄', 'Erstelle heute Abend bei den Schlauen Märchen eine Geschichte über einen mutigen Ritter, der schon 6 Monate alt ist.'),
  ('0e21a1c5-4a15-41e9-abfe-8342adaebb92', 'Niemand ist perfekt 🛑', 'War deine Geduld heute am Ende und bist du vielleicht wütend geworden? Mach dir keine Vorwürfe. Schreib deine Gefühle in dein Stimmungstagebuch und lass sie los.'),
  ('31e88909-0b90-49e0-8727-857efb6836f3', 'Ein Schlaflied von Papa 👨‍🍼', 'Aktiviere den Partnermodus, damit dein Partner die Benachrichtigungen erhält. Heute Abend kann er das Schlaflied zum Einschlafen singen.'),
  ('a24757f2-97fa-405f-9959-e4c715aa8ed8', 'Ich suche dich! 👀', 'Sucht dein Baby mit den Augen nach dir und weint, wenn du das Zimmer verlässt? Langsam kann Trennungsangst beginnen. Gib ihm Sicherheit.'),
  ('989db48b-e318-47e6-9019-f4f957b60d59', 'Weinanfälle ohne erkennbaren Grund können ganz schön zermürben. 😭', 'Mach dich nicht fertig. Nutze die Schreianalyse und finde heraus, welche Botschaft in der Stimme deines Babys steckt.'),
  ('a6d43603-e416-4760-8a3f-176e42bf2dc7', 'Kuckuck ist sein Lieblingsspiel! 🙈', 'Verdecke dein Gesicht mit den Händen, zeige es wieder und beobachte, wie sehr sich dein Baby freut. Weitere Spiele dieser Art findest du im Bereich „Blogs“.'),
  ('a85c19d5-09d8-4302-9d52-6f63acdaebee', 'Ein Schlaflied für die Nacht 🎶', 'Keine Stimme wirkt so beruhigend wie Mamas Stimme. Nimm dein Baby heute Abend an deine Brust und singe ihm leise etwas vor.'),
  ('2fc6e816-81b8-4662-85f5-ea7fd4e748a8', '10 Minuten für Mama ☕', 'Das Chaos im Zimmer läuft dir nicht davon. Stürze dich nicht sofort in die Hausarbeit, wenn dein Baby schläft. Gieß dir einen Kaffee ein und entspanne dich einfach 10 Minuten lang.'),
  ('8dd01cdf-8e98-4b6a-91ce-2edcc5e6a4df', 'Störende Geräusche ausblenden 🤫', 'Straßenlärm kann den Tiefschlaf stören. Überprüfe den Geräuschpegel mit dem Schallpegelmesser und nutze bei Bedarf weißes Rauschen.'),
  ('9bb7f096-5daa-4e1c-9f5e-688698945f7a', 'Sind die ersten Zähnchen unterwegs? 🦷', 'Ist das untere Zahnfleisch schmerzhaft oder geschwollen? Die ersten Zähnchen können sich um den 6. Monat herum zeigen.'),
  ('081951c6-0b7d-4045-b641-a4716f751a3d', 'Papas Schultern 👨‍👧', 'Deine Geduld ist am Ende? Aktiviere den Partner-Modus. Heute Abend darf sich der Papa ganz allein um das Kind kümmern.'),
  ('b099b3d8-9148-450c-8795-4ab16ea72b2c', 'Hast du noch Fragen? 🤖', 'Mit welchem Gemüsepüree soll ich anfangen? – Stelle diese und andere Fragen, die dich beschäftigen, der Anacan AI und erhalte zuverlässige Informationen.'),
  ('e3aafd70-c5f0-4254-ba79-e24f4dca3567', 'Ein Wasserfall aus Spucke 🤤', 'Wird das Oberteil deines Babys ständig nass? Halte Beißringe aus Silikon bereit.'),
  ('34eb8ef4-b7a5-4969-916d-abfccb27c775', 'Dezibelkontrolle 🤫', 'Erschreckst du bei jedem Geräusch im Haus, wenn dein Baby schläft? Aktiviere den Schallpegelmesser und überprüfe die Akustik im Zimmer.'),
  ('da48ef6d-1a19-4a32-9bdc-d912779edf22', 'Chaotisches Zuhause, glückliches Kind 🌪️', 'Liegt überall im Zimmer Spielzeug herum? Zehn fröhliche Minuten mit deinem Kind sind wichtiger als eine aufgeräumte Wohnung.'),
  ('ec6f8334-a2ec-4274-9ce3-07c0a3276622', 'Selbstständiges Drehen 🤸‍♂️', 'Kann sich dein Baby schon sicher vom Rücken auf den Bauch und vom Bauch auf den Rücken drehen? Halte diesen Erfolg im Entwicklungstracker fest!'),
  ('2ecd0a8e-2817-4551-98e0-4276739c7da9', 'Wir sind ein Team! 💖', 'Sechs Monate lang habt ihr euch in schlaflosen Nächten gegenseitig unterstützt. Öffne das Stimmungstagebuch und bedanke dich bei deinem Partner für diese Teamarbeit.'),
  ('ce877206-0633-48d8-aa8f-9241cfab27c3', 'Ein Hochstuhl für die Beikost 🪑', 'Denkst du darüber nach, einen Hochstuhl zu kaufen? Sieh dir im Bereich „Empfohlene Produkte“ ergonomische und leicht zu reinigende Hochstühle an.'),
  ('e6e852b1-bfb4-4197-aa7b-70b6b2367f30', 'NUR NOCH 5 TAGE BIS ZUM HALBJÄHRIGEN! 🎈', 'Nur noch 5 Tage, dann ist dein Baby ein halbes Jahr alt! Ist die Torte schon bestellt? Wähle schon jetzt im Tool für Baby-Fotoshootings besondere Rahmen zum 6. Monat aus und plane das Shooting.'),
  ('1297700e-9cfd-4ca4-a9de-fc8b3c3e36fd', 'Ein neues Märchen entdecken 📖', 'Lass uns diesen Abend zu etwas Besonderem machen. Erstelle in den intelligenten Märchen eine persönliche Geschichte und erfülle das Zimmer mit Magie.'),
  ('9d58451e-ede3-4a05-ba21-dd4e0b7f4086', 'Wir beobachten täglich den Windelinhalt. 🧷', 'Dokumentiere vor der Einführung der Beikost jeden Windelwechsel in Anacan, um sicherzugehen, dass die Verdauung gut funktioniert.'),
  ('edc6faba-a997-408a-a40b-e590a39a3721', 'Ich kann sitzen! 🪑', 'Sitzt dein Baby mit Unterstützung schon sicherer? Stütze es mit Kissen ab und ermutige es so zum Sitzen – aber nur für kurze Zeit.'),
  ('27dc11b4-8fdd-4bba-a87f-5fa9b264f28d', 'Müdigkeitssignale 🥱', 'Reibt sich dein Baby die Augen? Warte nicht, bis es vor Müdigkeit quengelig wird: Verdunkle gleich das Zimmer und beginne mit der Abendroutine.'),
  ('a9165256-d8d7-431e-ac72-e7ef065f4e1f', 'Energie für Mama 🍲', 'Für den morgigen großen Tag brauchst du Energie. Wähle aus den gesunden Rezepten einen sättigenden Snack aus und gönn dir etwas Ruhe.'),
  ('febb037e-33e6-4760-bc42-cae9b6c70a8a', 'LETZTE VORBEREITUNGEN! 📸', 'Morgen ist der große Tag! Ist die Torte zum Halbjahresgeburtstag fertig? Lege die schönsten Outfits für das Baby-Fotoshooting bereit – morgen machen wir ganz viele Fotos!'),
  ('1ac47b8c-1167-4ac1-a522-104b832c25b0', 'GENAU 6 MONATE! EIN HALBES JAHR! 🎉', 'Herzlichen Glückwunsch! Seit genau 180 Tagen begleitest du dieses kleine Wunder beim Großwerden. Erstelle jetzt beim Baby-Fotoshooting ein besonderes Bild für diesen Tag und teile es in der Anacan Community!'),
  ('788697fe-7a57-4c4c-a3dc-514298d952ed', 'Applaus für dich 👏', 'Schau dir noch einmal all deine Einträge an. Sieh, wie sehr dein Baby gewachsen ist und wie souverän du inzwischen geworden bist! Ihr seid ein großartiges Team.'),
  ('7f7b88ee-089c-4ccc-9849-c2f4117d4833', 'Ein Abend zum Feiern 🥂', 'Setzt euch heute Abend zusammen, wenn euer Baby schläft. Seid stolz auf diese 180 Tage und nehmt euch fest in den Arm!'),
  ('7d616a8c-c926-4291-9221-42ee50e15fd5', 'Ein neuer Abschnitt: Beikost! 🥣', 'Dein Baby ist jetzt 6 Monate alt! Nun ist es Zeit, erste Gemüsepürees kennenzulernen. Informiere dich bei Anacan AI über die 3-Tage-Regel zum Testen neuer Lebensmittel auf mögliche allergische Reaktionen.'),
  ('936424c3-1b30-4fc1-924e-920162d0d5bd', 'Absolute Ruhe 🤫', 'Fällt deinem Baby das Einschlafen schwer? Prüfe mit dem Schallpegelmesser die Dezibelzahl im Zimmer und dunkle den Raum vollständig ab.'),
  ('e0613a64-c64f-491d-8c87-72276f72849e', 'Fleckige Kleidung 👗', 'Beikost bedeutet, dass überall etwas danebengeht. Ärgere dich nicht darüber, verwende Silikonlätzchen und genieße diese lustigen Momente.'),
  ('6dad4f0a-8c98-4797-a95f-50aab81d4662', 'Überraschungswetter ⛅', 'Lass dich beim Spazierengehen nicht vom Wetter täuschen und vermeide, dass dein Baby friert. Nutze den Wetter- und Kleidungsassistenten, um die passende Kleidung für draußen auszuwählen.'),
  ('affd2ecc-89d1-4649-8b63-63dfe9a1ced9', 'Ich suche dich! 👀', 'Fängt dein Baby an zu weinen, sobald du das Zimmer verlässt? Die Trennungsangst entwickelt sich jetzt deutlich. Dein Baby fürchtet einfach, dass du nicht wiederkommst. Gib ihm mit deiner Stimme Sicherheit.'),
  ('c4e8f9e9-c94b-41fc-a23a-61a8c7026386', 'Veränderungen bei der Verdauung 🧷', 'Mit der Einführung der Beikost verändert sich auch der Stuhlgang. Dokumentiere jeden Windelwechsel in Anacan, um die Entwicklung im Blick zu behalten.'),
  ('3bd59fce-abbd-4e13-ab2d-4379b5c89cac', 'Isst dein Baby den Brei nicht und spuckt ihn wieder aus?', 'Fühl dich nicht unfähig. Für dein Baby ist das eine völlig neue Erfahrung – hab Geduld.'),
  ('48005ac4-750b-4fca-b0cd-2711d3eb3c21', 'Hörgeschichten 🪄', 'Lass den Tag heute Abend unterhaltsam ausklingen, indem du bei den Smarten Märchen eine Geschichte erstellst.'),
  ('ae1cbea0-aaaf-49ff-9518-967813809e3b', 'Juckendes Zahnfleisch? 🦷', 'Mit der Einführung der Beikost können auch die Beschwerden beim Zahnen zunehmen. Verwende ein Zahnungsgel nur nach ärztlicher Rücksprache.'),
  ('4beff801-d69f-40c0-bed1-2e8938edb5f2', 'Was machen andere Mütter? 💬', 'Dein Baby mag keinen Kürbisbrei? Tritt der Anacan-Community bei und entdecke die Erfahrungen und vielfältigen Rezepte anderer Mütter.'),
  ('7df7f58f-05e6-4afb-aa2c-73438e6504d4', 'Müdigkeitssignale 🥱', 'Wenn dein Baby sich die Augen reibt und ins Leere schaut, warte nicht, bis es übermüdet und quengelig wird. Verdunkle sofort das Zimmer und beginne mit der Schlafroutine.'),
  ('8afe4995-9e98-44a1-a9cc-5c970d87a396', 'Erste Versuche, frei zu sitzen 🪑', 'Lehnt sich dein Baby schon weniger an die Kissen? Schon bald wird es ganz ohne Unterstützung sitzen!'),
  ('34c92908-0941-4c15-a946-75240f0ea7f7', 'Teile deine Stimmung 📝', 'Bist du heute sehr müde? Schreibe deine Gefühle ganz ehrlich in dein Stimmungstagebuch. Dir alles von der Seele zu schreiben, wird dir guttun.'),
  ('cd45d0d2-bf31-47be-adf8-84c3b1895339', 'Hat es Schmerzen oder Blähungen? 😭', 'Die Einführung der Beikost kann zu Verstopfung oder Blähungen führen. Wenn sich dein Baby trotz allem nicht beruhigt, nutze die Schrei-Analyse, um herauszufinden, was hinter seinem Weinen steckt.'),
  ('e67730b8-4981-4bba-b868-fe6cf9b7e3da', 'Die Vorräte gehen zur Neige 🛒', 'Brauchst du neues Gemüse für den Brei? Schreib es auf die Einkaufsliste, damit dein Partner auf dem Heimweg von der Arbeit frische Lebensmittel mitbringt.'),
  ('1f9cc7dc-a0b4-41a4-983b-794c5917ee08', 'Von Hand zu Hand entdecken 🧸', 'Kann dein Baby ein Spielzeug ganz mühelos von einer Hand in die andere geben? Seine beiden Gehirnhälften arbeiten hervorragend zusammen. Gib ihm Gegenstände mit unterschiedlichen Oberflächen zum Erkunden.'),
  ('298934a2-9d12-42b8-8c9c-6098d3709ab4', 'Die Unterhaltungen werden länger! 🗣️', 'Da-da-da und ba-ba-ba hallt es durchs ganze Haus. Besuche den Bereich „Blogs“, um mehr über die Sprachentwicklung deines Babys zu erfahren.'),
  ('89ff16e6-d11a-4deb-ae4f-1ba03e76271d', 'Papa, der Held der Nacht 🦸‍♂️', 'Die schönste Regel für die ersten Monate: Beim Vorsingen von Schlafliedern wechselt ihr euch ab! Heute Abend kuschelt dein Baby mit Papa und du ruhst dich aus.'),
  ('6f0575b2-9379-4dca-bf05-d518a93aead1', 'Vergessen, an welcher Brust du gestillt hast? 🤱', 'Halte mit dem Timer fest, ob du an der rechten oder linken Brust gestillt hast – Anacan merkt sich alles für dich!'),
  ('a134dfa9-2e73-4246-a281-0577e4411534', 'Lass dein Baby mit dem Essen spielen! 🥦', 'Lass es das Essen anfassen, zerdrücken und entdecken. Halte diese süßen, chaotischen Momente mit dem Baby-Fotoshooting als Erinnerung fest!'),
  ('d9470e5a-6317-45d8-9bd1-419a7827e3e6', 'So werden nächtliche Wachphasen zur Routine. 😴', 'Schalte nicht jedes Mal das Licht ein, wenn dein Baby aufwacht. Stille oder füttere es mit dem Anacan Timer und hilf ihm mit Weißem Rauschen, wieder einzuschlafen.'),
  ('07efb31a-2639-41f8-b1c7-f3807d010a8f', 'Die Zeit anhalten 📸', 'Es wächst so schnell ... Halte seine süßen, entspannten Gesichtszüge im Schlaf mit dem Baby-Fotoshooting als Erinnerung fest.'),
  ('7deb7b07-a963-4605-b27c-7714e980157d', 'Hast du Fragen? 🤖', 'Schwirren dir tausend Fragen zur Beikost und zur Gabe von Wasser durch den Kopf? Schreib der Anacan AI und erhalte fundierte pädiatrische Ratschläge.'),
  ('ab8df92e-4241-44fb-8ac7-10559ea60a6f', 'Ich kenne dich! 🥰', 'Sucht dein Baby bei dir Schutz, wenn eine fremde Person zu Besuch kommt? Keine Sorge: Es kann vertraute von fremden Menschen unterscheiden. Das ist ein Zeichen gesunder geistiger Entwicklung.'),
  ('17a57fd8-a4e1-4a40-b13f-cad6191dae2a', 'Neue Geschmacksentdeckungen! 🍎', 'Welches Obst oder Gemüse probiert ihr heute? Schau dir unbedingt die Rezepte für Babys an, die mit der Beikost beginnen, und lass dich inspirieren.'),
  ('b98f5eb2-8b81-4c72-8526-61cc728e9e49', 'Die Geschichte geht immer weiter 📖', 'Erfinde heute Abend in den interaktiven Märchen die Geschichte eines mutigen und klugen Kindes.'),
  ('baf623af-022a-4483-b233-e77e915f194b', 'Ein kleiner Vielfraß 🥣', 'Isst dein Baby seinen Brei schon mit Begeisterung? Es wird groß!'),
  ('0ced9920-5225-4ffc-81ba-de83e31f1bd2', 'Morgenkonzert 🎶', 'Dein Baby schaut dich an und erfindet verschiedene Silben. Gerade gibt es das schönste Morgenkonzert im ganzen Zimmer – hör gut zu!'),
  ('db243270-0483-44d0-9aef-b63565c06a9e', 'So klug wie ein Arzt 🤖', 'Hat sich der Stuhlgang deines Babys seit der Einführung fester Nahrung verändert? Statt dir Sorgen zu machen, frag Anacan AI, ob das normal ist.'),
  ('f06a8dcb-51df-4b58-a9ac-01e5154e736a', 'Die Grundlage für guten Schlaf ⏱️', 'Ein warmes Bad, eine Massage und ein abgedunkeltes Zimmer ... Halte konsequent an der Schlafroutine fest, damit eure Nächte ruhig bleiben.'),
  ('5378180a-aa43-4728-9384-08bbcf8838ee', 'Sprich mit mir! 🗣️', 'Spricht dein Baby Silben wie „Ba-ba“ oder „Ma-ma“ schon deutlicher aus? Reagiere auf seine Laute und fördere so eure Kommunikation.'),
  ('a4be80bb-cd06-42ba-b875-78d5a32af3ba', 'Gespräch im Team 🛋️', 'Setzt euch nach einem anstrengenden Tag zusammen und sprecht offen darüber, was euch beschäftigt. Wenn ihr euch gegenseitig unterstützt, wird die Last halbiert.'),
  ('efa880a4-37d0-4521-93db-df2495a01243', 'Sei stolz auf dich 👏', 'Denk daran zurück, wie unsicher du in den ersten Wochen warst. Und jetzt bist du eine echte Brei-Profi-Mama!'),
  ('5be2b9be-dabd-44b8-93f3-30aaaab56ccf', 'Ein Schlaflied für die Nacht 🎶', 'Nichts wirkt so beruhigend wie Mamas Stimme. Drück dein Baby heute Abend einfach an deine Brust und sing ihm leise etwas vor.'),
  ('98621899-f977-46d0-ba01-3a49123c5aef', 'Erste Krabbelversuche! 🐢', 'Dreht sich dein Baby auf dem Bauch im Kreis, robbt rückwärts oder versucht, auf die Knie zu kommen? Halte diese spannenden Entwicklungsschritte gleich im Babyalbum fest.'),
  ('f5a121b8-a795-4ca6-87d9-f17351b40bec', 'Bist du bei der Entwicklung unsicher? 🤖', 'Mein Baby krabbelt noch nicht – ist das normal? Stelle diese und weitere Fragen an Anacan AI und erhalte eine fachlich fundierte Antwort.'),
  ('19aba970-f2bf-4842-9b69-4aed1781aeec', 'Schau mal nach unten! 👣', 'Dein Baby hat seine Zehen entdeckt und steckt sie in den Mund! Beobachte diesen lustigen Moment und genieße diesen Entwicklungsschritt.'),
  ('6b5eb8f2-b9ae-4f72-adf0-630e10588b7d', 'Muttermilch bleibt die wichtigste Nahrung! 🍼', 'Auch nach der Einführung der Beikost solltest du den Ernährungstimer nutzen, um sicherzustellen, dass der tägliche Milchbedarf deines Babys gedeckt ist.'),
  ('c2924eec-8b24-41b0-b28a-f63497f548c2', 'Erfahrungen austauschen 💬', 'Suchst du nach Beikostrezepten? Dann schau im Bereich „Gesunde Rezepte“ vorbei und lass dich inspirieren.'),
  ('2d910805-1ce0-44fc-88f6-f3f6dfe16cea', 'Die Krabbelversuche nehmen zu! 🐢', 'Robbt dein Baby auf dem Bauch rückwärts oder versucht es, sich auf die Knie zu stützen? Halte diese aktiven Entwicklungsmomente im Babyalbum fest.'),
  ('8f5769c4-aeb4-4cd1-acf0-052c7e0df753', 'Zeit für eine smarte Geschichte 🪄', 'Erstelle bei den smarten Geschichten eine ganz besondere Geschichte für heute Abend.'),
  ('f175db80-862d-40e7-9aed-5b0a0c4423e3', 'Wir gewöhnen uns ans Wassertrinken. 💧', 'Vergiss nicht, deinem Baby zur Beikost auch Wasser anzubieten.'),
  ('0e6fe355-3307-4562-8e24-f479625f3ff6', 'Frische Luft tut euch beiden gut. 🌳', 'Sucht euch den nächstgelegenen Park aus und genießt den Tag.'),
  ('4085929a-ec71-4c5c-a693-62bb796910ba', 'Kleiderchaos 👗', 'Ziehst du dein Baby manchmal zu dünn und manchmal zu warm an? Kein Grund zur Sorge. Prüfe das Wetter und die passende Kleidung – dann kannst du dein Baby ganz sicher richtig anziehen.'),
  ('e7ddb2bb-cbd6-4f99-9f52-7fc0bb34e7ba', 'Clevere Ruhe 🤫', 'Wacht dein Baby beim Einschlafen durch plötzliche Geräusche auf? Mit dem Schallpegelmesser kannst du die Lautstärke im Zimmer im Blick behalten.'),
  ('3e7220fc-a665-4ed2-8b95-f202d84e92a8', 'Ich greife selbst danach! 🧸', 'Greift dein Baby schon ganz gezielt nach hängenden Spielsachen? Seine Hand-Auge-Koordination wird immer besser. Motiviere es mit Gegenständen in verschiedenen Farben.'),
  ('747238a1-853b-4e40-a51e-30b2b6d818ac', 'Mach dir keine Vorwürfe 💖', 'Denkst du, dass du zu wenig Zeit mit deinem Kind verbringst? 10 Minuten liebevolle, fröhliche Zuwendung sind wertvoller als 1 stressige Stunde.'),
  ('a8ca5021-abaf-413e-abe5-95d715e5127d', 'Vorbereitung auf einen tiefen Schlaf 🛀', 'Ein lauwarmes Bad, eine sanfte Massage und ein abgedunkeltes Zimmer ... Eine feste Schlafroutine ist Gold wert.'),
  ('14f79c92-38f1-4965-a9d0-fbcb8e236840', 'Sabberalarm 🤤', 'Ist der ganze Kragen innerhalb von Sekunden nass? Das Zahnfleisch bereitet sich aufs Zahnen vor. Verwende Silikonlätzchen.'),
  ('173f7149-2567-449f-9693-a462d1148849', 'Wir sind ein Team! 💖', 'Setzt euch nach einem anstrengenden Tag zusammen und sprecht darüber, was euch beschäftigt. Wenn ihr euch gegenseitig unterstützt, fühlt sich die Last nur noch halb so schwer an.'),
  ('1af66eec-0d7d-4dcd-9326-d4155d237a55', 'Beginnt die Fremdelphase? 🙈', 'Wenn dein Baby weint, sobald es dich nicht sieht oder einer fremden Person begegnet, ist das ein normaler Teil seiner Entwicklung. Lass dich dazu von Anacan AI beraten.'),
  ('23068177-6d18-4649-91f5-5ac9ecb37933', 'Schnelle Antworten 🤖', 'Geht dir etwas nicht aus dem Kopf? Statt stundenlang Foren zu durchstöbern, kannst du Anacan AI deine Frage stellen und schnell eine Antwort erhalten.'),
  ('52b2efdc-0a49-4bfa-8a7e-21a3342254cb', 'Dein Baby versucht es! 🤸‍♂️', 'In der Bauchlage versucht dein Baby, sich nach vorn zu schieben. Seine Muskeln werden von Tag zu Tag stärker. Lege ein Spielzeug vor dein Baby, um es zu motivieren.'),
  ('97716c97-1bb3-4784-acfc-a5f0354d1864', 'Die Kraft der Musik 🎶', 'Wenn dein Baby gegen Abend ohne erkennbaren Grund weint, versuche, es mit langsamer klassischer Musik zu beruhigen.'),
  ('21fef948-0fab-41a2-932d-5efc89cc4b78', 'Die Basis für guten Schlaf ⏱️', 'Ein guter Schlafrhythmus ist sehr wichtig. Haltet euch konsequent an eure Routine, damit eure Nächte entspannt bleiben.'),
  ('29cfcc36-87ce-4b4b-b753-dcd4b0ef2352', 'NUR NOCH 1 TAG BIS ZUM 200. TAG! 🎂', 'Morgen wird dein Baby 200 Tage alt! Hast du schon überlegt, wie ihr diese beeindruckende Zahl feiern möchtet? Beginne mit den Vorbereitungen!'),
  ('76b44761-7bef-4f9c-b984-97e78f4d78cb', 'Alles ist in Ordnung ✔️', 'Manchmal denkst du vielleicht, dass du nichts schaffst. Doch schau dir die saubere Kleidung und das satte Bäuchlein deines Babys an. Du machst das großartig!'),
  ('01da84b5-ee27-4d08-b8e5-12f1d6a1b6e2', 'Schau zurück 📈', 'Erinnere dich an deine Ängste in den ersten Tagen. Und sieh nur, wie sicher du inzwischen mit der Beikost umgehst. Sei stolz auf dich!'),
  ('87133947-89a5-414b-a6d4-637285ff301e', 'GROSSARTIGE 200 TAGE! 🎉', 'Kannst du es glauben? Seit genau 200 Tagen geht ihr diesen magischen Weg gemeinsam! Halte diesen Moment bei einem Baby-Fotoshooting mit einem besonderen Sticker fest und teile das Foto in der Community!'),
  ('e7927d9c-8cbd-4c7d-b3cf-e5df983f4169', 'Sei stolz auf diese 200 Tage. 🥂', 'Vergiss nicht, heute Abend, wenn dein Baby schläft, gemeinsam mit deinem Partner euren großen Erfolg als Team zu feiern!'),
  ('125f59de-0644-435e-8593-de05b7cc7065', 'Gutenachtlieder 🎶', 'Keine App kann Mamas Wiegenlied ersetzen. Nimm dein Baby heute Abend einfach fest in die Arme und sing ihm leise sein Lieblingslied vor.'),
  ('63093c63-3ea0-4bb2-90bb-318617d51b7e', 'Püree-Festival 🥣', 'Sind Gesicht, Nase und sogar die Haare voller Essen? Statt dich zu ärgern, halte diesen süßen Moment bei einem Baby-Fotoshooting für immer fest.'),
  ('9ff73499-a2bd-41b7-96fa-1ec2d780279f', 'Hab kein schlechtes Gewissen 💖', 'Denkst du, dass du zu wenig Zeit mit deinem Kind verbringst oder den Haushalt nicht schaffst? Hör auf, dir Vorwürfe zu machen. Du machst das großartig.'),
  ('5cafdda5-c60b-4328-9530-450093ed8026', 'Absolute Ruhe 🤫', 'Hat dein Baby Schwierigkeiten einzuschlafen? Dunkle das Zimmer vollständig ab und sorge für Ruhe. Dunkelheit und Stille sind seine besten Einschlafhilfen.'),
  ('8ee71700-bb17-4782-940b-c0fc02328f1a', 'Hat sich die Farbe des Stuhls verändert? 💩', 'Mit der Einführung der Beikost sind unterschiedliche Stuhlfarben normal. Wenn du dennoch beunruhigt bist, frag Anacan AI nach möglichen Ursachen.'),
  ('9240cd01-c58e-42aa-be44-a4d2ac461bc2', 'Erschöpft zu sein ist normal 🔋', 'Wenn deine Geduld nachlässt, heißt das nicht, dass du eine schlechte Mutter bist. Diese Erschöpfung ist ganz natürlich.'),
  ('21f7df85-0fd1-4e90-a27b-52045487116f', 'Nächtliches Aufwachen 🌙', 'Wacht dein Baby kurz vor dem Zahnen nachts plötzlich häufiger auf? Hab Geduld, sein schmerzendes Zahnfleisch macht ihm zu schaffen. Lass es spüren, dass du bei ihm bist.'),
  ('3ad2c870-178d-449f-aabd-6c01acacefd8', 'Erste Krabbelversuche 🐢', 'Stützt sich dein Baby auf die Knie und wippt vor und zurück? Es bereitet sich aufs Krabbeln vor!'),
  ('b80481ba-8798-458c-83d8-f359b3802548', 'Ein Moment der Ruhe ☕', 'Das Chaos im Zimmer läuft nicht weg. Wenn dein Kind allein spielt, musst du nicht sofort mit dem Aufräumen beginnen. Setz dich aufs Sofa und tu 10 Minuten lang einfach nichts.'),
  ('104420b5-a415-4abb-81d8-7f7b520d18bd', 'Entdeckungstour am Zahnfleisch 🦷', 'Kaut dein Baby heftig auf allem herum und sabbert viel? Behalte den Zahnungsprozess mit dem Zahnungs-Tracker im Blick. Kühlende Beißringe sind an solchen Tagen die Rettung.'),
  ('c9c8946d-7797-4bd6-8476-9f649f770a6e', 'Wir sind ein Team! 💪', 'Fühlst du dich allein und erschöpft? Atme tief durch. Du und dein Partner seid die stärksten Helden dieser turbulenten Tage.'),
  ('f8790842-2782-419a-aaaa-3c8c1fc497de', 'Wetter und Kleidung ⛅', 'Du musst nicht lange überlegen, was du deinem Baby draußen anziehen sollst. Schau im Wetter-und-Kleidungs-Tool nach, finde in Sekundenschnelle das ideale Outfit und dann ab an die frische Luft.'),
  ('05e938a0-adb4-413b-992b-19bbd78f0925', 'BEREIT FÜR DEN MONATSGEBURTSTAG! 🎂', 'In nur 9 Tagen wird dein Baby 7 Monate alt! Hast du dir für diesen Monat ein besonderes Motto oder eine spezielle Torte überlegt? Fang am besten schon jetzt mit den Vorbereitungen an, damit du nicht alles auf den letzten Tag verschieben musst.'),
  ('9c5c6958-af17-4420-aa80-95cd295c8995', 'Freie Hände 👐', 'Stützt sich dein Baby in Bauchlage auf eine Hand und greift mit der anderen nach einem Spielzeug? Sein Muskelgleichgewicht wird immer besser!'),
  ('acd2495b-eae5-4005-8f31-3fdfdc4738aa', 'Papa ist dran 👨‍👧', 'Übergib den Baby-Dienst heute für eine Weile an deinen Partner. Lass die beiden spielen, während du einfach die Füße hochlegst und dich ausruhst.'),
  ('094a764e-f3f1-4dd1-8a87-04126b16323f', 'Vergiss dich selbst nicht 🍲', 'Dein Baby hat seinen Brei gegessen – und du? Um neue Energie zu tanken, solltest auch du dich gut ernähren. Bestell dir heute eine sättigende Mahlzeit.'),
  ('734bd8a8-49ec-4c9f-bb8c-17a8d1fc50b6', 'Ich kenne dich 👀', 'Klammert sich dein Baby an dich und schaut misstrauisch, wenn Besuch kommt? Die Trennungsangst beginnt. Dein Baby fühlt sich im Moment einfach nur bei seiner Mama sicher – respektiere dieses Bedürfnis.'),
  ('740c028d-4797-4507-a894-816747e5301d', 'Euer ganz persönliches Märchen 🪄', 'Gib dem Tool „Smarte Märchen“ heute Abend ein zauberhaftes Thema: „Die Geschichte vom süßesten Stern, der vom Himmel fiel“. Lass nur den Klang dieses Märchens durch das Zimmer schweben.'),
  ('1175cce8-f8b8-4dcc-a8b2-c864d9349ad6', 'NUR NOCH 3 TAGE BIS ZUM 7. MONAT! 🎂', 'Ist die Torte bestellt? Sind die Outfits ausgesucht? Es dauert nicht mehr lange, bis dein Baby 7 Monate alt wird. Feiert diesen schönen Meilenstein mit einem kleinen Fotoshooting zu Hause!'),
  ('6496f6e2-60a8-4932-a5d1-b8cb0c9682cf', 'Der Freund im Spiegel 👀', 'Setz dein Baby vor einen Spiegel. Zu beobachten, wie es sein Spiegelbild erstaunt anschaut und dabei lacht, ist eine wunderbare und beruhigende Beschäftigung.'),
  ('f998fac0-0a6b-42d2-b200-7a956f147c9a', 'Papa ist dran 👨‍🍼', 'Heute Abend übernimmt Papa das Baden und macht euer Baby bettfertig.'),
  ('06cfdff1-da31-4945-b562-a0c104f43d15', 'Ich höre dich 🗣️', 'Hört dein Baby dir aufmerksam zu und versucht, ähnliche Silben wie „ma-ma“ oder „ba-ba“ zu bilden? Es spricht mit dir! Antworte ihm mit ganz viel Lächeln.'),
  ('83caf542-3e86-4833-b9bd-0befb15b04d7', 'Zeit für frische Luft 🌳', 'Setz dein Baby in den Kinderwagen und geht 20 Minuten an die frische Luft. Das wird euch beiden richtig guttun.'),
  ('fca627d6-9c72-4d82-999a-3b13347100cd', 'Der Held der Nacht 🦸‍♂️', 'Bist du von den nächtlichen Wachphasen erschöpft? Scheue dich nicht, Papa zu wecken. Ein Team zu sein bedeutet, die Aufgaben gerecht aufzuteilen.'),
  ('4335b974-a43c-4ba3-b369-2006056301ed', 'Freies Sitzen 🪑', 'Sitzt dein Baby schon aufrecht, ohne Kissen zu brauchen, wenn auch nur für kurze Zeit? Sichere es dabei gut ab und beobachte diese Muskelentwicklung aufmerksam.'),
  ('5bc047d7-1539-47af-a21f-c1df4aa3461d', 'Iss dein Mittagessen nicht hastig im Stehen. 🥑', 'Bereite dir einen leckeren Salat zu und nimm dir 15 Minuten Zeit nur für dich.'),
  ('8d02cce6-aec5-439c-aadf-52670f1abd08', 'Vorbereitung auf einen tiefen Schlaf 🛀', 'Ein warmes Bad, eine sanfte Massage und ein abgedunkeltes Zimmer ... Eine feste Schlafroutine ist das Geheimnis ungestörter Nächte.'),
  ('347526cf-7568-4464-ab1e-f2a4e4f4b799', 'GANZE 7 MONATE! 🎉', 'Unglaublich! Seit genau 7 Monaten lasst ihr als Team dieses kleine Wunder wachsen. Halte diesen Tag gleich beim Baby-Fotoshooting fest und teile ihn in der Community!'),
  ('a649650d-baa3-4dab-9158-780252d27ef4', 'Das Ende eines wunderschönen Tages. ✨', 'Du bist eine unglaublich starke Mama! Schreib in dein Stimmungstagebuch, wie stolz du auf dich bist, finde mit Weißem Rauschen zur Ruhe und genieße einen erholsamen Schlaf.'),
  ('f5e18de7-aba2-4bda-84e9-b3a568ce950b', 'Blick zurück 📈', 'Erinnere dich daran, wie unerfahren du in den ersten Tagen warst. Und sieh dir jetzt an, was für eine erfahrene Mama du geworden bist. Sei stolz auf dich!'),
  ('4650c8e1-3011-45f0-9997-0c6decd79a65', 'Die Liste ist deine Rettung 🛒', 'Hast du im Alltagsstress etwas vergessen? Mach dir keinen Kopf und schreibe alles, was du für zu Hause brauchst, auf die Einkaufsliste.'),
  ('8c057f2d-32f2-4561-9ca5-5bc651edddcc', 'Wir behalten die Verdauung im Blick. 🧷', 'Feste Nahrung verändert den Stuhlgang. Dokumentiere jeden Windelwechsel in Anacan, um zu sehen, wie dein Baby auf neue Lebensmittel reagiert.'),
  ('9fc39323-52a1-4045-aa65-bf5c16fac78f', 'Hungrig oder müde? 😭', 'Weint dein Baby scheinbar grundlos und klingt sein Schreien anders als sonst? Kein Grund zur Sorge. Lass die Schreianalyse den Laut direkt auswerten und finde heraus, was dahintersteckt.'),
  ('05f5ce2b-27c1-4d94-b681-3d4e9ce809b6', 'Sicherheitsmaßnahmen für zu Hause! 🛡', '️ Je mobiler dein Baby wird, desto mehr Gefahren gibt es. Schau dir unsere Liste empfohlener Produkte mit Kindersicherungen und Eckenschutz an.'),
  ('a0d08200-8263-43d9-90a3-313dda8dadc9', 'Zeit für Fingerfood? 🥦', 'Möchte dein Baby das Essen schon selbst in die Hand nehmen? Entdecke sichere Optionen in unseren Rezepten für Babys, die mit der Beikost beginnen.'),
  ('ef507e65-7f14-47a2-8b48-8ce6e3e1fc96', 'Übungen fürs Krabbeln! 🐢', 'Robbt dein Baby auf dem Bauch rückwärts oder versucht es, sich auf die Knie zu stützen? Frage Anacan AI nach hilfreichen Übungen, die das Krabbeln fördern.'),
  ('6ac03f7c-34a8-46f5-96a4-c1aa521476a5', 'Das Objektpermanenz-Spiel! 🧸', 'Verstecke ein Spielzeug unter einer Decke und lass dein Baby danach suchen. Halte seine Freude bei diesem Denkspiel mit dem Baby-Fotoshooting fest.'),
  ('746b1115-b7ff-4fd7-b04a-46935d1a6f43', 'Überall im Haus liegen Babysachen herum? 🌪️', 'Überall im Haus liegen Babysachen herum? Das ist völlig in Ordnung. Ein unaufgeräumtes Zuhause bedeutet nicht, dass du eine schlechte Mutter bist, sondern dass dein Baby für dich an erster Stelle steht.'),
  ('bc99d2a9-e4a6-4af7-937f-bb0a7a91d292', 'Klangtherapie gegen Unruhe 🎶', 'Wenn dein Baby heute Abend vor lauter Aufregung über seine neuen Fähigkeiten nicht einschlafen kann, spiele unter Weiße Geräusche die Klänge aus dem Mutterleib ab.'),
  ('5b09b018-664d-4b58-86b9-31b6e1d3baf2', 'Die „Das gehört mir!“-Phase 🛑', 'Wird dein Baby wütend, wenn du ihm einen gefährlichen Gegenstand wegnimmst? Statt es einfach nur zu verbieten, lenke seine Aufmerksamkeit auf ein anderes, auffälligeres und farbenfroheres Spielzeug. So lassen sich diese kleinen Wutanfälle leichter überbrücken.'),
  ('698ffa60-da73-4003-9656-db865993d1b5', 'Ein Kunstwerk auf dem Teller 🥦', 'Dein Baby möchte den Brei nicht essen? Manchmal liegt es nicht am Geschmack, sondern am Aussehen. Nutze gesunde Rezepte und gestalte lustige Gesichter aus buntem Gemüse, um seinen Appetit anzuregen.'),
  ('eec20c49-b219-4211-8916-1e602a8ceafb', 'Geräuschempfindlicher Schlaf 🤫', 'Schreckt dein Baby gleich nach dem Einschlafen beim kleinsten Geräusch auf? Prüfe die Raumakustik mit dem Schallpegelmesser und spiele weißes Rauschen ab, um Geräusche von draußen zu überdecken.'),
  ('52134c06-b272-4f5f-93b6-cf014fc0e867', 'Muttermilch bleibt die wichtigste Nahrung! 🍼', 'Achte trotz Beikost darauf, dass der tägliche Milchbedarf gedeckt ist, indem du den Still- und Fütterungstimer verwendest.'),
  ('62cb9c93-e0de-4d15-8d33-e81c1723d1db', 'Energie-Kick für Mamas! 🥗', 'Auch du solltest dich unbedingt gesund ernähren! Bereite dir mit unseren gesunden Rezepten einen vitaminreichen Salat oder Smoothie zu, der dir neue Energie schenkt.'),
  ('f25f7637-e945-4232-a1c1-f7594c81a0b3', 'Eine beruhigende Stimme 📖', 'Lies deinem Baby heute Abend mit deiner eigenen Stimme ein kurzes Märchen vor. Mamas Stimme ist die Lieblingsmusik eines Babys.'),
  ('2a37fc3a-8b98-420a-99ba-c491a8c0f435', 'Müdigkeitssignale 🥱', 'Warte nicht, bis dein Baby sich die Augen reibt und gähnt. Sobald sein Blick starr wird, solltest du direkt mit der Schlafroutine beginnen.'),
  ('74e14338-c8e1-4b5c-b426-24332f30b919', '10 Minuten für Mama ☕', 'Stürze dich nicht gleich auf die Hausarbeit, sobald dein Baby schläft. Setz dich aufs Sofa, trink deinen Kaffee und nimm dir 10 Minuten, um einfach nur die Wand anzuschauen und durchzuatmen.'),
  ('bb4d4aaf-f143-4aa9-b4e0-7b7a4fc4ea1f', 'Quengelige Morgenstunden ☁️', 'Ist dein Baby heute Morgen mit nichts zufrieden? Vielleicht zahnt es oder macht gerade einen Entwicklungssprung durch. Kuschele es einfach etwas mehr und vermittle ihm Geborgenheit.'),
  ('4d7eb303-e249-46ed-8460-db2f0a519240', 'Die Natur ist die beste Medizin ⛅', 'Dein Baby ist sehr unruhig und lässt sich durch nichts ablenken? Öffne das Wetter- und Kleidungstool, zieh dein Baby passend zum Wetter an und geh gleich für 20 Minuten mit ihm im Park spazieren.'),
  ('4dcbbcf9-87b6-44f2-9ce0-d8fdd1caacf7', 'Stille Tränen 📝', 'Heute war dir alles zu viel und du möchtest weinen? Das ist ganz natürlich ... Schreib all deine Erschöpfung in dein Stimmungstagebuch. Dir alles von der Seele zu schreiben, wird dir guttun.'),
  ('e8e53d71-abc7-400d-80a7-8cf91f3339ab', 'Erste Silben wiederholen 🗣️', 'Wiederholt dein Baby häufig Laute wie „Da-da“ oder „Ba-ba“? Es probiert gerade aus, wie sein Sprechapparat funktioniert. Wiederhole jede Silbe lächelnd, damit es lernt, einen Dialog zu führen.'),
  ('27772b37-d653-4081-a4d8-e2d8e3036d19', 'Fragen zur kindlichen Entwicklung 🤖', 'Ist es normal, dass sich der Schlafrhythmus um den 8. Monat herum verändert? Statt stundenlang im Internet zu suchen, kannst du Anacan AI nach konkreten wissenschaftlichen Fakten zur Schlafregression im 8. Monat fragen.'),
  ('e5b5ed3f-01d7-4566-8860-0dc049a710b5', 'Abendmelodie 🎶', 'Wenn dein Kind sich gegen das Einschlafen wehrt, lass im Zimmer leise klassische Musik laufen. Die sanften Klänge helfen seinem angespannten Nervensystem, zur Ruhe zu kommen.'),
  ('ea452c1a-6484-41b5-9042-60a3abcf409d', 'Der Beginn fantasievoller Spiele 🧸', 'Versucht dein Kind, seinem Teddybären oder seiner Puppe Wasser zu geben? Seine Fantasie entwickelt sich und die ersten symbolischen Spiele beginnen. Genieße es, diesem kleinen Regisseur zuzusehen.'),
  ('a2641bfd-0346-425a-86be-0a5a6822a3d8', 'Papas Stimme 📖', 'Sorgt heute Abend für eine ganz besondere Atmosphäre im Zimmer. Denkt euch in den schlauen Märchen eine Geschichte über einen mutigen Waldbewohner aus und lasst Papa sie mit seiner tiefen, beruhigenden Stimme vorlesen.'),
  ('ba28583a-a3f1-40f6-9657-b7b38af17c60', 'Raus aus den eigenen vier Wänden ☕', 'Der Alltag zu Hause fällt dir langsam auf die Decke. Sorg heute für etwas Abwechslung. Such dir ein Café in der Nähe aus, das du bequem mit dem Kinderwagen besuchen kannst, und genieße deinen Kaffee.'),
  ('ea94213c-026e-4de0-be12-a192e4d22b19', 'Dein Kind entwickelt sich jeden Tag weiter🤏', 'Versucht dein Kind, selbst den kleinsten Fleck oder Krümel auf dem Boden mit Daumen und Zeigefinger aufzuheben? Seine Feinmotorik ist in Bestform!'),
  ('2ab7b4ab-59b4-4e96-8271-8ddcc86f1911', 'Auf Möbel klettern 🧗‍♂️', 'Hält sich dein Baby am Sofa oder Stuhl fest und zieht sich daran hoch? Seine Beinmuskulatur bereitet sich auf das selbstständige Stehen vor. Achte auf seine Sicherheit, aber halte diesen kleinen Kletterer nicht von seinen Versuchen ab.'),
  ('82e71311-374a-4306-bcfc-4f69bc54da1b', 'Nächtlicher Sturm 😭', 'Ist dein Baby mitten in der Nacht scheinbar grundlos weinend aufgewacht? Finde mithilfe der Schreianalyse die Ursache heraus und beruhige es.'),
  ('c7aadd23-e889-42f2-a761-3f955cb9600f', 'Zerbrich dir nicht den Kopf 🛒', 'Hat der Schlafmangel dein Gedächtnis beeinträchtigt, sodass du beim Einkaufen immer wieder etwas vergisst? Schreib alles auf die Einkaufsliste, damit dein Partner es auf dem Heimweg besorgen kann.'),
  ('3f339310-d600-43dc-81a3-1b609288885e', 'Hartnäckige Flecken 👗', 'Die Beikostzeit bedeutet, dass zu Hause und auf der Kleidung ständig Flecken entstehen. Ärgere dich nicht darüber. Verwende Silikonlätzchen und genieße einfach diese lustigen, farbenfrohen Momente.'),
  ('60071670-7fa4-4f9f-829f-892d281a9741', 'Hör auf, dir Vorwürfe zu machen. 🛑', 'Heute war die Bildschirmzeit zu lang oder die Wohnung ist unaufgeräumt geblieben? Du bist einfach ein müder Mensch und gibst dein Bestes.'),
  ('fe5cb47e-9f22-41f9-a236-1db4b224e518', 'Das Spiel „Sachen auf den Boden werfen“ 🥄', 'Wirft dein Baby sein Spielzeug vom Hochstuhl und wartet darauf, dass du es aufhebst? Es entdeckt gerade die Schwerkraft und das Prinzip von Ursache und Wirkung. Hab Geduld und lächle.'),
  ('28d590c8-c8a6-4c89-b78b-e70f2f482c0d', 'An die Dunkelheit gewöhnen 🌙', 'Schalte alle zusätzlichen Lichtquellen und Bildschirme im Zimmer aus, damit dein Baby schneller einschläft. Die Ausschüttung des Hormons Melatonin wird nur in einer ruhigen und dunklen Umgebung angeregt.'),
  ('31783568-6230-449d-98c8-e7b1b046a34e', 'Quengelige Morgenstunden ☁️', 'Weint dein Baby gleich nach dem Aufwachen wegen allem und lässt sich durch nichts zufriedenstellen? Vielleicht steckt es gerade mitten in einem Wachstumsschub. Schenke ihm einfach ganz viele Umarmungen und Geborgenheit.'),
  ('38c7f3dd-4cf4-4758-8006-37d59832bac8', 'Lauf nicht gleich zum Geschirrspüler, sobald dein Kind schläft! 🛋️', 'Leg dich aufs Sofa, schließe die Augen und genieße 15 Minuten lang diese seltene, vollkommene Stille zu Hause.'),
  ('3a7b24a5-41c6-4c5d-a602-8a4582791ae2', 'Iss dein Mittagessen im hektischen Alltag nicht nebenbei im Stehen. 🥑', 'Du tust alles, damit dein Baby satt wird. Aber was ist mit dir? Bereite auch für dich einen sättigenden, eisenreichen Teller zu.'),
  ('61d3770b-ac23-4b61-a0c4-be4c333cc55a', 'Erfahrungen austauschen 💬', 'Du machst dir Sorgen und fragst dich: „Warum krabbelt mein Kind noch nicht?“ Dann schau gleich in der Anacan Community vorbei. Lies die echten Geschichten Tausender Mütter oder stelle deine Frage – so wirst du sehen, dass jedes Kind einzigartig ist.'),
  ('a8ecb50a-232f-401a-97bc-3fbfc63cc92b', 'Trennungsangst 🥺', 'Weint dein Baby dir hinterher, sobald du das Zimmer verlässt? Es glaubt, dass du nicht mehr zurückkommst. Sag ihm mit beruhigender Stimme immer wieder: „Ich bin da“, und vermittle ihm so ein Gefühl von Sicherheit.'),
  ('6666dee6-8da7-4982-b6e5-9cdc982b4a75', 'Das Zahnfleisch juckt weiterhin 🦷', 'Kaut dein Baby kräftig auf allem herum und sabbert viel? Im Kühlschrank gekühlte Beißringe sind in dieser Zeit echte Lebensretter.'),
  ('bedd9e86-f764-4777-9e49-e315e75433fd', 'Auch Papa trägt Verantwortung 👨‍🍼', 'Bewältige das nächtliche Aufstehen nicht ganz allein. Wecke auch deinen Partner, denn ein Team zu sein bedeutet, diese Verantwortung gemeinsam zu tragen.'),
  ('c36dcca2-2b51-424c-b39c-c98f7988d549', 'Ich hab dich gefunden! 🙈', 'Lacht dein Baby laut, wenn du dein Gesicht mit den Händen verdeckst und dann „Kuckuck!“ sagst? Sein Verständnis für die Objektpermanenz entwickelt sich jetzt vollständig. Mach dieses Spiel zu einem Teil eurer täglichen Routine.'),
  ('3b5314f5-fa59-44ed-9fa8-b6cf2bce9e2d', 'Teambesprechung 🥂', 'Ihr habt einen anstrengenden Tag hinter euch. Wenn euer Baby eingeschlafen ist, schenkt euch gemeinsam eine Tasse Tee ein und vergesst nicht, einander mit den Worten „Wir sind wirklich ein tolles Team“ wertzuschätzen.'),
  ('579d5966-d49f-4125-a264-8acd785d0a8d', 'Der Freund im Spiegel 👀', 'Setz dein Baby vor den Spiegel. Beobachte, wie es sein Spiegelbild fasziniert betrachtet und versucht, es zu berühren. Das ist eine wunderbare Aktivität, um seine Selbstwahrnehmung zu fördern.'),
  ('9099f274-aa9c-4fe9-8624-5cd611699d2d', 'Schnell für Nachschub sorgen 🛒', 'Gehen Babyöl oder Feuchttücher zur Neige? Die Einkaufsliste wartet in der App auf dich. Trag dort ein, was ihr braucht, damit dein Partner es auf dem Heimweg von der Arbeit besorgen kann.'),
  ('1d706879-d02b-44cf-bac5-4f53776477d3', 'Überraschungswetter ⛅', 'Lass dich beim Spazierengehen nicht vom Wetter täuschen, damit dein Baby nicht friert. Verlass dich nicht nur auf den Blick aus dem Fenster: Mit dem Wetter- und Kleidungsassistenten kannst du genau entscheiden, was für die Bedingungen draußen am besten geeignet ist.'),
  ('acd7fb31-0c36-4f0b-9849-cf983e0b0e95', 'Ich esse selbst! 🥦', 'Möchte dein Baby den Brei nicht mehr mit dem Löffel essen, sondern das Gemüse selbst in die Hand nehmen? Unterstütze seine Selbstständigkeit. Ja, dabei wird es rundherum schmutzig, aber das fördert seine Entwicklung.'),
  ('e1819391-1d2d-450e-ac14-9ecfa65465d4', 'Die magische Welt der Märchen 🪄', 'Probiere heute Abend bei den Smarten Märchen etwas ganz Neues aus. Passe deine Stimme dem Rhythmus des Märchens an.'),
  ('aff9ba8d-8d8a-4d80-9363-09474c73609e', 'Kleiner Entdecker 👣', 'Dein Baby hat bereits seine Zehen entdeckt und versucht, sie in den Mund zu stecken!'),
  ('d79d065c-4399-4ac9-8bd9-d4970a686fba', 'Papas Nachtschicht 👨‍🍼', 'Die Erschöpfung am Tag ist schon genug. Überlass es abends dem Papa, euer Baby bettfertig zu machen und ihm den Schlafanzug anzuziehen, und schau einfach entspannt zu.'),
  ('ea309314-6720-4ddf-9fe1-7a4fb805b43f', 'Hast du eine Frage? 🤖', 'Machen dir im 8. Monat die Größen- und Gewichtskurven deines Babys Sorgen? Statt beängstigende Artikel im Internet zu lesen, bitte Anacan AI um eine verlässliche, wissenschaftlich fundierte Übersicht.'),
  ('1c1e068a-2609-422f-991f-68ad50839ea3', 'Neue Energie tanken 🍲', 'Steckt dir die Müdigkeit in den Knochen? Wähle aus den gesunden Rezepten einen besonderen Smoothie, der in 10 Minuten zubereitet ist, deine Milchbildung unterstützt und dir neue Energie schenkt.'),
  ('51badc42-c8bc-4aa3-b0b8-ec576b19fa07', 'Störgeräusche vermeiden 🤫', 'Die erste halbe Stunde nach dem Einschlafen ist besonders sensibel. Prüfe die Umgebung mit einem Schallpegelmesser und vermeide plötzlichen Lärm aus dem Nebenzimmer oder vom Fernseher.'),
  ('69f05aef-6a67-462b-8173-638d2cb174d5', 'Zielstrebiges Krabbeln 🐢', 'Dein Baby sucht sich jetzt ein Ziel aus und krabbelt schnell darauf zu. Entferne sofort alle kleinen, verschluckbaren und gefährlichen Gegenstände in Bodennähe.'),
  ('7405692f-45e1-45fa-9dd9-b527045b5e7d', 'Erfahrungen austauschen 💬', 'Hat dich eine neue Verhaltensweise deines Kindes erschreckt, zum Beispiel, dass es seinen Kopf gegen die Wand schlägt? Schreib in der Anacan-Community darüber und lies, wie andere Mütter diese Phase erlebt haben.'),
  ('cad415e5-9ff2-468b-bfee-aaed538d25a0', 'Mutige Schritte 🧗‍♂️', 'Hält sich dein Baby am Sofa fest und versucht, eine Hand loszulassen? Sein Gleichgewichtssinn entwickelt sich rasant. Bleib in sicherer Nähe, um es notfalls aufzufangen, und beobachte seine furchtlosen Versuche mit einem Lächeln.'),
  ('e2523211-afd7-48c7-8227-2ec7b0b2f0f7', 'Lass deinen Gefühlen freien Lauf 📝', 'Fühlst du dich sehr allein und unverstanden? Das ist ein ganz natürliches Gefühl. Schreib deine Gefühle offen, ehrlich und ungefiltert in dein Stimmungstagebuch.'),
  ('16c8c619-fdcd-4a82-a21a-ff965106a15f', 'Chaos zu Hause 🌪️', 'Liegen überall im Zimmer Spielsachen herum? Zehn fröhliche Minuten mit deinem Kind sind wichtiger als eine aufgeräumte Wohnung. Die Spielsachen sind morgen auch noch da – überfordere dich nicht.'),
  ('4bcc0503-2fe9-4f95-83e9-1eb9c7b5e773', 'Vorfreude auf den 8. Monat! 🎂', 'Aufgepasst! In nur 10 Tagen wird dein Kleines schon 8 Monate alt! Schau im Entwicklungstracker, wie weit ihr bereits gekommen seid. Überleg dir schon jetzt, ob Mami zu diesem kleinen Jubiläum eine kleine Torte bestellen möchte.'),
  ('724d9097-f64c-406e-8895-2982258b710d', 'Mit Musik in den Schlaf 🛀', 'Ist eure Abendroutine schwieriger geworden? Lass während eines warmen Bades im Hintergrund beruhigende Musik laufen. Das harmonische Zusammenspiel von Wasser und Melodie lässt selbst das unruhigste Kind zur Ruhe kommen.'),
  ('5d8608e7-e1cb-4a71-9c73-7f6dde65adfe', 'Nur noch 5 Tage bis zum 8. Monat! 🎈', 'Die Vorfreude steigt! In nur 5 Tagen wird dein Baby 8 Monate alt! Wenn du eine besondere Torte bestellen oder ein Motto planen möchtest, warte damit nicht bis zum letzten Tag.'),
  ('7a0d5b5d-2b7e-42a8-a73b-a50ead526d05', 'Ruhe und Kaffee 🤫', 'Dein Baby schläft! Statt jetzt die Waschmaschine auszuräumen, setz dich ins abgedunkelte Zimmer. Aktiviere den Geräuschpegelmesser, behalte die Umgebung im Blick und genieße 15 Minuten kostbare Ruhe.'),
  ('f72fbb7e-431d-4f4b-9a73-06637ff7bd68', 'Perfektion gibt es nicht 🛑', 'Heute lief nichts nach Plan? Gib dir nicht die Schuld. Du bist eine echte Mama und keine gefilterte Illusion aus den sozialen Medien. Dein Kind braucht einfach nur dich.'),
  ('61ffa498-18cc-4858-987c-676f525f467c', 'Lass den emotionalen Ballast los 📝', 'War es ein schwieriger Tag? Schreib all den negativen Stress von heute in dein Stimmungstagebuch und lass deinen Gefühlen freien Lauf. Alle Mütter erleben solche Krisen – du bist keinesfalls allein.'),
  ('856b771b-5997-4eed-bc26-8b35541184c6', 'Wetter-Check ⛅', 'Ist das Wetter draußen unbeständig? Lass dir vom Wetter- und Kleidungshelfer sofort die Windgeschwindigkeit, die du vom Fenster aus nicht erkennen kannst, und das passende Outfit anzeigen. So könnt ihr ohne Bedenken spazieren gehen.'),
  ('c82d9568-ae94-4492-9789-4621c2dbcabc', 'Mein Spielzeug gebe ich nicht her! 🧸', 'Protestiert dein Baby und weint laut, wenn du ihm etwas wegnimmst? Sein Gefühl für Besitz und Individualität entwickelt sich. Das ist eine ganz natürliche psychologische Entwicklungsphase – kämpfe nicht dagegen an.'),
  ('bc11c415-3d46-43c3-a8ed-0a204516e9ce', 'Gesunde Mama, gesundes Baby 🥑', 'Deine Eisen- und Kalziumspeicher sind erschöpft. Belohne dich mit einem gesunden, schnell zubereiteten und energiereichen Gericht, das dir neue Kraft gibt.'),
  ('e386c8f2-240d-4f0f-adaf-e43ea496b8b2', 'Schlaues Köpfchen beim Blättern 📖', 'Blättert dein Baby selbstständig durch die dicken Seiten von Pappbilderbüchern und reagiert auf die Bilder? Sein visuelles Gedächtnis funktioniert hervorragend. Lest gemeinsam und benennt die Tiere auf den Bildern.'),
  ('e418c384-8ae3-455b-af14-a223e6595751', 'Ein Moment für die Ewigkeit 📸', 'Wenn dein Baby gerade vergnügt im Zimmer spielt, öffne gleich das Baby-Fotoshooting und halte sein besonderes, schon so viel reiferes Gesicht kurz vor dem 8. Monat mit einem schönen Motto für immer fest.'),
  ('4068a45c-e5fe-4a82-8c4b-a81d556f97cc', 'Zeit für einen Austausch 💬', 'Der Gedanke „Ich kann kaum glauben, dass mein Baby schon 8 Monate alt wird“ macht dich emotional? Teile dieses schöne und zugleich tief berührende Gefühl mit den anderen Mamas in der Anacan-Community.'),
  ('90c5ba08-9d91-4669-8b26-99e0b48d4cf2', 'Versuch und Irrtum 🧱', 'Dein Baby versucht, zwei Bauklötze aufeinanderzustapeln, doch sie fallen um. Aufmerksam versucht es das Ganze noch einmal. Beobachte diese kleinen Konstruktions- und Experimentier­versuche still und voller Stolz.'),
  ('ed75b4ae-9703-498c-a857-64016faef6cc', 'Licht dimmen 🌙', 'Schalte 1 Stunde vor dem Schlafengehen alle hellen Lichter und Bildschirme im Haus aus. Melatonin wird nur in einer ruhigen, schwach beleuchteten Umgebung schnell ausgeschüttet.'),
  ('12b2ddaa-17a1-4692-8574-725c962b0e1b', 'Schreiphasen ohne erkennbare Ursache sind zermürbend. 😭', 'Schreiphasen, deren Ursache du nicht herausfinden kannst, sind zermürbend. Hör auf zu rätseln: Mit der Schreianalyse erkennst du sofort die verborgene Botschaft hinter den Lauten, etwa Schmerzen oder Müdigkeit.'),
  ('19b095ff-5334-4011-abd1-b8df6c79520c', 'Zeit für einen Spaziergang 🌳', 'Die eigenen vier Wände fallen dir auf den Kopf. Setz dein Baby in den Kinderwagen und geht an die frische Luft – auch wenn es nur für 20 Minuten ist. Die Ruhe der Natur tut sowohl deinem Baby als auch deinem seelischen Wohlbefinden gut.'),
  ('b6194099-d4e6-4061-b3f2-d6bc5cce0529', 'Der Zeigefinger ☝️', 'Zeigt dein Baby mit dem Finger auf einen entfernten Gegenstand und schaut dich dabei an? Es sagt dir damit: „Schau mich an“ oder „Das möchte ich haben“. Das ist ein großer Entwicklungssprung in der Kommunikation! Sag ihm, wie der Gegenstand heißt.'),
  ('b78498d9-706c-458c-aa0f-d6081c7746c6', 'Ein Schlaflied für die Nacht 🎶', 'Keine App und kein Geräusch kann Mamas Schlaflied ersetzen. Nimm dein Baby heute Abend einfach fest an deine Brust und sing ihm leise sein liebstes Schlaflied vor, das ihm Geborgenheit schenkt.'),
  ('d08b308d-00d3-45c9-9840-df7ac1047703', 'Klatsch-Kommando 👏', 'Zeigt dein Baby seine Freude, indem es in die Hände klatscht? Sobald du diesen großartigen Meilenstein der motorischen Entwicklung siehst, veranstalte zu Hause einen kleinen Freudentanz und mach mit!'),
  ('dd6cc7ba-db6f-403b-93e6-2447dbb967dc', 'Eine Liste ist kein Extra, sondern ein Muss 🛒', 'Vergiss die Dekoration für die 8-Monats-Party nicht! Zerbrich dir nicht den Kopf, sondern trage alles sofort in die Einkaufsliste ein und stimme dich mit deinem Partner ab.'),
  ('7227b833-2ecd-472c-a074-7273a66732d9', 'Vertraute Gesichter 🥰', 'Hast du dieses breite, ganz besondere Lächeln auf seinem Gesicht gesehen, als du ins Zimmer kamst? Dein Baby erkennt dich und deinen Partner unter allen anderen wieder. Seine bedingungslose Liebe ist die schönste Motivation.'),
  ('90341333-a47d-4dc8-b1bb-8fcf07c769b0', 'Papas lustige Grimassen 🤡', 'Der schnellste Weg, dein Baby zum Lachen zu bringen: Papa macht seltsame Geräusche und lustige Grimassen. Lehn dich heute Abend entspannt zurück und genieße das fröhliche Kichern im Hintergrund.'),
  ('d4f1084b-2a25-422f-954c-038d4cf53bd2', 'Verlier dich nicht in Foren 🤖', 'Du bist dir bei der Beikost unsicher und fragst dich: „Darf ich das geben?“ Statt stundenlang zu suchen, lass Anacan AI deine Fragen beantworten – wie ein digitaler Kinderarzt für die Hosentasche.'),
  ('11c30298-2c39-4c7f-bfc1-dcf22c8e2ebc', 'Ein Ort für Mama ☕', 'Fällt dir zu Hause langsam die Decke auf den Kopf? Wähle unter den mama-freundlichen Orten ein ruhiges Café aus, in dem du bequem mit dem Kinderwagen Platz findest, und gönn dir ein kleines Date mit dir selbst.'),
  ('66c8660e-b8ca-4046-9e3f-578e25572ec7', 'Müll-Expedition 🗑️', 'Alles, was dein Baby auf dem Boden oder am Teppichrand findet, wird mit großer Neugier untersucht. Werde nicht ungeduldig und nimm ihm nicht gleich alles weg – es ist schließlich ein kleiner Entdecker. Achte nur besonders auf Kleinteile, die es verschlucken könnte.'),
  ('8d417480-194b-431c-987a-b0b5216ea151', 'Heute bei den smarten Märchen 🪄', 'Erstelle bei den smarten Märchen eine Geschichte über deinen kleinen großen Helden, der in nur wenigen Tagen 8 Monate alt wird. Lass nur diese zauberhafte Geschichte die Stille der Nacht erfüllen.'),
  ('695238eb-b88d-4ffe-800b-82d23636ceb9', 'Wer macht den Haushalt? 🌪️', 'Für die kleine Feier morgen ist noch etwas zu erledigen? Dann lass es liegen. Bitte deinen Partner, heute den Haushalt zu übernehmen. Du ruhst dich für morgen aus.'),
  ('c96d26d0-5fe0-42f4-a1a7-44abd71bd8d8', 'Zeit für eine Massage 💆‍♂️', 'Wenn euer Baby eingeschlafen ist, könnt ihr euch gegenseitig die Schultern massieren und so den Stress des Tages hinter euch lassen. Sammelt unbedingt neue Energie für den schönen Meilenstein morgen!'),
  ('d3b0f81b-e9b4-4b00-883d-9e8bb86131bc', 'Morgen sind es 8 Monate! 📸', 'Bist du bereit? Morgen ist der große Tag: genau 8 Monate! Schaffe freien Speicherplatz auf deinem Handy – für das Baby-Fotoshooting morgen wirst du jede Menge Platz brauchen. Bügle die Kleidung am besten schon heute.'),
  ('393a7a2a-b162-45e4-9577-0e4f2d088bf3', 'Freudentanz 🥂', 'Feiere heute Abend gemeinsam mit deinem Partner all die Erschöpfung, die Tränen und die Freude der vergangenen 8 Monate. Stellt eine Kerze auf den Tisch und stoßt auf euren großartigen Erfolg als unschlagbares Team an!'),
  ('4419f2fd-8e6f-4837-aa0e-9d571aac3895', 'Ein Blick zurück 📈', 'Wie weit dein Baby schon gekommen ist! Die zerbrechliche Unsicherheit der ersten Tage ist inzwischen einem riesigen Vertrauen gewichen. Du hast diese 8 Monate mit so viel Stärke und Stolz gemeistert! Du bist wirklich großartig!'),
  ('b4769acb-82a0-480e-b58f-3017d46b37a4', 'Wundervolle 8 Monate! 🎉🎂', 'HERZLICHEN GLÜCKWUNSCH! Seit genau 240 Tagen geht ihr diesen wundervollen Weg gemeinsam! Dein Baby ist nun ganze 8 Monate alt. Feiert diesen besonderen Tag gebührend und teilt ihn voller Stolz in der Anacan-Community!'),
  ('0cf5cff8-d958-4ec0-b6df-6f78457976fd', 'So klug wie ein Arzt 🤖', 'Du bist dir bei den Entwicklungsmeilensteinen nach dem 8. Monat unsicher? Verlier dich nicht im Internet, sondern erhalte von Anacan AI verlässliche, wissenschaftlich fundierte und kinderärztlich geprüfte Antworten.'),
  ('77b45217-21e4-402a-b5dd-d0ee28c29f05', 'Fingerfood 🥦', 'Dein Baby möchte keinen Brei mehr, sondern das Gemüse mit den eigenen Händen greifen! Unterstütze seine Versuche, selbstständig zu essen, und bleib unbedingt dabei, auch wenn es rundherum schmutzig wird.'),
  ('dd6d5f01-5a48-4f85-953e-c5e21662ae95', 'Papas Nachtschicht 👨‍🍼', 'Bewältige das nächtliche Aufwachen nicht ganz allein. Weck auch deinen Partner – ein Team zu sein bedeutet, die Verantwortung gerecht zu teilen. Heute Nacht ist er mit dem Einschlafbegleiten dran.'),
  ('918fe7fd-3c85-49ee-b337-c52aba217614', 'Wacht dein Baby mitten in der Nacht schreiend auf und lässt sich nicht beruhigen?  😭', 'Lass die Schreianalyse die Stimme deines Babys auswerten, um herauszufinden, ob nur ein Nachtschreck oder körperliche Schmerzen dahinterstecken.'),
  ('b5dc2a4a-17b6-4c13-ad1b-8f6ccddc9f9b', 'Tanzen zur Musik 🎶', 'Wiegt sich dein Baby im Takt, wenn fröhliche Musik läuft? Die Verbindung zwischen Gehör und Motorik entwickelt sich wunderbar! Mach ein fröhliches Lied an und tanzt gemeinsam durchs Zimmer.'),
  ('deba3d42-726a-4e83-bbbd-900d2aee20ad', 'Dein Baby ist satt – jetzt bist du dran.', 'Such dir aus den gesunden Rezepten einen energiereichen Snack aus und tanke neue Kraft, indem du dich wenigstens 10 Minuten lang aufs Sofa legst.'),
  ('075bea5d-3ab7-4404-af70-89a3de20a0ff', 'Schnelle Einkaufsliste 🛒', 'Sind gestern alle Vorräte zu Hause aufgebraucht worden? Öffne die Einkaufsliste, trage Milch, Obst und andere fehlende Dinge in Sekundenschnelle ein und sende sie an das Handy deines Partners.'),
  ('3c7f679a-b11a-4f67-a3ae-5f350e93a451', 'Eine ganz persönliche Geschichte 🪄', 'Erstelle mit den intelligenten Märchen eine besondere Geschichte, in der dein eigenes Kind die Hauptrolle spielt.'),
  ('e32c4fc2-e649-4150-9d80-08ebdc4ae2e8', 'Chaos nach der Monatsfeier 🌪️', 'Nach der gestrigen Feier zum 8. Monat herrscht zu Hause das reinste Chaos? Stürze dich nicht gleich auf den Haushalt. Verbringe diesen Tag mit deinem nun acht Monate alten kleinen Schatz einfach damit, dich auszuruhen und gemeinsam die neuen Spielsachen zu entdecken.'),
  ('2c9fa500-5618-49b8-a232-965da7b82ef7', 'Die Geräuschkulisse im Blick 🤫', 'Die erste halbe Stunde nach dem Einschlafen ist die empfindlichste Phase. Überprüfe die Umgebung mit einem Schallpegelmesser und vermeide plötzlichen Lärm sowie Geräusche vom Fernseher oder von der Straße.'),
  ('87a20850-e59a-4ee2-81e8-79c4b5808e7b', 'Ich höre dich 🗣️', 'Hört dein Baby dir aufmerksam zu und versucht, ähnliche Silben zu bilden? Es spricht mit dir! Antworte mit einem breiten Lächeln und ermutige es zu diesem Austausch.'),
  ('9c963f32-b147-4e84-aa9a-af699e50681f', 'War deine Geduld heute am Ende und bist du vielleicht wütend geworden?  🛑', 'Mach dir keine Vorwürfe. Lass dich nicht von den Illusionen im Internet täuschen. Du bist eine echte Mutter und darfst deine Gefühle zulassen.'),
  ('31a887b1-fde3-4a67-a32c-13cc6764d41e', 'Lest gemeinsam ein Buch! 📖', 'Bücher mit Geräuschen und bunten Bildern ziehen die Aufmerksamkeit deines Babys besonders auf sich. Mit den Tipps in den Blogs könnt ihr diese lehrreichen Lesemomente noch schöner gestalten.'),
  ('a82a604d-9504-4486-86ea-c38998236871', 'Vergessen, an welcher Brust du gestillt hast? 🤱', 'Der Anacan-Timer merkt sich für dich, ob du an der rechten oder linken Brust gestillt hast. Starte jetzt den Timer für die Stillmahlzeit!'),
  ('d7cab28d-37d6-4301-8e4d-28dfd96b83ab', 'Gewöhnen wir dein Baby ans Wassertrinken. 💧', 'Vergiss nicht, deinem Baby zur Beikost auch Wasser anzubieten. Geeignete Trinklernbecher findest du unter „Empfohlene Produkte“.'),
  ('6122dba2-692e-45e2-8027-9ab67ba2bf07', 'Komm, komm 👏', 'Klatscht dein Baby in die Hände oder streckt es dir die Arme entgegen? Das ist eine wunderbare Form der Kommunikation. Nimm es in den Arm.'),
  ('a73ae95c-98a0-4201-9af1-960893ecd116', 'Die Zeit anhalten 📸', 'Dein Baby wächst so schnell ... Fotografiere im Schlaf sein süßes, friedliches Gesicht und halte diesen Moment als Erinnerung fest.'),
  ('b8c9eaea-1257-487d-8647-7c1cb6d70a3a', 'Hast du eine Frage? 🤖', 'Gehen dir unzählige Fragen zur Entwicklung deines Babys durch den Kopf? Schreib der Anacan AI und erhalte fundierte kinderärztliche Ratschläge.'),
  ('7580f5d5-67e6-4fe8-b318-8dd1f6c00cd6', 'Gefühlstagebuch 📝', 'Wenn du dich einsam und erschöpft fühlst, schreib deine Gefühle in dein Stimmungstagebuch. Alle Frauen durchleben solche turbulenten Zeiten. Du bist stark und schaffst das!'),
  ('90ae683e-61a6-4dd5-b894-186c95367ff3', 'Juckt das Zahnfleisch noch? 🦷', 'Hat dein Baby ständig die Finger im Mund und sabbert viel? Dann ist es wieder Zeit für die gekühlten Beißringe aus dem Gefrierfach.'),
  ('b9bfa71c-cf95-4768-adc9-c82fe1e676ac', 'Frische Luft ist die beste Medizin 🌳', 'Hat dein Baby den ganzen Tag geweint und war unruhig? Die Lösung ist ganz einfach: Schau nach dem Wetter, zieh dein Baby passend an, setz es in den Kinderwagen und geh direkt in den Park. Die Natur beruhigt oft am schnellsten.'),
  ('0a0b2a9c-f56c-4830-8b42-dd0901fc3b1d', 'Ein Spiel zur Objektpermanenz! 🧸', 'Versteck das Spielzeug unter einer Decke und lass dein Baby danach suchen.'),
  ('2e5279b4-ad3c-4da7-866e-49a5932c0601', 'Schreit dein Baby, wenn du ihm das Spielzeug wegnimmst?🧸', 'Das Besitzgefühl wird stärker. Das ist ein wichtiger Teil der Persönlichkeitsentwicklung.'),
  ('d2ac515d-c34a-47d7-a082-82f89c2863e8', 'Muttermilch bleibt die Hauptnahrung! 🍼', 'Achte trotz der Beikost darauf, dass der tägliche Milchbedarf gedeckt wird, indem du den Still-Timer startest.'),
  ('19dff725-11f8-467a-b784-f2971b302ba0', 'Bereit für Tag 250! 🌟', 'Morgen steht eine ganz besondere Zahl an: genau 250 Tage! Sorgt zu Hause für ein wenig Feststimmung und macht euch bereit, diesen Meilenstein mit Stolz zu feiern.'),
  ('c304b9f3-2045-4d2f-b423-1096223f0f83', 'Heute wird nicht geputzt 🛑', 'Bist du müde? Sag deinem Partner Bescheid. Heute wird weder geputzt noch gekocht. Heute hat Mama frei!'),
  ('e01d3a10-f5c2-40e8-8168-d7a86ab3c73d', 'Die Geschichte geht immer weiter 📖', 'Schafft heute Abend eine ruhige Atmosphäre, indem ihr in den schlauen Märchen die Geschichte eines mutigen und klugen Kindes erfindet.'),
  ('561e1f8b-1a7d-4ace-9ef9-bd3f43b083d2', 'Feiert stolz eure 250 Tage🥂', 'Vergesst nicht, heute Abend, nachdem euer Kind eingeschlafen ist, gemeinsam diesen großartigen Erfolg als Team zu feiern!'),
  ('8f3f2d4b-5b88-42ed-95c1-db9f61e1f218', 'UNGLAUBLICHE 250 TAGE! 🎉', 'Kannst du es glauben? Seit genau 250 Tagen geht ihr diesen turbulenten und magischen Weg gemeinsam! Feiert diesen Moment bei einem Baby-Fotoshooting mit einem besonderen Sticker!'),
  ('e0e283b4-8f62-4d84-98d9-c186d1f67042', 'Blick zurück 📈', 'Erinnere dich an deine Ängste in den ersten Tagen. Und jetzt bist du Mama eines Kindes, das bereits versucht aufzustehen! Sei stolz auf dich!')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_de = v.t, body_de = v.b
FROM (VALUES
  ('01890bf6-ab5a-403c-96d2-696020ff0863'::uuid, 'Gefahren auf dem Boden 🧸', 'Die Zimmer sind für dein Baby jetzt ein großes Entdeckungsgebiet. Krabbelnd erreicht es jeden Winkel. Höchste Zeit, dein Zuhause auf mögliche Gefahren zu überprüfen.'),
  ('64b9a99f-59f6-4495-b5ab-9a4825037afc', 'Der Schwerkrafttest 🥄', 'Wirft dein Baby Gegenstände absichtlich auf den Boden und schaut dich dabei an? Es entdeckt gerade den Zusammenhang zwischen Ursache und Wirkung. Hab Geduld und mach bei dem Spiel mit.'),
  ('b34bf0e6-4ffb-4b59-90eb-68d99299dee1', 'Wenn der Kaffee wieder kalt wird ☕', 'Ist dein Kaffee heute schon wieder kalt geworden? Macht nichts – du bist eine Heldin, die ständig in Bewegung ist. Halte das heutige Chaos mit einer Prise Humor in deinem Stimmungstagebuch fest.'),
  ('026d603e-c612-41a2-9525-f4d00f730669', 'Allein duschen – purer Luxus 🛀', 'Den ganzen Tag hinter deinem Baby herzulaufen, hat dich ganz schön erschöpft. Übergib deinem Partner oder deiner Partnerin das Ruder und gönn dir 15 Minuten ungestörte Wassertherapie.'),
  ('1c49ef6a-c84a-47c7-a1bc-352a17833a3d', 'Erste Schritte am Sofa entlang 🛋️', 'Zieht sich dein Baby an Möbeln hoch und bewegt sich seitwärts daran entlang? Das ist ein großer Schritt in Richtung Selbstständigkeit. Halte diesen Moment unbedingt im Entwicklungstracker fest.'),
  ('b5c1158f-415c-414a-b3ec-c9879bf6e9d9', 'Dein Baby kennt seinen Namen! 🗣️', 'Dreht sich dein Baby zu dir um, wenn du aus einem anderen Zimmer seinen Namen rufst? Sein Hörvermögen und Sprachverständnis entwickeln sich immer weiter. Sprich häufig mit deinem Baby und nenne dabei seinen Namen.'),
  ('288682cf-7f40-402e-a594-adaf2cbbed34', 'Barfuß auf Entdeckungstour 👣', 'Dein Baby läuft zu Hause nicht gern mit Socken herum? Der Kontakt der Nerven in den Fußsohlen mit dem Boden ist wunderbar für die Gehirnentwicklung. Lass es sich frei bewegen!'),
  ('2951ca5f-9454-4562-9820-3bfb3531edfd', 'Eine Liste rettet den Tag 🛒', 'Der Gedächtnisnebel will einfach nicht verschwinden? Die Seife ist alle, das Obst geht zur Neige? Schreib es gleich auf die Einkaufsliste, damit dein Partner sich darum kümmern kann.'),
  ('5a72ebf7-bb71-45f2-8047-a9b0ffc32a13', 'Teambesprechung 🥂', 'Öffnet heute Abend, nachdem euer Baby eingeschlafen ist, gemeinsam das Stimmungstagebuch und lacht zusammen über das Chaos dieser Woche.'),
  ('06f3c3ab-79a9-4f2f-94ed-e08927cda8e1', 'Die Zähne greifen wieder an 🦷', 'Scheinbar grundloses Weinen kann durch den Druck im Zahnfleisch verursacht werden. Aktualisiere den Zahnungs-Tracker und hol die gekühlten Beißringe heraus.'),
  ('8e728e0f-9970-4b3d-acfc-5e72bc0eb7af', 'Die Akustik im Zimmer 🤫', 'Wacht dein Baby beim Einschlafen schon vom kleinsten Geräusch auf? Überprüfe die Umgebung mit dem Schallpegelmesser und unterstütze seinen Schlaf mit gleichmäßigem weißem Rauschen.'),
  ('cefb8b22-0318-4268-adf8-8f7052ad66cc', 'Zeigt dein Baby auf einen entfernten Gegenstand und macht dabei Laute? ☝️', 'Damit sagt es dir: „Schau mich an“ oder „Das möchte ich haben“. Das ist ein großer Sprung in seiner Kommunikationsentwicklung!'),
  ('2e4d0e7a-db8d-4408-9d88-01d37ed8b303', 'Das Schlaffenster wird kleiner 🥱', 'Die nächtlichen Wachphasen bringen dich an deine Grenzen? Vielleicht befindet sich dein Baby gerade im Übergang von 3 auf 2 Tagschläfchen. Überprüfe die Abstände zwischen den Tagschläfchen noch einmal.'),
  ('b19774b6-01ed-4a77-8052-5a03aef4ba22', 'Brei in den Haaren 🤦‍♀️', 'Wird jede Mahlzeit zum Schlachtfeld? Wenn dein Kind das Essen berührt und erkundet, fördert das seine sensorische Entwicklung. Nimm die Flecken gelassen.'),
  ('f1d99477-a71b-4368-b9eb-c5c699e49b39', 'Die Natur hilft 🌳', 'Dein Kind quengelt viel und hält es zu Hause nicht mehr aus? Hol dir beim Wetter- und Kleidungshelfer Tipps und macht euch gleich für 20 Minuten auf in den Park.'),
  ('2958c07b-39da-4ecb-ac79-c0f1640a7d1a', 'Vergleiche dich nicht 🛑', 'Vergiss Sätze wie: „Das Kind von anderen läuft schon.“ Jedes Kind entwickelt sich in seinem eigenen Tempo. Tausche dich in der Anacan-Community mit Müttern aus, die genauso denken wie du.'),
  ('da431940-9d6b-4ed8-a933-fd80b83687d9', 'Warten auf das erste „Mama“ 🥰', 'Dein Baby bildet schon verschiedene Silben. Das erste bewusst gesprochene „Mama“ oder „Papa“ ist ganz nah! Reagiere liebevoll auf seine Laute und ermutige es dadurch.'),
  ('f40e6c18-873e-481a-ba28-76a5634b977a', 'Musik ist Nahrung für die Seele 🎶', 'Versuche, scheinbar grundlose Unruhe am späten Nachmittag mit sanfter klassischer Musik zu lindern. Oft wirkt dieser einfache Trick wahre Wunder.'),
  ('bb4b0ba8-0880-4332-8a97-7715f01a7ba8', 'Schrankdetektive 🕵️‍♂️', 'Sind die Küchenschränke das liebste Ziel deines Babys? Räume ungefährliches Geschirr in einen Unterschrank und lass dein Baby seinen Schatz entdecken und stundenlang damit spielen.'),
  ('bf07c6c2-b84c-44ed-9459-f26c37f0e099', 'Kuckuck-Meister 🙈', 'Das Gesicht mit den Händen zu bedecken und Kuckuck zu spielen, ist die liebste Abendbeschäftigung deines Babys.'),
  ('c24149f4-cca2-46bd-ba68-2442b259ab90', 'Du bist auch eine Frau 💄', 'Du bist Mutter und Beschützerin, aber auch ein eigenständiger Mensch. Schau dich im Spiegel an, lächle dir zu und tu heute eine kleine Sache nur für dich.'),
  ('4283eae1-f0b6-489a-be21-28cec6201152', 'Verlier dich nicht in Foren 🤖', 'Bist du dir bei etwas rund um die Essensroutine unsicher? Suche nicht stundenlang im Internet – Anacan AI beantwortet deine Fragen mit dem Wissen eines Kinderarztes direkt in deiner Tasche.'),
  ('743ea03a-9755-40d4-b4aa-1eb6cf8a7495', 'Papas Vorlesestunde 📖', 'Erstellt heute Abend bei den intelligenten Märchen die Geschichte von der mutigen Ziege, die auf die Berge klettert. Papa liest vor und du genießt die Ruhe.'),
  ('fc594ad6-91bd-4ee2-a759-0d1e76e468c0', 'Essen mit den Fingern 🥦', 'Dein Baby möchte keinen Brei mehr, sondern das Gemüse selbst in die Hand nehmen! Unterstütze seine Versuche, selbstständig zu essen, aber bleib unbedingt immer dabei.'),
  ('0c385e87-5c02-4870-85f8-9ab052891af8', 'Vitamine für Mama 🥑', 'Du tust alles, damit dein Baby satt wird. Aber was ist mit dir? Wähle im Bereich für gesunde Rezepte ein leichtes, eisen- und kalziumreiches Mittagessen aus.'),
  ('bda4f100-98ac-4f09-9fa3-a50d4e42eedd', 'Achtung! Nur noch 10 Tage, dann sind 9 Monate voll!  🎂', 'Jetzt ist der richtige Zeitpunkt, um für diesen besonderen Meilenstein eine kleine Torte oder eine Feier im Familienkreis zu planen.'),
  ('effeac28-8d9e-4d0e-b754-fb4004990432', 'Weg von den Bildschirmen 📱', 'Schalte 1 Stunde vor dem Nachtschlaf alle Fernseher und Bildschirme im Haus aus. Die Melatoninproduktion kommt nur in einer ruhigen, dunklen Umgebung richtig in Schwung.'),
  ('47fc8d5e-d99d-4104-9258-c8e18ad15266', 'Was ist das Thema für heute Abend?🪄', 'Lass heute Abend die künstliche Intelligenz eine Geschichte schreiben: Das kleine Eichhörnchen, das seine Spielsachen sucht. Nur deine sanfte Stimme soll die Stille der Nacht durchbrechen.'),
  ('856e1374-a46f-4ac4-b093-11e46392180f', 'Kleiner Papagei 🦜', 'Imitiert dein Baby dein Husten, dein Lachen oder deine Handbewegungen? Du bist der beste Spiegel im Raum. Zeig ihm deine schönsten Gesichtsausdrücke!'),
  ('e263bb82-67f5-4f23-9107-f117b8634a27', 'Lass deine Gefühle raus 📝', 'Manchmal möchtest du einfach die Tür schließen und weinen? Das ist völlig normal ... Schreiben wird dir guttun. Halte deine Gefühle im Stimmungstagebuch fest.'),
  ('73d0b947-9db1-4d57-a222-c8c22a2a895b', 'Der Charakter formt sich 🌟', 'Dein Baby zeigt inzwischen deutlich, was es mag und was es auf keinen Fall möchte. Wenn seine Hartnäckigkeit dich erschöpft, denk daran, dass sich dahinter die Entwicklung seiner Persönlichkeit verbirgt.'),
  ('9596d063-607c-465f-9e92-b73f9f6f0ece', 'Freundschaft unter Müttern 💬', 'Schwierigkeiten miteinander zu teilen, macht die Last leichter. In der Anacan-Community gibt es Tausende Frauen, die genauso empfinden wie du. Sich auszusprechen ist kostenlos.'),
  ('fb27143e-60bd-4519-b45e-80c5584417a4', 'Trost von Papa 🫂', 'Versuche nicht, nächtliche Krisen allein zu bewältigen. Beziehe auch deinen Partner mit ein. Manchmal beruhigen ein anderer vertrauter Geruch und eine andere Umarmung das Baby sofort.'),
  ('4e869b86-0b42-4c4a-86f7-22a0999a3387', 'Applaus-Team 👏', 'Zeigt dein Baby seine Freude, indem es in die Hände klatscht? Halte diesen großartigen motorischen Meilenstein im Entwicklungstracker fest und feiert zu Hause mit einem kleinen Freudentanz.'),
  ('72a32149-c4d7-4a45-b296-5cc7c5b673ad', 'Schneller Check-up 🤖', 'Was wird in der Entwicklung mit 9 Monaten erwartet? Vergiss lange Artikel. Stelle deine Frage direkt an Anacan AI und erhalte eine Antwort auf kinderärztlichem Niveau.'),
  ('df74b674-d83b-4306-a6c3-1477bd965efe', 'Vorbereitung aufs Schlafengehen 🛀', 'Ein warmes Bad hilft fast immer. Halte dich konsequent an die Abendroutine, denn sie signalisiert dem Gehirn deines Babys, dass es Zeit zum Schlafen ist.'),
  ('3c29a397-ae21-4b66-9ae6-c3001d2f3e36', 'Es schaut dich an 👀', 'Ganz gleich, wo du im Zimmer bist – seine Augen sind immer auf dich gerichtet. Bei dir fühlt es sich sicher und geborgen. Wenn deine Geduld am Ende ist, denk an seine bedingungslose Liebe.'),
  ('b3560b09-ab82-494c-a5e9-d6be5d4cb35a', 'Die Kunst des Chaos 🌪️', 'Es verteilt alles, womit es spielt, im ganzen Raum. Nicht das Aufräumen ist jetzt wichtig, sondern dass du dich ausruhst. Die Spielsachen sind morgen noch da – aber eine erholte Mama wird jetzt gebraucht.'),
  ('fe563692-e0de-40b2-aa34-9d6335348a54', 'Die Stille der Nacht 🤫', 'Wenn Auto- oder andere Außengeräusche dein Baby stören, lass im Hintergrund durchgehend weißes Rauschen laufen.'),
  ('268d0edd-f8c9-45fd-af24-4b1bd27e458d', 'Papas Massagesalon 💆‍♀️', 'Lass deinen Partner euer Kind ins Bett bringen und dir anschließend eine 5-minütige Massage für deine verspannten Nackenmuskeln gönnen!'),
  ('38581365-03a6-48aa-a7b4-923dde40764d', 'Faszination Treppen 🧗‍♂️', 'Gibt es zu Hause Treppen oder erhöhte Bereiche, zieht es dein Baby geradezu magisch dorthin. Jetzt ist wirklich der richtige Zeitpunkt, Schutzgitter anzubringen.'),
  ('b1d60979-35c2-486a-9e3b-5e85d1d3dbdf', 'Kampf ums Essen 🥣', 'Schiebt dein Baby den Brei weg? Zwing es nicht zum Essen. Gestalte die Mahlzeit spielerisch, damit es keine negative Beziehung zum Essen entwickelt, und entdecke alternative Rezepte aus der Community.'),
  ('4e8edba3-fd16-4c28-a7ff-08ff9853211e', 'Kleine Dinge des Alltags werden schnell vergessen. 🛒', 'Sind die Windeln oder Feuchttücher alle? Setz sie auf die Einkaufsliste, damit dein Partner sie auf dem Rückweg aus dem Supermarkt mitbringt.'),
  ('5f49ad4f-107b-4550-adae-e4aab3aa9d5b', 'Umstellung auf zwei Schläfchen 🥱', 'Dein Baby schläft tagsüber dreimal, wehrt sich aber inzwischen gegen das letzte Schläfchen? Es wird größer! Jetzt ist es Zeit, den Schlafrhythmus auf 2 Schläfchen umzustellen.'),
  ('8750f5ee-e089-418c-9d9b-a881ca3441c3', 'Magische Märchenwelt 🪄', 'Erstelle bei den intelligenten Märchen die Geschichte deines großen Helden, der in nur 5 Tagen 9 Monate alt wird.'),
  ('7ee44a70-ee6e-4b49-a487-76ff5581f580', 'Mutige Schritte 🧗‍♂️', 'Hält sich dein Baby an Möbeln fest und versucht, eine Hand loszulassen? Sein Gleichgewichtssinn entwickelt sich. Halte seine Hand und gib ihm ein wenig Sicherheit.'),
  ('97d44a72-2ca4-4c0f-b997-91c31aeabbef', 'Ein Gespräch, das verbindet 🥂', 'Öffne dein Stimmungstagebuch und sprich mit deinem Partner darüber, wie euch diese Monate verändert haben. Ein Team zu sein, ist eure größte Stärke.'),
  ('ff86bc54-face-4f54-a1de-cc0ec9cccbc2', 'Alles ist in Ordnung ✔️', 'Überwältigen dich manchmal deine Ängste? Schau auf die saubere Kleidung deines Babys, sein sattes Bäuchlein und seine Augen, die dich anlächeln. Du machst das großartig!'),
  ('5626563e-1119-4751-a2d2-ad651cb7961b', '9 Monate und 5 Tage! 🎈', 'Bis zum großen Tag ist es nicht mehr lang! Eine Torte, kleine Dekorationen oder einfach die schönsten Sachen für zu Hause ... Jetzt wird es Zeit, die Vorbereitungen für das Baby-Fotoshooting voranzutreiben.'),
  ('5e8f6838-89c2-40a6-940e-2ef8b752a179', 'Gemeinsame Erinnerungen 📸', 'Dieses Lächeln ist einfach wunderschön! Fotografiere vor dem Schlafengehen dieses unschuldige Gesicht – diese Momente kommen nie wieder zurück.'),
  ('912ca02c-47d0-4e27-8bdb-7afe9ba868be', 'Eisenspeicher 🥩', 'Eine Anämie kann deinem Kind sowohl den Appetit als auch die Energie rauben. Überprüfe seine Ernährungsroutine und frage bei Bedarf Anacan AI nach eisenreichen Lebensmitteln.'),
  ('0135df6f-fe6e-4faf-9136-dc65b2b29e33', 'Zeit zum Winken 👋', 'Winkt dein Baby zum Abschied, wenn jemand das Haus verlässt? Das ist ein besonders süßes Zeichen seiner sozialen Entwicklung! Ermutige es immer wieder dazu.'),
  ('44260d05-153e-4b6b-b9dd-6f07fb02c462', 'Auf der Suche nach Ruhe ⛅', 'Wenn die Anspannung steigt, hilft es oft am besten, einfach vor die Tür zu gehen. Prüfe das Wetter, setze dein Baby in den Kinderwagen und geh eine Runde spazieren, um den Kopf freizubekommen.'),
  ('67247d93-ddf7-4fcc-adef-5828dde725b4', 'Die Illusion der Perfektion 🛑', 'Heute lief nichts nach Plan? Gib dir nicht die Schuld. Du bist eine echte Mama und keine gefilterte Illusion aus den sozialen Medien.'),
  ('55476184-e000-441a-91f6-32b219ce5489', 'Morgen ist der große Tag! 🎉', 'Genau 9 Monate! Hast du die Kleidung schon vorbereitet? Schaffe Platz auf deinem Handy – morgen brauchst du jede Menge Speicherplatz für das Baby-Fotoshooting!'),
  ('801186a2-f617-44a4-bfbe-39fa8b84707d', 'Schlaflied für die Nacht 🎶', 'Dunkle das Zimmer heute Abend vollständig ab. Keine technischen Geräte – nur deine sanft flüsternde Stimme.'),
  ('bcabe7b8-3e78-42a9-bdf0-3f1883219079', 'Hungrig oder müde? 😭', 'Verliere nicht die Ruhe, wenn dein Baby scheinbar grundlos weint. Nutze die Schreianalyse, um die Ursache schnell zu erkennen und das Problem zu lösen.'),
  ('327e6e73-14c5-44c7-86f9-1b01671cc4cc', 'Ein Blick zurück 📈', 'Was für einen weiten Weg dein Kind schon zurückgelegt hat! Die Aufregung der ersten Tage ist inzwischen einem sicheren Gefühl gewichen. Du hast diesen Weg großartig gemeistert!'),
  ('4b865d9a-0f66-4cb0-98d0-deaa6f061766', 'Ein bisschen Romantik 💖', 'Feiere heute Abend bei Kerzenschein gemeinsam mit deinem Partner die Erschöpfung und den Stolz dieser 9 Monate. Ihr seid ein perfektes Team!'),
  ('8be43b5a-b4b9-49ba-b74f-59b204783156', 'Genau 9 Monate! 🎂', 'Herzlichen Glückwunsch! Seit der Geburt sind genau 9 Monate vergangen. Dein Baby ist 9 Monate in deinem Bauch und 9 Monate in deinen Armen gewachsen! Feiere diesen wundervollen Moment und teile deine Erinnerung mit der Community!'),
  ('334b387f-4019-4208-b951-95f53c679a8b', 'Energiebedarf 🍲', 'Die Müdigkeit steckt dir in den Knochen. Wähle aus den gesunden Rezepten eine in 10 Minuten zubereitete, eisen- und proteinreiche Mahlzeit und tanke neue Kraft.'),
  ('495a74f3-0952-464a-80e0-08b1cc46205c', 'Geräusche regulieren 🤫', 'Der Lärm zu Hause stört seinen tiefen Schlaf. Sorge mit dem Schallpegelmesser für eine gleichmäßige Geräuschkulisse, damit auch du dich entspannt ausruhen kannst.'),
  ('73c5a297-0a32-46fb-8b7c-4ca9aeac6cb1', 'Die Kraft des Wortes „Nein“ 🛑', 'Schiebt dein Baby Essen weg, das es nicht mag, schüttelt den Kopf und sagt Nein? Seine Persönlichkeit entwickelt sich! Respektiere seinen Willen.'),
  ('5238f2b7-2892-49ff-9220-f07d0cf3221d', 'Du bist tagsüber schon müde genug. 👨‍🍼', 'Am frühen Abend mit dem Baby auf dem Boden herumzurollen und zu spielen, ist allein Papas Aufgabe.'),
  ('c89b6b27-fdbd-4cb8-a5cb-f7ddd8bc2ede', 'Schatzsuche 🧺', 'Den Wäschekorb auszuräumen oder Schränke zu durchstöbern, macht deinem Baby am meisten Spaß. Lass es frei spielen – das fördert seine motorischen Fähigkeiten.'),
  ('f0057ec1-cc62-4ea5-9364-5327660ddc30', 'Trau dich zu fragen 🤖', 'Welche Gewürze sind in Babynahrung erlaubt? Frag Anacan AI sofort alles, wobei du unsicher bist, und sei ganz beruhigt.'),
  ('00632cb5-4d20-4f2d-9bf8-82242042667b', 'Zeit für ein zauberhaftes Märchen 🪄', 'Heute Abend gibt es eine besondere Geschichte: die magische Wolke, die so gern einschläft. Sprich leiser und schaffe eine gemütliche Atmosphäre.'),
  ('61c9e192-532e-41bc-9ebb-f2c296bb0670', 'Teile deine seelische Last 💬', 'Schau in der Anacan Community vorbei. Manchmal schenkt dir der Beitrag einer Mutter, die du gar nicht kennst, mehr Energie als eine Tasse Kaffee.'),
  ('92c6be75-a837-4908-b755-b4ae97896380', 'Gefahrenzonen in Reichweite ⚡', 'Steckdosen und Kabel wecken die Aufmerksamkeit deines Babys. Lege zu Hause klare Tabuzonen fest und überprüfe noch einmal, ob alles kindersicher ist.'),
  ('159ac401-c76f-42ec-b9e1-bb1a6d73130e', 'Entdeckungen mit dem Pinzettengriff 🤏', 'Selbst den winzigsten Krümel auf dem Boden findet dein Baby und hebt ihn mit den Fingerspitzen auf! Seine Feinmotorik ist in Höchstform.'),
  ('306f7e64-ae54-408a-95b9-ac4f9c3c6684', 'Nächtliche Geborgenheit 🛀', 'Ändere nichts an der Routine. Dasselbe Bad, dasselbe Massageöl und dasselbe abgedunkelte Zimmer sind der goldene Schlüssel zu gutem Schlaf.'),
  ('f3512bb1-5e87-4250-8249-5c396829b593', 'Vier-Wände-Koller ☕', 'Fällt dir zu Hause die Decke auf den Kopf? Finde unter den kinder- und mütterfreundlichen Orten den nächstgelegenen Platz, an dem du durchatmen kannst und sich dein Baby wohlfühlt.'),
  ('1835b0bb-3338-4b12-9da9-167cd1643dc6', 'Wer macht den Haushalt? 🌪️', 'Das Geräusch des Staubsaugers macht deinem Baby Angst und die Hausarbeit bleibt liegen? Dann lass sie liegen. Bitte deinen Partner, die Hausarbeit heute zu übernehmen.'),
  ('be2205ed-6711-45b7-b2f3-ab21216eef54', 'Gefühlstagebuch 📝', 'Wenn du dich allein fühlst, schreib deine Gefühle in dein Stimmungstagebuch. Alle Frauen machen solche Phasen durch – du bist stark.'),
  ('cd0245fe-8c0d-4f3e-ad23-05cff2186013', 'Entdeckungstour am Boden 🗑️', 'Alles, was dein Baby auf dem Boden findet, untersucht es mit großer Neugier. Werde nicht ärgerlich und nimm ihm nicht ständig alles weg – es ist ein kleiner Entdecker. Behalte es einfach gut im Auge.'),
  ('6ff5d725-a5bb-441a-a5ed-1b1b10bf2638', 'Trost von Papa 🫂', 'Wechselt euch beim nächtlichen Aufstehen ab: einmal du, einmal dein Partner. Manchmal beruhigen dein Baby nur Papas gleichmäßige Streicheleinheiten.'),
  ('77c04114-1662-45d9-9778-494a99f15f4f', 'Lass dich vom Wetter nicht täuschen ⛅', 'Entscheide vor dem Spaziergang nicht nur nach einem Blick aus dem Fenster. Mit dem Wetter- und Kleidungs-Tool findest du beim Zwiebellook genau das richtige Maß.'),
  ('b630415b-1d8a-4088-bd37-659e6494cb2c', 'Mein Spielzeug gebe ich nicht her! 🧸', 'Dein Baby protestiert und weint, wenn du ihm etwas wegnimmst? Sein Gefühl für Besitz und die eigene Persönlichkeit entwickelt sich. Das ist eine ganz natürliche psychologische Entwicklungsphase.'),
  ('5c4470d4-31c9-42e6-98b2-6ebad58cdce5', 'Du weißt nicht, warum sich das Weinen so ungewöhnlich anhört? 😭', 'Lass es sofort von der Schreianalyse auswerten und finde heraus, ob Zahnen oder Blähungen dahinterstecken.'),
  ('906becee-91c7-4860-a453-bec23a80f855', 'Ruhe ist wichtig 🤫', 'Sorge mit dem Schallpegelmesser für Ruhe im Zimmer. Nächtliche Unterbrechungen stören den Schlaf und verderben euch beiden am Morgen die Laune.'),
  ('93f3b238-cc16-44a9-888c-f9d77043f372', 'Tanzen zur Musik 🎶', 'Wippt dein Baby im Takt, wenn fröhliche Musik läuft? So entwickelt sich die Verbindung zwischen Hören und Motorik! Mach ein fröhliches Lied an und tanzt gemeinsam dazu.'),
  ('334464c1-4599-4dd4-83dd-d57c384eb650', 'Blättert in Büchern 📖', 'Versucht dein Baby, die Seiten von Pappbilderbüchern umzublättern? Biete ihm viele farbenfrohe Bilderbücher mit Fühlelementen an.'),
  ('d7009029-eb30-44cd-bedc-77f2ddcbdbe4', 'Vom Brei zu stückiger Kost! 🍲', 'Kann dein Baby schon Lebensmittel essen, die es kauen muss? Probiere in unserer App die Brei- und Suppenrezepte mit unterschiedlichen Konsistenzen aus dem Bereich „Babys beim Beikoststart“ aus.'),
  ('f5716668-d412-4d80-9c29-0a69a23f4f4e', 'Einkaufsliste 🛒', 'Sind Brokkoli oder Haferflocken ausgegangen? Ergänze sofort die Einkaufsliste und schicke sie an das Handy deines Partners.'),
  ('57fa0aeb-432f-4b34-915b-98422c100236', 'Zahnungsschmerzen 🦷', 'Ist das Zahnfleisch wieder gerötet und der Speichelfluss kaum zu stoppen? Lege gekühlte Beißringe bereit.'),
  ('bda23a3e-0646-4246-a5dc-febd245b2bb1', 'Vergessen, an welcher Brust du gestillt hast? 🤱', 'Der Anacan-Timer merkt sich für dich, ob du an der rechten oder linken Brust gestillt hast. Starte jetzt den Timer fürs Stillen!'),
  ('e2296439-aad7-4bdf-a627-05d1e066a3d8', 'Behalte den Schlafbedarf im Blick. ⏱️', 'Starte den Schlaf-Timer, wenn dein Baby einschläft, und prüfe in der Übersicht, ob es den täglichen Schlafbedarf eines 9 Monate alten Babys erreicht.'),
  ('13322f59-d734-452d-8178-1ffb4e5e9f78', 'Auf den Sessel klettern 🧗‍♂️', 'Reicht es deinem Baby nicht mehr, auf dem Boden herumzulaufen, und versucht es, auf Möbel zu klettern? Ein großer Schritt in der motorischen Entwicklung! Behalte es dabei unbedingt im Auge.'),
  ('b349c13b-d822-42ec-876c-d41ccb790846', 'Frische Luft ist die beste Medizin 🌳', 'Hat dein Baby den ganzen Tag geweint und war unruhig? Die Lösung ist ganz einfach: Prüfe das Wetter, zieh es passend an, setze es in den Kinderwagen und ab in den Park.'),
  ('e46eb59c-0196-4f8a-b3f3-e86458e1f828', 'Raumakustik 🤫', 'Schon ein leises Knacken weckt dein Baby im Schlaf. Analysiere die Umgebung mit dem Schallpegelmesser und sorge für ungestörte Ruhe.'),
  ('16369cf1-7620-428e-8c38-c6f5104fb5ab', 'Es räumt seine Spielsachen aus der Kiste! 🧸', 'Dein Baby liebt es, Gegenstände einzeln aus der Kiste zu nehmen und wegzuwerfen. Halte diesen lustigen, chaotischen Entdeckungsmoment mit dem Baby-Fotoshooting fest und erinnere dich später mit einem Lächeln daran.'),
  ('912a7ba7-5cb9-41f1-9daa-dc1c800036eb', 'Stehen die ersten Schritte kurz bevor? 🧗‍♂️', 'Dein Baby zieht sich nicht nur am Sofa hoch, sondern läuft auch schon an der Wand entlang? Dann solltest du die Sicherheitsvorkehrungen noch einmal verstärken.'),
  ('ec70551b-eda4-4e87-86a9-151235d2eb3e', 'Mit einem Märchen einschlafen 🪄', 'Erstelle in den smarten Märchen Geschichten über mutige, liebenswerte Tiere und verwandle das Kinderzimmer in einen magischen Ort.'),
  ('39498b75-8a2a-463e-a232-aa6ed7188810', 'Dein Baby versteht deinen Tonfall 🗣️', 'Hält dein Baby inne und sieht dich an, wenn du mit ernster Stimme Nein sagst? Es beginnt bereits, Gefühle und Verbote zu verstehen!'),
  ('6d030e22-f99a-4fa8-829a-d62a50ce76e0', 'Entwicklungscheck 🤖', 'Denkst du, dass die körperliche Entwicklung deines Kindes verzögert sein könnte? Erhalte von Anacan AI verständliche Informationen über die motorischen Fähigkeiten mit 9 Monaten.'),
  ('e607d1aa-9be0-4388-9790-764a5c1e94da', 'Wir behalten die Verdauung im Blick. 🧷', 'Feste Nahrung verändert den Stuhlgang. Dokumentiere jeden Windelwechsel in Anacan, um die Gesundheit deines Babys im Blick zu behalten.'),
  ('3ab1636f-ed5f-47f5-93d7-4ac521edd386', 'Fühlst du dich nicht gut genug? 💬', 'Schau gleich in der Anacan-Community vorbei, lies die aufmunternden Kommentare anderer Mütter und fühl dich besser.'),
  ('62964d86-1e07-4c7f-a135-52c48581ffc5', 'Ist heute alles drunter und drüber gegangen?', 'Macht nichts. Wenn dein Kind satt und sauber ist, bist du die beste Mama der Welt.'),
  ('fa0817a9-00d2-41fc-bdcb-8fdae95932ff', 'Es lernt die Namen von Gegenständen 🧸', 'Sucht dein Baby mit den Augen nach dem Ball und findet ihn, wenn du fragst: „Wo ist der Ball?“ Seine Wahrnehmung entwickelt sich immer weiter! Spielt gemeinsam Spiele, bei denen du die Gegenstände benennst.'),
  ('93f4fd0f-1f45-436c-b46b-7acc69d1b899', 'Balance auf beiden Beinen 🤸‍♂️', 'Steht dein Baby aufrechter und kräftiger auf seinen Beinen, wenn du es unter den Armen hältst? Halte diesen wichtigen Schrittreflex unbedingt im Entwicklungstracker fest!'),
  ('b0bdf4f4-2902-43a5-876f-e99b39aef4f9', 'Magische Märchenstunde 🪄', 'Bring mit der Geschichte „Die Einschlafgeheimnisse des kleinen Helden“ aus den klugen Märchen Abwechslung in eure Abendroutine.'),
  ('c6da7887-a402-4a11-8fbf-8de4d7696325', 'Eine Liste rettet den Tag 🛒', 'Im Haushalt geht ständig etwas aus. Mach dir keinen Kopf: Füll die Einkaufsliste aus und warte darauf, dass Papa nach der Arbeit den Tag rettet.'),
  ('1b15944e-9198-4fc4-b86d-0b17af6cdd00', 'Was soll ich den Arzt fragen? 🤖', 'Du weißt nicht, was du vor der monatlichen Untersuchung fragen sollst? Bitte Anacan AI um eine Check-up-Liste für den 9. Monat.'),
  ('1eda7621-0a6a-4ff0-8efe-ec931b28a106', 'Der kleine Helfer im Haushalt 🧺', 'Kommt dein kleiner Schatz auch dazu und hilft dir, indem er die gefaltete Wäsche wieder durcheinanderbringt? Beziehe ihn einfach mit ein und gib ihm ein Handtuch in die Hand.'),
  ('59e058ca-af20-4537-9c74-8aa7eb175af6', 'Lass deinen Gefühlen freien Lauf 📝', 'Hol dir am Nachmittag einen Kaffee und schreibe eine kurze Notiz in dein Stimmungstagebuch. Vergleiche dabei deine jetzigen Gefühle mit denen der vergangenen Monate.'),
  ('30a7e68c-862a-436f-a801-8270fce13b90', 'Achte auf dich 🍲', 'Wenn du gesund bist, ist es dein Baby auch. Wähle aus den gesunden Rezepten einen leichten Salat für Mamas, der in 10 Minuten zubereitet ist, und lass ihn dir schmecken.'),
  ('32607011-b168-4558-b64b-8c8947e8d9a9', 'Ein warmes Bad, eine Massage und ein abgedunkeltes Zimmer. 🛀', 'Eine feste Schlafroutine ist das wichtigste Geheimnis für ungestörte Nächte.'),
  ('ca309c2b-9bd6-47c4-bfb8-da0eb88d4f08', 'Verschiedene Silben und erste Versuche mit ganzen Sätzen 🗣️', 'Dein Baby brabbelt ausgiebig in seiner eigenen Sprache, als würde es ganze Sätze bilden. Hör dem süßesten kleinen Nachrichtensprecher im Raum aufmerksam zu!'),
  ('3908e4ee-6364-4b5e-bf19-9883638e23db', 'Geräuschpegel im Zimmer 🤫', 'Fällt das Einschlafen schwer? Prüfe mit dem Schallpegelmesser die Dezibel im Zimmer und stelle den Fernseher so leise, dass er nur im Hintergrund zu hören ist.'),
  ('ce7b77f8-95b5-4071-bf35-61b06d785d85', 'Wir sind ein Team! 💖', 'Setzt euch nach einem anstrengenden Tag zusammen und sprecht offen über das, was euch beschäftigt. Wenn ihr einander unterstützt, trägt sich die Last leichter.'),
  ('fab0e5e3-a0d0-40d0-843b-ff548b4b816f', 'Das Komm-her-Team 👏', 'Hat dein Baby schon gelernt, mit den Händen „Komm her“ zu winken? Halte diese süße Nachahmung unbedingt auf Video fest und füge sie eurem Erinnerungsalbum hinzu.'),
  ('0b91a5b0-1518-4473-b0bb-59cec89d7f6f', 'Die Gespräche werden immer vielseitiger! 🗣', '️ Lies die Tipps zur Sprachentwicklung in den Blogs, um die süßen Dialoge mit Silben wie „Ma-ma“ und „Ba-ba“ spielerisch zu fördern.'),
  ('ccbd5c11-509e-4b73-9eb1-b2f8b729e5b5', 'Lebensmittel, die deine Milchbildung unterstützen. 🍲', 'Probiere heute im Bereich „Gesunde Rezepte für Frauen“ eine der milchbildungsfördernden Suppen aus und stärke dich.'),
  ('db929314-83ca-4372-8890-03ef676e68e5', 'Weinanfälle ohne erkennbaren Grund können sehr zermürbend sein. 😭', 'Mach dich nicht fertig: Nutze die Weinanalyse und finde heraus, was dahintersteckt.'),
  ('72b7b721-7f37-4054-90fd-05ac29f9ff3c', 'Klangtherapie gegen Unruhe. 🎶', 'Wenn dein Baby heute Abend unruhig ist, spiele bei den Weißen Geräuschen den Klang aus dem Mutterleib ab und beruhige es im Handumdrehen.'),
  ('761f9ba9-87d1-4b16-a40a-f1ec2385a5fd', 'Vorfreude auf den 10. Monat! 🎂', 'Achtung! In nur 10 Tagen wird dein Kleines 10 Monate alt! Vergiss nicht, für den Start in die zweistelligen Lebensmonate eine besondere Torte zu bestellen!'),
  ('b335cc4c-9dc2-482d-a2f2-b6bcbf3a72f9', 'Mit einem Märchen einschlafen 🪄', 'Erfinde in den interaktiven Märchen Geschichten über mutige, liebenswerte Tiere und verwandle das Zimmer in einen zauberhaften Ort.'),
  ('19eac11a-ecf7-498d-85e1-95d4f484d466', 'Noch 10 Tage bis zum 10. Monat! 🎈', 'Noch 10 Tage bis zum großen Tag! Wähle schon jetzt im Tool für Baby-Fotoshootings besondere Rahmen aus und plane alles im Voraus.'),
  ('36d1de0a-5eb5-4e0f-98ce-a583a10b254e', 'Lass dich vom Wetter nicht täuschen ⛅', 'Entscheide vor dem Spaziergang nicht nur nach einem Blick aus dem Fenster. Mit dem Wetter- und Kleidungstool findest du beim Zwiebellook genau das richtige Maß.'),
  ('ea9b5851-8f4a-4a19-990c-97e725808bb5', 'Ein Schlaflied von Papa 👨‍🍼', 'Heute Abend übernimmt Papa alle Schlaflieder und Gute-Nacht-Geschichten.'),
  ('14c6187e-df8b-47e8-b44f-9bc87c4b9143', 'Die Stille der Nacht 🤫', 'Wenn Autolärm oder andere Geräusche von draußen dein Baby stören, lass im Hintergrund durchgehend weißes Rauschen laufen.'),
  ('36c8e54c-04ef-4b47-9a2f-c0754b0990c9', 'Durch Hinfallen lernen 🧗‍♂️', 'Dein Baby hält sich am Sofa fest, läuft daran entlang, fällt auf den Po und steht wieder auf? So lernt es, nicht aufzugeben. Bleib ruhig und ermutige es.'),
  ('c0c6e209-b8c8-4325-bc8e-9d4231949abd', 'Schmerzen beim Zahnen 🦷', 'Ist das Zahnfleisch wieder gerötet und läuft der Speichel ununterbrochen? Halte gekühlte Beißringe bereit.'),
  ('65f53c0c-e8ea-4257-8798-e79b9ed847be', 'Dein Baby möchte essen, was du isst 🥣', 'Greift dein Baby nach allem auf deinem Teller? Sein Interesse am Essen ist jetzt besonders groß. Biete ihm kleine, babygeeignete Stückchen Fingerfood an, die es selbst essen kann.'),
  ('bbfc7848-e7f7-4bfa-a960-a2aeb003f7a4', 'Gefühlstagebuch 📝', 'Wenn du dich allein fühlst, schreib deine Gefühle in dein Stimmungstagebuch. Das Aufschreiben wird dir guttun.'),
  ('d2c3bcc6-5492-42b4-857f-d6ad8a442199', 'Entwicklungscheck 🤖', 'Hast du Fragen zur Beikost? Bitte Anacan AI um Informationen zu einem Speiseplan für ein 9 Monate altes Baby.'),
  ('69d7aa9d-fa7f-4594-a0de-a2ff1fbdebb6', 'Zauberhafte Märchenstunde 🪄', 'Heute Abend gibt es eine besondere Geschichte: die magische Wolke, die es liebt, einzuschlafen. Sprich leiser und schaffe eine gemütliche Atmosphäre.'),
  ('ae31e811-95f5-438c-9d8f-7b39b14eed84', 'Alles an seinen Platz räumen 🧸', 'Wirft dein Baby das Spielzeug in die Kiste und holt es wieder heraus? So entdeckt es den Unterschied zwischen drinnen und draußen.'),
  ('ed4bee35-1ea6-4f7f-ba0b-bb5c2bd4f981', 'Wir gewöhnen uns ans Wassertrinken. 💧', 'Vergiss nicht, deinem Baby zur Beikost auch Wasser anzubieten. Unter den empfohlenen Produkten findest du ganz einfach passende Trinklernbecher.'),
  ('0b7b3ea8-6539-4606-ac0b-b0428466ace0', 'Kleiner Papagei 🦜', 'Ahmt dein Baby dein Husten oder Lachen nach? Du bist der beste Spiegel im Raum. Zeig ihm deine schönsten Gesichtsausdrücke!'),
  ('380bef16-ec45-4aa3-8cc8-5ea1cf489dc2', 'Energie-Kick für Mamas! 🥗', 'Einem aktiven Baby hinterherzulaufen, kostet Kraft! Bereite dir mit unseren gesunden Rezepten für Frauen einen vitaminreichen Salat oder Smoothie zu.'),
  ('a261deac-e213-48df-a6bd-e43793de79c9', 'Papas Massagesalon 💆‍♀️', 'Lass deinen Partner das Kind ins Bett bringen und dir danach 5 Minuten lang die verspannten Schultern und den Nacken massieren!'),
  ('3995ea79-4422-4b71-b376-6426966b7d85', 'Frische Luft ist die beste Medizin 🌳', 'Dein Baby hat den ganzen Tag geweint und war unruhig? Die Lösung ist ganz einfach: Prüfe das Wetter, zieh dein Baby passend an, setz es in den Kinderwagen und geh direkt in den Park.'),
  ('b67edfc6-e141-41a3-866c-78583fe5c77b', 'Nur noch 5 Tage bis zum 10. Monat! 🎂', 'Bis zu diesem großen Meilenstein ist es nicht mehr lange! Jetzt ist genau der richtige Zeitpunkt, die Torte und das Outfit für den 10. Monat vorzubereiten. Schritt für Schritt nähert ihr euch dem ersten Geburtstag!'),
  ('da354848-a7ac-41ba-9616-ccf0b8799a86', 'Müdigkeitssignale 🥱', 'Wenn dein Baby sich die Augen reibt und ins Leere schaut, warte nicht, bis es quengelig wird. Dunkle sofort das Zimmer ab und beginne mit der Schlafroutine.'),
  ('049b837c-5a26-4c32-95e4-e745b4a3443b', 'Protestiert und weint dein Baby, wenn du ihm etwas wegnimmst? 🧸', 'Das Gefühl für Besitz und die eigene Persönlichkeit entwickelt sich. Das ist eine ganz natürliche psychologische Entwicklungsphase.'),
  ('06a37325-84f4-4012-b4a0-ff317ba78e4c', 'Wir winken zum Abschied! 👋', 'Hat dein Baby gelernt, Menschen zum Abschied hinterherzuwinken? Halte diese bewusste und niedliche Geste gleich bei einem Baby-Fotoshooting als Erinnerung fest.'),
  ('69b02f6b-1a0a-4f09-860a-f56dfb370b0a', 'Sicherheitsmaßnahmen zu Hause! 🛡', '️ Je häufiger dein Baby versucht, sich hinzustellen, desto mehr Gefahren entstehen. Sieh dir unbedingt unsere Liste mit empfohlenen Produkten wie Kindersicherungen und Eckenschutz an.'),
  ('03f6a4bb-fc20-440d-bf19-5a474e3fa7f6', 'Nimm dir Zeit für dich. 🛁', 'Während dein Kind schläft, kannst du deine Haare und deine Haut pflegen und dich entspannen.'),
  ('87dbc3cb-466d-4628-b1df-07cce718a3ab', 'Es isst gerne selbst! 🥦', 'Bereite für Babys, die mit Beikost beginnen, einfache, gesunde Fingerfoods aus den Rezepten zu.'),
  ('9b804616-ae80-4d37-b6a9-76004e3e5506', 'Es versteht einfache Aufforderungen! 🧠', 'Reicht es dir sein Spielzeug, wenn du sagst: „Gib mir das“? Lies die entwicklungsfördernden Artikel in den Blogs, um diesen Entwicklungssprung zu unterstützen.'),
  ('dffa4555-16c2-4705-a09e-e04f9ae6d25d', 'Bleibt etwas liegen? Dann lass es liegen.  🌪️', 'Bitte deinen Partner, heute die Hausarbeit zu übernehmen. Ruh du dich aus.'),
  ('f2c9cd05-6f08-42dc-b88f-310abadaba89', 'Nächtliche Ruhe 🛀', 'Ein warmes Bad, eine Massage und ein abgedunkeltes Zimmer. Eine feste Schlafroutine ist das wichtigste Geheimnis für ungestörte Nächte.'),
  ('fad6626b-f1fb-4e8d-8e1a-679ccb7c1f85', 'Alles, was es auf dem Boden findet, untersucht es ganz neugierig.  🗑️', 'Werde nicht ungeduldig und nimm ihm nicht alles aus der Hand – dein Baby ist ein kleiner Entdecker. Behalte es einfach im Auge.'),
  ('7a757f5f-8810-4a3e-a344-a9b3d9a89548', 'Hungrig oder müde? 😭', 'Verliere nicht die Ruhe, wenn dein Baby scheinbar grundlos weint. Nutze die Schreianalyse, um Unterstützung zu erhalten, die Ursache schnell zu erkennen und das Problem zu lösen.'),
  ('cc7b8905-a439-46c1-8d92-ea81667052be', 'Trost von Papa 🫂', 'Wechselt euch beim nächtlichen Aufstehen ab: Einmal stehst du auf, beim nächsten Mal dein Partner. Teilt euch die Belastung als Team gleichmäßig auf.'),
  ('df82eb33-3f1e-407f-b436-e4b5c122a87e', '300 Tage voller Aufregung! 🌟', 'Morgen steht ein großes, doppeltes Jubiläum an: 10 Monate und 300 Tage! Sorgt zu Hause für ein wenig Feststimmung und schafft freien Speicherplatz auf eurem Handy.'),
  ('19b97cb2-c4a1-4649-a316-a7b34bb3eed4', 'Wie weit dein Kind schon gekommen ist!  📈', 'Die Aufregung der ersten Tage ist einem Gefühl der Sicherheit gewichen. Du hast diesen Weg mit großem Erfolg gemeistert – du bist großartig!'),
  ('1d119442-bc5b-4f46-a607-68533220e425', 'Hast du eine Frage? 🤖', 'Frage unseren Anacan AI-Assistenten jederzeit – auch nachts – nach Entwicklungsdetails, die dich beschäftigen, und erhalte fachkundige Unterstützung.'),
  ('dd2f968e-d28b-4ab1-9758-59cda94c35f6', 'Wundervolle 10 Monate und 300 Tage! 🎉', 'Herzlichen Glückwunsch! Seit genau 300 Tagen, also ganzen 10 Monaten, begleitest du dieses kleine Wunder beim Großwerden.'),
  ('63090d6e-b5fb-4db8-bce4-2e5749468a34', 'Interesse an Büchern 📖', 'Integriere gedruckte Bücher in eure Abendroutine. Dein Baby versucht jetzt schon, die Seiten selbst umzublättern. Passe deine Stimme an das Tempo der Geschichte an.'),
  ('64ab60a5-a744-4f7e-a8a1-28b04eede9d6', 'Der Essensturm ist eingestürzt 🥣', 'Wirft dein Baby absichtlich den Löffel oder das Essen vom Hochstuhl und schaut dich danach an? Es testet Grenzen und die Schwerkraft. Bewahre Geduld.'),
  ('cd288f90-d6da-4851-9b9a-2a8e15ba81fb', 'Dein Körper verändert sich 👗', 'Macht dich der Anblick deiner Silhouette im Spiegel traurig? Mit diesem Körper hast du einen Menschen erschaffen. Schreibe eine Dankesbotschaft an dich selbst in dein Stimmungstagebuch.'),
  ('0e1a794c-f019-4037-b108-0a10db7b5f9f', 'Leise Heldin 🤫', 'Sobald dein Baby eingeschlafen ist, klingt jedes Geräusch im Haus wie eine Explosion. Lege mit einem Schallpegelmesser eine Lautstärkegrenze für das Zimmer fest und bewege dich selbst auf leisen Sohlen.'),
  ('cb2d76e0-4e92-41f1-9153-3b4a29404a17', 'Schrankdetektiv 🕵️‍♀️', 'Stehen alle Töpfe aus der Küche auf dem Boden? Lass dein Baby ruhig mit ungefährlichen Gegenständen spielen – das fördert sein logisches Denken. Räume nur scharfe Gegenstände außer Reichweite.'),
  ('d194240e-ae66-4f32-83ef-39ade449ccb6', 'Mamas unter sich 💬', 'Gehen dir Fragen wie „Warum krabbelt mein Kind noch nicht?“ ständig durch den Kopf? Schreib darüber in der Anacan-Community. Dort wirst du sehen, dass jedes Kind sein eigenes, genau richtiges Tempo hat.'),
  ('249e422f-5203-4598-a063-3032744aab4c', 'Der Wasser-Dickkopf 💧', 'Dein Baby möchte seine Tasse ganz allein halten und daraus trinken, verschüttet dabei aber das meiste? Freu dich über seine ersten Schritte in die Selbstständigkeit – dafür gibt es schließlich Feuchttücher.'),
  ('88ed955b-e80f-4226-9234-7112a99a4951', 'Aufladezeit für deinen Partner 🔋', 'Tagsüber hast du deine ganze Energie deinem Kind gewidmet. Lass deinen Partner heute Abend die Zeit mit eurem Kind verbringen und gönn dir eine Auszeit offline.'),
  ('d2dfb95a-94ec-43c1-97da-20aed6c6d0bb', 'Die ersten Sekunden ohne Festhalten 🧗‍♂️', 'Lässt dein Baby plötzlich die Hände los, während es sich am Sofa hochzieht? Es findet gerade sein Gleichgewicht! Bleib in diesen kurzen, aber aufregenden Sekunden aufmerksam in seiner Nähe und sichere es ab.'),
  ('80ecdccb-340a-49ab-94a9-ff073855c0a0', 'Was soll ich bloß kochen? 🍲', 'Dir gehen die Ideen für den Beikostplan aus? Verlier dich nicht in den Weiten des Internets. Bitte die Anacan AI um eine Liste einfacher Fingerfood-Ideen für ein 10 Monate altes Baby.'),
  ('b8e6e605-baf6-44b6-9e44-842e0b7a0af0', 'Mischt sich ins Gespräch ein 🗣️', 'Während du telefonierst, plappert dein Baby in seiner eigenen Sprache mit und wird dabei immer lauter? Seine Kommunikationsfähigkeit entwickelt sich rasant – jetzt gibt es einen zweiten Sprecher im Raum!'),
  ('c9db13f9-8aff-4b71-a7fa-bdce47336917', 'Plötzlich schreiend aufgewacht? 😭', 'Dahinter könnte ein Nachtschreck stecken. Lass die Weinanalyse den Schrei auswerten, um besser einzuschätzen, ob die Ursache körperlich oder psychisch ist.'),
  ('29cc3dd1-d28b-45c9-93d7-58bfda48629c', 'Der Zeigefinger ist im Einsatz ☝️', 'Dein Baby zeigt mit dem Finger auf eine Katze oder ein Spielzeug in der Ferne und reagiert darauf. Das ist eine besonders weit entwickelte Form der gemeinsamen Aufmerksamkeit.'),
  ('6eab5294-c731-4890-971d-ad01e35f7d7c', 'Park oder Zuhause? ⛅', 'Ihr möchtet nach draußen, aber es ist windig. Der Wetter- und Kleidungsassistent zeigt dir nicht nur die Temperatur, sondern empfiehlt auch passende winddichte Kleidung für dein Baby.'),
  ('edfb2fd4-70c3-4b15-b2d1-0fc891b31501', 'Papas lustige Grimassen 🤡', 'Am besten bringt Papa das Baby mit seinen lustigen Geräuschen zum Lachen. Haltet die fröhlichen Momente dieses Abends mit dem Baby-Fotoshooting als Erinnerung fest.'),
  ('9b064bbe-67b8-4d62-b3a0-30f79dc81515', 'Mama nicht von der Seite weichen 🥰', 'Selbst wenn du nur zur Toilette gehst, wartet dein Baby weinend hinter der Tür auf dich. Die Trennungsangst ist gerade besonders stark. Gib ihm Sicherheit, indem du immer wieder sagst: „Ich bin da.“'),
  ('e77deeee-d612-4dac-bea4-ec9f16608958', 'Heute im smarten Märchen 🪄', 'Erstelle in den smarten Märchen eine besondere Geschichte, in der dein eigenes Kind die Hauptrolle spielt: ein kleiner Schatz, der tagsüber müde wird und nachts zu den Sternen fliegt.'),
  ('f0ba97cb-8dd2-4486-865e-1d22a5e551a6', 'Die Einkaufsliste für unterwegs 🛒', 'Keine Äpfel mehr für den Obstbrei? Überlass den Einkauf deinem Partner. Schreib alles auf die Einkaufsliste – den Supermarkt übernimmt er.'),
  ('26bb2530-b202-43eb-9226-30863365843e', 'Wir behalten die Verdauung im Blick. 🧷', 'Verschiedene feste Lebensmittel verändern den Stuhlgang. Halte jeden Windelwechsel in Anacan fest und analysiere so die Gesundheit deines Babys.'),
  ('32966fee-53d4-4975-ad1e-195457a2fa5c', 'Nächte voller Widerstand 🥱', 'Wehrt sich dein Baby mit aller Kraft gegen das Einschlafen? Vielleicht ist es an der Zeit, eines der Nickerchen am Tag wegzulassen. Überprüfe eure Routine.'),
  ('b5660557-30c8-45a9-9c75-69616076d9ce', 'Zeit für Mama ☕', 'Das viele Zuhausebleiben hat dir die Energie geraubt. Wähle unter den mama-freundlichen Orten ein gemütliches Café mit Kindermenü aus und nimm dir etwas Zeit für dich.'),
  ('221ab24d-c8af-4cca-b9d8-b4eae15499d0', 'Sei stolz auf dich 👏', 'Schau nicht auf das unaufgeräumte Zimmer, sondern darauf, wie glücklich dein Baby heute ist. Du bist eine großartige Mama – das kann dir kein Buch der Welt beibringen.'),
  ('cdf44716-8a24-472d-9ff5-449bcc14a7fe', 'Der Körper tanzt zur Musik 🎶', 'Sobald dein Baby im Fernsehen oder auf dem Handy einen rhythmischen Klang hört, beginnt es, mit dem Po zu wackeln. Sein Gespür für Musik entwickelt sich – mach mit und tanzt gemeinsam!'),
  ('d3e69c0c-c087-4266-8819-3e9aa9fc132a', 'Zeit für eine Massage 💆‍♂️', 'Wenn euer Kind eingeschlafen ist, könnt ihr euch gegenseitig die Schultern massieren und so den Stress des Tages hinter euch lassen. Ihr seid ein Team!'),
  ('12c2a250-54bd-4e0d-a366-20c820596148', 'Schneller Kinderarzt 🤖', 'Hat dein Kind kleine Rötungen am Körper? Bevor du zum Arzt gehst, kannst du dir bei Anacan AI schnell Informationen über die Anzeichen einer Nahrungsmittelallergie holen.'),
  ('7b4d66d9-a24a-47b0-a1dd-7047f05e45ec', 'Reaktion auf den eigenen Namen 🗣️', 'Wenn du dein Baby rufst, schaut es dich nicht nur an, sondern unterbricht sogar, was es gerade tut, und versucht, zu dir zu kommen.'),
  ('c7423d2f-6f9f-452c-9de2-5dea29b29f93', 'Licht dimmen 🌙', 'Schalte 1 Stunde vor dem Schlafengehen alle grellen Lichter und Bildschirme zu Hause aus. Melatonin wird nur in einer ruhigen, schwach beleuchteten Umgebung ausgeschüttet.'),
  ('100bd53c-84e3-4c7e-8a31-2a287a02c440', 'Lass dein schlechtes Gewissen los 📝', 'Denkst du, dass du heute zu wenig mit deinem Baby gespielt hast? 10 Minuten ungeteilter Aufmerksamkeit sind wertvoller als 1 müde Stunde.'),
  ('42ea49cf-0e72-4699-aaf4-7633e9ea6a82', 'Ein Bild, das die Zeit anhält 📸', 'Jeden Tag sieht dein Baby ein bisschen mehr wie ein Kleinkind aus, und die typischen Babyzüge verschwinden langsam. Öffne gleich das Baby-Fotoshooting und halte diese Veränderung fest.'),
  ('a0c5dfe0-02f0-4961-8b06-219cd57dde9d', 'Die ersten Zeichen auf dem Weg zum 11. Monat! 🎈', 'Achtung! In nur 20 Tagen wird dein Baby 11 Monate alt, und wir starten den großen Countdown bis zum 1. Geburtstag. Lächeln!'),
  ('6032f94e-69e7-4802-b291-44567c9f71d1', 'Papas Schlaflied 👨‍🍼', 'Heute Abend ist dein Partner an der Reihe und darf versuchen, das Baby allein im Zimmer zum Schlafen zu bringen.'),
  ('7b460d4a-b37e-465f-9c70-e137f59bcc07', 'Aufräumen oder ausruhen? 🛋️', 'Lauf nicht gleich zum Geschirrspüler, wenn dein Baby schläft. Leg dich aufs Sofa, schließe die Augen und atme einfach 15 Minuten lang durch. Bist du ein Roboter? Nein.'),
  ('a1392cb5-508d-45a8-9d3d-1985c8d19958', 'Die Nein-Phase beginnt 🛑', 'Wenn du deinem Baby etwas gibst, das es nicht mehr mag, schüttelt es den Kopf und schiebt es weg. Sein eigener Wille entwickelt sich. Versuche, seine kleinen Entscheidungen zu respektieren.'),
  ('2cc5ac97-f2b1-4c92-8852-fec32f54b311', 'Geräusche im Griff 🤫', 'Die erste halbe Stunde nach dem Einschlafen ist die empfindlichste Zeit. Prüfe die Lautstärke im Raum mit einem Schallpegelmesser und vermeide plötzlichen Lärm.'),
  ('e0b42cd5-f681-4866-a7ec-b0b890444381', 'Gesunde Mama, gesundes Baby 🥑', 'Deine Eisen- und Kalziumspeicher sind aufgebraucht. Bereite nach einem gesunden Rezept einen energiereichen Salat zu, der schnell gemacht ist und dich bei Kräften hält.'),
  ('e83a5069-7214-47ea-9051-6406495d5723', '„Gib mir mein Spielzeug!“-Trotz 🧸', 'Wenn du deinem Baby etwas wegnimmst, reagiert es heftig und weint. Sein Besitzgefühl entwickelt sich jetzt vollständig. Statt es ihm zu verbieten, lenke seine Aufmerksamkeit auf etwas anderes.'),
  ('188836b2-55a8-4b14-87fe-653f4e05ae3e', 'Hat dich heute alles genervt?', 'Wenn dein Kind schläft, schreib deine Gefühle in dein Stimmungstagebuch. Morgen wird ein neuer und schönerer Tag.'),
  ('4d566d24-14b9-45b0-be5d-1940c1563ed9', 'Schnell noch einkaufen 🛒', 'Dein Partner hat gleich Feierabend? Öffne schnell die Einkaufsliste und schick ihm in Sekundenschnelle, was zu Hause fehlt – Milch, Obst und andere Dinge.'),
  ('fd0252a6-07bf-4750-bd4b-be91888e16f6', 'Die Großen nachahmen 🧹', 'Du putzt das Haus und dein Kind nimmt ebenfalls ein Tuch und versucht, es dir gleichzutun? Es ist dein Spiegel! Es macht alles nach, was du tust.'),
  ('a789d8f9-cc5b-43fd-8931-a3c5dbb78c75', 'Gemeinsam stark 🥂', 'Trink mit deinem Partner eine Tasse Tee, lasst gemeinsam die Anspannung des Tages hinter euch und sagt euch: Auch heute haben wir es geschafft.'),
  ('ac527e8b-ca16-4272-b6ba-964f15ba419b', 'Fragen zur Kindergesundheit 🤖', 'Wie groß sollte eine Portion für ein 10 Monate altes Baby sein? Mach dir keinen Stress – bitte Anacan AI um eine genaue, kinderärztlich geprüfte Übersicht.'),
  ('e38208ca-c817-4de4-ba96-5a5ca4752901', 'Das Zahnfleisch juckt weiterhin 🦷', 'Hat dein Baby ständig die Finger im Mund und kaut auf allem herum? Vielleicht sind die Backenzähne unterwegs. Halte den aktuellen Stand im Zahnungs-Tracker fest.'),
  ('33fb356d-029a-4c8c-bf0d-4b2ad8ed6777', 'Mit Märchen einschlafen 🪄', 'Erstelle bei den intelligenten Märchen eine besondere Klangkulisse, die nur aus Musik und Naturgeräuschen besteht. Keine Worte, nur Ruhe und Geborgenheit.'),
  ('3e6ba90a-e6bd-4527-a0cb-94dcb9fecfac', 'Freundschaft mit dem Park 🌳', 'Findet dein Baby Spaziergänge im Kinderwagen langweilig? Prüfe das Wetter und seine Kleidung und lass es im Park frei den Boden, das Gras und die Blätter berühren.'),
  ('d3bac322-3971-4b22-8636-d789ac7ce8db', 'Es läuft an der Wand entlang 🧗‍♀️', 'Sich seitwärts an Möbeln entlangzubewegen, ist seine Lieblingsübung. Jetzt ist der perfekte Zeitpunkt, Sicherungen und scharfe Kanten noch einmal zu überprüfen.'),
  ('6498b35b-aa8e-416f-9da1-2596c74b14d0', 'Wir sagen Tschüss 👋', 'Wenn jemand zur Tür hinausgeht, winkt dein Baby von sich aus zum Abschied! Ein wunderbarer sozialer Reflex.'),
  ('b49f5612-c3e4-4568-8a0e-3494499a88d1', 'Ist dein Baby mitten in der Nacht ohne erkennbaren Grund aufgewacht und weint ununterbrochen? 😭', 'Nimm es ruhig in den Arm und versuche nicht, es aufzuwecken. Lass die Schreianalyse den Ton analysieren, um sicherzugehen.'),
  ('fd05df6d-36c8-4c59-9212-7542837f9f4c', 'Zeit zum Reden 💬', 'Belastet dich der Gedanke, dass du nie wieder die Alte sein wirst? Teile dieses vorübergehende Gefühl mit den Müttern in der Anacan-Community. Du bist nicht allein.'),
  ('0535564e-f2c8-4264-bd71-a94e3154d928', 'Wetter-Check ⛅', 'Draußen ist das Wetter nicht ganz eindeutig? Das Wetter- und Kleidungs-Tool zeigt dir sofort die Windgeschwindigkeit, die du vom Fenster aus nicht erkennen kannst, und empfiehlt das passende Outfit.'),
  ('51cec612-e243-435d-9b60-1e3269d69cee', 'Musikalische Abende 🎶', 'Am einfachsten lassen sich die Quengeleien am späten Nachmittag beruhigen, indem du das Lieblingslied deines Babys anmachst, es in den Arm nimmst und mit ihm tanzt.'),
  ('533a4ec1-68c0-4cf3-92cd-723b3f8c0979', 'Zieht seine Schuhe selbst aus 👟', 'Ist das Anziehen inzwischen zu einem Ringkampf geworden? Dein Baby zieht seine Socken und Schuhe schon selbst aus. Freu dich über seine motorischen Fähigkeiten!'),
  ('7bbccad8-a83a-493c-82e1-d823d261e04b', 'Logikspiele 🧩', 'Wirft dein Baby Spielzeug in eine Kiste und leert sie anschließend wieder vollständig aus? So entwickelt es sein Verständnis für „drinnen“ und „draußen“. Unterbrich es bei dieser Beschäftigung nicht.'),
  ('84cdedf9-5de5-49c9-887b-6f8ccc988990', 'Papas Nachtschicht 👨‍🍼', 'Bewältige das nächtliche Aufwachen nicht ganz allein. Weck auch deinen Partner – ein Team zu sein bedeutet, die Verantwortung gerecht zu teilen.'),
  ('a4c45285-b9cc-4763-a80c-d694137bbb6a', 'Ein Ort zum Durchatmen für Mama ☕', 'Bei all dieser Erschöpfung musst auch du einmal durchatmen. Finde unter den mama-freundlichen Orten ein ruhiges Café in deiner Nähe und gönn dir eine kleine Auszeit.'),
  ('37e8bf23-2dc4-4b8c-8c8f-49146922ba57', 'Versuch und Irrtum 🧱', 'Dein Baby versucht, zwei Spielzeugwürfel aufeinanderzustellen, doch sie fallen um. Aufmerksam probiert es immer wieder. Beobachte seine kleinen technischen Experimente ganz in Ruhe.'),
  ('732cb07a-0e5f-4dc9-9d15-78470db05396', 'Ideen für Mahlzeiten 🍲', 'Bist du es leid, immer wieder das Gleiche zu kochen? Entdecke gesunde Rezepte für neues und leckeres Fingerfood für 10 Monate alte Babys.'),
  ('a387d51e-9e9d-455a-be61-4650ee6ffa63', 'Ruhiges Zimmer, ruhiger Kopf 🤫', 'Wenn sich dein Baby auf den Schlaf vorbereitet, solltest du den Geräuschpegel im Zimmer senken. Prüfe mit einem Schallpegelmesser die Lautstärke deiner Stimme und der Umgebung.'),
  ('439ac8e3-ab5f-434a-bb69-d98dee8208cd', 'Ein ganz persönliches Märchen 🪄', 'Erschaffe in den intelligenten Märchen eine Geschichte über den kleinen Helden, der in nur 10 Tagen ein Stück größer sein wird, und erfülle das Zimmer mit Magie.'),
  ('e8d1cc1f-b4b8-4874-a0cc-8f10d75b5769', 'Nur noch 10 Tage bis zum 11. Monat! 🎂', 'Unglaublich! In genau 10 Tagen wird dein Baby 11 Monate alt. Jetzt ist der perfekte Zeitpunkt, um über die Feier zum 1. Geburtstag nachzudenken!'),
  ('ff800946-b6d3-4e88-8699-fe114e37b692', 'Ein Foto voller Lächeln 📸', 'Dein Baby entwickelt sich jeden Tag zu einer einzigartigeren und süßeren kleinen Persönlichkeit. Öffne gleich das Baby-Fotoshooting, verziere das Bild mit Stickern und halte diesen fröhlichen Moment für immer fest.'),
  ('16cae145-7589-4ff6-ae2c-368fe115d232', 'Gefühle im Griff 📝', 'Deine Nerven liegen blank und du könntest jeden Moment explodieren? Schreib den ganzen Stress in dein Stimmungstagebuch und atme tief durch.'),
  ('9b99e928-dd9a-40d6-9254-12459dac4a3d', 'Freundschaft mit der Dunkelheit 🌙', 'Baue das Kennenlernen der Dunkelheit in eure Abendroutine ein, damit dein Baby schneller einschläft. Schalte alle zusätzlichen Lichtquellen im Zimmer aus.'),
  ('ee2e2e79-277e-4a7f-9473-05aa36068880', 'Kennt seine Körperteile 👀', 'Berührt es seine Nase und zeigt darauf, wenn du fragst: „Wo ist deine Nase?“ Seine kognitive Auffassungsgabe ist gerade auf dem Höhepunkt!'),
  ('2cb20f11-aee5-456a-b969-c87733104c72', 'Ein Abend zum Feiern 🥂', 'Stoßt heute Abend, nachdem euer Baby eingeschlafen ist, gemeinsam darauf an: „Wir sind ein großartiges Team!“ Ihr macht das wirklich fantastisch!'),
  ('57b926b9-28cb-4c4e-8863-8ce72241c9fe', 'Verdacht auf eine Allergie 🤖', 'Du hast ein neues Lebensmittel eingeführt und Rötungen an den Wangen bemerkt? Bevor du in Panik gerätst, frag Anacan AI nach den ersten Schritten.'),
  ('9c11d140-acfd-48e4-9fef-141a9e34586d', '„Ich will selbst essen!“ 🥦', 'Dein Baby möchte dir den Löffel aus der Hand nehmen. Lass es ruhig. Es wird sich bekleckern, aber dieses Gefühl der Selbstständigkeit ist für dein Baby sehr wichtig.'),
  ('09817e37-4e65-43f6-968c-dd333358e01e', 'Die Einkaufsliste wird nie kürzer 🛒', 'Ist im täglichen Chaos das Shampoo oder sind die Windeln ausgegangen? Versuch nicht, dir alles zu merken: Schreib es auf die Einkaufsliste und synchronisiere sie mit deinem Partner.'),
  ('1f244347-1957-4238-988d-4563adba7bcd', 'Papas Nachtschicht 👨‍🍼', 'Du bist vom Tag schon müde genug. Abends das Baby fürs Schlafengehen fertig zu machen und ihm eine Geschichte vorzulesen, ist allein Papas Aufgabe.'),
  ('9f618083-9332-44d7-8a8f-8ad3af6c22ac', 'Zu Hause wird alles zum Spielzeug 🥄', 'Plastikbehälter und Holzlöffel sind für dein Baby spannender als das teuerste Spielzeug. Lass es die Küchenutensilien ungestört entdecken.'),
  ('354e039c-3978-4aa3-a008-1a3a7bbe85a3', 'Die Schreianalyse hilft weiter 😭', 'Dein Baby ist mitten in der Nacht aufgewacht und lässt sich nicht beruhigen? Hör auf zu rätseln und finde mit der Schreianalyse sofort den Grund heraus.'),
  ('8fb53566-815d-4365-b87c-c14288ebb122', 'Frische Luft wirkt Wunder 🌳', 'Wenn die Stimmung zu Hause kippt, prüfe Wetter und Kleidung, setz dein Baby in den Kinderwagen und geh direkt in den Park. In der Natur beruhigt es sich meist am schnellsten.'),
  ('c87df5f1-fbe2-4462-a617-a6649445ce77', 'Die Quengelphase erreicht ihren Höhepunkt ☁️', 'Dein Baby ist mit nichts zufrieden und weint wegen jeder Kleinigkeit? Vielleicht steckt ein Wachstumsschub oder Zahnungsbeschwerden dahinter. Schenk ihm jetzt einfach ganz viele Kuscheleinheiten.'),
  ('7fd53d22-26ef-4c4c-83bb-d44647b94560', 'Gemeinsam finden wir eine Lösung 💬', 'Hast du es satt, dich zu fragen: „Warum macht mein Kind das?“ Schau in der Anacan Community vorbei und entdecke, dass es in Tausenden Familien ganz genauso läuft!'),
  ('a6ef3f7c-7550-4712-8fc9-23c742a51744', 'Sanft in den Schlaf 🛀', 'Ein warmes Bad hilft fast immer. Behalte die Abendroutine unbedingt bei, denn sie signalisiert seinem Gehirn, dass jetzt Schlafenszeit ist.'),
  ('d6154f3b-6df3-4af3-97e7-fdfd798b8cfb', 'Hinfallen, aufstehen, lernen 🧗‍♂️', 'Beim Stehen fällt dein Baby auf den Po, lacht und steht wieder auf. Durch diese Stürze entwickelt sich das Muskelgedächtnis – greif deshalb nicht zu oft ein.'),
  ('25903ac8-0fd6-44f0-92d8-c3e1bee035e5', 'Ruhe ist wichtig 🤫', 'Wacht dein Baby beim Einschlafen schon vom kleinsten Knacken auf? Analysiere die Umgebung mit einem Schallpegelmesser und sorge für ungestörte Ruhe.'),
  ('3a5c700f-e10c-4819-bba1-cddd9f951f4f', 'Listen gegen Vergesslichkeit 🛒', 'Will der Gedankenebel einfach nicht verschwinden? Versuche nicht, dir jeden kleinen Einkauf zu merken: Trag ihn sofort in die Einkaufsliste ein und lass deinen Partner den Rest erledigen.'),
  ('47b342b1-9525-44b6-b917-2eb642240cb2', 'Eine „Ich liebe dich“-Umarmung 🫂', 'Kommt dein Kind plötzlich zu dir, umarmt dich oder streichelt dein Gesicht? Es zeigt seine Liebe jetzt auch körperlich. Genieße diesen Moment.'),
  ('932e2f32-ffee-4b5c-9d10-16c135453b42', 'Morgen ist der große Tag! 🎉', 'Bist du bereit? Morgen wird dein Baby genau 11 Monate alt! Nur noch 1 Monat bis zum ersten Geburtstag! Bereite für das Baby-Fotoshooting eine besondere Kulisse und ein schönes Outfit vor.'),
  ('aac354e5-8061-403a-8cf7-d00ce05e4093', 'Gemeinsam stark 🥂', 'Öffne dein Stimmungstagebuch, erinnere dich gemeinsam mit deinem Partner an die ersten Tage und lacht zusammen darüber. Der Weg durch diese 11 Monate war nicht immer leicht!'),
  ('d24d332c-e00e-4b7f-8dac-28439e172c26', 'Mamas Kaffeepause ☕', 'Das Chaos im Zimmer läuft nicht weg, aber deine Energie kann zur Neige gehen. Wenn dein Kind selbstständig spielt, stürze dich nicht sofort auf die Hausarbeit. Setz dich hin und genieße deinen Kaffee.'),
  ('6ef8817b-2854-4da4-969a-fe13d344017a', 'Freudentanz 💖', 'Feiere heute Abend gemeinsam mit deinem Partner die Erschöpfung und den Stolz der vergangenen 11 Monate. Ihr seid auf der Zielgeraden zum ersten Geburtstag!'),
  ('8c48dfb8-f3cc-4402-82d4-4c81ed9fc15b', 'Muttermilch bleibt wichtig! 🍼', 'Bis zum Alter von 1 Jahr ist Muttermilch weiterhin wichtig. Starte den Ernährungstimer, um sicherzustellen, dass der tägliche Milchbedarf deines Babys gedeckt wird.'),
  ('ad9c3e79-16bb-44a7-9f37-6f5935a4494c', 'Genau 11 Monate! 🎂', 'Herzlichen Glückwunsch! Seit der Geburt sind genau 11 Monate vergangen! Wähle jetzt beim Baby-Fotoshooting den Sticker für 11 Monate aus und teile deine Freude mit der Anacan-Community!'),
  ('23c2a94e-cf0d-4f81-9604-79b4dcfb2460', 'Raus aus den vier Wänden ⛅', 'Fällt euch zu Hause die Decke auf den Kopf? Prüfe das Wetter, zieh dein Baby passend an und lass es im Park nach Herzenslust Gras und Blätter auf dem Boden berühren.'),
  ('77a8c135-4a26-4877-9f24-fc51c941fb7a', 'Hilft beim Anziehen 👕', 'Streckt dein Baby beim Anziehen des Oberteils selbst die Arme aus oder hebt es ein Bein? Es arbeitet mit dir zusammen. Halte diesen kleinen Entwicklungsschritt im Entwicklungstracker fest.'),
  ('9df28291-b590-4e7d-a861-feb0732398b2', 'Freundschaft mit der Dunkelheit 🌙', 'Ergänze eure Abendroutine um eine Gewöhnung an die Dunkelheit, damit dein Baby schneller einschläft. Schalte alle zusätzlichen Lichtquellen im Zimmer aus.'),
  ('72f5aeb4-94f9-40bc-943e-fa87664da32b', 'Verlier dich nicht in Foren 🤖', 'Ist dir etwas Ungewöhnliches an den Bewegungen deines Kindes aufgefallen? Suche nicht stundenlang im Internet, sondern stelle deine Frage direkt der Anacan AI und beruhige dich.'),
  ('c8b05bf8-0ed8-4eec-86f7-4cba168167e1', 'Versteht die Bedeutung von Wörtern 🗣️', 'Wenn du dein Baby bittest, den Ball zu holen, geht es tatsächlich los und sucht danach. Sein passiver Wortschatz – also die Wörter, die es versteht – wächst rasant. Sprich mit ihm in komplexeren Sätzen.'),
  ('f8aae6d9-1b70-4333-a55c-1937c871c533', 'Zeit für ein smartes Märchen 🪄', 'Erstelle in „Smarte Märchen“ eine Geschichte über eine Hauptfigur, die in nur einem Monat ein Jahr alt wird. Lass nur dieses Märchen die nächtliche Stille durchbrechen.'),
  ('361e96e8-a6ed-4fdf-a7bb-50e07abcec66', 'Die Ruhe der Nacht 🪄', 'Erschaffe in den smarten Märchen Geschichten über mutige, liebenswerte Tiere und verwandle das Zimmer in einen magischen Ort.'),
  ('a4baaa67-c9fb-4208-aab7-e7515b21f64f', 'Du tust alles, damit dein Baby satt wird. Und du?', 'Wähle in der Rubrik mit gesunden Rezepten ein Mittagessen voller Eisen und Eiweiß und tanke neue Kraft.'),
  ('c58c8b30-4c95-4f60-98d7-d9580eb48a38', 'Die Buchseiten werden umgeblättert 📖', 'Blättert dein Baby die Seiten von Pappbilderbüchern schon ganz allein um? Halte diesen motorischen Meilenstein im Entwicklungstracker fest.'),
  ('2631ed9f-967a-4f12-9097-1f619f7f1e5f', 'Heute lief nichts nach Plan?', 'Hab kein schlechtes Gewissen, wenn dein Kind schläft. Du bist eine echte Mama – und du bist perfekt.'),
  ('34415812-3e31-43f2-99de-a1dd76bb1d9e', 'Gezielte Würfe ⚾', 'Dein Baby versucht, das Spielzeug in seiner Hand bewusst auf ein bestimmtes Ziel zu werfen. Die Hand-Auge-Koordination entwickelt sich rasant.'),
  ('ec7ed8d1-bb0f-4b34-a7a5-da3857dfd5d4', 'Schneller Kinderarzt 🤖', 'Wie lang sollte der Mittagsschlaf eines 11 Monate alten Babys sein? Frag Anacan AI sofort alles, wobei du unsicher bist, und sei beruhigt.'),
  ('78c638dd-68ed-4cf9-acf9-6738b0e5ec7f', 'Gefahrenzonen in Reichweite ⚡', 'Dein Baby ist wieder ein Stück gewachsen und erreicht nun Regale, an die es vorher nicht herankam. Überprüfe erneut die Sicherheit zu Hause – insbesondere scharfe Kanten und schwere Gegenstände.'),
  ('8a4a7da2-606f-4fbb-8668-101f2d47c03c', 'Die Kraft der Musik 🎶', 'Versuche, scheinbar grundlose Unruhe am späten Nachmittag mit sanfter klassischer Musik zu beruhigen. Oft wirkt dieser einfache Trick Wunder.'),
  ('a70ebacf-44d0-4367-babf-09742bda8fa8', 'Der Trubel um den ersten Geburtstag beginnt! 🎈', '11 Monate liegen hinter euch. In nur 30 Tagen steht der erste Geburtstag an! Ein Motto, eine besondere Location oder einfach zu Hause feiern? Beginne langsam mit der Planung.'),
  ('0387bc9b-1c64-4eae-ac49-660cb56552f8', 'Ich finde mein Spielzeug selbst 🧸', 'Findet dein Baby ein Spielzeug wieder, das du vor seinen Augen weggenommen und irgendwo versteckt hast? Dann hat es die Objektpermanenz vollständig verstanden!')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_de = v.t, body_de = v.b
FROM (VALUES
  ('6b5c2e80-bfa3-452b-805d-82d54c6b5d2d'::uuid, 'Papas Nachtschicht 👨‍🍼', 'Bewältige das nächtliche Aufwachen nicht ganz allein. Wecke auch deinen Partner – ein Team zu sein bedeutet, die Verantwortung gleichmäßig zu teilen.'),
  ('89a2b668-b451-4cfe-a183-3183fc159297', 'Lass deinen Gefühlen freien Lauf 📝', 'Spürst du kurz vor dem ersten Geburtstag eine seltsame Wehmut und denkst: „Wie schnell mein Baby groß geworden ist“? Halte diese Gefühle in deinem Stimmungstagebuch fest.'),
  ('0ca61e8f-0ab9-48ea-85e7-af32b2be41a1', 'Deko und Luftballons für den 1. Geburtstag?  🛒', 'Mach dir keinen Kopf und beginne schon jetzt mit deiner Einkaufsliste.'),
  ('519cad33-f5e8-4169-8f1d-93f4343568db', 'Hartnäckige Versuche 🧗‍♂️', 'Mit einem Spielzeug in der Hand versucht dein Baby, sich an Möbeln hochzuziehen. Sein Gleichgewichtssinn hat sich unglaublich verbessert. Beobachte es aus der Nähe, ohne einzugreifen.'),
  ('aa2fb7c9-acf7-4050-9102-4f2927091b95', 'Leise Heldin 🤫', 'Sobald dein Baby eingeschlafen ist, klingt jedes Geräusch im Haus wie eine Explosion. Lege mit dem Schallpegelmesser einen Grenzwert für das Zimmer fest und schleiche selbst auf leisen Sohlen.'),
  ('9cba5d69-92c6-472c-bb83-c5522d806018', 'Unter Müttern 💬', 'Die Frage „Wie soll ich den Geburtstag feiern?“ lässt dir keine Ruhe? Schreib in die Anacan Community und hol dir von anderen Müttern kreative, budgetfreundliche Ideen.'),
  ('f558e782-e140-4835-8b11-1d5f01a717bf', 'Ein Moment, der die Zeit anhält 📸', 'Dein Baby sieht jeden Tag ein bisschen mehr wie ein Kleinkind aus. Öffne gleich das Baby-Fotoshooting und halte diesen zauberhaften Tanzmoment für immer fest.'),
  ('f56842a9-3a83-4016-8e93-a096810c45d3', 'Tanz und Rhythmus 🎶', 'Tanzt dein Baby, sobald es im Fernsehen oder auf dem Handy einen Rhythmus hört? Sein Gespür für Musik ist jetzt voll entwickelt – mach mit und tanzt gemeinsam!'),
  ('510bccc7-40fa-4c0b-8d0b-8a3105fd00ea', 'Sicherheitsmaßnahmen zu Hause! 🛡', '️ Sobald dein Baby selbstständig unterwegs ist, nehmen die Gefahren zu. Sieh dir unbedingt unsere Liste empfohlener Produkte für Kindersicherungen und Treppenschutzgitter an.'),
  ('959729c5-8ab6-4053-99ca-82aa5fdabc7e', 'Zeit für gemeinsame Fürsorge mit Papa. 👨‍🍼', 'Überlass Papa nach der abendlichen Mahlzeit das Vorlesen und Zubettbringen, während du ein kurzes Nickerchen machst.'),
  ('a478b2eb-eaec-4b54-813a-6f2ba55a5d14', 'Es zeigt auf alles mit dem Zeigefinger! ☝', '️ Statt „Was ist das?“ zu sagen, zeigt dein Baby mit dem Finger auf alles. Halte diese neugierige Phase im Babyalbum fest.'),
  ('97023662-0ba2-4bcd-aff7-bc7adf5883ba', 'Geräusche im Blick behalten 🤫', 'Die erste halbe Stunde nach dem Einschlafen ist die empfindlichste Phase. Überprüfe die Umgebung mit einem Schallpegelmesser und vermeide plötzlichen Lärm.'),
  ('d02f135b-16bc-4fa9-978f-0e7d992c1ba4', 'Aufräumen oder ausruhen? 🛋️', 'Wenn dein Baby schläft, lauf nicht gleich zum Geschirrspüler. Leg dich aufs Sofa, schließ die Augen und atme 15 Minuten lang einfach nur durch.'),
  ('f12c7751-b89f-4d12-a843-8e331c338393', 'Dein Baby baut eine Burg aus Bauklötzen 🧱', 'Es versucht, zwei oder drei Bauklötze aufeinanderzustapeln. Beobachte diese kleinen Bauversuche in Ruhe und applaudiere deinem Baby.'),
  ('35ab2e31-1937-4e58-b764-83729c6e330a', 'Antworten mit Körpersprache 🗣️', 'Wenn du „Gehen wir?“ fragst, hebt dein Baby die Arme, und bei „Nein“ schüttelt es den Kopf. Sein Sprachverständnis hat sich unglaublich weiterentwickelt.'),
  ('65a36f4e-0f24-45fe-a038-a2e61c778c81', 'Sei stolz auf dich 👏', 'Schau nicht auf das unordentliche Zimmer, sondern darauf, wie glücklich dein Kind heute war. Du bist eine großartige Mama – das kann dir kein Buch der Welt beibringen.'),
  ('7b75b0ec-d253-4e5a-bfac-9ff801269b5f', 'Heute im interaktiven Märchen 🪄', 'Erstelle eine besondere Geschichte, in der dein Kind die Hauptrolle spielt: Der kleine Löwe bereitet sich auf seinen ersten Geburtstag vor.'),
  ('01302c3b-60e6-4b0a-8a88-e63349585527', 'Sorgen vor dem 1. Geburtstag? 💬', 'Kreisen dir Fragen wie „Mein Kind läuft noch nicht – ist es spät dran?“ ständig im Kopf herum? Schreib darüber in der Anacan Community. Dort wirst du sehen, dass jedes Kind sein eigenes, genau richtiges Tempo hat und du nicht allein bist.'),
  ('51d3f88a-4baa-4ed5-b62c-e84a750f8166', 'Papas Nachtschicht 👨‍🍼', 'Du musst die nächtlichen Wachphasen nicht ganz allein bewältigen. Weck auch deinen Partner – ein Team zu sein bedeutet, die Verantwortung gleichberechtigt zu teilen.'),
  ('984d2a76-5fec-4059-86ef-85671516c9b6', 'Wetter-Check ⛅', 'Das Wetter draußen ist unbeständig? Das Wetter- und Kleidungstool zeigt dir sofort die Windgeschwindigkeit und das passende Outfit an.'),
  ('357cf8f4-8f26-47ee-9a7b-b3db1bd2898e', 'Gesunde Mama, gesundes Baby 🥑', 'Deine Eisen- und Kalziumspeicher sind aufgebraucht. Bereite nach unseren gesunden Rezepten einen schnellen, energiereichen Salat zu, der dir neue Kraft gibt.'),
  ('7883fd83-494d-41a3-b42d-58d452de13d7', 'Papas lustige Seite 🤡', 'Am besten bringt Papa das Baby mit seinen komischen Geräuschen zum Lachen. Genießt heute Abend gemeinsam diese fröhlichen Momente.'),
  ('981d8d60-ab26-4f64-a20b-eee1dc2fed12', 'Jetzt vollständig auf Stückchenkost umsteigen! 🍲', 'Dein Baby kann jetzt Lebensmittel essen, die es kauen muss. Probiere mit den Rezepten für Babys, die mit der Beikost beginnen, in unserer App neue Konsistenzen aus.'),
  ('74f02405-1cdd-401e-bb47-01d87997f231', 'Zeit zum selbstständigen Spielen 🧸', 'Dein Baby kann sich jetzt 10-15 Minuten lang allein mit seinen Spielsachen beschäftigen. Das zeigt, dass seine Aufmerksamkeitsspanne länger wird. Beaufsichtige es aus der Nähe und genieße die Ruhe.'),
  ('8d91b32b-a0f2-4a07-a181-da0b746268bc', 'Park oder lieber zu Hause? ⛅', 'Du möchtest nach draußen, aber es ist windig. Lass dir vom Wetter- und Kleidungsassistenten nicht nur die Temperatur anzeigen, sondern auch, welche winddichte Kleidung du deinem Baby anziehen solltest.'),
  ('9890a3bf-dcd7-4d43-8ef7-e98ca087bf8e', 'Hartnäckige Nächte 🥱', 'Wehrt sich dein Baby mit aller Kraft gegen das Einschlafen? Überprüfe noch einmal seine Tagesschläfchen und die Schlafroutine.'),
  ('2f4fbaac-dfe4-48b5-b844-6636c2bc201a', 'Deine Liste für unterwegs 🛒', 'Sieh dir in Anacan die Tortenoptionen an, um die Torte für den 1. Geburtstag zu bestellen.'),
  ('395ddd9b-9009-4fec-ba6f-816d156ad432', 'Große Gefühle, kleiner Körper 🛑', 'Wirft sich dein Kind auf den Boden oder weint, wenn es nicht bekommt, was es möchte? Es kann seine Gefühle noch nicht regulieren. Geh auf Augenhöhe und sprich ruhig mit ihm, um gemeinsam durch den Wutanfall zu kommen.'),
  ('d824145b-4905-49d1-9f4f-46ade8a730f8', 'Plötzlich schreiend aufgewacht? 😭', 'Es könnte sich um einen Nachtschreck handeln. Lass die Weinanalyse die Geräusche auswerten, um herauszufinden, ob die Ursache körperlich oder psychisch ist.'),
  ('a7923459-9b74-4330-949d-00e94d185768', 'Was „Nein“ bedeutet! 🛑', 'Beobachtet dein Kind bereits deine Reaktion, wenn es etwas tut, das es nicht tun soll? Lass dich von Anacan AI zu den ersten Schritten liebevoller Grenzsetzung beraten.'),
  ('ec1173c9-8c5f-4b55-8ebd-5fdf69b08da1', 'Zeit für eine Massage 💆‍♂️', 'Wenn euer Kind eingeschlafen ist, könnt ihr euch gegenseitig mit einer Schultermassage verwöhnen und den Stress des Tages loslassen. Ihr seid ein Team!'),
  ('ef821341-2506-439d-8346-fbafb2b792ff', 'Nur noch 25 Tage bis zum 1. Geburtstag! 🎈', 'Der Countdown hat offiziell begonnen! Habt ihr schon über einen Ort und ein Outfit für das Fotoshooting zum 1. Geburtstag nachgedacht? Legt mit den Vorbereitungen los!'),
  ('063ccb8e-7bd6-43e4-9c41-f30c172e10a7', 'Gesunde Mama, gesundes Baby 🥑', 'Deine Eisen- und Kalziumspeicher sind erschöpft. Bereite aus unseren gesunden Rezepten einen Salat zu, der schnell gemacht ist und dir neue Energie gibt.'),
  ('1bed0d5c-444a-48fc-8e21-35fd8fff35b5', 'Nur noch 20 Tage bis zum 1. Geburtstag! 🎂', 'Wie schnell die Zeit vergeht! Beginne damit, Notizen zu Geburtstagseinladungen, Listen und kleinen Überraschungen zu machen.'),
  ('caa0a9a0-1a0d-4362-a446-9f103d33e564', 'Ein Moment, der die Zeit anhält 📸', 'Wenn dein Baby gerade süß im Zimmer spielt, öffne gleich das Baby-Fotoshooting und halte seine schon so große Persönlichkeit fest.'),
  ('3cc5a97d-281f-41bf-8747-fbb71f040e65', 'Dimme das Licht 🌙', 'Schalte 1 Stunde vor dem Schlafengehen alle hellen Lichter und Bildschirme zu Hause aus. Melatonin wird nur in einer ruhigen, schwach beleuchteten Umgebung ausgeschüttet.'),
  ('528b02c4-9d93-4cda-add4-eb9a04a4395a', 'Lebensmittel, die deine Milchbildung unterstützen. 🍲', 'Probiere heute die milchbildungsfördernden Suppen aus der Rubrik „Gesunde Rezepte für Frauen“ und stärke dich.'),
  ('a889d8c9-3ffc-4f2f-8c82-a33c81ad3e8d', 'Hast du vergessen, an welcher Brust du gestillt hast? 🤱', 'Der Anacan-Timer merkt sich für dich, ob du rechts oder links gestillt hast. Starte jetzt den Timer für die Stillmahlzeit!'),
  ('20db1e8e-1980-431d-800c-b7aa4ccf158b', 'Erste Versuche, selbst mit dem Löffel zu essen! 🥄', 'Versucht dein Baby schon, den Löffel zu halten und zum Mund zu führen? Unterstütze diese unterhaltsamen Momente, indem du geeignete Lebensmittel für den Beikoststart auswählst.'),
  ('77cedc71-0d6f-45f7-a8a4-9ddfcd0a5be6', 'Mit einem Märchen einschlafen 🪄', 'Erstelle bei den intelligenten Märchen eine besondere Geräuschkulisse, die nur aus Musik und Naturgeräuschen besteht. Keine Worte, einfach nur Ruhe.'),
  ('eca3e78d-00de-4e77-bade-43808f152e4f', 'Liebevolle Küsschen 🥰', 'Beugt sich dein Baby zu dir, spitzt die Lippen oder macht deine Wange nass, wenn du es küsst? Seine kleinen Küsschen können all deine Müdigkeit wie von Zauberhand vertreiben.'),
  ('863a6afb-427b-4143-a527-2e01fe303116', 'Papas lustige Grimassen 🤡', 'Am besten bringt Papa das Baby mit seinen lustigen Geräuschen zum Lachen. Genießt heute Abend gemeinsam diese fröhlichen Momente.'),
  ('b4676fcf-2967-4b49-adbd-12ebe6a54334', 'Zeit für einen Herzensaustausch 💬', 'Macht dich der Gedanke „Ich kann nicht glauben, dass mein Baby schon 1 Jahr alt ist“ emotional? Teile dieses wunderschöne Gefühl mit den anderen Mamas in der Anacan-Community.'),
  ('b86239c1-4a1c-48b3-b49a-3fd4a012ebae', 'Nur noch 15 Tage bis zum 1. Geburtstag! 🎈', 'Da kommt Nostalgie auf! Erinnerst du dich noch an den ersten Tag, als ihr die Geburtsklinik verlassen habt? Und jetzt bereitet ihr euch schon auf den 1. Geburtstag vor! Lege beim Baby-Fotoshooting das erste und das aktuelle Foto nebeneinander!'),
  ('222d12a8-4347-4dce-afd7-4a0890721d0b', 'Hartnäckige Nächte 🥱', 'Wehrt sich dein Baby mit aller Kraft gegen das Einschlafen? Vielleicht ist es an der Zeit, eines der Tagesschläfchen wegzulassen. Überprüfe eure Routine.'),
  ('5047e51c-64dc-4fe5-bc38-0409a743d0f6', 'Zeit, Größe und Gewicht zu überprüfen! 📏', 'Bis zur Untersuchung mit 1 Jahr ist es nicht mehr lange. Aktualisiere die neuesten Angaben im Bereich zur Entwicklungsverfolgung und freue dich über die gesunde Wachstumskurve.'),
  ('873f2996-36df-4d67-a2df-ec60f668be2f', 'Der Essensturm ist eingestürzt 🥣', 'Wirft dein Baby den Löffel absichtlich auf den Boden und schaut dich dabei an? Es testet die Schwerkraft und deine Reaktion. Bleib geduldig – das ist eine Form des Spielens.'),
  ('8cd57628-b75f-4445-8bc9-6b180e6572dc', 'Heute im smarten Märchen 🪄', 'Erstelle in den smarten Märchen eine besondere Geschichte, in der dein Kind die Hauptrolle spielt.'),
  ('94b60a89-bc34-41d8-818c-174aa7ed663b', 'Aufräumen oder ausruhen? 🛋️', 'Wenn dein Kind schläft, lauf nicht gleich zum Geschirrspüler. Leg dich aufs Sofa, schließe die Augen und atme einfach 15 Minuten lang durch. Bist du ein Roboter? Nein.'),
  ('c7b84129-89ab-4610-b19f-84959d6194f9', 'Schrankdetektiv 🕵️‍♀️', 'Stehen alle Töpfe aus der Küche auf dem Boden? Das Spielen mit ungefährlichen Gegenständen fördert das logische Denken deines Babys. Lass es ungestört auf Schatzsuche gehen.'),
  ('152edc3c-3a8c-41ee-81bb-0df222f2c1ea', 'Nur noch 2 Wochen! 🎈', 'Bis zum Geburtstag sind es nur noch 14 Tage! Da kommt Nostalgie auf … Öffne die Babyfotos und vergleiche ein Bild vom Tag der Geburt mit einem aktuellen Foto – so kannst du staunend sehen, wie sehr dein Baby gewachsen ist.'),
  ('87c2d4c6-8130-43a1-8ff7-fa406c018013', 'Papas Nachtdienst 👨‍🍼', 'Die Erschöpfung am Tag ist schon genug für dich. Abends ist Papa dafür zuständig, das Baby bettfertig zu machen und eine Geschichte vorzulesen. Du setzt einfach deine Kopfhörer auf.'),
  ('d1325a58-5701-4db5-a92f-ca67116c5c21', 'Ein paar Sekunden freihändig 🧗‍♂️', 'Lässt dein Baby beim Stehen am Sofa für einen kurzen Moment die Hände los? Es findet gerade sein Gleichgewicht.'),
  ('3beff563-1e72-4a1f-8490-4e977c8b0b7a', 'Was soll ich nur kochen? 🍲', 'Gehen dir kurz vor dem ersten Geburtstag die Ideen für den Speiseplan aus? Bitte Anacan AI um eine Liste mit einfachem Fingerfood, das dein Kind selbst halten und essen kann.'),
  ('eebfea92-7f8e-43d7-a45c-4a10e720b24c', 'Freundschaft mit der Dunkelheit 🌙', 'Mache die Dunkelheit zu einem Teil der Abendroutine, damit dein Baby schneller einschläft. Schalte alle zusätzlichen Lichtquellen und Bildschirme im Zimmer aus.'),
  ('f8f9e691-e184-414d-9abe-ae0a3969929a', 'Mischt sich ins Gespräch ein 🗣️', 'Sagt dein Baby in seiner eigenen Sprache etwas und wird dabei lauter, während du sprichst? Seine Kommunikationsfähigkeit entwickelt sich rasant – jetzt gibt es im Zimmer noch eine zweite Stimme. Hör unbedingt gut zu!'),
  ('5c42ea20-5a84-467a-b408-412bcaaf8374', 'Verändert sich der Tagschlaf? 🥱', 'Wehrt sich dein Baby gegen einen der beiden Tagschläfchen? Wenn es auf den 1. Geburtstag zugeht, kann es Zeit sein, den Schlafrhythmus neu anzupassen.'),
  ('b5252c17-b36e-4334-8221-0dc9210bbc77', 'Ein eigener Platz am Familientisch! 🍲', 'Dein Baby isst inzwischen gerne gemeinsam mit euch. Entdecke in unserer App unter den Rezepten für Babys, die mit Beikost beginnen, köstliche Gerichte für die ganze Familie.'),
  ('ee88eee3-00d7-4463-b0db-60b939d85d4e', 'Hast du eine Frage? 🤖', 'Wie gelingt nach dem 1. Geburtstag die Umstellung auf Kuhmilch? Stelle unserem Anacan AI-Assistenten auch nachts deine wichtigen Fragen und erhalte Unterstützung.'),
  ('48047d55-0e81-4b9a-976d-56b580b1a7b7', 'Fragen zur kindlichen Entwicklung 🤖', 'Was verändert sich bei der Ernährung, wenn dein Baby auf den 1. Geburtstag zugeht? Mach es dir nicht unnötig schwer und bitte Anacan AI um eine klare, kinderärztlich geprüfte Liste.'),
  ('56284941-dca4-4067-9e31-d61fc4ebeb63', 'Unterstützung im Team 🥂', 'Trinkt gemeinsam mit deinem Partner eine Tasse Tee, lasst die Anstrengungen des Tages hinter euch und sagt euch: Auch heute haben wir es geschafft.'),
  ('c69bf08f-8c53-4bb9-8c0e-a81edd03f90e', 'Es führt einfache Aufforderungen vollständig aus! 🧠', 'Dein Baby versteht dich, wenn du sagst: Gib mir den Ball oder komm her. Unterstütze diesen geistigen Entwicklungssprung zusätzlich mit den Artikeln in unseren Blogs.'),
  ('11e743be-fb20-462f-8c74-07c143992d51', 'Noch 10 Tage bis zum 1. Geburtstag! 🎂', 'Die Aufregung steigt! Geburtstagstorte, Kleidung, Gästeliste ... Schreibe alles in den Bereich für besondere Notizen im Stimmungstagebuch, um deine Gedanken zu ordnen.'),
  ('15436a4e-52bb-4539-9146-377403746da0', 'Mamas unter sich 💬', 'Machen dich Fragen wie „Warum läuft mein Kind noch nicht?“ unruhig? Tritt der Anacan-Community bei und du wirst sehen, dass jedes Kind sein eigenes Tempo hat.'),
  ('21394622-dd96-488a-a90a-b8f72d718390', 'Die ersten Schuhe! 👟', 'Die Schritte werden schneller! Schau dir unbedingt unsere Liste mit empfohlenen Produkten an, um die ersten orthopädischen Schuhe mit weicher Sohle zu finden, die eine gesunde Entwicklung der Füße unterstützen.'),
  ('c8d8ec20-b116-4c1f-93ec-b76e6f76a1b1', 'Sicherheitsmaßnahmen zu Hause! 🛡', '️ Je selbstständiger dein Kind läuft, desto mehr Gefahren lauern. Sieh dir unsere empfohlenen Produkte wie Kindersicherungen und Treppenschutzgitter an.'),
  ('cbeda45d-85bc-4e45-b9c0-cc3c3d5c896b', 'Dein veränderter Körper 👗', 'Macht dich der Anblick deines Körpers im Spiegel traurig? Mit diesem Körper hast du einen Menschen erschaffen. Umarme dich selbst und erinnere dich daran, wie stark du bist.'),
  ('f38aba52-8d3a-44ad-96bf-7d9de570ef68', 'Es will immer bei Mama sein 🥰', 'Selbst wenn du nur zur Toilette gehst, wartet dein Kind weinend hinter der Tür auf dich. Die Trennungsangst ist jetzt besonders stark. Gib ihm Sicherheit, indem du immer wieder sagst: „Ich bin da.“'),
  ('03283459-7c0f-4d41-9c06-406552e1c477', 'Die Illusion der Perfektion 🛑', 'Heute lief nichts nach Plan? Mach dir keine Vorwürfe. Du bist eine echte Mutter und keine gefilterte Illusion aus den sozialen Medien.'),
  ('3843a02f-a85f-47a9-97ba-0e63677749e2', 'Stille Heldin 🤫', 'Sobald dein Baby eingeschlafen ist, klingt jedes Geräusch im Haus wie eine Bombe. Während du mit dem Schallpegelmesser den Grenzwert für das Zimmer einstellst, solltest du auch möglichst leise auftreten.'),
  ('fde65599-b651-49fa-a50a-5b78bed58d9f', 'Zeigefinger aktiviert ☝️', 'Dein Baby zeigt mit dem Finger auf einen entfernten Gegenstand und reagiert darauf. Das ist eine wichtige Entwicklungsstufe der gemeinsamen Aufmerksamkeit. Schau dir den Gegenstand gemeinsam mit deinem Baby an.'),
  ('069d21f4-a2ef-4d28-91bb-979c8ca3f3f6', 'Darf ich Kuhmilch geben? 🥛', 'Wenn dein Baby 1 Jahr alt wird, verändert sich sein Speiseplan. Wenn du Fragen zur Einführung von Kuhmilch oder Lebensmitteln wie Honig hast, frag direkt Anacan AI.'),
  ('6b37b92f-5c61-4852-9ace-caab2bda465b', 'Familienausflüge und Pläne! ☕', 'Der Geburtstag steht bald vor der Tür! Unter den mama-freundlichen Orten findest du Cafés, die du bequem mit dem Kinderwagen besuchen kannst, um dich mit Freunden und Familie zu treffen.'),
  ('fedb8c6b-7722-4e20-9134-1af5ae254e85', 'Zeit für eine Massage 💆‍♂️', 'Wenn das Baby eingeschlafen ist, könnt ihr euch gegenseitig mit einer Schultermassage verwöhnen und so den Stress des Tages abbauen. Ihr seid ein Team!'),
  ('0549edc6-63d2-4caa-a43c-f029f7f39465', 'Zahnungsschmerzen 🦷', 'Ist das Zahnfleisch wieder gerötet und läuft ständig der Speichel? Vielleicht sind die ersten Backenzähne unterwegs.'),
  ('1c81021a-496b-49c0-86bc-4bde92ff779d', 'Geräusche im Blick behalten 🤫', 'Die erste halbe Stunde nach dem Einschlafen ist die empfindlichste Zeit. Prüfe die Umgebung mit einem Schallpegelmesser und vermeide plötzlichen Lärm.'),
  ('262cbb13-eb12-4831-9fe5-37ece168bdfa', 'Antworten mit Körpersprache 🗣️', 'Wenn du „Wollen wir gehen?“ fragst, hebt dein Baby die Arme, und bei „Nein“ schüttelt es den Kopf. Sein Sprachverständnis hat sich unglaublich weiterentwickelt!'),
  ('38f7fe28-84d1-4b40-8904-c7ef3e18b0f8', 'Frische Luft wirkt Wunder 🌳', 'Wenn die Stimmung zu Hause kippt, prüfe das Wetter und die Kleidung, setze dein Baby in den Kinderwagen und geh direkt in den Park. In der Natur beruhigt es sich oft am schnellsten.'),
  ('39697061-01f6-4b41-8098-183a43f25058', 'Eine Burg aus Bauklötzen 🧱', 'Dein Baby versucht, zwei oder drei Bauklötze aufeinanderzustapeln. Beobachte diese kleinen Bauversuche in Ruhe und klatsche begeistert Beifall.'),
  ('c5294433-a84c-4be9-ad57-5744718366c9', 'Hat dich heute alles genervt? 📝', 'Wenn dein Kind schläft, schreib deine Gefühle in dein Stimmungstagebuch. Morgen ist ein neuer und schönerer Tag.'),
  ('51bb1e4c-965f-4d69-b6e7-c79da0dce45c', 'Ein Ort für Mama ☕', 'Vom vielen Zuhausebleiben bist du ganz schön erschöpft. Wähle unter den mama-freundlichen Orten ein gemütliches Café mit Kindermenü aus und nimm dir etwas Zeit für dich.'),
  ('814176f3-c727-409b-b14a-fa62636170f1', 'Interesse an Büchern 📖', 'Integriere gedruckte Bücher in eure Abendroutine. Dein Baby versucht bereits, die Seiten selbst umzublättern. Passe deinen Tonfall dem Erzähltempo der Geschichte an.'),
  ('f73c2769-0def-42bc-93e0-9a021c41b271', 'Ein Körper, der zur Musik tanzt 🎶', 'Sobald dein Baby im Fernsehen einen rhythmischen Klang hört, wackelt es mit dem Po. Sein Gespür für Musik erwacht – mach mit und genießt diesen wundervollen Moment gemeinsam.'),
  ('4c628627-3074-421f-9cfc-318df363eaf0', 'Hast du vergessen, mit welcher Brust du gestillt hast? 🤱', 'Der Anacan-Timer merkt sich für dich die rechte/linke Brust. Starte jetzt das Stillen mit dem Timer!'),
  ('99abcc3d-bec9-4537-89f9-92bfe6f4056c', 'Das Ende eines wundervollen Tages. ✨', 'Du bist eine unglaubliche Mama und leistest seit 1 Jahr wahre Heldinnenarbeit! Schreib in dein Stimmungstagebuch, dass du stolz auf dich bist, und schlafe ganz entspannt.'),
  ('d58a373d-b464-4fff-9b8e-74a104499618', 'Nur noch 5 Tage bis zum 1. Geburtstag! 🎈', 'Der Countdown ist fast vorbei! Der erste Geburtstag! Dekoration, kleine Gäste ... Tritt der Anacan-Community bei und hol dir von anderen Mamas kreative Ideen für die Geburtstagsparty zum 1. Geburtstag.'),
  ('0eb89ca2-1605-4f92-8c61-0198a966afb1', 'Freudentanz 💖', 'Feiert heute Abend gemeinsam bei Kerzenschein die Anstrengungen und den Stolz des vergangenen Jahres. Ihr seid ein perfektes Team!'),
  ('2e46d431-01ee-479e-a146-2b349cd7f234', 'EIN JAHR! DER ERSTE GEBURTSTAG! 🎂🎉', 'IHR SEID GROSSARTIG! Ganze 365 Tage, schlaflose Nächte, das erste Lachen, die ersten Schritte! Dein Baby ist jetzt 1 Jahr alt! Plant ein Baby-Fotoshooting und haltet diesen historischen Tag in wunderschönen Bildern für immer fest!'),
  ('3c2fa886-d095-424c-ad68-b439a1ffc0b9', 'Applaus für dich selbst 👏', 'Dein Baby ist 9 Monate in deinem Bauch und 1 Jahr in deinen Armen gewachsen! Heute ist nicht nur sein Geburtstag, sondern auch dein Geburtstag als Mutter. Sei stolz auf dich!'),
  ('0944c4dc-3e95-4efb-97dc-8b4809d96d45', 'Die Kleinkindphase beginnt 🌟', 'Die Babyzeit liegt hinter euch! Dein Kind entwickelt jetzt ganz offiziell seine eigene Persönlichkeit und möchte alles selbst machen. Ein neues Abenteuer voller Geduld und Liebe beginnt!'),
  ('569602c0-f0cf-4229-b498-984bfdabf097', 'Smarte Märchenstunde 🪄', 'Führt eure Routine mit smarten Märchen fort und erfindet eine Geschichte über den großen kleinen Helden, der jetzt 1 Jahr alt ist und die Welt entdeckt.'),
  ('ae6d1371-ca56-433f-b6db-9c70c59094fb', 'Neue Trotzanfälle 🛑', 'Beginnen neue Wutanfälle, bei denen sich dein Kind zum Beispiel auf den Boden wirft? Es kann seine Gefühle noch nicht selbst regulieren. Geh auf Augenhöhe, sprich ruhig mit ihm und begleite es liebevoll durch den Wutanfall.'),
  ('5a7c1a91-4811-4c74-93f4-2ee19bdbb39a', 'Erinnert euch an eure ersten gemeinsamen Tage und lacht zusammen.', 'Ihr habt dieses erste Jahr nicht mühelos gemeistert! Es ist euer gemeinsamer Erfolg als Team.'),
  ('5c11361a-fa0a-4cbc-ab7e-82f7bcc5e4bf', 'Nur noch 2 Tage bis zum großen Tag! 🗣', '️ Das schönste Geschenk ist, wenn dein Baby dich Mama oder Papa nennt. Lies die Tipps in den Blogbeiträgen, um die Sprachentwicklung und die ersten Wörter zu fördern.'),
  ('e7879bf6-3dca-4f0b-9981-d7f119d39235', 'Licht dimmen 🌙', 'Schalte 1 Stunde vor dem Schlafengehen alle hellen Lichter und Bildschirme zu Hause aus. Melatonin wird nur in einer ruhigen, schwach beleuchteten Umgebung ausgeschüttet.'),
  ('14e209af-2489-4eb6-a1f0-be21be617768', 'Mit einem Märchen in den Schlaf 🪄', 'Schaffe bei den smarten Märchen eine besondere Klangkulisse, die nur aus Musik und Naturgeräuschen besteht. Keine Worte – nur Ruhe und Vorfreude.'),
  ('a6e2ed87-38de-413e-9884-cda9afcbb191', 'Letzte Vorbereitungen 📸', 'Sind Kerzen, Torte und Kleidung bereit? Schaffe freien Speicherplatz auf deinem Handy – morgen brauchst du viel Platz für das Baby-Fotoshooting!'),
  ('c639a352-3f59-4488-9ce0-2ba361a4790c', 'Morgen wird dein Baby 1 Jahr alt! 🎉', 'Zeit für Nostalgie! Erinnerst du dich an den ersten Tag, als ihr die Geburtsklinik verlassen habt? Öffne dein Stimmungstagebuch und schreibe deinem Baby heute Abend einen emotionalen Brief, den es später einmal lesen kann.'),
  ('6e25898e-24d8-4ca6-8cbe-71a271993d6f', 'Geräusche im Griff 🤫', 'Die erste halbe Stunde nach dem Einschlafen ist die empfindlichste Phase. Prüfe die Umgebung mit dem Schallpegelmesser und vermeide plötzlichen Lärm.'),
  ('d5e35c42-03ad-4068-b27d-3efca55a35ad', 'Der Kampf um den Löffel 🥄', 'Dein Baby möchte den Löffel selbst halten und den Brei allein essen. Dabei wird etwas danebengehen und es wird schmutzig – aber für die motorische Entwicklung ist das sehr wichtig. Lass es ruhig ausprobieren.'),
  ('f93e7290-30ca-44fe-a1e4-55044619c9a6', 'Energiebedarf 🍲', 'Der Alltag wird immer turbulenter. Wähle aus den gesunden Rezepten ein eisen- und proteinreiches Mittagessen, das dir neue Energie gibt.'),
  ('10a3d57b-5997-4410-8ceb-fa0dd3d4cee2', 'Papas Nachtschicht 👨‍🍼', 'Bewältige das nächtliche Aufwachen nicht ganz allein. Wecke auch deinen Partner – ein Team zu sein bedeutet, die Verantwortung gerecht zu teilen.'),
  ('50b26349-9946-4708-aec2-e87f1b15952f', 'Die ersten freien Schritte? 🧗‍♂️', 'Vielleicht heute, vielleicht morgen ... Dein Baby versucht bereits, ein oder zwei Schritte zu machen, ohne sich festzuhalten. Sei bereit, diesen Meilenstein im Entwicklungstracker festzuhalten!'),
  ('9407d96f-ca5a-4378-a7c6-ee00256c457a', 'Wettercheck ⛅', 'Verlass dich vor dem Spaziergang nicht nur auf den Blick aus dem Fenster. Mit dem Wetter- und Kleidungshelfer erfährst du sofort die Windgeschwindigkeit und welches Outfit am besten passt.'),
  ('3ed836ab-41d4-4203-a7c8-b9e7b1394cd2', 'Du brauchst jemanden zum Reden 💬', 'Machen dir andere Angst, die sagen, nach dem ersten Geburtstag werde alles schwieriger? Schreib in der Anacan Community und lies echte, positive Erfahrungen anderer Mütter.'),
  ('4c27d203-23f5-4e87-918e-d40df5e30875', 'Eine ruhige Nacht 🛀', 'Ein warmes Bad, eine Massage und ein abgedunkeltes Zimmer: Eine feste Schlafroutine ist das wichtigste Geheimnis für ruhige Nächte ohne Unterbrechungen.'),
  ('6ad316f8-edd9-4dff-aac4-f3492d4a602a', 'Es befolgt einfache Aufforderungen 🧸', 'Findet und bringt dein Baby den Ball tatsächlich, wenn du sagst: „Gib mir den Ball“? Sein Sprachverständnis ist gerade besonders ausgeprägt! Beziehe es noch mehr in Spiele ein.'),
  ('028a5b0d-04de-43dc-984d-eaf6e3427904', 'Die ersten Schuhe auswählen 👟', 'Dein Baby macht sich bereit zum Laufen – aber sollte es zu Hause Schuhe tragen? Frag Anacan AI nach den richtigen Schuhen für die ersten Schritte und den Vorteilen des Barfußlaufens.'),
  ('5d68d6d5-05d2-43b4-bd93-e3f95983e445', 'Eine Liste rettet den Tag 🛒', 'Nach dem ersten Geburtstag ändert sich der Speiseplan. Braucht ihr Kuhmilch oder andere Lebensmittel? Ergänze sofort die Einkaufsliste und schick sie an deinen Partner oder deine Partnerin.'),
  ('9a073421-3e36-4699-bbbd-50a69e46f431', 'Nimm dir Zeit für dich. 🛁', 'Es ist nicht leicht, den ganzen Tag hinter einem laufenden Kind herzurennen. Trag deine Erschöpfung ins Stimmungstagebuch ein, lass den Ballast los und gönn dir eine Pause.'),
  ('2cdeb7df-f4f5-4a75-ae9b-552210a168fe', 'Blättert in Büchern 📖', 'Kann dein Baby die Seiten von Pappbilderbüchern schon ganz allein umblättern und reagiert es auf die Bilder? Lies ihm viele farbenfrohe Märchenbücher vor.'),
  ('8b98f6cf-24e2-4a41-9bea-c77f1a82d1bd', 'Die ersten freien Schritte! 🧗‍♂', '️ Dein Baby lässt die Möbel los, steht allein und macht vielleicht sogar den lang ersehnten ersten Schritt! Verpasse diesen unvergesslichen historischen Moment nicht und lade ihn gleich als Video ins Babyalbum hoch.'),
  ('beccb06c-7cf4-4f1a-9455-17d5b952ad96', 'Musikalische Abende 🎶', 'Das einfachste Mittel gegen abendliche Quengelei: Mach sein Lieblingslied an, nimm dein Baby in den Arm und tanzt gemeinsam.'),
  ('0c97760a-2746-4ddf-ad12-5f44e1960612', 'Bedürfnis nach Ruhe 🤫', 'Sorge mit dem Schallpegelmesser für Ruhe im Zimmer. Unterbrochener Nachtschlaf trübt am Morgen sowohl seine als auch deine Stimmung.'),
  ('61d67656-ab73-4417-b42d-5e55ecf64b87', 'Die Kraft des Wortes Nein 🛑', 'Dein Baby hat gelernt, bei einem Angebot den Kopf zu schütteln und Nein zu sagen! Das ist kein Trotz, sondern eine Möglichkeit, seine Meinung auszudrücken. Beruhige es, indem du ihm Wahlmöglichkeiten gibst.'),
  ('b58ae5cb-ec5b-400f-b490-16ff65c6cead', 'Logikspiele 🧩', 'Wirft dein Baby Spielzeug in eine Kiste und leert sie danach wieder vollständig aus? So entwickelt es sein Verständnis für „drinnen“ und „draußen“. Unterbrich diese Beschäftigung nicht.'),
  ('6b997061-a83d-4040-b848-d55a40a87a1a', 'Gesunde Mama 🥑', 'Wenn dein Baby satt ist, bist du an der Reihe. Such dir einen energiereichen Snack aus unseren gesunden Rezepten aus und leg dich wenigstens 10 Minuten aufs Sofa.'),
  ('8d89c421-922f-4b8a-bc83-525a380ead88', 'Faszination Treppen 🧗‍♂️', 'Reicht es deinem Baby nicht mehr, unten herumzulaufen, und versucht es, Treppen und Möbel zu erklimmen? Da macht die Motorik einen kräftigen Entwicklungsschub! Behalte dein Baby dabei unbedingt im Auge.'),
  ('dacf6637-c6dd-4427-9e89-1dc06f453ae5', 'Magische Märchenstunde 🪄', 'Bring mit der Geschichte „Die Einschlafgeheimnisse des kleinsten Helden“ aus den klugen Märchen Abwechslung in eure Abendroutine.'),
  ('2d2e06b1-2d94-4883-a675-93637a17ca98', 'Quengelei auf dem Höhepunkt ☁️', 'Dein Baby ist mit nichts zufrieden und weint wegen allem? Vielleicht brechen gerade die hinteren Backenzähne durch. Halte gekühlte Beißringe bereit.'),
  ('2eeb1f61-7042-48aa-9ecc-41443c68b4a8', 'Papas Nachtschicht 👨‍🍼', 'Wechselt euch beim nächtlichen Aufwachen ab: Einmal stehst du auf, einmal dein Partner. Manchmal hilft dem Baby nur Papas rhythmisches Streicheln.'),
  ('d1cf73d9-421b-4ad1-b114-e5025146d5b2', 'Wer macht den Haushalt? 🌪️', 'Die Hausarbeit bleibt liegen? Dann lass sie liegen. Bitte deinen Partner, heute den Haushalt zu übernehmen. Du ruhst dich aus.'),
  ('18cb3df2-de24-43c0-a3d0-160051dc5202', 'Gefühlstagebuch 📝', 'Wenn du dich allein fühlst, schreibe deine Gefühle in dein Stimmungstagebuch. Alle Frauen erleben solche Phasen – du bist stark.'),
  ('19c626ef-26a5-49ef-921f-4577f35ab653', 'Schnuller oder Fläschchen abgewöhnen? 🍼', 'Du möchtest deinem Baby nach dem 1. Geburtstag den Schnuller abgewöhnen? Frage die Mütter in der Anacan-Community nach besonders sanften Methoden.'),
  ('c6a284e9-0bba-433f-9823-bcc74708dbd9', 'Frische Luft ist die beste Medizin 🌳', 'Dein Baby hat den ganzen Tag geweint und war unruhig? Die Lösung ist oft ganz einfach: Prüfe das Wetter, zieh dein Baby passend an, setz es in den Kinderwagen und geh direkt in den Park.'),
  ('5f3d97d0-e211-488f-bb05-dd9ccce213a3', 'Wir sind ein Team! 💖', 'Setzt euch nach einem anstrengenden Tag zusammen und sprecht offen darüber, was euch beschäftigt. Wenn ihr euch gegenseitig unterstützt, wird die Last leichter.'),
  ('92cb503c-c013-47cb-ab12-416c047b2693', 'Entwicklungscheck 🤖', 'Du brauchst Informationen zu den motorischen Fähigkeiten eines 12 Monate alten Kindes? Bitte Anacan AI um eine kurze, präzise und kinderärztlich geprüfte Liste.'),
  ('f20aef27-fde2-489c-9dd8-fe28386cf1db', 'Formen und Denkspiele! 🧩', 'Dein Baby versucht, den Kreis oder das Quadrat in die passende Öffnung zu stecken. Halte diese lehrreichen Entdeckungsmomente im Babyalbum fest.'),
  ('078c86a9-a3c8-4f20-a27a-3aa00d3961ad', 'Spaß beim Essen! 🥦', 'Wenn dein Baby wenig Appetit hat, bereite im Bereich „Rezepte“ für Babys, die mit Beikost beginnen, farbenfrohe und ansprechende Portionen zu.'),
  ('3b7df91a-7022-4a50-9438-82f89b2240b8', 'Es erkennt Körperteile 👀', 'Zeigt dein Baby mit dem Finger auf sein Auge, wenn du fragst: „Wo ist dein Auge?“ Seine geistige Auffassungsgabe ist jetzt auf dem Höhepunkt! Halte diesen Meilenstein voller Stolz im Entwicklungstracker fest.'),
  ('f55bcf4b-2f37-47d2-8e08-b8c72b1b9a56', 'Du gibst dein Bestes! 💖', 'Ein Kind großzuziehen ist wie ein Marathon. Nimm dir heute Abend etwas Zeit für dich, sieh dir einen Film an, den du magst, oder ruh dich einfach aus.'),
  ('18eaf932-80c3-47ae-a394-f6ce083ef215', '„Ich will selbst essen!“ 🥦', 'Dein Baby möchte dir den Löffel aus der Hand nehmen. Lass es ruhig. Dabei wird zwar etwas danebengehen, aber dieses Gefühl von Selbstständigkeit ist für dein Baby sehr wichtig.'),
  ('b55b3812-173b-489f-a2ae-d2c78611fd35', 'Freundschaft mit der Dunkelheit 🌙', 'Damit dein Baby schneller einschläft, kannst du die Dunkelheit in eure Abendroutine einbauen. Schalte alle zusätzlichen Lichtquellen im Zimmer aus.'),
  ('c9fb44a1-ad82-4f16-a316-50d99863130e', 'Verdacht auf eine Allergie 🤖', 'Hast du nach dem ersten Geburtstag neue Lebensmittel eingeführt? Wenn du dir Sorgen machst, erfährst du bei Anacan AI sofort, welche ersten Schritte du unternehmen solltest.'),
  ('0c105765-0e1a-42dd-bd14-0ca4153705c0', 'Die Feinmotorik entwickelt sich. 🖍', '️ Vielleicht macht es deinem Baby Spaß, mit einem Stift auf Papier zu kritzeln. Gib ihm geeignete dicke Buntstifte und beobachte seine Kreativität.'),
  ('1b77ed52-4cf2-48a6-98fc-53d0a94dc968', 'Eine Schlafroutine gibt Geborgenheit. 🌙', 'Eine gleichbleibende Abfolge jeden Abend (Baden, eine Geschichte, gedämpftes Licht) hilft deinem Baby, leichter einzuschlafen.'),
  ('795996e4-e3e1-4fa7-b442-27c8ffa35bff', 'Zahnungsschmerzen 🦷', 'Ist das Zahnfleisch wieder gerötet und läuft ständig Speichel? Halte den Verlauf im Zahnungs-Tracker fest und lege gekühlte Beißringe bereit.'),
  ('452e9fa3-8dba-4774-8bfe-d6afa50d161c', 'Eine Liste ist Gold wert 🛒', 'Ist das Obst oder der Haferbrei für die Mahlzeit ausgegangen? Ergänze sofort die Einkaufsliste und sende die benötigten Dinge an das Handy deines Partners.'),
  ('8c12c251-a9b5-45cb-92ff-f145e2484025', 'Es läuft an der Wand entlang 🧗‍♀️', 'Sich an Möbelkanten festzuhalten und seitwärts zu laufen, ist seine Lieblingsübung. Bis zu den ersten freien Schritten dauert es nicht mehr lange! Sieh im Entwicklungs-Tracker nach.'),
  ('c7e52a2b-46d5-4446-b455-907f7523256e', 'Geräuschpegel im Blick behalten 🤫', 'Die erste halbe Stunde nach dem Einschlafen ist die empfindlichste Zeit. Prüfe die Umgebung mit dem Schallpegelmesser und vermeide plötzlichen Lärm.'),
  ('0955065c-ecf1-48ed-9f6f-735958386a41', 'Vitamine für Mama 🥑', 'Du tust alles, damit dein Baby satt wird. Aber was ist mit dir? Wähle im Bereich „Gesunde Rezepte“ ein leichtes, eisen- und kalziumreiches Mittagessen aus.'),
  ('1d781ae8-7800-48ae-b0ee-fe44c7f13291', 'Verändert sich der Tagschlaf? 🥱', 'Wehrt sich dein Baby völlig gegen einen seiner beiden Tagschläfchen? Nach dem ersten Geburtstag beginnt der Übergang zu nur einem Tagschlaf. Passt eure Routine nach und nach an.'),
  ('61536a43-b97b-4fe8-8f6a-f358141baefc', 'Mit einem Märchen einschlafen 🪄', 'Erstelle in den smarten Märchen Geschichten über mutige, liebenswerte Tiere und verwandle das Zimmer in einen magischen Ort.'),
  ('76e3844a-efe7-4daa-855a-4cfd4d92bfc9', 'Licht dimmen 🌙', 'Schalte 1 Stunde vor dem Schlafengehen alle hellen Lichter und Bildschirme im Haus aus. Melatonin wird nur in einer ruhigen, schwach beleuchteten Umgebung ausgeschüttet.'),
  ('8b586560-e2d2-46b0-ba82-419bb7b56682', 'Gedächtnisnebel 🛒', 'Die Vergesslichkeit lässt dich nicht los? Denk nicht lange über kleine Einkäufe für den Haushalt nach: Setze sie sofort auf die Einkaufsliste und lass deinen Partner sie erledigen.'),
  ('b87394f8-5f2b-4eb7-a491-26b80560c8a3', 'Gezielte Würfe ⚾', 'Dein Baby versucht bewusst, das Spielzeug in seiner Hand auf ein bestimmtes Ziel zu werfen. Die Hand-Augen-Koordination entwickelt sich rasant. Werft euch gemeinsam einen Ball zu.'),
  ('159279c3-df89-49cf-a71c-bb577a8dd0c3', 'Gefahrenzonen in Reichweite ⚡', 'Dein Baby ist wieder ein Stück gewachsen und erreicht jetzt Regale, an die es vorher nicht herankam. Überprüfe deshalb dringend noch einmal, ob euer Zuhause kindersicher ist.'),
  ('3b6ac273-a759-45de-9492-87af2df8cac9', 'Die Stille der Nacht 🤫', 'Wenn Autolärm oder andere Geräusche von draußen dein Baby stören, überprüfe die Umgebung unbedingt mit dem Schallpegelmesser und lass im Hintergrund weißes Rauschen laufen.'),
  ('bc24cbab-3bcd-4b5b-92fb-249b861079c2', 'Alles, womit dein Baby spielt, verteilt es im ganzen Raum.  🌪️', 'Nicht das Aufräumen ist wichtig, sondern dass du dich ausruhst. Die Spielsachen sind morgen auch noch da – aber dein Baby braucht jetzt eine ausgeruhte Mama.'),
  ('0693172d-9675-431e-ae2b-b1d735f8da0f', 'Lass die ganze Müdigkeit hinter dir.', 'Vergiss nicht, heute Abend, wenn euer Kind schläft, gemeinsam mit deinem Partner euren Erfolg als Team zu feiern!'),
  ('3e6bfa0e-5f58-4921-bf7a-6f47b0eb1125', 'Vergleiche dich nicht 🛑', 'Vergiss Sätze wie: „Das Kind von anderen hat früher gesprochen.“ Jedes Kind entwickelt sich in seinem eigenen Tempo. Schenke deinem Kind einfach Liebe.'),
  ('b9520b22-b9b3-4ca3-a219-de05702404a8', 'Auf dem Weg zu eineinhalb Jahren! 📸', 'Dein Baby ist jetzt schon 12.5 Monate alt! Starte ein Baby-Fotoshooting und halte die lustigsten Momente dieser turbulenten, bewegungsreichen Kindheitsphase in Bildern fest.'),
  ('9dd82a43-7f3a-4a5e-9d01-a99d7d738015', 'Selbstständiges Anziehen. 👕', 'Versucht dein Kind schon, seine Socken selbst aus- oder anzuziehen? Unterstütze diese feinmotorischen Fähigkeiten geduldig.'),
  ('ccf44d60-2dc0-447f-b1ea-dd06a80f0324', 'Wassertrinken ist sehr wichtig. 💧', 'Aktive Kinder bekommen schnell Durst. Denk daran, deinem Kind über den Tag verteilt und besonders nach dem Abendessen Wasser anzubieten.'),
  ('d4a01ba0-4f2b-45a3-8cb0-3f2fa493585d', 'Zeit für ein neues Spielzeug? 🛒', 'Wenn du nach altersgerechtem Lernspielzeug suchst, das die geistige Entwicklung deines Kindes fördert, wirf einen Blick auf unsere Liste mit empfohlenen Produkten.'),
  ('10934358-ef97-4dab-87ad-73a62aee1231', 'Aufräumen oder ausruhen? 🛋️', 'Wenn dein Kind schläft, lauf nicht gleich zum Geschirrspüler. Leg dich aufs Sofa, schließe die Augen und atme einfach 15 Minuten lang durch.'),
  ('58866969-75c5-44cd-a308-210945d7a2af', 'Versuch und Irrtum 🧱', 'Dein Kind versucht, zwei Spielzeugklötze aufeinanderzustapeln, doch sie fallen um. Aufmerksam probiert es immer wieder. Beobachte seine ersten Bauversuche ganz in Ruhe.'),
  ('94a9a306-04fb-42bb-9962-95b473b02f89', 'Gefühlstagebuch 📝', 'Wenn du dich allein fühlst, schreib deine Gefühle in dein Stimmungstagebuch. Alle Frauen machen solche Phasen durch – du bist stark.'),
  ('56403a92-c6d5-492f-b073-20bcd436f218', 'Papas Nachtschicht 👨‍🍼', 'Bewältige das nächtliche Aufwachen nicht ganz allein. Wecke auch deinen Partner – als Team teilt ihr euch die Verantwortung.'),
  ('763e2885-6f82-4d6b-8ec4-680155ad7a5f', 'Austausch unter Mamas 💬', 'Du weißt bei Wutanfällen nicht weiter? Schau gleich in der Anacan-Community vorbei, lies die unterstützenden Kommentare anderer Mamas und atme erst einmal durch.'),
  ('f47e2fcf-5030-43a8-a77b-79834cb3f95a', 'Große Gefühle, kleiner Körper 🛑', 'Wirft sich dein Kind auf den Boden, wenn es nicht bekommt, was es möchte? Geh auf Augenhöhe und sprich ruhig mit ihm, um es durch den Gefühlsausbruch zu begleiten.'),
  ('a0e7f0f6-1438-4f75-acb4-559e4df47974', 'Bedürfnis nach Ruhe 🤫', 'Bewahre mit dem Schallpegelmesser die Ruhe im Zimmer. Unterbrochener Nachtschlaf wirkt sich am Morgen sowohl auf die Stimmung deines Kindes als auch auf deine eigene aus.'),
  ('dfa800b1-6c2e-4bc9-b061-4b6d1df9eb95', 'Zeit und Raum für Mama ☕', 'Das viele Zuhausebleiben hat deine Energiereserven aufgebraucht. Wähle unter den mama-freundlichen Orten ein gemütliches Café aus und nimm dir etwas Zeit für dich.'),
  ('f34137b7-333a-47bb-8fab-66dd8be52bfb', 'Tanz und Rhythmus 🎶', 'Fängt dein Kind sofort an zu tanzen, sobald es im Fernsehen oder auf dem Handy einen Rhythmus hört? Sein Gespür für Musik ist jetzt voll erwacht – mach mit und tanzt gemeinsam!'),
  ('8a5f3751-2bcd-4454-bfef-74c90f1c3f85', 'Tagesausklang – Zeit für dich. 🛁', 'Warst du heute sehr müde? Nimm eine warme Dusche, entspann dich und sei stolz auf alles, was du geschafft hast.'),
  ('dcaa4b27-ca42-45e3-98f1-f11ad70e3dc8', 'Wir lernen die Körperteile kennen! 👃', 'Zeigt dein Baby mit seinem kleinen Finger auf die Nase, wenn du fragst: „Wo ist deine Nase?“ Macht daraus ein lustiges Spiel vor dem Spiegel und genießt gemeinsam diese süßen Entdeckungen.'),
  ('e70adad3-3a0b-4d15-ab3c-9f286916a872', 'Zeit für einen gesunden Snack. 🍎', 'Für Kinder voller Energie sind Obststücke oder Gemüsesticks eine tolle Wahl. Gib deinem Kind die Möglichkeit, sie selbst zu halten und zu essen.'),
  ('6b0a9309-594c-4f0a-a15f-6c0611c0d5c3', 'Kleine Künstler am Werk! 🖍', '️ Gib deinem Kind dicke Wachsmalstifte und lass es frei auf einem Blatt Papier kritzeln. Das fördert die Feinmotorik und Kreativität.'),
  ('ccb3a3d0-8dc5-450a-b184-37cf81a39c01', 'Frische Luft tut euch beiden gut. 🌳', 'Entdecke auf unserer Karte mit still- und familienfreundlichen Orten einen neuen Park, in dem du bequem mit dem Kinderwagen spazieren gehen kannst.'),
  ('dd0a1e57-cbbc-4cc0-9c63-a03032174ab5', 'Eine Schlafroutine gibt Geborgenheit. 🌙', 'Wenn ihr jeden Abend die gleichen Schritte in derselben Reihenfolge wiederholt (baden, eine Geschichte vorlesen, das Licht dimmen), hilft das deinem Kind, schneller einzuschlafen.'),
  ('04429520-36d1-489e-8ec7-309a2c08ae92', 'Wir sind ein Team! 💖', 'Setzt euch nach einem anstrengenden Tag zusammen und sprecht offen darüber, was euch beschäftigt. Wenn ihr euch gegenseitig unterstützt, wird die Last leichter.'),
  ('05fff0e7-029c-401c-bfab-497bbc099997', 'Dein Baby versteht die Bedeutung von Wörtern 🗣️', 'Wenn du sagst: „Hol den Ball“, macht es sich tatsächlich auf die Suche danach. Sein Wortschatz wächst schnell. Sprich jetzt in komplexeren Sätzen mit ihm.'),
  ('ec4b2f26-3631-4fed-9578-c9539a35a5c0', 'Deine Einkaufsliste für unterwegs 🛒', 'Ist im Alltagschaos das Shampoo oder sind die Windeln ausgegangen? Versuch nicht, dir alles zu merken: Schreib es auf die Einkaufsliste und synchronisiere sie mit deinem Partner.'),
  ('663824a2-b8fe-471a-b981-3eb69f3a2c7f', 'Große Gefühle, kleiner Körper. 🌪', '️ Es ist ganz normal, dass dein Kind wütend wird und weint, wenn es sich nicht ausdrücken kann. Geh auf Augenhöhe und sag ihm mit ruhiger Stimme, dass du seine Gefühle verstehst.'),
  ('8be96289-58a8-4a48-89ec-c4ba0488e973', 'Spielen mit Wasser beruhigt. 💧', 'Fülle eine kleine Schüssel mit Wasser und gib ein paar Plastikgefäße hinein. Das Spielen mit Wasser hilft Kindern, überschüssige Energie abzubauen und sich zu entspannen.'),
  ('a70fb0ff-98b0-4735-ac10-846168dd5d60', 'Hast du eine Frage? 🤖', 'Stell unserem Anacan AI-Assistenten auch nachts wichtige Fragen wie „Wie gehe ich mit der 1-Jahres-Krise um?“ und erhalte fachkundigen Rat.'),
  ('8a51b6b4-96e5-40da-8e4b-a3f74c147eb5', 'Gute-Nacht-Geschichten sind zauberhaft. 📖', 'Eine kurze Geschichte vor dem Schlafengehen regt die Fantasie an und stärkt zugleich eure emotionale Bindung.'),
  ('b28c4699-a204-48ae-80c2-bef5008fdffd', 'Selbstständig spielen lernen. 🧩', 'Wenn dein Kind auch nur für kurze Zeit allein spielen kann, zeigt das, dass sich seine Aufmerksamkeit weiterentwickelt. Beobachte es in diesen Momenten liebevoll aus der Ferne.'),
  ('e6b48652-88e0-49d8-b2cc-654a9f8eb626', 'Wir verfolgen das Wachstum. 📏', 'Wird die Kleidung deines Kindes langsam zu klein? Trage die neuen Werte im Gewichts-Tracker ein und dokumentiere seine gesunde Entwicklung.'),
  ('05e8d5ea-453b-4a35-a697-81e0b9ca911a', 'Erwachsene nachahmen 🧹', 'Du putzt das Haus und dein Kind nimmt ebenfalls ein Tuch in die Hand und versucht, es dir nachzumachen? Es ist wie ein Spiegel und ahmt alles nach, was du tust.'),
  ('13c2fa37-beb3-4b36-a1a9-4ba3fd32e6a0', 'Park oder zu Hause? ⛅', 'Du möchtest nach draußen, aber es ist windig? Der Wetter- und Kleidungsassistent empfiehlt dir sofort das passende Outfit.'),
  ('ecb2b9d1-a640-4303-b570-f3c7f463e0ab', 'Schwierige Abende 🥱', 'Wehrt sich dein Kind mit aller Kraft gegen das Einschlafen? Überprüfe noch einmal seine Tagesschläfchen und die Schlafroutine.'),
  ('2a991705-4255-4931-9ad5-cef8eb9bf0dd', 'Dein kleiner Helfer! 🧹', 'Nimmt dein Baby ein Tuch und versucht, Staub zu wischen, indem es dich nachahmt? Halte diese süßen und lehrreichen Momente unbedingt als Video im Babyalbum fest.'),
  ('813ebcca-fa4c-42de-926c-6ca1c1526de6', 'Mit Musik zur Ruhe kommen. 🎶', 'Hört euch abends statt lebhafter Spiele lieber beruhigende Musik an. So bereitest du dein Baby auf den Schlaf und dich selbst auf eine entspannte Auszeit vor.'),
  ('ce071e13-068a-4c5a-8d4c-437e6f25658d', 'Wählerisches Essverhalten. 🍲', 'Mach dir keine Sorgen, wenn dein Baby bestimmte Lebensmittel ablehnt. Biete sie an verschiedenen Tagen und in unterschiedlichen Formen erneut an – zum Beispiel als Fingerfood statt als Püree.'),
  ('502b8118-151f-47c7-9476-eb53fa55cfd0', 'Türme wachsen in die Höhe! 🧱', 'Dein Baby kann bereits 3-4 Bauklötze aufeinanderstapeln. Lobe und unterstütze es bei diesem Spiel, das Konzentration und Hand-Augen-Koordination erfordert.'),
  ('af470a51-532a-4658-877a-26e61845210a', 'Zeit für soziale Kontakte. 👶', 'Beobachtet dein Baby im Park aufmerksam die anderen Kinder? Auch wenn sie noch nicht miteinander spielen, ist das Spielen nebeneinander (Parallelspiel) ein erster großer Schritt in der sozialen Entwicklung.'),
  ('ceb1c77d-c486-4755-b204-47ec200fcd34', 'Dein Baby versteht deinen Tonfall 🗣️', 'Hält dein Baby inne und sieht dich an, wenn du mit ernster Stimme Nein sagst? Es beginnt bereits, Emotionen und Verbote zu verstehen!'),
  ('12139491-dd07-42f8-b056-98645d9880be', 'Ein Bild, das die Zeit anhält 📸', 'Dein Baby wächst jeden Tag ein bisschen mehr. Öffne gleich das Baby-Fotoshooting und halte diesen innigen Moment für immer fest.'),
  ('302d3885-ce15-4277-a0cf-d95f95d7ed63', 'Licht dimmen 🌙', 'Schalte 1 Stunde vor dem Schlafengehen alle hellen Lichter und Bildschirme aus. Melatonin wird nur in einer ruhigen Umgebung ausgeschüttet.'),
  ('78f8f713-17f3-46f4-83f8-9cdbfd0c9894', 'Zeit zum selbstständigen Spielen 🧸', 'Dein Baby kann sich jetzt schon 10-15 Minuten allein mit seinen Spielsachen beschäftigen. Behalte es aus der Nähe im Blick und genieße die Ruhe.'),
  ('a72fe5b0-0907-43fb-b4ef-fc4dd880fecd', 'Wetter-Check ⛅', 'Draußen ist das Wetter nicht ganz eindeutig? Das Wetter- und Kleidungstool zeigt dir sofort die Windgeschwindigkeit und das passende Outfit an.'),
  ('bac8ff9b-6338-4b34-a5d6-84b7aefd251c', 'Papas Nachtschicht 👨‍🍼', 'Bewältige das nächtliche Aufwachen nicht ganz allein. Wecke auch deinen Partner – ein Team zu sein bedeutet, die Verantwortung gleichmäßig zu teilen.'),
  ('c1daed2c-e22f-4c5a-8534-4ff90b6b866e', 'Ich finde mein Spielzeug selbst 🧸', 'Findet dein Baby ein Spielzeug wieder, das du aus seinem Blickfeld genommen und versteckt hast? Es versteht jetzt, dass Gegenstände weiter existieren, auch wenn es sie nicht sieht!'),
  ('53cb1b60-78f0-41c1-a42e-b48a4324533b', '400 Tage voller Aufregung! 🌟', 'Morgen ist der große, vierhundertste Tag! Mehr als 1 Jahr und 1 Monat! Sorgt zu Hause für ein wenig Feststimmung und schafft freien Speicherplatz auf eurem Handy.'),
  ('9e145532-f5a6-48ed-a07c-a3e9fc574858', 'Zeit für eine Massage 💆‍♂️', 'Wenn euer Kind eingeschlafen ist, könnt ihr euch gegenseitig mit einer Schultermassage verwöhnen und den Stress des Tages hinter euch lassen. Ihr seid ein Team!'),
  ('fab52013-4ea8-458f-b397-01341fb91dad', 'Ein Abend der Selbstvergebung 📝', 'Hat dich heute einfach alles genervt? Wenn dein Kind schläft, schreib deine Gefühle in dein Stimmungstagebuch. Morgen beginnt ein neuer und schönerer Tag.'),
  ('165064a6-acf5-4848-b342-4a3782635921', 'Fantastische 400 Tage! 🎉', 'Herzlichen Glückwunsch! Seit genau 400 Tagen geht ihr gemeinsam durch diese turbulente Zeit! Feiert diesen besonderen Tag gebührend!'),
  ('894151c3-97b8-419f-9602-aa08da619716', 'Weiter selbstständig essen. 🥄', 'Auch wenn dabei alles schmutzig wird, lass dein Kind versuchen, mit seinem eigenen Löffel zu essen. Das stärkt sein Selbstvertrauen und fördert seine Muskelkoordination.'),
  ('8c8e0b49-c38c-485a-b336-5facb1258a02', 'Du bist die Beste! ✨', 'Dein unermüdlicher Einsatz in diesen 400 Tagen ist unbezahlbar. Atme jetzt tief durch, lehn dich zurück und gönn dir etwas Ruhe.'),
  ('9089b5ba-67c3-48ba-a5c3-8e428c87d9ec', 'Papa macht sich zum Spaßvogel 🤡', 'Am besten bringt Papa das Baby mit lustigen Geräuschen zum Lachen. Genießt heute Abend gemeinsam diese fröhlichen Momente.'),
  ('3170ad10-66c6-4ca0-bf72-80b0daf91373', 'Eine Abendroutine stimmt auf den Schlaf ein. 🌙', 'Kleine Rituale, die jeden Tag zur gleichen Zeit stattfinden (Zähne putzen, eine Geschichte vorlesen), erleichtern deinem Kind das Einschlafen erheblich.'),
  ('64832db8-28ac-41fb-8d33-21a72b48fa8c', 'Kleiner Entdecker auf Erkundungstour! 🔍', 'Jede Ecke und jeder Schrank zu Hause ist für dein Kind eine neue Welt. Schaffe eine sichere Umgebung und lass es die Wohnung frei erkunden.'),
  ('f283f219-7efa-4926-a360-3fb653057b9b', 'Frische Luft und jede Menge Energie! 🌳', 'Wenn Kinder sich draußen richtig austoben, fällt ihnen der Mittagsschlaf leichter. Macht euch gemeinsam auf den Weg in den Park.'),
  ('35a5e175-d9f9-4d9a-9445-a523d64bc595', 'Dein Kind möchte selbst essen. 🥦', 'Auch wenn es dabei kleckert, lass dein Kind den Löffel selbst halten. Das fördert seine Selbstständigkeit und seine Hand-Auge-Koordination.'),
  ('66beeaaa-0b78-4114-b41f-8d7e6f407c55', 'Du hast dir eine Pause verdient. 🛁', 'Du warst den ganzen Tag auf den Beinen. Wenn dein Kind eingeschlafen ist, gieße dir eine Tasse heißen Tee ein und genieße einfach die Ruhe.'),
  ('979d3d6f-0938-49ad-b47d-0cedcf8c1cf6', 'Flotte Schritte! 🏃‍♂', '️ Dein Kind läuft bereits selbstständig von einem Zimmer ins andere und versucht sogar zu rennen. Hinterherzukommen ist für Mamas ein echtes Workout!'),
  ('1008f62b-ef11-490d-886c-a80a06e64454', 'Wo sind deine Augen? 👀', 'Das Spiel, bei dem dein Kind die Körperteile benennt, gehört noch immer zu seinen Lieblingsspielen. Vor dem Spiegel macht es gleich noch mehr Spaß.'),
  ('2ca5e024-95be-449a-af7e-ee34228f8bca', 'Planung schafft Entspannung. 📝', 'Gehe im Kopf mit kleinen Notizen durch, was du morgen erledigen möchtest oder was du kochen willst. So kannst du beruhigt ins Bett gehen.'),
  ('efb1280f-e8f0-4ecf-bb77-385f667aff5d', 'Auf der Suche nach Entspannung. ☕', 'Manchmal möchtest du einfach raus und Zeit in einer anderen Umgebung verbringen. Finde unter den mama-freundlichen Orten ein Café in deiner Nähe, das du bequem mit deinem Kind besuchen kannst, und genieße deinen Kaffee.'),
  ('aa01a859-3ad0-4c64-9ef3-4423ccf76d24', 'Sagt dein Kind gern Nein? 🛑', 'Dein Kind ahmt deine Einwände nach und sagt deshalb möglicherweise zu allem Nein. In dieser Phase ist es wichtig, geduldig zu bleiben und ihm kleine Alternativen anzubieten.'),
  ('b8b7257f-64c5-46a3-b958-ded901da8e8d', 'Mach das Wassertrinken zum Vergnügen. 💧', 'Biete deinem Kind regelmäßig Wasser in einer bunten Trinkflasche an, damit es nach dem aktiven Spielen ausreichend mit Flüssigkeit versorgt ist.'),
  ('d2e6d5c6-90cf-4a42-ae18-383c2c592a7c', 'Papas Vorlesestunde. 👨‍🍼', 'Überlass heute Papa das Vorlesen der Gutenachtgeschichte und das Zubettbringen und gönn dir eine kleine Auszeit.'),
  ('4484d3ee-8677-4454-8e65-371ba851a267', 'Die Kraft des weißen Rauschens. 🎶', 'Wenn dein Kind nach einem aktiven Tag nicht einschlafen kann, spiele Meeresrauschen oder Regengeräusche aus den Weißen Geräuschen ab und schaffe so eine beruhigende Atmosphäre im Zimmer.'),
  ('b03cef74-ad4c-4ee6-86e3-5d55fe15d1fd', 'Liebevolle Kuschelmomente! 🤗', 'Wenn dein Kind dich plötzlich umarmt oder zu küssen versucht, ist das seine Art, dir seine Liebe zu zeigen. Genieße diese einzigartigen Momente voller Liebe!'),
  ('fb1bbc34-c7a1-41dc-b4eb-e7444cbade21', 'Beziehe dein Kind ins Gespräch ein. 🗣', '️ Benenne die Gegenstände im Zimmer und warte darauf, dass dein Kind die Wörter wiederholt. Durch solche kleinen Spiele wächst sein Wortschatz.'),
  ('05dbf09b-2a49-4886-a4e4-6f85e7cbea42', 'Raus aus den vier Wänden ⛅', 'Dein Kind kann zu Hause seine Energie nicht loswerden und quengelt? Die Natur ist das beste Beruhigungsmittel. Prüfe Wetter und Kleidung, wähle die passende Kombination und macht euch gleich auf den Weg in den Park.'),
  ('3cf4affc-53f5-4c77-84f1-006d5732e36a', 'Spielzeit mit Papa 👨‍👧', 'Nachdem du ihm den ganzen Tag hinterhergelaufen bist, tun dir die Beine weh. Jetzt ist der Partner-Modus dran. Lass Papa das Herumtollen auf dem Boden und die Pferdchenspiele übernehmen. Du ruhst dich aus.'),
  ('f1269e86-21d6-4d2f-83e1-31926957408a', 'Marathon von Zimmer zu Zimmer 🏃‍♂️', 'Gehen reicht ihm nicht mehr – jetzt wird von Zimmer zu Zimmer gerannt! Sein Gleichgewicht im Stehen entwickelt sich immer weiter. Halte diesen großen Meilenstein der Grobmotorik im Entwicklungstracker fest.'),
  ('7df527b0-7bf7-42d6-b9f4-0f231186e70c', 'Kleiner Menü-Diktator 🥣', 'Heute schiebt es das Essen weg, das es gestern noch geliebt hat? Wählerisches Essverhalten ist nach dem 1. Geburtstag normal. Keine Panik: Suche bei den gesunden Rezepten nach abwechslungsreichen Alternativen.'),
  ('85bb394b-b9a2-4a30-a34a-98479663ff2d', 'Die „Was ist das?“-Phase ☝️', 'Dein Kind zeigt mit dem Finger auf alles und macht dabei einen bestimmten Laut. Es möchte, dass du ihm die Welt benennst. Sage ihm geduldig, wie jeder Gegenstand heißt, auf den es zeigt.'),
  ('f78a5d11-ba9f-41e9-8557-2840d12964be', 'Lass die Schuldgefühle los 📝', 'Heute habe ich ihm zu wenig vorgelesen, es hatte zu viel Bildschirmzeit ... Bring diese Stimmen zum Schweigen! Du gibst dein Bestes. Schreibe in dein Stimmungstagebuch eine liebevolle Notiz an dich selbst.'),
  ('1167974e-3206-4f0f-b4e8-4d14f35444b6', 'Übergang zu einem Tagesschlaf 🥱', 'Dein Kind möchte morgens nicht schlafen und der ganze Zeitplan gerät durcheinander? Es wird größer! Vielleicht befindet es sich gerade in der Übergangsphase von zwei Tagesschläfchen zu einem. Passe die Routine nach und nach an.'),
  ('8017b10d-4bdb-4fe5-8a0b-20ae132c6ec2', 'Magisches Zimmer 🪄', 'Erstelle in den smarten Märchen eine persönliche Geschichte über einen mutigen Helden, der die Welt entdeckt. Erleichtere deinem Kind mit diesem süßen Märchen den Übergang in die Nacht.'),
  ('c7ad498c-1a79-4b6f-a5e5-0ac0b264682c', 'Entdecke einen Ort für Mamas ☕', 'Du bist es leid, zu Hause immer auf dieselben Wände zu schauen. Entdecke unter den mama-freundlichen Orten ein Café mit Kinderspielecke. Dein Baby kann spielen, während du deinen Kaffee genießt.'),
  ('5b41e7e4-7a14-41e6-a7a1-c4a7838db66b', 'Lest gemeinsam ein Buch. 📖', 'Dein Baby möchte die Seiten jetzt schon selbst umblättern. Pappbilderbücher und Hörgeschichten sind für diese Phase ideal.'),
  ('d29d33a4-aed4-4635-9f37-3a7a39a378b0', 'Dein Baby testet Grenzen. 🛑', 'Obwohl du Nein gesagt hast, schaut dein Baby dir in die Augen und greift trotzdem wieder nach dem Gegenstand? Das ist kein Trotz, sondern ein Versuch, Grenzen kennenzulernen. Bleib geduldig und konsequent.'),
  ('f3355fe9-0c3b-41e2-9043-0a5cb8a61740', 'Nächtliches Aufwachen. 😴', 'Zahnen oder ein Wachstumsschub können den Schlaf stören. Nutze bei Bedarf den Schlaf-Timer, um Veränderungen im Schlafrhythmus festzuhalten.'),
  ('2e0b0129-5a3d-466c-a35f-ef4707dea065', 'Trost von Papa 🫂', 'Wechselt euch beim nächtlichen Aufwachen unbedingt ab. Manchmal beruhigen Papas rhythmische Streicheleinheiten und sein vertrauter Geruch das Baby im Dunkeln sofort.'),
  ('812159bf-a0a9-4bf9-8e7b-97d82abbaa80', 'Dein kleiner Nachahmer 🧹', 'Während du zu Hause sauber machst, nimmt dein Baby ebenfalls ein Tuch und versucht, es dir gleichzutun. Es ist dein kleines Ebenbild! Gib ihm einen ungefährlichen Gegenstand und beziehe es in die Hausarbeit ein.'),
  ('9510e83b-c10c-4166-b921-d1cd3c8f203c', 'Vergesslichkeit austricksen 🛒', 'Hat dich dein Gedächtnis schon wieder im Stich gelassen? Trage alles, was zu Hause zur Neige geht, sofort in die Einkaufsliste ein, damit dein Partner es auf dem Heimweg von der Arbeit besorgen kann.'),
  ('0a5f0553-0fcd-480d-a18f-a3ecfcfe950c', 'Logikspiele 🧩', 'Wirft dein Baby Spielzeug in eine Kiste und leert sie anschließend wieder vollständig aus? So lernt es die Konzepte „drinnen“ und „draußen“ kennen. Beobachte diese wiederholten Versuche einfach in Ruhe.'),
  ('302bafdb-c5ca-4389-a56e-16a2ddd6812b', 'Die Kraft der Abendroutine 🛀', 'Ein warmes Bad hilft immer. Halte unbedingt an der Abendroutine fest, denn sie signalisiert dem Gehirn deines Babys ganz klar, dass jetzt Schlafenszeit ist.'),
  ('309b39de-d5f5-4702-93e1-596dca9c9021', 'Tanke neue Energie 🥑', 'Wenn dein Baby satt ist, bist du an der Reihe. Iss dein Mittagessen trotz des hektischen Alltags nicht im Stehen. Wähle einen energiereichen Snack aus unseren gesunden Rezepten und mach es dir auf dem Sofa gemütlich.'),
  ('66b4bd9b-8226-4190-94c7-9d50f8db6c34', 'Zeit für einen Austausch 💬', 'Lässt dich der Gedanke „Warum macht mein Kind das?“ nicht los? Tritt der Anacan Community bei, lies ähnliche Geschichten anderer Mütter und finde Trost.'),
  ('80e6be85-6917-46a0-b283-acc653cca6c1', 'Kleine Leseratte 📖', 'Blättert dein Baby in Pappbilderbüchern und reagiert auf die Bilder? Sein visuelles Gedächtnis entwickelt sich. Lies ihm viele farbenfrohe Bilder- und Märchenbücher vor.'),
  ('df1f7c26-41ff-4081-9b25-dae8d38c75e8', 'Mit euch ist jeder Moment schön. ✨', 'Jeder Tag ist ein neues Abenteuer. Wenn dein Baby schläft, schau dir seine kleinen Hände an und lächle über seine kleinen Erfolge des Tages.'),
  ('52e92eba-b885-4c30-891d-aa6e5379acf9', 'Ich will allein essen! 🥄', 'Dein Baby nimmt dir den Löffel aus der Hand und möchte selbst essen. Dabei wird einiges danebengehen und es wird sich bekleckern, doch für seine motorische Entwicklung ist das wichtig. Lass es selbstständig ausprobieren.'),
  ('a26c1e0d-7872-4f7e-9268-2fba22c9203a', 'Hast du eine Frage? 🤖', 'Wenn du Fragen zum Verhalten oder zur Entwicklung deines 13–14 Monate alten Kindes hast, kannst du dir sofort Rat von unserem Anacan AI-Assistenten holen.'),
  ('eb8ab523-6225-489f-8a09-0f37ba40956a', 'Energie abbauen! 🏃‍♂', '️ Spiele vor dem Mittagsschlaf bewegungsreiche Spiele mit deinem Baby, die es ein wenig müde machen – etwa Fangen oder Ballspielen. So kann es leichter einschlafen.'),
  ('5d99a4ad-d33f-448d-9f7c-32943cbfa648', 'Sind die Backenzähne im Anmarsch? 🦷', 'Ist das Zahnfleisch geschwollen und kaut dein Baby auf allem herum? Vielleicht brechen gerade die hinteren Zähne durch. Lege kühlende Beißringe in den Kühlschrank.'),
  ('70d7d4ed-5c06-44bc-99e5-3871d07a9510', 'Licht dimmen 🌙', 'Schalte 1 Stunde vor dem Schlafengehen grelles Licht und alle Bildschirme aus. Melatonin wird nur in einer ruhigen, abgedunkelten Umgebung ausgeschüttet.'),
  ('aa9c9479-f8d5-4149-b7c4-99976958a17c', 'Gefahrenzonen in Reichweite ⚡', 'Dein Baby ist größer geworden und erreicht nun Regale, an die es vorher nicht herankam. TV-Möbel, Ecken ... Überprüfe die Sicherheit deines Zuhauses jetzt unbedingt noch einmal.'),
  ('0872925d-e2d7-471e-ba13-22ee468f0a1f', 'Plötzliches Aufwachen 😭', 'Wacht dein Baby mitten in der Nacht schreiend auf und lässt sich nicht beruhigen? Lass die Weinanalyse den Schrei auswerten, um die mögliche Ursache herauszufinden.'),
  ('1fe0720b-91d5-4dc9-ad61-71e5ff522246', 'Wachstumstempo 📏', 'Auch an der Kleidung merkst du, wie schnell dein Baby wächst. Trage Gewicht und Größe im Tracker ein, um seine gesunde Entwicklung im Blick zu behalten.'),
  ('ca5a420a-5b8f-49ce-b884-6a219b8b71aa', 'Große Gefühle, kleiner Körper 🛑', 'Wirft sich dein Kind auf den Boden, wenn es nicht bekommt, was es möchte? Das sind die typischen Wutanfälle der Kleinkindphase. Bleib ruhig, stelle Blickkontakt her und vermittle ihm: Ich bin bei dir.'),
  ('005096a2-1549-4208-a331-7e39e1da9587', 'Schnelle Hilfe vom Kinderarzt 🤖', 'Du brauchst Informationen zu Entwicklungsschüben mit 13.5 Monaten? Mach es dir leicht und bitte Anacan AI um eine genaue, kinderärztlich geprüfte Übersicht.'),
  ('7de487db-11d1-4c22-8b8d-e58adb31344a', 'Befolgt einfache Aufforderungen 🧸', 'Du sagst „Bring deine Schuhe“, und dein Kind holt sie tatsächlich? Wortschatz und Sprachverständnis entwickeln sich gerade rasant! Beziehe es noch häufiger in Spiele ein.'),
  ('47368a03-c0f0-4e5c-a343-b4577d2ffa64', 'Nächtliche Ruhe 🛀', 'Ein lauwarmes Bad, eine Massage und ein abgedunkeltes Zimmer: Eine feste Schlafroutine ist das wichtigste Geheimnis ruhiger Nächte.'),
  ('8edf71cc-a90b-4465-947f-070adc35b5f7', 'Tanzen zur Musik 🎶', 'Sobald dein Baby im Fernsehen einen Rhythmus hört, wackelt es mit dem Po. Sein Gefühl für Musik entwickelt sich – mach mit und tanzt gemeinsam!')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_de = v.t, body_de = v.b
FROM (VALUES
  ('8f7c6b2d-87b3-4688-9ad1-78064dda6eb8'::uuid, 'Mütter unter sich 💬', 'Fühlst du dich nicht gut genug? Schau gleich in der Anacan-Community vorbei, lies die unterstützenden Kommentare anderer Mütter und lass dich aufmuntern.'),
  ('4a0eb59e-113c-42ab-af5f-e0f64f837b44', 'Entdecke neue Orte. ☕', 'Bist du vom Alltagstrott gelangweilt? Finde in unserer App ein kinderwagenfreundliches Café und gönn dir eine Kaffeepause.'),
  ('4c4da832-707f-472e-a209-374acff11d94', 'Hilfe im Haushalt! 🧹', 'Möchte dein Baby unbedingt mit einem Tuch Staub wischen oder mit dem Besen spielen? Dass es dich nachahmt, ist ein wunderbares Zeichen seiner Entwicklung.'),
  ('ca45e311-dc2b-43fe-aa24-08a197d26f0a', 'Hast du Fragen zur kindlichen Entwicklung? 🤖', 'Wenn dich etwas zur Entwicklungsphase mit 13-14 Monaten beschäftigt, kannst du unserem Anacan AI-Assistenten auch nachts schreiben.'),
  ('0ffbde04-3193-4b21-aa17-136db5de3c72', 'Gefühlstagebuch 📝', 'Wenn du dich allein fühlst, schreib deine Gefühle in dein Stimmungstagebuch. Alle Frauen erleben solche Phasen – du bist stark.'),
  ('7cdfa7f4-2c92-497d-9290-43caf53d8a56', 'Zeit für Ruhe 🤫', 'Sorge mit dem Schallpegelmesser für Ruhe im Zimmer. Nächtliche Schlafunterbrechungen beeinträchtigen am Morgen sowohl die Stimmung deines Babys als auch deine eigene.'),
  ('4716a93b-966d-4c69-b174-c2a48e9a09fa', 'Abendliches Bad. 🛁', 'Ein lauwarmes Bad macht nicht nur Spaß und wäscht den Schmutz des Tages ab, sondern entspannt dein Kind auch und bereitet es wunderbar auf den Schlaf vor.'),
  ('dbbcb16c-cf48-47f7-92ab-992ed2fab247', 'Es kennt seine Körperteile. 👃', 'Spielt das Spiel „Wo ist deine Nase?“ oder „Wo ist dein Ohr?“. Wenn dein Kind richtig zeigt, klatsche und ermutige es.'),
  ('0cc0cda4-4fef-4e92-9af2-cd065cfee008', 'Du bist die Beste! 💖', 'Ein Kind großzuziehen ist wie ein Marathon. Nimm dir heute Abend etwas Zeit für dich, schau dir einen Lieblingsfilm an oder entspanne dich einfach in aller Ruhe.'),
  ('781ac9f7-7fd3-4466-9d70-0b41dd1e954a', 'Es zieht seine Spielsachen hinter sich her! 🧸', 'Nachziehspielzeug oder kleine Wagen, die dein Kind schieben kann, gehören jetzt zu seinen liebsten Beschäftigungen. Das ist eine tolle Übung für das Gleichgewicht!'),
  ('7dec83e1-5089-42b4-a2b5-f3d997eb1138', 'Tu auch dir selbst etwas Gutes. 🥗', 'Mit einem energiegeladenen Kind Schritt zu halten, ist nicht leicht. Bereite dir mit einem unserer gesunden Rezepte für Frauen eine leckere, vitaminreiche Mahlzeit zu, die dir neue Energie schenkt.'),
  ('6942d3e7-d39d-4aee-b8a0-ef2313920693', 'Die „Ich allein!“-Phase. 🧦', 'Wenn dein Kind versucht, seine Socken selbst anzuziehen oder allein zu essen, halte es nicht davon ab. Sein Gefühl für Selbstständigkeit entwickelt sich genau durch solche kleinen Versuche.'),
  ('c0c8236b-5e7c-45b1-a5c1-d45f005b603c', 'Gefühle loslassen. 📝', 'Manchmal kann einfach alles zu viel werden. Schreib im Stimmungstagebuch auf, was dich beschäftigt und wie erschöpft du bist, um den Stress des Tages loszulassen.'),
  ('e1f2089f-f46e-44ca-b5b5-5564bd6ee8fb', 'Entdeckungen an der frischen Luft. 🌳', 'Im Park Blätter zu berühren und Steine zu sammeln, fördert die Sinneswahrnehmung deines Kindes. Wählt für euren nächsten Spaziergang einen neuen Park aus.'),
  ('f39f5c34-c612-4758-a438-ed52b2d49ba8', 'Wir sagen Tschüss 👋', 'Wenn jemand zur Tür hinausgeht, winkt dein Baby von sich aus zum Abschied! Das ist ein schöner sozialer Reflex. Ermutige es immer wieder dazu.'),
  ('0dcb1657-4eeb-47c5-a193-84ed106d43bc', 'Trau dich zu fragen 🤖', 'Denkst du, dass du bei der Schlafroutine etwas falsch machst? Frag Anacan AI sofort nach allem, wobei du unsicher bist, und entspann dich.'),
  ('10d800e4-c6bd-4325-b22e-385edaca8f7f', 'Wacht dein Baby nachts weiterhin auf? 😴', 'Wenn dein Baby in den letzten Tagen wieder schlechter schläft, analysiere den Schlafrhythmus mit dem Anacan-Schlaftimer und finde mögliche Lücken in der Routine.'),
  ('319cae50-0492-468a-98e4-1b38563ab7ea', 'Bald 14 Monate! Noch 10 Tage! 🎂', 'Unglaublich! In genau 10 Tagen wird dein kleiner Schatz 14 Monate alt. Mit jedem Tag entwickelt er sich zu einer immer selbstständigeren Persönlichkeit.'),
  ('2064ec2b-0483-4d3b-9453-106b6b9f32f8', 'Die ersten Erfahrungen mit Buntstiften. 🖍', '️ Gib deinem Baby geeignete dicke Buntstifte und beobachte liebevoll, wie es auf dem Papier kritzelt. Vielleicht wächst hier ein zukünftiger Künstler heran!'),
  ('7f86b541-f24f-46cc-bf72-a538c8e62fa0', 'Allein mit den eigenen Spielsachen spielen. 🧩', 'Auch wenn es nur für kurze Zeit ist: Wenn dein Baby allein spielen kann, ist das ein großer Schritt in Richtung Selbstständigkeit. Beobachte es aus der Ferne.'),
  ('f945146d-2bbb-40d9-95f6-29bdc7f3be6d', 'Das Wachstum geht weiter. 📏', 'Die Kleidung deines Kindes wird zu klein! Trage im Bereich „Entwicklungstracker“ die neuen Größen- und Gewichtswerte ein und verfolge seine Entwicklung.'),
  ('241a81f3-8158-4d3c-a8b2-640a1b060696', 'Mit wählerischem Essverhalten umgehen. 🍲', 'An manchen Tagen lehnt dein Baby sogar sein Lieblingsessen ab. Zwinge es nicht, sondern biete einfach verschiedene Alternativen an.'),
  ('f1854aec-f168-4789-a191-8a1fa96c3cd8', 'Die Sicherheitsmaßnahmen müssen angepasst werden. 🛡', '️ Je mobiler dein Baby wird und je häufiger es Schränke öffnet, desto mehr Gefahren entstehen. Schau dir unsere Liste empfohlener Produkte mit Kindersicherungen an.'),
  ('02d67440-3e37-4d1c-99f8-cbfa7aadda52', 'Zeit für einen gesunden Snack. 🍎', 'Obststücke oder Gemüsesticks sind eine tolle Wahl für Kinder voller Energie. Lass dein Kind sie selbst halten und essen.'),
  ('4a197291-3001-4afb-9a70-d4320bd260b2', 'Die „Was ist das?“-Phase. ☝', '️ Dein Kind zeigt mit dem Finger auf alles und fragt, wie es heißt. Benenne geduldig die Dinge – so wächst sein Wortschatz schnell.'),
  ('8938f1b0-220a-48ac-b5f5-33db3613995c', 'Papas Vorlesestunde. 👨‍🍼', 'Überlass heute Papa das Vorlesen der Gute-Nacht-Geschichte und das Zubettbringen und gönn dir eine kleine Pause.'),
  ('47ea2f2a-adf0-473a-a6a2-47218a354bbd', 'Klettert wie ein Äffchen! 🧗‍♂', '️ Dein Kind versucht, allein auf das Sofa oder niedrige Möbel zu klettern. Sorge für eine sichere Umgebung und lass es diese mutigen motorischen Schritte unter Aufsicht ausprobieren.'),
  ('4c8a3a5d-e5df-48ed-823d-41dd50a6bc1d', 'Küsschen durch die Luft! 👋', 'Winkt dein Kind Menschen, die gehen, schon ganz bewusst hinterher und wirft ihnen Küsschen zu? Genieße diese süße und soziale Geste.'),
  ('ea4bc86f-6869-478f-98a6-52bb8dc4c40f', 'Das Einschlafen wird leichter. 🌙', 'Ein gleichbleibender Ablauf am Abend (Bad, Geschichte, gedämpftes Licht) hilft deinem Kind, leichter einzuschlafen.'),
  ('3d197dae-8e31-468d-8d92-41ba68985a62', 'GENAU 14 MONATE! 🎉', 'Herzlichen Glückwunsch! Seit der Geburt sind genau 14 Monate vergangen! Erstelle jetzt beim Baby-Fotoshooting ein Bild mit einem besonderen Design und teile diese Freude in der Anacan-Community!'),
  ('96b02483-42a2-4868-a751-d817b0144951', 'Vergiss nicht, Wasser zu trinken. 💧', 'Das gilt für dein Kind und für dich! Trinkt nach ausgelassenem Spielen und zwischen den Mahlzeiten unbedingt Wasser, damit ihr ausreichend mit Flüssigkeit versorgt bleibt.'),
  ('d89100dc-a7f8-49dd-8358-e3c63248fa5d', 'Kleine Hilfe im Einsatz! 🧹', 'Nimmt dein Kind ein Tuch und wischt Staub oder spielt mit dem Besen, um dich nachzuahmen? Kinder lernen vor allem durch Beobachten.'),
  ('eea0806e-a72b-42f1-b1c3-b7a791619a96', 'Verändert sich der Schlafrhythmus? 😴', 'Wenn dein Kind tagsüber allmählich nur noch einmal schläft, kann sich der Nachtschlaf während der Umstellung verlängern. Verfolge mit dem Schlaf-Timer den Schlafrhythmus der letzten Tage.'),
  ('15bfc39a-e833-4e38-b7fc-bc13ef473b00', 'Zeit zum selbstständigen Spielen 🧸', 'Dein Kind kann sich jetzt schon 10-15 Minuten allein mit seinen Spielsachen beschäftigen. Das zeigt, dass seine Aufmerksamkeitsspanne länger wird. Genieße die Ruhe.'),
  ('99045f34-6450-4abd-856c-64fd61405e7b', 'Dein Kind versteht deinen Tonfall 🗣️', 'Hält es inne und schaut dich an, wenn du mit ernster Stimme Nein sagst? Es beginnt bereits, Gefühle und Verbote zu verstehen!'),
  ('dc953aca-0624-4e7e-a96b-11f2b35b9a14', 'Die Kraft der Musik 🎶', 'Versuche, scheinbar grundlose Unruhe am späten Nachmittag mit sanfter klassischer Musik zu beruhigen. Oft wirkt dieser einfache Trick Wunder.'),
  ('1eee6b26-c3fa-460c-8e48-030eb1e5a77c', 'Farbenfrohe Kritzeleien! 🖍', '️ Richte deinem Kind in einer Zimmerecke dicke Malstifte und ein großes Blatt Papier her. Vergiss nicht, seine ersten Kunstwerke im Babyalbum festzuhalten!'),
  ('3ed02c3f-6c13-412d-9e4b-93ad1bd1da69', 'Brauchst du fachkundige Unterstützung? 🤖', 'Stelle unserem Anacan AI-Assistenten auch nachts Fragen wie: „Wie kann ich die Sprachentwicklung meines 14 Monate alten Kindes fördern?“'),
  ('9052004a-46e9-4652-8de2-61f2a8f774d7', 'Müdigkeit und Stolz💖', 'Feiere heute Abend gemeinsam mit deinem Partner die Anstrengungen und Erfolge der vergangenen 14 Monate. Ihr seid ein perfektes Team!'),
  ('dde3a118-6b4b-4b86-b077-744218b7fcd7', 'Wie weit dein Kind schon gekommen ist! 📈', 'Die Ängste der ersten Tage sind einem starken Vertrauen in dich als Mutter gewichen. Sei stolz auf dich!'),
  ('33a2089a-67cc-4441-bb79-483ad77a1a42', 'Nimm dir Zeit für dich. 🛁', 'Du warst den ganzen Tag auf den Beinen. Halte deine Erschöpfung im Stimmungstagebuch fest, um sie loszulassen, und entspanne dich bei einer Tasse warmem Tee.'),
  ('625bdfef-2359-4843-aaac-6c8411b1963b', 'Die Kunst, Dinge fallen zu lassen. 🎾', 'Wenn dein Kind Spielzeug oder Essen auf den Boden wirft und hinterherschaut, ist das kein Unfug – es entdeckt die Schwerkraft. Hab Geduld und lass es mit unzerbrechlichen Gegenständen spielen.'),
  ('ee0ba9ab-4b88-462e-aae9-f9a207218204', 'Rückwärts und seitwärts gehen! 🦀', 'Dein Kind probiert jetzt nicht nur Schritte nach vorn aus, sondern auch rückwärts und seitwärts. Das ist eine großartige Übung für Gleichgewicht und Motorik!'),
  ('21478892-353c-43fd-ba31-59c9aeb8255d', 'Ein Energiebooster für Mamas! 🥗', 'Aktive Kinder verlangen ihren Mamas doppelt so viel Energie ab! Belohne dich, indem du aus den gesunden Rezepten ein leckeres Gericht auswählst und zubereitest.'),
  ('530feb7f-e42b-4ca3-88fe-a9c205c1ef1e', 'Hallo, wer ist da? 📱', 'Hält dein Kind die Fernbedienung oder das Telefon ans Ohr und versucht, wie du zu sprechen? Lass dir diese süßen Momente des Nachahmens nicht entgehen.'),
  ('ab819835-a2e1-481b-91b5-5391eb6051e8', 'Behalte den Schlafbedarf im Blick. ⏱️', 'Hat sich der Tagschlaf bereits auf ein einziges Schläfchen reduziert? Starte den Schlaf-Timer, wenn dein Baby einschläft, und überprüfe in der Übersicht, wie es sich an den neuen Rhythmus gewöhnt.'),
  ('f5a87b81-5f64-4d75-abaf-6fd718e53fc5', 'Gesunde Snacks. 🍎', 'Obststücke oder Joghurt sind tolle Snacks für dieses Alter. Entdecke in unserer App abwechslungsreiche und leckere Rezeptideen für Kinder.'),
  ('0b365564-8d23-4572-9881-7a4b9e2159bf', 'Die ersten Kunstwerke! 🖍', '️ Dein Baby liebt es, mit dicken Stiften auf Papier zu kritzeln. Bewahre seine ersten Kunstwerke im Bereich „Baby-Fotoshooting“ als Erinnerung für später auf.'),
  ('c0638659-03fe-4ca5-b078-76057498811f', 'Immer ganz nah bei Mama 🥰', 'Selbst wenn du zur Toilette gehst, wartet dein Baby weinend hinter der Tür auf dich. Die Trennungsangst ist gerade besonders stark. Gib ihm immer wieder Sicherheit.'),
  ('f2ba1614-ef41-4060-97ee-0fe66e58b884', 'Regelmäßiges Wassertrinken ist wichtig. 💧', 'Je aktiver dein Baby ist, desto mehr Durst bekommt es. Vergiss nicht, ihm beim Spielen und nach den Mahlzeiten Wasser anzubieten.'),
  ('1bf6a974-24ed-47b3-8587-a38235ea120e', 'Entdeckungstour in der Küche! 🍳', 'Töpfe, Löffel und Plastikbehälter gehören jetzt zu den Lieblingsspielzeugen deines Babys. Lass sichere Schränke zum Entdecken offen.'),
  ('88b4c840-5c20-4f9f-8b89-4530da60297b', 'Jetzt den Kinderschutz anpassen! 🛡', '️ Sobald dein Baby frei herumläuft und Schränke öffnet, nehmen die Gefahren zu. Sieh dir unbedingt unsere Liste mit empfohlenen Produkten für Kindersicherungen und Eckenschutz an.'),
  ('9e41eb2a-f9ac-4f4c-8455-0ad7cfd405e3', 'Ein beruhigendes Bad. 🛁', 'Ein warmes Bad macht Spaß und hilft dabei, die Energie des Tages abzubauen. Gleichzeitig entspannt es die Muskeln und bereitet dein Baby optimal auf den Schlaf vor.'),
  ('409e6b49-8ccb-4975-92b1-c12021092540', 'Die Magie der Gutenachtgeschichte. 📖', 'Eine kurze Geschichte vor dem Schlafengehen regt die Fantasie an und stärkt zugleich eure emotionale Bindung.'),
  ('44b33bc4-3602-4265-9fe5-30b5609015de', 'Gemeinsame Betreuung mit Papa. 👨‍🍼', 'Abends geht es beim Spielen oft besonders lebhaft zu. Lass dein Kind heute Abend mit Papa herumtoben und überlass ihm auch das Zubettbringen, während du dich ausruhst.'),
  ('b2803eb7-9fa9-49b3-a014-d7a2eabb5c95', 'Das Mitgefühl erwacht! 💖', 'Kommt dein Kind zu jemandem, der weint oder traurig ist, und versucht, ihn zu trösten oder zu streicheln? Seine emotionale Intelligenz entwickelt sich wunderbar.'),
  ('e569bdf3-a845-44dc-852b-5318a0cf6a72', 'Grenzenlose Energie an der frischen Luft! 🌳', 'Entdecke unter den mama-freundlichen Orten sichere, neue Parks, die ihr bequem erreichen könnt und in denen sich dein laufbegeistertes Kind austoben kann.'),
  ('381afc75-3dbd-4716-b5ea-3af987c642dc', 'Widerstand gegen den Mittagsschlaf. 😴', 'Spielen ist viel spannender als Schlafen! Beendet aktive Spiele eine halbe Stunde vor dem Zubettgehen und geht zu ruhigeren Beschäftigungen über.'),
  ('3ed2bd45-e711-4e56-bdc9-29b31e605069', 'Hast du eine Frage? 🤖', 'Wichtige Fragen wie „Warum isst mein Kind an manchen Tagen überhaupt nichts?“ kannst du sogar nachts unserem Anacan AI-Assistenten stellen und dir Unterstützung holen.'),
  ('718ac202-3ddd-463e-90fd-d1367161e2b5', 'Wählerisches Essverhalten meistern. 🍲', 'An manchen Tagen lehnt dein Kind vielleicht sogar sein Lieblingsessen ab. Zwinge es nicht, sondern probiere einfach die verschiedenen alternativen Rezepte in unserer App aus.'),
  ('9693a098-adc4-4d19-ab73-4c5cc195a25e', 'Ich wische selbst! 🧽', 'Möchte dein Kind auch ein Tuch haben, wenn du den Tisch abwischst? Gib deinem kleinen Helfer eine ungefährliche Aufgabe. Das stärkt sein Selbstvertrauen enorm.'),
  ('98ba1e51-63c6-4c73-891d-99f1b14f3495', 'Die Kraft von weißem Rauschen. 🎶', 'Wenn dein Kind nach einem ereignisreichen Tag oder wegen des Zahnens nicht schlafen kann, spiele bei den Weißen Geräuschen Regengeräusche ab und schaffe eine beruhigende Atmosphäre im Zimmer.'),
  ('2cca6125-c540-4b9b-9a06-6121b60507e5', 'Abenteuer an der frischen Luft! 🌳', 'Kann dein Kind seine Energie drinnen nicht loswerden? Wähle einen sicheren Park, in dem ihr bequem mit dem Kinderwagen spazieren gehen könnt, und genießt gemeinsam die frische Luft.'),
  ('73b001a8-93ab-4798-bca3-094a519e468a', 'Lass deinen Gefühlen freien Lauf. 📝', 'Nicht jeder Tag ist einfach, und manchmal kann alles zu viel werden. Schreib deine Gefühle in dein Stimmungstagebuch und lass so den Stress des Tages hinter dir.'),
  ('d452b163-e134-4c64-90b8-7e561b20c6f9', 'Wir ahmen Wörter nach! 🗣', '️ Versucht dein Kind, deine Wörter oder Tierlaute nachzuahmen? Reagiere begeistert auf diese Versuche, damit seine Freude daran wächst, sich auszudrücken.'),
  ('80913e3b-4640-4efe-ae49-ce789db16fd1', 'Der perfekte Tagesausklang. ✨', 'Auch heute hast du dein Bestes als Mama gegeben. Schließe die Augen, sei stolz auf dich und gleite entspannt in den Schlaf.'),
  ('8e332da4-937a-4f7f-af67-edbe9e325d0e', 'Die Schritte werden sicherer! 🏃‍♂', '️ Dein Kind läuft jetzt schon selbstständig durch die Wohnung und versucht manchmal sogar zu rennen. Diese mutigen Bewegungen machen dich stolz und halten dich zugleich ständig auf Trab!'),
  ('b5982bde-910f-4d42-bc5f-8e5e9b2e683f', 'Verdacht auf eine Allergie 🤖', 'Du hast ein neues Lebensmittel angeboten und Rötungen auf den Wangen bemerkt? Bevor du in Panik gerätst, erfährst du bei Anacan AI, was als Erstes zu tun ist.'),
  ('0deab7a8-9a3b-4827-969f-f24303c70419', 'Beschwerden beim Zahnen 🦷', 'Ist das Zahnfleisch wieder gerötet und der Speichelfluss hört nicht auf? Halte gekühlte Beißringe bereit.'),
  ('46166e0f-606a-46ff-86d4-07304bc93180', 'Regelmäßiges Wassertrinken ist wichtig. 💧', 'Je aktiver dein Kind ist, desto mehr Durst hat es. Vergiss nicht, ihm beim Spielen und nach den Mahlzeiten Wasser anzubieten.'),
  ('6b7d6637-7328-44aa-b6c8-47c73df3a6f3', 'Das Wachstum schreitet schnell voran. 📏', 'Die Kleidung deines Kindes wird schon wieder zu klein! Trage im Entwicklungs-Tracker die neuen Größen- und Gewichtswerte ein und halte seine gesunde Entwicklung fest.'),
  ('807127b9-417f-43a0-9bca-9ef33fbdadb8', 'Antworten mit Körpersprache 🗣️', 'Wenn du „Gehen wir?“ fragst, hebt dein Kind die Arme, und bei „Nein“ schüttelt es den Kopf. Sein Sprachverständnis hat sich unglaublich weiterentwickelt!'),
  ('356f85b5-b941-4e2e-8218-18498e652ff8', 'Eine Burg aus Bauklötzen 🧱', 'Dein Kind versucht, zwei oder drei Bauklötze aufeinanderzustapeln. Beobachte ganz in Ruhe seine kleinen ersten Konstruktionsversuche.'),
  ('b22af5a1-54b4-4af4-afbf-f4de46dc6ba3', 'Die Kraft des weißen Rauschens. 🎶', 'Wenn dein Kind nach einem aktiven Tag oder wegen des Zahnens nicht einschlafen kann, spiele unter „Weißes Rauschen“ Regengeräusche ab und schaffe eine ruhige Atmosphäre im Zimmer.'),
  ('f73e2678-7057-466b-a01a-218bff7ab963', 'Zähneputzen mit Spaß. 🪥', 'Möchte dein Kind die Zahnbürste selbst halten? Putzt euch gemeinsam vor dem Spiegel mit einer passenden, weichen Zahnbürste die Zähne und macht das Zähneputzen so zur Gewohnheit.'),
  ('58b586ed-1396-42c6-81f5-29f087488332', 'Sanft in den Schlaf finden. 🌙', 'Dimme nach einem aktiven Tag das Licht im Zimmer, sprich leiser und bereite dein Kind mit einer ruhig vorgelesenen Geschichte auf den Schlaf vor.'),
  ('82b39d0a-8bac-4430-a17f-2937f0af35e1', 'Auch deine Energie kann zur Neige gehen. 🥗', 'Bist du sehr erschöpft? Bereite dir aus den gesunden Rezepten für Frauen einen vitaminreichen Smoothie zu, der dir schnell neue Energie schenkt, und gönn dir etwas Gutes.'),
  ('917ef6a5-ae0d-4133-b145-53d60f762945', 'Bring mir den Ball! 🧠', 'Dein Kind versteht einfache Aufforderungen inzwischen sehr gut. Wenn du es um etwas bittest und es dir den Gegenstand freudig bringt, zeigt das, wie schnell sich seine geistigen Fähigkeiten entwickeln.'),
  ('9e232723-1401-4819-8b29-1e4636b3edc3', 'Die ersten Kunstwerke! 🖍', '️ Dein Baby liebt es, mit dicken Wachsmalstiften auf Papier zu kritzeln. Bewahre seine ersten Kunstwerke im Bereich „Baby-Fotoshooting“ als Erinnerung für später auf.'),
  ('2423bd81-d7d2-4b3e-b97a-32a10186bc3d', 'Die ersten Rollenspiele beginnen. 🧸', 'Versucht dein Baby, seinen Teddybären zu füttern oder ihm Wasser zu geben? Das ist der süßeste Beweis dafür, wie aufmerksam es dich beobachtet und nachahmt!'),
  ('a589cdee-fd82-4fde-b44b-6b88fbe8e1cc', 'Hast du eine Frage? 🤖', 'Fragen, die dich beschäftigen, wie „Ist es normal, dass mein Kind beim Essen wählerisch ist?“, kannst du unserem Anacan KI-Assistenten sogar nachts stellen.'),
  ('d4f6586e-25f9-4dd3-9a6b-1408627d49eb', 'Widerstand gegen den Mittagsschlaf. 😴', 'Spielen ist einfach immer verlockender als Schlafen. Wenn dein Baby nur schwer einschläft, kannst du mit dem Anacan Schlaftimer den Schlafrhythmus der letzten Tage verfolgen und seine Routine entsprechend anpassen.'),
  ('13b16a71-31e8-44cf-bbf4-b97f55c8f45e', 'Ist das Wetter draußen unbeständig? ⛅', 'Das Wetter- und Kleidungs-Tool zeigt dir sofort die Windgeschwindigkeit, die du beim Blick aus dem Fenster nicht erkennen kannst.'),
  ('807a2e9f-2fb3-4378-94cf-0ad756854f25', 'Ein ganz persönliches Märchen 🪄', 'Erstelle in „Smarte Märchen“ eine besondere Geschichte, in der dein eigenes Kind die Hauptrolle spielt: Das mutige Kind, das zu den Sternen kletterte.'),
  ('d08fdb3f-542d-478d-95e6-72b2d85a8a9a', 'Noch 5 Tage bis zum 15. Monat! 🎈', 'Der Countdown ist fast vorbei! Inzwischen teilst du dein Zuhause mit einem kleinen Menschen, der herumläuft und alles versteht. Lächle!'),
  ('25f37869-be99-4918-83ae-dd5fecd2f5ce', 'Gemeinsam in der Küche. 🥦', 'Gib deinem Baby beim Kochen eine unzerbrechliche Plastikschüssel und einen Holzlöffel, damit es sein eigenes Essen zubereiten kann.'),
  ('4e2f3772-b7ad-4946-a8a3-70f3ebef0c4e', 'Auch du brauchst Energie. 🥗', 'Du bist den ganzen Tag auf den Beinen. Bereite dir mit unseren gesunden Rezepten für Frauen einen leckeren Snack zu, der dir neue Energie schenkt.'),
  ('6df61827-7605-47d2-aeef-a4e811b4d8c8', 'Rasante Entdeckungstouren! 🏃‍♂', '️ Dein Baby läuft inzwischen sicher von Zimmer zu Zimmer und möchte alles anfassen. Sorge dafür, dass euer Zuhause kindersicher ist, und genieße diese aktive Phase.'),
  ('c9b2a6a2-258b-4f8c-96f9-86282d8d8145', 'Lass deinen Gefühlen freien Lauf. 📝', 'Schreibe nach einem anstrengenden Tag deine Gefühle in dein Stimmungstagebuch und lass den Stress des Tages hinter dir. Du bist eine großartige Mama!'),
  ('14e2b559-f6b1-4ffb-ba5f-0e5d6eeca267', 'Du bist eine Heldin! ✨', 'Die Liebe und Fürsorge, die du in diesen 450 Tagen geschenkt hast, sind unbezahlbar. Lehn dich jetzt zurück und schlafe nach diesem schönen Tag ganz entspannt ein.'),
  ('4df5ec18-5365-45c2-a49d-90ce26310b0b', 'Schon ganze 15 Monate! 🎉', 'Wie die Zeit vergeht! Seit der Geburt deines Babys sind genau 1 Jahr und 3 Monate vergangen. Herzlichen Glückwunsch.'),
  ('a50254b7-b2f0-44b3-8ee9-5246bba08038', 'Glück am Familientisch. 🍲', 'Dein Baby kann jetzt schon dieselben Gerichte essen wie ihr. Entdeckt mit den Rezepten in unserer App köstliche Familiengerichte und feiert dieses kleine Jubiläum.'),
  ('157a98b7-1825-4699-b38d-85781cd21cf3', 'Marathon von Zimmer zu Zimmer 🏃‍♂️', 'Dein Baby läuft nicht mehr nur, sondern rennt schon fast! Sein Gleichgewicht wird von Tag zu Tag besser. Halte diese bewegungsreiche Phase voller Stolz im Entwicklungstracker fest.'),
  ('47ea1c98-c71a-45d9-b06c-d95aa3da437b', 'Papa als Spielkamerad 👨‍👧', 'Den ganzen Tag hinter deinem Baby herzulaufen, hat dich erschöpft. Am Abend ist Papa an der Reihe! Lass ihn das Herumtollen auf dem Boden und die Fangspiele übernehmen.'),
  ('c0b75b28-86cb-44ea-8bc4-de62c31fae30', 'Planung sorgt für Entspannung. 📝', 'Notiere dir kurz, was du morgen erledigen möchtest oder was es zu essen geben soll. So kannst du mit einem freien Kopf entspannt ins Bett gehen.'),
  ('e47ea433-71bf-4c11-8e6e-6edbaec03292', 'Es zeigt auf alles mit dem Finger. ☝', '️ Das ist die stille Version der Frage „Was ist das?“. Um seine Neugier wachzuhalten, benenne geduldig alles, worauf es zeigt.'),
  ('09564db7-642f-496e-b113-4fd15ad5aefe', 'Papas Nachtschicht 👨‍🍼', 'Du musst das nächtliche Aufwachen nicht ganz allein bewältigen. Wecke auch deinen Partner – ein Team zu sein bedeutet, die Verantwortung gleichmäßig zu teilen.'),
  ('30d6fd90-986c-491d-9a4a-39c6c9f48f69', 'Entwicklungscheck 🤖', 'Möchtest du mehr über die Entwicklungsschübe im 15. Monat erfahren? Dann wirf einen Blick in den Krisenkalender.'),
  ('661b0ef0-cce8-4702-8d5a-2f90901198ad', 'Freude am Bücherlesen. 📖', 'Die Seiten von Bilderbüchern umzublättern und dir beim Vorlesen zuzuhören, fördert den Wortschatz auf wunderbare Weise. Lest jeden Tag gemeinsam – und wenn es nur 10 Minuten sind.'),
  ('3d8cb5fe-0f15-4006-98f6-4f4232e5efb2', 'Es versteht deinen Tonfall 🗣️', 'Hält es inne und schaut dich an, wenn du mit ernster Stimme Nein sagst? Es beginnt bereits, Emotionen und Verbote zu verstehen!'),
  ('553f302d-8ba0-44d9-9d9d-e356d494f003', 'Abendroutine. 😴', 'Ein lauwarmes Bad und ein frischer Schlafanzug helfen ihm, sich zu entspannen, und bereiten es wunderbar auf den Schlaf vor.'),
  ('ed9814d4-d919-40b0-833b-d118d90c1727', 'Auf dem Weg zur Selbstständigkeit. 🥣', 'Wenn dein Baby seine Schüssel oder seinen Löffel selbst halten möchte, gib ihm die Gelegenheit dazu. Kleckern gehört zum Lernen einfach dazu.'),
  ('9b3b08e6-de82-413f-9e4b-6da904b304a3', 'Stresse dich nicht, weil das Haus heute so unordentlich ist.', 'Kinder erinnern sich nicht an ein aufgeräumtes Zuhause, sondern an eine glückliche Mama. Gieß dir einen Kaffee ein und entspann dich.'),
  ('67b35eea-eab9-41c5-88b7-f31e283eddd9', 'Dein Kind kann zu Hause seine Energie nicht loswerden und quengelt?  ⛅', 'Die Natur ist das beste Beruhigungsmittel. Schau aufs Wetter, wähle passende Kleidung aus und macht euch gleich auf den Weg in den Park.'),
  ('b9cf7b0e-6913-455f-8740-fcf7cc3d09d9', 'Die „Was ist das?“-Phase ☝️', 'Dein Kind zeigt mit dem Finger auf alles und macht dabei einen bestimmten Laut. Es möchte, dass du ihm die Welt benennst. Sag ihm geduldig, wie jeder Gegenstand heißt, auf den es zeigt.'),
  ('d4a833e4-9676-4c95-baa2-923b9117c325', 'Jetzt ist Ruhe gefragt 🤫', 'Die erste halbe Stunde nach dem Einschlafen ist die empfindlichste Phase. Prüfe den Geräuschpegel im Raum mit einem Schallpegelmesser und vermeide plötzlichen Lärm.'),
  ('088ce5b1-9a8e-4d7d-8f55-017e0cc63605', 'Hast du eine Frage? 🤖', 'Gibt es etwas in der Entwicklung deines 15 Monate alten Kindes, das dich beschäftigt? Verlier dich nicht im Internet, sondern schreib direkt der Anacan AI und erhalte eine wissenschaftlich fundierte Antwort.'),
  ('b6c6ae0a-2aaa-45b3-b8de-d4785923503c', 'Ein magisches Märchen 🪄', 'Erstelle in „Schlaue Märchen“ eine persönliche Geschichte über einen mutigen Helden, der die Welt entdeckt. So wird das Einschlafen noch schöner.'),
  ('c4cd946e-4029-4937-a10b-6f87983c2067', 'Übergang zu nur einem Tagschlaf 🥱', 'Dein Kind möchte morgens nicht mehr schlafen und der ganze Rhythmus gerät durcheinander? Es wird größer! Der Übergang von zwei Tagschläfchen zu nur einem beginnt. Passe die Routine langsam an.'),
  ('2517046a-f369-483a-b1e2-38f6320720ad', 'Ein warmes Bad entspannt. 🛁', 'Beim Spielen mit Wasser kann dein Kind den Staub und die Müdigkeit des Tages hinter sich lassen. Das macht ihm Spaß und bereitet es perfekt aufs Schlafengehen vor.'),
  ('1b9c01dc-4c8d-4f96-bbe5-d06d1d460981', 'Die süßen Momente des Tages. 📸', 'Halte mit dem Baby-Fotoshooting eine lustige Aktion oder eine neu erlernte Fähigkeit deines Babys für immer fest.'),
  ('21100889-9857-4170-a0a6-59c3dec113f8', 'Es testet seine Grenzen. 🛑', 'Greift dein Baby trotz deines Neins wieder nach demselben Gegenstand? Das ist kein Trotz, sondern ein Test, um die Regeln zu verstehen. Hab Geduld.'),
  ('66da2b8a-fe86-40dc-b027-d36d46f5091a', 'Ein kleiner Bücherfan 📖', 'Blättert dein Baby in Pappbilderbüchern und reagiert auf die Bilder? Sein visuelles Gedächtnis entwickelt sich. Lies ihm viele farbenfrohe Bilderbücher vor.'),
  ('5991e165-7b36-40d5-be3a-c6729cd8e924', 'Aufräumen oder ausruhen? 🛋️', 'Wenn dein Kind schläft, lauf nicht gleich zum Geschirrspüler. Leg dich aufs Sofa, schließe die Augen und atme 15 Minuten lang einfach nur durch. Bist du ein Roboter? Nein.'),
  ('67273a71-3d6d-40e2-b209-34b098335818', 'Jeden Tag wird dein Baby ein bisschen größer.📸', 'Öffne gleich das Baby-Fotoshooting und halte diesen innigen Moment als Erinnerung fest.'),
  ('d17f36fc-9cb8-4df2-a29e-60891f565b13', 'Der Wunsch, selbstständig zu essen 🥄', 'Dein Baby nimmt dir den Löffel aus der Hand und möchte selbst essen. Es wird kleckern und sich schmutzig machen, doch das ist wichtig für seine Motorik. Lass es selbstständig sein.'),
  ('145c55e0-770c-4adc-a15b-4bd94389378f', 'Gefahrenzonen in Reichweite ⚡', 'Dein Baby ist gewachsen und erreicht jetzt Regale, an die es vorher nicht herankam. TV-Möbel, Ecken ... Überprüfe dringend noch einmal, ob dein Zuhause kindersicher ist.'),
  ('b6ac32de-f983-4a93-89fc-cb209586570b', 'Sind die Backenzähne unterwegs? 🦷', 'Ist das Zahnfleisch deines Babys geschwollen und steckt es die Hand in den Mund? Vielleicht brechen die hinteren Zähne durch. Sieh im Zahnungs-Tracker nach und gib ihm gekühlte Beißringe.'),
  ('d2fd7757-cdd9-4cc6-b45c-347ada81b748', 'Licht dimmen 🌙', 'Schalte 1 Stunde vor dem Schlafengehen alle hellen Lichter und Bildschirme zu Hause aus. Melatonin wird nur in einer ruhigen, schwach beleuchteten Umgebung ausgeschüttet.'),
  ('4139adbd-6ed1-4e3e-a4dc-01c65b9d8182', 'Plötzliches Aufwachen 😭', 'Wacht dein Baby mitten in der Nacht schreiend auf und lässt sich nicht beruhigen? Lass die Schreianalyse die Stimme deines Babys analysieren, um herauszufinden, ob ein Nachtschreck oder Schmerzen dahinterstecken.'),
  ('cfd3d5f1-834e-412c-9e3a-a69a0413fbc1', 'Große Gefühle, kleiner Körper 🛑', 'Wirft sich dein Kind auf den Boden, wenn es nicht bekommt, was es möchte? Das sind die typischen Wutanfälle im Kleinkindalter. Bleib ruhig, stelle Blickkontakt her und sage ihm, dass du da bist.'),
  ('d33491b0-9722-4db2-ae48-c019740b7411', 'Gemeinsam stark 🥂', 'Erinnert euch gemeinsam an die ersten Tage und die schlaflosen Nächte und lacht darüber. Ihr habt es nicht ohne Weiteres bis hierher geschafft! Das ist euer gemeinsamer Erfolg.'),
  ('138aeaf3-e845-4d03-b6db-2a04410076a7', 'Immer noch wählerisch beim Essen? 🥦', 'Mach dir keine Sorgen, wenn dein Baby bestimmte Speisen ablehnt. Probiere für Babys, die gerade mit der Beikost beginnen, verschiedene und spielerische Anrichteideen aus den Rezepten aus.'),
  ('2f302f24-3142-4182-84a0-2782c5ce8394', 'Gefühle loslassen. 📝', 'War es ein sehr anstrengender Tag? Schreibe deine Gefühle in dein Stimmungstagebuch, nachdem dein Kind eingeschlafen ist, und lass so den Stress des Tages hinter dir.'),
  ('8b269aa5-a26e-4c52-b247-14a7194a3d35', 'Ein Marathon durch die Wohnung! 🏃‍♂', 'Dein Kind begnügt sich nicht mehr mit dem Laufenlernen, sondern versucht schon fast zu rennen. Genieße das Trippeln der kleinen Füße, aber lass dein Kind dabei nicht aus den Augen!'),
  ('8ee97257-b3d6-4144-ad9a-91e2e54c967a', 'Fangen spielen an der frischen Luft. 🌳', 'Kann dein Kind seine Energie zu Hause nicht loswerden? Geht gemeinsam an die frische Luft und lass es sich im Park frei bewegen und nach Herzenslust austoben.'),
  ('e84402f2-45d4-40ce-ae96-610f12a3e06b', 'Kleine Haushaltshilfe im Einsatz! 🧹', 'Möchte dein Kind unbedingt mit einem Tuch Staub wischen oder mit dem Besen spielen? Dich nachzuahmen ist einer der schönsten Teile seines Lernprozesses.'),
  ('ed63e2e3-10b5-4bd6-9b06-a81622e913eb', 'Eine Schlafroutine gibt Sicherheit. 🌙', 'Jeden Abend die gleichen Abläufe in derselben Reihenfolge (Baden, eine Geschichte vorlesen, das Licht dimmen) helfen deinem Kind, leichter einzuschlafen.'),
  ('ae5acd1f-b8cf-43ad-b265-37b9e76b0c35', 'Wörter verstehen lernen. 🧠', 'Findet und bringt dein Kind seine Schuhe, wenn du es darum bittest? Das zeigt, dass sich seine geistigen Fähigkeiten rasant entwickeln. Lobe und ermutige es ausgiebig!'),
  ('ce1fc21a-8f96-4c92-b928-5126f2240b1d', 'Auch du brauchst Energie. 🥗', 'Du bist den ganzen Tag auf den Beinen. Vergiss nicht, dir einen vitaminreichen und leckeren Snack zuzubereiten.'),
  ('d8cf1dda-3655-48e8-9316-6481b7ea82ba', 'Wutanfälle? 🌪', '️ Wenn dein Kind sich noch nicht ausdrücken kann, reagiert es möglicherweise wütend und weint. Wenn du dabei Unterstützung brauchst, lass dich von Anacan AI beraten und erfahre, wie du richtig damit umgehst.'),
  ('2b9c6af1-1706-4704-b2ce-29e57d4866f4', 'Papa ist an der Reihe. 👨‍🍼', 'Überlass es heute Papa, die Gute-Nacht-Geschichte vorzulesen und euer Kind ins Bett zu bringen, und gönn dir eine kleine Auszeit.'),
  ('8db205c2-0561-48d8-8b6c-61fc68065e2a', 'Die Kunst des Turmbauens. 🧱', '3-4 Bauklötze aufeinanderzustapeln und wieder umzuwerfen gehört zu den liebsten Beschäftigungen. Dieses Spiel fördert die Hand-Augen-Koordination besonders schnell.'),
  ('e513a042-7558-4dae-8bc5-5e2b5e5d74fa', 'Entspannt unterwegs. ☕', 'Bist du vom Alltagstrott gelangweilt? Finde unter den mutterfreundlichen Orten ein Café, das du bequem mit dem Kinderwagen besuchen kannst, und gönn dir eine Kaffeepause.'),
  ('258818a7-034e-4b93-86ea-97e8e01d3126', 'Wutanfälle? 🌪', '️ Wenn dein Kind sich nicht ausdrücken kann, wird es möglicherweise wütend und weint. Wenn du dabei Unterstützung brauchst, lass dich von Anacan AI beraten und erfahre, wie du richtig damit umgehst.'),
  ('ca5a1958-0c22-4c62-874b-c3b801f70118', 'Wörter verstehen. 🧠', 'Findet dein Kind seine Schuhe und bringt sie dir, wenn du sagst: „Bring deine Schuhe“? Das zeigt, dass sich seine geistigen Fähigkeiten rasant entwickeln. Lobe es ausgiebig!'),
  ('63bf2d84-bd96-49e0-9c51-b1f59bd85995', 'Zeit für Obst! 🍎', 'Bereite einen bunten, ansprechenden Teller mit saisonalem Obst vor, damit dein Kind neue Energie tanken kann.'),
  ('72ba71ca-1652-48f5-bc29-c321459f659a', 'Die Kraft von weißem Rauschen. 🎶', 'Wenn dein Kind nach einem aktiven Tag nicht einschlafen kann, spiele im Zimmer unter „Weißes Rauschen“ Meeres- oder Regengeräusche ab und schaffe so eine ruhige Atmosphäre.'),
  ('9cae6c34-b21b-425c-bdc8-0f1f07e9d0ea', 'Der Menü-Diktator 🥣', 'Schiebt dein Kind heute das Essen weg, das es gestern noch geliebt hat? In diesem Alter ist es normal, beim Essen wählerisch zu sein. Keine Panik – stöbere unter „Gesunde Rezepte“ nach verschiedenen Alternativen.'),
  ('54788c72-cfe2-4f75-82f0-ba29d942e404', 'Tierlaute nachahmen! 🐱', 'Spielt das Spiel „Wie macht die Katze?“. Diese einfachen und unterhaltsamen Nachahmungen sind eine hervorragende Grundlage für die Sprachentwicklung.'),
  ('b6e52bfa-dc31-4ddf-8f05-2d6b4e9ec2fa', 'Tanke neue Energie 🥑', 'Dein Kind ist satt, jetzt bist du dran. Iss dein Mittagessen im hektischen Alltag nicht im Stehen. Wähle unter „Gesunde Rezepte“ einen energiereichen Snack aus und mach es dir auf dem Sofa gemütlich.'),
  ('f3a87482-9f2e-4700-94d8-d413093ea00a', 'Die Kraft der Abendroutine 🛀', 'Ein warmes Bad hilft immer. Halte unbedingt an der Abendroutine fest, denn sie signalisiert dem Gehirn deines Kindes: Jetzt ist Schlafenszeit.'),
  ('6537418f-2c88-443b-b40f-e07f0ccd5801', 'Die Kraft des weißen Rauschens. 🎶', 'Wenn dein Baby nach einem aktiven Tag nicht einschlafen kann, sorge mit Meeresrauschen oder Regengeräuschen für eine beruhigende Atmosphäre im Zimmer.'),
  ('c45968e1-c58f-48dd-a705-2dc4c22325e0', 'Wachstumstempo. 📏', 'Die Kleidung wird schon wieder zu klein! Füge im Entwicklungs-Tracker die neuen Größen- und Gewichtswerte hinzu und aktualisiere die Wachstumskurve.'),
  ('f13027ff-0446-4962-9c51-398d40234b5a', 'Die ersten Kunstwerke! 🖍', '️ Dein Baby liebt es, mit dicken Stiften auf Papier zu kritzeln. Bestaune seine ersten Kunstwerke mit ganz viel Liebe.'),
  ('3b86e3a2-b53e-4603-a4b1-a57fc531000c', 'Dein Baby möchte selbst essen! 🥄', 'Auch wenn Kleidung und Umgebung dabei schmutzig werden, lass dein Baby den Löffel selbst halten. Das ist für seine Muskelkoordination und Selbstständigkeit sehr wichtig.'),
  ('ce4d24a9-fdbd-44df-93c0-058cf5d834aa', 'Süße Kuschelmomente! 🤗', 'Wenn dein Baby dich plötzlich umarmt oder zu küssen versucht, zeigt es dir damit seine Liebe. Genieße diese einzigartigen Momente und halte sie beim Baby-Fotoshooting für immer fest.'),
  ('fd4e2dc2-dbda-49c0-bcfc-b6880fe0e4a7', 'Freude am Vorlesen. 📖', 'Lass dein Baby die Seiten von Bilderbüchern selbst umblättern. Geschichten mit deiner Stimme zu hören, erweitert seinen Wortschatz.'),
  ('1cb9115d-9cf4-466e-adbe-8fa808d6b45c', 'Den Schlafrhythmus im Blick behalten. ⏱️', 'Wenn dein Baby tagsüber nur noch einmal schläft, wird es abends früher müde. Du kannst die Schlafenszeit am Abend etwas vorverlegen.'),
  ('42c60ff7-6aed-4b88-96d2-512be311f08c', 'Trinken nicht vergessen. 💧', 'Je aktiver dein Baby ist, desto mehr Durst hat es. Biete ihm beim Spielen und nach den Mahlzeiten regelmäßig Wasser an.'),
  ('6f0da037-da86-424d-bd6d-1e6d3aefe4db', 'Trau dich zu fragen 🤖', 'Denkst du, dass du bei der Schlafroutine etwas falsch machst? Frag Anacan AI sofort nach allem, worüber du unsicher bist, und lass dich beruhigen.'),
  ('b0d45a27-101a-4c13-b494-715c8c48dda4', 'Lass die ganze Erschöpfung hinter dir. 🥂', 'Vergiss nicht, heute Abend, wenn das Kind schläft, mit deinem Partner euren gemeinsamen Erfolg als Team zu feiern!'),
  ('8bf81bea-dee2-4f82-9f28-f1e6a128a812', 'Wenn der Geduldsfaden reißt. 📝', 'Manchmal kann die Energie deines Kindes dich völlig erschöpfen. Öffne dein Stimmungstagebuch und schreib ganz frei auf, was dich heute am meisten angestrengt hat.'),
  ('977f5267-192c-40d2-9215-420a5a54d255', 'Der Umstieg auf die Gabel. 🍴', 'Dein Baby versucht jetzt schon, sein Essen mit der Gabel aufzuspießen. Bereite mithilfe der Rezepte für Babys, die mit Beikost beginnen, Speisen zu, die sich leicht mit der Gabel aufnehmen lassen.'),
  ('c22aaf03-7bb2-467b-9c9d-ca82637af893', 'Es zieht seine Schuhe selbst aus 👟', 'Ist das Anziehen inzwischen zu einem Ringkampf geworden? Dein Kind zieht seine Socken und Schuhe schon selbst aus. Bestaune seine motorischen Fähigkeiten!'),
  ('3f154cd8-81d2-425b-aa71-ec2864247772', 'Das gehört mir! 🧸', 'Protestiert und weint dein Kind, wenn du ihm etwas wegnimmst? Sein Besitzgefühl wird stärker. Das ist ein wichtiger Teil seiner Persönlichkeitsentwicklung.'),
  ('7a8e2bea-1a47-4839-9ded-36d3fa6fbd27', 'Papa ist mit Baden dran. 👨‍🍼', 'Überlass heute Papa das abendliche Schaumbad mit Wasserspielen und das Zubettbringen – und gönn dir eine Pause.'),
  ('b60defb6-6a44-41ab-8087-7dec23cd3f5c', 'Was soll ich nur kochen? 🍲', 'Gehen dir die Ideen für den Beikostplan aus? Verlier dich nicht im Internet, sondern entdecke neue Köstlichkeiten im Bereich „Gesunde Rezepte“.'),
  ('9a860f2e-97a8-4151-9a68-ed86235ecd75', 'Die „Was ist das?“-Phase. ☝', '️ Es zeigt mit dem Finger auf alles und fragt dich, wie es heißt. Benenne geduldig jeden Gegenstand; so entdeckt es die Welt um sich herum.'),
  ('09bd2033-24ed-4376-ba68-6795f9e6d0fa', 'Es tanzt zur Musik! 🎶', 'Sobald es einen rhythmischen Klang hört, wiegt es sich hin und her und tanzt? Lade diese lebhaften Momente als Video ins Babyalbum hoch.'),
  ('899ab05b-717c-4e03-b941-aadf4ad85007', 'Allein spielen lernen. 🧩', 'Wenn dein Baby sich auch nur für kurze Zeit allein beschäftigen kann, zeigt das, dass sich seine Aufmerksamkeit weiterentwickelt. Beobachte es in diesen Momenten liebevoll aus der Ferne.'),
  ('98938324-49d8-43fc-bdde-202849487b20', 'Ein lauwarmes Bad entspannt. 🛁', 'Beim Spielen mit Wasser kann dein Baby den Staub und die Müdigkeit des Tages abschütteln. Das macht ihm Spaß und bereitet es wunderbar auf den Schlaf vor.'),
  ('67d07afb-a906-4267-ae07-195da32a67d1', 'Es testet Grenzen aus. 🛑', 'Greift dein Baby trotz deines Neins erneut nach dem Gegenstand? Das ist kein Trotz, sondern seine Art, Regeln kennenzulernen. Bleib konsequent und geduldig.'),
  ('71f533be-645b-4990-ac46-86ad77f1a038', 'Zeit für Obst! 🍎', 'Bereite einen farbenfrohen, ansprechenden Teller mit saisonalem Obst zu, damit dein Baby neue Energie tanken kann.'),
  ('cbf7129c-f3df-44ab-928f-9f74910675e9', 'Vergiss dich selbst nicht! 💖', 'Die erste Stunde, nachdem dein Kind eingeschlafen ist, sollte nur dir gehören. Erledige nichts, sondern beschäftige dich einfach mit etwas, das du liebst, und erhole dich.'),
  ('569d0003-c871-435a-ae9b-f4e977441a16', 'Nur noch 10 Tage bis zum 16. Monat! 🎂', 'Unglaublich! In genau 10 Tagen wird dein kleiner Schatz 16 Monate alt. Plane für diesen Meilenstein doch schon einmal eine kleine Torte oder ein Fotoshooting.'),
  ('8878ea41-701a-4729-9437-858b0e0448ae', 'Ballwerfen macht Spaß! ⚽', 'Dein Baby rollt den Ball nicht mehr nur, sondern hebt die Arme und versucht, ihn dir zuzuwerfen! Halte diese sportlichen Versuche auf Video fest und füge sie gleich dem Babyalbum hinzu.'),
  ('d2eace3f-d381-45ba-bfbb-2db61f670769', 'Wer ist auf dem Familienfoto? 🖼', '️ Zeigt dein Baby beim Anschauen der Fotos mit dem Finger auf die richtige Person, wenn du fragst: „Wo ist Oma?“ Sein Gedächtnis und seine Fähigkeit, Gesichter zu erkennen, entwickeln sich rasant.'),
  ('f2055f25-61d4-4680-83b3-954a3f1a9671', 'Kleine Bauversuche 🧱', 'Dein Baby versucht, zwei Bauklötze aufeinanderzustellen, doch sie fallen um. Aufmerksam probiert es immer wieder. Beobachte seine Versuche ganz in Ruhe.'),
  ('458a103b-d07a-4e59-ac24-1d9dafc323f0', 'Eine Auszeit für Mama ☕', 'Das viele Zuhausebleiben hat dir die Energie geraubt. Wähle unter den mama-freundlichen Orten ein gemütliches Café aus und nimm dir etwas Zeit für dich.'),
  ('d9ba76c2-3830-4eb2-b0e8-55a4c6a2f75e', 'Quengelphase auf dem Höhepunkt ☁️', 'Dein Baby ist mit nichts zufrieden und weint wegen jeder Kleinigkeit? Vielleicht brechen gerade die hinteren Backenzähne durch. Halte den Verlauf im Zahnungs-Tracker fest.'),
  ('ed11b132-51fc-4e86-99e0-021b6675020e', 'Ein Schlaflied für die Nacht 🎶', 'Keine Stimme beruhigt so sehr wie Mamas Stimme. Nimm dein Baby heute Abend einfach an deine Brust und singe ihm leise etwas vor.'),
  ('07f52bf7-1174-455b-9c35-8391687a69fe', 'Entwicklungscheck 🤖', 'Du möchtest mehr über die Entwicklungsschübe mit 16 Monaten erfahren? Bitte Anacan AI um eine kurze, präzise und kinderärztlich geprüfte Liste.'),
  ('c016a9a1-5e0d-434a-ba4b-907c1125a45a', 'Nur noch 5 Tage bis zum 16. Monat! 🎈', 'Der Countdown ist fast vorbei! Sind die Torte bestellt und die Outfits vorbereitet? Entdecke schon jetzt fröhliche Ideen für das Baby-Fotoshooting.'),
  ('d94026ce-ef2a-4e93-b559-9f926c9f245d', 'Beruhigende Klänge. 🎶', 'Wenn dein Kind nach einem Tag voller aktiver Entdeckungen nicht zur Ruhe kommt, spiele im Zimmer über die Funktion „Weißes Rauschen“ Regengeräusche ab und schaffe so eine entspannte Atmosphäre.'),
  ('523911e7-6ac9-424d-9f11-0729711fb179', 'Sinnesspiele. 🌾', 'Gib etwas Reis oder Nudeln in eine große Schüssel und verstecke darin Spielzeug. Lass dein Kind mit den Händen danach suchen und so seinen Tastsinn fördern.'),
  ('9d72a4f6-eac7-46c3-b9e9-ae6e482ce533', 'Zeit für selbstständiges Spielen 🧸', 'Dein Kind kann sich jetzt schon 10-15 Minuten allein mit seinem Spielzeug beschäftigen. Das zeigt, dass seine Aufmerksamkeitsspanne länger wird. Genieße die Ruhe.'),
  ('adb7bf26-343c-4ba5-8233-149cdef6b1f2', 'Die Kraft der Musik 🎶', 'Versuche, scheinbar grundlose Unruhe am späten Nachmittag mit sanfter klassischer Musik zu lindern. Oft wirkt dieser einfache Trick Wunder.'),
  ('35d30a24-8966-43d1-afce-6f79d49ebcec', 'Unterstützung vom Experten. 🤖', '„Mein Kind beißt mich – wie soll ich reagieren?“ Stelle unserem Anacan AI-Assistenten neue Fragen zu Verhaltensweisen, die dir Sorgen bereiten.'),
  ('5c715c5a-b613-43a0-9f22-5f59af3ae1fc', 'Die Kunst des Ausziehens. 🧦', 'Anziehen ist schwierig, aber Ausziehen macht richtig Spaß! Lass dein Kind versuchen, Mütze, Socken oder Schuhe selbst auszuziehen.'),
  ('d3844bde-9596-474d-adfe-9c81a7e0ff26', 'Die Sachen der Großen sind spannend. 👜', 'In deiner Tasche zu stöbern oder Papas Schuhe anzuprobieren gehört zu den Lieblingsbeschäftigungen deines Kindes. Lass es deine ungefährlichen Sachen erkunden.'),
  ('17b19954-1449-474d-a0b9-d199021947cc', 'Gesunde Mama, gesundes Baby 🥑', 'Deine Eisen- und Kalziumspeicher sind erschöpft. Bereite mit unseren gesunden Rezepten einen Salat zu, der schnell gemacht ist und dir neue Energie gibt.'),
  ('68c3e726-41d6-481a-91d7-a89fa5795172', 'Kritzelkunst 🖍️', 'Versucht dein Baby, auf Papier zu kritzeln, wenn du ihm einen Stift gibst? Das ist eine großartige Übung für die Feinmotorik. Achte darauf, dass die Stifte sicher und ungiftig sind.'),
  ('ab2f1bd1-caf0-41b5-b8ae-89ec60663539', 'Papas Nachtschicht 👨‍🍼', 'Bewältige das nächtliche Aufwachen nicht ganz allein. Wecke auch deinen Partner – ein Team zu sein bedeutet, die Verantwortung gleichmäßig zu teilen.'),
  ('1ba81e06-af3c-43ed-b2c1-9d0d1b231a26', 'Zeit für ein offenes Gespräch 💬', 'Belastet dich der Gedanke: „Ich werde nie wieder so sein wie früher“? Teile dieses vorübergehende Gefühl mit den anderen Müttern in der Anacan-Community.'),
  ('2980029e-45df-4043-851c-f7839d81a721', 'Morgen schon 16 Monate! 🎉', 'Bist du bereit? Morgen ist dein Baby genau 16 Monate alt! Schaffe etwas Speicherplatz auf deinem Handy, damit du beim Baby-Fotoshooting die süßesten Gesichtsausdrücke festhalten kannst.'),
  ('5d958416-87e8-44f2-8b6e-cde98e63822d', 'Heute bei den smarten Märchen 🪄', 'Erfinde bei den smarten Märchen eine Geschichte über mutige und liebenswerte Tiere und verwandle das Zimmer in einen magischen Ort.'),
  ('679e2936-6a93-4a92-9069-b372c4d3f661', 'Eine Gute-Nacht-Geschichte ist magisch. 📖', 'Dein Baby zeigt dir jetzt sogar selbst die Bilder im Buch. Eine kurze Geschichte, die ihr vor dem Schlafengehen gemeinsam lest, stärkt eure Bindung auf wundervolle Weise.'),
  ('86b4bb0f-0f98-485c-9149-10540747f598', 'GENAU 16 MONATE! 🎂', 'Unglaublich, oder? Seit jenem aufregenden Tag, an dem du dein Baby zum ersten Mal im Arm gehalten hast, sind genau 16 Monate vergangen! Jetzt ist der perfekte Zeitpunkt, diese wundervolle Entwicklung zu feiern. Wähle beim Baby-Fotoshooting ein Thema aus, verewige den süßesten Moment und teile deinen Stolz unbedingt mit den anderen Müttern in der Anacan-Community!'),
  ('fbb768fe-d41f-4451-8978-b683840f7855', 'Die Ein- und Ausräumphase! 📦', 'Die Spielsachen in eine große Kiste räumen und anschließend alle auf einmal auf dem Boden ausleeren! Dieses Ursache-Wirkungs-Spiel fördert das logische Denken deines Babys.'),
  ('24b47242-9a10-48f7-a928-0a19449b984a', 'Licht dimmen 🌙', 'Schalte eine Stunde vor dem Schlafengehen alle hellen Lichter und Bildschirme zu Hause aus. Melatonin wird nur in einer ruhigen Umgebung ausgeschüttet.'),
  ('2d66c314-cb67-48c8-93d1-be3249bad125', 'Schatzsuche in der Natur. 🍂', 'Sammelt bei einem Spaziergang im Park verschiedene Blätter oder Zapfen. Entdeckt über die mütterfreundlichen Orte neue Parks mit abwechslungsreichen Naturlandschaften.'),
  ('98db8b9f-36cd-4968-86c5-ed66999457de', 'Tierlaute 🐶', 'Versucht dein Kind beim Anblick einer Katze „Miau“ oder bei einem Hund „Wauwau“ zu sagen? Der Wortschatz beginnt mit Tierlauten. Spielt dieses Spiel gemeinsam.'),
  ('8e91be33-56a9-43aa-bf49-8aa525510abf', 'Schatzsuche in der Natur. 🍂', 'Sammelt bei einem Spaziergang im Park verschiedene Blätter oder Zapfen. Entdeckt über die mütterfreundlichen Orte neue Parks mit abwechslungsreichen Naturlandschaften.'),
  ('a9e6c327-e70b-4cd7-9bed-cb9d250622ba', 'Beruhigende Klänge. 🎶', 'Wenn dein Kind nach einem Tag voller aktiver Entdeckungen nicht zur Ruhe kommt, spiele bei den weißen Geräuschen Regenklänge ab und schaffe so eine entspannte Atmosphäre im Zimmer.'),
  ('e0bce3ef-dd35-48ce-9b1d-dc4a7ba30ba8', 'Ein- und Ausräumen! 📦', 'Die Spielsachen in eine große Kiste räumen und danach alle auf einmal auf dem Boden ausleeren! Dieses Ursache-Wirkungs-Spiel fördert das logische Denken deines Kindes.'),
  ('1705b7a5-fb30-4cc3-974a-91a4210ec2a2', 'Zeit nur für dich. 🛁', 'Dein Kind schläft und zu Hause ist es ruhig geworden. Lege jetzt dein Handy beiseite, mach einen Film an, den du magst, und genieße es einfach, einmal nichts zu tun.'),
  ('60fa7d8e-7d2e-4789-b844-5bdd9d35a5eb', 'Rückwärts und seitwärts gehen! 🦀', 'Dein Kind geht jetzt nicht mehr nur vorwärts, sondern testet sein Gleichgewicht auch mit Schritten nach hinten oder zur Seite. Halte diese lustigen Momente unbedingt auf Fotos fest.'),
  ('5a23341a-91f5-4bdf-a760-e7b99f610283', 'Offen für verschiedene Konsistenzen. 🥦', 'Wechsle die Farben und Formen der Speisen, um den Appetit deines Babys anzuregen. Lass dich im Bereich „Rezepte für Babys beim Beikoststart“ inspirieren.'),
  ('6581c209-98c5-4f79-adf1-c7b985567899', 'Du bist eine echte Heldin. 🛁', 'Du hast den ganzen Tag ein aufgewecktes, herumflitzendes Kind auf Trab gehalten. Gieß dir jetzt eine Tasse heißen Tee ein, schalte ab und ruh dich einfach aus.'),
  ('755229fb-26a0-4a27-af2c-49bb6a367386', 'Eine beruhigende Routine. 🌙', 'Wenn du vor dem Nachtschlaf das Licht im Zimmer dimmst und leise sprichst, kommt auch dein Baby zur Ruhe und kann sich auf das Schlafen einstimmen.'),
  ('ae949749-3a87-49dc-a4ae-057b9e3594b1', 'Vom Kritzeln zu gezielten Linien! 🖍', '️ Wenn dein Kind einen Stift in die Hand nimmt, versucht es nicht mehr nur Punkte, sondern auch lange Linien zu zeichnen. Fotografiere dieses kleine Kunstwerk und füge es gleich dem Babyalbum hinzu.'),
  ('f1cd31cb-c9bf-40c8-b2e0-ab0c8e5c21b9', 'Schatzsuche in der Natur. 🍂', 'Im Garten oder Park Blätter und kleine Steine zu sammeln und zu untersuchen, ist eine wunderbare Aktivität für die sensorische Entwicklung deines Kindes.'),
  ('1b65f6b1-f423-43f5-bc48-5ffb574c7c74', 'Entspannung bei Wasserspielen. 🛁', 'Beim Baden im lauwarmen Wasser mit den hineingelegten Spielsachen zu spielen, hilft deinem Kind, den Stress des Tages abzubauen, und macht außerdem jede Menge Spaß.'),
  ('bc0b7dcc-fdc0-4664-bff5-56183ea22258', 'Dein Kind versteht Anweisungen mit zwei Schritten! 🧠', 'Führt dein Kind beide Handlungen nacheinander aus, wenn du sagst: „Hol den Schuh und gib ihn mir“? Das ist ein Zeichen für einen großartigen Entwicklungssprung in seinem Denken!'),
  ('c18b2eee-ba78-43cc-89fd-423a464819d2', 'Mamas Energie ist sehr wichtig. 🥗', 'Das ständige Hinterherlaufen hat dich müde gemacht. Bereite dir mit unseren gesunden Rezepten für Frauen eine köstliche und vitaminreiche Mahlzeit zu.'),
  ('bf80d71f-c8bb-4983-b046-1ee91c367f20', 'Unterstützung durch einen Experten. 🤖', 'Du fragst dich: „Es versteht die Wörter, aber warum spricht es so wenig?“ Stelle unserem Anacan KI-Assistenten solche Fragen und finde beruhigende Antworten.'),
  ('cd0e822c-b843-41fa-9a3e-f4b682a848ae', 'Selbstständig mit dem Löffel essen. 🥄', 'Wenn dein Kind den Löffel zum Mund führt, verschüttet es immer weniger. Lobe diese feinmotorische Fähigkeit und gib ihm die Freiheit, es selbst zu versuchen.'),
  ('d6374c1a-94a0-4de3-855d-6a8d4e9a29af', 'Mitgefühl für Spielzeug. 🧸', 'Streichelt dein Kind seinen Teddybären, füttert ihn oder deckt ihn zu? Diese süßen Rollenspiele zeigen, wie schön sich seine emotionale Intelligenz entwickelt.'),
  ('299405ea-50dc-48c1-ba2a-233941bf627c', 'Papas Vorlesestunde. 👨‍🍼', 'Überlasse heute Papa das Vorlesen der Gute-Nacht-Geschichte und das Zubettbringen und gönne dir eine kleine Pause.'),
  ('7ad6ef35-e677-498c-8bc2-cc3e84535415', 'Die Sicherheitsmaßnahmen müssen angepasst werden. 🛡️', 'Schränke und Schubladen zu öffnen, gehört jetzt zu den Lieblingsbeschäftigungen deines Kindes. Sieh dir unbedingt unsere Liste mit empfohlenen Produkten für Kindersicherungen an.'),
  ('ec2361c8-31f7-458e-ad6e-506355b447a5', 'Neue Höhen werden erobert! 🧗‍♂', '️ Dein Kind kann jetzt höher greifen und leichter auf Möbel klettern. Es ist Zeit, die Sicherheitsmaßnahmen zu Hause noch einmal zu überprüfen.'),
  ('21888245-7cf1-48e4-a08b-53389aa39131', 'Mach Wassertrinken zum Vergnügen. 💧', 'Aktives Herumtoben und Spielen macht durstig. Biete deinem Kind regelmäßig Wasser in seiner bunten Trinkflasche an, damit es ausreichend Flüssigkeit bekommt.'),
  ('4595ac68-2033-4a66-a4d9-1146030382ed', 'Tagesbilanz. ✨', 'Du musst nicht jeden Tag perfekt sein. Wenn du heute nicht alles geschafft hast, ist das völlig in Ordnung. Für dein Kind bist du die Beste.'),
  ('f05a8717-d544-48fb-a529-17361118fee2', 'Wachstumsschub! 📏', 'Hast du das Gefühl, dass dein Kind gewachsen ist? Trage die neuen Werte im Bereich Gewichtstracker ein und sieh dir an, wie die Wachstumskurve ansteigt.'),
  ('75798a4e-e59c-4911-827e-b1622b37ae33', 'Haare kämmen und Zähne putzen. 🪥', 'Dein Kind beobachtet dich und fährt sich mit dem Kamm durchs Haar oder steckt die Zahnbürste in den Mund. Jetzt ist die ideale Zeit, ihm spielerisch Körperpflege-Routinen beizubringen.'),
  ('784b1d1b-2c53-42bf-a43b-d6b6e3121aba', 'Abendessen mit der Familie. 🍲', 'Du möchtest heute Abend nicht zu Hause kochen? Auf der Karte in unserer App findest du Restaurants mit einer eigenen Kinderkarte und Hochstühlen.'),
  ('b328273f-0602-46a6-a82b-54d47ec1b77d', 'Atme tief durch. ✨', 'Nicht jeder Tag läuft wie geplant, und manchmal bleibt zu Hause etwas liegen. Du musst nicht perfekt sein – für dein Kind bist du genau richtig.'),
  ('714f8ced-9ccc-40ff-a807-9428279f86d4', 'Sanft einschlafen. 🌙', 'Dimme nach einem aktiven Tag das Licht im Zimmer und singe deinem Kind mit sanfter Stimme ein Schlaflied, damit es entspannt in einen tiefen Schlaf findet.'),
  ('cd9fb3be-79a5-4ecd-980a-171e6fa00ed4', 'Lass dein Kind wählen. 👕', '„Möchtest du das rote oder das blaue Oberteil anziehen?“ Kleine Wahlmöglichkeiten verringern Trotzverhalten und stärken das Selbstbewusstsein deines Kindes.'),
  ('d25d87b5-6fc8-47d3-a3b2-ce74b55cbbfe', 'Verstecken für Fortgeschrittene! 🙈', 'Findet dein Kind sein Spielzeug problemlos, selbst wenn du es unter zwei verschiedenen Decken versteckst? Dann ist sein Verständnis für Objektpermanenz vollständig entwickelt.'),
  ('373a30b7-4c10-4d16-b029-a2c123ab28b9', 'Die ersten Laufversuche beginnen! 🏃‍♂', '️ Aus schnellen Schritten werden jetzt kleine Sprints. Auch wenn es immer schwieriger wird, die Knie vor Schrammen zu schützen, ist es unbezahlbar, die Freude deines Kindes an dieser neuen Freiheit mitzuerleben!'),
  ('9a00f6ae-31b9-432b-a4a4-3a97caf3bc85', 'Das Rhythmusgefühl wird stärker! 🎶', 'Bewegt sich dein Baby und lächelt, sobald es die ersten Sekunden seines Lieblingsliedes hört? Halte diese energiegeladenen Momente mit dem Baby-Fotoshooting fest und teile sie in der Familiengruppe.'),
  ('33b8d80d-5434-483c-b198-c7b20c73321d', 'Dein Baby lernt seine Körperteile immer genauer kennen. 👂', 'Wenn dein Baby neue Fragen wie „Wo ist dein Bauch?“ oder „Wo ist dein Ohr?“ richtig beantwortet, zeigt das, wie schnell es dazulernt.'),
  ('87029bf7-0808-4eac-a180-0abfa62f0b48', 'Lest gemeinsam ein Buch. 📖', 'Dein Baby blättert nicht mehr nur die Seiten um, sondern zeigt auch mit dem Finger auf Tiere oder Gegenstände im Buch und wartet darauf, dass du sie benennst.'),
  ('cc468aff-f9d2-4961-b955-bf2eaa13f7ef', 'Wie entwickelt sich das Wachstum? 📏', 'Ärmel und Hosenbeine werden schon wieder zu kurz! Trage die neuen Werte im Gewichts-Tracker ein und beobachte, wie die Entwicklungskurve ansteigt.'),
  ('308b629a-7190-416d-8240-7f61a2fe4d68', 'Wut, wenn dein Kind sich nicht ausdrücken kann. 🌪', '️ Es ist normal, dass dein Kind wütend wird und weint, wenn es nicht bekommt, was es möchte, oder sich nicht verständlich machen kann. Geh auf Augenhöhe und sage ihm, dass du seine Gefühle verstehst.'),
  ('78541e65-2128-40ff-8cb4-1e0d54454519', 'Lass deinen Gefühlen freien Lauf. 📝', 'War es ein sehr anstrengender Tag? Schreib deine Gefühle in dein Stimmungstagebuch, nachdem dein Kind eingeschlafen ist, und lass so den Stress des Tages los.'),
  ('7ea95622-1f8d-4996-8638-aeeafe28a802', 'Entdeckt neue Orte. ☕', 'Bist du vom Alltagstrott gelangweilt? Unter „Mama-freundliche Orte“ findest du Cafés, die du entspannt mit deinem Kind besuchen kannst und die eine Kinderkarte anbieten.'),
  ('58ff14f8-978e-4eec-8b86-a777de1b33ba', 'Aufräumen als Spiel. 🧺', 'Dein kleiner Schatz, der sein Spielzeug gern aus der Kiste ausräumt, lernt nun auch, einige Teile wieder hineinzulegen. Singt gemeinsam ein Aufräumlied und macht daraus ein lustiges Spiel.'),
  ('17791a06-d7d3-466d-acee-c2689fa82589', 'Fühlspiele. 🌾', 'Fülle eine große Schüssel mit Reis oder Sand und verstecke darin Spielzeug. Wenn dein Kind mit den Händen danach sucht, fördert das auf wertvolle Weise seine Feinmotorik.'),
  ('85ff80d1-72d4-4dd2-9fa5-45e283e54bc3', 'Selbst entscheiden, was es anzieht. 👕', 'Möchtest du das blaue oder das grüne Shirt anziehen? Zwei Optionen zur Auswahl zu geben, stärkt das Selbstbewusstsein deines Kindes und kann Trotzreaktionen etwas verringern.'),
  ('e6632c98-233d-431d-adc3-c5f78c1c7a37', 'Entspannung mit Wasserspielen. 🛁', 'Ein warmes Bad und das Plätschern des Wassers lassen die Müdigkeit des Tages verfliegen. Stelle unterschiedlich große Gefäße ins Wasser, um deinem Kind spielerisch ein Gefühl für Volumen und Mengen zu vermitteln.'),
  ('148de716-5fb6-4776-96cc-81e2d00b53b8', 'Teile deine Gefühle. ✨', 'Manchmal kommt einfach alles auf einmal. Widme dich am Ende des Tages einem Hobby, das du liebst, um wieder zu innerer Ruhe zu finden.'),
  ('b3ddea65-cbd9-4fdd-900d-8914e021db1f', 'Es wirft den Ball gezielt! ⚽', 'Dein Kind rollt den Ball nicht mehr nur, sondern versucht, ihn gezielt in eine bestimmte Richtung zu werfen. Das ist ein deutliches Zeichen dafür, dass sich seine Hand-Auge-Koordination weiterentwickelt.'),
  ('cbf9b73e-6e0b-4cbc-8731-ad9674e6dca3', 'Mach das Wassertrinken zum Vergnügen. 💧 A', 'Aktive Kinder bekommen schnell Durst. Biete deinem Kind regelmäßig Wasser in einer bunten, ansprechenden Trinkflasche an, damit sein Körper ausreichend mit Flüssigkeit versorgt bleibt.'),
  ('2f67b26a-192a-4bd5-87f9-5f376ff164e3', 'Zweiteilige Aufforderungen. 🧠', '„Nimm das Spielzeug und lege es in die Kiste.“ Wenn dein Kind solche komplexen Aufforderungen ausführt, zeigt das, dass sein Verständnis bereits gut entwickelt ist.'),
  ('bf0e882a-2f6d-4439-b170-c9adaeed59cd', 'Es tanzt im eigenen Rhythmus zur Musik. 🎶', 'Dein Kind wiegt sich nicht mehr nur hin und her, sondern klatscht passend zum Tempo der Musik in die Hände oder dreht sich im Kreis.'),
  ('b54bf6d9-a27d-4cd5-bc2b-21d160aa5b81', 'Ändert sich der Schlafrhythmus? ⏱️', 'Wenn dein Baby tagsüber nur noch ein Nickerchen macht, kann sich der Übergang zum Nachtschlaf etwas verändern. Verfolge mit dem Anacan-Schlaftimer den heutigen Tagesablauf und passe den neuen Rhythmus an.'),
  ('e71126af-730c-4cca-8daa-1682609e21a1', 'Formen zuordnen (Puzzles). 🧩', 'Dein Baby versucht, den Kreis in die runde Öffnung und das Quadrat in die quadratische Öffnung zu stecken. Diese Denkspiele fördern seine Geduld und Aufmerksamkeit.'),
  ('069cc383-0002-41b5-ba19-4172c6d6b10f', 'Fällt das Einschlafen schwerer? 😴', 'Aktives Entdecken kann dein Kind manchmal aufgedreht halten. Schalte den Schlaftimer ein, dimme vor dem Schlafengehen das Licht im Zimmer so weit wie möglich und lies eine Gute-Nacht-Geschichte vor.'),
  ('1beeca23-44cf-48f8-9b07-fc08412e7809', 'Danke und Bitte. 🙏', 'Wenn dein Kind etwas gibt oder bekommt, nickt es bereits oder bedankt sich in seiner eigenen Sprache. Jetzt ist genau der richtige Zeitpunkt, um soziale Umgangsformen zu lernen!'),
  ('eb807359-495c-4338-a628-e4dd3e405226', 'Wir verfolgen Wachstum und Gewicht. 📏', 'Werden die Kleidungsstücke schon wieder zu klein? Aktualisiere die neuen Werte im Bereich Gewichtstracker und erstelle zum 500. Tag ein Entwicklungsdiagramm.'),
  ('158d01ac-e4e7-4be6-959c-37e93007ee0b', 'Dein Kind erkennt die Tiere im Buch. 🐶', 'Zeigt dein Kind mit dem Finger darauf, wenn du fragst: „Wo ist der Hund?“ Beginne auch damit, die Farben der Gegenstände im Buch zu benennen, um seinen Wortschatz zu erweitern.'),
  ('9e266e10-1251-4668-af5f-a58fe3b3f537', 'Die Sicherheitsvorkehrungen müssen angepasst werden. 🛡️', 'Dein Kind kann inzwischen höher gelegene Dinge erreichen. Überprüfe Tischdecken und scharfe Ecken noch einmal. Bei Bedarf kannst du dir die empfohlenen Produkte ansehen.'),
  ('ca40c713-93a7-4e51-9b1b-8465a3151e1f', 'Papas Zeit zum Herumtoben. 👨‍🍼', 'Überlass Papa den energiegeladenen Teil des Abends. Gemeinsame Spiele voller Lachen stärken ihre Bindung und verschaffen dir zugleich eine Pause.'),
  ('c522fcf6-60fc-463a-b943-7933f5ac5c70', 'Die abendliche Märchenstunde ist magisch. 📖', 'Lass dein Baby die Geschichte anhand der Bilder mit eigenen Worten erzählen. Das legt den Grundstein für die spätere Freude am Lesen.'),
  ('19e05272-ac3b-430f-bbad-b5c770118fd3', 'Zeit zum Feiern! 🎈', 'Feiert diesen Tag mit einem kleinen Kuchen oder seinem Lieblingsobst. Zu sehen, wie schnell dein Baby wächst, ist deine schönste Belohnung.'),
  ('52e84dda-8f2e-4dce-9b8e-b095190c1816', 'Sei dir selbst dankbar. ✨', 'Danke dir selbst für all die Hingabe, Liebe und Geduld, die du in diesen 500 Tagen aufgebracht hast. Schlaf dich jetzt gut aus – morgen beginnt ein neuer Abschnitt!'),
  ('7cc24719-4bcf-403b-9178-3f6a80317c26', 'Unglaubliche 500 Tage.🎉', 'Kannst du es glauben?! Seit der Geburt sind genau 500 Tage vergangen!')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_de = v.t, body_de = v.b
FROM (VALUES
  ('ad8a8472-f316-41bd-82ab-7d5720d810ee'::uuid, 'Energieschub für Mama 🔋', 'Hat der Trubel des Tages deine ganze Energie aufgebraucht? Dich selbst bei der Kindererziehung zu vergessen, ist kein Heldentum. Bring dein Baby an einen sicheren Ort und gönn dir eine 10-minütige Kaffeepause.'),
  ('dcf8f474-5360-4c6f-ac54-ecde70444961', 'Das Tempolimit wird überschritten 🏃‍♂️', 'Dein Baby geht nicht mehr nur, es rennt schon fast! Da wird es immer schwieriger, hinterherzukommen. Trag diesen neuen Geschwindigkeitsrekord im Entwicklungstracker ein und räum mögliche Hindernisse zu Hause aus dem Weg.'),
  ('fb70ef32-f9e7-42c7-9f54-302457a506bf', 'Verständigung ohne Worte 🫂', 'Du hattest heute einen anstrengenden Tag. Wenn dein Baby eingeschlafen ist, setzt euch einfach schweigend nebeneinander aufs Sofa und genießt gemeinsam die Ruhe.'),
  ('19f5918f-33f2-423f-ba32-d0be2a6bca2a', 'Was dein Körper braucht 🥑', 'Tun dir die Arme oder der Rücken weh? Dein Baby wird immer schwerer. Unterstütze deine Muskeln mit einem leichten, kalzium- und eiweißreichen Mittagessen aus unseren gesunden Rezepten.'),
  ('1cec3e77-df8d-4fe0-9a15-4d7f7ee66785', 'Teile deine Erfahrungen 💬', 'Lässt dir der Gedanke „Ist mein Kind auch so?“ keine Ruhe? Tritt der Anacan Community bei, lies die Geschichten anderer Mütter mit 16 Monate alten Kindern und atme tief durch.'),
  ('61b42915-8f61-46a7-b887-07cc8998e71f', 'Ein beruhigendes Bad. 🛁', 'Vor dem Schlafengehen mit lauwarmem Wasser zu spielen, lässt die Anspannung des Tages verfliegen. Gib ein wenig ätherisches Öl ins Wasser und schaffe eine entspannte Atmosphäre.'),
  ('f5e358ba-f868-4a50-851c-6980fa2b0075', 'Der Versuch, allein Treppen zu steigen. 🪜', 'Wenn du dein Baby an der Hand hältst, steigt es die Treppe schon sicherer hinauf. Halte es nicht davon ab, damit es seine Beinmuskulatur stärken kann – achte einfach gut auf seine Sicherheit.'),
  ('bd0e8e10-27b9-43f5-b4c1-6f893a8d95e6', 'Deine Einkaufsliste für unterwegs 🛒', 'Ist im Alltagschaos das Shampoo oder sind die Feuchttücher ausgegangen? Versuche nicht, alles im Kopf zu behalten: Schreib es auf die Einkaufsliste und synchronisiere sie mit deinem Partner.'),
  ('c131d78d-b239-4de3-9bc9-c0c8fe25a6f7', 'Hast du eine Frage? 🤖', 'Warum wacht mein Baby nachts plötzlich häufiger auf? Solche Fragen kannst du unserem Anacan AI-Assistenten sogar mitten in der Nacht stellen und erhältst sofort eine Antwort.'),
  ('c67019a7-8ef8-4eef-bcc7-41d6f859382f', 'Ich hab dich gefunden! 🙈', 'Verdeckt dein Baby die Augen mit den Händen und spielt Kuckuck? Sein Verständnis dafür, dass Dinge weiter existieren, auch wenn es sie nicht sieht, entwickelt sich immer weiter.'),
  ('45bc547e-6211-4178-aad6-4266015ca9cf', 'Wir sind ein Team! 💖', 'Setzt euch nach einem anstrengenden Tag zusammen und sprecht offen darüber, was euch beschäftigt. Wenn ihr euch gegenseitig unterstützt, halbiert ihr die körperliche und emotionale Belastung.'),
  ('89373578-8a41-4cd9-bcef-3a5786b1f576', 'Fragen an den Kinderarzt 🤖', 'Was erwartet dich in der Entwicklung zwischen 16 und 18 Monaten? Statt beängstigende Berichte im Internet zu lesen, kannst du Anacan AI um eine fundierte fachliche Zusammenfassung bitten.'),
  ('3ddcf967-26bf-4c82-a9be-ef2d0c28d637', 'Fantasiespiele beginnen 🧸', 'Versucht dein Baby, seinen Teddybären zu füttern oder ins Bett zu bringen? Seine Fantasie erwacht! Beobachte diese wunderbaren ersten Versuche, Mitgefühl zu zeigen, mit Stolz.'),
  ('c178ee13-258d-408c-8a70-3133436f4f3b', 'Spielzeit mit Papa 👨‍👧', 'Bist du mit deiner Geduld am Ende? Dann überlass heute Abend Papa das Herumtollen auf dem Boden und die Kitzelspiele.'),
  ('05b16636-3744-4ea1-b6f2-f3824e51cd2d', 'Entdeckungsreise in der Küche. 🍎', 'Lass dein Baby beim Waschen des Obstes mithelfen. Das Geräusch des Wassers und die Farben der Früchte werden seine Neugier wecken.'),
  ('3fd7287e-bc6f-49d6-a94b-292122e10559', 'Erste Zweiwortsätze. 🗣', '️ Versucht dein Baby, zwei Wörter wie „Ma-ma, gib“ oder „Pa-pa, schau“ miteinander zu verbinden? Das ist ein großartiger Entwicklungssprung beim Sprechen!'),
  ('d3ed901e-4f05-435d-a1d6-02b2847be818', 'Magische Geräuschkulisse für die Nacht 🪄', 'Hat dein Baby Schwierigkeiten beim Einschlafen? Spiele als beruhigende Hintergrundkulisse weißes Rauschen ab, das nur aus sanften Flussgeräuschen besteht.'),
  ('9884e1c4-18cf-4fce-b89d-ae4f4603110b', 'Kleiner Künstler bei der Arbeit 🖍️', 'Kritzelt dein Baby auf Papier (oder an die Wand), sobald du ihm einen Stift gibst? Seine Feinmotorik entwickelt sich rasant. Zeit, abwaschbare Malstifte zu besorgen.'),
  ('cbbf4112-6812-4999-b3bd-fe378d632205', 'Papas Geschichtenstunde. 👨‍🍼', 'Überlass Papa die letzten ausgelassenen Spiele des Abends. Ihr gemeinsames Lachen wird für dich die schönste Geräuschkulisse zum Entspannen sein.'),
  ('fcd25c40-af67-4335-a70a-9d6c3e016480', 'Wetter-Check ⛅', 'Ist es draußen windig oder einfach nur kühl? Verlass dich nicht nur auf den Blick aus dem Fenster. Das Wetter- und Kleidungstool zeigt dir in Sekundenschnelle das passende Outfit.'),
  ('daea63ca-66de-40da-bafb-c740af314d06', 'Bücherliebe 📖', 'Blättert dein Baby selbstständig die Seiten um und berührt die Bilder mit dem Finger? So entwickelt sich schon jetzt die Freude am Lesen. Benenne gemeinsam mit deinem Baby, was auf den Bildern zu sehen ist.'),
  ('1ba2f4ba-35bf-41b8-9b1d-a9de5072ed4d', 'Ist dein Kind plötzlich schreiend aufgewacht?', 'Es könnte sich um einen Nachtschreck handeln. Lass die Weinanalyse den Laut auswerten, um herauszufinden, ob die Ursache körperlich oder psychisch ist.'),
  ('e0bbc5a2-5e4d-47c8-bbdb-cfdb203faf5c', 'Der Haushalt kann warten 🛑', 'Der Boden ist noch nicht gewischt? Dann lass ihn so. Eine unordentliche Wohnung lässt sich aufräumen, doch eine erschöpfte Mutter braucht lange, um sich zu erholen. Leg dich aufs Sofa und genieße einfach die Ruhe.'),
  ('fba2093e-fbf1-4663-b05f-7071650fd43f', 'Logikspiele 🧱', 'Stapelt dein Kind 3-4 Bauklötze zu einem Turm? Halte diesen motorischen Erfolg im Entwicklungs-Tracker fest! Feiere seine kleinen Bauversuche.'),
  ('0fea9ae7-0132-47ff-9282-adcf39bd128b', 'So fällt das Einschlafen leichter. 🌙', 'Dimme das Licht im Zimmer so weit wie möglich und sprich leise im Flüsterton. Das signalisiert seinem Nervensystem, dass es Zeit ist, sich auszuruhen.'),
  ('449d1eaf-e90d-45bb-8ac5-83cc8e44397d', 'Zeit zum Auftanken. 🍎', 'Wenn dein Kind schläft, schließe auch du für 20 Minuten die Augen. Die Hausarbeit nimmt kein Ende, deine Energie aber schon. Achte gut auf dich.'),
  ('eb955e5b-023a-4e67-ac53-d6ab712c507e', 'Kleine helfende Hand. 🧺', 'Wenn du die Spielsachen in die Kiste räumst, bringt dein Kind auch eines und legt es hinein? Lobe diese kleinen Hilfsversuche unbedingt und bedanke dich bei ihm.'),
  ('49fd2511-4696-40ce-a9eb-8140a6570163', 'Der Zauber der personalisierten Märchen 🪄', 'Erstelle ein besonderes Märchen, in dem dein eigenes Kind die Hauptfigur ist: ein mutiges kleines Kind, das durch den Zauberwald streift.'),
  ('f03e45ee-5599-42df-9ad9-5c86e351f328', 'Mamas Zeit für sich 🎧', 'Lauf nicht gleich in die Küche, sobald dein Kind schläft. Setz deine Kopfhörer auf, mach einen deiner Lieblingssongs an und sei 15 Minuten lang einfach nur du selbst.'),
  ('ff37a7ef-9322-44bc-9dbd-322f32bc0ec9', 'Es will unbedingt selbst essen. 🥄', 'Wenn dein Kind dir den Löffel aus der Hand nimmt, lass es ruhig machen. Auch wenn es sich dabei schmutzig macht: Selbstständiges Essen ist ein wichtiger Beweis für seine wachsende Unabhängigkeit.'),
  ('09e40e6a-1b4a-402d-88ca-e9d2b030ae96', 'Schau mich an! ☝️', 'Dein Kind macht Geräusche, um deine Aufmerksamkeit zu wecken, und zeigt mit dem Finger auf etwas, das es interessiert. Teile seine Entdeckungsfreude und bestätige: Ja, das ist ein Ball.'),
  ('c5a0bf61-8c64-48fe-98e1-446f7f35fcb3', 'Der hartnäckige Löffel 🥄', 'Dein Kind möchte selbst essen und verschüttet dabei die Hälfte auf sich? Konzentriere dich nicht auf die Sauberkeit. In dieser Zeit wird der Grundstein dafür gelegt, dass es selbstständig essen lernt.'),
  ('c62d64af-c28e-4bfc-82ce-a73c5d55fd91', 'Tagesbilanz 📝', 'Wenn du dich nicht gut genug fühlst, schreib deine kleinen Erfolge von heute in dein Stimmungstagebuch. (Zum Beispiel: Ich habe mein Kind zum Lachen gebracht und dafür gesorgt, dass es satt ist). Du bist großartig.'),
  ('14fb698f-87dd-4c4e-b7ba-3a1f2a79dd22', 'Das Gespräch wird immer ernster 🗣️', 'Dein Kind erzählt dir etwas in unverständlichen Worten und gestikuliert dabei sogar? Geh mit derselben Ernsthaftigkeit auf den Dialog ein – das ist eine wichtige Voraussetzung für seine Sprachentwicklung.'),
  ('1d9a7143-69c8-42b7-9dd5-0d7f48adbb9c', 'Die Kraft frischer Luft 🌙', 'Dein Kind will nicht schlafen? Öffne das Fenster und lüfte das Zimmer gründlich. Kühle, frische Luft erleichtert das Einschlafen.'),
  ('66766839-1404-43e5-8e4f-02d3ea6ce97c', 'Verdacht auf eine Allergie? 🤖', 'Du hast deinem Kind eine neue Frucht gegeben und es hat Hautrötungen bekommen? Bevor du in Panik gerätst, informiere dich bei Anacan AI über die ersten Schritte bei einer möglichen Nahrungsmittelallergie bei Kindern.'),
  ('59f57b09-3fb4-490e-8cae-41edccebdd18', 'Süße Träume 🌙', 'Du hattest heute einen anstrengenden Tag. Spiele beim Einschlafen unter „Weißes Rauschen“ Meeresrauschen ab, damit dein Baby ruhig schläft und auch du dich erholen kannst.'),
  ('69941885-7481-4f3d-83b9-75392ac8bf14', 'Essens-Timer ⏱️', 'Die Essenszeiten im Blick zu behalten, ist jetzt noch einfacher! Starte den Fütterungs-Timer und behalte die tägliche Nahrungsmenge deines Babys genau im Auge.'),
  ('76342fb8-c3b7-4c1b-a6cb-70ae7ab72954', 'Jetzt geht das Rennen los! 🏃‍♀️', 'Wirbelt dein 17 Monate alter Entdecker zu Hause alles durcheinander? Entdecke unter „Mama-freundliche Orte“ einen neuen Park in deiner Nähe, in dem dein Kind sich austoben kann.'),
  ('310b35fd-56c2-4e43-bf45-49c975449bf2', 'Lecker und mal etwas anderes! 🥦', 'Du überlegst, was du deinem Baby heute Besonderes kochen könntest? Im Bereich „Rezepte“ findest du köstliche Ideen für Babys, die gerade mit der Beikost beginnen.'),
  ('9477e55c-8f99-4ea9-8c87-38780aa67baa', 'Schreib deine Gefühle auf 📝', 'Muttersein kann manchmal anstrengend sein – und das ist völlig normal. Schreib in dein Stimmungstagebuch, was dich heute am meisten erschöpft hat, und lass ein wenig los.'),
  ('bd556eab-5192-450f-94ce-a80cdc85557b', 'Morgendliche Überraschung 💩', 'Hast du heute schon die erste Windel gewechselt? Vergiss nicht, es im Windel-Tracker der App einzutragen, damit du die Hygieneroutine ganz einfach im Blick behältst!'),
  ('86fd1056-7ec6-4295-9ae9-cce90735b8fe', 'Mittagsschlaf 😴', 'Starte den Schlaf-Timer! Analysiere die Dauer des Mittagsschlafs deines 17 Monate alten Kindes, um die Schlafenszeit am Abend genauer zu planen.'),
  ('88975ce2-bde2-4036-a81f-ecfc994e6ec7', 'Praktisch und sicher trinken 🍼', 'Du suchst den besten auslaufsicheren Trinklernbecher, damit dein Baby selbstständiger trinken kann? Sieh dir im Bereich „Empfohlene Produkte“ die beliebtesten Favoriten anderer Mütter an.'),
  ('8fe0e4be-15b3-4472-a10c-0dbbc28c48cc', 'Heute mal etwas anderes 🌟', 'Langweilt euch der Alltag zu Hause? Öffne unsere Karte mit familienfreundlichen Orten und entdecke ein neues Café, in dem du mit deinem Baby entspannt sitzen kannst.'),
  ('ea228eca-a9dc-4d32-bfab-5af38c95cc81', 'Kleiner Star! 📸', 'Dieses süße Lächeln ist unbezahlbar! Halte diesen Tag mit der Baby-Fotoshooting-Funktion und verschiedenen Rahmen für immer fest.'),
  ('5124c8a0-ed5f-4aa8-8203-12fc951409c5', 'Verdauungs-Check ⏱️', 'Die tägliche Anzahl der Windelwechsel gibt Aufschluss darüber, ob dein Baby ausreichend Nahrung bekommt. Hast du die heutigen Windelwechsel schon in unserer App eingetragen?'),
  ('9c188bf4-4509-4c22-a2b7-a1a25cc28562', 'Gemeinsam am Familientisch 🍲', 'Was bekommt dein Baby heute zum Abendessen? In unseren Beikostrezepten findest du gesunde Gerichte, die der ganzen Familie schmecken.'),
  ('dab8f6cb-2ef5-454d-85b6-120c0f7644eb', 'Deine Geschichte als Mama 📝', 'Die Geschichte jeder Mutter ist einzigartig. Lass dich von den echten Erfahrungen und Geschichten anderer Mütter in unseren Blogs inspirieren.'),
  ('2522685d-511e-40e4-ab2a-4b34a238936c', 'Laufen im Park 👟', 'Nach den ersten Schritten folgen schon bald die ersten Laufversuche. Entdecke im Bereich „Empfohlene Produkte“ gesunde Modelle für die ersten Schuhe.'),
  ('4b619580-dcf5-4c3a-a584-37bd74dfbaba', 'Ruhe im Kinderzimmer 🌊', 'Fällt das Einschlafen heute schwer? Spiele bei den Weißen Geräuschen das Rauschen der Meereswellen ab, um das Nervensystem zu beruhigen und das Einschlafen zu erleichtern.'),
  ('7ae22b42-7e16-455e-8d98-b410c2cd5c7a', 'Bekommt dein Kind genug Eiweiß? 🍗', 'Eiweiß ist für das Wachstum deines Kindes unverzichtbar! Überprüfe mit dem Ernährungstracker die tägliche Nährstoffbalance und gleiche mögliche Defizite aus.'),
  ('b24e422c-33a1-4394-8c5a-e6048392180c', 'Vergiss dich selbst nicht! ☕', 'Deine Energie ist besonders wichtig für dein Baby. Bereite dir mit unseren gesunden Rezepten einen leckeren, energiespendenden Smoothie zu.'),
  ('6a0dbe71-a2e3-4dfc-90e2-77ab87992f1d', 'Blog und Kaffee 📖', 'Dein Kind schläft – jetzt gehört die Zeit dir! Lies unseren neuen Blogbeitrag und erfahre spannende Fakten über die Psychologie besonders aktiver Kinder.'),
  ('92227c75-1f64-4b68-adfc-1f2f5187c456', 'Entspannt unterwegs 👟', 'Braucht ihr beide bequeme Schuhe, damit du deinem Kind im Park hinterherlaufen kannst? Entdecke die besten Optionen im Bereich „Produktempfehlungen“.'),
  ('ee92e380-b93d-467f-ae59-b65756c20e29', 'Hast du eine Frage? 🤔', 'Fragst du dich, wie du mit der zunehmenden Trotzphase deines Kindes umgehen kannst? Anacan AI beantwortet deine Fragen sofort mit fachkundigen Empfehlungen!'),
  ('0d93db4a-8b6f-404c-af2e-d97c0d79adf5', 'Atme tief durch ✨', 'Es muss nicht alles perfekt sein. Du bist auch so die beste Mama! Lass den Stress des Tages im Stimmungstagebuch los und gönn dir etwas Erholung.'),
  ('c34d441d-5c3c-48a4-9477-974b42412b6e', 'Schon wieder gewachsen? 🦒', 'Werden die Kleider langsam zu eng? Trage die neuen Werte im Wachstumstracker ein und sieh nach, wie sich die Wachstumskurve entwickelt.'),
  ('d37162b5-bdeb-4abc-8206-52d2382cc6de', 'Ausgewogene Ernährung 🥣', 'Hat dein Baby heute genug Eiweiß bekommen? Analysiere den täglichen Speiseplan deines Babys mit dem Ernährungstracker und gleiche mögliche Defizite aus.'),
  ('06c24f98-8519-42a4-86d5-14e6b430bf94', 'Beruhigende Klänge 🌧️', 'Kann dein Baby nach einem aufregenden Tag nicht einschlafen? Wähle unter „Weißes Rauschen“ das Geräusch von Regen aus und hilf seinem Nervensystem, auf natürliche Weise zur Ruhe zu kommen.'),
  ('2c591870-5eb2-4029-b209-ea812c8276ab', 'Ist der Schlaf-Timer aktiviert? ⏳', 'Bringst du dein Baby gerade ins Bett? Starte den Timer, analysiere die Einschlafdauer und erfahre, wie du diese Routine verbessern kannst.'),
  ('9c6e1121-6b3a-4988-b52a-daff7cb47017', 'Dein smarter Helfer 🤖', 'Warum hat dein Kind plötzlich keinen Appetit mehr? Stelle Anacan AI diese oder andere Fragen, die dich beschäftigen, und erhalte sofort eine wissenschaftlich fundierte Antwort.'),
  ('fb78ab52-3c7a-4706-adfa-55485f38dc6d', 'Energie tanken 🔋', 'Bist du bereit für den turbulenten Alltag? Wähle aus unseren gesunden Rezepten für Frauen ein leckeres, vitaminreiches Frühstück für dich aus.'),
  ('543206e3-a734-4c0f-89e0-a5bb0b8f6100', 'Komfort für dein Kind 🍼', 'Suchst du den besten auslaufsicheren Trinklernbecher, damit dein Kind selbstständig trinken kann? Entdecke unter „Empfohlene Produkte“ die beliebtesten Favoriten anderer Mütter.'),
  ('70ce55d5-f110-4637-a672-3efae4b7e852', 'Du schaffst das! 💪', 'Hattest du einen schwierigen Tag? Höre in deinem Stimmungstagebuch auf deine innere Stimme. Denk daran: Es ist nur ein schwieriger Tag, kein schlechtes Leben.'),
  ('787e9318-ea30-497d-9a1a-d3de64060a9d', 'Ernährungsbericht 📊', 'Trage die heutigen Mahlzeiten deines Kindes in den Ernährungstracker ein. Schauen wir, ob es heute alle wichtigen Vitamine bekommen hat.'),
  ('15793f9f-2b07-4de4-817b-a555822e7e8e', 'Der besondere Moment des Tages 🖼️', 'Eine besondere Erinnerung an den 520. Tag! Lade die schönsten und lustigsten Fotos ins Babyalbum hoch und erinnere dich auch Jahre später noch mit einem Lächeln daran.'),
  ('58bde9b3-f42d-49ca-ae5b-48563d307555', 'Ein Entwicklungsschub? 📈', 'Weint dein Kind viel oder schläft es plötzlich schlechter? Frage Anacan AI, ob dahinter der Entwicklungsschub im 17. Monat stecken könnte.'),
  ('136efb64-ddf1-465d-be06-c1f4f0ca13f2', 'Will dein Baby selbst essen? 🥦', 'Strebt dein Baby nach mehr Selbstständigkeit? Wähle unter Rezepte leckere, griffige und kleckerfreie Portionen für Babys, die gerade mit der Beikost beginnen.'),
  ('37e233ca-794d-4595-8c1d-115d93279302', 'Trotzphase meistern 🤖', 'Sagt dein Kind zu allem Nein? Wenn du nicht weißt, wie du mit den Krisen dieser Phase umgehen sollst, lass dich direkt von Anacan AI beraten.'),
  ('256bddeb-107b-434f-9688-0c6670394bc8', 'Werden die Kleider zu eng? 📏', 'Hast du das Gefühl, dass dein Kind plötzlich einen Wachstumsschub gemacht hat? Trage die neuen Werte im Gewichts-Tracker ein und sieh dir die Wachstumskurve an.'),
  ('ac852fa3-348f-43fe-9321-7b4e3e9f3af1', 'Mahlzeiten-Timer ⏱️', 'Wie lange dauert eine Mahlzeit? Starte den Mahlzeiten-Timer und behalte den Rhythmus im Blick, damit genügend Zeit für die Verdauung bleibt.'),
  ('f78fdccc-68a3-4827-b309-2accfb39bff1', 'Lesenswertes für dich 📖', 'Das Kind schläft – und was machst du? Lies die neuesten Artikel in unserem Blog-Bereich und erweitere dein Wissen rund ums Mamasein.'),
  ('0a2bf8ce-6e82-41df-9345-19718f7bde4c', 'Auf der Suche nach dem idealen Trinklernbecher 🥤', 'Suchst du einen auslaufsicheren und praktischen Trinklernbecher? Entdecke unter Empfohlene Produkte die von Müttern am häufigsten getesteten Produkte.'),
  ('12fa87ff-96f2-48c2-a70c-da7757524f9b', 'Kaffeepause ☕', 'Möchtest du heute rausgehen? Finde unter Mama-freundliche Orte ein Café mit Spielecke und nimm dir etwas Zeit für dich.'),
  ('5bd8188b-93fc-435a-8a33-b488c4ecc902', 'Gefühle loslassen 📝', 'Heute lief nicht alles nach Plan? Mach dir keine Vorwürfe. Schreib im Stimmungstagebuch auf, was dich innerlich belastet, und befreie deinen Kopf.'),
  ('7771d800-de2f-41eb-8bd6-431add8986fe', 'Entspannende Abendroutine 🌙', 'Ein schöner Tag geht zu Ende. Starte den Schlaftimer, wähle ein Schlaflied aus den Weißen Geräuschen und genieße ganz in Ruhe den Ausklang des Tages.'),
  ('b9d3a084-eae2-4a4a-af8c-e99d02752f66', 'Auf der Suche nach frischer Luft 🌳', 'Fällt dir zu Hause die Decke auf den Kopf? Öffne unsere Karte mit familienfreundlichen Orten und entdecke einen neuen Park, in dem du entspannt mit deinem Baby spazieren gehen kannst.'),
  ('c7d9bc7f-54a9-4f50-9876-80c78adff647', 'Zeit zum Schlafen ⏱️', 'Bringst du dein Baby gerade ins Bett? Starte den Schlaftimer und analysiere seinen Schlafbedarf, indem du festhältst, wie gut ihr eure Schlafroutine einhaltet.'),
  ('e064d0bf-455a-4252-9305-e3585f5b88ac', 'Wie ist der Appetit am Morgen? 🥣', 'Ein gesunder Start in den Tag ist wichtig! Berechne mit dem Ernährungstracker den heutigen Vitaminbedarf und plane das passende Menü.'),
  ('0d268555-6803-4b45-adab-7558434a3d7b', 'Morgenroutine 💩', 'Hast du heute schon die erste Windel gewechselt? Farbe und Konsistenz des Stuhls geben Aufschluss über die Darmgesundheit. Trage die Daten gleich in den Windeltracker ein!'),
  ('7d0a17bf-475f-48d2-9838-14918053b021', 'Energie für Frauen 🥗', 'Die tägliche Hektik kann anstrengend sein. Vergiss dich selbst nicht! Bereite mit unseren gesunden Rezepten für Frauen einen leckeren Salat zu, der dir schnell neue Energie schenkt.'),
  ('b2894838-9e87-4d9f-80b1-63a311667ac3', 'Die Magie der Weißen Geräusche 🌧️', 'War es ein besonders aktiver Tag? Spiele im Zimmer das Regengeräusch aus den Weißen Geräuschen ab, damit dein Baby leichter einschläft und auch du durchatmen kannst.'),
  ('0b41a1b3-ce5c-4804-b352-c95cc9725120', 'Der süßeste Moment des Tages 📸', 'Hat dein Baby heute etwas Ungewöhnliches oder Lustiges gemacht? Halte diesen Augenblick mit den verspielten Rahmen des Baby-Fotoshootings fest und mache ihn zu einer Erinnerung fürs Leben.'),
  ('30a82706-c2b4-4804-8bf8-50b827b59af2', 'Schauen wir uns den Schlafbedarf an 😴', 'Wie hat dein Baby letzte Nacht geschlafen? Sieh dir die Aufzeichnungen des Schlaf-Timers an und prüfe, ob dein Baby seinen täglichen Schlafbedarf erreicht hat.'),
  ('63599f1b-cfac-43fe-af30-fa096e5c9039', 'Was bereitet dir Sorgen? 🤖', 'Hast du Fragen oder Bedenken zur Entwicklung deines Kindes? Schreib unserem KI-Experten Anacan und erhalte wissenschaftlich fundierte Antworten, die dir Sicherheit geben.'),
  ('c29b8ee7-5a3e-484e-b3fb-fba482038bb2', 'Jede Mahlzeit schmeckt anders 🍲', 'Die Frage „Was soll ich heute kochen?“ hat ein Ende. Unter „Rezepte“ findest du abwechslungsreiche und gesunde Menüs für Babys, die mit der Beikost begonnen haben.'),
  ('0c8639eb-e97c-4e44-a8d2-900ea16527d9', 'Täglicher Ausscheidungsbericht 💩', 'Vergiss nicht, den Windelwechsel am Morgen einzutragen! Wenn du die Windelwechsel über den Tag hinweg erfasst, kannst du erkennen, ob dein Kind ausreichend Flüssigkeit bekommt.'),
  ('c9a5ad78-ffcc-4191-a0f2-0e290d6c0364', 'Auch du hast Bedürfnisse 🥗', 'Geht dir langsam die Energie aus? Bereite dir mit unseren gesunden Rezepten für Frauen einen vitaminreichen Smoothie zu. Du musst bei Kräften bleiben!'),
  ('d0842140-92ca-41c9-be61-ea76700b043c', 'Unvergessliche Erinnerungen 🖼️', 'Lade die schönsten Fotos deines Babys ins Babyalbum hoch und bewahre sie dort sicher auf – damit ihr später gemeinsam über diese süßen Momente lachen könnt.'),
  ('4a60c9b7-f5e6-41f9-ba8e-fc0fbecf8b3e', 'Wie hast du dich heute gefühlt? 💖', 'Auch wenn du sehr müde bist, ist alles vergessen, sobald du den Duft deines Babys einatmest, oder? Halte deine heutigen Gefühle im Stimmungstagebuch fest und gönn dir etwas Ruhe.'),
  ('965bee4a-5d90-4c53-aa89-40a47df609d3', 'Mahlzeiten mit Timer ⏱️', 'Sitzt dein Kind zu lange am Esstisch? Starte den Ernährungstimer, achte auf eine angemessene Essensdauer und beuge Appetitlosigkeit vor.'),
  ('83a23b90-6573-48f0-bd8e-9924821c611c', 'Achte auf dich 🥗', 'Bist du erschöpft vom Hinterherlaufen? Entdecke bei den gesunden Rezepten für Frauen einen köstlichen Salat, der dir sofort neue Energie schenkt.'),
  ('e949f663-9f46-4fb4-8e24-07f0556f19ea', 'Morgendliche Sauberkeit 🧻', 'Wie lief der erste Windelwechsel des Tages? Trage die Ausscheidungsdaten in die App ein und behalte so ganz einfach die Verdauung deines Babys im Blick.'),
  ('23c1e329-cee4-4d43-89e7-04f3883f2a24', 'Eine Extraportion Vitamine 🥦', 'Überprüfe mit dem Ernährungstracker den heutigen Speiseplan. In den Babyrezepten warten farbenfrohe Mahlzeiten auf dich, die fehlende Vitamine liefern!'),
  ('2450b85b-f956-4dd3-b9ad-11b269818238', 'Ganz schön trotzig? 🤖', 'Sagt dein Kind ständig Nein? Hol dir von unserem Anacan AI-Assistenten wissenschaftlich fundierte psychologische Tipps, um die Trotzanfälle deines 17.5 Monate alten Kindes besser zu meistern.'),
  ('91b9e4eb-ca6a-4a90-94bc-2abf486852f9', 'Ein Abend voller Ruhe 🌊', 'Zeit, eine ruhige Atmosphäre im Zimmer zu schaffen. Spiele unter den Weißen Geräuschen das Rauschen der Meereswellen ab und hilf dem Nervensystem deines Babys, in einen tiefen Schlaf zu finden.'),
  ('60f75637-7bb2-4f09-8e04-1616cc3f6b3a', 'Geduldsprobe am Esstisch ⏱️', 'Ziehen sich die Mahlzeiten zu lange hin? Starte den Ernährungstimer, halte die empfohlene Dauer ein und analysiere zugleich die Ursachen für den fehlenden Appetit.'),
  ('8773c2dd-9938-4a61-a038-72940b1c0339', 'Deine tägliche Auszeit 📝', 'Muttersein ist manchmal eine emotionale Achterbahnfahrt. Öffne das Stimmungstagebuch, schreibe dir die heutige Erschöpfung von der Seele und fühl dich leichter.'),
  ('da198266-6b56-4801-ac35-87e201ed0cda', 'Zeit für einen Kaffee ☕', 'Fällt dir zu Hause die Decke auf den Kopf? Finde unter den kinderfreundlichen Orten ein Café, das du entspannt mit deinem Kind besuchen kannst, und gönn dir eine schöne Auszeit.'),
  ('dd84435f-c5e3-4339-9062-61f9c8648898', 'Befolgt einfache Aufforderungen 🧸', 'Holt dein Baby die Schuhe tatsächlich, wenn du es darum bittest? Sein Wortschatz und Sprachverständnis entwickeln sich gerade rasant! Beziehe es noch mehr in Spiele ein.'),
  ('52450380-67b2-4414-9193-af2b18f7264a', 'Sei stolz auf dich 👏', 'Schau nicht auf das unordentliche Zimmer, sondern darauf, wie glücklich dein Kind heute war. Du bist eine großartige Mama – besser, als es dir jedes Buch beibringen könnte.'),
  ('c0292e27-64a9-4ecc-95f9-37e4ccbb6b7d', 'Schlafanalyse mit Timer ⏱️', 'Wird der Tagesschlaf kürzer? Starte den Schlaf-Timer, analysiere den Wochenverlauf und passe die Schlafenszeit am Abend entsprechend an.'),
  ('fda065c2-2893-4c1e-858b-19c095a29529', 'Unterstützt euch gegenseitig! 💖', 'Setzt euch nach einem anstrengenden Tag zusammen und sprecht offen darüber, was euch beschäftigt. Gegenseitige Unterstützung halbiert die Last.'),
  ('5d7b0b3c-0707-4aa1-9c33-a30f5f43c63b', 'Appetit am Mittag 🥣', 'Hat dein Kind heute genug Eiweiß gegessen? Trage die Mahlzeiten in den Ernährungstracker ein und vergewissere dich, dass der Tagesbedarf gedeckt ist.'),
  ('815e2a58-ed5b-46c4-bdc7-5775cc6d2d5b', 'Entwicklungsschub 🧠', 'Was passiert gerade im Gehirn deines Babys? Lies im Blog den neuesten Artikel über die kognitive Entwicklung von Kindern im Alter von 17–18 Monaten.'),
  ('87dc449d-a56d-419b-bdab-000fd5ed38fd', 'Schlafplan ⏱️', 'Haben sich die Wachzeiten verändert? Sieh dir die Statistiken des Schlaf-Timers an und analysiere genau das Verhältnis zwischen Tages- und Nachtschlaf.'),
  ('4c6d197d-5cde-42e9-b88b-05a62b37e397', 'Morgendlicher Bericht 💩', 'Die Verdauung ist einer der ersten Hinweise auf die Gesundheit. Trage beim Windelwechsel die Ausscheidungen in der App ein und verfolge die Veränderungen im Tagesverlauf.'),
  ('ff2d08b5-7a14-4db2-985e-1998a959811b', 'Spiele am Morgen 🧩', 'Gemeinsam lernen! Lies unbedingt unseren Beitrag im Bereich „Blogs“ über Spiele, die die geistige Entwicklung von 17.5 Monate alten Kindern fördern.'),
  ('276fc8e9-ee3f-4392-a41a-de859475f6f7', 'Eine „Ich hab dich lieb“-Umarmung 🫂', 'Kommt dein Kind plötzlich zu dir, umarmt dich oder streichelt dein Gesicht? Es zeigt seine Liebe jetzt auch durch körperliche Nähe. Genieße diesen Moment.'),
  ('6d6ea5dd-3811-42ae-a92c-4f0473fafb88', 'Trost von Papa 🫂', 'Wechselt euch beim nächtlichen Aufstehen ab: Einmal stehst du auf, das nächste Mal dein Partner. Teilt euch die Belastung als Team genau zur Hälfte.'),
  ('87b2db95-d589-400c-8cce-c78da82f0fee', 'Verdacht auf eine Allergie 🤖', 'Du hast ein neues Lebensmittel angeboten und Rötungen an den Wangen deines Babys bemerkt? Bevor du in Panik gerätst, erfährst du von Anacan AI, was als Erstes zu tun ist.'),
  ('85d64887-6099-4720-8a44-11c6766f10bb', 'Fällt dir zu Hause die Decke auf den Kopf?☕', 'Finde unter den mama-freundlichen Orten das nächstgelegene Café, in dem du frische Luft schnappen kannst und dein Baby Spaß hat.'),
  ('aa709e76-dc89-4447-b36a-69ce62fbdfe6', 'Dein Kind versteht deinen Tonfall 🗣️', 'Hält es inne und schaut dich an, wenn du mit ernster Stimme Nein sagst? Es versteht Emotionen und Verbote jetzt vollständig. Bleib konsequent bei deinen Grenzen.'),
  ('d09c606d-f7bf-4df1-900d-b7cc38d34313', 'Dimme das Licht 🌙', 'Schalte 1 Stunde vor dem Schlafengehen alle hellen Lichter und Bildschirme zu Hause aus. Melatonin wird nur in einer ruhigen Umgebung ausgeschüttet.'),
  ('7c968d48-84d9-4e6e-9f71-708f424d13fc', 'Empfohlene Schlafdauer ⏱️', 'Zeit fürs Bett! Aktiviere den Schlaf-Timer. Analysiere den Verlauf, um sicherzustellen, dass dein Kind seine tägliche empfohlene Schlafdauer erreicht.'),
  ('317a6a9f-9ea0-4356-ac6b-713b806d7195', 'Süße Erinnerungen 📸', 'Halte die lustigste Aktion deines Babys heute im Babyalbum fest. In ein paar Jahren werdet ihr beim Durchblättern dieser Aufnahmen herzlich lachen.'),
  ('c56a5aef-ad55-4a58-b85d-04ee040e2457', 'Auslaufsicherer Trinkbecher 🥤', 'Dein Kind trinkt beim Herumlaufen gern Wasser, schüttet sich dabei aber voll? Entdecke unter „Empfohlene Produkte“ die praktischsten Trinkbecher, die von Müttern ausgewählt wurden.'),
  ('e0699b25-a664-453e-b3a5-a31644bae458', 'Die Kleidung wird zu klein! 📏', 'Sind die Ärmel deines kleinen Schatzes schon wieder zu kurz? Trage die neuen Werte in den Gewichtstracker ein und verfolge stolz das Wachstum von Größe und Gewicht in der Entwicklungskurve.'),
  ('281783cf-f4b1-478b-9c23-4859307143e4', 'Zeit zum selbstständigen Spielen 🧸', 'Dein Kind kann sich jetzt schon 10-15 Minuten allein mit seinen Spielsachen beschäftigen. Das zeigt, dass seine Aufmerksamkeitsspanne wächst. Genieße die Ruhe.'),
  ('64f775c3-f09d-4993-a954-437681ccf730', 'Draußen ist das Wetter nicht eindeutig? ⛅', 'Das Wetter- und Kleidungstool zeigt dir sofort die Windgeschwindigkeit, die du vom Fenster aus nicht erkennen kannst, und empfiehlt das passende Outfit.'),
  ('6ca7a3a7-3202-4bdf-87de-b43d04388374', 'Zeit für eine Massage 💆‍♂️', 'Wenn euer Kind eingeschlafen ist, könnt ihr euch gegenseitig die Schultern massieren und so gemeinsam den Stress des Tages loslassen. Ihr seid ein Team!'),
  ('0c27441c-12ef-47a7-9dc7-2b5ead6dd4a7', 'Die Lautstärke im Blick 🤫', 'Die erste halbe Stunde nach dem Einschlafen ist besonders empfindlich. Überprüfe die Umgebung mit dem Schallpegelmesser und vermeide plötzliche laute Geräusche.'),
  ('cee8912e-bf87-4d52-b0d0-309e7583f3e5', 'Schneller Kinderarzt 🤖', 'Machst du dir Sorgen um die Sprachentwicklung deines 18 Monate alten Kindes? Frag Anacan AI und erfahre, welche Wörter in diesem Alter üblich sind.'),
  ('91d67474-6689-4302-b69e-a9b260aedef7', 'Das richtige Spielzeug 🧩', 'Du suchst ein Spielzeug, das das logische Denken fördert? Entdecke im Bereich „Empfohlene Produkte“ altersgerechte und pädagogisch wertvolle Puzzles.'),
  ('c5a6eac8-e59c-4b94-98cf-eb7be52db9a2', 'Abendroutine 🌙', 'Wenn du dein Baby jeden Tag zur gleichen Zeit schlafen legst, entwickelt es eine feste Gewohnheit. Aktiviere den Schlaf-Timer, überprüfe seinen Schlafbedarf und freue dich über entspanntes Einschlafen.'),
  ('e8b020dc-c4fe-4f5b-946a-28ae84382a39', 'Gesundes Wachstum 📈', 'Bis zum 18. Monat ist es nicht mehr lange! Analysiere die Entwicklung im Gewichts-Tracker und überprüfe, ob Größe und Gewicht im Normbereich liegen.'),
  ('ab02b4ce-b2c3-41bc-a1aa-f97787c0ba17', 'Der perfekte Tagesabschluss 🖼️', 'Halte diesen besonderen Tag (540 Tage!) für immer fest: Füge euer fröhlichstes und liebevollstes gemeinsames Foto dem Babyalbum hinzu.'),
  ('c1dc4453-41a2-40e6-812c-73fb934ccc70', 'Du bist eine Heldin! ✨', 'Heute ist der 540. Tag deiner Reise als Mutter! Erzähle Anacan AI von deinem heutigen Erfolg und erhalte eine persönliche Motivation, die deinen Tag noch schöner macht.'),
  ('fa1d5820-5e14-435d-81d1-df116bd7de6f', 'Gemeinsam am Familientisch 🍲', 'Dein Baby kann jetzt schon die gleichen Gerichte essen wie ihr. Mit dem Ernährungstracker kannst du den Nährwert eurer gemeinsamen Mahlzeiten ganz einfach berechnen.'),
  ('ae531928-8e01-4e71-961a-63a517eaee5a', 'Sanft in den Tiefschlaf 🌙', 'Aktiviere den Schlaf-Timer. Wenn dein Baby nachts häufiger aufwacht, kannst du sein Nervensystem mit Meeresrauschen aus den Weißen Geräuschen beruhigen.'),
  ('bacdcc71-8211-4dd5-b3af-c5af34fb468a', 'Morgendliche Überraschung 💩', 'Halte den ersten Windelwechsel des Tages fest! So kannst du die Verdauung und Flüssigkeitsaufnahme deines heranwachsenden Babys optimal im Blick behalten.'),
  ('e59af63b-a407-459e-a6f1-a0263d9f74f5', 'Kleiner Stern 🌟', 'Lass dir dieses süße Lächeln nicht entgehen! Halte die heutige Stimmung deines Babys mit den kreativen Themen im Baby-Fotoshooting-Tool für immer fest.'),
  ('f71b2bf0-976d-4844-8538-db17781ce999', 'Nimm dir Zeit für dich 🍵', 'Dein Kind schläft – jetzt bist du an der Reihe, deinem Körper Erholung zu gönnen. Such dir bei den gesunden Rezepten einen beruhigenden Kräutertee aus und brüh ihn auf.'),
  ('4f770f32-235d-4481-acc9-8a3353f11910', 'Was beschäftigt dich? 🤔', 'Lehnt dein Baby plötzlich das Essen ab? Stell Anacan AI alle deine Fragen rund ums Muttersein und erhalte sofort eine fachlich fundierte Antwort.'),
  ('996b9423-cc50-4ec2-bbf6-02866083bb10', 'Sanft einschlafen 🎶', 'Kann dein Baby nach einem Tag voller Entdeckungen nicht einschlafen? Wähle unter Weißes Rauschen ein Schlaflied aus und schaffe eine zauberhaft ruhige Atmosphäre im Zimmer.'),
  ('9d8ea18e-9c4f-4f0b-9883-a708f0ed884b', 'Die Natur entdecken 🍂', 'Frische Luft tut euch beiden gut. Entdecke unter den mama-freundlichen Orten einen neuen Park und lass dein Kind nach Herzenslust herumtoben und seine Energie loswerden.'),
  ('19f1aa58-50a6-4acf-b375-1d03850cfcb6', 'Deine innere Stimme 💖', 'Du musst keine perfekte Mutter sein – für dein Kind bist du die Beste. Schreib deine heutigen Gefühle in dein Stimmungstagebuch und lass los, was dich beschäftigt.'),
  ('6cc2d53f-bf34-4dcd-9edd-bf3d05a35b98', 'Selbstständig essen üben ⏱️', 'Versucht dein Kind, selbstständig zu essen? Sieh über das Chaos hinweg! Starte den Essens-Timer und beobachte, wie lange es dafür braucht.'),
  ('f869363f-52a1-4240-a759-b2b999d347e4', 'Gesunde Leckerei 🍪', 'Süßigkeiten aus dem Supermarkt sind nicht nötig. Bereite mit den Rezepten für Babys im Beikostalter einfache, zuckerfreie und leckere Kekse zu.'),
  ('e207d666-c361-4203-8076-7ba835d4f015', 'Legt dein Baby den Löffel gar nicht mehr aus der Hand? 🥄', 'Aktiviere den Ernährungstimer. Analysiere, wie lange die Versuche dauern, selbstständig zu essen, und überprüfe die tägliche Nahrungsmenge.'),
  ('35587de2-b62b-435c-aca4-01e72314423a', 'Schreib dir alles von der Seele 📝', 'Nicht jeder Tag ist perfekt – und das ist völlig normal. Schreib deine heutigen Gefühle in dein Stimmungstagebuch, lass den Stress los und gönn dir etwas Ruhe.'),
  ('6dca6700-52a0-4818-812b-80dcc5c42de9', 'Jetzt ganz offiziell 1.5 Jahre alt! 🎈', 'Dein Kind wächst in diesen Monaten besonders schnell. Trag die neuesten Werte in den Entwicklungs-Tracker ein und wirf voller Stolz einen Blick auf die Entwicklungskurve.'),
  ('da88924f-9b7a-4cc5-9b9e-429e9d903edd', 'Belohne dich selbst ☕', '18 Monate Mama sein ist alles andere als einfach! Finde auf unserer Karte mit mama- und kinderfreundlichen Orten ein gemütliches Café und gönn dir einen heißen Kaffee.'),
  ('6b77a02d-8882-4aed-be91-5f8ce3841671', 'Bereit für die ersten Sprints? 👟', 'Für die ersten sicheren Laufschritte sind die richtigen Schuhe unverzichtbar! Entdecke unter den empfohlenen Produkten die orthopädischen Modelle, die bei Mamas besonders beliebt sind.'),
  ('d6d681fb-3d1d-40b8-84c0-e3cd64921f6e', 'Zuckersüße Momente 📸', 'Dein Baby fällt beim Laufen hin und lacht dabei? Füge diesen süßen Moment gleich dem Babyalbum hinzu und mach ihn zu einer farbenfrohen Erinnerung fürs Leben.'),
  ('e2aefd08-9263-41a3-87d4-c2d0378c7526', 'Wie steht es um die Eisenversorgung? 🥩', 'Überprüfe mit dem Ernährungstracker, ob dein Baby heute genügend Eisen aufgenommen hat. Falls nicht, sieh dir die Babyrezepte an.'),
  ('48983c78-1769-4320-a7cf-ba470eef1415', 'Ein ganz persönliches Märchen 🪄', 'Erstelle mit den intelligenten Märchen eine besondere Geschichte, in der dein Kind die Hauptrolle spielt: die Abenteuer eines 1.5-jährigen Entdeckers.'),
  ('1bf2c33f-3711-4208-8da6-0a931502b566', 'Völlige Dunkelheit 🌙', 'Dein Baby wehrt sich gegen das Einschlafen? Selbst ein kleines Licht im Zimmer kann es ablenken. Schalte alle Bildschirme aus und verdunkle den Raum vollständig, um die Melatoninausschüttung anzuregen.'),
  ('5f000b16-6031-438b-92a6-3ea1d69ae68b', 'Hat dich dein Gedächtnis schon wieder im Stich gelassen? 🛒', 'Sind die Windeln oder der Joghurt ausgegangen? Zerbrich dir nicht den Kopf – setze es sofort auf die Einkaufsliste, damit dein Partner es auf dem Heimweg von der Arbeit mitbringen kann.'),
  ('8593e3b3-5794-49a0-a5ef-d04af1bd53a7', 'Details in Büchern 📖', 'Blättert dein Baby im Buch und zeigt mit dem Finger auf kleinste Details im Bild, zum Beispiel auf einen kleinen Vogel? Halte diese kognitive Aufmerksamkeit im Entwicklungstracker fest. Sein visuelles Gedächtnis funktioniert hervorragend!'),
  ('5df90283-8938-4f2c-bc5d-95fad0d0249f', 'Überprüfen wir den Schlafrhythmus ⏱️', 'Dein Baby möchte abends nicht schlafen? Analysiere die Übersicht des Schlaf-Timers. Vielleicht sollte der Tagschlaf etwas kürzer ausfallen.'),
  ('eb685812-a20b-4dfa-8dcd-a8c0865f1a25', 'Mamas Energie 🔋', 'Vergiss dich selbst nicht! Wähle aus den Rezepten eine köstliche, proteinreiche Mahlzeit, die sich morgens schnell zubereiten lässt.'),
  ('f80fa225-e7f6-4b7d-a7da-b651f5688ba0', '„Nein!“-Krisen 🛑', 'Dein Kind widerspricht bei allem? Sprich mit unserem Anacan AI-Assistenten über die Trotzphase mit 1.5 Jahren und erhalte psychologische Unterstützung sowie hilfreiche Lösungsansätze.'),
  ('bd224607-0812-4b81-8b5d-af59d7d7cc10', 'Vitaminbombe 🥗', 'Mamas Energie darf nicht ausgehen! Bereite aus unseren gesunden Rezepten für Frauen einen leckeren Smoothie zu, der dir sofort neue Energie gibt.'),
  ('c9435c7a-e56d-449f-9eb8-fae0dc263176', 'Einschlafritual 🌙', 'Starte den Schlaf-Timer und verdunkle das Zimmer. Analysiere die Übersicht und gewöhne dein Baby ganz einfach daran, jeden Abend zur gleichen Zeit schlafen zu gehen.'),
  ('9815225a-8bb2-4fd7-93dd-34bcbbda8ac0', 'Weiter geht das Wachstum! 🌟', 'Dein Baby ist jetzt schon über 18 Monate alt! Eine neue Phase beginnt – mit einem selbstständig laufenden Kind, das seine Gefühle zeigt, eigensinnig, aber zugleich unglaublich liebevoll ist!'),
  ('cdca9fee-71e1-4e46-aea7-41734d6fa68a', 'Schlafregression mit 18 Monaten? 🥱', 'Wehrt sich dein Kind gegen das Einschlafen oder wacht es nachts auf? Das ist die bekannte Schlafregression in diesem Alter. Frage Anacan AI nach wissenschaftlich fundierten Informationen zu diesem biologischen Prozess.'),
  ('be8b4ec7-a61e-4f60-ae12-bdc8b7beda03', 'Die „Selber machen!“-Phase 🛑', 'Dein Kind möchte alles selbst nehmen – sogar gefährliche Gegenstände. Stell dich auf einen heftigen Gefühlsausbruch ein, wenn du ihm etwas wegnimmst. Statt es nur zu verbieten, kannst du versuchen, seine Aufmerksamkeit auf etwas Interessanteres zu lenken.'),
  ('d6508b29-e914-4995-93c3-58c73e271159', 'Massage und Ruhe 💆‍♀️', 'Tut dir vom vielen Hinterherlaufen schon der Rücken weh? Bitte deinen Partner nach dem Einschlafen des Kindes um eine 10-minütige Schultermassage. Du hast es verdient!'),
  ('dd068a2e-5d54-49f1-be6d-02db7c690974', 'Du bist auf der Laufstrecke 🏃‍♂️', 'Flitzt dein Kind unermüdlich von Zimmer zu Zimmer? In dieser Phase entwickelt sich sein Gleichgewicht beim Stehen und Laufen vollständig. Räume kleine Gefahrenquellen zu Hause weg und genieße es, diese energiegeladenen Momente zu beobachten.'),
  ('d14775e1-8a41-4689-87c3-351bcaa01c87', 'Papas Spielplatz 👨‍👧', 'Ist deine Geduld am Ende? Mach die Zimmertür zu und lass das Kind mit seinem Papa allein. Heute Abend darf er den heimischen Spielplatz leiten.'),
  ('e1121d1f-a680-4fb9-9a1f-6792cb16e172', 'Obstverweigerung 🍎', 'Wirft dein Kind den Apfel, den es gestern noch geliebt hat, heute auf den Boden? Wählerisches Essverhalten ist eines der typischsten Probleme in diesem Alter. Statt dich im Internet zu verlieren, findest du unter „Gesunde Rezepte“ kreative Ideen, um Obst spielerisch anzurichten.'),
  ('ef76ecee-5471-407a-a72c-9593be1406af', 'Der Redefluss nimmt kein Ende 🗣️', 'Erzählt dein Kind gleich nach dem Aufwachen ausgiebig etwas in seiner eigenen Sprache? Sein Sprachzentrum macht gerade einen gewaltigen Entwicklungssprung. Hör ihm ganz ernsthaft zu und antworte: „Wirklich?“ oder „Und was ist dann passiert?“'),
  ('ffe1377d-426e-4c3f-a06d-3551b2ee446b', 'Intelligenzspielzeug 🧩', 'Mit 18 Monaten ist die ideale Zeit für Denkspiele. Entdecke unter „Empfohlene Produkte“ altersgerechte Puzzles und Bauklötze, um die geistigen Fähigkeiten deines Babys zu fördern.'),
  ('10d89b1a-052c-42d7-9604-a8aa080e3159', 'Gemeinsame Familienmahlzeiten 🍲', 'Dein Baby kann jetzt schon ganz normal mit euch mitessen! Wähle unter „Rezepte“ ein gesundes Abendessen für die ganze Familie aus, das auch für Babys nach Beginn der Beikost geeignet ist.'),
  ('25077620-39e7-49c9-abd7-7ee3d4c9f4a5', 'Verdauung im Blick ⏱️', 'Trage die Veränderungen im Laufe des Tages in den Windel-Tracker ein. So kannst du leicht beurteilen, ob dein Baby genügend Flüssigkeit und Ballaststoffe bekommt.'),
  ('94fb4891-ca2e-4e41-b663-ea23a832df89', 'Beruhigendes Regengeräusch 🌧️', 'Ein aktiver Tag kann das Gehirn ermüden. Spiele unter „Weißes Rauschen“ Regengeräusche ab und schaffe im Zimmer eine beruhigende, einschlaffördernde Atmosphäre.'),
  ('02d8aef9-6d63-4748-9f41-c063ee842eb2', 'Du schaffst das! 💖', 'Wenn du dich erschöpft fühlst, öffne das Stimmungstagebuch. Schreibe dort einfach „Ich schaffe das alles“ hinein und gönn dir eine Pause.'),
  ('04fca8dd-97bb-4af2-93b5-030f318cd3da', 'Die Natur entdecken 🌳', 'Wird es deinem Baby zu Hause zu eng? Finde unter „Mama-freundliche Orte“ einen weitläufigen, sicheren Park, in dem es sich austoben kann.'),
  ('7306940e-101e-4de4-af72-da4ab6736ad8', 'Mahlzeiten-Timer ⏱️', 'Spielt dein Baby zu viel mit dem Essen? Starte den Ernährungs-Timer, um zu prüfen, ob die Zeit am Tisch angemessen ist, und seinen Appetit einzuschätzen.'),
  ('07b5d33a-c674-4dcc-a023-81e3746cb054', 'Denkspiele 🧱', 'Stapelt dein Baby 4-5 Bauklötze zu einem Turm? Halte diesen motorischen Meilenstein im Entwicklungs-Tracker fest! Vergiss nicht, seine kleinen Bauversuche zu feiern.'),
  ('be5acfb3-03f0-4bea-9e14-40b38bca8262', 'Papas Nachtschicht 👨‍🍼', 'Bewältige das nächtliche Aufwachen nicht ganz allein. Wecke auch deinen Partner – als Team teilt ihr die Verantwortung. Heute Nacht ist er mit dem Beruhigen dran.'),
  ('fa9c7680-afc6-4095-9ec3-d56ad432d989', 'Park oder Zuhause? ⛅', 'Du möchtest raus, aber das Wetter ist wechselhaft. Der Wetter- und Kleidungsassistent zeigt dir nicht nur die Temperatur, sondern empfiehlt dir auch windfeste Kleidung für dein Baby.'),
  ('b62665c0-5b12-4c5d-adfa-7b34000204cf', 'Fröhliches Lachen 📸', 'Erinnere dich an den süßen Moment, der dich heute am meisten zum Lachen gebracht hat, und halte ihn unbedingt mit einem kurzen Video oder Foto im Babyalbum fest.'),
  ('e16b58bb-af8f-43a3-bf1f-c1d132a221a5', 'Keine Panik 🤖', 'Ist dir ein ungewöhnliches Verhalten bei deinem Kind aufgefallen? Warte nicht bis zum Abend, sondern schreibe sofort an Anacan AI und kläre deine Sorge.'),
  ('ec3f1a4d-28dd-4a4a-9b91-b595f96327d4', 'Kalziumbedarf 🦷', 'Berechne mit dem Ernährungstracker, wie viel Kalzium dein Kind heute aufgenommen hat. Achte auf eine ausreichende Menge an Milchprodukten für starke Knochen und Zähne.'),
  ('72bb2391-6fc4-4ef8-9352-3ae963d61f5b', 'Jetzt bist du dran 🥗', 'Dein Kind schläft? Dann ab in die Küche! Entdecke bei den gesunden Rezepten für Frauen einen proteinreichen Salat, der dir sofort neue Energie gibt.'),
  ('7c893844-8335-47b4-baf7-b21329be4554', 'Schreib dir alles von der Seele 📝', 'War dein Tag besonders turbulent? Wenn du deine Gefühle im Stimmungstagebuch festhältst, kannst du deinen Kopf entlasten.'),
  ('fa6aaf54-9d2b-4b0c-a7b0-543d93bdc90a', 'Schon wieder aus der Kleidung herausgewachsen? 📏', 'Ab dem 18. Monat ist ein Wachstumsschub zu erwarten. Trage die neuen Werte in den Gewichts-Tracker ein und betrachte stolz die Entwicklungskurve.'),
  ('ee049a04-c690-49d6-a1c7-d2c603be49d5', 'Mit einem Märchen einschlafen 🪄', 'Erstelle unter „Intelligente Märchen“ eine ganz besondere Geschichte. Lies sie deinem Kind vor.'),
  ('46fbf80f-0604-494d-b68e-60f85488090d', 'Es isst ganz allein! 🥣', 'Will dein Kind den Löffel gar nicht mehr hergeben? Starte den Ernährungstimer, um die Dauer der Mahlzeit zu verfolgen und zu prüfen, ob die empfohlene Menge eingehalten wird.'),
  ('5174db8a-22d1-41db-af86-5a575522337a', 'Die ersten Bilder 🖍️', 'Hat dein Kind mit dem Kritzeln begonnen? Entdecke im Bereich „Empfohlene Produkte“ die besten ungiftigen und abwaschbaren Farben.'),
  ('5e9337e9-36e0-44d6-9ecf-c3265d3eca6b', 'Kleines Künstlerkind 📸', 'Ist dein Kind von Kopf bis Fuß mit Farbe bekleckert? Statt dich zu ärgern, kannst du diesen lustigen Moment mit den fröhlichen Rahmen im Baby-Fotoshooting verewigen.'),
  ('2d802010-e9c4-4370-b595-862f19214f3d', 'Eine Extraportion Kalzium 🧀', 'Kalzium ist für Zähne und Knochen unverzichtbar. Prüfe mit der Ernährungskontrolle, ob dein Kind heute die empfohlene Menge an Milchprodukten bekommen hat.'),
  ('739069ab-a4c7-4cc9-ae84-572e67836bd2', 'Der süßeste Moment des Tages 🖼️', 'Erinnerst du dich an die kleine Geste, die dich heute am meisten zum Lachen gebracht hat? Lade sie gleich ins Babyalbum hoch und bewahre sie für die Zukunft auf.'),
  ('faac9718-e68e-455d-90e4-e34b7b38a24e', 'Geistige Entwicklung 🧠', 'Lies im Blog unbedingt den neuen Artikel über die erstaunlichen Prozesse, die im Gehirn von 1.5-jährigen Kindern ablaufen.'),
  ('2155f722-dd8c-49ec-a515-ecee85476474', 'Der morgendliche Check 🧻', 'Hast du die erste Windel des Tages in der App erfasst? Farbe und Konsistenz der Ausscheidungen zeigen zuverlässig, ob dein Kind genügend Flüssigkeit bekommt.'),
  ('22efa7bf-186e-41c7-b46c-b75ce17b0a09', 'Morgendliche Pflege 💧', 'Hast du die erste Windel des Tages gewechselt? Trage die Ausscheidungen in der App ein und überprüfe ganz einfach, ob dein Baby genügend Flüssigkeit bekommt.'),
  ('37e7b0b1-141f-488d-99c8-a87bde73955f', 'Krise am Esstisch 🥣', 'Dein Baby verweigert das Essen? Statt es zum Essen zu zwingen, kannst du mit verschiedenfarbigem Gemüse auf dem Teller sein Interesse wecken. Entdecke neue Ideen in unseren gesunden Rezepten.'),
  ('5ae1647c-ec81-4db7-838c-66f57619dd06', 'Geräuschpegel im Blick 🤫', 'Sorge beim Einschlafen mit dem Schallpegelmesser für eine angenehme Lautstärke im Zimmer. Unterbrochener Nachtschlaf beeinträchtigt sowohl die Entwicklung deines Babys als auch deine Stimmung am Morgen.'),
  ('2e177a88-e995-4df3-ae19-8a1044979006', 'Musikalische Abende 🎶', 'Wenn dein Baby am späten Nachmittag quengelig wird, hilft oft am besten: sein Lieblingslied einschalten, es in den Arm nehmen und gemeinsam tanzen.'),
  ('82b5cb21-ea7e-4957-9166-81471c0b098a', 'Warum macht mein Baby das? 🤖', 'Hat dein Baby plötzlich scheinbar grundlose Wutanfälle (Tantrums)? Lass dich direkt von Anacan AI beraten und lerne psychologisch fundierte Lösungsansätze kennen.'),
  ('8aa141ab-420e-4a45-9eba-7dddd2430cb1', 'Energie ohne Zucker 🍌', 'Dein Baby möchte nachmittags etwas Süßes? Entdecke in den Babyrezepten gesunde Snacks mit Banane und Hafer und achte so auf eine ausgewogene Ernährung.'),
  ('284e490f-ef18-407e-b320-432395edf56f', 'Die Einkaufsliste wird immer länger 🛒', 'Shampoo, Windeln oder Haferflocken sind aufgebraucht? Du musst dir nicht alles merken: Trage es in die Einkaufsliste ein und synchronisiere sie mit deinem Partner.'),
  ('91cfb4b2-1e2c-4e02-8b77-867d550b9fcd', 'Zeit, rauszugehen ☕', 'Du brauchst eine Abwechslung vom Alltag? Finde unter den mama-freundlichen Orten ein Café mit Kinderecke und genieße einen heißen Kaffee.'),
  ('1e433a5c-ee68-4089-bf86-5ce74fde7136', 'Logikspielzeug 🧩', 'Mit 18.5 Monaten ist die ideale Zeit für Logikspiele. Entdecke unter „Empfohlene Produkte“ altersgerechte Puzzles und Bauklötze.'),
  ('9d69d283-cfae-47a2-a874-8fabcc20a7f1', 'Wachstumstempo 📈', 'Analysiere das Entwicklungstempo im Entwicklungs-Tracker. Verfolge anhand der Grafik, ob Größe und Gewicht im Normbereich liegen.'),
  ('a242b14e-b434-493a-ab87-b2064aedfc9e', 'Ein echter Abenteurer 📸', 'Füge das fröhlichste Foto, das du beim Klettern oder Herumtoben aufgenommen hast, dem Babyalbum hinzu und halte diesen Moment als Erinnerung fest.'),
  ('465d0258-9df5-4a0a-9902-79a09218dcc5', 'GENAU 19 MONATE! 🎂', 'Herzlichen Glückwunsch! Seit der Geburt sind genau 19 Monate vergangen! Wähle jetzt beim Baby-Fotoshooting einen besonderen Sticker aus und teile diese Freude in der Anacan-Community!'),
  ('913b583d-e8e0-426f-a7cd-75ab8b1bc0b4', 'Fröhliches Kinderlachen 📸', 'Füge das fröhlichste Foto, das du beim Klettern oder Herumtoben aufgenommen hast, dem Babyalbum hinzu und lass die Müdigkeit des Tages einem Lächeln weichen.'),
  ('ccbbf1c0-789d-4a84-96bd-cdb04c618d13', 'Behalten wir das Wachstum im Blick 📈', 'Die körperliche Aktivität hat zugenommen. Aber liegt die Gewichtszunahme im Normbereich? Analysiere das Entwicklungstempo mit dem Gewichts-Tracker und lass deine Sorgen hinter dir.'),
  ('0671a41f-8a24-4dff-87f0-008aa3abfc3d', 'Wie geht es der Verdauung? 💩', 'Trage beim Windelwechsel den Stuhlgang in der App ein. So kannst du leicht verfolgen, wie sich ballaststoffreiche Lebensmittel im Laufe des Tages auf die Verdauung auswirken.'),
  ('d414aad6-2d3e-4a62-a555-9241874e68b3', 'Schlafrhythmus ⏱️', 'Zeit fürs Bett! Starte den Schlaf-Timer und analysiere den Schlafrhythmus, um sicherzustellen, dass dein Baby täglich genug schläft.'),
  ('67ef78f2-7b35-47be-a6f4-6368c3a37a84', 'Esstisch-Challenge ⏱️', 'Sitzt dein Kind lange am Tisch und spielt mit dem Essen? Starte den Ernährungstimer und analysiere die möglichen Ursachen für seine Appetitlosigkeit.'),
  ('d9b69a33-09da-4d7d-98e9-ac3acd553715', 'Schlafregression? 🤖', 'Wacht dein Kind nachts häufig auf? Schreib dem Anacan-KI-Experten und finde sofort heraus, ob ein Wachstumsschub dahintersteckt.'),
  ('283507fe-ca12-4764-a828-61d9a9f30424', 'Du bist eine Heldin 💖', 'Du musst nicht perfekt sein. Schreib einfach „Ich schaffe das alles“ in dein Stimmungstagebuch und gönn dir eine Pause.'),
  ('290e0f59-3a24-4f74-9a01-c478f55efce5', 'Entdeckungstour an der frischen Luft 🌳', 'Zu Hause wird es deinem Kind langsam zu eng. Finde unter den mama-freundlichen Orten einen großen, sicheren Park, in dem es sich richtig austoben kann.'),
  ('d9528425-30f7-4a4a-ac0d-053206658d00', 'Damit dir die Energie nicht ausgeht 🔋', 'Bist du vom vielen Hinterherlaufen völlig erschöpft? Wähle aus den gesunden Rezepten für Frauen ein köstliches Frühstück, das dir sofort neue Energie gibt.'),
  ('0867f1c5-1a97-47ac-ba01-ac80c4c73f6b', 'Mittagsschlaf ⏱️', 'Aktiviere den Schlaftimer. Erfasse die Schlafenszeiten tagsüber genauer und gestalte so den Übergang zum Nachtschlaf leichter.'),
  ('1b9ea296-6f6b-4447-9f45-4c6548d5e543', 'Gemeinsame Familienmahlzeit 🍲', 'Dein Kind kann jetzt schon dasselbe essen wie ihr. Mit dem Ernährungstracker kannst du den Nährwert eurer gemeinsamen Mahlzeiten ganz einfach berechnen.'),
  ('f9ac9f1e-0a4a-473c-909e-2a7e500a27b0', 'Beruhigendes Meeresrauschen 🌊', 'Kann dein Kind nach einem Tag voller Entdeckungen nicht einschlafen? Wähle bei den Weißen Geräuschen das Meeresrauschen aus und schaffe eine zauberhafte Ruhe im Zimmer.'),
  ('fbbb1355-d1ac-4efe-b9c7-1746b97b1656', 'Will es nicht teilen? 🤖', 'Dein Kind will sein Spielzeug im Park nicht teilen und schreit? Finde mit Anacan AI heraus, wie du in dieser Situation reagieren kannst, und setze die Tipps direkt um.'),
  ('7616cbf9-cf9d-45e8-86a1-eb74cb13ae1e', 'Morgendliche Überraschung 💩', 'Hast du die erste Windel des Tages gewechselt? Trage die Ausscheidungsdaten in die App ein, um die Verdauung und Flüssigkeitsaufnahme deines Babys genau im Blick zu behalten.'),
  ('b32e8863-be99-483a-aff4-94fc82f554bc', 'Der Schlaftimer läuft! ⏱️', 'Die Abendroutine beginnt. Starte den Timer und analysiere ganz einfach, wie ein aktiver Tag die Einschlafzeit beeinflusst.'),
  ('f0fc96ac-776c-4e66-bacf-461eff128cbc', 'Bunte Teller 🥦', 'Dein Baby mag kein Gemüse? Wenn es gerade mit Beikost beginnt, findest du unter Rezepte kreative Ideen zum Anrichten. So erreicht ihr die empfohlene Menge im Ernährungs-Tracker auf spielerische Weise.'),
  ('4673b81e-675b-4232-a5ca-c06aa26d504d', 'Energie für Mama 🔋', 'Hat dir der ganze Trubel die letzte Energie geraubt? Vergiss dich selbst nicht! Bereite dir mit den gesunden Rezepten einen proteinreichen Smoothie zu, der dir sofort neue Kraft gibt.'),
  ('7a2ab463-526e-46c6-a246-3494b6c46fa9', 'Ein schwieriger Morgen? 🌪️', 'Trotzanfälle können anstrengend sein. Atme tief durch und frage Anacan AI direkt, wie du in dieser Situation reagieren kannst.'),
  ('c995af30-30f9-4eaf-a66c-3d0d65fc825b', 'Hör auf deine innere Stimme 📝', 'Dein Kind schläft. Öffne jetzt dein Stimmungstagebuch und schreibe dir in den Zeilen, die niemand sonst lesen wird, deine heutigen Gefühle von der Seele.'),
  ('0aa2cefc-f18c-4c10-98d6-e4dfda22198e', 'Beruhigendes Rauschen 🌧️', 'Kann dein Baby nach einem Tag voller neuer Entdeckungen nicht einschlafen? Spiele unter Weißes Rauschen den Regensound ab, um sein Nervensystem auf natürliche Weise zu beruhigen.'),
  ('a57c041d-751b-4413-a98e-ee1564a86127', 'Frische Luft, jede Menge Energie 🌳', 'Fällt euch zu Hause die Decke auf den Kopf? Entdecke unter den mutterfreundlichen Orten einen neuen Park mit verschiedenen Spielgeräten, auf denen sich dein Baby richtig austoben kann.'),
  ('f3737052-fe7e-4f0c-9b36-7d082f7dbdfc', 'Entwicklungsschub 🧠', 'Was passiert im Gehirn eines 18.5 Monate alten Babys? Lies den neuesten Artikel im Blog und erfahre mehr über die einzelnen Entwicklungsschritte.'),
  ('108adc32-ab84-4dcd-be8c-e7597e84aa99', 'Sitzt dein Baby lange am Tisch? ⏱️', 'Jetzt beginnt die Phase, in der dein Baby mit dem Essen spielt. Aktiviere den Ernährungstimer und analysiere die Dauer der Mahlzeiten, um Appetitlosigkeit vorzubeugen.'),
  ('36ae8436-7cda-46ec-b16d-44295bf2f7bc', 'Schon wieder aus der Kleidung herausgewachsen? 📏', 'Hast du das Gefühl, dass dein Baby plötzlich einen Wachstumsschub gemacht hat? Trage die neuen Werte in den Entwicklungs-Tracker ein und beobachte stolz, wie die Wachstumskurve steigt.'),
  ('909b1a9f-36d9-4ba3-a481-ae0e711ea145', 'Zauberhafte Schnappschüsse 📸', 'Versucht dein Baby zu hüpfen oder zu tanzen? Verziere diesen Moment mit den fröhlichen Rahmen aus dem Baby-Fotoshooting und halte ihn als lebenslange Erinnerung fest.'),
  ('049ab226-ff27-4f2f-a64f-85d2b588c035', 'Könnten es Zahnschmerzen sein? 🤖', 'Ist dein Baby ohne erkennbaren Grund appetitlos oder weint es häufig? Frage Anacan AI nach einer fachlichen Einschätzung zu den Anzeichen durchbrechender Backenzähne.'),
  ('0e73fb38-1702-4d44-8a47-bf821e795ce5', 'Sichere Schritte 👟', 'Dein Baby wird beim Laufen immer schneller! Entdecke im Bereich „Empfohlene Produkte“ die besten orthopädischen Schuhmodelle für seine ersten sicheren Schritte.'),
  ('2606521b-da76-4e40-8b9b-74eaed8f4900', 'Erinnerungen für die Zukunft 🖼️', 'Hast du den Moment, der dich heute am meisten zum Lachen gebracht hat, schon zum Babyalbum hinzugefügt? So bleiben deine Erinnerungen immer sicher, selbst wenn der Handyspeicher voll ist.'),
  ('f8ad5a51-f4c3-4fc4-8170-0775df79fe84', 'Will selbst essen 🥣', 'Gibt dein Baby den Löffel nicht mehr aus der Hand? Starte den Ernährungstimer, verfolge die Dauer der Mahlzeit und wähle unter den Baby-Rezepten Lebensmittel aus, die sich leicht greifen lassen.'),
  ('995604f6-97b2-4fe5-91ea-98f2248c1b28', 'Eine Extraportion Eiweiß 🥚', 'Für die Muskeln deines kleinen Wirbelwinds ist Eiweiß unverzichtbar! Prüfe mit dem Ernährungstracker die tägliche Ausgewogenheit seiner Mahlzeiten und gleiche mögliche Defizite aus.'),
  ('ec6ff433-9523-4a66-a427-b2548807345b', 'Aufmerksamkeit und Gedächtnis 🧠', 'Wie lernt dein Baby? Lies im Blogbereich unserer App den Artikel über die Entwicklung von Aufmerksamkeit und Gedächtnis ab einem Alter von 1.5 Jahren.'),
  ('ef4e2662-a0c2-4758-a2d7-d0ebe8f23855', 'Der Tag geht zu Ende 🌙', 'Zeit fürs Bett! Starte den Schlaftimer, dokumentiere den Schlafrhythmus deines Babys, um sicherzustellen, dass es genug Schlaf bekommt, und entspanne dich.'),
  ('0bcc42e9-f88e-427d-8d6d-562c3e7e7138', 'Mission Brokkoli! 🥦', 'Dein Baby lehnt Gemüse ab? Keine Sorge. Entdecke in den Baby-Rezepten, wie du Brokkoli in leckeren Pfannkuchen verstecken kannst.'),
  ('2e502c2f-240e-4506-a102-a80013f7742b', 'Sei ehrlich zu dir selbst 🛋️', 'Warst du heute völlig erschöpft und wolltest einfach alles hinschmeißen? Das ist normal! Öffne dein Stimmungstagebuch, schreibe „Ich brauche eine Pause“ hinein und widme diesen Abend nur dir selbst.'),
  ('530196ff-adb2-4ae9-a06d-67bb4bfd998f', 'Bleibt die Windel häufiger trocken? 🧻', 'Überprüfe morgens die Windel. Wenn sie länger als 2 Stunden trocken bleibt, kann das ein erstes Zeichen dafür sein, dass dein Kind bereit für das Töpfchentraining ist! Trage deine Notizen in den Windeltracker ein und sieh dir die Statistik an.'),
  ('057998e1-6566-4f75-aa40-70a38d334aee', 'Mamas Flüssigkeitshaushalt 💧', 'Hast du beim Hinterherlaufen hinter deinem Kind vergessen, genug zu trinken? Das könnte die Ursache deiner Kopfschmerzen sein. Bereite Detox-Wasser nach unseren gesunden Rezepten zu und tanke neue Energie.'),
  ('309ac2aa-7e4c-4fba-a6ae-8ce53ca7a9f7', 'Schlafregression? ⏱️', 'Wacht dein Baby nachts häufig auf? Schau dir die Übersicht im Schlaf-Timer an. Wenn der Tagschlaf zu lange dauert, könnte es Zeit sein, ihn etwas zu verkürzen.'),
  ('6cc3ddd9-74b8-4e89-bf39-abc72a3548c9', 'Kalziumspeicher 🧀', 'Kalzium ist für Zähne und Knochen unverzichtbar. Prüfe mit dem Ernährungstracker, ob du heute die empfohlene Menge an Milchprodukten zu dir genommen hast.'),
  ('ec0d2d5d-31ad-48a9-8c47-f6c4eeeace11', 'Tägliche Balance 💧', 'Vergiss nicht, den Windelwechsel am Mittag einzutragen! Die Häufigkeit der Ausscheidungen gibt Aufschluss über den Flüssigkeitsbedarf und die Verdauung deines Kindes – besonders bei viel Bewegung.'),
  ('44008632-a96c-4f5e-a936-9b65273a2264', 'Jetzt bist du dran 🥗', 'Dein Kind macht gerade Mittagsschlaf? Dann ab in die Küche! Bereite dir mit unseren gesunden Rezepten für Frauen etwas Leckeres zu.'),
  ('868f8ace-292a-4cf1-9abe-4b2da08aca3f', 'Kaffeepause ☕', 'Bist du von Haushalt und Alltag erschöpft? Finde unter den mama-freundlichen Orten ein Café mit Kinderecke. Eine heiße Tasse Kaffee hast du dir wirklich verdient.'),
  ('f7b08a7d-5067-40df-81d3-421be952c00e', 'Keine Mutter ist perfekt 💖', 'Wenn heute nicht alles nach Plan gelaufen ist, mach dir keine Vorwürfe. Schreib im Stimmungstagebuch auf, was dich innerlich belastet, und atme tief durch.'),
  ('58a79bee-96dd-429b-a570-14dc6d97d91a', 'Beruhigende Wellen 🌊', 'Ein überreiztes Gehirn braucht Zeit, um zur Ruhe zu kommen. Spiele im Zimmer über die Weißen Geräusche Meeresrauschen ab und hilf deinem Kind, sich zu entspannen.'),
  ('cf7f3cf6-5b3a-46ef-aef0-f4f77d4245e1', 'Die „Was ist das?“-Phase 🤖', 'Überraschen dich die endlosen Fragen und die Entdeckerfreude deines Kindes? Erfahre von unserem Anacan AI-Assistenten mehr über diesen Entwicklungsschub.'),
  ('29452fba-ed37-4bde-8e72-45e1f9c46d4d', 'In 10 Minuten einschlafen... ⏱️', 'Starte den Einschlaftimer und verdunkle das Zimmer. Spiele Waldrauschen aus den Weißen Geräuschen ab und verwandle das Einschlafen für dein Baby und dich in einen zauberhaften Moment.'),
  ('fa637a9e-0a58-4301-a5dd-89fb27cdb46b', 'Nudelmonster! 🍝', 'Beim selbstständigen Essen sind Kleidung und sogar Haare voller Soße? Halte diesen lustigen Moment fest! Verziere das Foto mit den fröhlichen Rahmen aus dem Baby-Fotoshooting und füge es dem Album hinzu.'),
  ('44418a3d-932e-44e2-832c-c9fdeea34df1', 'Hauen und Beißen? 🛑', 'Gefühle, die dein Kind noch nicht ausdrücken kann, äußern sich manchmal als Aggression. Frage Anacan AI, wie du in diesem Alter am besten mit Beißen und Hauen umgehst.'),
  ('4a287257-0f36-49cd-93f7-28a1154386a6', 'Wie entsteht die Liebe zu Büchern? 📖', 'Lest ihr vor dem Schlafengehen? In unserem Blog erfährst du die goldenen Regeln, mit denen du bei deinem Kind die Liebe zu Büchern weckst und seine Aufmerksamkeit auf den Seiten hältst.'),
  ('f9f77164-bd35-4d6c-83ca-1991fcf7701a', 'Neue Entdeckungen, neue Gefahren ⚠️', 'Dein Baby klettert inzwischen überall hinauf! Sieh dir im Bereich „Empfohlene Produkte“ unbedingt die weichen Kantenschützer für Möbel an, um euer Zuhause sicherer zu machen.'),
  ('66297752-072e-4e90-afa0-bfdfc587176c', 'Wie steht es um die Eisenversorgung? 🥩', 'Prüfe im Ernährungstracker die heutige Eisenaufnahme und gleiche mögliche Defizite aus, damit dein kleiner Wirbelwind keine Blutarmut entwickelt und voller Energie bleibt.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_de = v.t, body_de = v.b
FROM (VALUES
  ('802d0f46-e525-43d0-8f5c-440b82228035'::uuid, 'Therapie mit Sand und Blättern 🍂', 'Raus aus den eigenen vier Wänden! Finde unter den mama-freundlichen Orten einen Park mit Sandkasten oder einer großen Grünfläche und unterstütze so die sensorische Entwicklung deines Kindes.'),
  ('ee6e42f5-c128-4ecd-8cea-dcd4ee6be618', 'Verabschiede dich vom Perfektionismus ✨', 'Hast du heute dein Kind angeschrien? Mach dir keine Vorwürfe. Schreibe im Stimmungstagebuch auf, was dich innerlich belastet, vergib dir selbst und bereite dich auf einen neuen Tag morgen vor.'),
  ('031932e3-d91b-494c-9f35-dc03d53026b4', 'Drücken die Schuhe? 👟', 'Stolpert dein Kind in letzter Zeit beim Laufen häufiger? Vielleicht sind seine Füße gewachsen! Trage die neue Schuhgröße und Körpergröße in den Gewichts-Tracker ein, um sein Wachstum zu analysieren.'),
  ('db0a30ff-e18a-4830-abdc-881dc8827a75', 'Nahrung fürs Gehirn: Omega-3 🐟', 'Fisch ist wichtig für die geistige Entwicklung. Bereite für Babys, die bereits Beikost bekommen, nach einem unserer Rezepte leckere grätenfreie Fischfrikadellen aus dem Ofen zu.'),
  ('eb71840a-d8fc-43f9-897d-715c008b72b7', 'Zeit, einen Gang herunterzuschalten! 🌙', 'Ein aktiver Tag geht zu Ende. Aktiviere den Schlaf-Timer, beendet das Herumtoben und geht zu beruhigenden Beschäftigungen über, zum Beispiel zu einem Puzzle.'),
  ('36d9b82f-d63f-40d9-bafa-df3b3dc844b9', 'Genuss in 5 Minuten! 🥗', 'Isst du mittags nur schnell eine Kleinigkeit? Bereite aus unseren gesunden Rezepten für Frauen einen Avocado-Ei-Toast zu, der lange satt macht und Energie spendet.'),
  ('5db92d40-f36e-4671-8f65-a3cb3f1c91ed', 'Physikexperimente in der Badewanne 🛁', 'Halte den ernsten, konzentrierten Gesichtsausdruck deines Babys beim Umgießen von Wasser aus einem Plastikbecher in einen anderen im Babyalbum fest – diese kleinen Entdeckungsmomente sind unvergesslich!'),
  ('e18f3a19-4a7e-44e4-9703-5c88f6dda037', 'Zu viel Bildschirmzeit? 📱', 'Löst es einen großen Wutanfall aus, wenn du das Smartphone wegnimmst? Erfahre von Anacan AI, wie du die Bildschirmzeit stressfrei begrenzen und gesunde Grenzen setzen kannst.'),
  ('2c1e9be8-ccf0-412a-a942-30cea5075e5b', 'Zeit für neue Kontakte! 👶', 'Dein Kind möchte jetzt immer häufiger mit anderen Kindern zusammen sein. Entdecke unter den mama­freundlichen Orten einen Ort mit einem Kinderspielbereich und bereite ihm eine Freude.'),
  ('cb4b4d68-2b36-4d3f-aa77-92d10314464f', 'Neues Lebensmittel, neue Reaktion 💩', 'Hat dein Kind gestern etwas Ungewohntes oder möglicherweise Allergieauslösendes gegessen? Beobachte beim morgendlichen Windelwechsel den Stuhl und dokumentiere Veränderungen von Farbe oder Konsistenz in der App, um die Situation im Blick zu behalten.'),
  ('fec1f9db-8b95-410a-b753-aded5a7dc606', 'Hat dein Baby Angst im Dunkeln? 🌌', 'Weint dein Baby oder wird es unruhig, wenn du das Licht im Zimmer ausschaltest? Spiele unter „Weißes Rauschen“ die Geräusche aus dem Mutterleib mit Herzschlag ab und schenke ihm so das vertraute Gefühl von Wärme und Geborgenheit.'),
  ('5c635a69-e5ff-42eb-9277-29e39d9986fa', 'Zähneputzen macht Spaß! 🪥', 'Lässt dein Kind die Zahnbürste nicht an den Mund? Sieh dir unter „Empfohlene Produkte“ Fingerzahnbürsten oder Modelle mit Licht und Musik an und verwandle die tägliche Zahnpflege in ein Spiel.'),
  ('f2a19104-ece3-4a8f-9966-8cad392a68af', 'Die Stille der Nacht 🍵', 'Dein Kind schläft, der Timer ist gestoppt. Jetzt musst du nicht mehr hetzen – es ist Zeit, dich auszuruhen. Brühe dir nach unseren gesunden Rezepten einen Kamillentee auf und genieße die vollkommene Ruhe.'),
  ('f524b282-4173-4386-b8dd-255261b77d1d', 'Ich ziehe mich selbst an! 👕', 'Gibt es morgens beim Anziehen oft großen Streit? Im Bereich „Blogs“ findest du praktische Tipps, wie du deinem Kind Wahlmöglichkeiten gibst und so Krisen beim Anziehen entschärfst.'),
  ('46919051-4727-4a43-8ba3-d5a1f5451c16', 'Großes Geschrei im Supermarkt? 🛒', 'Wirft sich dein Kind in der Öffentlichkeit auf den Boden, weil es nicht bekommt, was es möchte? Lass dich von den Blicken anderer nicht verunsichern: Sprich in diesem Moment mit Anacan AI und hole dir Unterstützung, um ruhig zu bleiben.'),
  ('874df706-e26e-4b72-a02c-7f8309fc95d5', 'Sätze aus zwei Wörtern! 🗣️', 'Hat dein Kind heute eine neue Wortkombination wie „Mama, komm“ oder „Wirf den Ball“ gebildet? Halte diesen großartigen sprachlichen Entwicklungsschritt sofort als Video mit Ton im Babyalbum fest.'),
  ('af368cd3-f751-4611-9e47-9c8fda037ebd', 'Die Feinmotorik ist im Einsatz! 🧩', 'Lass dein Kind Erbsen, Mais oder geschnittenes Obst selbstständig essen. Das fördert seine Feinmotorik. Behalte die Portionsgröße mit der Ernährungskontrolle im Blick.'),
  ('1f770df3-c7ef-4bf3-8564-f5ddd0b6a323', 'Unterstützung für das Immunsystem! 🍊', 'Wechselt das Wetter? Berechne mit der Ernährungskontrolle die heutige Vitamin-C-Zufuhr und ergänze den Speiseplan um Zitrusfrüchte, Kiwi oder bunte Paprika.'),
  ('cc01349a-6eef-4c61-aa08-b3f505c2eb5f', 'Der „Ich will allein essen!“-Kampf 🥣', 'Lässt du dein Kind allein essen, landet das Essen überall – hilfst du ihm, schreit es. Erfahre jetzt mit den psychologischen Tipps von Anacan AI, wie du diese Phase stressfrei meistern kannst.'),
  ('3abde512-ebd4-4cf1-986e-fb1953695f78', 'Ein bunter Schutzschild fürs Immunsystem 🛡️', 'Prüfe mit dem Ernährungstracker, ob dein Kind heute genug Vitamin C bekommen hat. In den Babyrezepten findest du passende Gerichte mit orangefarbenem und rotem Gemüse.'),
  ('56129e04-2f90-42b1-b51e-b835940e284e', 'Befreie dich von der mentalen Last 🧘‍♀️', 'Das muss ich noch erledigen, jenes noch kochen – kommt dein Kopf nicht zur Ruhe? Schreibe all deine Pläne und Sorgen in dein Stimmungstagebuch. Sie aufzulisten, reduziert den Stress sofort.'),
  ('deb6cbd4-3a89-4915-9bdf-626d87829918', 'Die Liebe zu Wasser und Matsch 💦', 'Hab keine Angst vor schmutziger Kleidung! Finde unter den mama­freundlichen Orten einen Platz im Freien und lass dein Kind die Natur mit allen Sinnen entdecken – eine wertvolle Erfahrung für seine sensorische Entwicklung.'),
  ('1576f605-27d8-4159-b3bd-3dd9e63c91dd', 'Viel Flüssigkeit, leichte Verdauung 💧', 'Die vollständige Umstellung auf feste Nahrung kann die Verdauung manchmal erschweren. Halte im Windeltracker alles fest, um leicht zu erkennen, ob dein Kind mehr Flüssigkeit braucht.'),
  ('93141c59-a17f-414d-9f6c-c865a0650eeb', 'Das Schattentheater beginnt! 🐰', 'Schalte das Licht im Zimmer aus und forme mit einer Taschenlampe Schattenfiguren an der Wand. Halte unbedingt den süßen, staunenden Gesichtsausdruck deines Babys für das Babyalbum fest.'),
  ('a14c30d1-ff1f-46da-8b1e-98116e38ee0d', 'Lust, Seiten zu zerreißen? 📖', 'Will dein Kind Bücher lieber zerreißen, statt sie anzuschauen? Lies im Blogbereich unsere neuen Tipps dazu, warum Pappbilderbücher und Fühlbücher in diesem Alter so wichtig sind.'),
  ('8e7d531f-d445-43eb-a4d5-05ffff377c4f', 'Von Geräuschen zur Stille 🎶', 'Der plötzliche Wechsel von Fernseh- oder Spielzeuggeräuschen zu völliger Stille kann Kinder erschrecken. Spiele im Zimmer über die Weißen Geräusche Zuggeräusche ab und schaffe so einen sanften Übergang in die Schlafatmosphäre.'),
  ('6bb4b5b9-3f8e-4a1c-a637-e0752d1d87ee', 'Kleine Fashionista am Werk! 👗', 'Möchte dein Baby seine Kleidung selbst aussuchen und kombiniert dabei unpassende Farben? Verziert dieses lustige Outfit beim Baby-Fotoshooting mit fröhlichen Stickern und macht das Foto zum witzigsten Schnappschuss im Album.'),
  ('f830cd97-a8bb-4789-bdc5-7806bcd89cfe', 'Überdreht und hellwach 🎇', 'Ein Gehirn, das tagsüber sehr aktiv ist, kann nachts nur schwer abschalten. Spiele unter Weißes Rauschen das Geräusch eines Haartrockners oder Ventilators ab und beobachte, wie der gleichmäßige Klang dein Baby beruhigt.'),
  ('f8565841-4602-47d5-af45-99f7dea5b129', 'Links- oder Rechtshänder? 🤚', 'Mit welcher Hand hält dein Baby den Löffel? Lies unbedingt unseren neuen wissenschaftlich fundierten Artikel im Bereich Blogs darüber, wie und wann sich die Händigkeit entwickelt.'),
  ('1915583e-53f5-46af-8212-835dfd587e22', 'Hält der Haarausfall an? 💇‍♀️', 'Dein Körper befindet sich noch immer in der Erholungsphase. Tu dir heute etwas Gutes und wähle aus den gesunden Rezepten für Frauen ein Frühstück, das reich an Zink und Biotin ist.'),
  ('cfbeabf3-def0-4cbe-a106-fd34987dd776', 'Zeit für Musikinstrumente 🥁', 'Trommelt dein Baby gern mit Holzlöffeln auf Töpfen? Entdecke unter Empfohlene Produkte Xylofone und Trommeln mit einer Lautstärke, die für Kinderohren unbedenklich ist.'),
  ('daa6a0d6-25d4-401e-ba81-8a8ca5108695', 'Die ersten Tierlaute 🐮', 'Versucht dein Baby, einen Hund oder eine Katze nachzuahmen, sobald es sie sieht? Halte diesen wunderbaren Entwicklungsschritt in einem kurzen Video fest und füge es dem Babyalbum als schöne Erinnerung hinzu.'),
  ('2ed7fd17-90ba-451d-9c88-a1f94a180fe0', 'Weniger Appetit – und das Gewicht? 📉', 'In diesem Alter werden viele Babys beim Essen wählerischer. Trage die aktuellen Werte in den Gewichts-Tracker ein und finde heraus, ob sich dein Baby völlig normal entwickelt – das kann dich schnell beruhigen.'),
  ('50209dd4-d2d7-4719-bf4e-21df8c72686a', 'Rituale vor dem Schlafengehen 🧸', 'Jeden Abend der gleiche Ablauf! Starte den Schlaf-Timer, lass dein Baby seinem Lieblingsteddy Gute Nacht sagen und beobachte, wie diese Beständigkeit das Einschlafen erleichtert.'),
  ('28cf8172-0a76-4afd-b2de-765879c7939a', 'Danke dir selbst! 💖', 'Du bist so eine hingebungsvolle und wunderbare Mama! Öffne das Stimmungstagebuch, notiere selbst die kleinste gute Sache, die du heute für dein Kind getan hast, und sei stolz auf dich.'),
  ('f00a5e44-ed12-4c77-9249-e4246b2b108d', 'Das erste Kennenlernen mit dem Töpfchen 🚽', 'Auch wenn es noch früh ist, schafft ein Töpfchen im Badezimmer bereits visuelle Vertrautheit. Schau dir unter den empfohlenen Produkten bequeme und interessante Modelle an, die seine Aufmerksamkeit wecken.'),
  ('6d72635f-ba12-4c8b-b7ef-f626dd634dce', 'Morgens ist die Energie ganz anders! ⚡', 'Lehnt dein Kind Haferbrei ab? Entdecke in den Babyrezepten einen Smoothie mit Obst und Erdnussmus und erreiche damit ganz einfach dein Kalorienziel in der Ernährungskontrolle.'),
  ('9867089b-80a4-4895-985d-1e1d5fa3df95', 'Fallen dir die Augen zu? 😴', 'Leg dich ebenfalls hin, wenn dein Kind schläft. Wenn du nicht schlafen kannst, bereite dir aus den gesunden Rezepten für Frauen einen antioxidantienreichen grünen Tee zu und tanke neue Energie.'),
  ('a5fedf21-2dca-46ed-9476-0b415ced68a5', 'Widerstand gegen das Zubettgehen? 🛌', 'Der 19. Monat ist für Schlafregressionen bekannt. Starte den Schlaftimer und überprüfe den Schlafplan – vielleicht ist jetzt genau der richtige Zeitpunkt, den Mittagsschlaf zu verkürzen!'),
  ('39db43fc-07a0-417e-90da-c0bbbd5f14a4', 'Verdacht auf Bauchschmerzen? 💩', 'Trage beim morgendlichen Windelwechsel die Ausscheidungen ein. Wenn Verstopfungsgefahr besteht, frage Anacan AI nach schnell anwendbaren natürlichen Maßnahmen und Massagetechniken.'),
  ('613cd9e2-958a-41bd-b191-0de3ff8ec07f', 'Wie oft hast du heute „Nein“ gehört? 🙉', 'Mit einem trotzigen kleinen Kind umzugehen, erfordert Geduld. Schreibe deine innere Anspannung in dein Stimmungstagebuch und lass deine Gefühle heraus, ohne dich selbst zu verurteilen.'),
  ('e893b0aa-e3fc-4f78-a970-b681a0ed0450', 'Kletterchampion! 🧗', 'Reichen die Möbel zu Hause nicht mehr aus? Finde unter den mama-freundlichen Orten ein Indoor-Spielzentrum mit weichen Hindernisparcours, in dem dein Kind seinen Kletterdrang sicher ausleben kann.'),
  ('c6f920b8-00cf-46b0-a823-bf8cf1fd5ecf', 'Probleme beim Teilen 🧸', 'Dein Kind läuft im Park zu den Spielsachen anderer Kinder, möchte sein eigenes aber nicht hergeben? Erfahre mit Anacan AI, wie du einem 1.5-jährigen Kind beibringen kannst, sich beim Spielen abzuwechseln.'),
  ('ca671510-91c4-4377-9f69-b4bd47b292a2', 'Eine Tasse Auszeit ☕', 'Wie voll ist dein Akku? Lass die Hausarbeit ruhen. Backe nach unseren gesunden Rezepten für Frauen einen energiereichen Erdnussbutterkuchen und genieße einfach in Ruhe deinen Kaffee.'),
  ('38141003-a43c-4589-a477-21da541a08db', 'Zauberspaß mit kinetischem Sand 🏖️', 'Wie wäre es mit einem kleinen Strand zu Hause? Entdecke unter den empfohlenen Produkten Sets mit kinetischem Sand, die die Fingermuskulatur stärken und sich leicht wegräumen lassen.'),
  ('75f9f2e1-a04a-4711-9125-3d8c610326d9', 'Dein Kind kennt seinen Körper! 👃', 'Zeigt dein Kind stolz auf seine Nase, wenn du fragst: „Wo ist deine Nase?“ Veranstalte beim Baby-Fotoshooting ein kleines Shooting im Zimmer und halte diese süße Pose gleich im Album fest.'),
  ('ae036003-f237-47e6-8031-7feeb47126cc', 'Woran erkennst du, dass dein Kind satt ist? ⏱️', 'Wenn dein Kind anfängt, das Essen wegzuwerfen oder auszuspucken, kann das bedeuten: „Ich bin satt.“ Stoppe den Ernährungstimer, vermerke, dass die vorgesehene Menge erreicht wurde, und analysiere den Appetit.'),
  ('05bc3cfd-c566-4963-b6b2-87889d369e27', 'Auch du brauchst Gemeinschaft 💬', 'Der Austausch mit anderen Müttern wird auch dir guttun! Wähle unter den mama- und babyfreundlichen Orten ein Zentrum mit Spielgruppen aus und schenke euch beiden wertvolle soziale Kontakte.'),
  ('5b6366a9-6eb4-4593-8335-c41fd3447da1', 'Was ist dein heutiger Erfolg? 🏆', 'Dein Kind ohne Tränen ins Bett gebracht? Oder eine ganze Schüssel gefüttert? Halte selbst deinen kleinsten Erfolg im Stimmungstagebuch fest und klopfe dir dafür selbst auf die Schulter.'),
  ('98a39354-24f3-4f3c-9cfb-1e084764a56b', 'Wachstum zeigt sich zuerst an den Schuhen 📏', 'Vielleicht möchte dein Kind seine Schuhe nicht anziehen, weil sie zu eng geworden sind! Sieh in der Größentabelle des Gewichtstrackers nach und behalte die körperliche Entwicklung im Blick.'),
  ('a0570819-b575-49b5-bbf4-bc21cf5fc939', 'Mit beiden Beinen hüpfen 🦘', 'Versucht dein Kind, aus dem Stand mit beiden Beinen gleichzeitig zu hüpfen? Das sieht richtig lustig aus, oder? Halte diesen Moment unbedingt mit dem Baby-Fotoshooting fest.'),
  ('1eeadb7c-f8e9-45ae-bbde-edff2903cb9d', 'Kein Mittagsschlaf mehr? 🥱', 'Will dein Kind tagsüber nicht schlafen und wehrt sich dagegen? Bitte Anacan AI um genaue Informationen zu den Wachfenstern von 20 Monate alten Kindern und um einen passenden Schlafplan.'),
  ('2edb626b-eafe-49c0-a743-e6dae9f9eddd', 'Musikalische Geborgenheit 🎶', 'Die einfachste Lösung gegen die Quengelei am späten Nachmittag: Mach die Lieblingsmelodie deines Kindes an, nimm es in den Arm und tanzt langsam zusammen.'),
  ('b174df30-8e63-488e-ae9b-4d227f3136f1', 'Ein Festmahl für Mama 🥑', 'Du tust alles, damit dein Kind satt wird. Aber was ist mit dir? Wähle aus den gesunden Rezepten ein eisenreiches Mittagessen, das dir Kraft gibt, und nimm dir die Zeit, es in Ruhe zu genießen.'),
  ('5d951093-5ada-49f6-9750-d303bcf8d918', 'Die großen Backenzähne? 🦷', 'Kaut dein Kind scheinbar grundlos auf allem herum und weint? Vielleicht sind die hintersten Backenzähne unterwegs. Dokumentiere den Verlauf im Zahnungs-Tracker und lege gekühlte Beißringe bereit.'),
  ('9fe66081-4fad-49c8-891d-2ca85484f87d', 'Der Held der Geschichte 🪄', 'Erstelle heute Abend bei den Schlauen Geschichten eine besondere Erzählung, in der dein eigenes Kind die Hauptrolle spielt: ein mutiges Kleines, das gerne seine Zähne putzt.'),
  ('c638741f-2af1-4bf3-a4de-09ffcb406144', 'Nur Mut, raus ins Freie ⛅', 'Seid ihr zu Hause geblieben, weil das Wetter unbeständig ist? Das Wetter- und Kleidungs-Tool zeigt dir sofort die Windgeschwindigkeit, die du vom Fenster aus nicht erkennen kannst, und das passende Outfit. So könnt ihr gut vorbereitet in den Park gehen.'),
  ('3d75b744-8440-4e62-83c6-4a08b865c0f7', 'Joghurtmaske! 🥣', 'Hat dein Kind das Essen im Gesicht und in den Haaren verteilt? Statt dich zu ärgern, kannst du dieses geniale Kunstwerk im Babyalbum verewigen und mit lustigen Stickern verzieren.'),
  ('5bcd3758-fc71-4b21-a0a4-008b6ec5eec1', 'Für Haare und Haut 🥑', 'Gönn deinem vom Alltag erschöpften Körper etwas Pflege. Bereite einen vitalisierenden Salat mit Avocado und Walnüssen zu – ein gesundes Rezept für Frauen und eine wahre Antioxidantienbombe.'),
  ('a832a387-bccf-4a1a-823c-3930e73e4c07', 'Wasser geben, Mama kommen 🗣️', 'Versucht dein Kind schon, zwei Wörter zu kleinen Sätzen zu verbinden? Das ist ein großartiger Sprung in der Sprachentwicklung! Bestärke es immer wieder in seinen Versuchen und ermuntere es zum Sprechen.'),
  ('d1f9f7f1-6831-4583-9dbd-fab805703b8d', 'Endlose Energie 🔋', 'Wird dein Kind vom Herumrennen einfach nicht müde? Starte den Einschlaf-Timer und dimme das Licht im Zimmer. Mit sanftem Waldrauschen aus den Weißen Geräuschen kannst du es langsam auf das Schlafengehen einstimmen.'),
  ('34104368-1e25-46df-8c68-910d16cd40b1', 'Wie läuft die Verdauung? 🚽', 'Hat dein Kind Verstopfung? Notiere es morgens beim Windelwechsel und füge seinem Speiseplan mit dem Ernährungstracker unbedingt ballaststoffreiche Lebensmittel wie Birnen und Haferflocken hinzu.'),
  ('79b083b6-1c72-4250-a120-ca8846206ce5', 'Wie fühlst du dich? 🧘‍♀️', 'Hast du heute sehr oft „Nein!“ gesagt? Hab kein schlechtes Gewissen. Schreib dir im Stimmungstagebuch alles von der Seele und erinnere dich daran, wie viel du als Mutter jeden Tag leistest.'),
  ('bfb35c45-0163-48f3-be24-eff4697cb9e8', 'Kleine Naturkünstler 🍂', 'Blätter, Steine und Zweige sind die besten Spielsachen! Finde unter den mutterfreundlichen Orten einen grünen Park und begebt euch gemeinsam auf eine echte Entdeckungstour im Freien.'),
  ('01861a89-1cc1-4443-8c58-c79d90402305', 'Wutanfälle im Supermarkt 🛒', 'Hat sich dein Kind auf den Boden geworfen, weil du ihm im Laden nicht gekauft hast, was es wollte? Keine Panik. Ignoriere die Blicke der anderen, bleib ruhig und geh auf Augenhöhe mit deinem Kind.'),
  ('32e724db-ca0f-4d6b-9d07-716443a9dcdd', 'Lass den emotionalen Ballast los 📝', 'War es ein schwieriger Tag? Schreib den heutigen Stress in dein Stimmungstagebuch und lass alles heraus. Alle Mütter erleben solche Phasen – du bist nicht allein.'),
  ('e6ec7f70-00dc-438b-af17-5f764a9d8216', 'Wird der Mittagsschlaf kürzer? ⏱️', 'Will dein Kind keinen Mittagsschlaf mehr machen? Behalte die Statistiken des Schlaftimers im Blick. Vielleicht ist es schon vollständig auf nur einen Tagschlaf umgestiegen und sollte dafür abends früher ins Bett gehen.'),
  ('46ef9700-c667-4312-ac63-98bd03625249', 'Der tägliche Schuhkampf 👟', 'Will dein Kind im Sommer unbedingt seine Winterschuhe anziehen, wenn ihr rausgeht? Lass ihm manchmal die freie Wahl – das stärkt seine Willenskraft.'),
  ('5541587a-ad73-4e1d-9174-d4fe1c028c3e', 'Widerstand gegen das Einschlafen? 🛌', 'Dein Kind will nicht ins Bett, weil Spielen viel spannender ist als Schlafen! Starte den Schlaftimer und hilf seinem Gehirn mit Meeresrauschen aus den Weißen Geräuschen, langsam zur Ruhe zu kommen.'),
  ('c2f59a7d-198f-4c77-831a-cca0b1b7e5e6', 'Beginnt das Interesse an der Toilette? 🚽', 'Will dein Kind mit dir ins Badezimmer kommen? Das ist ein Teil der visuellen Vorbereitung. Lies im Bereich „Blogs“, wann und wie du mit dem Töpfchentraining beginnen solltest, und bereite dich darauf vor.'),
  ('3b603489-95c3-4a32-b0e0-5191fc844b75', 'Der Kampf ums Selbstanziehen 👕', 'Hat die Trotzphase mit „Dieses T-Shirt will ich nicht!“ begonnen? Frag Anacan AI, wie du morgendliche Kleidungskrisen reduzieren und deinem Kind die Möglichkeit geben kannst, selbst zu wählen.'),
  ('89933e6a-484e-4f2e-bf20-8262f6a74c72', 'Omega-3-Versorgung 🐟', 'Die Gehirnentwicklung macht keine Pause. Prüfe in der Ernährungskontrolle, ob dein Kind diese Woche genug Fisch oder Walnüsse gegessen hat, und vermerke unbedingt, wenn die Zufuhr nicht ausreichend war.'),
  ('fa46cf0a-85f0-484c-8aa5-b60eb52b320b', 'Wie wird dein Kind zu Hause seine Energie los? 🏃‍♂️', 'Könnt ihr nicht nach draußen? Sieh dir unter „Empfohlene Produkte“ Minitrampoline oder Rutschen für den Innenbereich an, damit dein Kind seine Energie gezielt abbauen kann.'),
  ('00691751-d785-4fc6-8036-d313adccdad6', 'Morgendlicher Windelcheck 🧻', 'Gibt es häufiger trockene Windeln oder wird die Verdauung träger? Trage den morgendlichen Windelwechsel in den Windel-Tracker ein, um den Flüssigkeits- und Ballaststoffbedarf deines Kindes direkt auszuwerten.'),
  ('45af46ac-18bf-499b-a5c7-56bbe71e4564', 'Zeit zum Entspannen 🎶', 'Die kleinen Füße, die den ganzen Tag herumgeflitzt sind, brauchen jetzt eine Pause. Spiele unter „Weißes Rauschen“ die gleichmäßigen Geräusche aus dem Autoinnenraum ab und schaffe so die perfekte Schlafumgebung.'),
  ('47b68bdb-a1fd-4da7-9316-dcca5fdae94f', 'Auch du brauchst Freundinnen 👯‍♀️', 'Möchtest du dich mit anderen Müttern unterhalten, während dein Kind im Park spielt? Entdecke unter „Mütterfreundliche Orte“ Einrichtungen mit Spielgruppen, knüpfe Kontakte und tausche dich aus.'),
  ('49af58d4-c188-43d7-a0b2-43f4cd255337', 'Kaffee allein reicht morgens nicht! ☕', 'Wenn du den Tag auf nüchternen Magen nur mit Kaffee beginnst, ist deine Energie schnell aufgebraucht. Wähle aus den gesunden Rezepten für Frauen einen energiereichen Haferkuchen, der in nur 5 Minuten fertig ist.'),
  ('869af623-de96-421f-808b-d64172a8f765', 'Das hast du toll gemacht! 👏', 'Heute ist die Wohnung unaufgeräumt geblieben? Mach dir nichts daraus! Die fröhlichen Momente mit deinem Kind sind viel wertvoller. Vergiss nicht, dich in deinem Stimmungstagebuch selbst zu loben.'),
  ('aaf473f6-79bc-44cf-97f4-687dfa4eb293', 'Trinkt dein Kind nicht gern Wasser? 💧', 'War die Windel heute Morgen sehr trocken? Dann sollte dein Kind mehr Flüssigkeit zu sich nehmen. Trage es im Windel-Tracker ein und entdecke in der App Rezepte für Fruchtwasser sowie verschiedene Trinkbecher und Trinkflaschen.'),
  ('ff614b36-4091-473e-b7fa-91411bd4e2a9', 'Die Knochen werden stärker! 🦴', 'Prüfe heute mit dem Ernährungstracker, ob dein Kind genügend Kalzium und Vitamin D aufgenommen hat. Diese beiden Nährstoffe sind für die schnelle körperliche Entwicklung unverzichtbar.'),
  ('348430a9-4730-49e1-90ac-91076b5c5d7c', 'Sortieren wir die Farben! 🔴🔵', 'Die roten Spielsachen kommen auf die eine Seite, die blauen auf die andere. Entdecke im Blog Spiele für zu Hause, die bei 19.5 Monate alten Kindern Aufmerksamkeit und logisches Denken fördern, und probiere sie gemeinsam mit deinem Kind aus.'),
  ('907f2a4d-a45c-43e1-8024-d6c91a18d072', 'Ein großer Wutanfall im Supermarkt? 🛒', 'Hat sich dein Kind in der Öffentlichkeit auf den Boden geworfen und geweint? Vergiss die Blicke der anderen. Tausche dich mit Anacan AI aus und lerne Methoden kennen, mit denen du solche Wutanfälle ruhig und gelassen bewältigen kannst.'),
  ('69c1e419-f8f2-4b2f-90e3-9b51e78ff197', 'Der Timer ist gestoppt – gönn dir eine Pause 🍵', 'Du hast den Schlaf-Timer gestoppt und das Zimmer verlassen. Lass jetzt bloß die Hausarbeit liegen! Brühe dir einen Kamillentee auf und lass die Müdigkeit des Tages mit dem warmen Dampf verfliegen.'),
  ('934796d5-42af-4c49-9cb9-67f18b657e36', 'Juckt das Zahnfleisch? 🦷', 'Vielleicht sind die letzten Backenzähne unterwegs. Bereite aus den Babyrezepten kühles, zuckerfreies und gesundes Fruchteis am Stiel zu, um den Juckreiz am Zahnfleisch zu lindern.'),
  ('06d75280-127a-43d4-a7f0-42d2871b24c5', 'Kleiner Küchenchef! 👨‍🍳', 'Will dein Baby dir den Löffel nicht geben? Bereite aus den Babyrezepten handliche Frikadellen zu. Analysiere mit dem Ernährungstimer, wie lange dein Baby selbstständig isst, und behalte seinen Appetit im Blick.'),
  ('4b7fd5a1-3084-40d7-9f2d-e7fb4777d2eb', 'Lustige Grimassen 🤪', 'Schneidet dein Baby vor dem Spiegel Grimassen? Lass dir diesen lustigen Moment nicht entgehen! Verziere das Foto beim Baby-Fotoshooting mit witzigen Stickern und mach es zum fröhlichsten Bild im Album.'),
  ('739af07d-8466-4c3f-a164-5e408385ca93', 'Klettert dein Baby überall hoch? 🧗‍♀️', 'Sofa, Tisch, Schrank ... Dein Baby ist ein echter Kletterprofi! Lies im Blogbereich, wie du diesem riskanten, aber wichtigen Bewegungsdrang zu Hause auf sichere Weise Raum geben kannst.'),
  ('8ac7016a-7613-48aa-a952-59cc5f8a6354', 'Sind die Hosenbeine zu kurz geworden? 👖', 'Der Wachstumsschub ist in vollem Gange! Trage die aktuellen Größen- und Gewichtswerte in den Gewichts-Tracker ein und schau voller Stolz zu, wie die Entwicklungskurve ansteigt.'),
  ('db467018-0ec9-41a9-a3a3-3ef1c48cda53', 'Auf der Suche nach einem Lernspielzeug 🧩', 'Jetzt braucht dein Baby Spielzeug, das nicht nur Geräusche macht, sondern auch zum Denken anregt. Schau dir unter den empfohlenen Produkten unbedingt die Logik- und Formpuzzles für Kinder ab 1.5 Jahren an.'),
  ('df8f7402-1277-45bd-a743-5c24bdaf48e1', 'Wütendes Beißen? 🦖', 'Schlägt oder beißt dein Baby, wenn es wütend ist? Dahinter stecken Gefühle, die es noch nicht mit Worten ausdrücken kann. Erfahre von Anacan AI, wie du dieses Verhalten behutsam verändern kannst.'),
  ('0bde6683-6d18-4d98-bc39-b122396c0b17', 'Jetzt ist Zeit zum Entspannen 🍵', 'Der Trubel ist vorbei! Bereite dir ein Getränk nach einem gesunden Rezept zu, mach es dir auf dem Sofa gemütlich und genieße einfach die Ruhe.'),
  ('0eecf770-9ba2-463c-9b39-bbe24d01b4e1', '„Das gehört mir!“-Rufe 🧸', 'Nimmt dein Kind anderen auf dem Spielplatz das Spielzeug weg? Erfahre von Anacan AI, welche psychologischen Strategien am besten helfen, mit der für dieses Alter typischen egozentrischen Phase umzugehen.'),
  ('0a81bd63-014b-4d25-b347-1808455aea49', 'Raus aus den eigenen vier Wänden 🏃‍♀️', 'Zu Hause ist es schwer, all die Energie loszuwerden. Finde unter den kinderfreundlichen Orten ein sicheres Spielzentrum, in dem dein Kind herumtoben und du in Ruhe einen Kaffee trinken kannst.'),
  ('657f4585-c7bb-41c0-9574-51e8f943398b', 'Chaotisch, aber selbstständig! 🥣', 'Dein Kind besteht darauf, selbst zu essen? Starte den Ernährungstimer, verfolge die Dauer der Mahlzeit und halte fest, wie diese Selbstständigkeit seine Feinmotorik fördert.'),
  ('7feaa5c7-f1f9-4df2-a08a-b9cef56c0ce4', 'Sind die nächtlichen Wachphasen zurück? ⏱️', 'Dahinter könnte die Schlafregression mit 20 Monaten stecken. Sieh dir die Übersicht des Schlaftimers an und prüfe, ob es Zeit ist, den Mittagsschlaf um 15 Minuten zu verkürzen.'),
  ('385a8205-8e28-4c23-94fa-a2a8fe32e28c', 'Mach dir keine Vorwürfe 📝', 'Bist du heute etwas lauter geworden? Verurteile dich nicht dafür. Schreib dir deinen inneren Druck im Stimmungstagebuch von der Seele und denk daran: Du bist die beste Mama für dein Kind.'),
  ('49b18c8f-b30b-4368-9445-6af88b1d8115', 'Sätze aus 2 Wörtern! 🗣️', '„Mama, komm“, „Ball geben“ – der Wortschatz deines Kindes wächst rasant. Füge diese süßen Sprechversuche sofort als Video mit Ton zum Babyalbum hinzu und mache sie zu einer Erinnerung fürs Leben.'),
  ('5d516faa-7c77-4db9-b201-49bff969e3d8', 'Kalzium für starke Knochen 🦴', 'Die Knochen deines kleinen Wirbelwinds müssen stark sein. Prüfe in der Ernährungsübersicht die heutige Kalziumzufuhr (Käse, Joghurt) und ergänze bei Bedarf die noch fehlende Menge.'),
  ('ad033330-a436-4b30-84e7-2df370198c16', 'Auf der Suche nach cleverem Spielzeug 🧩', 'Steckt dein Baby gern Formen in die passenden Öffnungen? Entdecke unter „Empfohlene Produkte“ altersgerechte Holzpuzzles, die seine Denkfähigkeit weiter fördern.'),
  ('d22a5573-d857-4918-90d2-9def6a084f6f', 'Die Kunst, zur Ruhe zu kommen 🎶', 'Ein überreiztes Kind findet abends nur schwer in den Schlaf. Verdunkle das Zimmer und spiele unter „Weißes Rauschen“ Meereswellen ab, um dein Baby sanft auf einen tiefen Schlaf vorzubereiten.'),
  ('fb035079-cf24-4146-9049-8d721e68f53f', 'Ein kleiner Künstler voller Farbe! 🎨', 'Hat sich dein Baby beim Kritzeln von Kopf bis Fuß mit Farbe bekleckert? Statt dich zu ärgern, kannst du diesen lustigen Moment mit fröhlichen Stickern aus dem Baby-Fotoshooting verzieren und ins Album hochladen.'),
  ('0b2c56b1-a7a8-4553-8880-13254eeb155b', 'Die Kleidung wird zu klein? 📏', 'Wenn die Hosenbeine plötzlich zu kurz sind, steckt vielleicht ein Wachstumsschub dahinter! Trage die aktuellen Maße in den Gewichts-Tracker ein und beobachte stolz, wie die Entwicklungskurve ansteigt.'),
  ('9f2ceaa6-0d99-46a0-884c-3460db78351b', 'Dein Baby versteht dich, spricht aber noch nicht? 🧠', 'Der passive Wortschatz entwickelt sich schneller als der aktive. Lies im Bereich „Blogs“ unbedingt den Artikel über Spiele für zu Hause, die die Sprachentwicklung eines 20 Monate alten Kindes fördern.'),
  ('f641f443-9a8d-4060-a2b5-fe5d5562fa9d', 'Mission: versteckte Vitamine 🥕', 'Schiebt dein Baby Grünzeug und Gemüse beiseite? Entdecke in den Babyrezepten, wie du Spinat und Karotten geschickt in leckeren Pfannkuchen verstecken kannst.'),
  ('68ef19de-c144-4be9-8878-9cc1b34a6483', 'Wie lange dauert das Einschlafen? ⏱️', 'Wälzt sich dein Baby lange im Bett herum? Aktiviere den Schlaftimer und erfasse die Einschlafdauer. Vielleicht solltet ihr die abendlichen Spiele etwas früher beenden.'),
  ('70a3e410-6335-466b-99bc-28ac0c3d913f', 'Warum weint dein Baby plötzlich? 🤖', 'Wacht dein Baby nachts schreiend auf und lässt sich nicht beruhigen? Schreib dem Anacan AI-Experten sofort, wenn du einen Nachtschreck vermutest, und erfahre, wie du richtig reagieren kannst.'),
  ('847e9a71-981a-4920-b6be-a1986674dd92', 'Endlose Show am Esstisch ⏱️', 'Dein Kind spielt mit dem Essen und wirft es auf den Boden, isst aber nichts? Aktiviere den Mahlzeiten-Timer, bleib geduldig und analysiere in dieser Phase der Selbstständigkeit die Entwicklung seines Appetits genau anhand der Grafik in der App.'),
  ('890ee8d7-3315-4b7a-994a-c41900d8c960', 'Auf der Suche nach cleverem Spielzeug 🧩', 'Kann dein Kind Formen schon sicher in die passenden Öffnungen stecken? Entdecke jetzt im Bereich „Empfohlene Produkte“ altersgerechte Puzzles, die seine kognitiven Fähigkeiten weiter fördern.'),
  ('8ad462c4-33b5-4c76-be29-aa192feb14a1', 'Drücken die Schuhe? 📏', 'Stolpert dein Kind in letzter Zeit beim Laufen häufiger? Vielleicht sind seine Füße gewachsen! Trage die aktuelle Körpergröße und weitere Maße in den Entwicklungs-Tracker ein und behalte seine körperliche Entwicklung im Blick.'),
  ('2e662854-2d0b-4e0d-be84-f71f33b1ed5b', 'Warum weint dein Kind plötzlich? 🤖', 'Hat sich seine Stimmung mitten im fröhlichen Spielen plötzlich verändert und es hat angefangen zu weinen? Schreib unserem KI-Expertenassistenten von Anacan, um den Grund für diese Gefühlsschwankungen herauszufinden.'),
  ('b30cbe06-794a-4924-bc78-63ebe289b716', 'Die geistige Entwicklung geht weiter 🧠', 'Dein Kind liebt es, alles zu sortieren! Lies im Bereich „Blogs“ unbedingt den Artikel über Spiele für zu Hause, die bei 20-21 Monate alten Kindern die Wahrnehmung von Farben und Formen fördern.'),
  ('dcfe0150-6b59-46be-be17-cba289272768', 'Energie für 5 Minuten 🔋', 'Kaffee auf nüchternen Magen lässt deine Energie bis zum Mittag schwinden. Wähle aus den gesunden Rezepten einen leckeren, sättigenden Haferkuchen, der im Handumdrehen zubereitet ist.'),
  ('41523bc6-ac22-4b48-a7b5-8663ed9c74c3', 'Sandtherapie 🏖️', 'Hab keine Angst vor Schmutz! Finde unter den mama-freundlichen Orten einen Platz mit Sandkasten. Sand zu berühren ist für die sensorische Entwicklung wertvoller als teures Spielzeug.'),
  ('863859ae-c920-41fe-b876-915ee50bba17', 'Kleiner Künstler voller Farbe! 📸', 'Hat dein Kind sich selbst und gleich noch die Wand angemalt? Statt dich zu ärgern, kannst du diesen lustigen Kritzelmoment ins Babyalbum hochladen und mit witzigen Stickern verzieren.'),
  ('80e71246-05ae-4bc6-857d-5ce3af704b5e', 'Kraftquelle für Mamas 🥗', 'Bist du vom ständigen Hinterherlaufen völlig erschöpft? Greif nicht zu Süßigkeiten, sondern zu Eiweiß! Bereite aus den gesunden Rezepten für Frauen einen Erdnussbutter-Smoothie zu, der dir sofort neue Energie gibt.'),
  ('145211fa-74d2-4e28-8a64-c14921db5185', 'Lob dich selbst! 🌟', 'Hast du es heute geschafft, dein Baby zu füttern, ohne dass es weint? Notiere selbst deinen kleinsten Erfolg im Stimmungstagebuch und gönn dir für deine Fähigkeiten als Mama einen kräftigen Applaus.'),
  ('4f60f5e8-df5e-4892-aa2e-dcffda8f877b', 'Ein ausgeglichener Wasserhaushalt ist lebenswichtig 💧', 'Beim aktiven Herumtoben verliert der Körper viel Flüssigkeit. Trage morgens die Windel im Windel-Tracker ein und sieh dir unter „Empfohlene Produkte“ Sporttrinkflaschen an, die dein Kind leicht selbst öffnen kann.'),
  ('edd993f1-ac76-4300-8ed0-6009d7897f2b', 'Plaudern mit anderen Mamas ☕', 'Bist du es leid, dich nur mit deinem Kind zu unterhalten? Finde unter „Mama-freundliche Orte“ Kindercafés, in denen sich viele Mamas treffen, und gönn auch dir etwas Geselligkeit.'),
  ('6f516c4d-5db5-4d3e-8fca-8c461e614752', 'Sind die Eisenspeicher gut gefüllt? 🥩', 'Damit dein aktives Kleines keinen Eisenmangel bekommt, überprüfe in der Ernährungskontrolle die heutige Eisenaufnahme aus Fleisch und Hülsenfrüchten und passe den Speiseplan entsprechend an.'),
  ('b003834c-8ce3-4da4-a17e-0b837c04f7f7', 'Überprüfen wir die Kalziumversorgung 🧀', 'Die schnell wachsenden Knochen brauchen Kalzium! Prüfe mit der Ernährungskontrolle, ob dein Kind heute genug Käse und Joghurt gegessen hat, und ergänze, was noch fehlt.'),
  ('b5cae897-2c37-4223-8c5a-201bd9d0229a', 'Die geheimnisvollen Klänge des Waldes 🍃', 'War der Tag laut und voller Trotzanfälle? Spiele unter „Weißes Rauschen“ sanftes Blätterrascheln ab und gönn damit sowohl dem Nervensystem deines Kindes als auch deinem eigenen wohltuende Entspannung.'),
  ('20cf6725-2fdc-45bb-965b-09069424fe0a', 'Zuckerfreier Snack 🍪', 'Kekse aus dem Supermarkt sind nicht nötig. Entdecke in den Baby-Rezepten gesunde Leckereien mit Datteln und Haferflocken, die du zu Hause in nur 10 Minuten zubereiten kannst.'),
  ('3b1eb831-8b25-40be-89a6-b50384eeb49b', 'Es möchte sprechen, aber ... 🗣️', 'Ist sein passiver Wortschatz größer als sein aktiver? Lies im Bereich „Blogs“, wie du diesen großartigen Sprachsprung unterstützen kannst, auch wenn dein Baby die Wörter noch nicht richtig ausspricht.'),
  ('a4477b67-ebfc-489b-b2e5-165c0ebb273f', 'Der Wunsch nach Selbstständigkeit 🥣', 'Will dein Baby dir den Löffel nicht geben? Starte den Ernährungstimer und analysiere, wie lange dieser Versuch, selbstständig zu essen, dauert. Und lächle einfach über das verschüttete Essen.'),
  ('527e5a17-444d-47c4-8578-4ebb1ee870b1', 'Süße Träume oder Kampf? 🛌', 'Wenn das Zubettgehen zu einer großen Krise geworden ist, frag Anacan AI direkt nach Einschlafritualen und psychologischen Tipps für 21 Monate alte Kinder.'),
  ('9c6e3d93-ba09-4cda-8c01-9c820b1e3ed6', 'Wie war die Nacht? 🌙', 'Wenn die Windel morgens sehr schwer ist, solltest du möglicherweise die nächtliche Flüssigkeitszufuhr anpassen. Trag es im Windel-Tracker ein und überprüfe den Flüssigkeitshaushalt über den Tag hinweg.'),
  ('ac8ebb1f-1fc4-47f7-86d8-2eb0fa26e0a4', 'Feinmotorik der Finger 🧩', 'Dein Baby kann Formen schon geschickt richtig zuordnen. Entdecke jetzt im Bereich „Empfohlene Produkte“ altersgerechte Puzzles, die seine kognitiven Fähigkeiten weiter fördern.'),
  ('b322d3bf-6cd3-46c1-9a5f-bb9f3a106c60', 'Zeit zum Runterfahren 🎶', 'Ein aktiver Tag kann das Gehirn ermüden. Spiele bei „Weißes Rauschen“ Waldrauschen ab und schaffe im Zimmer eine beruhigende, schlaffördernde Atmosphäre.'),
  ('d93eedfc-78de-4d26-810d-89c2b8c71690', 'Gönn dir einen Kaffee ☕', 'Du bist vom Herumrennen den ganzen Tag völlig erschöpft! Finde auf der Karte „Mama-freundliche Orte“ ein Café mit Kinderspielbereich und gönn dir eine kleine Auszeit.'),
  ('fcfa5044-061e-4832-8787-ddd94f46ab93', 'Ein neues Wort entdeckt 🗣️', 'Welches neue Wort hat dein Baby heute gesagt?'),
  ('9a0a29d7-d513-4158-b204-99c831639c23', 'Zusammen und doch getrennt 👶', 'Spielt dein Kind im Park nicht mit den anderen Kindern, sondern beobachtet sie nur aus der Ferne? Das nennt man Parallelspiel! Frag Anacan AI nach spannenden Fakten über diese Phase der sozialen Entwicklung.'),
  ('f527de5c-afa8-4884-a173-da37070a2826', 'Kleine Haushaltshilfe 🧹', 'Während du den Boden fegst, wischt dein Kind mit einem Tuch über den Tisch? Halte diesen süßen Moment, in dem es Verantwortung übernimmt, gleich fest und mach ihn zu einer der schönsten Erinnerungen im Babyalbum.'),
  ('18518788-d8e2-4971-93f7-6fbf0592ca33', 'Hauen oder Schubsen 🛑', 'Holt dein Kind plötzlich mit der Hand aus, wenn es wütend ist? Frag Anacan AI, wie du mit Spielen angemessen auf dieses typische Verhalten im 20. Monat reagieren kannst.'),
  ('a6200253-33e2-4142-a4a9-811aa67d4feb', 'Du bist die Heldin des Tages 🧘‍♀️', 'Dein Kind schläft. Lass jetzt alle Hausarbeiten liegen. Schreib deine Gefühle in dein Stimmungstagebuch, mach entspannende Musik an und widme diesen Abend einfach nur dir selbst.'),
  ('eefd67fd-3835-4f65-abf3-9ced6b705e30', 'Geduldsprobe am Esstisch ⏱️', 'Braucht dein Kind 5 Minuten für einen Löffel? Starte den Ernährungstimer, bleib geduldig und analysiere die Entwicklung seines Appetits anhand des Berichts in der App.'),
  ('070b2f75-0440-4e85-b828-292900301f9e', 'Die Fantasiespiele beginnen 🧸', 'Gibt dein Kind seinem Teddy Wasser oder behandelt dich wie ein Arzt? Halte diese wunderbaren Momente der Empathie für die Zukunft fest, indem du sie als Videos mit Ton zum Babyalbum hinzufügst.'),
  ('388f83f4-0bb5-4306-abf6-b75f9dc65017', 'Eisenspeicher prüfen 🥩', 'Für aktive Muskeln und eine gesunde Entwicklung ist es wichtig, einer Blutarmut vorzubeugen. Prüfe mit dem Ernährungstracker die heutige Eisenaufnahme aus Fleisch und Hülsenfrüchten und gleiche mögliche Defizite direkt aus.'),
  ('9cb7efe6-c6c0-4032-89de-12eeec5119ee', 'Von Geräuschen zur Stille 🎶', 'Nach den Geräuschen von Fernseher und Spielzeug kann plötzliche Stille dein Kind erschrecken. Spiele im Zimmer bei den Klängen für weißes Rauschen das Geräusch eines Haartrockners ab und beobachte, wie sich der gleichmäßige Klang positiv auf die Schlafumgebung auswirkt.'),
  ('af623bf2-6a45-452d-a9c0-bd16d67bf74d', 'Pfannkuchenmonster 🥞', 'Dein Baby verweigert das Frühstück? Probiere bei den Babyrezepten das Rezept für zuckerfreie Bananenpfannkuchen aus. Es kann sie selbst in die Hand nehmen und essen – und bekommt dabei bestimmt Appetit.'),
  ('a7786d73-a362-4a32-a77f-3c09e4ab2ffb', 'Physikstunde mit Wasser 🛁', 'Wird dein Baby nie müde, in der Badewanne Wasser von einem Becher in den anderen zu gießen? Entdecke unter „Empfohlene Produkte“ unterhaltsame und beruhigende Wasserspielzeuge.'),
  ('ccc521b5-a8ef-4b74-a8d7-bf2ba2f22793', 'Kalziumschutzschild 🦴', 'Kalzium ist für Zähne und Knochen unverzichtbar. Prüfe mit dem Ernährungstracker, ob ihr heute die empfohlene Menge an Joghurt und Käse erreicht habt.'),
  ('e8d46282-de1c-4981-9242-f0dff7014b1d', 'Analysieren wir den Rhythmus ⏱️', 'Ist die Wachphase am Abend zu lang geworden? Starte den Schlaftimer und beobachte den Tagesrhythmus. Vielleicht ist genau jetzt der richtige Zeitpunkt, den Mittagsschlaf um 15 Minuten zu verkürzen.'),
  ('a1bb5dc0-7875-44dc-a4df-f9fa8c0a427f', 'Signale von Magen und Darm 💩', 'Die vollständige Umstellung auf feste Nahrung kann die Verdauung belasten. Trage die morgendliche Windel im Windeltracker ein und prüfe ganz einfach, ob ihr die Flüssigkeits- und Ballaststoffzufuhr anpassen solltet.'),
  ('c4d895de-4842-4a9b-ae46-1557c6e3d2cc', 'Natürliche Beruhigung 🍃', 'War der Tag voller Gefühlsausbrüche und Lärm? Spiele bei den Weißen Geräuschen sanftes Blätterrauschen ab – eine Wohltat für das Nervensystem deines Babys und für dein eigenes.'),
  ('f1307d3d-156d-45b5-82ac-2f5c2abfa1a3', 'Der Kampf ums Anziehen 👗', 'Hört das trotzige „Ich will dieses Oberteil nicht!“ gar nicht mehr auf? Verwandle das Anziehen in ein Spiel und erzähle deinem Baby, dass ihr für das Baby-Fotoshooting Fotos machen werdet. So gibt es morgens weniger Streit um die Kleidung.'),
  ('0daafb47-5c27-4a37-935b-b3612abf5506', 'Heldin des Tages 🌟', 'Jede neue Fähigkeit, die dein Baby täglich erlernt, ist auch dein Verdienst. Öffne das Stimmungstagebuch, notiere selbst die kleinste gute Tat, die du heute für dein Baby getan hast, und sei stolz auf dich!'),
  ('205f33e0-59b6-4cce-bdf2-72feb1805167', 'Auf der Suche nach gesunden Naschereien 🍪', 'Du suchst einen leckeren Snack ohne Zucker? Entdecke bei den Babyrezepten Bananen-Dattel-Kekse, die in nur 10 Minuten zubereitet sind.'),
  ('db60a4c8-3ab7-4727-9545-2ff3fea13946', 'Das trotzige Nein! 🛑', 'Dein Kind widerspricht bei allem und schreit? Lass dich von unserem Anacan AI-Assistenten zur Trotzphase im 21. Monat beraten und lerne, mit Gefühlsausbrüchen umzugehen.'),
  ('ec464aff-d0a0-4b3d-ac5c-7d32cf5dcf36', 'Überprüfen wir den Schlafrhythmus ⏱️', 'Wacht dein Kind nachts häufig auf? Analysiere die Übersicht im Schlaf-Timer. Vielleicht hilft es, den Mittagsschlaf etwas zu verkürzen, damit es abends müder ist.'),
  ('87662f03-ab51-47a9-bb0d-dc1172cdf859', 'Eine Extraportion Vitamine 🥗', 'Berechne mit dem Ernährungstracker den heutigen Vitaminbedarf und plane das Menü. Achte besonders auf ein ausgewogenes Verhältnis von Omega-3 und Vitamin D.'),
  ('a1ffdcb1-2aeb-4842-a0b3-6bc2096bceb7', 'Logikspielzeug 🧩', 'Dieses Alter ist ideal für Logikspiele. Entdecke unter den empfohlenen Produkten altersgerechte Puzzles und Formsortierspiele, um die Denkfähigkeit deines Kindes zu fördern.'),
  ('b4b68202-2497-420c-9cf0-d0f43130a249', 'Schreib dir alles von der Seele 📝', 'Nicht jeder Tag ist perfekt – und das ist ganz normal. Schreib deine heutigen Sorgen ins Stimmungstagebuch, lass den Stress los und gönn dir in Ruhe eine Pause.'),
  ('4dbfd2fe-196e-4f4f-9fd6-89ab8dff4f94', 'Wachstumsschub! 📏', 'Hast du das Gefühl, dass dein Kind plötzlich einen Wachstumsschub gemacht hat? Trage die neuen Werte in den Entwicklungs-Tracker ein und betrachte stolz seine gesunde Wachstumskurve.'),
  ('9167bebc-9c9c-4cbb-8cf3-b64e9ea99677', 'Zeit, Energie zu tanken 🔋', 'Vergiss dich selbst nicht! Bereite dir für den Morgen einen schnellen, leckeren und proteinreichen Smoothie aus unseren gesunden Rezepten zu und starte mit neuer Energie in den Tag.'),
  ('e61cda6e-e7ca-46f3-a40c-42185a9f8216', '5 Minuten Energie ⚡', 'Wenn dein Kind mittags schläft, stürz dich nicht gleich in die Hausarbeit. Bereite dir mit einem unserer gesunden Rezepte einen antioxidantienreichen Smoothie zu und tanke neue Energie.'),
  ('733a062a-9528-4b89-8399-8894cdcd37ab', 'Gemeinsam Bücher lesen 📖', 'Möchte dein Kind die Buchseiten selbst umblättern? Im Blog findest du einen tollen Artikel darüber, wie du in diesem Alter spielerisch die Freude am Lesen wecken kannst.'),
  ('840a48c0-60b0-4169-a7a4-bfd97c049d9d', 'Die Natur entdecken 🌳', 'Fühlt sich dein Kind zu Hause eingeengt? Finde unter den kinderwagenfreundlichen Orten einen weitläufigen, sicheren Park, in dem es sich in der Natur austoben kann.'),
  ('fc70b034-70d7-48ac-b093-b541c3d08e54', 'Morgendlicher Check 💧', 'Hast du die erste Windel des Tages gewechselt? Trage die Ausscheidungen in die App ein und behalte so ganz einfach im Blick, ob die Flüssigkeitszufuhr und Verdauung ausreichend sind.'),
  ('8139b24d-f8c3-4b60-b4f1-38bd25e609a6', 'Legt dein Kind den Löffel nicht aus der Hand? 🥄', 'Starte den Ernährungstimer. Analysiere, wie lange die Versuche, selbstständig zu essen, dauern, und überprüfe in der App die tägliche Nahrungsmenge.'),
  ('9cda88a3-f6c1-4cc3-92c3-5cb54bd45a91', 'Sandtherapie 🏖️', 'Hab keine Angst vor Schmutz! Entdecke im Bereich „Empfohlene Produkte“ gleich die besten Hilfsmittel für Spiele mit kinetischem Sand und andere sensorische Aktivitäten.'),
  ('f71cc78c-d1eb-4694-b94a-1843f80e2db1', 'Beruhigende Wellen 🌊', 'Kann dein Kind nach einem Tag voller aktiver Entdeckungen nicht einschlafen? Wähle bei den Weißen Geräuschen das Meeresrauschen aus, schaffe eine zauberhaft ruhige Atmosphäre im Zimmer und stimme dein Kind auf den Schlaf ein.'),
  ('3787f491-d618-4351-acd6-86ff87689c17', 'Schlagen und Schubsen 🛑', 'Schlägt oder beißt dein Kind plötzlich, wenn es wütend wird? Frage Anacan AI, wie du liebevoll mit diesem für den 21. Monat typischen Verhalten umgehen kannst.'),
  ('e29e6044-f61d-47fa-b1d7-8e16d2c4b2ce', 'Wie sieht es mit der Eiweißversorgung aus? 🍗', 'Eiweiß ist für das Wachstum deines Kindes unverzichtbar! Überprüfe mit dem Ernährungstracker die tägliche Nährstoffbalance und gleiche mögliche Defizite aus.'),
  ('e90a6ec1-ff62-4f86-8635-bb93512c7c35', 'Schlafanalyse mit Timer ⏱️', 'Ab ins Bett! Starte den Schlaftimer, analysiere den Schlafrhythmus, um sicherzugehen, dass dein Kind ausreichend schläft, und gönn auch dir etwas Ruhe.'),
  ('0ac93f21-93e2-449d-b93b-ae00befc33f7', 'Angst im Dunkeln? 🌌', 'Wird dein Kind unruhig, wenn du das Licht im Zimmer ausschaltest? Spiele unter „Weißes Rauschen“ die vertrauten Geräusche aus dem Mutterleib mit Herzschlag ab und schenke ihm ein Gefühl von Wärme und Geborgenheit.'),
  ('5831d6e0-9735-485f-be90-56915bc7047f', 'Jetzt bist du an der Reihe 🥗', 'Dein Kind schläft? Dann ab in die Küche! Entdecke unter den gesunden Rezepten für Frauen einen eiweißreichen Salat oder ein Detox-Wasser, das dir schnell neue Energie schenkt.'),
  ('5c1e8139-b38e-4666-8558-f6706af826d7', 'Kleine Künstler am Werk 🖍️', 'Dein Kind liebt es zu kritzeln? Selbst wenn die Kleidung voller Farbe ist – bleib gelassen! Füge diesen kreativen Moment gleich dem Babyalbum hinzu und halte ihn als lebenslange Erinnerung fest.'),
  ('04f3e5a5-25b9-471b-9c8e-e6c96050313b', 'Ein farbenfroher Schutzschild fürs Immunsystem 🛡️', 'Überprüfe mit dem Ernährungstracker, ob dein Kind heute ausreichend Vitamin C aufgenommen hat. In den Babyrezepten findest du passende Ideen mit buntem Gemüse.'),
  ('41231bd2-e2dd-4432-bc31-3952982f012e', 'Schon Zähne geputzt? 🪥', 'Läuft dein Kind schon beim Anblick der Zahnbürste davon? Sieh dir unter „Empfohlene Produkte“ musikalische Zahnbürsten oder Fingerzahnbürsten an und verwandle diese wichtige Pflegeroutine in ein lustiges Spiel.'),
  ('9603c325-693c-472c-b02b-2c75bd255571', 'Du bist die Heldin des Tages! 🌟', 'Trotz aller Trotzanfälle und Erschöpfung machst du das großartig! Öffne dein Stimmungstagebuch und schreibe heute etwas auf, wofür du dir selbst Beifall schenken möchtest.'),
  ('f9b61a4f-eba1-4cee-bf4a-958278a9300c', 'Der kleine Küchenchef zu Hause 👩‍🍳', 'Hilft dir dein Baby in der Küche und rührt in den Töpfen? Verschönere diesen lustigen, mehlbestäubten Moment mit den Koch-Stickern aus dem Baby-Fotoshooting.'),
  ('2c0cd78a-df37-49ab-8eae-44063551c7d9', 'Puzzle-Profi 🧩', 'Wird dein Baby immer geschickter darin, Formen richtig zuzuordnen? Entdecke unter „Empfohlene Produkte“ geometrische Puzzles für 21 Monate alte Kinder, die spielerisch das Denkvermögen fördern.'),
  ('eeefba30-2a67-4d29-87df-2dbd7f03271f', 'Lust am Seitenzerreißen 📖', 'Zerreißt dein Baby die Seiten, statt sich das Buch anzusehen? Lies jetzt im Bereich „Blogs“, wie du damit umgehen kannst, ohne die Freude am Lesen zu beeinträchtigen.'),
  ('f7f548f7-29ae-4098-8eb1-12f16f94c4b9', 'Die Phase des Spielens mit Essen 🥣', 'Wirft dein Baby den Löffel weg und erkundet das Essen mit den Händen? Starte den Ernährungstimer, beobachte die Entwicklung des Appetits und begleite diese Phase der sensorischen Entwicklung mit Geduld.'),
  ('3512adbc-96b2-42e9-8a54-b673dc404876', 'Abendliches Kichern 📸', 'Verpasse nicht diese lustige Aktion vor dem Schlafengehen! Nimm sofort ein Video auf und füge es dem Babyalbum hinzu – so wird die Müdigkeit des Tages zu einem Lächeln.'),
  ('42cda594-bd4d-4a45-a1f6-1f894ad11fe7', 'Neue Wörter sind unterwegs! 🗣️', 'Macht dein Baby viele Laute, sagt aber noch keine vollständigen Wörter? Erfahre von Anacan AI, welche Spiele für zu Hause und welche Silbenübungen den passiven Wortschatz besonders wirksam aktivieren.'),
  ('ad6e0b2f-1d5f-4db6-82ee-93ed492c1c54', 'Sind die Schuhe zu klein geworden? 👟', 'Stolpert dein Baby in letzter Zeit beim Laufen häufiger? Vielleicht sind die Füße gewachsen! Trage die aktuellen Maße in den Entwicklungs-Tracker ein und verfolge die Entwicklung.'),
  ('8ae66558-ee37-4cd1-9102-46bab1a97b21', 'Genuss in 5 Minuten! 🥗', 'Isst du mittags oft nur schnell eine Kleinigkeit im Stehen? Bereite aus den gesunden Rezepten für Frauen einen Avocado-Toast zu, der lange satt macht und sofort neue Energie schenkt.'),
  ('03d03133-0370-4630-9d2e-153f9459d86d', 'Wacht dein Baby schreiend auf?', 'Schalte das Geräusch aus dem Mutterleib unter „Weißes Rauschen“ ein, ohne das Licht anzumachen. So fühlt sich dein Baby geborgen und findet leichter wieder in den Schlaf.'),
  ('8ed6f8ef-f210-4aaa-96f8-4667b80d657e', 'Zu allem Nein! 🛑', 'Lehnt dein Baby jeden Vorschlag ab? Statt gegen seinen Trotz anzukämpfen, frage Anacan AI direkt, wie du ihm passende Wahlmöglichkeiten anbieten kannst.'),
  ('a3aeb0cd-d49a-4a1a-a82c-e3dc837e022c', 'Flüssigkeitszufuhr am Abend 🚰', 'Wenn die Windel morgens sehr schwer ist, kann es sinnvoll sein, die Trinkmenge am Abend anzupassen. Trage sie im Windel-Tracker ein und sieh dir die tägliche Statistik an.'),
  ('0b3896bc-de1d-4dd2-b68d-bd0aa3890750', 'Dauert der Mittagsschlaf zu lange? ⏱️', 'Wehrt sich dein Baby abends gegen das Zubettgehen? Starte den Schlaftimer und beobachte den Schlafrhythmus. Vielleicht wacht es zu spät vom Mittagsschlaf auf?'),
  ('7c7fefdb-4a4d-41d2-bca8-742c9430dc8d', 'Kalzium und Knochen 🦴', 'Das schnelle körperliche Wachstum erfordert ausreichend Kalzium. Ermittle mit dem Ernährungstracker den Bedarf an Käse und Joghurt. Falls noch etwas fehlt, sieh dir die Baby-Rezepte an.'),
  ('c7f42861-81dc-4ed2-b93f-7c30709d92ed', 'Fühlst du dich erschöpft? 🔋', 'Ist deine Energie aufgebraucht? Greife nicht gleich zu Süßigkeiten. Bereite mit unseren gesunden Rezepten für Frauen zuckerfreie Energiekugeln zu, die dir schnell neue Kraft geben.'),
  ('2ecfbac7-2e44-4661-8705-95fe2f59e9a9', 'Verabschiede dich vom Perfektionismus 🧘‍♀️', 'Zu Hause herrscht Chaos? Das ist völlig in Ordnung! Schreibe deine Gefühle in dein Stimmungstagebuch. Denk daran: Eine glückliche Mama ist wichtiger als ein perfektes Zuhause.'),
  ('31e46f9b-eb74-4b8a-8369-6c0eb709b2d1', 'Auch du brauchst eine Pause ☕', 'Geh raus und atme ein wenig durch! Finde unter den mama-freundlichen Orten ein Café mit Spielecke in deiner Nähe und genieße deinen heißen Kaffee in Ruhe.'),
  ('a3eb6f02-e9da-422e-a243-1f395cf4661e', 'Verschiebt sich die Schlafenszeit? ⏱️', 'Ist die Wachphase am Abend länger geworden? Starte den Schlaf-Timer, analysiere den Schlafrhythmus und berechne die Schlaffenster neu.'),
  ('aac102d8-edd5-4708-bab2-8cf3fcc9802c', 'Ist die Verdauung träge? 🚽', 'Achte beim morgendlichen Windelwechsel auf den Stuhlgang. Bei Verstopfung kannst du dies in der App eintragen. Vergiss außerdem nicht, ballaststoffreiche Lebensmittel wie Birne und Hafer in den Speiseplan aufzunehmen.'),
  ('5bf406ee-d6c9-4691-8b5e-2df617ed2939', 'Die Natur entdecken 🌳', 'Fühlt sich dein Baby zu Hause eingeengt? Suche unter den mama-freundlichen Orten nach einem sicheren Park mit großem Sandkasten und Schaukeln und genießt gemeinsam die frische Luft.'),
  ('ad873c49-3118-429c-a9cf-3328699e514f', 'Nudelspaß! 🍝', 'Möchte dein Baby nicht am Esstisch sitzen? Entdecke unter den Babyrezepten bunte Nudelgerichte mit Gemüse und lenke seine Aufmerksamkeit wieder auf den Teller.'),
  ('dca5184f-26ea-4b5e-b78d-2f4c36c6bf42', 'Die Kraft gleichmäßiger Geräusche 🌬️', 'Macht die Stille deinem Baby Angst? Spiele unter „Weißes Rauschen“ das Geräusch eines Haartrockners oder Ventilators ab und beobachte, wie es in der Schlafumgebung ein Gefühl von Geborgenheit vermittelt.'),
  ('04ea5cc7-5f44-4fc9-ad82-59f8e294f0a5', 'Lobe dich selbst! 🌟', 'Hast du es heute geschafft, dein Baby anzuziehen, ohne dass es geweint hat? Halte selbst deinen kleinsten Erfolg im Stimmungstagebuch fest und schenke dir für deine Fähigkeiten als Mama einen tosenden Applaus.'),
  ('5d85dda7-f62e-4490-8b4e-2ca037fd60ac', 'Schutzschild für das Immunsystem 🛡️', 'Seid ihr auf den Jahreszeitenwechsel vorbereitet? Prüfe mit dem Ernährungstracker, ob dein Baby heute ausreichend Vitamin C aufgenommen hat, und passe den Speiseplan an.'),
  ('680f971c-231a-40e8-a772-413975915698', 'Hauen und Schubsen 🛑', 'Haut oder schubst dein Baby, wenn es plötzlich wütend wird? Frage Anacan AI, wie du mit diesem herausfordernden Verhalten im Alter von 21.5 Monaten spielerisch umgehen kannst.'),
  ('4bdcd931-fb36-41ca-9759-7a92226d97f9', 'Woran erkennst du, dass dein Baby satt ist? ⏱️', 'Wenn dein Baby anfängt, das Essen wegzuwerfen oder auszuspucken, signalisiert es: Ich bin satt. Stoppe den Ernährungstimer, vermerke, dass die vorgesehene Menge erreicht wurde, und analysiere den Appetit.'),
  ('be36c558-6f81-4ee5-9a59-f79497bbff2d', 'Der tägliche Zahnputz-Kampf 🪥', 'Läuft dein Kind weg, sobald es die Zahnbürste sieht? Schau dir unter „Empfohlene Produkte“ musikalische Zahnbürsten oder Fingerzahnbürsten an und verwandle diese wichtige Hygieneroutine in ein lustiges Spiel.'),
  ('cd9296b3-74e7-4229-8871-9f5ee4fe977a', 'Mamas Flüssigkeitshaushalt 💧', 'Hast du Kopfschmerzen? Vielleicht hast du beim Hinterherlaufen hinter deinem Kind zu wenig getrunken. Bereite Detox-Wasser nach den gesunden Rezepten für Frauen zu und bringe deinen Körper wieder in Schwung.'),
  ('2fbfd933-5095-452a-808e-4209aab75b80', 'Auch du brauchst soziale Kontakte 👯‍♀️', 'Bist du es leid, dich nur mit deinem Kind zu unterhalten? Finde unter „Mutterfreundliche Orte“ Einrichtungen mit Spielgruppen und lerne andere Mütter kennen.'),
  ('a7d068ee-6f98-437e-b7f3-f2284f8fbdbc', 'Kleiner Nachahmer 📱', 'Tut dein Kind so, als würde es wie du telefonieren, und ahmt deine Gesten nach? Kinder sind unser größter Spiegel!'),
  ('bf157f3f-185f-45b5-aae0-091b2cf00653', 'Zusammen und doch getrennt 👶', 'Spielt dein Kind im Park nicht mit den anderen Kindern, sondern beobachtet sie nur? Das nennt man Parallelspiel! Entdecke im Bereich „Blogs“ interessante Fakten über diese Phase der sozialen Entwicklung.'),
  ('9faf82e4-78ff-4782-a4bb-0d745a808c97', 'Protest gegen alles Grüne 🥦', 'Lehnt dein Baby Gemüse ab? Entdecke unter „Rezepte für Babys mit Beikoststart“, wie du es in leckeren Pfannkuchen verstecken kannst.'),
  ('c2142ff9-9553-4737-9602-95ee907b4599', 'Lass dich nicht von der Erschöpfung überwältigen 🛋️', 'Wolltest du heute einfach alles stehen und liegen lassen? Das ist ganz normal! Öffne dein Stimmungstagebuch, schreibe auf, was dich innerlich belastet, und widme diesen Abend nur dir selbst.'),
  ('cc7b1b1f-1c7c-4424-996a-a223a00c890e', 'Bleibt die Windel trocken? 🧻', 'Zeit für den Morgencheck! Wenn die Windel längere Zeit trocken bleibt, rückt das Töpfchentraining näher. Trage es im Windel-Tracker ein und sieh dir die Statistik an.'),
  ('3e9ffaf8-f631-4e99-946e-651b683eab7f', '„Mama, komm!“ – erste Sätze 🗣️', 'Versucht dein Kind schon, zwei Wörter zu einem Satz zu verbinden? Das ist ein großer Sprung in der Sprachentwicklung! Halte seine ersten kleinen Sätze als Erinnerung im Entwicklungstracker fest.'),
  ('473def83-9d3b-4698-becd-a16f81aed11d', 'Wutanfälle im Supermarkt 🛒', 'Dein Kind hat sich auf den Boden geworfen, weil du ihm nicht gekauft hast, was es wollte? Keine Panik. Ignoriere die Blicke der anderen, bleib ruhig und begib dich auf seine Augenhöhe.'),
  ('fdbb311e-3b42-4723-986f-c65a632fb53e', 'Lass den emotionalen Ballast los 📝', 'War es ein schwieriger Tag? Schreib den heutigen Stress in dein Stimmungstagebuch und lass alles raus. Alle Mütter erleben solche Wutanfälle in der Öffentlichkeit – du bist nicht allein.'),
  ('6b045729-7aac-44f1-99aa-a2dbeb7985f2', 'Eine Liste kann den Tag retten 🛒', 'Hat dich dein Gedächtnis schon wieder im Stich gelassen? Du musst dir nicht jede Kleinigkeit merken, die zu Hause ausgegangen ist. Trag sie sofort in die Einkaufsliste ein – dein Partner kümmert sich darum.'),
  ('7abb85ab-0b3c-4464-a5f4-15bfe391f1ba', 'Den Ball kicken ⚽', 'Versucht dein Kind, einen Ball auf dem Boden mit dem Fuß zu treten? Sein Gleichgewicht und die Koordination der Beine werden immer besser. Spielt eine kleine Runde Pässe miteinander.'),
  ('eec0d21f-e4e1-482b-ae4c-9c9f182e42a1', 'Magische Stimmung für die Nacht 🪄', 'Fällt deinem Kind das Einschlafen schwer? Erstelle in den intelligenten Märchen eine ganz eigene Geschichte und lies sie ihm vor.'),
  ('51155148-f9ec-40a7-99a1-3f09cffe59c1', 'Papa übernimmt 👨‍👧', 'Ist deine Geduld am Ende? Schließ die Zimmertür und lass das Kind mit seinem Papa allein. Heute Abend darf er das Kommando auf dem heimischen Spielplatz übernehmen.'),
  ('f29d2f2b-6e38-44f2-9d6b-467c0c3431e7', 'Der Kampf ums Anziehen 👗', '„Dieses Oberteil will ich nicht!“ – hat die Trotzphase begonnen? Erfahre von Anacan AI, wie du morgendliche Kleidungskrisen reduzieren und deinem Kind freie Wahlmöglichkeiten geben kannst.'),
  ('2a640acf-5bf6-44d4-b56f-00e902c2ddd2', 'Der Wunsch nach Selbstständigkeit 🥣', 'Will dein Kind dir den Löffel nicht geben? Starte den Ernährungstimer und analysiere, wie lange dieser Versuch, selbstständig zu essen, dauert. Lächle einfach über das verschüttete Essen hinweg.'),
  ('cb94164a-0ea2-471c-9c17-a09778ea707c', 'Trennungsangst? 🌌', 'Weint dein Kind dir hinterher, sobald du das Zimmer verlässt? Spiele unter „Weißes Rauschen“ die Geräusche aus dem Mutterleib (Herzschlag) ab und schenke ihm so das vertraute Gefühl von Wärme und Geborgenheit.'),
  ('d3ae908a-552f-4504-a171-436173eaeceb', 'Der Kampf ums Zähneputzen 🪥', 'Macht dein Kind den Mund fest zu, sobald es die Zahnbürste sieht? Sieh dir unter „Empfohlene Produkte“ musikalische Zahnbürsten oder Fingerzahnbürsten an und verwandle diese Hygieneroutine in ein lustiges Spiel.'),
  ('4932b8a8-d024-498c-ba06-d790b59bc198', 'Sei nachsichtig mit dir 🧘‍♀️', 'Ist heute alles schiefgelaufen? Schreibe deine inneren Gedanken in dein Stimmungstagebuch, verzeih dir selbst, atme tief durch und ruh dich aus.'),
  ('ed014436-2469-48a6-b579-7bce93de1ae7', 'Der Wortschatz wächst 🗣️', 'Bildet dein Kind immer mehr Zweiwortsätze? Frage Anacan AI direkt, wie du diese großartige Sprachentwicklung fördern und Gespräche mit deinem Kind führen kannst.'),
  ('ed579060-f78c-4890-b8e4-2bb0c7729792', 'Die Farbe des Stuhlgangs 💩', 'Notiere sie beim Windelwechsel! Nutze die Ernährungsübersicht, um das Gleichgewicht von Flüssigkeit und Ballaststoffen im Blick zu behalten und Verstopfung vorzubeugen.'),
  ('15f9bb81-a16f-4753-a3f5-a2b604b16a46', 'Schlafen an der frischen Luft 🌳', 'Kann dein Kind zu Hause nicht schlafen? Finde unter „Mama-freundliche Orte“ einen ruhigen, grünen Park. Die frische Luft wird sowohl seinen Appetit als auch seinen Schlaf fördern.'),
  ('53335520-c239-4dc6-bb98-8950aeac052d', 'Versteckspiel mit Gemüse 🥕', 'Dein Baby lehnt Karotten und Spinat ab? Entdecke in den Babyrezepten, wie du diese Vitaminbomben geschickt in leckeren Pfannkuchen verstecken kannst.'),
  ('9cc1439a-0d58-4e5e-94b1-3125467bf825', 'Hab kein schlechtes Gewissen 💖', 'Bist du heute einmal lauter geworden? Mach dir keine Vorwürfe. Schreib deine Gefühle in dein Stimmungstagebuch – du bist trotzdem die beste Mama für dein Baby.'),
  ('bd4e1f9a-2949-4f64-b861-47344e3cdbfc', 'Die endlose Show am Esstisch ⏱️', 'Dein Baby spielt mit dem Essen, isst aber nicht? Starte den Ernährungstimer, behalte die Dauer der Mahlzeit im Blick und analysiere genau, wie sich sein Appetit entwickelt.'),
  ('31a9cc16-de41-4012-b357-b74232182120', 'Du bist die Heldin des Tages 🌟', 'Jede neue Fähigkeit, die dein Baby erlernt, ist auch dein Verdienst. Öffne dein Stimmungstagebuch und schreib heute etwas auf, für das du dir selbst stehende Ovationen geben würdest!'),
  ('39267d40-2480-48f4-9716-e425031ba3b3', 'Gemeinsam und doch getrennt 👶', 'Spielt dein Baby im Park nicht mit den anderen Kindern, sondern schaut ihnen nur zu? Das nennt man Parallelspiel! Lies im Blog mehr über diese gesunde Phase der sozialen Entwicklung.'),
  ('7ae07c2d-565f-4b45-bebf-b9e3ab799a99', 'Zuckerfreier Snack 🍪', 'Du brauchst keine Kekse aus dem Supermarkt. Entdecke in den Babyrezepten gesunde Leckereien mit Datteln und Äpfeln, die du zu Hause in nur 10 Minuten zubereiten kannst.'),
  ('4c3b97db-69e0-4349-8a8d-b599fed49f3d', 'Ist die Windel nachts voll? 🧻', 'Wenn die Windel morgens sehr schwer ist, kann das den Nachtschlaf stören. Trag die Ausscheidung im Windel-Tracker ein und analysiere die Statistik, um die Flüssigkeitszufuhr am Abend anzupassen.'),
  ('c15f640c-d99c-497d-be3f-c7f256e90fd8', 'Kleine Küchenentdecker 🥦', 'Dein Baby möchte mit dir kochen? Entdecke in den Rezepten einfache, gemüsereiche und leckere Muffins, die du gemeinsam mit deinem Baby ab Beikostbeginn zubereiten kannst.'),
  ('53a89401-1ea0-43b5-9469-65a0d422f72c', 'Endlose Show am Esstisch 🥣', 'Dein Baby spielt mit dem Essen und wirft es auf den Boden, isst aber nichts? Starte den Ernährungstimer und analysiere die Entwicklung seines Appetits genau anhand der Grafik in der App.'),
  ('86da0f7a-f021-4c65-aed2-e8e15433a92d', 'Große Freude am Drehen 🌀', 'Dreht dein Baby ununterbrochen Räder oder Deckel? Lies in den Blogbeiträgen mehr über dieses besondere motorische Bedürfnis und seine Bedeutung für die kognitive Entwicklung.'),
  ('9ea6bc21-5003-4afe-8fca-e2eebb549250', 'Sandtherapie 🏖️', 'Hab keine Angst vor Schmutz! Finde unter den mama­freundlichen Orten einen Platz mit Sandkasten. Das Berühren von Sand ist ideal für die sensorische Entwicklung.'),
  ('081299bb-b5c9-4af5-8361-9fa39bbdf0bf', 'Hat dein Baby Verstopfung? 🚽', 'Achte beim morgendlichen Windelwechsel auf den Stuhlgang. Bei Verstopfung kannst du sie in der App eintragen und unter den Rezepten für Babys, die mit Beikost beginnen, ballaststoffreiche Lebensmittel wie Birne und Hafer auswählen.'),
  ('a11b2562-1cd1-41dc-ac6f-d1a7d36b53bb', 'Kleiner Künstler bei der Arbeit 🎨', 'Malt dein Baby beim Kritzeln auch sich selbst an? Entdecke unter den empfohlenen Produkten die bei Müttern beliebtesten ungiftigen, abwaschbaren Farben.'),
  ('f9d59314-c8fe-45fa-9d77-efb82ec57626', 'Abendliches Lachen 📸', 'Verpasse nicht diesen lustigen Moment vor dem Schlafengehen!'),
  ('34d9fbb9-7747-4964-9067-399afa7f0a7c', 'Natürliche Entspannung 🍃', 'Dein Kind schläft. Vergiss die Hausarbeit! Bereite dir nach einem unserer gesunden Rezepte für Frauen einen Melissentee zu, mach es dir auf dem Sofa bequem und genieße einfach die Stille.'),
  ('e79393de-a250-4c25-b9a8-93a1bc3692aa', 'Vitamin-C-Schutzschild 🍊', 'Ein starkes Immunsystem ist wichtig. Prüfe heute mit dem Ernährungstracker, ob dein Kind genügend Vitamin C aufgenommen hat, und bringe mehr Farbe auf den Speiseplan.'),
  ('1e63b6e0-14e2-4999-89f7-2f0db3539031', 'Nächtliches Aufwachen ⏱️', 'Starte den Schlaf-Timer! Anhand der statistischen Auswertung des Timers kannst du sofort erkennen, ob dein Kind unter Nachtschreck leidet oder gerade eine Schlafregression durchmacht.'),
  ('8665ce13-4bbc-4643-86cd-402909af004b', 'Eisenbedarf 🥩', 'Versorge die kleinen Muskeln mit Energie! Prüfe mit dem Ernährungstracker, ob dein Kind heute genug Eisen aufgenommen hat, und passe den Speiseplan entsprechend an.'),
  ('2097babe-f9a8-45d7-927c-24d3ef08f38a', 'Fröhliches Kinderlachen 📸', 'Verzieht dein Baby das Gesicht oder lacht es dich fröhlich an? Verziere diesen süßen Moment mit Stickern aus dem Baby-Fotoshooting und füge ihn als bleibende Erinnerung zum Album hinzu.'),
  ('3d45eb72-a379-4b0c-95b5-43a9f90cd232', 'Die beruhigende Kraft gleichmäßiger Geräusche 🎶', 'Nach einem lauten Tag kann plötzliche Stille dein Baby erschrecken. Spiele unter „Weißes Rauschen“ das Geräusch eines Föhns ab und schaffe so eine geborgene Schlafumgebung.'),
  ('af588f6b-bdb1-4b34-b380-81bc42d5db3f', 'Mamas Akku 🔋', 'Deine Energie ist aufgebraucht? Greife nicht gleich zu Süßigkeiten! Bereite mit den gesunden Rezepten für Frauen einen proteinreichen Erdnussbutter-Smoothie zu, der dir schnell neue Kraft gibt.'),
  ('3f0a8eb7-b5c5-4230-90cc-9ba54d5ff248', 'Wird die Kleidung schon wieder zu eng? 📏', 'Da ist wohl ein Wachstumsschub im Gange! Trage die aktuelle Körpergröße und Schuhgröße in den Entwicklungstracker ein und beobachte stolz, wie die Wachstumskurve ansteigt.'),
  ('5bace5b1-8b66-491f-869e-157ff26e9bbf', 'Knobelspaß 🧩', 'Hat dein Kind genug von den immer gleichen Spielsachen? Entdecke unter „Empfohlene Produkte“ altersgerechte und sichere Puzzles, die seine Denkfähigkeit fördern.'),
  ('e03c5d95-be6c-414b-b518-86431da64323', 'Plötzliches Schlagen und Beißen 🦖', 'Wird dein Kind aggressiv, wenn es wütend ist? Erfahre mit Anacan AI, wie du dieses Verhalten spielerisch und behutsam verändern kannst.'),
  ('81f2ea67-6d6b-45a8-9d3f-bdbc71d94739', 'Trotz bei der Kleiderwahl 👗', 'Will dein Kind im Sommer den dicken Pullover und im Winter das Sommerhemd tragen? Es entwickelt gerade seinen eigenen Willen. Lege zwei passende Kleidungsstücke bereit und überlasse ihm mit der Frage „Welches möchtest du?“ die Wahl.'),
  ('c6ce4007-ba3b-4772-8fba-7c4797ad17dd', 'Frische Luft ist die beste Medizin 🌳', 'Ist dein Kind sehr unruhig und hält es zu Hause kaum aus? Prüfe das Wetter, zieh es passend an und macht euch gleich auf den Weg in den Park. Die Natur wirkt oft am schnellsten beruhigend.'),
  ('02902252-366d-405a-a62b-9c6f129b4a84', 'Wie entwickelt sich die Intelligenz? 🧠', 'Lies im Blog unbedingt den Artikel über Spiele für zu Hause, die bei 21.5 Monate alten Kindern die Wahrnehmung von Farben und Formen fördern und das Gehirn stimulieren.'),
  ('08bbbba1-9e53-4379-a09e-82d1079f7df6', 'Eisenreserven prüfen 🥩', 'Damit die aktiven Muskeln gut versorgt sind, sollte keine Blutarmut vorliegen. Prüfe mit dem Ernährungstracker die heutige Eisenaufnahme und gleiche mögliche Defizite direkt aus.'),
  ('cd9b8bec-56d4-42a3-a245-f71b148a61ef', 'Von Geräuschen zur Ruhe 🎶', 'Plötzliche Stille nach lauten Spielen kann dein Kind erschrecken. Spiele im Zimmer unter „Weißes Rauschen“ das Geräusch eines Haartrockners ab und beobachte, wie sich der gleichmäßige Klang positiv auf den Schlaf auswirkt.'),
  ('54f26234-4c50-45b3-9088-6a5b0c08fcd2', 'Mamas Flüssigkeitshaushalt 💧', 'Hast du Kopfschmerzen? Vielleicht hast du beim Hinterherlaufen hinter deinem Kind zu wenig getrunken. Bereite mit unseren gesunden Rezepten Detox-Wasser zu und bring deinen Körper wieder in Schwung.'),
  ('a27861d3-4efc-4b58-bec5-f3117fe589e3', 'Sortierspiele 🔴🔵', 'Sortiert dein Kind gern die roten Dinge auf die eine und die blauen auf die andere Seite? Frag Anacan AI nach Spielideen, um diese Förderung des logischen Denkens noch unterhaltsamer zu gestalten.'),
  ('d5617275-bfe2-4829-8f3f-d3b94dc34cfe', 'Analysieren wir den Tagesrhythmus ⏱️', 'Ist die Wachphase am Abend zu lang geworden? Starte den Schlaf-Timer und beobachte den Schlafplan. Vielleicht ist jetzt genau der richtige Zeitpunkt, den Mittagsschlaf um 15 Minuten zu verkürzen.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_de = v.t, body_de = v.b
FROM (VALUES
  ('e02612f3-415f-450d-9411-e60c3bd32d09'::uuid, 'Der Klang der Stille 🌧️', 'Nach einem besonders turbulenten Tag braucht das Gehirn Zeit, um herunterzufahren. Spiele unter den Weißen Geräuschen Regengeräusche ab und schaffe so auf natürliche Weise eine ruhige Schlafumgebung.'),
  ('3dca59c4-0add-4ccb-919d-3806c0dfdbf4', 'Natürliche Beruhigung 🍃', 'War der Tag voller Wutanfälle und Lärm? Spiele unter den Weißen Geräuschen Blätterrauschen ab und schenke damit sowohl seinem als auch deinem Nervensystem wohltuende Entspannung.'),
  ('3f5ef83a-d114-41da-8dd2-6bd3c11c45e8', 'Energie in 5 Minuten ⚡', 'Stürze dich morgens nicht sofort in die Hausarbeit. Bereite dir unter den gesunden Rezepten ein antioxidantienreiches Beeren-Porridge zu und tanke neue Energie.'),
  ('e5117ef0-d242-45f1-b114-50b3bfca72d9', 'Auch du brauchst Gesellschaft ☕', 'Bist du es leid, nur mit deinem Kind zu sprechen? Finde unter den mama-freundlichen Orten beliebte Kindercafés, in denen sich viele Mütter treffen, und knüpfe neue Kontakte.'),
  ('622216cc-100d-4e85-95dc-7d70e41c5761', 'Es möchte selbst essen 🥣', 'Gibt es dir den Löffel nicht? Starte den Ernährungstimer und finde heraus, wie lange dieser Versuch der Selbstständigkeit dauert. Lächle einfach über das Essen, das danebenlandet.'),
  ('9387504c-dde1-4fdb-977d-53c3dfbb83a2', 'Sicher auf Entdeckungstour ⚠️', 'Schränke, Schubladen ... Für kleine Entdecker können sie gefährlich sein! Sieh dir unter den empfohlenen Produkten Möbelsicherungen und Sicherheitsschlösser an.'),
  ('bdef77ef-7476-4b14-a4a3-51d31635951f', 'Analysieren wir den Rhythmus ⏱️', 'Ist die Wachzeit am Abend zu lang geworden? Starte den Schlaftimer. Vielleicht ist jetzt genau der richtige Zeitpunkt, den Tagschlaf um 15 Minuten zu verkürzen.'),
  ('1221d1a0-4818-4be5-bd89-1e05d41e52f3', 'Mamas Rückenschmerzen 🧘‍♀️', 'Tut dir vom vielen Hochheben der Rücken weh? Kümmere dich um deinen Körper und bereite dir unter den gesunden Rezepten einen entzündungshemmenden und regenerierenden Grüntee mit Ingwer zu.'),
  ('5e592d03-eefe-420f-a53e-496dd3dda1cc', 'Streit wegen des falschen Bechers? 🥤', 'Es gab einen riesigen Wutanfall, weil du das Wasser im blauen statt im roten Becher serviert hast? Frag Anacan AI sofort, wie du solche scheinbar absurden Krisen gelassen meistern kannst.'),
  ('5fa9e0c4-2198-4898-832b-73dabf54c160', 'Schreib dir alles von der Seele 📝', 'Dein Baby hat heute ununterbrochen geweint und du bist völlig erschöpft. Mach dir keine Vorwürfe. Schreib all deine Erschöpfung im Stimmungstagebuch nieder, um den Kopf freizubekommen und dich auszuruhen.'),
  ('17a5c3c0-5b0c-46d3-a055-3e4119a58d57', 'Lass dein Baby die Geschichte erzählen 📖', 'Dein Baby betrachtet die Bilder im Buch und erzählt etwas in seiner eigenen Sprache? Halte diesen wundervollen Moment voller Fantasie sofort als Video mit Ton im Babyalbum fest und bewahre ihn für die Zukunft auf.'),
  ('200bc386-90fc-4565-9a45-00b11604777d', 'Raus aus den eigenen vier Wänden 🌳', 'Dein Baby kann seine Energie zu Hause nicht abbauen und stellt alles auf den Kopf? Öffne die Karte mit kinderfreundlichen Orten, finde einen Park mit einer sicheren Fläche zum Herumtoben und geht an die frische Luft.'),
  ('f2808bcb-7bbf-4422-8d7a-f49af045384f', 'Will dein Baby nicht teilen? 🧸', 'Will dein Baby im Park niemandem sein Spielzeug geben? Lies im Blog unbedingt den praktischen Artikel darüber, wie du einem 22 Monate alten Kind beibringst, beim Spielen abzuwechseln.'),
  ('5ba12c84-c569-4cd8-9800-87090cc15d44', 'Ein Schutzschild aus Kalzium 🦴', 'Kalzium ist für Knochen und Zähne unverzichtbar. Prüfe mit der Ernährungskontrolle, ob dein Baby heute genug Joghurt und Käse gegessen hat.'),
  ('7ecc82ad-1a38-4c53-9465-dd5ae12ea103', 'Sind die Schuhe zu eng? 📏', 'Stolpert dein Baby in letzter Zeit häufig beim Laufen? Vielleicht sind seine Füße gewachsen! Trage die aktuelle Körpergröße und die Maße in den Gewichtstracker ein, um die körperliche Entwicklung zu verfolgen.'),
  ('d79dc60f-8bf8-4657-a15d-609886c6c332', 'Wirft dein Baby das Essen auf den Boden? 🥣', 'Wenn dein Baby anfängt, den Löffel und das Essen vom Tisch zu werfen, ist es vielleicht satt oder gelangweilt. Stoppe den Ernährungstimer, analysiere den Appetitverlauf in der Grafik und beende die Mahlzeit.'),
  ('1a8b991b-0214-44d5-b2fa-cca54722c709', 'Das Kunstwerk an der Wand 🎨', 'Hat dein Kind einen Stift genommen und die Wand bemalt? Nicht ärgern! Halte diesen süßen Streich mit den lustigen Rahmen im Baby-Fotoshooting fürs Album fest und lächle einfach darüber.'),
  ('5ded1b01-b65d-40da-8990-d4cd09688a69', 'Plötzliches Aufwachen ist zurück? ⏱️', 'Wacht dein Kind mitten in der Nacht weinend auf? Sieh dir den Verlauf im Schlaf-Timer an. Wenn der Tagschlaf zu spät endet, fällt es abends schwerer, in den Tiefschlaf zu finden.'),
  ('79c4c89f-ba17-4c97-96b0-f5dc444414e9', 'Mamas Kaffeepause ☕', 'Vergiss dich selbst nicht! Bereite dir nach unseren gesunden Rezepten für Frauen einen energiespendenden Hafer-Snack zu und genieße deinen Kaffee.'),
  ('178de938-0734-4759-bd61-91671bd355ba', 'Die richtige Wahl fürs Töpfchen 🚽', 'Jetzt beginnt die visuelle Vorbereitung aufs Töpfchentraining! Sieh dir unter „Empfohlene Produkte“ unbedingt die bequemsten und ansprechendsten Töpfchenmodelle an, die von Müttern getestet wurden.'),
  ('2f6cc31a-8b1b-415e-861a-b476799ab26e', 'Wie steht es um die Omega-3-Versorgung? 🐟', 'Für die schnelle Gehirnentwicklung sind Fisch oder Walnüsse besonders wichtig! Prüfe mit dem Ernährungstracker die Omega-3-Aufnahme dieser Woche und passe den Speiseplan gleich an.'),
  ('f1e65e7a-efb2-4ee4-9b90-639511a93965', 'Du musst nicht perfekt sein 💖', 'Heute herrscht zu Hause Chaos und das Essen kam zu spät? Das macht nichts! Schreibe deine Gedanken ins Stimmungstagebuch und denke daran, dass dein Kind dich genauso liebt, wie du bist.'),
  ('0ec68466-1a64-4bc2-ab11-6f19a539925d', 'Viel Wasser, leichte Verdauung 💧', 'Wie funktioniert die Verdauung deines aktiven kleinen Schatzes? Trage beim Windelwechsel deine Beobachtungen ein. Besteht ein Verstopfungsrisiko, findest du in der App Empfehlungen für natürlich ballaststoffreiche Lebensmittel.'),
  ('60b3ac1d-dc8e-4802-b644-6bc09bfcea1f', 'Kein Streit mehr beim Essen ⏱️', 'Wirft dein Kind am Tisch den Löffel weg? Stoppe den Ernährungstimer – dein Kind ist satt. Analysiere den Appetitverlauf und vermeide es, dein Kind zum Essen zu zwingen.'),
  ('bafa81ec-ed9b-4642-a5cd-3249a43a8c84', 'Hauen oder schubsen 🛑', 'Haut dein Kind plötzlich zu, wenn es wütend wird? Wende dich an Anacan AI und erfahre, wie du diese für das Alter typischen aggressiven Gefühlsausbrüche spielerisch und behutsam umlenken kannst.'),
  ('1b86b21d-6e02-4ac7-a965-21bdbcf95db5', 'Logischer Entwicklungssprung 🧩', 'Dein Kind beginnt, Ursache und Wirkung miteinander zu verknüpfen. Entdecke im Blog die besten Spiele für zu Hause, die die kognitive Entwicklung von 22 Monate alten Kindern fördern, und probiere sie aus.'),
  ('6351737e-949c-4fb6-a2b3-5af919c832cf', 'Analysieren wir den Tagesrhythmus ⏱️', 'Ist die Wachphase am Abend zu lang geworden? Starte den Schlaftimer und beobachte den Schlafrhythmus. Vielleicht ist jetzt genau der richtige Zeitpunkt, den Mittagsschlaf um 15 Minuten zu verkürzen.'),
  ('f36fcaba-998e-48e4-a1c2-d085b47ccd2f', 'Eisenspeicher überprüfen 🥩', 'Damit die aktiven Muskeln gut versorgt sind, sollte keine Blutarmut vorliegen. Überprüfe mit dem Ernährungstracker die heutige Eisenaufnahme und gleiche einen Mangel direkt aus.'),
  ('04a88ead-f1bb-44fb-a8ea-9c02adfcfb9b', 'Zuckerfreier Snack 🍪', 'Kekse aus dem Supermarkt sind nicht nötig. Entdecke in den Babyrezepten gesunde Leckereien mit Datteln und Äpfeln, die du zu Hause in 10 Minuten zubereiten kannst, und wecke den Appetit deines Kindes.'),
  ('7b343e4c-3369-4f05-b976-97c243e8ed13', 'Wachstumsschub! 📏', 'Sind die Ärmel schon wieder zu kurz? Die körperliche Entwicklung nimmt Fahrt auf. Trage die aktuellen Maße in den Entwicklungs-Tracker ein und betrachte stolz die Wachstumskurve.'),
  ('7c55b3cc-0f0f-47b0-8148-d026b3b7590e', 'Neue Wörter sind unterwegs! 🗣️', 'Dein Kind macht viele Laute, spricht aber noch keine vollständigen Wörter? Um den passiven Wortschatz zu aktivieren, kannst du diese lustigen Silbenversuche als Audio im Babyalbum festhalten und ihre Entwicklung verfolgen.'),
  ('614145be-ebb6-498c-9b3f-26a829cb6b6d', 'Kleine Haushaltshilfe 🧹', 'Dein Kind möchte jetzt bei der Hausarbeit mithelfen. Lies im Blog, wie du einem 22.5 Monate alten Kind spielerisch Verantwortungsbewusstsein vermitteln kannst, und probiere es aus.'),
  ('6d017679-be1f-4b11-b8fd-36574013a33a', 'Fantasie kennt keine Grenzen 🧸', 'Füttert dein Kind seinen Teddy oder verarztet es dich? Halte diese Entwicklung der Empathie in einem kurzen Video im Babyalbum fest und schaffe eine Erinnerung fürs Leben.'),
  ('f542a783-2187-4790-b865-10366397c49d', 'Sicher auf Entdeckungstour ⚠️', 'Schränke, Schubladen ... Für kleine Entdecker können sie gefährlich sein! Sieh dir unter „Empfohlene Produkte“ unbedingt Möbelsicherungen und Sicherheitsschlösser an.'),
  ('8497fe17-ba82-4513-8de8-e30bada196eb', 'Lass den anstrengenden Tag hinter dir 🛋️', 'Das ständige Hinterherlaufen hat dich völlig erschöpft. Dein Kind schläft – schreib jetzt all deinen Stress ins Stimmungstagebuch und gönn dir eine Tasse Kräutertee.'),
  ('8fc02957-0717-4600-94a0-03ec95b3ecc9', 'Bereit fürs Töpfchen? 🚽', 'Ist die Windel morgens noch ganz trocken? Dann könnte jetzt der ideale Zeitpunkt sein, mit dem Töpfchentraining zu beginnen. Notiere es im Windel-Tracker und sieh dir die Artikel zur Vorbereitung in der App an.'),
  ('924176de-d987-4381-ba5c-3bdf618f72f9', 'Mag dein Kind kein Fleisch? 🥩', 'Dein Kind braucht Eiweiß, verweigert aber Fleisch? Probiere die leckeren, leicht zu kauenden Hähnchenbällchen aus den Babyrezepten und erfülle damit den Tagesbedarf im Ernährungstracker.'),
  ('75bd2c8f-8af9-437f-ac84-6c69bc76ea8c', 'Fluchtplan fürs Zubettgehen 🏃‍♂️', 'Läuft dein Kind aus dem Zimmer, sobald es Schlafenszeit ist? Starte den Schlaftimer, spiele bei den Weißen Geräuschen das Rauschen des Waldes ab und verwandle das Zimmer in eine ruhige Höhle.'),
  ('bd146fb2-5002-4d8c-824b-58bbd81c0c9b', 'Morgendlicher Trotz 🛑', '„Das ziehe ich nicht an!“, „Das esse ich nicht!“ – machen solche Trotzanfälle dir den Morgen schwer? Schreib gleich der Anacan AI und erfahre, wie du mit dem für dieses Alter typischen Austesten von Grenzen umgehen kannst.'),
  ('fdf24d1a-f6c7-451f-974c-c9a5a3bf1aa7', 'Vom Sofa an die Wände! 🧗‍♂️', 'Dein Kind ist ein echter Stuntprofi! Finde unter den mama-freundlichen Orten Einrichtungen mit großen Spielbereichen, in denen es sich austoben und seine überschüssige Energie loswerden kann.'),
  ('685f831c-092e-4c6a-aaf1-8fc0973b0182', 'Energie in 5 Minuten ⚡', 'Stürze dich morgens nicht gleich in die Hausarbeit. Bereite dir ein Beeren-Porridge aus unseren gesunden Rezepten für Frauen zu – vollgepackt mit Antioxidantien – und tanke neue Energie.'),
  ('a2d43041-fecf-4b9c-87c8-b48f899e1810', 'Nächtliches Aufwachen ⏱️', 'Starte den Schlaf-Timer! Anhand der Statistik kannst du genau erkennen, ob ein Nachtschreck oder eine Schlafregression vorliegt, und den Schlafrhythmus entsprechend anpassen.'),
  ('ca7d5385-3628-4318-a29d-52e41611d6dd', 'Die geistige Entwicklung geht weiter 🧠', 'Dein Kind liebt es, Dinge zu sortieren! Entdecke jetzt unter „Empfohlene Produkte“ geometrische Puzzles, die die Wahrnehmung von Farben und Formen fördern und das Gehirn anregen.'),
  ('2c09d1ae-89ad-4429-b136-e47270b6a957', 'Du bist die Heldin des Tages 🌟', 'Jede neue Fähigkeit, die dein Kind lernt, ist auch dein Verdienst. Öffne das Stimmungstagebuch und schreibe heute etwas auf, für das du dir selbst Beifall schenken möchtest!'),
  ('61d69ed1-ecb9-44fd-ac6a-cb922359921f', 'Ein kleiner Künstler voller Farbe! 📸', 'Hat dein Kind sich selbst und die Wand angemalt? Statt dich zu ärgern, kannst du diesen lustigen Kritzelmoment beim Baby-Fotoshooting mit fröhlichen Stickern verzieren und als bleibende Erinnerung ins Album hochladen.'),
  ('f52268ca-f991-4824-88f4-73fcbe961356', 'Probleme mit Verstopfung? 💩', 'Achte beim morgendlichen Windelwechsel auf den Stuhlgang. Wenn dein Kind Verstopfung hat, trage sie in der App ein und ergänze den Speiseplan mithilfe der Ernährungskontrolle unbedingt um ballaststoffreiche Lebensmittel.'),
  ('596bb7f3-6693-46d8-ab7c-2abd702c9a04', 'Ein Gefühl von Geborgenheit 🌌', 'Hat dein Kind Angst, wenn du das Licht ausschaltest? Spiele unter „Weißes Rauschen“ Geräusche aus dem Mutterleib mit Herzschlag ab. So schenkst du ihm das vertraute, warme Gefühl von Geborgenheit und stimmst es auf den Schlaf ein.'),
  ('85644ffd-0693-4b98-8af6-f0210f7b50a9', 'Auch du brauchst soziale Kontakte ☕', 'Bist du es leid, immer nur mit deinem Kind zu sprechen? Finde unter „Mama-freundliche Orte“ Kindercafés, in denen sich viele Mütter treffen, und entdecke auch für dich ein neues Umfeld.'),
  ('e1d32a6a-e4ea-4c4f-8731-157813de9284', 'Andere Mamas kennenlernen 👯‍♀️', 'Während die Kinder spielen, könnt ihr euch unterhalten! Finde auf der Karte mit mama-freundlichen Orten ein Zentrum mit Spielgruppen und raus aus dem Haus.'),
  ('2e576d6b-3baa-4d91-b939-7173553eee26', 'Zähneputzen? 🪥', 'Macht dein Baby den Mund fest zu, sobald es die Zahnbürste sieht? Hol dir praktische Tipps von Anacan AI und erfahre, wie du diese Hygieneroutine in ein lustiges Spiel verwandeln kannst.'),
  ('8e98b7fa-b3a5-48a4-896a-9431c201a988', 'Natürliche Entspannung 🍃', 'War der Tag besonders laut und anstrengend? Die Zeit ist um. Vergiss den Haushalt, brüh dir nach einem unserer gesunden Rezepte einen Melissentee auf und genieße einfach die Ruhe.'),
  ('e49913ea-33f5-4d6e-8204-24fdfbb6dfec', 'Auf der Suche nach gesunden Naschereien 🍎', 'Schluss mit Keksen aus dem Supermarkt! Entdecke in den Babyrezepten gesunde Dattel-Apfel-Kekse, die du zu Hause in nur 10 Minuten zubereiten kannst, und wecke den Appetit deines Babys.'),
  ('8566be64-ecf0-4dc1-8d90-20c831db74ad', 'Ist die Trennungsangst zurück? 🌌', 'Weint dein Baby dir hinterher, sobald du das Zimmer verlässt? Spiele unter „Weißes Rauschen“ Herzschlaggeräusche ab, um ihm ein Gefühl von Geborgenheit zu geben und es auf den Schlaf einzustimmen.'),
  ('942d7419-7926-47e6-b70e-db59dc58e301', 'Die Hosen sind schon wieder zu kurz! 📏', 'Werden auch die Ärmel der Oberteile zu kurz? Dann steht möglicherweise ein körperlicher Wachstumsschub an. Trage die aktuellen Maße in den Gewichts-Tracker ein und betrachte stolz die Wachstumskurve.'),
  ('95ec49ae-492b-442d-be59-8db9c9f8c8e4', 'Lustige Aussprachen 🗣️', 'Manche Wörter spricht dein Baby so süß und falsch aus! Lass dir diese kostbaren Momente nicht entgehen. Lade sie als Video mit Ton ins Babyalbum hoch, damit ihr später gemeinsam darüber lachen könnt.'),
  ('25439bfb-873c-4735-bc03-f5aa2d6b8ff2', 'Wie sieht es mit der Eiweißzufuhr aus? 🍗', 'Für aktive Muskeln ist Eiweiß unverzichtbar. Überprüfe mit dem Ernährungstracker die tägliche Nährstoffbalance deines Babys und gestalte seinen Speiseplan abwechslungsreicher.'),
  ('a458d5c8-d74f-4a15-a4a9-53e24632f8f7', 'Das mache ich selbst! 👕', 'Wird das Anziehen am Morgen jedes Mal zur großen Krise? Erfahre jetzt von Anacan AI, wie du mit Trotz umgehst und deinem Kind Wahlmöglichkeiten gibst.'),
  ('f5dd0c22-b8ec-461e-a5b4-9045aa3ae282', 'Bücher lesen statt zerreißen 📖', 'Zerreißt dein Kind beim Vorlesen am Abend die Seiten? Lies jetzt im Blog, wie du dieses Problem lösen kannst, ohne die Freude am Lesen zu beeinträchtigen.'),
  ('19a9511e-358f-41a2-bbf2-d966afa6ffa9', 'Analysieren wir den Rhythmus ⏱️', 'Ist die Wachphase am Abend zu lang geworden? Starte den Schlaftimer und beobachte den Rhythmus. Vielleicht ist genau jetzt der richtige Zeitpunkt, den Mittagsschlaf um 15 Minuten zu verkürzen.'),
  ('65db46df-45b6-4a1e-ae35-6797a38fafce', 'Therapie mit Sand und Matsch 🏖️', 'Hab keine Angst vor schmutziger Kleidung! Entdecke jetzt im Bereich „Empfohlene Produkte“ die besten Hilfsmittel für Spiele mit kinetischem Sand und andere sensorische Spiele.'),
  ('dc3f8791-df91-4f2d-8dc5-44a0fff017da', 'Das ist dein Verdienst 🌟', 'Jede neue Fähigkeit, die dein Kind täglich erlernt, und jeder selbstbewusste Schritt sind auch dein Verdienst. Öffne das Stimmungstagebuch und schreibe heute etwas auf, das dich stolz auf dich macht!'),
  ('2dafd9b8-26be-4b73-a1b1-cede334643cd', 'Wie oft hast du heute Nein gesagt? 💆‍♀️', 'Du bist sehr müde, oder? Atme tief durch. Schreib all deine Gefühle in dein Stimmungstagebuch, lass die Schuldgefühle los und gönn dir einfach etwas Ruhe.'),
  ('379a5991-8f1e-48b3-9f27-5e21468d8859', 'Mit trockener Windel aufgewacht? 🩲', 'Hast du beim morgendlichen Windelwechsel bemerkt, dass die Windel trocken ist? Frag Anacan AI jetzt nach dem richtigen Zeitpunkt und geeigneten psychologischen Methoden, um mit dem Töpfchentraining zu beginnen.'),
  ('9728ea76-627d-4390-8b60-df7f4a0dc917', 'Kleine Kuchenliebe 🧁', 'Dein Kind möchte etwas Süßes? Du musst nicht gleich zum Supermarkt laufen. Entdecke bei den Babyrezepten einen zuckerfreien Bananen-Hafer-Muffin, der in 10 Minuten fertig ist, und bewahre damit deinen Gesundheitswert im Ernährungstracker.'),
  ('057bf87f-0bbd-415e-a240-9562e85f263d', 'Streit beim Anziehen! 👗', 'Wird das morgendliche Anziehen zur großen Krise? Gib deinem Kind zwei verschiedene Oberteile zur Auswahl und lass es selbst entscheiden.'),
  ('2ac666c9-f3bd-4794-a981-76652151d626', 'Werden die Augen gerieben? 🥱', 'Die ersten Müdigkeitssignale sind da! Starte den Schlaf-Timer, spiele unter „Weißes Rauschen“ sanftes Waldrauschen ab, um dein Kind auf den Schlaf einzustimmen, und behalte den Schlafrhythmus im Blick.'),
  ('5ce76677-164d-4bc6-835d-9ba614b47d9b', 'Mamas Kaffeepause ☕', 'Jetzt ist Zeit für eine Pause. Während dein Kind selbstständig spielt, kannst du mit einem antioxidantienreichen grünen Tee oder einem leichten Kaffee aus den gesunden Rezepten für Frauen neue Energie tanken.'),
  ('35dcaff3-d09c-4c5a-87b5-8fa048fa86b8', 'Klettert dein Kind zu Hause die Wände hoch? 🧗', 'Die Energie muss raus! Öffne die Karte mit mama-freundlichen Orten, entdecke einen neuen Park mit sicherer Freifläche zum Toben und einer Rutsche und lass dein Kind sich frei austoben.'),
  ('3eefbe35-a241-4512-8320-0993efa296ef', 'Flucht vom Esstisch! 🏃‍♂️', 'Lässt dein Kind das Essen stehen und läuft weg? Stoppe den Ernährungstimer. Statt es zum Essen zu zwingen, kannst du im Blog nachlesen, wie sich der Appetit auf natürliche Weise anregen lässt.'),
  ('ecf28bb2-147f-47c5-8e81-503885a13db6', 'Warum drücken die Schuhe? 👟', 'Stolpert dein Kind beim Laufen häufig? Vielleicht sind seine Füße gewachsen! Trage die aktuellen Maße in den Entwicklungstracker ein, prüfe direkt, ob ein Wachstumsschub vorliegt, und analysiere die Entwicklung.'),
  ('c795e5c9-7249-46e0-9227-8cae7b9774c9', 'Ordnet dein Kind die Formen richtig zu? 🧩', 'Unterstütze die Entwicklung des logischen Denkens: Suche jetzt unter „Empfohlene Produkte“ nach altersgerechten geometrischen Puzzles und pädagogisch wertvollem Holzspielzeug.'),
  ('ce8c0e6d-8b04-4829-9134-54da2f1cc621', 'Bekommt dein Kind genug Eiweiß? 🥚', 'Für schnell wachsende Muskeln ist Eiweiß unverzichtbar. Berechne mit dem Ernährungstracker den heutigen Bedarf und passe den Speiseplan an, falls noch Eiweiß fehlt.'),
  ('d5a7dad1-9dd5-40f2-bc6d-27d7e6052c76', 'Die ersten richtigen Gespräche 🗣️', 'Unterhält sich dein Baby ausgiebig in seiner eigenen Sprache mit dir? Halte diesen lustigen und unbezahlbaren Moment als Video mit Ton im Babyalbum fest.'),
  ('6d0154ad-03f9-4392-b21e-d18f214374b2', 'Plötzliche Wutanfälle! 🛑', 'Wirft sich dein Baby auf den Boden, wenn es nicht bekommt, was es möchte? Frage unseren Anacan KI-Expertenassistenten, wie du diese emotionalen Ausbrüche, die zum 23. Monat hin häufiger werden, spielerisch bewältigen kannst.'),
  ('9e25f59c-eab1-44ee-ae76-e1b1ae42dc4c', 'Ans Trinken denken 💧', 'Wie funktioniert die Verdauung deines kleinen Wirbelwinds? Dokumentiere beim Windelwechsel den Stuhlgang. Wenn ein Verstopfungsrisiko besteht, sieh dir in der App unbedingt unsere Empfehlungen für natürliche, ballaststoffreiche Lebensmittel an.'),
  ('bc4d0552-0cde-4c7a-bca8-4b2551c95ad7', 'Angst im Dunkeln? 🌌', 'Weint dein Baby, wenn du das Licht im Zimmer ausschaltest? Spiele unter den Weißen Geräuschen die vertrauten Klänge aus dem Mutterleib (Herzschlag) ab und schenke ihm so wieder das vollkommene Gefühl von Geborgenheit.'),
  ('1ecb40c2-379b-4b51-a326-4d93bf0ac050', 'Bewahre deine Energie am Morgen ⚡', 'Starte nicht mit leerem Magen in den Tag! Tu dir etwas Gutes und wähle aus den gesunden Rezepten für Frauen einen leckeren, sättigenden Haferflockenkuchen, der in 5 Minuten zubereitet ist.'),
  ('69fe7fde-913c-4ff4-8fe2-fcbdad210e16', 'Auch du brauchst Freunde 👯‍♀️', 'Bist du es leid, dich nur mit deinem Kind zu unterhalten? Finde unter den mutterfreundlichen Orten Zentren mit Spielgruppen, knüpfe Kontakte zu anderen Müttern und tausche Erfahrungen aus.'),
  ('f7991ada-b885-400f-9f72-4df6d1f9477e', 'Wird der Mittagsschlaf kürzer? ⏱️', 'Hat das Einschlafen am Abend lange gedauert? Starte den Schlaf-Timer und beobachte den Rhythmus. Vielleicht ist jetzt genau der richtige Zeitpunkt, den Mittagsschlaf um 15-20 Minuten zu verkürzen.'),
  ('0347ce08-669e-4477-9fbc-63c1580b9edb', 'Du bist die Heldin des Tages 🌟', 'Jede neue Fähigkeit, die dein Kind lernt, und jeder sichere Schritt sind auch dein Verdienst. Öffne das Stimmungstagebuch und schreibe heute etwas auf, das dich stolz auf dich selbst macht!'),
  ('789f31a5-225d-4210-8e89-eb69a6524d9d', 'Die Suche nach der perfekten Mama 💖', 'Warst du heute etwas lauter als sonst? Hab kein schlechtes Gewissen. Schreib deine Gefühle in dein Stimmungstagebuch – du bist für dein Baby ohnehin die beste Mama.'),
  ('354016aa-fdff-494e-9db1-d11124a417c8', 'Analysieren wir den Rhythmus ⏱️', 'War die Wachphase am Abend zu lang? Starte den Schlaftimer und beobachte den Schlafrhythmus. Vielleicht ist jetzt genau der richtige Zeitpunkt, den Tagschlaf um 15 Minuten zu verkürzen.'),
  ('d03661d9-e587-4637-b9c4-cf2d9c6ce6c8', 'Sand- und Matschtherapie 🏖️', 'Hab keine Angst vor Schmutz! Suche bei den mama-freundlichen Orten einen sicheren Park mit Sandkasten und lass dein Kind für seine sensorische Entwicklung die Natur unbeschwert entdecken.'),
  ('dd733e39-eed2-478b-9a6a-adcec13e6fc1', 'Der beste Freund des Eisens 🥩', 'Vitamin C ist für die Aufnahme von Eisen im Körper unverzichtbar! Überprüfe mit dem Ernährungstracker den heutigen Speiseplan und ergänze das Fleisch mit einem Salat und reichlich Zitronensaft.'),
  ('97ab1430-c17a-4645-93d1-2d0b7261c822', 'Isst dein Kind nur Brot? 🍞', 'Schiebt dein Kind Eiweißquellen und Gemüse beiseite und möchte nur Kohlenhydrate? Berechne mit dem Ernährungstracker, wie viele wertvolle Nährstoffe es heute aufgenommen hat, und passe die Menge entsprechend an.'),
  ('b991e93f-39a2-4eb7-afdb-453c13a1d55b', 'Die Lust, Seiten zu zerreißen 📖', 'Will dein Kind beim abendlichen Vorlesen die Buchseiten zerreißen? Lies im Blogbereich, wie du dieses Problem lösen kannst, ohne die Freude am Lesen zu beeinträchtigen.'),
  ('fa426bdb-bb7f-4a4f-9e93-d26f8fe4998a', 'Wütendes Beißen 🦖', 'Beißt dein Kind seine Freunde oder dich, wenn es wütend ist? Frag jetzt unseren KI-Expertenassistenten von Anacan, wie du liebevoll mit diesem schwierigen Verhalten umgehen kannst.'),
  ('1c3f0685-89ab-4827-a123-f84fa8b82551', 'Tut dir der Rücken weh? 🧘‍♀️', 'Ein über 12 kg schweres Kind ständig hochzuheben, ist nicht leicht. Bereite dir nach einem unserer gesunden Rezepte für Frauen einen entzündungshemmenden Ingwertee zu, der die Muskeln entspannt, und gönn dir eine Pause.'),
  ('19e2869e-6998-4c65-b3a4-edbc6a06f435', 'Flüchtet dein Kind vor Gemüse? 🥦', 'Wird dein Kind beim Essen wählerisch? Entdecke in den Babyrezepten, wie du Spinat und Karotten geschickt in leckeren Pfannkuchen versteckst und ihm Appetit machst.'),
  ('b793a816-4035-4e2c-8e9a-647949d5fa3a', 'Kleiner Künstler bei der Arbeit 🎨', 'Auch wenn dein Kind von Kopf bis Fuß mit Farbe bekleckert ist – ärgere dich nicht! Halte diesen kreativen Moment fest, verziere ihn in der Baby-Fotosession mit lustigen Stickern und füge ihn lächelnd dem Album hinzu.'),
  ('addb392c-deee-4dda-99c7-ed94d64cd987', 'Hauen oder Schubsen 🦖', 'Haut dein Kind plötzlich zu oder schubst seine Freunde, wenn es wütend ist? Erfahre von Anacan AI, wie du mit den heftigen Gefühlen in diesem Alter sanft und konstruktiv umgehen kannst.'),
  ('ebc52a7e-1091-4bf2-89de-cc6e528ddbe1', 'Die Knochen werden stärker 🦴', 'Schnelles Wachstum erfordert Kalzium. Prüfe mit dem Ernährungstracker, ob dein Kind heute genug Käse und Joghurt gegessen hat, und gleiche mögliche Defizite aus.'),
  ('ee59618a-2d83-4249-b1e6-0323265cd134', 'Natürliche Entspannung 🍃', 'War der Tag besonders laut und anstrengend? Der Timer ist abgelaufen. Vergiss die Hausarbeit, spiele bei den Weißen Geräuschen das Plätschern eines Bachs ab und lege dich zum Entspannen aufs Sofa.'),
  ('5557465c-fb11-48b9-90c2-fc336972f19c', 'Bücher lesen statt zerreißen 📖', 'Zerreißt dein Kind beim abendlichen Vorlesen die Seiten? Lies jetzt im Bereich „Blogs“, wie du damit umgehen kannst, ohne seine Freude am Lesen zu beeinträchtigen.'),
  ('5b487ba9-a209-4653-a8fe-4315e87398df', 'Endlose Show im Bett 🛌', 'Springt dein Kind im Bett herum, statt zu schlafen? Starte den Schlaf-Timer und verfolge den Schlafrhythmus. Finde heraus, ob es noch überschüssige Energie hat oder bereits übermüdet ist.'),
  ('9fb4af87-300a-4df0-8f02-48703cd4da3a', 'Streit beim Zähneputzen 🪥', 'Macht dein Kind den Mund fest zu, sobald es die Zahnbürste sieht? Sieh dir unter „Empfohlene Produkte“ musikalische Zahnbürsten oder Fingerzahnbürsten an und entdecke, wie du diese wichtige Routine in ein lustiges Spiel verwandelst.'),
  ('0b69ffc4-e10f-4228-a354-3609a2cf48bb', 'Wütendes Beißen 🦖', 'Beißt dein Kind seine Freunde oder dich, wenn es wütend ist? Frag jetzt unseren Anacan AI-Experten, wie du liebevoll mit diesem schwierigen Verhalten umgehen kannst.'),
  ('0bd19a92-8f32-4626-9053-67019de34d6b', 'Isst dein Kind nur Brot? 🍞', 'Schiebt es Eiweiß und Gemüse beiseite und will nur Kohlenhydrate? Berechne mit dem Ernährungstracker, wie viele wertvolle Nährstoffe dein Kind heute aufgenommen hat, und passe die Menge entsprechend an.'),
  ('3794ac2c-9f00-4406-8f93-da27c84ffed3', 'Lust am Seitenzerreißen 📖', 'Will dein Kind beim abendlichen Vorlesen die Buchseiten zerreißen? Lies im Blogbereich, wie du damit umgehen kannst, ohne seine Freude am Lesen zu beeinträchtigen.'),
  ('21c31221-548f-42a2-945f-424351b307be', 'Ein Kunstwerk an der Wand 🎨', 'Hat dein Kind einen Stift genommen und die Wand bemalt? Ärgere dich nicht! Verewige diesen süßen Streich mit den lustigen Rahmen aus dem Baby-Fotoshooting im Album und lächle einfach darüber.'),
  ('cb6101a7-dbfd-4d36-944e-5acbfd6bc964', 'Tut dir der Rücken weh? 🧘‍♀️', 'Ein Kleines mit 12+ kq ständig hochzuheben, ist nicht leicht. Bereite dir aus unseren gesunden Rezepten einen muskelentspannenden, entzündungshemmenden Ingwertee zu und gönn dir eine Pause.'),
  ('e15645b0-86cf-412b-8fdc-f53e32110fb7', 'Fluchtplan fürs Zubettgehen 🏃‍♂️', 'Klettert dein Kind aus dem Gitterbett, sobald die Schlafenszeit gekommen ist? Starte den Schlaftimer, spiele unter den Weißen Geräuschen das gleichmäßige Rattern eines Zuges ab und stimme es sanft aufs Schlafen ein.'),
  ('406278a2-debe-4851-9b00-479abeb4b13e', 'Bereit fürs Töpfchen? 🚽', 'Ist die Windel morgens völlig trocken? Dann könnte jetzt der ideale Zeitpunkt sein, mit dem Töpfchentraining zu beginnen. Trage es im Windeltracker ein und sieh dir unter „Empfohlene Produkte“ ergonomische Töpfchen an.'),
  ('67af77d4-bcc0-42c9-9d93-190208cee7c5', 'Will dein Kind allein spielen? 👶', 'Spielt es im Park nicht mit den anderen Kindern, sondern schaut nur von der Seite zu? Entdecke im Blogbereich spannende wissenschaftliche Fakten über diese gesunde Form des Parallelspiels.'),
  ('41e1758f-79bb-43e3-8304-d4d74fa983b0', 'Bleibt ihr wegen des wechselhaften Wetters zu Hause?', 'Das Wetter- und Kleidungstool zeigt dir sofort die Windgeschwindigkeit und das passende Outfit – so könnt ihr unbesorgt in den Park gehen.'),
  ('bcfad7da-e488-4ced-aa83-11c72d34ebec', 'Kommen die letzten Backenzähne? 🦷', 'Kaut dein Kind plötzlich auf allem herum und ist gereizt? Vielleicht sind die hintersten Backenzähne unterwegs. Halte den Verlauf im Zahnungs-Tracker fest und lege gekühlte Beißringe bereit.'),
  ('c57b31e1-ab4c-412f-95b1-bcfc05812865', 'Die Hauptfigur im Märchen 🪄', 'Erstelle heute Abend in den intelligenten Märchen eine besondere Geschichte, in der dein Kind die Hauptfigur ist: ein mutiges Kleines, das gerne seine Zähne putzt.'),
  ('3dd0cee4-66f4-4904-9285-5b0b7b0dfa7b', 'Nimm dir Zeit für dich 🛋️', 'Das ständige Hinterherlaufen hat dich erschöpft. Dein Kind schläft – schreibe jetzt all deinen Stress ins Stimmungstagebuch und gönne dir eine Tasse Melissentee.'),
  ('6721af60-2c7e-45f7-a60e-e27511cbb049', 'Hungrig oder durstig? 💧', 'Manchmal wird Durst mit Appetitlosigkeit verwechselt. Prüfe die Ausscheidungseinträge im Windel-Tracker, um schnell sicherzugehen, dass dein Kind genug Flüssigkeit bekommt.'),
  ('be975b82-781b-4e9e-b454-14728754957f', 'Kleiner Sänger 🎤', 'Singt dein Kind immer wieder dasselbe Lied? Das fördert sein Rhythmusgefühl und seine Sprachentwicklung.'),
  ('12f1dbe9-33ce-4aad-aead-7be2d360eb1e', 'Der Fantasie sind keine Grenzen gesetzt 🧸', 'Füttert dein Kind seinen Teddy oder untersucht es dich? Entdecke unter „Empfohlene Produkte“ Arzt- und Küchenspielsets, die diese wunderbare Entwicklung von Empathie unterstützen.'),
  ('813a036f-96ee-4802-8c36-c3d573f602c0', 'Ist die Trennungsangst wieder da? 🌌', 'Weint dein Kind, sobald du das Zimmer verlässt? Spiele unter „Weißes Rauschen“ Herzschlaggeräusche ab, um ihm ein Gefühl von Geborgenheit zu geben und es auf den Schlaf einzustimmen.'),
  ('71912e32-5753-4990-97c7-dcf5458c45d1', 'Kunstwerk an der Wand 🎨', 'Hat dein Baby einen Stift genommen und die Wand bemalt? Nicht ärgern! Halte diesen süßen Streich mit den lustigen Rahmen aus dem Baby-Fotoshooting im Album fest und lächle einfach darüber.'),
  ('aa4285be-2d37-4c2f-82d8-24587b052512', 'Fluchtplan aus dem Bett 🏃‍♂️', 'Klettert dein Baby aus dem Bettchen, sobald es Schlafenszeit ist? Starte den Schlaftimer und spiele das gleichmäßige Zuggeräusch aus den Weißen Geräuschen ab, damit es sanft zur Ruhe kommt und einschläft.'),
  ('7057ef80-4efd-430a-a44f-a695f7bd7b53', 'Mit beiden Füßen springen 🦘', 'Versucht dein Baby, aus dem Stand mit beiden Füßen gleichzeitig zu springen? Das sieht ziemlich lustig aus, oder? Halte diesen Moment unbedingt fest.'),
  ('a5fa8450-6478-40eb-8c4a-42d08f636974', 'Entspannung mit Musik 🎶', 'Die einfachste Lösung für die Quengelei am späten Nachmittag: Spiele die Lieblingsmelodie deines Babys, nimm es in den Arm und tanzt langsam zusammen.'),
  ('cea6f894-72c1-48a7-91fc-bc8637fa2cca', 'Kein Mittagsschlaf? 🥱', 'Will dein Baby tagsüber nicht schlafen und wehrt sich dagegen? Bitte Anacan AI um genaue Informationen zu den Wachfenstern rund um den 2. Geburtstag und um einen passenden Schlafrhythmus.'),
  ('b7bcd4fe-cc33-4ea9-a97e-59e15168cb31', 'Auf der Suche nach gesunden Leckereien 🍎', 'Schluss mit Keksen aus dem Supermarkt! Entdecke in den Babyrezepten gesunde Leckereien mit Datteln und Äpfeln, die du zu Hause in nur 10 Minuten zubereiten kannst, und wecke den Appetit deines Babys.'),
  ('ed519633-a8d9-4eaa-a80a-911f5bc80cd1', 'Streit beim Zähneputzen 🪥', 'Macht dein Baby den Mund fest zu, sobald es die Zahnbürste sieht? Hol dir praktische Tipps von Anacan AI und erfahre, wie du diese wichtige Hygieneroutine in ein lustiges Spiel verwandelst.'),
  ('fc53997b-db7d-4e51-803e-f6bd3797e9e3', 'Lustige Aussprache 🗣️', 'Manche Wörter spricht dein Baby so süß und falsch aus! Lass dir diese kostbaren Momente nicht entgehen. Lade sie als Video mit Ton ins Babyalbum hoch, damit ihr später gemeinsam darüber lachen könnt.'),
  ('4ee32e6d-768e-4628-8838-47e0599752e7', 'Kleiner Sofakletterer! 🧗', 'Ist das Klettern auf Möbeln sein größtes Hobby? Verziere diese mutige und lustige Motorik-Show mit fröhlichen Stickern aus dem Baby-Fotoshooting und lade sie ins Album hoch.'),
  ('74a21e11-19bb-4326-af8e-197831260dd5', 'Mamas Akku ist leer? 🔋', 'Nickst du mittags schon im Stehen ein? Bereite dir mit den gesunden Rezepten für Frauen einen proteinreichen Erdnussbutter-Smoothie zu, der dir ganz ohne Koffein sofort neue Energie gibt.'),
  ('842a46f0-f832-4901-8e08-572103acff74', 'Heute war einfach alles schwierig? 💆‍♀️', 'Hast du den ganzen Tag nur Schreien und Weinen gehört? Atme tief durch, hör auf, dich selbst zu verurteilen – du machst das großartig!'),
  ('25dc715a-32c8-4d74-92d1-69586eb52b13', 'Stehen alle Töpfe aus der Küche auf dem Boden?', 'Das Spielen mit ungefährlichen Gegenständen fördert sein logisches Denken. Lass dein Baby seinen Schatz in aller Ruhe erkunden.'),
  ('43609cdd-bc75-4be9-80ac-98506e0aba38', 'Ruhe ist jetzt wichtig 🤫', 'Die erste halbe Stunde nach dem Einschlafen ist die empfindlichste Phase. Prüfe den Geräuschpegel mit dem Schallpegelmesser und vermeide plötzlichen Lärm.'),
  ('8b59959d-35b3-4803-a8d5-668ef810ded0', 'Die Illusion der Perfektion 🛋️', 'Mach dir keine Vorwürfe, wenn du in den sozialen Medien ständig fröhliche Mütter siehst. Deine Erschöpfung und dein unaufgeräumtes Zimmer gehören genauso zum ganz normalen Alltag.'),
  ('17e385d1-c634-49cd-9d0d-e1c98c9b0fd8', 'Von Wörtern zu Sätzen 🗣️', 'Bildet dein Kind schon lustige Sätze aus 3 Wörtern? Halte diesen großartigen Sprachsprung und die niedliche Aussprache in einem Video mit Ton fest und bewahre die Erinnerung für später auf.'),
  ('3fe4d415-9d24-4577-93ed-654921e52b2c', 'Die Seiten werden lebendig 📖', 'Ahmt dein Kind beim Vorlesen die Laute der Tiere im Buch nach? Im Bereich „Blogs“ findest du interaktive Vorlesetechniken, die diese Entwicklung der Fantasie fördern – unbedingt lesen!'),
  ('c13703f6-090d-418f-ba78-30e2aa25d678', 'Kleine Haushaltshilfe 🧹', 'Dein Kind möchte jetzt schon bei der Hausarbeit mithelfen. Lies im Blog, wie du einem etwa 2-jährigen Kind spielerisch Verantwortungsbewusstsein vermittelst, und probiere die Tipps gleich aus.'),
  ('c6d0e6b3-90f7-4c66-9fd0-1f47e6d714c9', 'Sei stolz auf dich! 🌟', 'Jede neue Fähigkeit, die dein Kind täglich lernt, und jeder sichere Schritt sind auch dein Verdienst. Öffne das Stimmungstagebuch und schreibe heute einen Eintrag darüber, worauf du stolz bist!'),
  ('85abdfc2-20eb-4a57-a2bc-cb822114eada', 'Mission verstecktes Gemüse 🥦', 'Schiebt dein Kind den Teller weg, sobald es Brokkoli sieht? Entdecke in den Babyrezepten, wie du dieses vitaminreiche Gemüse geschickt in leckeren Pfannkuchen versteckst und so den Appetit deines Kindes anregst.'),
  ('8a4be0f9-7229-4996-baf5-618ca78de14d', 'Das Spiel will einfach nicht enden ⏱️', 'Läuft dein Kind weg und versteckt sich, statt ins Bett zu gehen? Starte den Einschlaftimer und spiele bei den Weißen Geräuschen Meeresrauschen ab, um das Zimmer in eine ruhige Schlafhöhle zu verwandeln.'),
  ('b333371b-bfc0-429c-bd23-a3e9996c1c00', 'Wacht dein Kind morgens zu früh auf? 🌅', 'Wacht dein Kind schon vor Sonnenaufgang voller Energie auf? Hol dir direkt bei unserem KI-Experten Anacan AI Tipps, wie du seinen Schlafrhythmus auf angenehmere Uhrzeiten verschieben kannst.'),
  ('3c7a1c30-6e81-411e-a8e2-8748214141cf', 'Logikspiele 🧩', 'Wirft dein Kind Spielzeug in eine Kiste und kippt danach alles wieder aus? So entwickelt sich sein Verständnis für „drinnen“ und „draußen“. Halte diese kognitive Fähigkeit im Entwicklungstracker fest.'),
  ('b06ec056-54a0-4363-b389-839031267542', 'Der Schuh-Dickkopf 👟', 'Will dein Kind im Sommer unbedingt seine Winterstiefel anziehen, wenn ihr nach draußen geht? Lass ihm manchmal die Wahl – das stärkt seinen eigenen Willen.'),
  ('ff08789a-eee1-4756-9d40-5ac5e65f75a9', 'Hast du eine Frage? 🤖', 'Macht dir Angst, was du über die Trotzphase mit 2 Jahren liest? Verlier dich nicht im Internet, sondern schreib direkt an Anacan AI und erfahre, wie ihr diese Phase leichter meistern könnt.'),
  ('bad958b0-7da3-4a62-ae7d-c35289ff6f57', 'Energieausbruch 💥', 'Die eigenen vier Wände halten diesem Bewegungsdrang kaum stand. Öffne die Karte mit mama-freundlichen Orten, finde einen sicheren Spielplatz mit weichem Boden und einer großen Rutsche und lass dein Kind sich dort frei austoben.'),
  ('6dabe6f9-b86b-4347-9d8c-8d189d8a1224', 'Ich putze selbst! 🪥', 'Dein Kind nimmt dir die Zahnbürste ab und möchte selbst putzen, putzt aber eigentlich gar nicht? Suche jetzt unter „Empfohlene Produkte“ nach musikalischen und ergonomischen Modellen, die diesen Prozess erleichtern.'),
  ('a9e849fb-b58a-4614-9ca7-0396de5c5865', 'Flüssigkeitszufuhr und Verstopfung 💧', 'Dein Kind ist ständig in Bewegung, trinkt aber wenig Wasser? Achte beim Windelwechsel auf die Ausscheidungen. Wenn ein Verstopfungsrisiko besteht, dokumentiere es in der App und ergänze mithilfe der Ernährungskontrolle sofort ballaststoffreiche Lebensmittel.'),
  ('d816b4dc-5206-4a90-9e61-8c02ef8f5c68', 'Geduldsprobe am Esstisch 🥣', 'Dein Kind spielt mit dem Essen und macht alles schmutzig? Aktiviere den Ernährungstimer, analysiere den Appetitverlauf anhand der Grafik und verfolge genau, wie lange die Mahlzeit dauert.'),
  ('5f435409-af45-4f28-ad39-0362ac580462', 'Alles auf den Boden werfen 🛑', 'Schleudert dein Kind Dinge weg, wenn es wütend ist oder sich langweilt? Frage Anacan AI, wie du diese emotionalen Reaktionen sanft in die richtige Richtung lenken kannst.'),
  ('cf7b282d-cfc2-4ce1-9f7c-e71f0a8529ba', 'Die Oberteile werden zu klein! 📏', 'Ist dir beim Anziehen aufgefallen, dass die Ärmel enger werden? Rund um den 2. Geburtstag steht ein körperlicher Wachstumsschub an! Trage die aktuelle Körpergröße in den Entwicklungstracker ein und betrachte stolz die Wachstumskurve.'),
  ('d1b0bfba-8ace-4234-8eb6-40647f25ce47', 'Heißer Tee und Ruhe 🍵', 'Der Timer ist abgelaufen, dein Kind schläft. Stürze dich jetzt nicht auf die Hausarbeit! Bereite dir nach einem der gesunden Rezepte für Frauen einen Melissentee zu und halte deine kleinen Erfolge des Tages im Stimmungstagebuch fest.'),
  ('1c764980-a64f-44cc-b47e-9bb7c39ae099', 'Die Kraft des Eisens 🥩', 'Damit dein aktives Kleinkind keine Blutarmut entwickelt und voller Energie bleibt, überprüfe in der Ernährungskontrolle die heutige Eisenzufuhr und passe bei einem Mangel den Speiseplan an.'),
  ('8c8e48b0-6f8d-4855-bb6b-3ff2edd9fbb3', 'Die Hosen sind schon wieder zu kurz! 📏', 'Werden die Ärmel der Oberteile zu kurz? Dein Kind macht gerade einen Wachstumsschub. Trage die aktuellen Maße in den Entwicklungs-Tracker ein und betrachte stolz die Wachstumskurve.'),
  ('24f24fa2-f109-4ee8-b9c0-2fe64e74bf4d', 'Mamas Proteinvorrat ⚡', 'Es ist nicht leicht, einem quirligen kleinen Entdecker hinterherzulaufen. Bereite aus unseren gesunden Rezepten für Frauen einen protein- und obstreichen Energie-Smoothie zu und lade deine Akkus wieder auf.'),
  ('5e6168f7-641f-4f35-ba96-328826769e77', 'Das mache ich selbst! 👕', 'Wird das Anziehen am Morgen zur großen Krise? Erfahre jetzt von Anacan AI, wie du mit Trotz umgehen und deinem Kind Wahlmöglichkeiten geben kannst.'),
  ('a40e092a-696e-4da1-98b1-5b56a4f49122', 'Woran erkennst du, dass dein Kind satt ist? ⏱️', 'Wenn dein Kind beginnt, Essen wegzuwerfen oder auszuspucken, signalisiert es, dass es satt ist. Stoppe den Ernährungstimer, vermerke, dass die übliche Menge erreicht wurde, und analysiere den Appetit.'),
  ('5266953d-d239-48ef-aac1-e6e5bcca5cbf', 'Liebe zu Büchern 📖', 'Bringt dein Kind sein liebstes Märchenbuch und setzt sich auf deinen Schoß? Seine Aufmerksamkeitsspanne wird länger. Lest gemeinsam und benennt, was auf den Bildern zu sehen ist.'),
  ('b3334b05-05eb-4d1a-9a1b-b94086c6493b', 'Beginnen die Ängste? 👻', 'Hat dein Kind plötzlich Angst vor dem Staubsauger, obwohl es sich früher nicht davor gefürchtet hat? Mit der Entwicklung der Fantasie können unbegründete Ängste entstehen. Nimm dein Kind in den Arm und sag ihm, dass es sicher ist.'),
  ('c2a4b3f4-3db4-4b1d-a807-2effcd0ace08', 'Zeit für frische Luft 🌳', 'Ist dein Kind sehr unruhig und hält es zu Hause nicht mehr aus? Prüfe das Wetter, wähle passende Kleidung und macht euch gleich auf den Weg in den Park. Die Natur beruhigt dein Kind oft am schnellsten.'),
  ('387df56f-151e-4857-83aa-f757db180cee', 'Auch du brauchst Freunde 👯‍♀️', 'Bist du es leid, dich nur mit deinem Kind zu unterhalten? Finde unter den mama-freundlichen Orten Zentren mit Spielgruppen, knüpfe Kontakte zu anderen Müttern und tauscht eure Erfahrungen aus.'),
  ('2754ee28-07df-42f6-ba7d-9d86b1edf758', 'Der Zauber der Monotonie 🌬️', 'Die plötzliche Stille nach dem Ausschalten des Fernsehers macht dein Baby unruhig. Spiele unter „Weißes Rauschen“ das Geräusch eines Ventilators oder Haartrockners ab und beobachte, wie es deinem Baby eine beruhigende und sichere Schlafatmosphäre schafft.'),
  ('301a1109-2563-49a6-a096-aa057de78fa7', 'Kunst mit bunten Händen 🎨', 'Hat sich dein Baby beim Spielen mit Farben das ganze Gesicht verschmiert? Statt dich zu ärgern, halte diesen lustigen, kreativen Moment fest und füge ihn als eine deiner farbenfrohsten Erinnerungen dem Album hinzu.'),
  ('3112ae5c-eae2-4dc5-ae42-0bb7f83e1fdb', 'Abendrituale 🧸', 'Schläft dein Baby jeden Abend mit demselben Spielzeug im Arm ein? Halte diesen süßen Moment der Geborgenheit ohne Foto fest, indem du ihn einfach im Notizbereich des Babyalbums beschreibst.'),
  ('363e202f-bc22-4752-9313-7e506d91cf84', 'Erste Freundschaftsversuche 👶', 'Interessiert sich dein Baby im Park für das Spielzeug eines anderen Kindes und gibt dabei Laute von sich? Tausche dich in den mama-freundlichen Treffpunkten mit anderen Müttern darüber aus, wie du diese Phase der sozialen Entwicklung unterstützen kannst.'),
  ('a11c68a5-ec27-4659-9acb-bdcc422f80f8', 'Der kleine Doktor bei der Arbeit 🩺', 'Gibt dein Baby seinem Teddybären eine Spritze oder hört dessen Bauch ab? Die Fantasie ist auf ihrem Höhepunkt! Lies im Bereich „Blogs“, welchen erstaunlichen Einfluss Rollenspiele auf die kognitive Entwicklung haben.'),
  ('053139e2-7d9f-4a00-9462-2ddb17d7e133', 'Mit völlig trockener Windel aufgewacht? 🩲', 'Hast du beim morgendlichen Windelwechsel bemerkt, dass die Windel trocken ist? Das ist ein wichtiges körperliches Anzeichen dafür, dass dein Baby bereit fürs Töpfchen ist! Trage es im Windel-Tracker ein und behalte die Statistik aufmerksam im Blick.'),
  ('d7110781-b463-4661-96ac-270a072de535', 'Ohne Zucker, aber süß 🍪', 'Möchte dein Baby nachmittags einen Snack? Kekse aus dem Supermarkt sind nicht nötig. Entdecke in den Babyrezepten gesunde Leckereien mit Datteln und Hafer, die in 10 Minuten zubereitet sind.'),
  ('f9924ca2-641b-4911-b60a-55193623479d', 'Analysieren wir den Rhythmus genau ⏱️', 'Hat das Einschlafen am Abend 40 Minuten gedauert? Sieh dir die Grafik des Schlaf-Timers an. Vielleicht ist jetzt genau der richtige Zeitpunkt, den Tagschlaf um 20 Minuten zu verkürzen und die abendliche Schlafenszeit vorzuverlegen.'),
  ('fe937f54-e4d9-4674-821c-ae81d7c0c2cc', 'Streit um den falschen Becher? 🥤', 'Ein Weltuntergang, nur weil du das Wasser im blauen statt im roten Becher serviert hast? Erfahre von Anacan AI, wie du bei solchen scheinbar absurden Wutanfällen gelassen bleibst.'),
  ('4582098e-0228-4efe-b173-11bb966a75f4', 'Nächtliches Aufwachen ⏱️', 'Starte den Schlaftimer! Analysiere anhand der Statistik des Timers genau, ob es sich um Nachtschreck oder eine Schlafregression handelt, und passe den Schlafrhythmus entsprechend an.'),
  ('91af8067-4bf1-4cab-af7f-58a96c7e04b3', 'Auch du brauchst eine Pause ☕', 'Geh raus und atme ein wenig durch! Finde unter „Mütterfreundliche Orte“ ein Café mit Kinderecke in deiner Nähe und genieße in Ruhe deinen heißen Kaffee.'),
  ('e6513be5-cd7d-41ca-afb7-bc1d9cfbc0d8', 'Probleme mit Verstopfung? 🚽', 'Achte beim morgendlichen Windelwechsel auf den Stuhlgang. Liegt eine Verstopfung vor, trage sie in der App ein und ergänze über die Ernährungskontrolle ballaststoffreiche Lebensmittel, um das Gleichgewicht wiederherzustellen.'),
  ('442e022d-5a7b-4ad3-bb7f-6aecb9da6631', 'Wutanfall wegen des Bildschirms 📱', 'Wirft sich dein Kind auf den Boden, wenn du ihm das Handy wegnimmst? Erfahre von Anacan AI, wie du die Bildschirmzeit stressfrei begrenzen und gesunde Grenzen setzen kannst.'),
  ('70c5aa02-8fdb-44ad-8a7f-cb5e6e2076a9', 'Du bist die Heldin des Tages 🌟', 'Jede neue Fähigkeit, die dein Kind täglich erlernt, ist auch dein Verdienst. Öffne das Stimmungstagebuch und schreibe heute einen Eintrag, für den du dir selbst stehenden Applaus schenken würdest!'),
  ('d0802019-8ab1-4450-b744-1d4846aeaf76', 'Streit beim Zähneputzen 🪥', 'Läuft dein Kind weg, sobald es die Zahnbürste sieht? Sieh dir unter „Empfohlene Produkte“ musikalische oder rotierende Kinderzahnbürsten an und verwandle diese wichtige Hygieneroutine in ein lustiges Spiel.'),
  ('134f77a6-22c5-4894-83a4-bbdf2a3551b0', 'Natürliche Beruhigung 🍃', 'War der Tag laut und voller Trubel? Der Timer ist abgelaufen. Dunkle das Zimmer ab, spiele unter „Weißes Rauschen“ das Plätschern eines Baches ab und gönne damit sowohl dem Gehirn deines Kindes als auch deinem eigenen eine wohltuende Massage.'),
  ('c38c019f-d84f-4e70-a98d-688ae4d3f657', 'Logischer Entwicklungssprung 🧩', 'Dein Kind beginnt, Ursache und Wirkung miteinander zu verknüpfen. Im Bereich „Blogs“ findest du die besten Spiele für zu Hause, die die kognitive Entwicklung von etwa 2-jährigen Kindern fördern. Probiere sie gleich aus.'),
  ('e1d2d8e1-5d2b-4afe-b927-cf13cedf3cda', 'Kalzium-Schutzschild 🦴', 'Kalzium ist für Zähne und Knochen unverzichtbar. Prüfe mit dem Ernährungstracker, ob dein Kind heute genug Joghurt und Käse gegessen hat.'),
  ('20e07ee8-1ee8-4d24-9dc9-8aeafced1a45', 'Pfannkuchenmonster 🥞', 'Dein Kind verweigert das Frühstück? Schau dir bei den Babyrezepten das Rezept für zuckerfreie Bananenpfannkuchen an. Es kann sie selbst in die Hand nehmen und essen – und bekommt dabei gleich mehr Appetit.'),
  ('98f28b6b-3cea-495d-a58b-704216aa3a0d', 'Geduldsprobe am Esstisch 🥣', 'Dein Kind spielt mit dem Essen und macht alles schmutzig? Starte den Ernährungstimer, analysiere den Appetitverlauf anhand der Grafik und verfolge genau, wie lange die Mahlzeit dauert.'),
  ('a8ac0c29-0fa0-4dec-a0ed-2411236fabc2', 'Sand- und Matschtherapie 🏖️', 'Hab keine Angst vor Schmutz! Entdecke im Bereich „Empfohlene Produkte“ gleich die besten Hilfsmittel für Spiele mit kinetischem Sand und andere sensorische Aktivitäten.'),
  ('5c1b9d9c-ddd2-4dad-b93e-0902ebeb2417', 'Die Kunst, Energie loszuwerden 🧗', 'Die eigenen vier Wände reichen deinem Kind nicht mehr aus. Öffne die Karte „Mama-freundliche Orte“ und finde einen Ort mit einem sicheren Spielbereich und weichem Boden, wo es nach Herzenslust springen und laufen kann.'),
  ('7c5f1c11-9db4-4f7a-913f-8ca7bf583cb6', 'Wählerischer Appetit 🥦', 'Dein Kind will nur Nudeln oder Brot? Analysiere den Speiseplan mit dem Ernährungstracker und gleiche fehlende Vitamine mit abwechslungsreich angerichteten Gerichten aus den Babyrezepten aus.'),
  ('ea466226-d28d-4765-94f7-982ef3a85a8e', 'Licht dimmen 🌙', 'Schalte 1 Stunde vor dem Schlafengehen alle hellen Lichter und Bildschirme aus. Melatonin wird nur in einer ruhigen, schwach beleuchteten Umgebung ausgeschüttet.'),
  ('94201b9a-86d5-4505-89c9-5202248a32f0', 'Morgendliches Theater 👗', '„Ich will diese Schuhe nicht!“ – macht diese Trotzphase euren Morgen zur Herausforderung? Erfahre von Anacan AI, wie du deinem Kind mit Alternativen und Wahlmöglichkeiten psychologisch sinnvoll begegnest.'),
  ('c7ffac8f-2df5-4b9d-8171-edd5730bbcb9', 'Mamas Proteinspeicher ⚡', 'Einem aktiven kleinen Wirbelwind hinterherzulaufen, ist nicht leicht. Verausgabe dich nicht! Bereite dir mit unseren gesunden Rezepten einen protein- und fruchtreichen Energie-Smoothie zu und tanke neue Kraft.'),
  ('fdd42343-56c5-47a1-8eaa-9e8b57c16e15', 'Natürliche Beruhigung 🍃', 'War der Tag laut und voller Herumgerenne? Der Timer ist abgelaufen. Verdunkle das Zimmer, spiele unter „Weißes Rauschen“ das Plätschern eines Baches ab und bringe damit dein Baby und dich selbst zur Ruhe.'),
  ('06ba8468-2412-484c-9b4b-12b5ce2a132b', 'Kampf um Selbstständigkeit! 👕', 'Dein Kind möchte sich allein anziehen und lehnt deine Hilfe ab? Frage jetzt unseren KI-Expertenassistenten Anacan AI, wie du diesen Eigensinn in eine gesunde Entwicklung lenken kannst.'),
  ('10c5438d-d27e-4125-a092-12fa2afc9118', 'Eisenspeicher-Check 🥩', 'Damit dein aktiver kleiner Wirbelwind keine Blutarmut entwickelt, überprüfe in der Ernährungskontrolle die heutige Eisenzufuhr (Fleisch, Hülsenfrüchte) und passe den Speiseplan an.'),
  ('f5441f5e-36e8-4685-812e-3b947ba2fe54', 'Abendliche Entschleunigung 🎶', 'Dein Kind wird vom Herumrennen nicht müde und will nicht ins Bett? Starte den Schlaftimer und spiele unter „Weißes Rauschen“ Meeresrauschen ab, um im Zimmer eine ruhige, schlaffördernde Atmosphäre zu schaffen.'),
  ('194c05a1-f79c-496c-b1f4-f1316b804846', 'Lass dein Kind die Geschichte erzählen 📖', 'Betrachtet dein Kind die Bilder im Buch und erzählt dabei etwas in seiner eigenen Sprache? Halte diesen wunderbaren Moment voller Fantasie gleich als Video mit Ton im Babyalbum fest und bewahre ihn für die Zukunft auf.'),
  ('81278832-aa98-446b-b9de-87731d74c2b6', 'Sicherer Platz zum Toben 🏃‍♀️', 'Kann dein Kind zu Hause seine Energie nicht loswerden und stellt alles auf den Kopf? Öffne die Karte „Mama-freundliche Orte“, finde einen Park mit einem sicheren Platz zum Toben und geht gemeinsam an die frische Luft.'),
  ('247c6eba-b9c7-406d-95d9-27a9c74871bf', 'Lernspielzeug 🧩', 'Mit 2 Jahren braucht dein Kind Spielzeug, das nicht nur Geräusche macht, sondern auch spielerisch Wissen vermittelt. Entdecke unter „Empfohlene Produkte“ Holzpuzzles, die das logische Denken fördern.'),
  ('50a05ffc-5382-423e-b256-bdeac07c78eb', 'Zuckerfreie Torte backen 🎂', 'Für den besonderen Tag morgen muss eine gesunde Torte her! Entdecke in den Babyrezepten fruchtige, kinderfreundliche Tortenrezepte ganz ohne raffinierten Zucker.'),
  ('9c2176f9-4583-459e-b4a3-631c624068de', 'Mamas Energiequelle 🥗', 'Vergiss nicht, auch deine eigenen Akkus aufzuladen! Bereite dir mit unseren gesunden Rezepten einen proteinreichen Smoothie mit Erdnussbutter zu, der dir sofort neue Energie schenkt.'),
  ('19814a91-cb64-4bf7-bdcb-7655e0d384a4', 'Offiziell 2 Jahre alt! 🎈', '2 Jahre voller unermüdlicher Fürsorge, Liebe und schlafloser Nächte. Halte im Stimmungstagebuch fest, wie stolz du auf diese 730 Tage sein kannst. Du bist wirklich eine großartige Mama!'),
  ('6a49b5e2-afea-42a7-8643-310e7b5b7642', 'Du hast es geschafft 🥂', 'Zwei Jahre voller Hingabe! Wenn dein Kind schläft, lass den Haushalt einfach liegen. Öffne das Stimmungstagebuch, schreibe dir selbst ein paar dankbare Worte und ruh dich einfach aus.'),
  ('e00156cd-d1b9-4727-b3d4-e86b004b8681', 'Trotzphase mit 2? 🌪️', 'Gibt es immer mehr Neins und Geschrei? Hol dir jetzt von Anacan AI Strategien für den Umgang mit Gefühlsausbrüchen, um entspannter durch diese bekannte Phase zu kommen.'),
  ('17c8a3a6-67b0-49ab-a185-9e25f788bb11', 'Es will nicht am Tisch sitzen 🥣', 'Hat dein Kind schnell genug vom Essen und läuft weg? Starte den Mahlzeiten-Timer, notiere die Dauer und vermeide es unbedingt, dein Kind zum Essen zu zwingen.'),
  ('32abe85c-b2ef-4ebb-aa71-2ad4fbb4e416', 'Zeit für Ruhe 🤫', 'Sorge nach dem gestrigen Trubel mit dem Geräuschmesser für eine ruhige Umgebung im Zimmer. Unterbrochener Nachtschlaf wirkt sich sowohl auf die Stimmung deines Kindes als auch auf deine eigene aus.'),
  ('8796a078-f4e3-4ea5-9258-919333a4b718', 'Chaos nach dem Geburtstag 🌪️', 'Nach der gestrigen Party herrscht zu Hause das reinste Chaos? Stürz dich nicht gleich in den Hausputz. Verbringe diesen Tag einfach ganz entspannt mit deinem frischgebackenen zweijährigen Geburtstagskind.'),
  ('07c79611-988f-4228-b928-f34af1a7425a', 'Kleine Naturkünstler 🍂', 'Raus an die frische Luft! Blätter und Steine im Park sind das beste Material für sensorische Spiele. Finde unter den mama-freundlichen Orten einen Platz mit viel Grün.'),
  ('14d525a3-b7d6-43c1-9919-132c8691cf60', 'Viel Wasser, gute Verdauung 💧', 'Vergisst dein Kind beim Herumtoben zu trinken? Trage morgens die Windel im Windeltracker ein und überprüfe sofort das Gleichgewicht zwischen Flüssigkeit und Ballaststoffen, um Verstopfung vorzubeugen.'),
  ('8a2ef907-aa42-42a0-b57d-125e83745fe9', 'Das abendliche Vorleseritual 📖', 'Erzählt dein Kind die vorgelesene Geschichte mit eigenen Worten nach? Halte diesen großartigen sprachlichen Entwicklungssprung sofort als Video mit Ton fest und bewahre ihn im Babyalbum für die Zukunft auf.'),
  ('031b0761-047d-4d63-84ce-fd41ce83245b', 'Die „Das gehört mir!“-Phase 🧸', 'Dein Kind will sein Spielzeug im Park nicht teilen und schreit? Erfahre von Anacan AI, wie du den typischen Egozentrismus mit 2 Jahren gesund begleiten kannst, ohne dass daraus aggressives Verhalten entsteht.'),
  ('16c2ca9a-7971-49b0-9210-b9dd3baea775', 'Entzündungshemmende Kraft 🍵', 'Schmerzen dein Rücken und deine Arme vom vielen Hochheben deines Kindes? Bereite dir nach unseren gesunden Rezepten für Frauen einen Ingwer-Zitronen-Tee zu und unterstütze deinen Körper bei der Regeneration.'),
  ('4645899a-65b7-4ec6-9619-57e71d7569de', 'Analysieren wir den Rhythmus ⏱️', 'Ist die Wachphase am Abend zu lang geworden? Starte den Schlaftimer und beobachte die Übersicht. Vielleicht ist es an der Zeit, den Mittagsschlaf um 20 Minuten zu verkürzen!'),
  ('5bc99c8b-11ed-40cb-90ff-db30ccb7cbdb', 'Das Nachahmen geht weiter 🦜', 'Du telefonierst und dein Kind hält sich ebenfalls die Fernbedienung ans Ohr? Es ahmt dich zu 100% nach! Versuche, ihm ein gutes Vorbild zu sein.'),
  ('bfbd5b7b-bf9b-48f6-a1a2-f194c1a573f8', 'Die Kraft des Wortes Nein 🛑', 'Wenn du ihm etwas anbietest, schüttelt es den Kopf und sagt Nein! Das ist kein Trotz, sondern seine Art, die eigene Meinung auszudrücken. Gib ihm verschiedene Optionen, um es zu beruhigen.'),
  ('e590043b-d98d-4bab-915d-caf59d5351e3', 'Papas lustige Seiten 🤡', 'Am besten bringt Papa das Baby mit seinen komischen Geräuschen zum Lachen. Genießt heute Abend gemeinsam diese fröhlichen Momente.'),
  ('72f63b03-217f-4966-9286-177869cd7d59', 'Ohne Zucker, aber lecker 🥞', 'Hat dein Baby Lust auf etwas Süßes? Dafür musst du nicht einkaufen gehen. Probiere bei den Babyrezepten die Bananen-Apfel-Pancakes aus, die in nur 10 Minuten fertig sind und garantiert Appetit machen.'),
  ('c2a3a287-3762-4751-aa0e-2e7d2c1d038c', 'Der Kampf mit der Zahnbürste 🪥', 'Wird das Zähneputzen jedes Mal zum großen Kampf? Schau dir bei den empfohlenen Produkten Zahnbürsten mit Musik oder beliebten Zeichentrickfiguren an und verwandle das Putzen im Handumdrehen in ein Spiel.'),
  ('d3ffa760-4dfc-4872-9709-1f13cf644f4a', 'Natürliche Entspannung 🍃', 'War der Tag voller Lärm und Herumrennen? Jetzt ist Schluss. Dunkle das Zimmer ab, spiele bei den Weißen Geräuschen das Plätschern eines Bachs ab und gönne auch deinem Kopf eine wohltuende Pause.'),
  ('3b32f5ba-4db0-47e2-ab4a-893183710c64', 'Der Eisenschutzschild 🥩', 'Hat dein Baby weniger Energie oder ist es einfach nur müde? Überprüfe heute mit dem Ernährungstracker seine Eisenzufuhr (Fleisch, Hülsenfrüchte) und gleiche mögliche Defizite direkt aus.'),
  ('a743db36-b967-433a-8695-0780f7195e63', 'Das Doktorspiel beginnt 🩺', 'Gibt dein Baby seinem Teddybären eine Spritze? Fantasiespiele sind gerade besonders beliebt. Halte diesen süßen Moment beim Baby-Fotoshooting fest und bewahre ihn als unvergessliche Erinnerung auf.'),
  ('d6af2d07-9e24-449e-843c-4a4fbcab142b', 'Auch du brauchst eine Pause ☕', 'Nimm dir einen Moment ohne dein Kind und atme tief durch! Finde bei den mama-freundlichen Orten ein Café mit Kinderecke und genieße deinen heißen Kaffee in aller Ruhe.'),
  ('78846b79-c47d-4a00-947e-59f644b0393d', 'Eisenschutzschild 🥩', 'Damit dein aktives Kleines keine Blutarmut entwickelt und voller Energie bleibt: Entdecke in den Babyrezepten leckere, leicht zu kauende Fleischbällchen mit Gemüse, die den Appetit anregen.'),
  ('14cb8a25-67e3-4a93-92e7-813bc9ea34c1', 'Lust am Seitenzerreißen 📖', 'Zerreißt dein Kind die Buchseiten, anstatt zu lesen? Frag jetzt Anacan AI, wie du damit umgehen kannst, ohne die Freude am Lesen zu beeinträchtigen.'),
  ('ce2cdb1e-e1d2-4e44-a336-1708ff489505', 'Energie in 5 Minuten ⚡', 'Könntest du mittags im Stehen einschlafen? Bereite dir aus den gesunden Rezepten für Frauen ein Beeren-Porridge voller Antioxidantien zu, das dir sofort neue Kraft schenkt.'),
  ('d83ebff1-21e6-4964-94da-2347551c7e01', 'Von Wörtern zu Sätzen 🗣️', 'Bildet dein Kind schon lustige Sätze aus 3-4 Wörtern? Entdecke im Blog die besten Spiele für zu Hause und Silbenübungen, die diesen beeindruckenden sprachlichen Entwicklungssprung unterstützen.'),
  ('25c00809-7707-4080-969f-0093aea099c2', 'Zeit für eine Massage 💆‍♂️', 'Wenn euer Kind eingeschlafen ist, könnt ihr euch gegenseitig die Schultern massieren und gemeinsam den Stress des Tages loslassen. Ihr seid ein Team!'),
  ('3708efde-5f63-47e0-b30e-19b8bf533ad8', 'Fantasie-Autofahrt 🚗', 'Nimmt dein Kind eine leere Schachtel oder ein Spielzeug, dreht es wie ein Lenkrad und macht dabei Geräusche? Das symbolische Spielen (Fantasiespiel) ist jetzt in vollem Gange!'),
  ('c1efd894-6c8f-4d33-9cdd-4d863998e9be', 'Austausch unter Müttern 💬', 'Lässt dir der Gedanke „Warum macht mein Kind das?“ keine Ruhe? Tritt der Anacan Community bei und lies ähnliche Geschichten anderer Mütter.'),
  ('71d54817-9c7d-4b6a-a083-cfc9af5ca532', 'Kalziumquelle 🦴', 'Kalzium ist für Zähne und Knochen unverzichtbar. Prüfe mit dem Ernährungstracker, ob ihr heute genug Joghurt und Käse gegessen habt, und gleiche mögliche Defizite aus.'),
  ('10e42611-20e5-4efa-b449-859dcdf79439', 'Fluchtplan fürs Zubettgehen 🏃‍♂️', 'Läuft dein Kind weg und versteckt sich, sobald es Schlafenszeit ist? Stelle den Schlaf-Timer ein, wähle bei den Weißen Geräuschen das Rauschen des Waldes und verwandle das Zimmer in eine ruhige Höhle.'),
  ('a00ab8a1-2a6c-4ace-a218-64e35136c179', 'Vom Parallelspiel zum gemeinsamen Spielen 👶', 'Das Interesse daran, mit anderen Kindern in derselben Umgebung zu spielen, nimmt zu. Entdecke im Bereich „Blog“ die Geheimnisse der sozialen Entwicklung von Zweijährigen und die Psychologie auf dem Spielplatz.'),
  ('ab2766ea-1937-4401-b3fe-78b7aa14f747', 'Der tägliche Kampf ums Anziehen 👗', 'Weint dein Kind und ruft: „Ich will diese Hose nicht!“? Erfahre von Anacan AI, wie du morgendliche Kleidungskrisen reduzieren und deinem Kind freie Wahlmöglichkeiten geben kannst.'),
  ('3743e0d0-daf8-4b16-9966-a5c865827254', 'Kleiner Koch bei der Arbeit 👨‍🍳', 'Hilft dir dein Kind in der Küche und knetet Teig? Halte diesen lustigen Moment, in dem es von Kopf bis Fuß mit Mehl bedeckt ist, als Video mit Ton fest und schaffe eine Erinnerung fürs Leben.'),
  ('8b9210f4-74fc-4c2d-b35a-90728df0c189', 'Wutanfall im Supermarkt 🛒', 'Wirft sich dein Kind in der Öffentlichkeit auf den Boden, weil es nicht bekommen hat, was es wollte? Vergiss die Blicke der anderen und sprich mit Anacan AI darüber, wie du diese Trotzanfälle mit 2 Jahren gelassen bewältigen kannst.'),
  ('d5d9b1e2-d062-4d67-8535-5d3b9126d7d2', 'Eine schlaflose Nacht gehabt? ☕', 'Haben die nächtlichen Wachphasen deine ganze Energie geraubt? Bereite dir mit unseren gesunden Rezepten für Frauen einen proteinreichen Erdnussbutter-Smoothie zu, der dir ohne Koffein sofort neue Kraft gibt.'),
  ('02f4d85d-ea15-4227-a58f-b7dba39b78d0', 'Plötzliches Aufwachen 🌌', 'Wacht dein Kind mitten in der Nacht weinend auf und lässt sich nicht beruhigen? Schreibe dem Experten von Anacan AI, um den Unterschied zwischen Nachtschreck und Albtraum zu verstehen und richtig zu reagieren.'),
  ('3a940a2c-0062-4cd0-9553-c25d5aadd4ea', 'Schluss mit dem Zahnbürsten-Streit 🪥', 'Macht dein Kind den Mund fest zu, sobald es die Zahnbürste sieht? Suche jetzt bei den Produktempfehlungen nach musikalischen und ergonomischen Modellen, die das Zähneputzen erleichtern, und verwandle die Routine in ein Spiel.'),
  ('86c19953-fc54-4688-b5d9-b4feaed16fa5', 'Analyse des Schlafrhythmus ⏱️', 'Wälzt sich dein Baby abends lange im Bett hin und her? Schau dir die Grafik des Schlaf-Timers an. Vielleicht ist jetzt genau der richtige Zeitpunkt, den Tagschlaf um 20 Minuten zu verkürzen und die Schlafenszeit am Abend vorzuverlegen.'),
  ('69468bd3-2ce5-4731-b30e-3685775a4a1a', 'Magische Hintergrundgeräusche für mehr Ruhe 🌊', 'War der Tag voller Krisen und Lärm? Spiele bei den Weißen Geräuschen Meeresrauschen ab und beruhige damit das Nervensystem deines Babys – und dein eigenes.'),
  ('86704e7d-f300-4ac8-a2e1-2a5068e8a7e2', 'Spielerisch Gemüse entdecken 🥦', 'Dein Baby lehnt Spinat ab? Entdecke in den Babyrezepten, wie du diese Vitamine geschickt in leckeren Pfannkuchen verstecken und so seinen Appetit anregen kannst.'),
  ('c422d14a-eccf-4f6a-bcbb-1ec2a5bdfc3a', 'Wachstumsschub! 📏', 'Sind die Hosen schon wieder zu kurz? Rund um den 25. Monat beschleunigt sich die körperliche Entwicklung. Trage die aktuellen Maße in den Entwicklungs-Tracker ein und betrachte stolz die Wachstumskurve.'),
  ('2f36e03e-8050-4c96-a7d2-3231c5e8bf3f', 'Entdeckungstour an der frischen Luft 🌳', 'Zu Hause fällt deinem Kind die Decke auf den Kopf. Finde unter den mama-freundlichen Orten einen großen, sicheren Park, in dem es frei herumtoben und seine ganze Energie loswerden kann.'),
  ('484ef066-dacc-4b23-98a9-ef3409b6f055', 'Geduldsprobe am Esstisch ⏱️', 'Spielt dein Baby mit dem Essen, statt zu essen? Starte den Ernährungstimer, erfasse die Dauer der Mahlzeit und analysiere die Entwicklung seines Appetits anhand der Grafik in der App.'),
  ('d99bde2e-2ab1-43d0-b2d0-95122a7f44ce', 'Warum schlägt mein Kind plötzlich? 🛑', 'Schlägt dein Kind, wenn es wütend wird? Erfahre vom Anacan AI-Experten, wie du mit spielerischen Methoden sanft mit den aggressiven Gefühlsausbrüchen in diesem Alter umgehen kannst.'),
  ('1a858fa5-276f-440e-972b-2b83e93db467', 'Kaffeepause ☕', 'Haushalt und Kinderbetreuung ... Jetzt ist Zeit für eine Pause! Finde unter den mama-freundlichen Orten ein Café mit Spielecke und genieße deinen heißen Kaffee in Ruhe.'),
  ('7f7e8cbd-f54d-475a-9880-5e509bceab0e', 'Der Teller hat die falsche Farbe! 🎨', 'Gab es einen Wutanfall, weil du das Essen auf dem roten statt auf dem grünen Teller serviert hast? Im Bereich „Blogs“ findest du Tipps, wie du mit den scheinbar unlogischen Trotzreaktionen in diesem Alter umgehen kannst.'),
  ('967e4cff-99ce-432e-991e-40e75469ba59', 'Mamas Rückenschmerzen 🧘‍♀️', 'Schmerzt dein Rücken vom Hochheben deines über 13 kg schweren Lieblings? Kümmere dich um dich selbst und bereite dir nach einem unserer gesunden Rezepte für Frauen einen muskelentspannenden Ingwertee zu.'),
  ('a1d9ccbc-d633-4cf7-8231-4a3a870b0696', 'Der heimliche Nachahmer 📸', 'Telefoniert dein Kind wie du oder ahmt es deine Bewegungen nach? Verziere diesen lustigen Moment mit fröhlichen Stickern aus dem Baby-Fotoshooting und füge ihn dem Album hinzu.'),
  ('43a58d7e-e492-4b05-8142-e4389027f185', 'Alles auf den Boden werfen 🛑', 'Wirft dein Kind Dinge durch die Gegend, wenn es wütend ist oder sich langweilt? In den Artikeln im Bereich „Blogs“ erfährst du, wie du diese emotionalen Reaktionen behutsam in die richtigen Bahnen lenken kannst.'),
  ('cec4b4c4-52ab-4e49-adea-d05ca6bfff30', 'Kunst mit bunten Händen 🎨', 'Hat sich dein Kind beim Spielen mit Farben das ganze Gesicht verschmiert? Statt dich zu ärgern, halte diesen lustigen, kreativen Moment direkt fest und füge ihn als farbenfrohste Erinnerung dem Babyalbum hinzu.'),
  ('deb2e459-e0cf-41a4-8379-c85e410b286a', 'Natürliche Entspannung 🍃', 'Der Timer ist abgelaufen. Das Kind schläft. Jetzt bist du dran! Bereite dir nach einem unserer gesunden Rezepte für Frauen einen Melissentee zu, leg dich aufs Sofa und genieße nach diesem anstrengenden Tag die Stille.'),
  ('6653e097-de4e-4ae0-8162-9b9f5ea59388', 'Ich wasche mich selbst! 🧽', 'Nimmt dir dein Kind in der Badewanne die Bürste oder den Waschlappen aus der Hand? Suche unter „Empfohlene Produkte“ nach kindgerechten Badeutensilien, die dieses Streben nach Selbstständigkeit unterstützen.'),
  ('74cf7a22-e38a-436b-abf9-30e1ae8f9815', 'Energie in 5 Minuten ⚡', 'Bist du vom vielen Herumrennen völlig erschöpft? Bereite dir nach einem unserer gesunden Rezepte für Frauen einen proteinreichen Erdnussbutter-Smoothie zu, der sofort neue Kraft gibt.'),
  ('725e419e-e208-48ec-ad13-bc8e5886eebb', '„Ich will allein essen!“ 🥦', 'Dein Baby möchte dir den Löffel aus der Hand nehmen. Lass es ruhig. Dabei wird zwar die Kleidung schmutzig, aber dieses Gefühl von Selbstständigkeit ist für dein Baby sehr wichtig.'),
  ('b6c449a4-eac7-47b9-9e9b-4c3b2deebe5b', 'Du bist die Heldin des Tages 🌟', 'Jede neue Fähigkeit, die dein Baby täglich erlernt, und jeder selbstständige Schritt sind auch dein Verdienst.'),
  ('2a9eaf13-aaf9-41fd-baa3-5fdcb48e56ca', 'Spielzeug mit Köpfchen 🧩', 'Zweijährige brauchen Spielzeug, das nicht nur Geräusche macht, sondern auch beim Lernen hilft. Entdecke unter „Empfohlene Produkte“ Holzpuzzles und Formenspiele, die das logische Denken fördern.'),
  ('5592a39d-90a2-449d-9f20-3a71ba9dddad', 'Probleme mit Verstopfung? 🚽', 'Vergisst dein Baby beim Herumtoben, Wasser zu trinken? Achte beim Windelwechsel auf den Stuhlgang. Besteht das Risiko einer Verstopfung, trage es in der App ein und füge über den Ernährungstracker ballaststoffreiche Lebensmittel hinzu.'),
  ('a589907e-1ec5-4668-9a51-f72995d314f0', 'Analysieren wir den Tagesrhythmus ⏱️', 'Hat das Einschlafen am Abend 40 Minuten gedauert? Sieh dir die Grafik im Schlaf-Timer an. Vielleicht ist jetzt genau der richtige Zeitpunkt, den Mittagsschlaf um 20 Minuten zu verkürzen und dein Baby abends früher ins Bett zu bringen.'),
  ('1966178b-773a-4205-ab76-e8693f0abf72', 'Zuckerfrei und trotzdem süß 🍪', 'Hat dein Baby am Nachmittag Lust auf einen Snack? Kekse aus dem Supermarkt sind nicht nötig. In den Babyrezepten findest du gesunde Leckereien mit Datteln und Hafer, die in nur 10 Minuten zubereitet sind.'),
  ('6f0ae293-593e-4249-828e-c2ec4c4fce2b', 'Lustige Grimassen 🤪', 'Schneidet dein Baby vor dem Spiegel Grimassen? Halte diesen lustigen Moment fest! Verziere das Foto gleich im Baby-Fotoshooting mit witzigen Rahmen und füge es dem Album hinzu.'),
  ('853c16b5-ec48-42df-a039-bc81b5a0ae1e', 'Auch du brauchst eine Pause ☕', 'Geh raus und schnapp ein wenig frische Luft! Finde unter „Mama-freundliche Orte“ ein Café mit Spielecke in deiner Nähe, genieße in Ruhe deinen heißen Kaffee und lerne andere Mütter kennen.'),
  ('40782485-009f-459f-b399-6e2d09a90f95', 'Du bist die Heldin des Tages 🌟', 'Jede neue Fähigkeit, die dein Kind Tag für Tag erlernt, ist auch dein Verdienst.'),
  ('9fcf0a97-e2c0-4a40-994a-17bcfcd07b1b', 'Ausgewogene Vitamin-C-Versorgung 🍊', 'Ein starkes Immunsystem ist wichtig. Berechne heute mit dem Ernährungstracker, ob dein Kind genügend Vitamin C aufgenommen hat, und passe den Speiseplan entsprechend an.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_de = v.t, body_de = v.b
FROM (VALUES
  ('0ef06d2c-90d7-4377-9290-8bde591b5f45'::uuid, 'Die endlose Warum-Phase 🤔', '„Was ist das?“, „Warum ist das so?“ … Dein Kind beginnt, die Welt zu hinterfragen! Antworte geduldig, denn in diesen Momenten feiern die Nervenzellen in seinem Gehirn ein wahres Fest.'),
  ('23204200-aac5-4b32-bb1b-c194a2fa62c8', 'Durchbrich den Perfektionszwang 🛑', 'Dein Kind hat heute keinen Mittagsschlaf gemacht und zu Hause herrscht Chaos? Macht nichts! Atme tief durch – du kannst nicht alles gleichzeitig im Griff haben. Lass einfach mal los.'),
  ('c615cbe9-985e-4212-bc61-219d1808967f', 'Ist deine Geduld am Ende?', 'Mach die Zimmertür zu und lass dein Kind mit seinem Papa allein. Heute Abend darf er die Leitung des heimischen Spielparks übernehmen.'),
  ('5d64edd3-2a7c-4881-81d2-2b0ca3685e08', 'Fällt dir zu Hause die Decke auf den Kopf?', 'Entdecke bei den kinderfreundlichen Orten ein Café mit Spielecke. Dein Kind kann spielen und du kannst in Ruhe deinen Kaffee genießen.'),
  ('752be34d-ef64-4eb5-9d4c-e6d82cd2a840', 'Ich ziehe mich selbst an 👕', 'Auch wenn dein Kind versucht, sich die Hose über den Kopf zu ziehen, solltest du seine Anziehversuche nicht unterbrechen. Sein Wunsch nach Selbstständigkeit ist gerade besonders groß! Halte diesen kleinen Erfolg im Entwicklungstracker fest.'),
  ('84770b0a-8d36-4d8c-9fce-09146969d787', 'Entspannung mit Musik 🎶', 'Das einfachste Mittel gegen die Quengelei am späten Nachmittag: Spiel seine Lieblingsmelodie, nimm dein Kind in den Arm und tanzt langsam zusammen.'),
  ('04f27cd2-d5c6-4a88-a758-f59dfedfac03', 'Magen-Darm-Signale 💩', 'Trage beim Windelwechsel deine Beobachtungen ein. Besteht Verstopfungsgefahr, sieh dir in der App unbedingt die Empfehlungen für natürlich ballaststoffreiche Lebensmittel und die Rezepte für Fruchtwasser an.'),
  ('2312b09a-1559-4ed0-aada-ff2063057e72', 'Trennungsangst? 🌌', 'Weint dein Baby, sobald du das Zimmer verlässt? Spiele unter den Weißen Geräuschen den Klang aus dem Mutterleib ab. Das schenkt ihm das vertraute Gefühl von Wärme und Geborgenheit und hilft ihm beim Einschlafen.'),
  ('a2bb6939-4631-4be2-a871-cb519c3fdacb', 'Zuckerfrei und trotzdem süß 🍪', 'Schluss mit Keksen aus dem Supermarkt! Entdecke in den Babyrezepten gesunde Leckereien mit Datteln und Haferflocken, die du zu Hause in 10 Minuten zubereiten kannst.'),
  ('5e9c412f-bcfb-4d5e-a447-66eebbf03e51', 'Die Kunst, Nein zu sagen 🛑', 'Sagt dein Kind zu allem Nein? Das ist kein Widerstand gegen dich, sondern ein wichtiger Schritt auf dem Weg zur eigenen Persönlichkeit. Stelle keine geschlossenen Fragen, sondern biete zwei Wahlmöglichkeiten an, um Machtkämpfe zu vermeiden.'),
  ('64707418-d2a0-43f8-b7ef-86936fa426fe', 'Schon wieder etwas vergessen?', 'Du musst dir nicht jede Kleinigkeit merken, die zu Hause ausgegangen ist. Setze sie sofort auf die Einkaufsliste, damit dein Partner sich darum kümmern kann.'),
  ('d3a41958-709d-460d-ae40-910c3a69b580', 'Wacht dein Kind mitten in der Nacht schreiend auf und lässt sich nicht beruhigen?', 'Die Trotzphase mit 2 Jahren kann sich auch auf den Schlaf auswirken. Lass die Schreianalyse die Laute deines Kindes auswerten, um herauszufinden, was ihm fehlt.'),
  ('07a0b7ef-0c8f-405e-aede-5d8c497ab1df', 'Ruhe wie in einer Höhle 🌌', 'Ist dein Kind vom Herumtoben nicht müde zu bekommen und will nicht ins Bett? Aktiviere den Einschlaftimer und spiele unter den Weißen Geräuschen das Rauschen des Waldes ab, um das Zimmer in eine ruhige Schlafhöhle zu verwandeln.'),
  ('9849f311-0e6e-4965-b1a2-164cf002508c', 'Zeit zum Hüpfen 🦘', 'Springt dein Kind zu Hause auf dem Sofa herum? Finde unter den mama-freundlichen Orten ein Freizeitzentrum mit Trampolin und weichem Boden, wo es sich sicher austoben kann.'),
  ('e6b6723c-fd0e-4884-94df-d412f5e903e7', 'Viel zu frühes Aufwachen! 🌅', 'Schon vor Sonnenaufgang hellwach? Hol dir jetzt praktische Tipps von unserem Anacan AI-Experten, um den Schlafrhythmus anzupassen.'),
  ('498eede0-22c9-4d0a-b512-067c46777cb9', 'Neue Wortschöpfungen 🗣️', 'Welches lustige Wort hat dein Baby heute erfunden? Halte diesen wunderbaren Meilenstein der Sprachentwicklung als Video mit Ton im Babyalbum fest – in ein paar Jahren werdet ihr herzlich darüber lachen.'),
  ('710fba45-03e1-4e84-9d81-f9c99d7d2c40', 'Mittags zum Umfallen müde?', 'Bereite dir mit unseren gesunden Rezepten einen Erdnussbutter-Smoothie zu, der dir sofort neue Energie gibt – ganz ohne Koffein.'),
  ('78d6a4b5-d4db-4754-8341-cf2bcc10342a', 'Endlose Show im Bett 🛌', 'Dein Kind hüpft im Bett, statt zu schlafen? Sieh dir die Übersicht im Schlaf-Timer an und finde sofort heraus, ob es noch überschüssige Energie hat oder bereits übermüdet ist.'),
  ('4622294e-c362-48ed-b4bf-63c35923b3ce', 'Warmer Tee und Ruhe 🍵', 'Der Timer ist abgelaufen, dein Kind schläft. Stürz dich jetzt nicht auf die Hausarbeit! Brüh dir eine Tasse Melissentee auf und genieße einfach die Ruhe.'),
  ('53c02e98-c468-40ac-9f02-6cb3c5e5158c', 'Ein Schutzschild aus Kalzium 🦴', 'Kalzium ist für Zähne und Knochen unverzichtbar. Prüfe mit dem Ernährungstracker, ob dein Kind heute genug Joghurt und Käse gegessen hat, und gleiche mögliche Defizite aus.'),
  ('f10247de-df8b-47ef-a539-e87f8db55ae2', 'Kleiner Arzt im Einsatz 🩺', 'Gibt dein Kind seinem Teddy eine Spritze oder hört es seinen Bauch ab? Die Fantasie läuft auf Hochtouren! Halte diesen süßen Moment gleich mit einem Baby-Fotoshooting fest und schaffe eine unvergessliche Erinnerung.'),
  ('1a31af42-99cc-4ebb-8d30-72e007760f62', 'Zeit für Ruhe 🤫', 'Bewahre mit dem Schallpegelmesser die Ruhe im Zimmer. Unterbrochener Nachtschlaf beeinträchtigt sowohl die Entwicklung deines Kindes als auch deine Stimmung am nächsten Morgen.'),
  ('bcb1a85f-15a5-4fe9-bbeb-6c1ae564f15a', 'Die letzten Backenzähne? 🦷', 'Kaut dein Kind scheinbar grundlos auf allem herum und hat ständig die Hände im Mund? Die hintersten Backenzähne (zweiten Molaren) könnten unterwegs sein. Schau unbedingt im Zahnungs-Tracker nach.'),
  ('e490e4c7-7ef7-4eec-a03a-11da14534526', 'Der Haushalt kann warten 🛑', 'Der Boden ist nicht gewischt? Dann lass ihn so. Ein schmutziges Zuhause lässt sich schnell wieder in Ordnung bringen, doch eine erschöpfte Mutter braucht lange, um sich zu erholen. Leg dich aufs Sofa und genieße einfach die Ruhe.'),
  ('753bfaff-7926-4516-b6b5-e78d2b60a270', 'Plötzlich ist Obst out 🍎', 'Gestern hat dein Kind das Obst noch geliebt und heute wirft es es auf den Boden? Wählerisches Essverhalten ist in diesem Alter ganz typisch. Entdecke bei den gesunden Rezepten lustige und abwechslungsreiche Ideen zum Anrichten.'),
  ('8b287134-38e5-4f28-8d41-3ba7f9bcd5b7', 'Fantasiespiele werden vielseitiger 🧸', 'Füttert dein Kind seine Spielsachen und bringt sie ins Bett? Seine Fantasie entwickelt sich gerade rasant! Halte diese ersten Zeichen von Empathie im Entwicklungs-Tracker fest.'),
  ('b884ea59-629f-4f5c-a2db-ce8f7aee5def', 'Gemeinsam seid ihr stark🥂', 'Wenn euer Kind eingeschlafen ist, macht euch gemeinsam einen Tee, lasst den Stress des Tages hinter euch und sagt einander: „Wir sind ein tolles Team.“ Zeigt euch gegenseitig eure Wertschätzung.'),
  ('26ecdf90-afa5-4aeb-a939-0e9c19c4397d', 'Analysieren wir den Tagesrhythmus ⏱️', 'Das Einschlafen am Abend hat 40 Minuten gedauert? Sieh dir die Übersicht im Schlaf-Timer an. Vielleicht ist jetzt genau der richtige Zeitpunkt, den Mittagsschlaf um 20 Minuten zu verkürzen und die Schlafenszeit am Abend vorzuverlegen.'),
  ('4efacff1-8d44-47f9-9c4b-52dbb8de0f37', 'Wutanfall in der Öffentlichkeit 🛒', 'Dein Kind hat sich im Supermarkt auf den Boden geworfen, weil es nicht bekommen hat, was es wollte? Ignoriere die Blicke der anderen und sprich mit Anacan AI darüber, wie du solche Wutanfälle gelassen bewältigen kannst.'),
  ('6e38a4cd-2c0a-4585-9a87-c6dd4f83a0a6', 'Keine Angst vor Schmutz!', 'Entdecke jetzt im Bereich „Empfohlene Produkte“ die besten Materialien für kinetischen Sand und andere sensorische Spiele und bestelle sie direkt zu dir nach Hause.'),
  ('031a9c48-32b8-49a9-a9d1-55eb165785a3', 'Proteinversorgung prüfen 🥚', 'Für schnell wachsende Muskeln ist Protein unverzichtbar. Berechne mit dem Ernährungstracker die heutige Zufuhr aus Eiern, Fleisch und Hülsenfrüchten und passe den Speiseplan an, falls noch etwas fehlt.'),
  ('9a014c54-2569-48f1-8b59-1e18b3b2e5b1', 'Fingermalerei! 🎨', 'Hat dein Kind beim Spielen mit Farben das ganze Gesicht verschmiert? Statt dich zu ärgern, kannst du diesen lustigen, kreativen Moment gleich mit fröhlichen Stickern aus dem Baby-Fotoshooting verzieren und ins Album hochladen.'),
  ('9b9b6d7f-8fb9-448e-ba10-0598457b94a6', 'Sind die nächtlichen Wachphasen zurück? ⏱️', 'Wacht dein Kind mitten in der Nacht weinend auf und findet nur schwer wieder in den Schlaf? Analysiere die Statistiken des Schlaftimers. Vielleicht dauert der Mittagsschlaf zu lange und bringt den Abendrhythmus durcheinander?'),
  ('87f68482-c94a-42ff-b3af-66083c5353fb', 'Nicht vorlesen, sondern erzählen 📖', 'Erzählt dir dein Kind bei der abendlichen Geschichte, was auf den Bildern zu sehen ist? Halte diesen wunderbaren Moment voller Fantasie als Audioaufnahme fest.'),
  ('9bde240a-b972-41fa-8294-7b553545ae04', 'Die Knochen werden stärker 🦴', 'Schnelles Wachstum erfordert Kalzium. Prüfe mit dem Ernährungstracker, ob dein Kind heute ausreichend Käse und Joghurt gegessen hat, und ergänze, was noch fehlt.'),
  ('ffa8de8b-2edf-4c8a-82b0-fb8a5415ce7b', 'Will dein Kind nicht teilen? 🧸', 'Läuft dein Kind im Park zu den Spielsachen anderer Kinder, will seine eigenen aber nicht hergeben? Erfahre im Blogbereich, wie du einem zweijährigen Kind beibringen kannst, sich beim Spielen abzuwechseln.'),
  ('0fca32b2-cafe-4f95-9933-261c2771f460', 'Analysieren wir den Tagesrhythmus genau ⏱️', 'Hat das Einschlafen am Abend 40 Minuten gedauert? Sieh dir die Grafik des Schlaftimers an. Vielleicht ist jetzt genau der richtige Zeitpunkt, den Mittagsschlaf um 20 Minuten zu verkürzen und die Schlafenszeit am Abend vorzuverlegen.'),
  ('3c1dc66a-c7fe-45c2-99c5-908555ae99a9', 'Mamas Energiebombe ⚡', 'Fallen dir vor lauter Herumrennen schon die Augen zu? Greif nicht zu Süßigkeiten, sondern zu Eiweiß! Lade deine Batterien mit einem Erdnussbutter-Smoothie auf, der sich nach einem unserer gesunden Rezepte für Frauen in nur 5 Minuten zubereiten lässt.'),
  ('83cfece3-b100-41d8-bb8e-0c02263c9e3e', 'Hat dein Baby Angst vor Schatten? 🌌', 'Beunruhigen dein Baby die Schatten an der Wand, wenn du das Zimmer abdunkelst? Die sich entwickelnde Fantasie kann Ängste auslösen. Spiele unter „Weißes Rauschen“ die Geräusche aus dem Mutterleib ab, damit sich dein Baby im Zimmer geborgen fühlt.'),
  ('a23bc347-ea83-491e-af00-0e80deaecf0f', 'Der erste Schritt zum Töpfchen? 🧻', 'Bleibt die Windel morgens völlig trocken und dein Baby wird unruhig? Das ist ein großartiges Zeichen. Halte es im Windel-Tracker fest und lies im Bereich „Blogs“, wie du dein Kind Schritt für Schritt auf das Töpfchentraining vorbereitest.'),
  ('46824a50-cc48-4a9c-ad3e-91d5073cd55e', 'Der „Nein!“-Sturm 🛑', 'Reagiert dein Kind auf jeden Vorschlag mit lautstarkem Protest? Hol dir jetzt von unserem Anacan AI-Experten wertvolle Tipps, wie du in dieser schwierigen Trotzphase um den 2. Geburtstag ruhig bleibst und Wutanfälle spielerisch entschärfst.'),
  ('51c7f01a-f92a-4f7e-97c1-5893c5304d42', 'Auf der Suche nach Logik 🧩', 'Einfache Spielsachen langweilen dein Kind inzwischen schnell. Entdecke im Bereich „Empfohlene Produkte“ Holzpuzzles und geometrische Spiele, die seine Denkfähigkeit fördern und die Konzentration stärken.'),
  ('a1d0bf30-60c8-4128-8527-423ff92dd8f8', 'Endloses Herumtoben 🏃‍♂️', 'Springt dein Kind auf den Sofas herum, statt ins Bett zu gehen? Starte den Schlaf-Timer, zeichne die Dauer des Einschlafens auf und prüfe anhand der Übersicht, ob du die Abendroutine vielleicht etwas vorverlegen solltest.'),
  ('1e0042aa-0b2b-4948-aaf5-3b9cec37c61f', 'Lustige Sätze 🗣️', 'Diese Sätze aus 3-4 Wörtern mit ihren niedlichen Fehlern sind Gold wert! Verpasse diesen wunderbaren Entwicklungsschritt nicht: Nimm sie gleich als Video mit Ton auf und füge sie dem Babyalbum hinzu, um die Erinnerung für immer festzuhalten.'),
  ('4d28b1d1-1b59-430b-a6d9-3d3ad8b1e671', 'Kann dein Kind seine Energie nicht loswerden und stellt alles auf den Kopf?', 'Öffne die Karte „Mama-freundliche Orte“, finde einen sicheren Spielplatz mit weichem Boden und Rutsche und lass dein Kind sich dort frei austoben.'),
  ('63d48088-e9cb-43c1-afc1-9e4bb32ff340', 'Deine kleine Kopie 📸', 'Wenn du das Zimmer fegst, wischt dein Baby dann auch mit einem Tuch oder läuft genauso wie du? Das Nachahmen ist jetzt auf seinem Höhepunkt!'),
  ('669259fd-a22a-4d24-b932-9eedd58dff3f', 'Zuckerfrei, aber süß 🍪', 'Schluss mit Keksen aus dem Supermarkt! Entdecke in den Babyrezepten gesunde Leckereien mit Datteln und Äpfeln, die du zu Hause in nur 10 Minuten zubereiten kannst, und mach deinem Baby eine Freude.'),
  ('14d92f0a-2caa-441a-b66e-e4531b0f2c30', 'Plötzliche Aggressivität 🛑', 'Schubst dein Kind andere, wenn es wütend ist, oder schlägt es nach dir? Frag jetzt Anacan AI, wie du die in diesem Alter stärker werdenden Emotionen sanft in die richtigen Bahnen lenken kannst.'),
  ('a1ab1785-3fde-4782-bfe0-d24e5fc6ec72', 'Tut dir der Rücken weh? 🧘‍♀️', 'Schmerzt dein Rücken vom Heben deines über 13+ kq schweren kleinen Schatzes? Tu dir etwas Gutes und bereite aus den gesunden Rezepten einen entzündungshemmenden Ingwertee zu, der die Muskeln entspannt.'),
  ('e3fde63e-bd7b-46c0-8b54-9e79a9f6fb65', 'Macht Stille deinem Baby Angst?', 'Spiele unter „Weiße Geräusche“ das Geräusch eines Ventilators oder Föhns ab und entdecke, wie es beim Schlafen ein wunderbares Gefühl von Geborgenheit schafft.'),
  ('7ac3c96c-42b7-4566-aa71-c52f9eb0b4eb', 'Brain Fog 🌫️', 'Bist du sehr müde und vergisst ständig etwas? Bereite aus den gesunden Rezepten für Frauen einen Omega-3-reichen Snack mit Walnüssen zu und schreib dir im Stimmungstagebuch alles von der Seele.'),
  ('8144388a-1733-475c-83c3-62e4fa74eb05', 'Keine Lust aufs Töpfchen? 🚽', 'Will dein Kind nicht aufs Töpfchen und weint? Frag jetzt unsere Anacan AI-Expertenhilfe, ob ihr beim Töpfchentraining eine Pause einlegen oder eine andere Methode ausprobieren solltet.'),
  ('aff8f3ff-854b-4c58-ae45-b01d9a3d3fdb', 'Isst dein Kind nur Obst? 🍎', 'Lehnt es Eiweißquellen oder Gemüse ab? Berechne mit dem Ernährungstracker, wie viele wertvolle Nährstoffe dein Kind heute aufgenommen hat, und stelle leckere Kombinationen wie Fruchtjoghurt zusammen.'),
  ('0e790195-f407-4908-a021-252afa265e2e', 'Mamas Flüssigkeitshaushalt 💧', 'Hast du beim Hinterherlaufen deines Kindes vergessen, Wasser zu trinken? Das könnte der Grund für deine Kopfschmerzen sein. Bereite dir nach einem der gesunden Rezepte für Frauen Detox-Wasser mit Minze und Zitrone zu und tanke neue Energie.'),
  ('704cb940-aadd-424e-94f9-6bfecacafa6d', 'Morgendlicher Verdauungscheck 💩', 'Achte beim Windelwechsel auf den Stuhlgang. Mit zunehmender Beikost steigt das Verstopfungsrisiko. Dokumentiere ihn in der App und ergänze mithilfe der Ernährungskontrolle ballaststoffreiche Lebensmittel wie Birne und Hafer.'),
  ('94804bde-ee95-44e1-87c0-8fe6a051dfb6', 'Angst vor plötzlichen Geräuschen 🌪️', 'Hat dein Baby Angst vor dem Staubsauger oder Mixer? Spiele im Zimmer unter „Weißes Rauschen“ das Geräusch eines Haartrockners ab. So kannst du seine Angst lindern und es zugleich sanft auf den Schlaf vorbereiten.'),
  ('0c2ed459-b6ef-4583-9c57-19766bfe4257', 'Farben sortieren 🔴🔵', 'Unterstütze die Entwicklung des logischen Denkens: Suche unter „Empfohlene Produkte“ nach altersgerechten geometrischen Puzzles und buntem Holzspielzeug, um die geistigen Fähigkeiten deines Kindes spielerisch zu fördern.'),
  ('1d490bb4-d589-47e3-911a-0660496e1c17', 'Beißen und Schlagen 🦖', 'Haut oder beißt dein Kind plötzlich, wenn es wütend wird? In den psychologischen Artikeln im Bereich „Blogs“ erfährst du, wie du mit den in diesem Alter stärker werdenden aggressiven Gefühlen behutsam umgehen kannst.'),
  ('f82f821d-7bd9-4cb7-9d17-c92628dde594', 'Sind die Schuhe plötzlich zu eng? 👟', 'Stolpert dein Kind beim Laufen häufig? Vielleicht sind seine Füße gewachsen! Trage die aktuelle Körpergröße und Schuhgröße in den Gewichts-Tracker ein, um seine körperliche Entwicklung zu verfolgen.'),
  ('ca3c13b4-94b6-44d7-a1be-1829a1d0e718', 'Die Knochen werden stärker 🦴', 'Schnelles Wachstum erfordert Kalzium. Prüfe mit der Ernährungskontrolle, ob dein Kind heute genug Käse und Joghurt bekommen hat, und gleiche mögliche Defizite direkt aus.'),
  ('cbda41ad-a761-4c07-b60f-6e77f3dd54cc', 'Du bist schon großartig 🌟', 'Heute bist du deinem Kind ununterbrochen hinterhergelaufen und nun erschöpft. Öffne das Stimmungstagebuch, notiere auch die kleinste gute Sache, die du heute für dein Kind getan hast, und schenke dir selbst einen großen Applaus!'),
  ('53d8ad5e-ba3b-4f31-a266-650eb5f83382', 'Kleine Haushaltshilfe 🧹', 'Wischt dein Kind beim Fegen auch mit einem Tuch hinterher oder stürzt es sich auf den Staubsauger? Verziere diese lustige Nachahmung gleich mit den Stickern aus dem Baby-Fotoshooting und lade das Bild ins Album hoch.'),
  ('9d0ac1c5-216f-4fa0-95d2-f983474b4839', 'Eisenspeicher prüfen 🥩', 'Damit dein aktiver kleiner Wirbelwind keine Blutarmut entwickelt, überprüfe im Ernährungstracker die heutige Eisenaufnahme aus Fleisch und Hülsenfrüchten und passe den Speiseplan an.'),
  ('8f01b040-4aa3-4a5f-a127-4287f88b0ef1', 'Die Kunst des Springens 🦘', 'Das Sofa reicht deinem Kind nicht mehr! Suche eine sichere Indoor-Spielhalle mit Trampolin, damit es sich so richtig austoben kann.'),
  ('cf348bab-0260-4da9-bc53-4069f0a6ddf3', 'Kleiner Künstler bei der Arbeit 🎨', 'Hat dein Kind beim Spielen mit Farben das ganze Gesicht verschmiert? Statt dich zu ärgern, genieße diesen lustigen, kreativen Moment.'),
  ('d6dd1818-c4fb-46af-be6f-20980791db71', 'Sind die nächtlichen Wachphasen zurück? ⏱️', 'Wacht dein Kind mitten in der Nacht weinend auf und findet nur schwer wieder in den Schlaf? Analysiere die Statistiken des Schlaf-Timers. Eine Schlafregression im Alter von 2 Jahren oder das Zahnen könnten die Ursache sein.'),
  ('1d5cbb75-8a18-4083-a6e5-10d5b00dd31c', 'Natürliche Beruhigung 🍃', 'War der Tag voller Lärm und Herumtoben? Verdunkle das Zimmer, spiele unter den Weißen Geräuschen das Plätschern eines Baches ab und gönne euch beiden eine wohltuende mentale Pause.'),
  ('947b2874-60ed-46dc-82cb-4ddf972a50b1', 'Wie steht es um die Proteinzufuhr? 🍗', 'Für aktive Muskeln ist Protein unverzichtbar. Prüfe mit dem Ernährungstracker die tägliche Nährstoffbalance deines Kindes und gestalte seinen Speiseplan abwechslungsreicher.'),
  ('f56b8fb7-fe66-42a7-afb0-9342dd02a543', 'Lieblingslieder 🎤', 'Singt oder summt dein Kind immer wieder dasselbe Lied? Halte sein Rhythmusgefühl und seine sprachliche Entwicklung fest, indem du diesen Moment mit den Musikstickern aus dem Baby-Fotoshooting ins Album aufnimmst.'),
  ('dc8f916f-27ea-45e1-9c5f-84435b0902fd', 'Ich will allein essen! 🥄', 'Nimmt dein Kind dir den Löffel weg und kleckert alles voll? Starte den Mahlzeiten-Timer und finde heraus, wie lange dieser Versuch, selbstständig zu essen, dauert. Lächle einfach über das verschüttete Essen hinweg.'),
  ('1d9a17fb-3ed7-4382-9eaf-1517914b5b98', 'Diese Hose will ich nicht! 👗', 'Hat die „Ich ziehe mich selbst an!“-Phase begonnen? Erfahre von Anacan AI, wie du morgendliche Kleiderkrisen reduzierst und deinem Kind die Freiheit gibst, selbst zu wählen.'),
  ('98d988ed-7e7f-4eb3-8b84-734112bb1929', 'Auch du brauchst Freunde 👯‍♀️', 'Bist du es leid, dich nur mit deinem Kind zu unterhalten? Finde unter den kinderfreundlichen Orten Zentren mit Spielgruppen, knüpfe Kontakte zu anderen Müttern und tausche Erfahrungen aus.'),
  ('f6ae40aa-d27d-4aed-a0d9-bd51bad467d7', 'Bücher lesen statt zerreißen 📖', 'Zerreißt dein Kind beim abendlichen Vorlesen die Seiten oder lässt dich nicht lesen? Frag Anacan AI gleich, wie du dieses Problem lösen kannst, ohne die Freude am Lesen zu beeinträchtigen.'),
  ('27d6b395-9576-4f2d-9566-57d41e7c6f41', 'Analysieren wir den Tagesrhythmus ⏱️', 'Das Einschlafen am Abend hat 40 Minuten gedauert? Sieh dir die Grafik des Schlaf-Timers an. Vielleicht ist jetzt genau der richtige Zeitpunkt, den Tagschlaf um 20 Minuten zu verkürzen und die Schlafenszeit am Abend vorzuverlegen.'),
  ('dec1d9f5-52bc-4c79-9c9c-281f44046beb', 'Die endlosen Warum-Fragen 🤔', 'Wird dein Kind des Fragens nie müde? Die „Was ist das? Warum?“-Phase hat offiziell begonnen! Erfahre in den Blogbeiträgen, wie du geduldig auf diese Entdeckungsfreude reagieren kannst.'),
  ('e68bbf03-3f37-41e8-a1d9-32feba8b86d7', 'Zuckerfrei und trotzdem süß 🍪', 'Schluss mit Keksen aus dem Supermarkt! Entdecke in den Babyrezepten gesunde Leckereien, die du zu Hause in 10 Minuten zubereiten kannst, und mach deinem Baby eine Freude.'),
  ('32443a45-bb1d-40cd-8cbf-77a3eda300d7', 'Heißer Kaffee und Ruhe 🍵', 'Der Timer ist abgelaufen, dein Kind schläft. Stürz dich jetzt nicht in die Hausarbeit! Bereite dir nach unseren gesunden Rezepten einen besonderen Kaffee zu, mach es dir auf dem Sofa gemütlich und genieße einfach die Ruhe.'),
  ('0963259b-f909-4657-ae5e-475b63d595ec', 'Aufstand gegen den Mittagsschlaf! 🛌', 'Will dein Kind mittags nicht schlafen und läuft davon? Frag Anacan AI nach dem Schlafbedarf von 2-Jährigen und Tipps für eine entspannte Ruhezeit (Quiet Time).'),
  ('0bba2ea7-ff2c-40db-9921-cae50208c766', 'Profi im Ausziehen! 🧦', 'Versucht dein Kind, seine Socken oder seine Hose selbst auszuziehen? Das ist ein großartiger Fortschritt in der motorischen Entwicklung.'),
  ('160a2dee-dfe4-4a75-b257-c4a10c478741', 'Die Kraft des Ingwers 🫖', 'Schmerzen dein Rücken und deine Beine, weil du den ganzen Tag unterwegs bist? Bereite dir aus den gesunden Rezepten einen muskelentspannenden Tee zu und gönn dir eine Pause.'),
  ('20369d8a-500f-4d0c-8f13-a85f623e07d2', 'Wir beobachten Vögel 🕊️', 'Langweilt sich dein Kind zu Hause? Sucht euch einen grünen Park, füttert gemeinsam die Vögel und stärkt so sein Mitgefühl für die Natur.'),
  ('69fc5add-e558-46f8-bee8-37acee27a9c1', 'Zeit, Geschichten zu erfinden 📖', 'Habt ihr genug vom Vorlesen? Schaltet das Licht aus, wählt bei den Weißen Geräuschen das Geräusch von Regen und erfindet im Dunkeln gemeinsam Fantasiegeschichten, bis ihr einschlaft.'),
  ('d25adde2-a568-4bad-bacf-b25822698f2a', 'Zurück zum Brei? 🥣', 'Ist dein Kind zu bequem, feste Nahrung zu kauen, und möchte wieder Brei? Entdecke bei den Babyrezepten spannende Rezepte für leicht zu kauende Bratlinge, die kein Brei sind.'),
  ('181e78e0-6fdf-4595-ab68-0d67492cb40c', 'Ich schenke selbst ein! 🥛', 'Möchte dein Kind das Wasser selbst ins Glas gießen und macht dabei alles nass? Entdecke unter den empfohlenen Produkten clevere, auslaufsichere Becher, mit denen es praktische Alltagsfähigkeiten üben kann.'),
  ('68364d15-562a-4922-a1dc-902274f2d63c', 'Knallt dein Kind mit den Türen? 🚪', 'Knallt dein Kind wütend mit den Türen und weint? Wende dich direkt an unseren Experten von Anacan AI und lerne Strategien kennen, um mit diesen heftigen Gefühlsausbrüchen umzugehen.'),
  ('de0f5d4f-9f96-42d7-a940-e7558af5d045', 'Nicht im Stehen snacken 🍎', 'Nimm dir Zeit für dich! Bereite aus unseren gesunden Rezepten einen antioxidantienreichen Beerensalat zu.'),
  ('7a5b3c40-a866-426b-8ed4-dd68302d6513', 'Die Liebe zum Toilettenpapier 🧻', 'Rollt dein Kind im Bad das Toilettenpapier ab und spielt damit? Nutze dieses Interesse und lies jetzt in den Blogs unseren Artikel darüber, wie der spielerische Übergang zum Töpfchentraining gelingt.'),
  ('d2a5512c-c089-47a6-aba1-367f406306e5', 'Eins, zwei, drei ... 🔢', 'Versucht dein Kind beim Treppensteigen, Dinge zu zählen? Das sind die ersten Anzeichen seiner mathematischen Entwicklung.'),
  ('f4ef4af2-bbdc-456f-a980-4eeb315c77b8', 'Sind jetzt alle Zähne da? 🦷', 'Brechen die letzten Backenzähne durch? Prüfe heute unbedingt mit dem Ernährungstracker, wie viel Joghurt und Käse dein Kind gegessen hat, um seinen erhöhten Kalziumbedarf zu decken.'),
  ('0480de3f-fc2e-475f-9c9a-7f062b43912d', 'Ist das Schlafzimmer zu warm? 🌡️', 'Wälzt sich dein Kind im Bett hin und her und schwitzt? Überprüfe die Raumtemperatur, aktiviere den Schlaf-Timer und sorge mit einem Ventilatorgeräusch aus den Weißen Geräuschen für ein Gefühl von Kühle.'),
  ('2b885719-7eb3-49f2-a501-3fdceb08a1dc', 'Weint dein Kind dir hinterher? 🚪', 'Ruft dein Kind dir sogar hinterher, wenn du nur kurz den Raum verlässt? Frage Anacan AI nach Tipps, wie du mit dieser neuen Phase der Trennungsangst behutsam umgehen kannst.'),
  ('4ef212ee-e501-41a3-bd1b-0f62028addbd', 'Logik im Einsatz 🧩', 'Wird dein Kind immer besser darin, geometrische Formen richtig zuzuordnen? Entdecke im Bereich „Empfohlene Produkte“ anspruchsvollere Spiele, die seine Denkfähigkeit noch stärker fördern.'),
  ('132f97c4-bee0-471c-ad8b-a7fc3585b9d6', 'Die richtige Zahnpasta wählen 🪥', 'Lernt dein Kind bereits, das Wasser auszuspucken? Lies unbedingt unseren wissenschaftlich fundierten Artikel im Bereich „Blogs“ darüber, ob eine Zahnpasta mit oder ohne Fluorid die richtige Wahl ist.'),
  ('250e2ef0-defa-4388-a9c2-8574f1be0fed', 'Kleine Küchenprofis 👩‍🍳', 'Knetet gemeinsam einen zuckerfreien Keksteig aus den Babyrezepten. So wird die Motorik deines Babys gefördert – und Selbstgemachtes schmeckt gleich noch besser.'),
  ('2ee3ac65-4c9f-4558-a181-e43a5be6a221', 'Kleiner Kletterprofi 🧗', 'Ist das Klettern auf Möbel schon zum Hobby geworden? Entdecke unter „Empfohlene Produkte“ spezielle Schutzvorrichtungen, um euer Zuhause so sicher wie möglich zu machen.'),
  ('e1c7d8a6-1882-42b5-8d1e-5420a73cc054', 'Sanftes Wasserrauschen 🌊', 'War der Tag besonders wild und turbulent? Dimme das Licht, wähle bei den Weißen Geräuschen das Plätschern eines Baches aus und genießt gemeinsam die Ruhe.'),
  ('09840996-6ece-429b-8105-2969a0ec7d4b', 'Sei stolz auf dich 🌟', 'Habt ihr den Tag ohne einen Wutanfall geschafft? Ohne dich wäre diese Entwicklung nicht möglich. Öffne das Stimmungstagebuch und schreibe dir selbst ein großes Dankeschön für deinen unermüdlichen Einsatz!'),
  ('152dc6e1-3207-4818-a59d-35cf71d6d914', 'Liebevolle Fürsorge für Spielzeug 🧸', 'Singt dein Baby seinem Teddy ein Schlaflied vor oder deckt ihn zu? Das ist ein deutliches Zeichen für die Entwicklung von Empathie. Halte diesen liebevollen Moment als Video mit Ton im Babyalbum fest.'),
  ('cb411136-f146-4918-b034-820fe50cfd21', 'Wortschatz-Explosion 🗣️', 'Wie entwickelt sich der Wortschatz deines Babys? Entdecke im Bereich „Blogs“ die Meilensteine der Sprachentwicklung für diesen Monat und Spiele für zu Hause, die diese Entwicklung unterstützen.'),
  ('047ed43c-bb7c-4206-afa0-67d1dc0f765d', 'Essen in lustigen Formen ⭐️', 'Mag dein Baby gewöhnlich geschnittenes Obst nicht? Entdecke in den Babyrezepten kreative Tellerideen in Stern- oder Tierform und mache das Essen zu einem visuellen Spiel.'),
  ('5f17b1b2-9554-4ba7-b535-5f0af1522385', 'Versteckt sich dein Baby fürs große Geschäft? 🙈', 'Zieht sich dein Baby hinter einen Vorhang oder in eine Ecke zurück, um sein großes Geschäft zu machen? Das ist eines der wichtigsten psychologischen Anzeichen für die Bereitschaft zum Töpfchentraining! Trage es im Windel-Tracker ein und lies die passenden Ratgeber im Bereich „Blogs“.'),
  ('c569bc01-3134-4ece-a6d6-d600fb0bf88b', 'Schmerzt dein Rücken? 🧘‍♀️', 'Vom Tragen deines immer schwerer werdenden kleinen Lieblings sind deine Muskeln verspannt. Bereite dir nach einem der gesunden Rezepte für Frauen einen entzündungshemmenden Ingwertee zu, leg dich hin und nimm dir etwas Zeit für dich.'),
  ('504aaa66-e4f6-4eca-bd17-eead2d69deec', 'Die Kunst des Selbstanziehens 👕', 'Versucht dein Kind, die Hose über den Kopf und das T-Shirt über die Beine zu ziehen? Lass dir diesen lustigen Versuch, selbstständig zu sein, auf keinen Fall entgehen! Verziere das Foto gleich mit den fröhlichen Stickern aus dem Baby-Fotoshooting und lade es ins Album hoch.'),
  ('c0ee7f2f-8895-4772-8368-647fe5fed56e', 'Pfützen-Expedition 🌧️', 'Nach dem Regen ist Drinnensitzen keine Option! Finde unter „Mama-freundliche Orte“ einen Park in deiner Nähe, zieh deinem Kind die Gummistiefel an und lass es im Matsch herumspringen.'),
  ('e70f443c-46d9-4882-ab14-fad93c425a0f', 'Das Schlaffenster verschiebt sich ⏱️', 'Hat dein Kind den Mittagsschlaf verweigert? Stelle den Schlaftimer und beginne die Abendroutine 30 Minuten früher, damit es am Abend nicht übermüdet ist und einen Wutanfall bekommt.'),
  ('65eaf451-e5ab-4c54-9b0f-1a6331bd0312', 'Die Feinmotorik entwickelt sich 🧩', 'Einfache Puzzles kennt dein Kind inzwischen auswendig. Entdecke unter „Empfohlene Produkte“ anspruchsvollere, mehrteilige Holzpuzzles, die seinen Verstand noch stärker fordern.'),
  ('c2a5ae09-9d8c-4ef8-afa7-4f35fb948c6f', 'Wutanfall auf dem Boden 🛑', 'Wirft sich dein Kind in der Öffentlichkeit auf den Boden und schreit? Ignoriere die Blicke der anderen! Sprich mit Anacan AI über deine Sorgen und lerne Strategien, um solche heftigen Gefühlsausbrüche gelassen zu bewältigen.'),
  ('f9afcff7-9182-4728-9ed2-135f5b97e440', 'Bücher lesen statt zerreißen 📖', 'Zerreißt dein Kind beim Vorlesen am Abend die Seiten? Lies im Bereich „Blogs“, wie du seine Aufmerksamkeit auf die Geschichte lenken kannst, ohne ihm die Freude am Lesen zu nehmen.'),
  ('11eb0bc9-4158-4fbc-8d65-97be316f8b92', 'Kalzium steckt nicht nur in Milch 🧀', 'Will dein Kind keine Milch trinken? Für gesunde Knochen ist Kalzium unverzichtbar. Erfasse heute mit dem Ernährungstracker, wie viel Käse, Joghurt oder Brokkoli es gegessen hat, und gleiche mögliche Defizite aus.'),
  ('51803c0a-8b62-474c-8ecd-e45188efdf2a', 'Wäsche-Faltspiel 🧺', 'Möchte dein Kind dir beim Wäschefalten helfen? Dann lass es die Sockenpaare zusammensuchen! In den Blogbeiträgen erfährst du, wie du spielerisch sein Verantwortungsbewusstsein stärkst.'),
  ('ede1e4a9-4d71-4eca-bacd-697cb6454edc', 'Angst im dunklen Zimmer 🌌', 'Weint dein Kind, wenn du das Licht ausschaltest? Mit seiner wachsenden Fantasie können auch Ängste zunehmen. Spiele unter „Weißes Rauschen“ die Geräusche aus dem Mutterleib ab und schenke ihm so das vertraute Gefühl von Geborgenheit.'),
  ('13aac5b4-c714-41fb-8e2e-16c1c92d8390', 'Wie entsteht Interesse an Büchern? 📖', 'Möchte dein Kind die Seiten lieber zerreißen, als der Geschichte zuzuhören? Frag Anacan AI nach praktischen Tipps, wie du seine Aufmerksamkeit auf die Geschichte lenkst, ohne ihm die Freude am Lesen zu nehmen.'),
  ('542e3a59-e25b-4803-a553-c3183744d2dc', 'Das Geheimnis der Eisenaufnahme: Vitamin C 🍋', 'Sieh dir den heutigen Speiseplan in der Ernährungskontrolle an, damit Eisen vom Körper optimal aufgenommen werden kann. Serviere zu einem Fleischgericht unbedingt einen Salat mit reichlich Zitronensaft oder Tomaten.'),
  ('bb3d49d9-8e03-48af-9a82-d11c505ca32b', 'Mamas Kaffeepause ☕', 'Lass die Hausarbeit kurz liegen und atme durch! Finde unter „Mama-freundliche Orte“ ein Café mit Spielecke, genieße in Ruhe deinen heißen Kaffee und lerne andere Mütter kennen.'),
  ('0d828df8-79e8-40c6-a759-0255d981435d', 'Der Klang der Nacht: Zug 🚂', 'Beunruhigt dein Kind die plötzliche Stille nach all den Geräuschen des Tages? Spiele unter „Weißes Rauschen“ das gleichmäßige Geräusch eines fahrenden Zuges ab, um andere Geräusche im Haus auszublenden und ihm beim Einschlafen zu helfen.'),
  ('8776b932-7a29-4e58-81cd-88646f84a4c7', 'Sind die Schuhe plötzlich zu eng? 👟', 'Stolpert dein Kind beim Laufen oder möchte es seine Schuhe ausziehen? Vielleicht sind seine Füße gewachsen! Trage die aktuellen Maße in den Entwicklungstracker ein und verfolge sofort seine körperliche Entwicklung.'),
  ('e742c56f-494a-46b7-82c7-113a5d4f0287', 'Zuckerfreie Energiekugeln 🍪', 'Schluss mit Süßigkeiten aus dem Supermarkt! Entdecke in den Babyrezepten gesunde, leckere Snacks mit Datteln und Haferflocken, die in nur 10 Minuten zubereitet sind, und mach deinem Kind eine Freude.'),
  ('c85cd72a-3a99-42a3-86ab-1fa1d9a4f422', 'Matschkuchen! 🧁', 'Will dein Baby draußen mit Erde spielen? Lass es ruhig schmutzig werden! Halte diese wunderbaren Momente, die die sensorische Entwicklung fördern, mit einem Baby-Fotoshooting für immer fest.'),
  ('da905da7-70f6-46f4-b372-c620f421daf8', 'Gönn deinem Kopf einen Neustart 🧘‍♀️', 'Wird dir gerade alles zu viel? Öffne das Stimmungstagebuch und schreibe 3 Minuten lang ohne Pause auf, was du fühlst. Schreiben kann Stress sofort reduzieren.'),
  ('929b30f1-695d-4f66-a22b-9182b15561c4', 'Der Schwerkraft-Test! 🍎', 'Lässt dein Baby Essen oder Spielzeug mit Begeisterung von oben herunterfallen? Erfahre mit Anacan AI, wie du diese physikalischen Entdeckungen sinnvoll umlenken kannst, statt sie zu unterbinden.'),
  ('a100b8dd-35f6-4549-ae5f-d60352e46cb5', 'Ballaststoffmangel? 💩', 'Ist der Stuhl hart und Verstopfung macht deinem Baby zu schaffen? Trage es im Windel-Tracker ein und füge mit der Ernährungskontrolle gleich Pflaumen oder Haferflocken zum Speiseplan hinzu.'),
  ('f0258928-f8cb-46a1-adb3-9d7138af115d', 'Der erste Spielkamerad 👯‍♂️', 'Versucht dein Kind im Park immer wieder, mit einem anderen Kind zu spielen? Entdecke unter „Mama-freundliche Orte“ kinderfreundliche Cafés, die diese neue Phase der sozialen Entwicklung unterstützen.'),
  ('0b94a795-dee1-49c6-a4fb-e07d6174147f', 'Auswertung des Schlaf-Timers ⏱️', 'Schläft dein Baby abends sehr spät ein? Sieh dir die Grafik des Schlaf-Timers an. Vielleicht ist es bald an der Zeit, den Tagschlaf zu verkürzen und die Schlafenszeit am Abend vorzuziehen.'),
  ('225bd8fb-b294-42ab-8941-6c8eee154c5f', 'Sind die Schuhe plötzlich zu eng? 👟', 'Stolpert dein Kind beim Laufen häufig? Vielleicht sind seine Füße gewachsen! Trage die aktuelle Körpergröße und Schuhgröße in den Entwicklungs-Tracker ein, um die körperliche Entwicklung zu verfolgen.'),
  ('f7cd700a-6bea-4a3e-a6b4-0018529f2ea2', 'Kaffee oder Wasser? 💧', 'Versuche nicht, deine Müdigkeit mit Koffein zu unterdrücken! Entdecke unter den gesunden Rezepten für Frauen energiespendende Detox-Getränke mit Protein und Früchten.'),
  ('d4efd00f-6d87-4868-a912-9b76b79425d0', 'Show vor dem Spiegel 🤪', 'Schneidet dein Baby Grimassen, betrachtet sich dabei und lacht laut los? Halte diesen lustigen Moment der Selbstentdeckung gleich als Video im Babyalbum fest und lass den Alltagsstress hinter dir.'),
  ('3f2f1108-7831-4796-88a8-5de7f4f81912', 'Auch du brauchst eine Pause ☕', 'Geh raus und schnapp ein wenig frische Luft! Finde unter den mamafreundlichen Orten ein Café mit Kinderecke in deiner Nähe, genieße in Ruhe deinen heißen Kaffee und lerne andere Mamas kennen.'),
  ('875b72c1-d353-4eb2-8649-bca828613387', 'Sei stolz auf dich 🌟', 'Jede neue Fähigkeit, die dein Baby erlernt, und jeder selbstbewusste Schritt sind auch das Ergebnis deiner Hingabe. Öffne das Stimmungstagebuch und schreibe heute einen Eintrag, für den du dir selbst stehenden Applaus geben würdest!'),
  ('9ccd2cce-af67-4d8c-b8c4-0ddfa25c77b1', 'Wirft dein Baby beim Essen alles herum? 🥣', 'Hat dein Baby keine Lust mehr, am Tisch zu sitzen, und wirft den Löffel weg? Starte den Ernährungstimer, analysiere die Dauer der Mahlzeiten in der Übersicht und vermeide es konsequent, dein Baby zum Essen zu zwingen.'),
  ('4bafd57a-0f5f-4a7d-8215-cfd63b08cad2', 'Nur Lebensmittel in einer Farbe? 🟡', 'Will dein Baby nur gelbe Lebensmittel wie Kartoffeln, Nudeln oder Bananen essen? Analysiere seinen Speiseplan mit dem Ernährungstracker und entdecke in den Babyrezepten farbenfrohe Alternativen mit geschickt verstecktem Gemüse.'),
  ('accea8e1-cb5f-4833-9081-056b6237ac04', 'Der Unterschied zwischen „ich“ und „du“ 🗣️', 'Spricht dein Kind nicht mehr in der dritten Person von sich, sondern sagt schon „ich“? Frage Anacan AI gleich nach Tipps für passende Dialoge, um diesen großen Entwicklungssprung im Denken zu unterstützen.'),
  ('f9e8a36b-3135-4421-adad-49b6ce187cf2', 'Noch eine Geschichte! 📚', 'Erfindet dein Kind ständig neue Ausreden, um nicht ins Bett gehen zu müssen? Starte den Schlaftimer, halte liebevoll an den Grenzen fest und lass unter „Weißes Rauschen“ Meereswellen erklingen, damit im Zimmer Ruhe einkehrt.'),
  ('52ee49fe-425d-44ef-9429-5ef1f4410d82', 'Die Kunst des Springens 🦘', 'Versucht dein Kind, von der Treppe oder vom Sofa zu springen? Für die motorische Entwicklung braucht es einen sicheren Ort. Finde unter den mamafreundlichen Orten einen Indoor-Spielpark mit Trampolin und lenke seine Energie in sichere Bahnen.'),
  ('81b85e80-d265-4f32-8c47-4b14aa23d8e1', 'Plötzliche Aggression 🦖', 'Schubst dein Kind andere Kinder oder schlägt es nach dir, wenn es wütend wird? Frag jetzt Anacan AI, wie du mit den heftigen Gefühlen in diesem Alter sanft und richtig umgehen kannst.'),
  ('bf03a99b-eae8-47d0-a5c6-eb2e17e62b7d', 'Vergiss dich selbst nicht ⚡', 'Geht dir mittags die Energie aus? Greif nicht zu Süßigkeiten! Bereite dir mit den gesunden Rezepten für Frauen einen proteinreichen Erdnussbutter-Smoothie zu, der sofort Energie liefert und deine Akkus wieder auflädt.'),
  ('fdde906c-a398-4012-a073-4015f9852301', 'Schlafanalyse mit Timer ⏱️', 'Hat das Einschlafen am Abend sehr lange gedauert? Starte den Schlaftimer und sieh dir die Grafik an. Finde heraus, ob dein Kind noch zu viel Energie hatte oder bereits übermüdet war.'),
  ('63af320f-f496-491d-b573-f5b6663a91e4', 'Warmer Tee und Ruhe 🍵', 'Der Timer ist gestoppt, dein Kind schläft. Lass jetzt bloß die Hausarbeit liegen! Brühe dir mit den gesunden Rezepten für Frauen einen Melissentee auf und lass die Müdigkeit des Tages mit dem warmen Dampf verfliegen.'),
  ('86e064b7-8da1-4aa9-b551-ca85b1a25e7c', 'Wie steht es um die Proteinversorgung? 🍗', 'Muskeln, die ständig rennen und springen, brauchen unbedingt Protein. Überprüfe mit dem Ernährungstracker die tägliche Nährstoffbalance deines Kindes und gestalte seinen Speiseplan abwechslungsreicher.'),
  ('947ec858-749d-4a0f-bf72-73a1503e2c5f', 'Die endlosen Warum?-Fragen 🤔', 'Was ist das? Warum ist das so? Diese Phase hat jetzt offiziell begonnen! In den Blogbeiträgen erfährst du, wie du die unendliche Entdeckerlust deines Kindes geduldig und entwicklungsfördernd begleiten kannst.'),
  ('5d69eb5c-8ed9-4c1d-9b48-d1c46bb4e1fb', 'Alte Sprachaufnahmen 🎤', 'Öffne nach dem Einschlafen deines Kindes das Babyalbum und hör dir die süßen Laute an, die es vor Monaten gemacht hat. Staune darüber, wie schnell es wächst, und sei stolz!'),
  ('c3ea09ec-b61b-40ca-8245-a6b47232b78f', 'Die Meins!-Phase 🧸', 'Will dein Kind im Park kein Spielzeug mit anderen teilen? Frag Anacan AI, wie du Kindern, die auf das Alter von 2.5 Jahren zugehen, beibringen kannst, sich beim Spielen abzuwechseln.'),
  ('f8fbff5d-2a79-4ebc-90f5-c58d315a80ab', 'Auch du hast einen Akku 🔋', 'Bist du erschöpft davon, den ganzen Tag Nein zu sagen und hinter deinem Kind herzurennen? Schreib dir deinen inneren Frust im Stimmungstagebuch von der Seele. Denk daran: Zeit für dich selbst ist kein Luxus, sondern ein Bedürfnis.'),
  ('fb79060e-f7c1-4e3e-983a-bf84e747b66e', 'Die Schuhe sind vertauscht! 👟', 'Zieht dein Kind den rechten Schuh links und den linken rechts an und will sie nicht mehr ausziehen? Verziere diesen lustigen Versuch, selbstständig zu sein, mit fröhlichen Stickern aus dem Baby-Fotoshooting und mach daraus die witzigste Aufnahme im Album.'),
  ('10f0ddfb-06ae-4780-9b39-ba433d0edc10', 'Banane oder Telefon? 🍌', 'Hält dein Kind eine Banane oder die Fernbedienung ans Ohr und führt Fantasiegespräche? Was für ein fantasievolles Spiel! Halte diesen kostbaren Moment für immer fest, indem du das Video mit Ton sofort zum Babyalbum hinzufügst.'),
  ('24cc9d6f-2286-4f7a-a81a-633ab5dd91df', 'Angst im dunklen Zimmer 🌌', 'Hält dein Kind die Gegenstände im Zimmer für Monster, sobald du das Licht ausschaltest? Mit wachsender Fantasie entstehen auch Ängste. Spiele unter „Weißes Rauschen“ Gebärmuttergeräusche ab und vermittle ihm so wieder das vertraute Gefühl vollkommener Geborgenheit.'),
  ('3c29abba-6cf4-47d2-a227-99611ccf0101', 'Das Geheimnis von Eisen und Energie 🥩', 'Damit dein aktives Kleines keine Blutarmut entwickelt, überprüfe in der Ernährungskontrolle die heutige Eisenaufnahme (Fleisch, Linsen, Spinat) und ergänze den Speiseplan mit Vitamin-C-reichen Lebensmitteln.'),
  ('074c97a3-66b5-4499-b8dd-c6ca41189da1', 'Flüssigkeitszufuhr und Verstopfung 💧', 'Tobt dein Kind viel herum, trinkt aber wenig Wasser? Achte beim Windelwechsel auf den Stuhlgang. Besteht das Risiko einer Verstopfung, notiere es in der App und ergänze über die Ernährungskontrolle sofort ballaststoffreiche Lebensmittel (Birne, Haferflocken).'),
  ('33f7b16f-fd6e-4686-be50-8b9aabfa4a20', 'Meister der Farben und Formen 🔴🟩', 'Sortiert dein Kind Gegenstände, Knöpfe oder Spielzeug nach Farben? Entdecke jetzt unter „Empfohlene Produkte“ Holzpuzzles, die sein Denkvermögen noch stärker fordern und das logische Denken fördern.'),
  ('912d3d15-f8b0-4ade-8219-5e9c81b99f0a', 'Nachtschreck oder Albtraum? 🤖', 'Wacht dein Kind mitten in der Nacht weinend auf und lässt sich nicht beruhigen? In unseren wissenschaftlich fundierten Artikeln im Blog erfährst du, wie du beides unterscheiden und psychologisch richtig reagieren kannst.'),
  ('0ba368ce-9746-48c2-a3e5-a973ee982121', 'Nudelliebe 🍝', 'Dein Kind möchte seit Tagen immer dasselbe essen? Wählerisches Essverhalten hat gerade Hochkonjunktur. Suche in den gesunden Rezepten nach leckeren, originellen Soßen, in denen du Gemüse verstecken kannst.'),
  ('92abce30-d667-4f40-9371-ee7642e09a28', 'Genieße die Stille 🤫', 'Endlich ist Ruhe eingekehrt. Lass die Aufgaben liegen und setz dich ins Dunkle. Aktiviere den Geräuschpegelmesser, miss diese wunderbare Stille und gönn deinem Kopf eine Pause.'),
  ('e50a9ce1-a01a-4462-9bc9-e410e94685ff', '800 geschafft!🚀', 'Jetzt ist die Zeit für noch mehr Fragen, mehr Bewegung und eine immer stärker werdende Persönlichkeit. Atme tief durch und starte in diese neue, aufregende Phase.'),
  ('0ea063ed-fd41-47e6-9ae7-1268a3f1138f', 'Der Mythos von der perfekten Mutter 🛑', 'Machst du dir Vorwürfe, weil die Bildschirmzeit heute zu lang war? Vergiss die scheinbar perfekten Mütter im Internet. Du bist mit deiner ganz eigenen Realität perfekt.'),
  ('6e5882b6-b1b9-4876-8253-b97551d73f12', 'Papa ist der Spielleiter 👨‍👧', 'Deine Geduld ist am Ende? Schließ die Zimmertür und lass dein Kind mit seinem Papa allein. Heute Abend darf er zu Hause das Kommando beim Spielen übernehmen.'),
  ('c72b4558-e629-4a4b-bb39-ef072b6603b3', 'Die Warum-Phase 🤔', 'Fragt dein Kind bei allem: „Warum ist das so?“ Sein Gehirn saugt Informationen auf wie ein Schwamm. Hab Geduld und gib ihm kurze, verständliche Antworten.'),
  ('015a0c8f-c960-422b-8198-6bdb85909e68', 'War es ein schwieriger Tag? 📝', 'Schreib den heutigen Stress in dein Stimmungstagebuch und lass alles raus. Alle Mütter erleben solche Krisen – du bist nicht allein.'),
  ('5229a519-68a8-4340-8bba-d14464123530', 'Fantasievolle Spiele 🧸', 'Lässt dein Kind seine Autos sprechen oder füttert es seinen Teddybären? Seine Fantasie blüht gerade richtig auf. Halte diesen kognitiven Entwicklungssprung im Entwicklungstracker fest und spiel mit.'),
  ('f0d11fbf-f594-485d-b316-f567d5c6731d', 'Langweilt ihr euch zu Hause?', 'Entdecke unter den mama-freundlichen Orten ein Café mit Kinderspielecke. Dein Kind spielt und du kannst deinen Kaffee warm genießen.'),
  ('b9ab0ee4-3e32-4c6f-9669-cbb581181150', 'Musikalische Geborgenheit 🎶', 'Die einfachste Möglichkeit, Quengeleien am späten Nachmittag zu beruhigen: Spiel seine Lieblingsmelodie, nimm dein Kind in den Arm und tanzt langsam zusammen.'),
  ('c4cbfe42-b7f8-4e4c-ad6a-198774caa2d6', 'Bleibt ihr wegen des wechselhaften Wetters zu Hause?', 'Mit dem Wetter- und Kleidungshelfer erfährst du sofort, wie warm es draußen wirklich ist. Dann ab in den Park!'),
  ('ce87972f-2f28-45fe-80b3-aa0ec4116930', 'Ich ziehe mich selbst an 👕', 'Auch wenn dein Kind sich die Hose über den Kopf zieht, solltest du seine Versuche, sich selbst anzuziehen, nicht unterbrechen. Sein Wunsch nach Selbstständigkeit ist gerade besonders groß! Gib ihm Zeit und lass es ausprobieren.'),
  ('43a750e7-aff2-4c1a-baec-6890bc56e642', 'Ich schenke selbst ein! 🥛', 'Dein Kind möchte das Wasser selbst ins Glas gießen und macht dabei alles nass? Suche bei den Produktempfehlungen nach praktischen, auslaufsicheren Kinderbechern, die Alltagskompetenzen fördern und dir das Leben erleichtern.'),
  ('8d131ccb-5e19-4d42-b8a6-86bf255b1f23', 'Kleine Küchenhilfe 👩‍🍳', 'Bereitet gemeinsam nach einem Babyrezept zuckerfreien Bananenkeksteig zu. So wird die Motorik deines Kindes gefördert, es hat Spaß und kann anschließend sein selbst gemachtes Werk mit Appetit genießen.'),
  ('bd7400ff-b3f7-4318-9c68-166242aa98f9', 'Warmer Tee und Ruhe 🍵', 'Der Timer ist abgelaufen, dein Kind schläft. Stürz dich jetzt nicht auf den Haushalt! Bereite dir nach unseren gesunden Rezepten einen Melissen- oder Kamillentee zu, mach es dir auf dem Sofa gemütlich und genieße einfach die Ruhe.'),
  ('65e69d4e-9f8b-4e23-8934-10178d918f6b', 'Deins? Meins! 🧸', 'Dein Kind möchte im Park das Spielzeug eines anderen Kindes nicht zurückgeben? Es befindet sich in der egozentrischen Entwicklungsphase. Bring ihm das Teilen nicht mit Zwang bei, sondern indem ihr euch abwechselt.'),
  ('71700719-be0c-45bf-8d93-6cb51d48ed2d', 'Kleine Leseratte 📖', 'Bringt dein Kind immer wieder sein Lieblingsmärchenbuch und möchte, dass du ihm dieselbe Seite vorliest? Wiederholungen helfen ihm beim Lernen. Lies sie geduldig noch einmal vor.'),
  ('d6aaa644-5d8a-47cd-b998-227fc0b6f04b', 'Die Hausarbeit kann warten 🛑', 'Der Boden ist nicht gewischt? Dann lass ihn so. Ein schmutziges Zuhause lässt sich wieder in Ordnung bringen, doch eine erschöpfte Mutter braucht lange, um sich zu erholen. Leg dich aufs Sofa und genieße die Ruhe.'),
  ('04312503-34be-494a-8896-38312d406a86', 'Eine imaginäre Teestunde 🫖', 'Musst du oder müssen die Kuscheltiere aus imaginären Tassen Tee trinken? Rollenspiele sind ein Höhepunkt der geistigen Entwicklung!'),
  ('149beadc-5c37-404b-8b3e-f6ce437629da', 'Nackenschmerzen bei Mama 🧘‍♀️', 'Sind dein Nacken und Rücken vom Spielen auf dem Boden und Hochheben deines Kindes verspannt? Gönn dir eine Pause und bereite dir aus den gesunden Rezepten einen muskelentspannenden, entzündungshemmenden Grüntee mit Ingwer zu.'),
  ('2daba5bf-3da2-43ab-bc87-fdc726c1aabb', 'Ein Monster unter dem Bett? 👾', 'Mit der Fantasie wachsen auch die Ängste und fühlen sich ganz real an. Wenn dein Kind Angst vor Schatten hat, dimme das Licht und spiele unter den Weißen Geräuschen den Klang aus dem Mutterleib (Herzschlag) ab. So schenkst du ihm das vertraute Gefühl vollkommener Geborgenheit.'),
  ('d0a47f18-7e98-462c-be4f-167fcf918411', 'Streit ums Rutschen 🛑', 'Dein Kind möchte im Park nicht warten, bis die anderen Kinder an der Reihe waren? Lies unbedingt die Artikel zur sozialen Entwicklung im Bereich Blogs. Dort erfährst du, wie du ihm mit etwa 2.5 Jahren beibringen kannst, zu warten und geduldig zu sein.'),
  ('dc66703c-31b3-4677-a6cd-dc09bb5b60cf', 'Mach dir keine Vorwürfe 💖', 'Hat dich die Trotzphase heute an deine Grenzen gebracht und du bist laut geworden? Schreib dir deinen Frust im Stimmungstagebuch von der Seele. Du bist kein Roboter und musst nicht perfekt sein!'),
  ('f9ec5212-0b50-47f7-b50f-84f41a8701a2', 'Verkehrt herum ist jetzt in! 👕', 'Dein Kind hat die Hose verkehrt herum und die Schuhe am falschen Fuß angezogen und will sie nicht ausziehen? Greif bei diesem lustigen Versuch, selbstständig zu sein, nicht ein!'),
  ('46ca17b0-646f-46ee-9f74-a67a0f778d4f', 'Der Held des Märchens 🪄', 'Erstelle heute Abend bei den Schlauen Märchen eine besondere Geschichte, in der dein eigenes Kind die Hauptrolle spielt: Der mutige kleine Held, der die Nacht liebt.'),
  ('44efc816-fa09-4bf6-a073-38bbffbb2693', 'Eine liebevolle Umarmung 🫂', 'Kommt dein Kind plötzlich zu dir, umarmt dich oder streichelt dein Gesicht? Es zeigt seine Liebe jetzt auch durch Berührungen. Genieße diesen Moment.'),
  ('764398f1-2f82-4a41-a767-bcf8004dd068', 'Dinge an ihren Platz räumen 🧸', 'Wirft dein Kind ein Spielzeug in die Kiste und holt es wieder heraus? So entwickelt sich sein Verständnis für „drinnen“ und „draußen“. Halte diese kognitive Fähigkeit unbedingt im Entwicklungstracker fest.'),
  ('850a613f-ecbc-4d9b-ab63-9701c3f268f9', 'Hast du eine Frage? 🤖', 'Wie sollte sich die Sprache eines Kindes nach dem 2. Geburtstag entwickeln? Verlier dich nicht in den Weiten des Internets: Schreib direkt an Anacan AI und erhalte eine wissenschaftlich fundierte Antwort.'),
  ('4fcc8b4e-e106-490a-a901-8c89be671af5', 'Jetzt kommen längere Sätze! 🗣️', 'Verbindet dein Kind schon 4-5 Wörter und erzählt damit eine lustige Geschichte? Sein Wortschatz wächst jetzt rasant! Verpasse diesen wertvollen Moment nicht: Nimm ihn gleich als Sprachnachricht im Babyalbum auf und halte so die Entwicklung fest.'),
  ('569d530d-d6b9-4460-be46-292c62f656dd', 'Auf der Suche nach Logik 🧩', 'Dein Kind kennt einfache Puzzles aus zwei bis drei Teilen schon auswendig. Im Bereich „Empfohlene Produkte“ findest du anspruchsvolleres Holzspielzeug, das sein Denkvermögen fördert und ihm hilft, Ursache und Wirkung zu verstehen.'),
  ('ce1a09c7-d2c5-485b-a920-bc02df41fb58', 'Sturm in der Badewanne 🛁', 'Dein Kind möchte nicht aus dem Wasser und weint? Frag Anacan AI direkt nach ablenkenden Spielzeugen und praktischen Übergangsstrategien, mit denen ihr die Baderoutine stressfrei beenden könnt.'),
  ('32be8503-ee3d-483e-baae-9b3b130b80cc', 'Streit ums Rutschen 🛑', 'Möchte dein Kind im Park nicht warten, bis die anderen Kinder an der Reihe waren? Lies in den Artikeln zur sozialen Entwicklung im Bereich „Blogs“, wie du ihm mit etwa 2.5 Jahren beibringen kannst, zu warten und zu teilen.'),
  ('36818534-e1f7-451b-9f88-51bf852bc139', 'Aufstand gegen den Mittagsschlaf! ⏱️', 'Dein Kind hat den Mittagsschlaf verweigert und ist jetzt völlig übermüdet? Sieh dir den Schlafrhythmus im Schlaf-Timer an und zieh die Abendroutine um mindestens 40 Minuten vor, um Nachtschreck vorzubeugen.'),
  ('54668cb8-852a-467f-9492-c88f3b1ba329', 'Hält dein Kind den Stuhl zurück? 💩', 'Steht dein Kind kurz vor dem Töpfchentraining und hält sein großes Geschäft zurück? Das kann zu psychisch bedingter Verstopfung führen. Notiere es im Windel-Tracker und ergänze den Speiseplan sofort um Aprikosen oder Haferflocken.'),
  ('d3a86832-34ed-43f4-90d5-a80f77b22f80', 'Zu Hause fällt ihm die Decke auf den Kopf 🌳', 'Kann dein Kind drinnen seine Energie nicht loswerden und wirft alles durch die Gegend? Öffne die Karte mit kinderfreundlichen Orten für Mamas, finde einen sicheren Spielplatz mit weichem Boden und Rutsche und lass dein Kind sich draußen frei austoben.'),
  ('24023d7c-2bc9-4102-89e5-fd869c13910d', 'Wachstumsschub bei Größe und Gewicht! 📏', 'Ist dir beim Anziehen aufgefallen, dass die Oberteile enger sitzen oder die Schuhe drücken? Trage die aktuelle Größe und die Maße in den Gewichts-Tracker ein und beobachte stolz, wie die Wachstumskurve ansteigt.'),
  ('af6b0980-8f3e-49f7-8539-9fc05967e656', 'Überprüfe die Eisenversorgung 🥩', 'Ist dein Kind blass oder schnell müde? Überprüfe in der Ernährungskontrolle die heutige Eisenzufuhr und gib zu Fleisch immer auch Vitamin C (Zitrone, Tomate), um die Eisenaufnahme zu verbessern.'),
  ('f5e0ef2c-4838-48df-b45d-d158a473879a', 'Auch du brauchst Gesellschaft 👯‍♀️', 'Bist du es leid, den ganzen Tag nur in Kindersprache zu sprechen? Finde über die kinderfreundlichen Orte für Mamas ein Kindercafé, in dem sich viele Mütter treffen, und schaffe auch dir Gelegenheit für soziale Kontakte.'),
  ('3046868d-cc9d-4ca4-8350-b813468ec4dd', 'Was ihr dringend braucht 🛒', 'Shampoo, Windeln oder Haferflocken sind aufgebraucht? Behalte es nicht nur im Kopf: Schreib es auf die Einkaufsliste und synchronisiere sie mit deinem Partner.'),
  ('437a3027-38a4-47b2-a62c-a24094b2e7eb', 'Wirft sich dein Kind auf den Boden und schreit, wenn es nicht bekommt, was es will?', 'Wutanfälle im Kleinkindalter kommen weiterhin vor. Bleib ruhig in der Nähe und nimm dein Kind in den Arm, sobald es sich beruhigt hat.'),
  ('bbf3c14f-5832-4554-88a9-fc0b10c25324', 'Seiten werden lebendig 📖', 'Erfindet dein Kind beim Vorlesen selbst das Ende der Geschichte? Entdecke mit Anacan AI interaktive Vorlesetechniken, die diesen wunderbaren Moment der Fantasie fördern.'),
  ('c3d03381-340f-4ce1-b075-de3e6584aed7', 'Flüssigkeitszufuhr und Verstopfung 💩', 'Tobt dein Kind viel herum, trinkt aber wenig Wasser? Achte beim Windelwechseln (oder auf dem Töpfchen) auf den Stuhlgang. Besteht ein Verstopfungsrisiko, trage es in der App ein und ergänze den Speiseplan mithilfe der Ernährungskontrolle direkt um Pflaumen oder Haferflocken.'),
  ('275e7b7b-377b-40f0-9e43-ab5886fc93b4', 'Spielen mit dem Essen 🥦', 'Zerdrückt dein Kind die Nudeln und verteilt sie überall, statt sie zu essen? In diesem Alter ist Essen auch ein Spielzeug. Trage im Ernährungsplan ein, wie viel es gegessen hat, und behalte so die wöchentliche Ausgewogenheit im Blick.'),
  ('7af19435-be8e-48dc-a066-aab689899f04', 'Morgenphilosophie 🧦', 'Wollte dein Kind heute Morgen die Socke über die Hand ziehen? Lass dich von solchen Entdeckungsmomenten, die oft von Eigensinn begleitet werden, nicht aus der Ruhe bringen. Lass es ruhig eine Weile so herumlaufen – damit erprobt es seine Selbstständigkeit.'),
  ('f13502d3-76f4-47c6-bfef-ed2cb1d9fcf7', 'Die magische Kraft des Wassers 🛀', 'Nach einem ganzen Tag voller Bewegung seid ihr beide erschöpft. Ein warmes Bad dient nicht nur der Sauberkeit, sondern ist auch eine wunderbare Möglichkeit, das Nervensystem deines Kindes zu beruhigen.'),
  ('1b2a22e9-6d73-4469-8535-2d773936acd1', 'Egoismus im Park 🧸', 'Will dein Kind beim Spielen im Sand sein Förmchen mit niemandem teilen? Mit 27 Monaten ist das Verständnis für das Teilen noch kaum ausgeprägt. Wirf ihm keinen Egoismus vor, sondern erkläre ihm einfach, dass alle der Reihe nach dran sind.'),
  ('57e50587-fc65-4605-a4e9-bbde134adfea', 'Papas Stimme 📖', 'Sorgt heute Abend für eine ganz andere Atmosphäre im Zimmer. Überlass das Vorlesen oder Geschichtenerzählen Papas tiefer, beruhigender Stimme und gönn dir währenddessen eine Pause.'),
  ('64f0ac54-c21f-4a4c-bcce-53662284a4f5', 'Ein erstaunliches Gedächtnis 🧠', 'Hat dein Kind heute Morgen genau die Stelle gefunden, an der du gestern sein Spielzeug versteckt hast? Sein Langzeitgedächtnis ist bereits erstaunlich gut entwickelt.'),
  ('99e86be1-9932-47a0-b9a8-f6b98dc7dfcf', 'Protest gegen den Mittagsschlaf 🥱', 'Dein Kind will keinen Mittagsschlaf machen und wehrt sich dagegen? Manche Kinder brauchen in diesem Alter keinen Mittagsschlaf mehr. Statt darüber zu streiten, könnt ihr eine Ruhezeit einführen und gemeinsam im Bett Bücher anschauen.'),
  ('f80a3604-81aa-4362-9508-4aa4c845b4bc', 'Die Raumakustik 🤫', 'Dein Kind schreckt beim kleinsten Geräusch auf, sobald es eingeschlafen ist? Überprüfe die Raumakustik mit einem Schallpegelmesser und nutze weißes Rauschen, um Geräusche von draußen zu überdecken.'),
  ('25092d10-5861-4eec-8fa9-86857d835418', 'Kleine Haushaltshilfe 🧹', 'Versucht dein Kind, dir die Wäsche oder den Wischmopp aus der Hand zu nehmen, wenn du Wäsche faltest oder den Boden wischst? Es fühlt sich schon ganz groß. Gib ihm ein kleines Tuch und lass es mithelfen.'),
  ('739e50cd-5199-4e7e-9448-99a52d59a069', 'Kissenburg 🏰', 'Verwandelt das Zimmer heute Abend in einen Spielplatz. Baut aus Sofakissen eine kleine Burg und krabbelt hinein. Es wird zwar etwas chaotisch, aber das gemeinsame Lachen ist es auf jeden Fall wert.'),
  ('a9e6d37d-aa66-4119-abcb-6619dfc78256', 'Aufmerksamkeitstest 🧩', 'Spielt dein Kind inzwischen 10-15 Minuten lang mit demselben Spielzeug? Seine Aufmerksamkeitsspanne wird länger.'),
  ('1a9b02d2-5d73-4e72-a7df-f4672edf0835', 'Abendroutine mit Papa 👨‍🍼', 'Überlass es heute Abend Papa, euer Kind bettfertig zu machen, ihm die Zähne zu putzen und den Schlafanzug anzuziehen – und genieße in aller Ruhe deinen Tee.'),
  ('6c74968c-8cc0-4bee-8ae3-eae708b5b244', 'Was soll ich nur kochen? 🍲', 'Du hast keine Idee, was du heute kochen sollst? Verlier dich nicht im Internet, sondern entdecke im Bereich „Blogs“ der App neue und einfache Rezepte in den Artikeln zur Kinderernährung.'),
  ('855cedcf-292a-4a61-b049-6fd355b3a599', 'Ursache und Wirkung entdecken 🤔', 'Was passiert, wenn ich das fallen lasse? Wozu ist dieser Knopf da? Dein Kind führt ständig kleine praktische Experimente durch. Überprüfe deshalb noch einmal, ob euer Zuhause kindersicher ist.'),
  ('1fe350a6-fb9b-4b57-8832-dec2f74e4b97', 'Laufmarathon 🏃‍♂️', 'Gehen ist ihm inzwischen zu langweilig – es rennt nur noch! Räumt kleine Hindernisse aus der Mitte des Zimmers und beobachtet diese unerschöpfliche Energie mit einem Lächeln.'),
  ('a661f7cf-1a9f-46de-b66d-252b9874aa1c', 'Spiele im Dunkeln 🐰', 'Dein Kind möchte nicht einschlafen und fürchtet sich im Dunkeln? Verdunkle das Zimmer vollständig und veranstalte mit deinen Händen ein Schattentheater an der Wand. So wird aus Angst jede Menge Spaß.'),
  ('a8a8e76c-4244-41ff-a34c-127f03070b5f', 'Mamas Offline-Zeit ☕', 'Wenn dein Kind ganz in seine eigene Welt versunken mit seinen Puppen spricht, lauf nicht sofort zum Geschirrspüler. Gieß dir einen Kaffee ein, leg auch dein Handy beiseite und gönn dir 15 Minuten ganz offline.'),
  ('41bea9aa-47ca-48e8-8cd4-15b1a0a181a6', 'Die ersten längeren Sätze 🗣️', 'Mama, das Auto ist dorthin gefahren! Dein Kind reiht nun Wörter aneinander und bildet sinnvolle Sätze. Hör dir diese historischen Momente an und halte sie unbedingt als Erinnerung im Entwicklungstracker fest.'),
  ('69b61ce4-2f0a-419f-8ea0-47c763ae7f20', 'Zeit für den Blog 📱', 'Ist jetzt der richtige Zeitpunkt, um mit dem Töpfchentraining zu beginnen? Wenn du unsicher bist, besuche den Blogbereich der Anacan-App und lies die von Fachleuten verfassten und kinderärztlich geprüften Artikel.'),
  ('8ba7811e-fc92-4ddc-b1e8-28de83aa7843', 'Tagesrückblick 📝', 'War es ein schwieriger Tag? Schreib den ganzen Stress von heute in dein Stimmungstagebuch und lass alles raus. Alle Mütter erleben solche heftigen Gefühlsausbrüche – du bist nicht allein.'),
  ('3932254a-4956-424d-86dc-117f82815e3f', 'Wasser? Nein, danke! 💧', 'Dein Kind verlangt statt Wasser ständig nach süßen Säften? Berechne seinen täglichen Wasserbedarf und biete ihm Wasser in bunten, interessanten Bechern an.'),
  ('7f344552-48d5-4a0e-95d3-b9aa7199f33a', 'Fantasiegeschichten 🎭', 'Lässt dein Kind seinen Spielzeugbären sprechen und erzählt ihm erfundene Geschichten? Seine Fantasie kennt keine Grenzen! Beobachte es aus einiger Entfernung und greif nicht ein.'),
  ('eda9b33e-46f7-44ed-b1db-b9ad146b53a3', 'Ohne Märchen geht es nicht ins Bett 🪄', 'Klassische Märchen wecken nicht mehr die Aufmerksamkeit deines Kindes? Erstelle mit den smarten Märchen eine ganz persönliche Geschichte, in der dein Kind selbst die Hauptfigur ist.'),
  ('67860791-a8d9-49e2-af36-c3429ea56929', 'Chaos ist schön 🌪️', 'Bist du es leid, jeden Tag dieselben Spielsachen in die Kiste zu räumen? Dann lass es heute einfach sein! Ein unaufgeräumtes Zuhause ist kein Weltuntergang – dein seelisches Wohlbefinden ist wichtiger.'),
  ('a0432486-9631-45f3-ac61-64c5dc937b54', '10 Minuten nur für dich 🛀', 'Im Zimmer ist es still geworden. Bitte deinen Partner, zu Hause für eine Weile alles zu übernehmen. Gönn dir eine warme Dusche und verbringe 10 Minuten ganz allein mit dir selbst.'),
  ('fc396394-677d-4b99-a945-20af7aec5056', 'Kalzium steckt nicht nur in Milch 🧀', 'Dein Kind möchte keine Milch trinken? Kalzium ist für starke Knochen unverzichtbar. Berechne heute mit dem Ernährungstracker, wie viel Käse, Joghurt oder Brokkoli dein Kind gegessen hat, und gleiche mögliche Defizite aus.'),
  ('40c67b1f-86cb-4258-ae34-ac9f630e9bcd', 'Gemeinsam sind wir stark 💬', 'Bist du völlig erschöpft und hast das Gefühl, dass dich niemand versteht? Schreib gleich in der Anacan-Community. Dort unterstützen dich Tausende Mütter, die genauso unter Schlafmangel leiden.'),
  ('5fa2d1b1-040b-4c74-81f7-5aaa581e81fc', 'Trotz ohne Logik 🛑', 'Heute Morgen gab es einen riesigen Aufstand, weil du das Wasser im roten statt im blauen Becher serviert hast? Das ist keine Laune – dein Kind testet nur, ob es seine Welt selbst bestimmen kann. Bleib geduldig.'),
  ('6555b02b-e564-49b7-b5ae-a0b3594560b0', 'Eine Portion Vitamine 🥗', 'Du tust alles dafür, dass dein Kind satt wird. Aber was ist mit dir? Wähle aus den gesunden Rezepten ein eisen- und kalziumreiches Mittagessen, das in 10 Minuten zubereitet ist, und tanke neue Energie.'),
  ('74e20827-e129-489b-a3ba-b3145efc42b3', 'Vor dem Spiegel 👀', 'Steht dein Kind vor dem Spiegel, schneidet verschiedene Grimassen und lacht über sich selbst? Das ist ein tolles Zeichen für seine Selbstwahrnehmung. Beobachte es heimlich und genieße diese lustigen Momente.'),
  ('3e22553e-b182-4faa-9fc2-459fc9a92590', 'Trotzanfälle 🛑', 'Sind dir Wutanfälle im Geschäft oder im Park unangenehm? Denk daran: Nicht das, was andere denken, ist wichtig, sondern die Gefühle deines Kindes in diesem Moment. Stell Blickkontakt her und beruhige es.'),
  ('e37f9999-21b9-4b48-be42-d9cbbc3d9c55', 'Erste Sprungversuche 🤸‍♂️', 'Versucht dein Kind, vom Sofa auf den Boden oder aus dem Stand in die Luft zu springen? Seine grobmotorischen Fähigkeiten entwickeln sich immer weiter! Ermutige es dabei.'),
  ('ebbeae36-6d1a-428b-bb72-2ef8bd324080', 'Analysieren wir den Tagesrhythmus genau ⏱️', 'Hat das Einschlafen am Abend 40 Minuten gedauert? Sieh dir die Grafik im Schlaftimer an. Vielleicht ist es an der Zeit, den Mittagsschlaf deutlich zu verkürzen und die Schlafenszeit am Abend vorzuverlegen.'),
  ('1240eee6-bdc5-4609-ba23-b9d212dcb809', 'Die Natur entdecken ⛅', 'Die eigenen vier Wände fallen dir auf die Nerven. Öffne das Wetter- und Kleidungs-Tool, zieh dein Kind dem Wetter entsprechend an und geh gleich mit ihm in den Park. Lass es Blätter und Steine entdecken.'),
  ('1e908b82-2f19-4ebe-b79e-40246a88bab7', 'Genieß die Ruhe 🤫', 'Endlich ist dein Kind eingeschlafen. Jetzt geht dir selbst das kleinste Geräusch im Haus auf die Nerven. Setz deine Kopfhörer auf, ohne etwas abzuspielen, und genieß einfach die Stille.'),
  ('488aec04-c9ee-4eb7-9fb1-11c9a4093d08', 'Farben entdecken 🎨', 'Zeigt dein Kind tatsächlich auf den roten Ball, wenn du danach fragst? Es beginnt bereits, Farben zu unterscheiden. Trag diesen neuen Entwicklungsschritt in den Entwicklungstracker ein.'),
  ('3be3de73-5fca-4eff-b43e-5882d476d692', 'Die „Ich bin satt“-Ausrede 🥣', 'Isst dein Kind zwei Löffel, sagt, es sei satt, und läuft davon? Zwing es nicht zum Essen. Versuch, ihm kleinere Portionen, dafür aber häufiger anzubieten.'),
  ('9e9231eb-622b-4591-8fb2-b2c0bedcc252', 'Körperteile erkennen 👀', 'Berührt und zeigt dein Kind seine Schultern, wenn du fragst: „Wo sind deine Schultern?“ Seine geistige Entwicklung läuft auf Hochtouren! Setz das Spiel mit weniger bekannten Körperteilen fort.'),
  ('dfbc5f7d-d4f2-4480-8272-664e257700f7', 'Der Schlafanzug-Kampf 👕', 'Wird das Anziehen am Abend jedes Mal zum großen Kampf? Überlass deinem Kind die Wahl: Möchtest du den weißen oder den blauen Schlafanzug? Dieser Trick hilft oft.'),
  ('437d195c-2ce7-46eb-a38c-e5ab8476f991', 'Das Spielzeug gehört mir 🧸', 'Dein Kind möchte sein Spielzeug nicht mit einem Besucherkind teilen? Das ist kein Egoismus, sondern bedeutet, dass es seine persönlichen Grenzen schützt. Bring ihm das Teilen nicht durch Zwang, sondern durch dein Vorbild bei.'),
  ('49a7a4ab-0bbe-4e7b-ab8f-16aac2b2f875', 'Aussprache von Wörtern 🗣️', 'Spricht dein Kind manche Wörter nur teilweise oder besonders lustig aus? Lach es nicht aus, sondern wiederhole das Wort einfach mit der richtigen Aussprache und Betonung, damit sein Gehirn die korrekte Form abspeichert.'),
  ('d03e0dcf-56bb-436b-bb3e-19d3231b91eb', 'Verdacht auf Nachtschreck 😭', 'Weint dein Kind mitten in der Nacht mit geschlossenen Augen und lässt sich nicht beruhigen? Lass das Geräusch sofort von der Weinen-Analyse auswerten. Manchmal sind es nicht einfach nur Blähungen, sondern ein Nachtschreck.'),
  ('42301ed7-ed5e-4c5a-a79b-59b5256decae', 'Morgendliche Quengelei ☁️', 'Weint dein Kind gleich nach dem Aufwachen wegen jeder Kleinigkeit und ist mit nichts zufrieden? Vielleicht steckt es gerade mitten in einem Wachstumsschub. Schenk ihm einfach besonders viele Umarmungen und Geborgenheit.'),
  ('4611486b-3235-40ef-8f07-a9ac44bd4de8', 'Lass dein Kind schmutzig werden 🏖️', 'Möchte dein Kind im Park mit Matsch oder Sand spielen? Lass es ruhig schmutzig werden! Die besten mama-freundlichen Orte für diese Aktivität, die die sensorische Entwicklung fördert, findest du in der App.'),
  ('b8751eb5-8b11-4040-9350-f54539cfefa1', 'Teamgeist 🥂', 'Ihr habt einen schwierigen Tag gemeistert. Wenn euer Kind eingeschlafen ist, macht euch gemeinsam einen Tee und würdigt euch gegenseitig mit den Worten: Wir kriegen das wirklich hin.'),
  ('dc029c20-8f5d-4aa9-a173-be7d3be13a69', 'Wie fühlst du dich? 🩸', 'Ist deine Energie plötzlich im Keller oder schwankt deine Stimmung? Wirf einen Blick auf den Perioden-Tracker in der App. Wenn du deinen Zyklus verfolgst, kannst du verständnisvoller auf die Bedürfnisse deines Körpers eingehen.'),
  ('e1b2a066-88e9-4a4f-9df5-3af6a5d26b79', 'Kein Mittagsschlaf 🥱', 'Schon wieder nicht eingeschlafen? Kämpfe nicht dagegen an und erschöpfe weder dein Kind noch dich selbst. Auch gemeinsam in aller Ruhe ein Buch anzuschauen, ist eine Form der Erholung für das Gehirn.'),
  ('17487e3f-403d-4b65-ab45-c514d335d8cb', 'Gefühle festhalten 📝', 'Warst du heute wahnsinnig erschöpft oder hat dein Kind etwas besonders Süßes gesagt? Öffne in beiden Fällen das Stimmungstagebuch und halte diesen Moment als Erinnerung für die Zukunft fest.'),
  ('343623a3-2f2a-4afd-99aa-b377f0610f4c', 'Der Kampf ums Zähneputzen 🦷', 'Lässt dein Kind die Zahnbürste nicht an seinen Mund? Mach daraus keinen Zwang, sondern ein Spiel. Lass es zuerst deine Zähne putzen, danach bist du an der Reihe.'),
  ('7022b1d9-81c4-428f-be96-d38885bd2971', 'Freies Spielen 🧸', 'Du musst dein Kind nicht jede Minute beschäftigen. Langeweile ist für Kinder der Anfang von Kreativität. Lass es allein im Zimmer etwas entdecken.'),
  ('561010fd-17de-4698-b582-1c91bc73389a', 'Einfach nur kuscheln 🫂', 'Du brauchst weder Hilfsmittel noch Bücher oder Märchen. Nimm dein Kind heute Abend einfach fest an deine Brust, atme seinen Duft ein und flüstere ihm im Dunkeln zu, wie lieb du es hast.'),
  ('927b3990-20b2-4f48-94c1-3ea0663bfcd4', 'Ein klares Nein 🛑', 'Weicht dein Kind zurück und sagt Nein, wenn jemand es küssen möchte? Respektiere seine körperlichen Grenzen und bestehe darauf, dass auch andere sie achten. Hier beginnt Selbstvertrauen.'),
  ('f73f1d7d-92d7-412b-a0e4-c0f949786729', 'Entdecke die Blogbeiträge 📱', 'Du weißt nicht, wie du mit den Trotzanfällen deines 2-jährigen Kindes umgehen sollst? Lies die psychologischen Blogbeiträge in der Anacan-App. Wenn du verstehst, was während eines solchen Gefühlsausbruchs im Gehirn deines Kindes passiert, fällt dir der Umgang damit leichter.'),
  ('7281bfed-2cc1-421c-942f-77684085a8cf', 'Zeit für ein personalisiertes Märchen 🪄', 'Erstelle heute Abend in den personalisierten Märchen ein besonderes Abenteuer für dein Kind: die Geschichte vom mutigen Hasen, der keine Angst hatte. Hilf deinem Kind mit Märchen, seine Ängste zu überwinden.'),
  ('df6798e4-19ad-45ba-b5f8-d0bab8fc0951', 'Fantasiegeschichten 📖', 'Keine Lust mehr aufs Vorlesen? Schalte das Licht aus, wähle bei den Weißen Geräuschen Regengeräusche aus und erfindet gemeinsam im Dunkeln Fantasiegeschichten, bis ihr einschlaft.'),
  ('ebf1eb36-04dc-42ad-9b92-cfc852cf267d', 'Fruchtige Entdeckungen 🍏', 'Dein Baby lehnt Eiweiß oder Gemüse ab? Berechne mit dem Ernährungstracker den heutigen Bedarf und stelle mit den Babyrezepten leckere Kombinationen wie Fruchtjoghurt zusammen.'),
  ('14a13bdc-ca07-4dfa-9231-806da316a5bd', 'Zählen mit den Fingern 🔢', 'Versucht dein Kind beim Treppensteigen oder beim Aufstellen seiner Autos eins, zwei, drei zu sagen? Damit wird der Grundstein für mathematisches Denken gelegt. Zählt gemeinsam alles laut.'),
  ('8bf6a243-dbba-488e-976d-ab76ac22fdef', 'Tief durchatmen 🧘‍♀️', 'Nach einem ganzen Tag voller Antworten auf Fragen ist dein Hals ganz trocken. Sobald es im Zimmer ruhig wird, gönn dir eine Pause: Schau auf keinen Bildschirm und atme einfach ein paarmal tief ein und aus.'),
  ('c86b2cf3-2c86-4802-abd7-eac1fbe8e326', 'Warmer Tee und Stille 🍵', 'Der Timer ist abgelaufen, dein Kind schläft. Stürz dich jetzt nicht auf die Hausarbeit! Bereite nach unseren gesunden Rezepten einen Melissen- oder Kamillentee zu, mach es dir auf dem Sofa gemütlich und genieße einfach die Stille.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_de = v.t, body_de = v.b
FROM (VALUES
  ('37bdad79-de07-4752-a75a-2761546b1523'::uuid, 'Teilen ist schwer 🧸', 'Verhält sich dein Kind seinem Geschwisterchen oder einem anderen Kind im Park gegenüber grob? Teilen ist für dein Kind noch ein abstrakter Begriff. Bestrafe es nicht, sondern zeige ihm, dass du seine Gefühle verstehst.'),
  ('966fb5ae-0b22-47d8-b524-7d0d8e3e8e61', 'Eine Teestunde in der Fantasie 🍵', 'Bezieht dein Kind dich in seine Fantasiespiele ein und möchte, dass du aus einer leeren Tasse Tee trinkst? Werde Teil seiner Fantasiewelt. Solche Spiele fördern seine soziale Intelligenz.'),
  ('cab52685-d8da-4cce-a78e-b76068863ea1', 'Papas Geschichte 📖', 'Gönn deiner Stimme heute Abend eine Pause. Überlass es Papa, die Lieblingsbücher eures Kindes mit unterschiedlichen Stimmen und auf lustige Weise vorzulesen.'),
  ('e96ff0af-1a62-4cbe-8543-0ed5c9498c20', 'Chaos zu Hause 🌪️', 'Das Zimmer, das du jeden Tag aufräumst, sieht nach 5 Minuten wieder chaotisch aus? Mach dir nichts draus! Dein Zuhause ist kein Museum, sondern ein Ort voller Leben. Konzentriere dich nicht auf die Unordnung, sondern auf die Freude deines Kindes.'),
  ('fa5b66d9-39b4-43f8-b655-5b6b176b299f', 'Wenn Ängste erwachen 👻', 'Dein Kind hatte früher nie Angst vor dem lauten Staubsauger, versteckt sich jetzt aber hinter dir? Mit der Entwicklung der Fantasie können unbegründete Ängste entstehen. Streichele dein Kind und gib ihm Sicherheit.'),
  ('7b50e55a-c023-4d17-aacb-ffa1852fdee2', 'Müde Augen 🥱', 'Obwohl dein Kind müde ist, will es auf keinen Fall ins Bett. Gestalte die Abendroutine heute etwas anders. Statt ein Buch vorzulesen, legt euch ins Bett und erinnert euch gemeinsam an die schönen Erlebnisse des Tages.'),
  ('a4e24e0d-5f22-40d2-b64c-109e7cec356e', 'Ein Energieschub ⛅', 'Klettert dein Kind zu Hause schon die Wände hoch? Dann muss es seine Energie loswerden. Zieh es dem Wetter entsprechend an, geht in den Park und lass es herumtoben, bis es müde ist.'),
  ('a628c2a6-552d-4e1a-a37b-9ed947ed297d', 'Es ahmt deine Stimme nach 🗣️', 'Belehrt dein Kind seine Spielsachen mit genau deinem Tonfall und deinen Sätzen? Es ist dein bester Spiegel. Dich einmal von außen zu erleben, kann ziemlich lustig sein.'),
  ('a5f509e7-b242-4ca9-b7c5-aa083ba7699a', 'Wachstumsschub bei Größe und Gewicht! 📏', 'Ist dir beim Anziehen aufgefallen, dass die Oberteile enger geworden sind oder die Schuhe drücken? Trage die aktuelle Größe und die Maße in den Entwicklungs-Tracker ein und beobachte stolz, wie die Wachstumskurve ansteigt.'),
  ('a9ef3c95-4b55-4dd2-abe5-e4a54e6509df', 'Wenn Mama müde ist 🛑', 'Du bist kein Roboter. Wenn du heute keine Kraft zum Kochen hast, bestell einfach etwas zu essen. Eine perfekte Mama zu sein bedeutet nicht, alles allein machen zu müssen.'),
  ('ce9a0c9c-c1ca-4fbc-ad47-53a33a6c199f', 'Ein Toast auf euren Erfolg 🥂', 'Ihr habt einen schwierigen Tag voller Trotz gut überstanden. Setzt euch einander gegenüber und stoßt mit euren Teetassen an. Ihr meistert diese große Verantwortung.'),
  ('380a71ea-f755-4ca8-a25d-c156eefcd118', 'Beim Hinfallen nicht weinen 🧗‍♂️', 'Dein Kind fällt leicht hin, weint aber nicht sofort, sondern schaut erst auf deine Reaktion? Bleib ruhig, lächle und sag: „Alles gut, du bist stark.“'),
  ('77a38e1b-ddf2-4519-806e-48198f93ac3a', 'Angst vor der Dunkelheit?  🌙', 'Stell ein kleines Nachtlicht mit warmem Licht neben das Bett. Halte den restlichen Raum jedoch vollständig dunkel, damit Melatonin ausgeschüttet werden kann.'),
  ('b3b925ae-8f35-4c41-918e-ce24c80daa1b', 'Gemüse als Erzfeind 🥦', 'Dein Kind sortiert jedes Stück Gemüse aus der Suppe aus? Suche im Ernährungsplan nach anderen Alternativen. Gemüse in Frikadellen zu verstecken, ist einer der ältesten Mama-Tricks.'),
  ('16c277b4-79fe-460a-b9a5-72a7e8683280', 'Die perfekte Mama gibt es nicht 💬', 'Du fühlst dich schlecht, weil du nicht alles gleichzeitig schaffst? Schau gleich in der Anacan-Community vorbei. Die ehrlichen Geständnisse der Mamas dort werden dir Kraft geben.'),
  ('2e1e3e82-a2d5-4c25-a5ab-d3b0a7f4df86', 'Lust aufs Kritzeln 🖍️', 'Dein Kind hält den Stift jetzt anders und zeichnet gezielt Linien auf das Papier. Markiere diesen großartigen Fortschritt der Feinmotorik unbedingt im Entwicklungstracker.'),
  ('72b641f0-637f-48cd-8a37-fcd8fc3414bf', 'Kaffee-Energieschub ☕', 'Der Trubel des Tages hat dich erschöpft. Beschäftige dein Kind 15 Minuten lang mit einer sicheren Aktivität (zum Beispiel Ausmalen) und gönn dir unbedingt deinen Kaffee-Energieschub.'),
  ('35817a20-39d6-4243-8610-08e856df9e52', 'Treffsichere Würfe ⚾', 'Versucht dein Kind schon, den großen Ball, den du ihm zuwirfst, mit den Armen zu fangen und sogar zurückzuwerfen? Die Hand-Auge-Koordination entwickelt sich schnell. Spielt gemeinsam im Flur Ball.'),
  ('801c2145-44f5-4f5c-b680-cdaa0cf58a86', 'Musikalischer Übergang 🛀', 'Ist die Abendroutine schwieriger geworden? Lass während eines warmen Bades im Hintergrund beruhigende klassische Musik laufen. Die Harmonie von Wasser und Musik bringt selbst das hartnäckigste Kind zur Ruhe.'),
  ('7cad0a21-48df-4f84-89c3-bca4ef4e2b8a', 'Glaubst du, dass dein Kind zu wenig Wasser trinkt?💧', 'Mach das Wassertrinken zu einer spielerischen Gewohnheit, indem du ihm bunte Becher in verschiedenen Formen kaufst.'),
  ('d2d72f62-94bd-4b00-9bc2-090ee3d937fa', 'Flüstergespräche 🌙', 'Schalte das Licht im Zimmer vollständig aus. Lege dich neben dein Kind und erzähle ihm ganz leise und flüsternd, was im Laufe des Tages passiert ist. Flüstern ist eine der besten Methoden, um das Gehirn auf den Schlaf vorzubereiten.'),
  ('df67b2d6-67a7-45d0-8784-314cb9888630', 'Freie Kleiderwahl 👗', 'Dein Kind möchte seine Kleidung selbst aussuchen, aber die Farben passen überhaupt nicht zusammen? Das macht nichts. Damit du seinen Willen nicht brichst, biete ihm einfach zwei Möglichkeiten an: Möchtest du das oder das andere?'),
  ('308209fb-08e0-4807-8fb4-5bc201b75466', 'Papas lustige Geräusche 🤡', 'Am schnellsten bringt Papa das Baby mit lustigen Geräuschen und Grimassen zum Lachen. Hör heute Abend seinem fröhlichen Lachen zu und lächle im Hintergrund mit.'),
  ('591ee14c-695d-499c-8f9b-1192b3fd9c23', 'Zeit zum Austauschen 💬', 'Heute hat dein Kind wegen allem geweint und du bist völlig erschöpft. Geh gleich in die Anacan-Community und schreibe: Heute war es sehr schwer. Du wirst sehen, dass Hunderte Frauen gerade dasselbe erleben.'),
  ('7b870bcd-23ba-4647-a5da-35a4bde7db6f', 'Kleiner Baumeister 🧱', 'Versucht dein Kind, große Lego-Steine zusammenzustecken und etwas daraus zu bauen? Es entdeckt gerade die Geometrie. Füge diese kleinen Bauversuche seinem Entwicklungstracker hinzu.'),
  ('3cc5c04e-9600-46b6-86d4-dfe7f6d1b82d', 'Wörter nachsprechen 🗣️', 'Spricht dein Kind jedes neue Wort, das es von dir hört, sofort wie ein Papagei nach? Sein Wortschatz wächst. Achte besonders darauf, welche Wörter du in seiner Nähe verwendest und welche Gefühle du dabei vermittelst.'),
  ('b4771ddf-ae8c-44a0-b4dd-2f61938d3c93', 'Melodie des Abends 🛀', 'Nach einem ganzen Tag voller Herumtoben seid ihr beide erschöpft. Ein warmes Bad und eine sanfte, ruhige Melodie im Hintergrund helfen seinem Nervensystem, vollständig zur Ruhe zu kommen.'),
  ('805c93f2-e2d3-43ec-9e6f-4782049680cd', 'Ein dunkles Zimmer 🌙', 'Damit dein Kind schneller einschläft, schalte alle zusätzlichen Lichtquellen im Zimmer aus – insbesondere die Bildschirme von Tablets. Melatonin wird nur bei Dunkelheit ausgeschüttet.'),
  ('ba544f24-4325-4cce-9fad-539f5e144287', 'Streit ums Essen 🥣', 'Dein Kind isst zwei Löffel und sagt, es sei satt? Zwinge es nicht weiterzuessen. Ein gesundes Verhältnis zum Essen ist wichtiger, als es zum Essen zu drängen. Biete häufiger kleinere Portionen an.'),
  ('0b8f75a4-5ddd-4527-a07d-f3a8b79df578', 'Freude am Klatschen 👏', 'Klatscht dein Kind stolz für sich selbst, wenn ihm etwas gelingt, zum Beispiel wenn es einen Turm baut? Es wünscht sich Bestätigung! Feiere auch du diesen kleinen Erfolg mit großer Begeisterung.'),
  ('2ac10424-b1ee-4b11-b087-e5d8e74e2722', 'Eine Stunde Ruhe ☕', 'Wenn dein Kind keinen Mittagsschlaf mehr macht, führe eine mindestens 1-stündige Ruhezeit (Quiet Time) ein. Es kann in seinem Bett Bücher anschauen, während du deinen Tee trinkst und auf dein Handy schaust.'),
  ('2eea19a8-6377-4aff-9f02-8b899ec1a730', 'Zeit für euch als Paar 🥂', 'Das Kind schläft. Lege jetzt das Handy und die Hausarbeit beiseite. Sprich mindestens 20 Minuten mit deinem Partner oder deiner Partnerin über etwas anderes als euer Kind. Ihr seid schließlich auch ein Paar.'),
  ('2102feb2-22f3-4c41-8de6-6f3e115e2d56', 'Das Ende der Geschichte 🪄', 'Klassische Märchen können ermüdend sein. Lass dein Kind diesmal selbst entscheiden, wie die Geschichte endet. Frage zum Beispiel: „Wer hat dem kleinen Bären wohl geholfen?“ So regst du seine Fantasie an.'),
  ('8df55e5c-cbbb-49b9-bd1a-b655d228f1d5', 'Grenzen austesten ⚠️', 'Du sagst, dass dein Kind etwas nicht tun soll, und es tut es trotzdem, während es dir direkt in die Augen schaut? Es will dich nicht wütend machen, sondern testet, wie verlässlich deine Grenzen sind. Bleib konsequent.'),
  ('aa89536f-3d4b-4a1e-9088-0384b755894e', 'Reaktion auf Bilder 📖', 'Berührt dein Kind Tiere oder Kinder in einem Buch und macht dabei Laute? Seine visuelle Wahrnehmung ist beeindruckend. Halte dieses Detail im Entwicklungstracker fest.'),
  ('0f4c51cd-27d9-4064-9aec-69b37d8e0a6f', 'Morgentanz 🎶', 'Ist dein Kind gleich nach dem Aufwachen voller Energie? Spiel ein fröhliches Kinderlied, um das morgendliche Chaos zu entschärfen, und tanzt ein paar Minuten durchs Zimmer – so startet ihr mit einem Lächeln in den Tag.'),
  ('3f35178a-8193-420a-abc5-0ec312dd4ef0', 'Einkaufsliste 🛒', 'Sind Windeln, Shampoo oder Fruchtpüree aufgebraucht? Du musst dir nicht alles merken: Schreib es sofort auf die Einkaufsliste und synchronisiere sie mit nur einem Klick mit deinem Partner.'),
  ('4ec6bcf9-c49a-4e82-9a6f-0ae618212221', 'Tiefe Stille 🤫', 'Die erste halbe Stunde nach dem Einschlafen ist die empfindlichste Phase. Prüfe mit dem Schallpegelmesser die Lautstärke im Raum, drehe den Fernseher leiser und genieße die tiefe Stille, die sich im Haus ausbreitet.'),
  ('79665648-b787-4a1e-b120-da8384605658', 'Das Geheimnis der Eisenaufnahme: Vitamin C 🍋', 'Ist dein Kind blass oder hat es wenig Appetit? Prüfe in der Ernährungserfassung die heutige Eisenzufuhr und serviere zum Fleisch einen Salat mit reichlich Zitronensaft, um die Eisenaufnahme zu verbessern.'),
  ('a55553fe-9a49-45fa-b5bb-ccf86cdd6fc8', 'Nächtliches Aufwachen 🌌', 'Wacht dein Kind mitten in der Nacht weinend auf und lässt sich nicht beruhigen? Schau im Bereich „Blogs“ nach, um den Unterschied zwischen Nachtschreck und Albtraum zu verstehen und richtig darauf zu reagieren.'),
  ('f582b213-b9d3-463a-9b65-bba1181ecabf', 'Die Kunst, Kreise zu malen! 🎨', 'Versucht dein Kind, mit einem Stift geschlossene Kreise auf Papier (oder an die Wand!) zu malen? Das ist ein großartiger Entwicklungsschritt der Feinmotorik.'),
  ('41c18ba7-5f94-4cf4-bbb5-a65eaf5e3cf9', 'Grüner Detox 🌿', 'Fühlst du dich aufgebläht? Überprüfe deinen Zyklus im Perioden-Tracker und bring mit einem grünen Smoothie aus den gesunden Rezepten für Frauen deinen Körper wieder in Schwung und tanke neue Energie.'),
  ('99409d74-b463-47c8-b5a8-30d9e195253d', 'Flüssigkeitszufuhr und Verstopfung 💩', 'Ist dein Kind ständig in Bewegung, trinkt aber wenig Wasser? Achte beim Windelwechseln (oder auf dem Töpfchen) auf den Stuhlgang. Besteht Verstopfungsgefahr, ergänze den Speiseplan um Haferflocken.'),
  ('493d7552-4aa4-42f1-ab76-65529b782f6d', 'Kleiner Baumeister 🏗️', 'Liebt dein Kind es, Türme zu bauen und wieder umzuwerfen? Entdecke jetzt unter den Produktempfehlungen magnetische Bausteine oder Holzklötze, die seine kognitiven und motorischen Fähigkeiten zusätzlich fördern.'),
  ('96969038-76a5-48c3-b60c-aafe8839c46c', 'Atme tief durch 🌬️', 'Bist du heute völlig erschöpft davon, deinem Kind hinterherzulaufen? Öffne das Stimmungstagebuch und schreibe auf, wie müde du bist. Versuche nicht, eine perfekte Mutter zu sein – auch deine Gefühle sind wichtig!'),
  ('3cbc904d-0d48-46fa-a264-4d48559d6b46', 'War es ein schwieriger Tag?', 'Schreib den Stress von heute in dein Stimmungstagebuch und lass alles raus. Alle Mütter erleben solche Krisen – du bist nicht allein.'),
  ('aabf621d-766b-4fe7-b19d-2316986fdc64', 'Ein Festmahl für Mama 🥑', 'Du tust alles, damit dein Kind satt wird. Aber was ist mit dir? Wähle aus den gesunden Rezepten ein eisenreiches Mittagessen, das dir Kraft gibt, und nimm dir die Zeit, es in Ruhe zu genießen.'),
  ('c60bf17d-5d16-4967-881d-d808bb5c5b6e', 'Sätze aus zwei Wörtern 🗣️', '„Mama, komm“, „Wirf den Ball“ – der Wortschatz deines Kindes wächst von Tag zu Tag. Unterstütze seine Sprachentwicklung, indem du unvollständig ausgesprochene Wörter mit der richtigen Aussprache wiederholst.'),
  ('274e44c7-f2f2-4e14-a2db-692e3ab50d92', 'Wutanfälle im Supermarkt 🛒', 'Hat sich dein Kind auf den Boden geworfen, weil du ihm im Laden nicht gekauft hast, was es wollte? Lass dich von den Blicken der anderen nicht verunsichern. Geh auf Augenhöhe und sag ihm, dass du seine Gefühle verstehst.'),
  ('7ffa24e8-d5c5-47fa-bd56-46791566e3ed', 'Verkehrt herum angezogene Kleidung 👗', 'Zieht dein Kind seine Schuhe an den falschen Fuß oder sein T-Shirt verkehrt herum an und will es auf keinen Fall ausziehen? Lass es einfach so! Das ist eine ganz harmlose Art, seine Individualität auszudrücken.'),
  ('90cdd9aa-f5c9-402b-8ee4-af9073e319ae', 'Entspannung mit Musik 🎶', 'Die einfachste Möglichkeit, das Quengeln am späten Nachmittag zu beruhigen, ist, die Lieblingsmelodie deines Kindes anzumachen, es in den Arm zu nehmen und langsam mit ihm zu tanzen.'),
  ('c19b60f5-cbba-4300-8903-9c5cb8625ba7', 'Sei stolz auf dich 🌟', 'Jede neue Fähigkeit, die dein Kind täglich erlernt, und jeder selbstbewusste Schritt sind das Ergebnis deiner und der Bemühungen deines Partners.'),
  ('e47a41a7-8601-4ce3-8c27-0c69ab445dad', 'Unabhängigkeitserklärung 📜', 'Sagt dein Kind bei allem „Ich mache das selbst!“ und hält dadurch alles auf? Frag Anacan AI gleich, wie du diese grenzenlose Hartnäckigkeit in einen Entwicklungsschritt verwandeln kannst.'),
  ('e4b29fb1-70d1-4a56-b112-96966513c6eb', 'Details in Büchern 📖', 'Blättert dein Kind im Buch und zeigt selbst auf das kleinste Detail im Bild? Sein visuelles Gedächtnis funktioniert hervorragend. Sprich mit ihm über das, was auf den Bildern zu sehen ist.'),
  ('14b9dba6-d0f2-4f3d-a4e8-f737b507b018', 'Kleiner Kritzelkünstler 🖍️', 'Sobald dein Kind einen Stift in die Hand bekommt, kritzelt es auf Wände oder Papier. Beim Malen mit Farben entwickelt sich seine Feinmotorik.'),
  ('48cc1013-ae1c-4b86-9e80-78bd05d5745a', 'Nächtliche Ruhe 🛀', 'Ein warmes Bad, eine sanfte Massage und ein dunkles Zimmer. Halte die Schlafroutine unbedingt ein, denn sie signalisiert seinem Gehirn, dass jetzt die beste Zeit zum Schlafen ist.'),
  ('a8d24ffb-d035-4c11-983e-8c2c2a9ad274', 'Mamas tauschen sich aus 💬', 'Macht dich der Gedanke „Warum ist mein Kind nur so stur?“ müde? Tritt der Anacan-Community bei – dort wirst du sehen, dass jedes Kind unterschiedliche Trotzphasen durchlebt.'),
  ('5ae62f81-7331-472c-9b48-c967d0615a5b', 'Der Held des Abends: Papa 🦸‍♂️', 'Überlass die Schlafroutine heute Abend über die Partner-Funktion deinem Partner. Er liest die Gute-Nacht-Geschichte vor, während du dir ein warmes Bad einlässt und den Stress des Tages hinter dir lässt.'),
  ('88d95f7d-2e98-41b0-8554-4115adfb31c5', 'Wählerisches Essverhalten 🥦', 'Lehnt dein Kind heute ein Gericht ab, das es gestern noch mit Appetit gegessen hat? Analysiere den Speiseplan mit dem Ernährungstracker und entdecke in den Babyrezepten abwechslungsreiche, spielerische Ideen zum Anrichten.'),
  ('fb38f47e-3f88-41bf-87e7-fb7f9b1c8e65', 'Krisenmoment 🛒', 'Dein Kind schreit, weil du ihm im Supermarkt das gewünschte Spielzeug nicht gekauft hast. Lass dich von den Blicken der vermeintlich perfekten Eltern um dich herum nicht verunsichern. Stelle ruhig Blickkontakt her und erkläre ihm die Situation.'),
  ('3a862b3f-38a2-4cda-8a77-17c531d3e5f5', 'Der Haushalt kann warten 🛑', 'Der Boden ist nicht gewischt und die Wäsche nicht zusammengelegt? Lass es liegen. Ein schmutziges Zuhause lässt sich wieder in Ordnung bringen, doch die Erholung einer psychisch erschöpften Mutter dauert viel länger. Leg dich aufs Sofa.'),
  ('52c32776-811a-4d66-a0c4-6b1c34cdfc69', 'Akzeptiere den Schlafmangel 😭', 'Dein Kind ist mitten in der Nacht aufgewacht und will nicht mehr schlafen. Werde nicht wütend auf es. Lass das Weinen von der Weinanalyse auswerten, um den Grund (Schmerzen, Blähungen, Angst) herauszufinden, und nimm dein Kind geduldig in den Arm.'),
  ('bc7db5e2-0eb7-4adc-85cd-1181aac8b268', 'Auf der Suche nach neuen Freunden 👫', 'Versucht dein Kind im Park, mit Gleichaltrigen herumzulaufen und auf sie zuzugehen? Das Knüpfen sozialer Kontakte ist offiziell in vollem Gange! Beobachte diesen Moment stolz aus der Distanz und behalte dein Kind dabei gut im Auge.'),
  ('100554ba-e336-4148-9dd0-9a0ceeecb04b', 'Lerne aus den Blogbeiträgen 📱', 'Bist du es leid, dass dein Kind zu allem Nein sagt? Das ist ein klassisches Anzeichen der Trotzphase mit 2 Jahren. Lies die psychologischen Blogbeiträge in der App, um zu verstehen, was in seinem Kopf vor sich geht.'),
  ('19cce24b-ae51-482e-8dc7-6812a220483b', 'Mach dir keine Vorwürfe 📝', 'Heute ist dir die Geduld ausgegangen und du bist laut geworden? Wenn dein Kind schläft, schreib deine Gefühle in dein Stimmungstagebuch und verzeih dir selbst. Du bist einfach nur müde. Du bist ein Mensch.'),
  ('1bc0b4db-b3a8-4a70-bfa5-eaa18f5fe1f5', 'Selbstständig Treppen steigen 🧗‍♂️', 'Will dein Kind an deiner Hand die Treppe hinaufsteigen oder es sogar ganz allein versuchen? Es testet die Grenzen seines Körpers aus. Gib ihm unbedingt diese Freiheit und sichere es dabei gut ab.'),
  ('380af2db-ede8-491b-ab1a-6f695da10f42', 'Trennungsangst 🥺', 'Selbst wenn du nur zur Toilette gehst, wartet dein Kind weinend hinter der Tür auf dich. Trennungsangst kann sich zeitweise verstärken. Melde dich jedes Mal bei ihm und sag ihm, dass du da bist und wiederkommst.'),
  ('ee2ef852-cac1-4c22-a029-d59cd40dbe5f', 'Monsterjagd! 👾', 'Sucht dein Kind unter dem Bett nach Monstern? Ängste, die durch die Fantasie entstehen, nehmen jetzt zu. Spiele unter den Weißen Geräuschen das Ventilatorgeräusch ab, um im Zimmer eine beruhigende, gleichmäßige und sichere Atmosphäre zu schaffen.'),
  ('3389c70e-b510-475b-87c1-4f01743277cd', 'Fluchtplan aus dem Bett 🛌', 'Versucht dein Kind, aus seinem Gitterbett zu klettern? Dann rückt der Wechsel in ein Kinderbett näher. Überprüfe die Sicherheit des Zimmers noch einmal aus der Perspektive deines Kindes – auf Bodenhöhe.'),
  ('92afc025-d2fe-4c60-9ebd-9366e19b0175', 'Eine Pause für Mama ☕', 'Wenn dein Kind allein spielt, musst du nicht sofort die Hausarbeit erledigen. Das Chaos im Zimmer läuft nicht weg, aber deine Energie kann zur Neige gehen. Setz dich hin und genieße deinen heißen Kaffee.'),
  ('c522fcae-04de-4086-b6e1-764904ead448', 'Die „Warum?“-Phase auf ihrem Höhepunkt 🤔', '„Warum ist das dort?“, „Warum schlafe ich?“ ... Das Gehirn deines Kindes ist wie ein Schwamm! Beantworte seine endlosen Fragen kurz, aber logisch. Es entdeckt die Welt mithilfe deiner Worte.'),
  ('3a442f56-c411-4f3c-a16a-32453afe5f33', 'Begegnungen im Park 🌳', 'Spielt dein Kind eher neben anderen Kindern als mit ihnen? Paralleles Spielen ist in diesem Alter völlig normal. Achte auf das Wetter und passende Kleidung und gib ihm regelmäßig Gelegenheit, Zeit mit Gleichaltrigen zu verbringen.'),
  ('5d66b2e6-45ec-4c26-ae59-9d0d0eba4b4d', 'Fantasiefreunde 🧸', 'Erzählt dein Kind seinem Teddybären Geschichten oder trinkt es Tee aus einer leeren Tasse? Symbolisches Spielen ist ein wichtiger Meilenstein der Entwicklung. Halte diesen kognitiven Entwicklungssprung stolz im Entwicklungs-Tracker fest.'),
  ('d4544a8c-8615-4a88-b7e6-c7dc2d3b805a', 'Bedürfnis nach Ruhe 🤫', 'Die erste halbe Stunde nach dem Einschlafen ist die empfindlichste Zeit. Prüfe mit dem Schallpegelmesser die Lautstärke im Zimmer und passe die Lautstärke des Fernsehers im Nebenraum entsprechend an.'),
  ('32813c49-da9b-4dca-8d61-b20de94b9fae', 'Will dein Kind alles für sich haben? 🛑', 'Das Verständnis fürs Teilen hat sich noch nicht vollständig entwickelt. Dränge dein Kind nicht dazu, sondern führe stattdessen nach und nach die Regel „Wir wechseln uns beim Spielen ab“ ein.'),
  ('b1d18fda-3875-4aca-b436-4ecb52ef49a6', 'Schmerzfreie Tage 🩸', 'Deine Periode steht bevor und die Krämpfe haben schon begonnen? Bevor du zu Medikamenten greifst, tu dir etwas Gutes und bereite aus den gesunden Rezepten für Frauen einen magnesiumreichen Dattel-Walnuss-Snack zu.'),
  ('55fa43db-2800-421e-b0f2-748c40c7ef07', 'Die Kleidung wird zu klein! 📏', 'Sind die Ärmel schon wieder zu kurz? Trage die aktuellen Maße in den Gewichtstracker ein und sieh dir die ansteigende Kurve an, um den Wachstumsschub um den 29. Monat genau zu verfolgen.'),
  ('8a1a47bc-2d1d-4804-abb1-5b5294f326db', 'Kleine Leseratte 📖', 'Möchte dein Kind, dass du dieselbe Geschichte zum 100. Mal vorliest? Lies in den Blogbeiträgen, welche erstaunliche Rolle diese scheinbar anstrengende Wiederholung für die geistige Entwicklung spielt, und tanke neue Geduld.'),
  ('c88c6893-fe11-4ce0-bf2d-ed7f94e0770d', 'Erste logische Schlussfolgerungen 🤔', 'Bildet dein Kind Sätze nach dem Muster „Wenn ich das mache, passiert das“? Halte diesen wunderbaren kognitiven Entwicklungssprung als Video mit Ton fest, füge es dem Babyalbum hinzu und sei stolz.'),
  ('3469bb77-d2d2-406c-8c90-287cb3502fb6', 'Teambesprechung 🥂', 'Wenn euer Kind eingeschlafen ist, kocht euch gemeinsam einen Tee, lasst den Stress des Tages hinter euch und zeigt einander mit den Worten „Wir sind ein großartiges Team“, wie sehr ihr euch schätzt.'),
  ('69a15994-f6a2-4e74-92d0-633dfea33b45', 'Ein neuer Lieblingsort für Mama ☕', 'Du kannst die immer gleichen vier Wände zu Hause nicht mehr sehen? Entdecke unter den kinderfreundlichen Orten ein Café mit Spielecke. Dein Kind spielt, während du deinen Kaffee genießt.'),
  ('71af31e1-67cd-4bc6-a54d-505d0d3ed0af', 'Tierlaute 🐶', 'Versucht dein Kind beim Anblick einer Katze „Miau“ und bei einem Hund „Wauwau“ zu sagen? Tierlaute fördern den Wortschatz auf spielerische Weise. Spielt dieses Spiel gemeinsam.'),
  ('1fe665ee-e68e-4e2a-b81e-f697b1100d0d', 'Schneller Kinderarzt 🤖', 'Wie groß sollten die Portionen sein, wenn dein Kind sich dem Alter von 2.5 Jahren nähert? Wenn du unsicher bist, bitte Anacan AI direkt um eine genaue, wissenschaftlich fundierte Übersicht.'),
  ('8139ee6f-daa0-4072-ad02-2be67ee8488d', 'Der Held des Märchens 🪄', 'Erstelle heute Abend bei den schlauen Märchen eine besondere Geschichte, in der dein Kind die Hauptrolle spielt: ein mutiges Kleines, das gerne seine Zähne putzt.'),
  ('9d6f4449-54d1-4585-9f63-6d19afec1bda', 'Eine Ich-hab-dich-lieb-Umarmung 🫂', 'Kommt dein Kind plötzlich zu dir, fällt dir um den Hals oder streichelt dein Gesicht? Es zeigt seine Liebe jetzt auch durch körperliche Nähe. Genieße das unvergleichliche Gefühl der Geborgenheit, das dieser Moment schenkt.'),
  ('c32b736c-41b6-4e37-ad3d-7f15cea8084a', 'Protest gegen den Mittagsschlaf 🥱', 'Dein Kind möchte keinen Mittagsschlaf machen und weint? Kämpfe nicht dagegen an. Führe stattdessen eine 30-minütige Ruhezeit ein, in der es still im Zimmer Bücher anschauen kann.'),
  ('c762e9b7-a5b4-4810-a642-39d1f9c28936', 'Schichtwechsel 👨‍👧', 'Nach einem ganzen Tag voller Warum?-Fragen ist dein Kopf erschöpft. Überlasse heute Abend deinem Partner oder deiner Partnerin das Anziehen des Schlafanzugs und das Zubettbringen – und ruh dich aus.'),
  ('dc54ef63-6d88-4c2f-9c5d-c431db5caf8b', 'Ausgefallene Mode 👗', 'Dein Kind möchte mitten im Winter Sommershorts tragen oder sich die Hose über den Kopf ziehen? Misch dich nicht in seinen Geschmack ein. Mit diesen lustigen Experimenten bringt es seine Individualität zum Ausdruck.'),
  ('37bfacdd-d6ce-4a16-96d7-85b70834ca41', 'Entdeckungsreise auf dem Teller 🥦', 'Wirft dein Kind heute das Essen auf den Boden, das es gestern noch geliebt hat? Öffne das Ernährungsplan-Tool und entdecke abwechslungsreiche, farbenfrohe Menüideen, die von Fachleuten für 2.5-Jährige zusammengestellt wurden.'),
  ('6b5d8f34-e3e9-4e8b-8382-9b0f64e3f018', 'Unerwartete Ängste 👻', 'Hat dein Kind plötzlich Angst vor der Dunkelheit im Zimmer oder vor eingebildeten Schatten? Mit der zunehmenden Vorstellungskraft können unbegründete Ängste entstehen. Gib ihm Sicherheit und lass es spüren, dass du bei ihm bist.'),
  ('b459387d-d414-446b-ac06-391ffb5af36c', 'Unerschöpfliche Batterie 🔋', 'Du hast deine Augen noch nicht richtig geöffnet, aber dein Kind läuft schon einen Marathon über den Teppich. Schenk dir eine große Tasse Kaffee ein – heute wird es sehr turbulent.'),
  ('fc8def68-9f4f-421f-a543-941a3d40a533', 'Neue Wörter 🧠', 'Hat dein Kind heute einen ungewöhnlichen, komplexen Satz wie ein Erwachsener gebildet? Öffne gleich den Entwicklungstracker und halte diesen kognitiven Sprung als Erinnerung fest, damit du später darauf zurückblicken kannst.'),
  ('115c548f-9326-4a38-a159-3195407d360e', 'Auszeit als Paar 🥂', 'Das Kind schläft. Lass jetzt den Haushalt liegen. Sprich mindestens 20 Minuten mit deinem Partner über irgendetwas anderes als euer Kind. Ihr seid schließlich auch ein Paar.'),
  ('91f7fb7e-2bab-481e-816b-6e91267f93ae', 'Gezieltes Krabbeln 🐢', 'Kann dein Kind schon laufen, krabbelt aber manchmal zum Spaß schnell davon? Räume gefährliche Hindernisse im Zimmer weg und mach bei diesem Fangspiel mit.'),
  ('ca59c65d-2643-4f9a-b7e1-efbf69908275', 'Offline-Zeit für Mama ☕', 'Wenn dein Kind ganz in sein Spiel vertieft ist, lauf nicht gleich zum Geschirrspüler. Mach dir einen heißen Tee, leg das Handy beiseite und gönn dir 15 Minuten offline, ohne an irgendetwas zu denken.'),
  ('53f1873b-90e8-4dcd-884c-7bbec73835df', 'Flüstergespräche 🌙', 'Schalte das Licht im Zimmer vollständig aus. Leg dich neben dein Kind und erzählt euch ganz leise und flüsternd, was ihr im Laufe des Tages erlebt habt. Flüstern ist eine besonders beruhigende Art, das Gehirn auf den Schlaf vorzubereiten.'),
  ('67fb000b-9452-4ae5-aa28-3a36f345f54a', 'Schmerzfreie Tage 🩸', 'Deine Periode steht bevor und du hast bereits Krämpfe? Bevor du gleich zu Medikamenten greifst, bereite dir aus den gesunden Rezepten einen magnesiumreichen Dattel-Walnuss-Snack zu und tu dir etwas Gutes.'),
  ('f0ddb044-981f-4758-9737-12aa24392d50', 'Zählen mit den Fingern 🔢', 'Versucht dein Kind beim Treppensteigen oder Aufstellen seiner Spielsachen eins, zwei, drei zu sagen? Das mathematische Denken erwacht. Zählt gemeinsam die Gegenstände im Zimmer laut ab.'),
  ('841fa22f-136a-48a1-b594-4a69eafbc030', 'Neue Energie tanken 🍲', 'Die ganze Hektik hat dich erschöpft. Statt im Stehen schnell etwas zu naschen, richte dir einen sättigenden, kalziumreichen Teller an und genieße ihn ganz in Ruhe.'),
  ('98be6947-c839-4cba-807a-2d0a7d2db4bd', 'Papas lustiges Gesicht 🤡', 'Der schnellste Weg, dein Baby zum Lachen zu bringen: Papa macht komische Geräusche und Grimassen. Lausche heute Abend dem fröhlichen Gelächter und lächle im Hintergrund einfach mit.'),
  ('9c1b9283-eb25-42f4-8927-c54192637c35', 'Mamas Morgenenergie ⚡', 'Bist du heute Morgen müde aufgewacht? Greif nicht gleich zu Zucker. Entdecke in den gesunden Rezepten einen eiweißreichen Haferbrei mit Obst, der in 5 Minuten zubereitet ist, und starte voller Energie in den Tag.'),
  ('1868bb46-a550-4249-8524-2b40ecd9cad3', 'Papas Unterstützung ist gefragt 🫂', 'Du bist laut Perioden-Tracker gerade in deiner PMS-Phase und besonders sensibel? Lass ihn über die Partnerfunktion wissen, dass du heute etwas mehr Unterstützung brauchst.'),
  ('5efae0dc-5ddd-4ac1-9526-ddfa449ec612', 'Eine Kissenburg 🏰', 'Verwandelt das Zimmer heute Abend in einen Spielplatz. Baut aus den Sofakissen eine kleine Burg und krabbelt hinein. Es wird zwar etwas chaotisch, aber das fröhliche Lachen ist es auf jeden Fall wert.'),
  ('e40e4ab0-cd42-4ed7-b968-edc0adab6461', 'Verhandeln wie ein Anwalt 🗣️', 'Sagt dein Kind: „Ich spiele noch ein bisschen und ziehe mich danach an“? Es versucht bereits, ganz professionell mit dir zu verhandeln. Seine Sprachentwicklung ist großartig – aber vergiss nicht, deine Grenzen liebevoll zu wahren.'),
  ('f9854a88-373e-4d4d-91e8-4e24a9ea9cba', 'Die Natur entdecken 🌳', 'Dir fällt zu Hause die Decke auf den Kopf. Auch wenn es draußen kühl ist: Zieh dein Kind warm an und geht für 20 Minuten in den Park. Lass es Blätter und Steine entdecken – die frische Luft wird euch beiden guttun.'),
  ('fb90f3c3-fde8-496d-b59b-6ba1236abd46', '„Ich hab dich gefunden!“ 🙈', 'Verstecken ist jetzt das absolute Lieblingsspiel. Dein Kind versteckt sich hinter dem Vorhang und wartet darauf, dass du es findest. Macht dieses Spiel zum lustigsten Teil eurer täglichen Routine.'),
  ('fce8d709-58cb-464d-bc50-7c2b9036555e', 'An die Dunkelheit gewöhnen 🌙', 'Schalte alle Bildschirme im Zimmer aus, damit dein Kind schneller einschläft. Das blaue Licht des Fernsehers verzögert die Ausschüttung des Schlafhormons.'),
  ('1dc3a9e4-8c1a-46c9-b53c-b30058a99bb3', 'Mutige Kletterversuche 🧗‍♂️', 'Hält sich dein Kind am Sofa oder Sessel fest und versucht, daran hochzuklettern? Sein Gleichgewichtssinn und seine Muskelkraft entwickeln sich weiter. Achte auf seine Sicherheit, aber halte es auf keinen Fall von diesen Kletterversuchen ab.'),
  ('a7098097-ad7b-4ef2-ac70-151dc53814b4', 'Keine Lust aufs Essen 🥣', 'Isst dein Kind zwei Löffel, sagt, es sei satt, und läuft davon? Zwinge es nicht zum Essen. Ein gesundes Verhältnis zum Essen zu entwickeln, ist wichtiger, als es zum Essen zu drängen.'),
  ('f8b30c93-8e49-4cb9-8db0-9b3082221d0d', 'Tagesrückblick 📝', 'Warst du heute völlig erschöpft oder hat dein Kind etwas besonders Süßes gesagt? Öffne in beiden Fällen dein Stimmungstagebuch, halte diesen Moment für später fest und schreib dir alles von der Seele.'),
  ('18e35d56-8285-420a-adac-121643743cd2', 'Aufmerksamkeitstest 🧩', 'Beschäftigt sich dein Kind inzwischen 10-15 Minuten lang mit einem Spielzeug, zum Beispiel einem Puzzle? Das zeigt, dass seine Aufmerksamkeitsspanne zunimmt. Stell dich leise in eine Ecke des Zimmers und beobachte es.'),
  ('87548d0a-d1fb-4a91-8d0e-f51d5f31d60e', 'Ursache und Wirkung entdecken 🤔', '„Was passiert, wenn ich das fallen lasse?“ „Wofür ist dieser Knopf da?“ Dein Kind führt ständig kleine physische Experimente durch. Überprüfe die Sicherheit eures Zuhauses noch einmal aus seiner Perspektive auf Bodenhöhe.'),
  ('f1a78ec7-6b62-43e2-8747-e4f8c033a5e7', 'Ohne Märchen geht es nicht ins Bett 🪄', 'Klassische Märchen wecken nicht mehr die Aufmerksamkeit deines Kindes? Erfinde eine besondere Geschichte, in der es selbst die Hauptrolle spielt, untermale sie mit Naturgeräuschen und tauche gemeinsam mit ihm in seine Fantasiewelt ein.'),
  ('becd06f2-3767-4d60-98af-e6ee50a40e21', 'Tanzen zur Musik 🎶', 'Beginnt dein Kind sofort, sich im Takt zu wiegen, sobald fröhliche Musik erklingt? Die Verbindung zwischen Gehör und Motorik entwickelt sich wunderbar! Mach ein fröhliches Lied an und tanzt gemeinsam durchs Zimmer.'),
  ('befcea5e-21fe-4c91-b025-35c7c94f17a1', 'Papas Vorlesezeit 📖', 'Schone heute Abend deine Stimme. Lass Papa die Lieblingsbücher eures Kindes mit verstellten Stimmen und auf lustige Weise vorlesen.'),
  ('5b291f89-d920-4ebd-a4e6-3d982c3f7c31', 'Auf den Spuren eines Künstlers 🖍️', 'Das Papier ist aufgebraucht – sind jetzt Wände und Türen dran? Beim Malen entwickelt dein Kind seine Feinmotorik. Breite im Zimmer einen großen Karton aus und erkläre ihm, dass es nur darauf malen darf.'),
  ('a9576738-56a5-42cd-a95f-6e85e5fb1189', 'Unlogischer Trotz 🛑', 'Es gab einen riesigen Aufstand, weil du das Wasser im roten statt im blauen Becher gereicht hast? Das ist keine Laune – dein Kind testet nur deine Grenzen und ob es seine Umwelt kontrollieren kann. Bleib geduldig.'),
  ('e5ef4a95-198d-48b4-a37a-8ba378115031', 'Die wohltuende Kraft des Wassers 🛀', 'Nach einem ganzen Tag voller Herumrennen seid ihr beide erschöpft. Ein warmes Bad dient nicht nur der Körperpflege, sondern ist auch eine der besten natürlichen Methoden, um das angespannte Nervensystem deines Kindes zu beruhigen.'),
  ('891847ab-5f43-4ba4-a99f-cf7faceb076c', 'Das Chaos akzeptieren 🌪️', 'Bist du es leid, jeden Tag dieselben Spielsachen aufzuräumen? Dann lass es heute einfach sein! Ein unordentliches Zuhause ist kein Weltuntergang – dein seelisches Wohlbefinden ist wichtiger als alles andere.'),
  ('9de03e77-6cb6-4585-9646-e7347bac18d6', 'Bring das schlechte Gewissen zum Schweigen 💬', 'Machst du dir Vorwürfe, weil dein Kind heute zu viel Zeit vor dem Bildschirm verbracht hat? Schau in der Anacan-Community vorbei und lies, dass es anderen Müttern manchmal genauso geht. Du bist nicht allein.'),
  ('f7d0d8f9-fd4d-4b19-b40e-907cdb2d4aea', 'Das eigene Ich im Spiegel 👀', 'Schneidet dein Kind vor dem Spiegel verschiedene Grimassen, spricht mit sich selbst und lacht dabei? Seine Selbstwahrnehmung entwickelt sich hervorragend. Beobachte es unbemerkt und genieße diese lustigen Momente voller Stolz.'),
  ('765fd3c5-2a1b-4659-aa42-b76314ae48dc', 'Egoismus auf dem Spielplatz 🧸', 'Will dein Kind beim Spielen im Sand seinen Eimer mit niemandem teilen? Das ist kein Egoismus, sondern das Wahrnehmen eigener Grenzen. Zwinge es nicht, sondern bringe ihm behutsam die Regel „Wir wechseln uns ab“ bei.'),
  ('8329858a-b5aa-4e88-a094-94baf4b4dff4', 'Fantasiespiele 🧸', 'Versucht dein Kind, seinem Teddybären oder seiner Puppe Wasser zu geben, und führt es Gespräche mit ihnen? Symbolisches Spielen ist ein wunderbarer Entwicklungsschritt. Beobachte diesen süßen kleinen Regisseur interessiert aus der Ferne.'),
  ('d245b047-0d4a-45c3-956c-817469ecd147', '„Warum?“ ist vorbei, „Wie?“ hat begonnen 🤔', 'Ein Sprung in Sachen Vorstellungskraft und logischem Denken! Jetzt fragt dein Kind auch, wie Dinge funktionieren. Erfahre von unserem Anacan AI-Experten, wie du diese Fragen altersgerecht und spannend beantworten kannst.'),
  ('0d9edca6-9e16-4f20-b482-5f21d8925331', 'Finde dich mit dem Schlafmangel ab 😭', 'Dein Kind wacht mitten in der Nacht auf und möchte nicht mehr schlafen. Werde nicht wütend. Finde heraus, was dahintersteckt – Schmerzen, Blähungen oder Angst – und vermittle ihm geduldig mit einer Umarmung Geborgenheit.'),
  ('6fbdbe3b-91f8-4e0a-9823-628cb1856a3a', 'Hartnäckige Flecken 👗', 'Bist du es leid, dass die Kleidung ständig Flecken bekommt? Ärgere dich nicht darüber. Dein Kind entdeckt gerade Lebensmittel. Verwende Silikonlätzchen und genieße diese bunten, chaotischen Momente.'),
  ('9f08baf7-46d6-4ac6-b651-94901e800f6b', 'Ich helfe dir! 🧹', 'Versucht dein Kind, dir den Wischmopp oder Staubwedel aus der Hand zu nehmen, wenn du putzt? Es fühlt sich schon ganz groß. Gib ihm ein kleines Tuch und lass es Teil deines Teams sein.'),
  ('40197a85-31e6-4141-9d38-df9b89843274', 'Hör auf deinen Körper 🩸', 'Plötzlicher Heißhunger auf Süßes oder Müdigkeit? Schau in den Kalender des Perioden-Trackers. Wenn deine Periode bevorsteht, wähle unter den gesunden Rezepten einen magnesiumreichen Snack aus.'),
  ('4ca62724-362e-47af-b9dc-e138d57c7cbd', 'Schatten im Zimmer 🌌', 'Hat dein Kind Angst vor der Dunkelheit und eingebildeten Monstern? Verdunkle das Zimmer nicht vollständig und spiele unter den Weißen Geräuschen Mutterleibgeräusche ab, um ihm das vertraute Gefühl vollkommener Geborgenheit zu schenken.'),
  ('f8e208a6-e2c2-4a88-b04c-adaeb10974b8', 'Trennungsangst 🥺', 'Weint dein Kind dir hinterher, sobald du das Zimmer verlässt – selbst wenn du nur zur Toilette gehst? Es glaubt, dass du nicht zurückkommst. Gib ihm Sicherheit, indem du immer wieder sagst: „Ich bin hier. Hörst du meine Stimme?“'),
  ('216f95a1-f03e-48c4-8e9d-615f08aa0853', 'Kleine Plaudertasche 🗣️', 'Verbindet dein Kind schon 4-5 Wörter und erzählt lustige Geschichten? Sein Wortschatz wächst jetzt explosionsartig! Lass dir diesen kostbaren Moment nicht entgehen.'),
  ('91db0bda-d980-4153-bb7d-0ed55ffcd626', 'Tief durchatmen 🧘‍♀️', 'Vom vielen Beantworten der Fragen ist dein Hals schon ganz trocken. Sobald es im Zimmer ruhig wird, gönn dir eine Pause: Schau auf keinen Bildschirm und atme einfach ein paarmal tief ein und aus.'),
  ('de182c61-510f-445a-9f50-8ed2459f90cf', 'Aussprache von Wörtern 🗣️', 'Spricht dein Kind manche Wörter nur teilweise oder besonders lustig aus? Lach es nicht aus, sondern sprich ihm das Wort mit der richtigen Betonung vor, damit sich sein Gehirn die korrekte Aussprache einprägt.'),
  ('f4bf03e5-dc33-4bfa-a875-42962b014227', 'Freies Spielen 🧸', 'Du musst dein Kind nicht jede Minute beschäftigen. Langeweile ist für Kinder oft der Beginn von Kreativität. Lass es im Zimmer selbstständig etwas entdecken.'),
  ('3ead07a7-4417-4744-9277-6bedf5fa245b', 'Ein Moment, der die Zeit anhält 📸', 'Schau dir das unschuldige Gesicht deines Kindes an, wenn es schläft. Auch wenn es dich den ganzen Tag in den Wahnsinn getrieben hat, vermisst du es, sobald es eingeschlafen ist, oder? Genau das ist das Paradoxe am Muttersein.'),
  ('5f09ad8f-0fde-4f65-8032-dfe56e435a81', 'Die Gewohnheit, Wasser zu trinken 💧', 'Will dein Kind statt Wasser ständig süße Säfte? Überprüfe die Flüssigkeitszufuhr im Ernährungsplan. Motiviere es, indem du Wasser in bunten Bechern mit besonderen Trinkhalmen anbietest.'),
  ('e8fd5bc0-a904-4768-8c61-d9259b243761', 'Applaus-Team 👏', 'Klatscht dein Kind vor Freude für sich selbst, wenn ihm etwas gelungen ist? Sobald du diesen wunderbaren Moment siehst, veranstalte zu Hause einen kleinen Siegestanz und teile seine Freude!'),
  ('2a429f3f-0b1b-49c6-befd-28bf5cd2cf98', 'Wenn Mama müde ist 🛑', 'Du bist kein Roboter. Wenn du heute keine Kraft zum Kochen hast, bestell etwas zu essen. Eine perfekte Mutter zu sein bedeutet nicht, alles allein machen zu müssen.'),
  ('5c059ccd-12dd-4a31-9da6-6e33ef79b1be', 'Ein klares Nein 🛑', 'Geht dein Kind auf Abstand und sagt entschieden Nein, wenn es jemand küssen möchte? Respektiere seine körperlichen Grenzen. Es ist sehr wichtig, dass es sich gegen Berührungen ohne seine Zustimmung wehrt.'),
  ('41e28dbe-e3fb-4744-b4f1-9927a3802b24', 'Geräusche herausfiltern 🤫', 'Beim Einschlafen ist dein Baby besonders geräuschempfindlich. Schalte im Zimmer leises weißes Rauschen (White Noise) oder sanfte Musik ein, um Geräusche von draußen zu überdecken.'),
  ('745737c8-7329-40d3-90c9-336ff2e4a2ae', 'Gemeinsam in der Küche 🧑‍🍳', 'Möchte dein Kind dir in der Küche helfen? Lass es beim Eingießen von Mehl oder Wasser mitmachen. Auch wenn dabei alles schmutzig wird – seine Freude und Begeisterung fürs Lernen sind es wert.'),
  ('1938c0bd-ea98-478e-8da7-ef024a27ce71', 'Eine Liste ist kein Extra, sondern ein Muss 🛒', 'Der Schlafmangel schwächt dein Gedächtnis und im Supermarkt vergisst du ständig etwas? Streng deinen Kopf nicht unnötig an. Schreib einfach alles in die Einkaufsliste der App.'),
  ('30a1934e-958b-40a0-9b32-c4894a70a798', 'Einfach nur kuscheln 🫂', 'Heute braucht es weder Spiele noch Bücher. Drück dein Baby heute Abend einfach an deine Brust, atme seinen Duft ein und flüstere ihm im Dunkeln zu, wie wertvoll es ist.'),
  ('e00d8cce-8b3a-4ac6-ad35-5a22b01bd325', 'Baumeister in Aktion 🧱', 'Versucht dein Kind, große Legosteine zusammenzustecken und etwas daraus zu bauen? So entdeckt es räumliche Zusammenhänge und Geometrie. Halte diesen besonderen kleinen Konstruktionsversuch im Entwicklungstracker fest.'),
  ('1a4b3925-7885-40fb-a56f-488e3358cee1', '10 Minuten nur für dich 🛀', 'Im Zimmer ist es still geworden. Bitte deinen Partner oder deine Partnerin, zu Hause alles zu übernehmen. Gönn dir währenddessen eine warme Dusche und genieße es, ganz für dich zu sein.'),
  ('505c8d78-0b81-4cb5-96f5-e5571e1fc049', 'Die Autonomiephase mit 2 📱', 'Bist du es leid, dass dein Kind zu allem Nein sagt? Lies die Artikel im Blogbereich und erfahre, was hinter diesem Entwicklungssturm in seinem Gehirn steckt.'),
  ('5e96bc6a-ca0b-4e3c-9cde-441c31566ab3', 'Mission: verstecktes Gemüse 🥦', 'Wirft dein Kind Kräuter oder Brokkoli vom Teller? Entdecke bei den Babyrezepten farbenfrohe, selbst gebackene Gemüsemuffins und hake im Ernährungstracker ganz entspannt die Vitaminportion ab.'),
  ('ca5c9545-5eb9-432c-acea-7e6fe2c5ab98', 'Ruhe und Kaffee 🤫', 'Es schläft! Statt jetzt den Geschirrspüler auszuräumen, setz dich ins dunkle Zimmer. Genieße 15 Minuten Ruhe und entspann dich.'),
  ('cc9ba302-22d8-43e5-a70d-2bed916f8d33', 'Schau nach unten! 👣', 'Greift dein Baby schon nach seinen Zehen und erkundet sie oder läuft es sogar gern barfuß? Die Nerven unter den Füßen zu entdecken, ist für sein Gleichgewicht sehr wichtig.'),
  ('0bcb845e-25a8-4c8a-b05c-67b7a3788c4a', 'Überraschungswetter ⛅', 'Lass dich beim Spaziergang nicht vom Wetter täuschen, damit dein Baby nicht friert. Verlass dich nicht nur auf den Blick aus dem Fenster, sondern prüfe vorher die Windgeschwindigkeit und die gefühlte Temperatur draußen.'),
  ('1566736d-5f6a-420b-9aaa-9e37909efa16', 'Es entdeckt sein Ich 👑', '„Ich!“ und „Meins!“ sind gerade seine Lieblingswörter. Jetzt ist die egozentrische Phase besonders ausgeprägt. Begegne seiner Individualität mit Respekt – sie ist ein wichtiger Entwicklungsschritt.'),
  ('7aba0d06-67c9-4fba-811b-47eacf1ff2d7', 'Papa übernimmt 👨‍🍼', 'Du hast tagsüber schon genug geleistet. Überlass es am Abend dem Papa, euer Kind bettfertig zu machen und ihm den Schlafanzug anzuziehen, und schau einfach entspannt zu.'),
  ('2876fc5f-fac3-4af5-b718-9c2f0d9b5314', 'Zeit für neue Energie 🍲', 'Steckt dir die Müdigkeit in den Knochen? Belohne dich mit einem besonderen Salat, der in 10 Minuten fertig ist, lange satt hält und dir neue Energie schenkt.'),
  ('2b82cde7-2302-4ad2-96b7-ca1beedb8f4f', 'Schluss mit dem Zahnbürstenkampf 🪥', 'Macht dein Kind den Mund fest zu, sobald es die Zahnbürste sieht? Suche unter „Empfohlene Produkte“ nach musikalischen oder rotierenden Kinderzahnbürsten, die das Zähneputzen erleichtern und Hygiene zum Vergnügen machen.'),
  ('c3b0f127-530e-4b11-9687-7c0bcb24de5f', 'Nächtlicher Sturm 😭', 'Ist dein Kind mitten in der Nacht scheinbar grundlos weinend aufgewacht? Sind es Blähungen oder nur ein Nachtschreck? Nimm es ruhig in den Arm und gib ihm Geborgenheit, ohne deine Stimme zu erheben.'),
  ('79a825c4-e46e-4e7d-81f2-4387a7318ef2', 'Geheimnisse teilen 💬', 'Bist du völlig erschöpft? Dann schau in der Anacan Community vorbei. Lies die echten Geschichten Tausender Mütter und schöpfe Kraft aus dem Gefühl: Ich bin nicht allein.'),
  ('0048f15c-3ab2-4568-b3e6-cf763bd916d3', 'Gemüse verstecken 🥦', 'Sortiert dein Kind jedes Stück Gemüse aus der Suppe aus? Kämpfe nicht dagegen an. Püriere das Gemüse und verstecke es in Soßen oder Frikadellen – ein altbewährter Mama-Trick.'),
  ('4d0d3015-35d0-4444-b757-3789d14e8ec4', 'Reaktionen auf Bilder 📖', 'Berührt dein Kind Tiere oder andere Gegenstände im Buch und macht Geräusche, wenn es sie sieht? Seine visuelle Wahrnehmung ist erstaunlich. Sprich mit ihm über die Figuren im Buch.'),
  ('cfe51929-b2af-45a2-b23e-e670a8d3ebd8', 'Der Kampf ums Schlafengehen 🏃‍♂️', 'Erfindet dein Kind ständig neue Ausreden, um nicht ins Bett zu müssen? Stelle den Schlaf-Timer ein, bleib konsequent und schaffe mit Regengeräuschen aus den Weißen Geräuschen eine ruhige Atmosphäre im Zimmer.'),
  ('0727c4e7-7433-410a-9da5-27fff69d9877', 'Flüssigkeitszufuhr und Verstopfung 💩', 'Ist dein Kind ständig in Bewegung, trinkt aber wenig Wasser? Achte auf den Stuhlgang im Töpfchen oder in der Windel. Besteht Verstopfungsgefahr, trage es in der App ein und ergänze den Speiseplan mithilfe des Ernährungs-Trackers direkt um Haferflocken oder Birne.'),
  ('5730e69b-8e67-40bb-94c5-56cb9dd41a75', 'Auf der Suche nach neuen Freunden 👫', 'Versucht dein Kind im Park, mit Gleichaltrigen herumzulaufen und auf sie zuzugehen? Die soziale Entdeckungsreise hat offiziell begonnen! Bleib in sicherer Nähe und beobachte diese ersten Versuche voller Stolz.'),
  ('a11a0d3a-a9c4-402b-9b3c-bc6d874fc9a7', 'Melodie der Nacht 🛀', 'Nach einem ganzen Tag voller Bewegung seid ihr beide erschöpft. Ein warmes Bad und eine sanfte, ruhige Melodie im Hintergrund helfen seinem Nervensystem, vollständig zur Ruhe zu kommen.'),
  ('100fc6ed-66a7-4e9e-939c-15af0683652e', 'Wenn der Mittagsschlaf ausfällt 🥱', 'Ist dein Kind schon wieder nicht eingeschlafen? Kämpfe nicht dagegen an und erschöpfe damit weder dein Kind noch dich selbst. Auch ruhiges Spielen mit Spielzeug im Zimmer ist eine Form der Erholung für das Gehirn.'),
  ('127ac6bb-4f6e-424f-91fb-e2d406c68c2a', 'Raus aus den eigenen vier Wänden ☕', 'Die Routine zu Hause wird dir langsam zu viel. Sorge heute für etwas Abwechslung. Geh mit deinem Kind in ein ruhiges Café in der Nähe – so erlebt es eine neue Umgebung und du kannst deinen Kaffee genießen.'),
  ('1e376436-3f0d-4a14-a96b-e1c16c40c937', 'Geräuschempfindlicher Schlaf 🤫', 'Schreckt dein Kind gleich nach dem Einschlafen beim kleinsten Geräusch auf? Prüfe die Raumakustik und nutze weißes Rauschen, um Geräusche von draußen zu überdecken.'),
  ('e0d7037f-df25-46a9-8fd2-5b2b39c1432d', 'Auf Möbel klettern 🧗‍♂️', 'Versucht dein Kind, sich am Sofa oder Stuhl hochzuziehen und hinaufzuklettern? Seine Beinmuskeln erproben dabei unterschiedliche Höhen. Sorge für eine sichere Umgebung, aber halte deinen kleinen Kletterer nicht von diesen Versuchen ab.'),
  ('458c2efd-1859-4a36-bc6c-218987ce42a4', 'Ein Kunstwerk auf dem Teller 🥦', 'Dein Kind möchte sein Essen nicht essen? Manchmal liegt es nicht am Geschmack, sondern am Aussehen. Gestalte mit buntem Gemüse lustige Gesichter, um seinen Appetit anzuregen.'),
  ('6007d88c-cdbb-46d0-9b99-4e7bdd857418', 'Ein Schlaflied für die Nacht 🎶', 'Keine App und keine Aufnahme kann Mamas Schlaflied ersetzen. Nimm dein Kind heute Abend einfach in den Arm und singe ihm leise sein liebstes Schlaflied vor, das ihm Geborgenheit schenkt.'),
  ('ade78fe2-3290-467b-9d4f-4aa0e7d81802', 'Der erste Erfolg auf dem Töpfchen! 🚽', 'Möchte dein Kind selbst aufs Töpfchen gehen? Das ist einer der größten Erfolge mit 2.5 Jahren! Trage diesen Erfolg im Windel/Töpfchen-Tracker ein und lies in den Blogs, wie du den Übergang noch leichter gestalten kannst.'),
  ('6c9cc94d-8363-4a16-b062-eb3e2640d824', 'Gedächtnis im Streik 🛒', 'Hat der Schlafmangel dein Gedächtnis geschwächt, sodass du beim Einkaufen ständig etwas vergisst? Mach es deinem Kopf leichter: Schreib alles auf eine Liste, damit dein Partner es auf dem Heimweg besorgen kann.'),
  ('8f8c331b-379e-4898-a071-076982bfc0c2', 'Diplomatische Verhandlungen 🤝', 'Will dein Kind im Park sein Spielzeug nicht hergeben? Lies unbedingt im Bereich „Blogs“ nach, wie du ihm ab 2.5 Jahren statt des Teilens beibringen kannst, sich beim Spielen abzuwechseln.'),
  ('e1ad3771-efd0-4fef-8fce-2cfe9cc2174f', 'Nächtliches Aufwachen 🌌', 'Wacht dein Kind mitten in der Nacht weinend auf und lässt sich nicht beruhigen? Sieh dir die Übersicht im Schlaf-Timer an. Schau gleich im Bereich „Blogs“ nach, um den Unterschied zwischen Nachtschreck und Albtraum zu verstehen.'),
  ('d3fd3ce0-fc06-4bdf-8472-041feda78c86', 'Heftige Trotzanfälle 🛑', 'Reagiert dein Kind auf jedes Nein mit Geschrei? Sprich mit Anacan AI darüber, wie du diese unkontrollierbaren Gefühlsausbrüche ruhig begleitest und dein Kind gezielt ablenken kannst.'),
  ('de972116-bddf-48f9-bc08-9f55438a9ed7', 'Papas Märchenstunde 📚', 'Überlass das Einschlafritual heute Abend deinem Partner! Nutzt den Partner-Modus in der App: Er liest die Geschichte vor, während du in Ruhe deinen Tee genießt.'),
  ('fd7112b4-d166-4f5f-ab2b-5f43c5c75632', 'Erfahrungen austauschen 💬', 'Hat dich ein neues Verhalten deines Kindes verunsichert? Suche nicht im Internet nach beängstigenden Artikeln. Nutze lieber die Ratschläge erfahrener Mütter in der Anacan-Community.'),
  ('0b033378-5688-4baf-b5a5-b23c33fde967', 'Das Geheimnis von Eisen: Vitamin C 🍋', 'Ist dein Kind blass oder hat es wenig Appetit? Prüfe im Ernährungstracker die heutige Eisenaufnahme und serviere zu Fleisch einen Salat mit reichlich Zitrone, um die Eisenaufnahme zu verbessern.'),
  ('69b9bded-4194-4499-ad7b-42407cdd5970', 'Nur trockene Lebensmittel? 🍞', 'Lehnt dein Baby Pürees und flüssige Speisen ab und möchte nur Brot oder Kekse? Das kann an einer Vorliebe für bestimmte Konsistenzen liegen. Analysiere den Speiseplan mit dem Ernährungstracker und finde gesunde Alternativen in den Babyrezepten.'),
  ('a97ba33c-1ca8-42a6-b9a0-1eac5f5ba6a9', 'Hör auf deinen Körper 🩸', 'Plötzlicher Heißhunger auf Süßes und Gereiztheit? Schau im Perioden-Tracker in den Kalender. Wenn deine Periode bevorsteht, bereite dir mit den gesunden Rezepten für Frauen einen magnesiumreichen Snack aus Datteln und Nüssen zu.'),
  ('16180139-d7b3-4c7d-9723-1b1d28274883', 'Naturdetektiv 🔍', 'Stellt dein Kind zu Hause alles auf den Kopf? Schnappt euch eine Lupe und geht nach draußen! Findet bei den mama-freundlichen Orten einen grünen Park und entdeckt gemeinsam Insekten und Blätter. So kann dein Kind seine Energie in der Natur ausleben.'),
  ('1e0561d7-2e98-4811-8aaf-2ee6c5e76ef8', 'Ist die Abendroutine schwieriger geworden?🛀', 'Lass während eines warmen Bades im Hintergrund beruhigende Musik laufen. Die Harmonie von Wasser und Melodie bringt selbst besonders willensstarke Kinder zur Ruhe.'),
  ('39972a4c-ff8f-4f23-abf0-aefe71b44bb9', 'Chaos zu Hause 🌪️', 'Das ganze Zimmer liegt voller Spielzeug? Zehn fröhliche Minuten mit deinem Kind sind wichtiger als Aufräumen. Das Spielzeug ist morgen auch noch da – überfordere dich nicht.'),
  ('15d607dd-13ee-4b91-b920-e762edd4acd3', 'Die Suche nach vollkommener Stille 🛋️', 'Sobald dein Kind schläft, musst du nicht gleich losrennen und die Spülmaschine ausräumen! Leg dich aufs Sofa, schließe die Augen und genieße 15 Minuten lang diese seltene, vollkommene Stille zu Hause.'),
  ('6417fc2a-8680-4b6d-9b78-5b97074e6a4c', 'An die Dunkelheit gewöhnen 🌙', 'Schalte alle zusätzlichen Lichtquellen und Bildschirme im Zimmer aus, damit dein Kind schneller einschläft. Eine ruhige und dunkle Umgebung fördert die Ausschüttung des Schlafhormons Melatonin.'),
  ('986722e4-1562-4f18-a164-dd6f65efe855', 'Ich höre dich 🗣️', 'Hört dein Baby dir aufmerksam zu und versucht, ähnliche Sätze zu bilden? Es spricht mit dir! Antworte ihm mit einem herzlichen Lächeln und ermutige es zu diesem Austausch.'),
  ('b222d604-2c4a-4c8d-9eda-efff14884581', 'Die Suche nach der perfekten Mama 💖', 'Heute ist dir der Geduldsfaden gerissen und du bist laut geworden? Mach dir keine Vorwürfe. Wenn dein Kind eingeschlafen ist, kannst du dir im Stimmungstagebuch alles von der Seele schreiben und dich so entlasten.'),
  ('259a4698-04af-4cc3-93e9-91599ab8a275', 'Ist der Mittagsschlaf bald Geschichte? ⏱️', 'Dein Kind weigert sich hartnäckig, mittags zu schlafen, ist abends aber völlig übermüdet? Analysiere die Statistiken des Schlaftimers und probiere aus, den Mittagsschlaf durch eine ruhige Auszeit (Quiet Time) zu ersetzen.'),
  ('278f2f23-c655-4241-807c-401148d291e5', 'Mamas PMS-Krisen 🍫', 'Fehlt dir kurz vor deiner Periode die Energie? Bevor du zu Medikamenten greifst, kannst du unter „Gesunde Rezepte für Frauen“ einen Beerensmoothie mit natürlichem Zucker zubereiten, der dir sofort neue Kraft gibt und deinen Körper stärkt.'),
  ('af74ff56-7d79-46b1-8bf0-e27bd2c06fed', 'Ich schneide selbst! ✂️', 'Dein Kind möchte in der Küche selbst eine Banane oder Knete schneiden? Das ist ein großartiger Wunsch, der die Feinmotorik fördert! Sieh dir jetzt unter „Empfohlene Produkte“ sichere, stumpfe Kindermesser und Kinderscheren an.'),
  ('04970a72-c396-466c-9613-3a82e661e79f', 'Es weiß selbst nicht, warum es weint 😭', 'Es kommt zu einem heftigen Wutanfall, weil der Becher rot statt blau ist? Oft stecken eigentlich Müdigkeit oder eine emotionale Überforderung dahinter. Sprich mit Anacan AI darüber, wie du solche unkontrollierbaren Gefühlsausbrüche gelassen begleiten kannst.'),
  ('c150e539-1698-44fc-be7c-18e8beb9b566', 'Störende Geräusche im Zimmer 🌌', 'Wacht dein Kind bei völliger Stille oder schon beim leisesten Klopfen aus der Nachbarwohnung auf? Spiele unter „Weißes Rauschen“ ein Ventilatorgeräusch ab und entdecke, wie es störende Geräusche in der Schlafumgebung ausblendet.'),
  ('f0684802-cf6d-4a4b-96a5-44c5cabd2832', 'Gemeinsam das Zuhause putzen 🧹', 'Das Zuhause muss geputzt werden? Aktiviere den Partnermodus! Entdeckt gemeinsam, wie du, der Papa und euer Kleines – mit einem kleinen Tuch in der Hand – das Putzen in ein lustiges Familienspiel verwandeln könnt.'),
  ('20745776-36d1-4511-abf0-1fafb63ced1d', 'Spielen statt Bildschirmzeit 📱', 'Dein Kind möchte am späten Nachmittag einen Zeichentrickfilm sehen und weint? Erfahre von Anacan AI, wie du die Bildschirmzeit stressfrei begrenzen und seine Aufmerksamkeit sofort auf ein anderes Spiel lenken kannst.'),
  ('2eb3f64d-4f32-4bfb-81ca-c75ffc798fd6', 'Zeit für frische Luft 🌳', 'Dir fällt zu Hause die Decke auf den Kopf. Setz dein Baby in den Kinderwagen und geht an die frische Luft – selbst wenn es nur für 20 Minuten ist. Die Ruhe der Natur tut sowohl deinem Baby als auch deiner Psyche richtig gut.'),
  ('48fd17bd-f8c5-4be3-9778-ec599f5cc5b0', 'Schau nach unten! 👣', 'Liebt dein Baby es schon, barfuß zu laufen und mit den Füßen unterschiedliche Oberflächen zu erkunden? Die Stimulation der Nervenenden an den Fußsohlen ist für sein Gleichgewicht sehr wichtig.'),
  ('e607fc1e-dfa8-4735-b945-f39209fa5d8a', 'Die magische Welt der Märchen 🪄', 'Probiert heute Abend etwas völlig Neues aus: die Geschichte einer kleinen Wolke, die den Himmel erkundet. Passe deine Stimme dem Rhythmus des Märchens an.'),
  ('4434b892-1b9a-48ea-bd05-6295b7705bc1', 'Ruhe in der Abendroutine 🌬️', 'Dein Baby war den ganzen Tag in Bewegung und kann jetzt nicht zur Ruhe kommen? Aktiviere den Einschlaftimer, wähle bei den Weißen Geräuschen Meeresrauschen und verwandle das Zimmer in eine ruhige Schlafhöhle, in der es seine Energie herunterfahren kann.'),
  ('a8561422-a7d3-4164-876d-1471ce35f23d', 'Papas Küchentag 👨‍🍳', 'Aktiviere den Partner-Modus. Heute ist Papa dafür zuständig, das Mittagessen zuzubereiten und dein Baby zu füttern! Nutze diese Zeit für dich, lies ein Buch oder ruh dich aus.'),
  ('f2202a7a-5edc-4209-b790-4083df0975d2', 'Krabbeln mit Ziel 🐢', 'Kann dein Baby schon laufen, krabbelt aber manchmal zum Spaß schnell vor dir davon? Räume gefährliche Hindernisse im Zimmer weg und mach bei diesem Fangspiel mit.'),
  ('9f77c4af-512a-49b9-8cbf-0c7c57609122', 'Vitamin D für starke Knochen ☀️', 'Vitamin D ist für die Aufnahme von Calcium unerlässlich! Überprüfe mit dem Ernährungstracker den heutigen Speiseplan und sieh dir unter „Empfohlene Produkte“ die von Ärztinnen und Ärzten empfohlenen Tropfen an.'),
  ('a85116cf-7f79-486c-8e28-8b90c93cfb63', 'Stress unter Zeitdruck 🛑', 'Ihr müsst aus dem Haus, aber dein Baby macht alles langsam und lässt sich nicht zur Eile bewegen? In diesem Alter hat es noch kein Zeitgefühl! Statt es anzutreiben, kannst du von unserem Anacan AI-Experten erfahren, wie du Übergänge erleichterst.'),
  ('02944013-1945-43f5-a622-bb7657b42970', 'Gemüse clever verstecken 🥦', 'Wirft dein Baby Kräuter oder Brokkoli vom Teller? Entdecke bei den Babyrezepten einen bunten, selbst gebackenen Gemüsemuffin und erreiche damit ganz einfach dein Vitaminziel im Ernährungstracker.'),
  ('45019ac4-08ed-4d8b-8186-060ceb70601a', 'Ihr seid ein großartiges Team 🌟', 'Jede neue Fähigkeit, die dein Baby täglich lernt, und jeder selbstbewusste Schritt sind euer gemeinsamer Verdienst. Öffne das Stimmungstagebuch und schenkt euch heute als Team einen großen Applaus!'),
  ('5613e3d7-d67b-4e9a-b92f-7ce15054b42e', 'Wachstumsschub bei Größe und Gewicht! 📏', 'Ist dir beim Anziehen aufgefallen, dass die Oberteile enger sitzen oder die Schuhe drücken? Trage die aktuelle Größe und die Maße in den Gewichtstracker ein und beobachte stolz, wie die Wachstumskurve ansteigt.'),
  ('3a871deb-8d4f-4409-84bd-a7fdcb6e8f4e', 'Märchenstunde mit Papa 📚', 'Heute Abend übernimmt dein Partner die Einschlafbegleitung. Lass ihn die Geschichte vorlesen und genieße die kleine Auszeit, die dir dadurch geschenkt wird.'),
  ('751db3a1-bc4d-4599-b35d-5aadaed3cfca', 'Die vielen „Warum?“-Fragen 🤔', 'Dein Kind möchte die Welt verstehen. In den Blogbeiträgen erfährst du, wie du geduldig auf seine endlosen Fragen antworten kannst. Deine Geduld fördert seine Entwicklung.'),
  ('ce6fd7ba-57bf-4c85-bfa6-c9b4b3713d0c', 'Fällt euch zu Hause die Decke auf den Kopf? 🌳', 'Fliegt zu Hause mal wieder alles durch die Gegend? Finde bei den mamafreundlichen Orten einen Park in deiner Nähe. Frische Luft ist die beste Medizin – für dein Kind und für dich.'),
  ('034073b2-a550-46ff-9473-8411c49fc4ec', 'Eisen und Kraft 🥩', 'Wirkt dein Kind blass? Überprüfe die Eisenaufnahme im Ernährungstracker. Serviere zum Fleisch einen Salat mit Zitronensaft, um die Eisenaufnahme zu verbessern.'),
  ('3e853511-fee0-4626-9f71-c751f4b255ca', 'Der Kampf mit der Zahnbürste 🪥', 'Läuft dein Kind weg, sobald es die Zahnbürste sieht? Sieh dir bei den empfohlenen Produkten Zahnbürsten mit Musik an. Mach aus der Zahnpflege keine Pflicht, sondern ein Spiel.'),
  ('956585f5-6347-4c88-b6a3-3638bd223889', 'Zeit für deinen Kaffee ☕', 'Hast du es satt, immer nur zu Hause zu sitzen? Entdecke unter „Mama-freundliche Orte“ kinderfreundliche Cafés, in denen sich viele Mütter treffen, und schaffe dir so neue Gelegenheiten, Kontakte zu knüpfen.'),
  ('96e63d94-22cd-4a99-8350-f721e6ade562', 'Die Kunst des Wartens 🧸', 'Dein Kind möchte im Park nicht warten, bis ein anderes Kind von der Rutsche herunterkommt? Lies im Bereich „Blogs“ unbedingt nach, wie du ihm ab 2.5 Jahren Geduld und das Abwechseln beim Spielen näherbringen kannst.'),
  ('1cf87075-900c-4f1c-a89d-b12b8314ac9b', 'Eisenspeicher im Blick 🥩', 'Ist dein Kind blass oder hat es wenig Appetit? Überprüfe in der Ernährungskontrolle die heutige Eisenzufuhr und serviere zum Fleisch einen Salat mit reichlich Zitronensaft, um die Eisenaufnahme zu verbessern.'),
  ('9c0be1cd-f5f7-43c2-bf11-199a917727ea', 'Massage vom Papa 💆‍♀️', 'Ist dein Rücken vom ständigen Hinterherlaufen den ganzen Tag verspannt? Teile deinem Partner über die Partnerfunktion mit, dass es heute Abend nach dem Zubettbringen eures Kindes Zeit für eine kurze Schultermassage für dich ist.'),
  ('fcd8e598-c584-4111-a575-0192c20a2ba3', 'Mach das Trinken zum Spiel 💧', 'Dein Kind tobt viel, trinkt aber wenig Wasser? Dadurch steigt das Verstopfungsrisiko. Trage den Stuhlgang in der App ein, ergänze den Speiseplan über die Ernährungskontrolle direkt um Haferflocken und bestelle unter „Empfohlene Produkte“ eine farbenfrohe Kindertrinkflasche.'),
  ('819da396-26ce-4c11-baf2-c21f3a1ad406', 'Wählerischer Appetit 🍝', 'Dein Kind möchte nur Nudeln? Überprüfe mit der Ernährungskontrolle die wöchentliche Ausgewogenheit. Setze dich nicht wegen eines einzigen Tages unter Druck.'),
  ('f0c36b67-8799-4202-8ab4-a072283a2c59', 'Tränen vor Erschöpfung 💧', 'Ist dir auch zum Weinen zumute? Das ist völlig normal. Schreibe deine Gefühle in dein Stimmungstagebuch und lass die Schuldgefühle los.'),
  ('f35164ca-a4af-42c5-8f5c-d2b4e2de79f4', 'Erkennt dein Kind Zahlen? 🔢', 'Versucht dein Kind, beim Treppensteigen oder Aufräumen der Spielsachen Dinge zu zählen? Halte diese ersten Funken mathematischer Entwicklung gleich als Video mit Ton im Babyalbum fest und mache sie zu einer Erinnerung fürs Leben.'),
  ('d32651ed-78b7-4090-bd14-46fc6e60d9a7', 'Bildschirmkrisen 📱', 'Bricht die Welt zusammen, sobald du das Handy wegnimmst? Frag Anacan AI nach psychologischen Tipps, die wirklich helfen, Bildschirmzeiten stressfrei zu begrenzen.'),
  ('49972eb0-ce9d-4cba-ad0b-3cc84b80e743', 'Nachtschreck 🤖', 'Dein Kind wacht mitten in der Nacht schreiend auf und erkennt dich nicht? Im Bereich „Blogs“ erfährst du sofort, was in diesem Fall zu tun ist und wie du einen Nachtschreck von einem Albtraum unterscheidest.'),
  ('4efefe1c-c867-4006-9142-0718a80c34db', 'Auch du hast Gesellschaft ☕', 'Den ganzen Tag nur mit dem Kind zu sprechen, kann anstrengend sein. Finde unter „Mütterfreundliche Orte“ kinderfreundliche Cafés, trink einen Kaffee und knüpfe Kontakte zu anderen Müttern.'),
  ('a185d77d-1385-43cb-bec6-87f42c458382', 'Morgendliche Krisen 🛑', 'Dein Kind weint bei jedem Nein? Sprich mit Anacan AI darüber, wie du Gefühlsausbrüche ruhig begleiten und dein Kind geschickt ablenken kannst.'),
  ('1d63f653-1008-4746-a730-0e985e6ca79c', 'Schmutzig werden erlaubt 🏖️', 'Dein Kind möchte mit Matsch spielen? Lass es ruhig schmutzig werden! Unter „Empfohlene Produkte“ findest du die besten Materialien zur Förderung der sensorischen Entwicklung.'),
  ('ab5b74cd-5dbb-4df0-aad8-f7ce58bb43e4', 'Wachstumsschub 📏', 'Die Oberteile sind zu kurz geworden? Dein Kind wächst! Trag die aktuellen Maße in den Gewichtstracker ein und beobachte stolz, wie die Wachstumskurve ansteigt.'),
  ('cd4b46fb-6caf-421b-9a9e-22b85cfd2d73', 'Warmer Tee und Ruhe 🍵', 'Der Timer ist abgelaufen, dein Kind schläft. Vergiss den Haushalt! Bereite dir nach unseren gesunden Rezepten einen Melissentee zu und genieße einfach die Ruhe.'),
  ('3e08f834-ae99-412b-94f4-fcb284f337ca', 'Schlafrhythmus analysieren ⏱️', 'Dauert das Einschlafen am Abend sehr lange? Sieh dir die Grafik des Schlaftimers an. Vielleicht ist es an der Zeit, den Mittagsschlaf deutlich zu verkürzen.'),
  ('6c779bea-dc2a-41ad-8ebb-96d5620eee3b', 'Kalzium-Schutzschild 🦴', 'Dein Kind trinkt keine Milch? Kalzium ist für die Knochen unverzichtbar. Mit dem Ernährungstracker kannst du erfassen, wie viel Joghurt oder Brokkoli es isst, und fehlendes Kalzium ergänzen.'),
  ('9550715f-5ff1-4a49-8dae-33944b52477f', 'Lange Sätze 🗣️', 'Erzählt dein Kind schon lustige Geschichten? Sein Wortschatz wächst rasant! Halte diesen kostbaren Moment als Spracherinnerung im Babyalbum fest.'),
  ('2d4c6405-93aa-4a22-9aae-af7a8dcd04fc', 'Frühes Aufwachen 🌅', 'Dein Kind wacht noch vor Sonnenaufgang voller Energie auf? Du dagegen bist völlig erschöpft. Frag Anacan AI, wie du diesen Rhythmus anpassen kannst. Der Schlafmangel dauert nicht ewig.'),
  ('49091c89-e2f8-4ecf-a7b6-b705116efa46', 'Papas Geschichte 📚', 'Aktiviere den Partnermodus. Heute Abend ist Papa der Held der Gutenachtgeschichte! Lass ihn vorlesen, während du dir einen Kaffee einschenkst und außerhalb des Zimmers die Ruhe genießt.'),
  ('865b1ef2-1722-47cc-bf4d-3108a098404b', 'Das leidige Teilen 🧸', 'Dein Kind will sein Spielzeug mit niemandem teilen? Das ist kein Egoismus, sondern eine normale Entwicklungsphase. In unseren Blogbeiträgen erfährst du, wie du ihm beibringen kannst, sich beim Spielen abzuwechseln.'),
  ('983d85d9-b1dc-40ec-a012-9c7aba93c4d9', 'Tränen sind normal 💧', 'Du bist erschöpft und möchtest einfach nur weinen? Eine starke Mutter zu sein bedeutet manchmal auch, sich die eigene Verletzlichkeit einzugestehen.'),
  ('ee623f8b-a47a-4ef6-96d3-5754f3e3cd43', 'Energietief ⚡', 'Du könntest mittags im Stehen einschlafen? Greif nicht zu Koffein, sondern zu Eiweiß! Tanke neue Energie mit einem Erdnussbutter-Smoothie aus unseren gesunden Rezepten.'),
  ('fe3bdaaa-fafd-445d-b4e7-84a8026c6168', 'Plötzliche Wutanfälle 🛑', 'Wirft sich dein Kind scheinbar grundlos auf den Boden? Sprich mit Anacan AI darüber, wie du diese Wutanfälle gelassen meisterst und die Blicke anderer ignorierst.'),
  ('d7ebaa5c-a836-4c14-8fc7-8ddab08162c6', 'Gemüse-Tarnung 🥦', 'Schiebt dein Kind alles Grüne auf dem Teller beiseite? Jetzt erreicht wählerisches Essverhalten seinen Höhepunkt. Im Bereich „Ernährungsplan“ findest du clevere Rezepte, bei denen du Gemüse pürieren und in Frikadellen verstecken kannst.'),
  ('2461cdb3-c847-4528-8c72-5b1258b6ff1d', 'Grenzen auf dem Spielplatz 🧸', 'Will dein Kind im Sandkasten niemandem seinen Eimer geben? Das ist kein Egoismus, sondern ein Zeichen dafür, dass es ein Verständnis von Eigentum entwickelt. Bring ihm das Teilen nicht mit Zwang bei, sondern durch Abwechseln: Jetzt ist das andere Kind an der Reihe.'),
  ('b0edd680-c98e-4626-b7fa-18383befe832', 'Die unsichtbaren Gäste sind da ☕', 'Spricht dein Kind allein im Zimmer mit unsichtbaren Freunden und schenkt ihnen Tee ein? Seine Fantasie ist gerade auf ihrem Höhepunkt! Beobachte diesen großartigen kleinen Drehbuchautor mit Stolz aus der Ferne.'),
  ('dea0086a-894a-4d43-a110-0948ee956740', 'Dein Kind führt Regie bei der Magie 🪄', 'Hat dein Kind genug von klassischen Märchen? Lass es diesmal in den interaktiven Märchen selbst die Hauptfigur auswählen. Ein fliegender Hund oder ein sprechender Baum – lasst der Fantasie freien Lauf.'),
  ('0a08658d-8354-4bb5-9ba8-b4c528e517fc', 'Dein Kind schreibt seine eigenen Regeln 🛑', 'Bei allem heißt es: „Ich allein!“ Die Schuhe sind vertauscht, das Oberteil sitzt falsch herum, doch dein Kind bleibt hartnäckig. Das macht nichts – sein Wunsch nach Selbstständigkeit ist wichtiger als ein perfektes Aussehen. Lass es ruhig selbst machen.'),
  ('411275c3-b6bc-4218-a886-bbf3ee4ba697', 'Wassertherapie 🛀', 'Nach einem ganzen Tag voller Herumtoben liegen bei euch beiden die Nerven blank. Ein warmes Bad dient nicht nur der Hygiene – nutze auch die beinahe magische Kraft des Wassers, Anspannung zu lösen.'),
  ('d5a4b327-9717-431f-8c67-ec44df34af85', 'Gefühl der Erschöpfung 🔋', 'Möchtest du wegen jeder Kleinigkeit losschreien? Das ist Burnout. Schau gleich in der Anacan-Community vorbei, lies die ehrlichen Erfahrungen von Müttern, die gerade dasselbe durchmachen, und hol dir Unterstützung.'),
  ('38c563a6-395b-403a-8ffd-c4d46a16b207', 'Küchenchaos 🧑‍🍳', 'Veranstaltet dein Kind mit den Töpfen ein Konzert, während du kochst? Es möchte ebenfalls Teil des Teams sein. Gib ihm ein kleines Stück Teig, damit es mitkochen kann.'),
  ('1e03f3e4-2305-4ae5-883c-39581f248697', 'Entdeckt die Zahlen 🔢', 'Beim Treppensteigen oder Aufstellen seiner Spielsachen versucht dein Kind, eins, zwei, drei zu zählen. Unterstütze diese mathematische Phase seiner kognitiven Entwicklung, indem ihr gemeinsam zählt.'),
  ('2e1f0716-93b5-4be3-9000-fdb28349534d', 'Papas Geheimwaffe 🤡', 'Wenn deine Tricks nicht mehr wirken, retten Papas seltsame Geräusche und lustige Grimassen sofort die Situation. Bei abendlichen Krisen kannst du den Ball direkt an ihn weiterspielen.'),
  ('b24ba903-09d2-4243-a80b-995524b45caf', 'Ärger mit dem Mittagsschlaf 🥱', 'Dein Kind will partout nicht ins Bett? Mit 2.5 Jahren beginnen manche Kinder, den Mittagsschlaf abzulehnen. Erzwinge den Schlaf nicht, sondern ersetze ihn durch eine 30-minütige ruhige Bilderbuchzeit.'),
  ('54501d8f-f370-4895-a96c-448bca275b4e', 'Schau nach unten – was gibt es da? 👣', 'Dein Kind genießt es besonders, barfuß zu laufen und verschiedene Oberflächen wie Sand, Teppich und Stein zu spüren. Die Stimulation der Nerven in den Fußsohlen ist für seine neurologische Entwicklung besonders wertvoll.'),
  ('7212233e-c5da-4c83-bd8d-a74e469e3fcc', 'Dimme das Licht 🌙', 'Schalte 1 Stunde vor dem Schlafengehen grelles Licht und alle Bildschirme mit blauem Licht aus. Schaffe zu Hause eine ruhige, gedämpfte Abendstimmung, damit die Melatoninproduktion angeregt wird.'),
  ('efc5b454-d92c-49c6-a2a5-9e995c6d9a84', 'Unsicher wegen des Arztbesuchs? 🤖', 'Du bist dir unsicher, welche Impfungen oder Vitamine mit 2.5 Jahren nötig sind? Verliere dich nicht in beängstigenden Internetforen, sondern erhalte sofort eine verlässliche Antwort von Anacan AI.'),
  ('235bf352-67d4-4056-94d7-5429271d340f', 'Kleine Wortgefechte 🗣️', 'Nein, ich bin schon groß, ich weiß es selbst! Dein Kind versucht nun, dir mit eigenen Argumenten zu widersprechen. Antworte auf Augenhöhe und bestimmt, ohne deine Stimme zu erheben.'),
  ('ae99921f-bf29-40ac-a251-a633a4741d07', 'Zeit für dich ist kein Grund für Schuldgefühle 💆‍♀️', 'Das Gefühl, zu wenig Zeit mit dem Kind zu verbringen, kennen viele Mütter. Doch vergiss nicht: Eine völlig erschöpfte Mutter hat keine Kraft mehr, ihrem Kind etwas zu geben. Gönne dir mittags eine 20-minütige Atempause.'),
  ('59dde031-61d1-4132-874a-bbebe2bc223a', 'Die Tragödie des zerbrochenen Kekses 🍪', 'Die Welt geht unter, nur weil der Keks in zwei Teile zerbrochen ist? Willkommen bei den klassischen Krisen mit 2.5 Jahren. Suche nicht nach Logik – zeig deinem Kind einfach, dass du seinen großen Kummer verstehst.'),
  ('5e26eff6-747b-42a4-909a-13e90be41e9d', 'Ungefilterte Realität 🛑', 'Du siehst dir in den sozialen Medien Videos von ruhigen, sauberen Kindern an und machst dir Vorwürfe? Das sind nur 15-sekündige Illusionen. Deine chaotische, laute Realität ist die schönste.')
) AS v(id, t, b)
WHERE x.id = v.id;
